const LIBRARY=[{"id": 0, "title": "蝉", "author": "虞世南", "body": "垂緌饮清露，流响出疏桐。\n居高声自远，非是藉秋风。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1, "title": "野望", "author": "王绩", "body": "东皋薄暮望，徙倚欲何依。\n树树皆秋色，山山唯落晖。\n牧人驱犊返，猎马带禽归。\n相顾无相识，长歌怀采薇。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2, "title": "秋夜喜遇王处士", "author": "王绩", "body": "北场芸藿罢，东皋刈黍归。\n相逢秋月满，更值夜萤飞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3, "title": "吾富有钱时", "author": "王梵志", "body": "吾富有钱时，妇儿看我好。\n吾若脱衣裳，与吾叠袍袄。\n吾出经求去，送吾即上道。\n将钱入舍来，见吾满面笑。\n绕吾白鸽旋，恰似鹦鹉鸟。\n邂逅暂时贫，看吾即貌哨。\n人有七贫时，七富还相报。\n图财不顾人，且看来时道。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 4, "title": "诗（选二首）", "author": "王梵志", "body": "我有一方便，价值百匹练。\n相打长取弱，至死不入县。\n他人骑大马，我独跨驴子。\n回顾担柴汉，心下较些子。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 5, "title": "杳杳寒山道", "author": "寒山", "body": "杳杳寒山道，落落冷涧滨。\n啾啾常有鸟，寂寂更无人。\n淅淅风吹面，纷纷雪积身。\n朝朝不见日，岁岁不知春。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 6, "title": "入朝洛堤步月", "author": "上官仪", "body": "脉脉广川流，驱马历长洲。\n鹊飞山月曙，蝉噪野风秋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 7, "title": "长安古意", "author": "卢照邻", "body": "长安大道连狭斜，青牛白马七香车。\n玉辇纵横过主第，金鞭络绎向侯家。\n龙衔宝盖承朝日，凤吐流苏带晚霞。\n百尺游丝争绕树，一群娇鸟共啼花。\n游蜂戏蝶千门侧，碧树银台万种色。\n复道交窗作合欢，双阙连甍垂凤翼。\n梁家画阁中天起，汉帝金茎云外直。\n楼前相望不相知，陌上相逢讵相识？\n借问吹箫向紫烟，曾经学舞度芳年。\n得成比目何辞死，愿作鸳鸯不羡仙。\n比目鸳鸯真可羡，双去双来君不见？\n生憎帐额绣孤鸾，好取门帘帖双燕。\n双燕双飞绕画梁，罗帷翠被郁金香。\n片片行云着蝉翼，纤纤初月上鸦黄。\n鸦黄粉白车中出，含娇含态情非一。\n妖童宝马铁连钱，娼妇盘龙金屈膝。\n御史府中乌夜啼，廷尉门前雀欲栖。\n隐隐朱城临玉道，遥遥翠幰没金堤。\n挟弹飞鹰杜陵北，探丸借客渭桥西。\n俱邀侠客芙蓉剑，共宿娼家桃李蹊。\n娼家日暮紫罗裙，清歌一啭口氛氲。\n北堂夜夜人如月，南陌朝朝骑似云。\n南陌北堂连北里，五剧三条控三市。\n弱柳青槐拂地垂，佳气红尘暗天起。\n汉代金吾千骑来，翡翠屠苏鹦鹉杯。\n罗襦宝带为君解，燕歌赵舞为君开。\n别有豪华称将相，转日回天不相让。\n意气由来排灌夫，专权判不容萧相。\n专权意气本豪雄，青虬紫燕坐春风。\n自言歌舞长千载，自谓骄奢凌五公。\n节物风光不相待，桑田碧海须臾改。\n昔时金阶白玉堂，即今惟见青松在。\n寂寂寥寥扬子居，年年岁岁一床书。\n独有南山桂花发，飞来飞去袭人裾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 8, "title": "咏蝉", "author": "骆宾王", "body": "西陆[1]蝉声唱，南冠[2]客思深。\n不堪玄鬓[3]影，来对白头吟。\n露重飞难进，风多响易沉。\n无人信高洁，谁为表予心？\n〔注〕[1]西陆：指秋天。《隋书·天文志》:“日循黄道东行……行西陆谓之秋。” [2]南冠：指囚徒。《左传·成公九年》:“晋侯观于军府，见钟仪，问之曰：‘南冠而絷者谁也？’有司对曰：‘郑人所献楚囚也。'” [3]玄鬓：指蝉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 9, "title": "于易水送人一绝", "author": "骆宾王", "body": "此地别燕丹，壮士发冲冠。\n昔时人已没，今日水犹寒。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 10, "title": "和晋陵陆丞早春游望", "author": "杜审言", "body": "独有宦游人，偏惊物候新。\n云霞出海曙，梅柳渡江春。\n淑气催黄鸟，晴光转绿苹。\n忽闻歌古调，归思欲沾襟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 11, "title": "渡湘江", "author": "杜审言", "body": "迟日园林悲昔游，今春花鸟作边愁。\n独怜京国人南窜，不似湘江水北流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 12, "title": "正月十五日夜", "author": "苏味道", "body": "火树银花合，星桥铁锁开。\n暗尘随马去，明月逐人来。\n游妓皆秾李[1]，行歌尽落梅[2]。\n金吾[3]不禁夜，玉漏[4]莫相催。\n〔注〕[1]秾李：《诗经·何彼秾矣》:“何彼秾矣，花如桃李。”用桃花和李花的秾艳，形容妇女容颜服饰之美。 [2]落梅：古曲调名。汉乐府《横吹曲》有《梅花落》。 [3]金吾：京城里的禁卫军。 [4]玉漏：指计时的漏壶，玉是形容质料的精致华美。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 13, "title": "咏风", "author": "王勃", "body": "肃肃凉风生，加我林壑清。\n驱烟寻涧户，卷雾出山楹。\n去来固无迹，动息如有情。\n日落山水静，为君起松声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 14, "title": "滕王阁诗", "author": "王勃", "body": "滕王高阁临江渚，佩玉鸣鸾罢歌舞。\n画栋朝飞南浦云，珠帘暮卷西山雨。\n闲云潭影日悠悠，物换星移几度秋。\n阁中帝子今何在？槛外长江空自流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 15, "title": "别薛华[1]", "author": "王勃", "body": "送送多穷路，遑遑独问津。\n悲凉千里道，凄断百年身。\n心事同漂泊，生涯共苦辛。\n无论去与住，俱是梦中人。\n〔注〕[1]诗题一作《秋日别薛昇华》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 16, "title": "送杜少府之任蜀川", "author": "王勃", "body": "城阙辅三秦[1]，风烟望五津。\n与君离别意，同是宦游人。\n海内存知己，天涯若比邻。\n无为在歧路，儿女共沾巾。\n〔注〕[1]三秦：泛指当时长安附近的关中之地。古为秦国，秦亡后，项羽分其地为雍、塞、翟三国，故称“三秦”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 17, "title": "江亭夜月送别二首（其二）", "author": "王勃", "body": "乱烟笼碧砌，飞月向南端。\n寂寞离亭掩，江山此夜寒。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 18, "title": "山中", "author": "王勃", "body": "长江悲已滞，万里念将归。\n况属高风晚，山山黄叶飞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 19, "title": "从军行", "author": "杨炯", "body": "烽火照西京[1]，心中自不平。\n牙璋辞凤阙，铁骑绕龙城[2]。\n雪暗凋旗画，风多杂鼓声。\n宁为百夫长[3]，胜作一书生。\n〔注〕[1]西京：长安。 [2]龙城：匈奴名城。这里泛指敌方要塞。 [3]百夫长：泛指低级军官。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 20, "title": "代悲白头翁", "author": "刘希夷", "body": "洛阳城东桃李花，飞来飞去落谁家？\n洛阳女儿惜颜色，行逢落花长叹息。\n今年落花颜色改，明年花开复谁在？\n已见松柏摧为薪，更闻桑田变成海。\n古人无复洛城东，今人还对落花风。\n年年岁岁花相似，岁岁年年人不同。\n寄言全盛红颜子，应怜半死白头翁。\n此翁白头真可怜，伊昔红颜美少年。\n公子王孙芳树下，清歌妙舞落花前。\n光禄池台文锦绣，将军楼阁画神仙。\n一朝卧病无相识，三春行乐在谁边？\n宛转蛾眉能几时？须臾鹤发乱如丝。\n但看古来歌舞地，惟有黄昏鸟雀悲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 21, "title": "送别杜审言", "author": "宋之问", "body": "卧病人事绝，嗟君万里行。\n河桥不相送，江树远含情。\n别路追孙楚，维舟吊屈平。\n可惜龙泉剑，流落在丰城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 22, "title": "题大庾岭北驿", "author": "宋之问", "body": "阳月南飞雁，传闻至此回。\n我行殊未已，何日复归来？\n江静潮初落，林昏瘴不开。\n明朝望乡处，应见陇头梅。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 23, "title": "早发始兴江口至虚氏村作", "author": "宋之问", "body": "候晓逾闽嶂，乘春望越台。\n宿云鹏际落，残月蚌中开。\n薜荔摇青气，桄榔翳碧苔。\n桂香多露裛，石响细泉回。\n抱叶玄猿啸，衔花翡翠来。\n南中虽可悦，北思日悠哉。\n鬒发俄成素，丹心已作灰。\n何当首归路，行剪故园莱。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 24, "title": "灵隐寺", "author": "宋之问", "body": "鹫岭郁岧峣，龙宫锁寂寥。\n楼观沧海日，门对浙江潮。\n桂子月中落，天香云外飘。\n扪萝登塔远，刳木取泉遥。\n霜薄花更发，冰轻叶未凋。\n夙龄尚遐异，搜对涤烦嚣。\n待入天台路，看余度石桥。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 25, "title": "渡汉江", "author": "宋之问", "body": "岭外音书断，经冬复历春。\n近乡情更怯，不敢问来人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 26, "title": "杂诗三首（其三）", "author": "沈佺期", "body": "闻道黄龙戍[1]，频年不解兵。\n可怜闺里月，长在汉家营[2]。\n少妇今春意，良人昨夜情。\n谁能将旗鼓，一为取龙城[3]。\n〔注〕[1]黄龙戍：唐时东北要塞，在今辽宁开原西北。 [2]“汉家”的“汉”既指汉族，也指汉朝。这里是以汉代唐，避免直指。 [3]龙城：匈奴名城，秦汉时匈奴祭祀的地方。这里借指敌方要地。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 27, "title": "夜宿七盘岭", "author": "沈佺期", "body": "独游千里外，高卧七盘西。\n山月临窗近，天河入户低。\n芳春平仲绿，清夜子规啼。\n浮客空留听，褒城闻曙鸡。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 28, "title": "独不见", "author": "沈佺期", "body": "卢家少妇郁金堂[1]，海燕双栖玳瑁梁。\n九月寒砧催木叶，十年征戍忆辽阳[2]。\n白狼河北音书断，丹凤城[3]南秋夜长。\n谁谓含愁独不见，更教明月照流黄！\n〔注〕[1]卢家少妇郁金堂：萧衍《河中之水歌》曰：“河中之水向东流，洛阳女儿名莫愁……十五嫁为卢家妇，十六生儿字阿侯。卢家兰室桂为梁，中有郁金苏含香。” [2]辽阳：在今辽宁省境，为当时边防要地；下句的白狼河（今名大凌河），即在这里。 [3]丹凤城：指长安。传说秦穆公的女儿弄玉善吹箫，引来凤凰集于城上，后来称京城为丹凤城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 29, "title": "古剑篇", "author": "郭震", "body": "君不见昆吾[1]铁冶飞炎烟，红光紫气俱赫然。\n良工锻炼凡几年，铸得宝剑名龙泉。\n龙泉颜色如霜雪，良工咨嗟叹奇绝。\n琉璃玉匣[2]吐莲花，错镂金环映明月。\n正逢天下无风尘[3]，幸得周防君子身。\n精光黯黯青蛇色，文章[4]片片绿龟鳞。\n非直结交游侠子，亦曾亲近英雄人。\n何言中路遭弃捐，零落飘沦古狱边。\n虽复沉埋无所用，犹能夜夜气冲天。\n〔注〕[1]昆吾：传说中的山名。相传山有积石，冶炼成铁，铸出宝剑光如水精，削玉如泥。[2]琉璃玉匣：晋葛洪《西京杂记》载，汉高祖斩白蛇，剑以五色琉璃为匣。 [3]风尘：指战争。[4]文章：指剑上花纹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 30, "title": "罢相", "author": "李適之", "body": "避贤初罢相，乐圣且衔杯。\n为问门前客，今朝几个来？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 31, "title": "感遇三十八首（其二）", "author": "陈子昂", "body": "兰若生春夏，芊蔚何青青！\n幽独空林色，朱蕤冒紫茎。\n迟迟白日晚，嫋嫋秋风生。\n岁华尽摇落，芳意竟何成！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 32, "title": "感遇三十八首（其四）", "author": "陈子昂", "body": "乐羊为魏将，食子殉军功。\n骨肉且相薄，他人安得忠？\n吾闻中山相[1]，乃属放麑[2]翁。\n孤兽犹不忍，况以奉君终。\n〔注〕[1]相：当时诸侯王子都有太傅，称为相。 [2]麑（ní）：幼鹿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 33, "title": "感遇三十八首（其二十三）", "author": "陈子昂", "body": "翡翠巢南海，雄雌珠树[1]林。\n何知美人意，骄爱比黄金？\n杀身炎洲里，委羽玉堂阴，\n旖旎[2]光首饰，葳蕤[3]烂锦衾。\n岂不在遐远？虞罗忽见寻。\n多材信为累，叹息此珍禽。\n〔注〕[1]珠树：即三珠树，古代传说中的树名。《山海经·海外南经》:“三珠树在厌火北，生赤水上。其为树如柏，叶皆为珠。” [2]旖旎（yǐnǐ）：本为旌旗随风飘扬貌，引申为柔美貌，犹言婀娜。 [3]葳蕤（wēiruí）：草木茂盛枝叶下垂貌。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 34, "title": "燕昭王", "author": "陈子昂", "body": "南登碣石馆，遥望黄金台。\n丘陵尽乔木，昭王安在哉？\n霸图今已矣，驱马复归来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 35, "title": "登幽州台歌", "author": "陈子昂", "body": "前不见古人，后不见来者。\n念天地之悠悠，独怆然而涕下！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 36, "title": "晚次乐乡县", "author": "陈子昂", "body": "故乡杳无际，日暮且孤征。\n川原迷旧国，道路入边城。\n野戍荒烟断，深山古木平。\n如何此时恨，噭噭夜猿鸣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 37, "title": "送魏大从军", "author": "陈子昂", "body": "匈奴犹未灭，魏绛复从戎。\n怅别三河道，言追六郡雄。\n雁山横代北，狐塞接云中。\n勿使燕然上，惟留汉将功。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 38, "title": "春夜别友人", "author": "陈子昂", "body": "银烛吐青烟，金樽对绮筵。\n离堂思琴瑟，别路绕山川。\n明月隐高树，长河没晓天。\n悠悠洛阳道，此会在何年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 39, "title": "咏柳", "author": "贺知章", "body": "碧玉妆成一树高，万条垂下绿丝绦。\n不知细叶谁裁出，二月春风似剪刀。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 40, "title": "回乡偶书二首", "author": "贺知章", "body": "少小离家老大回，乡音无改鬓毛衰。\n儿童相见不相识，笑问客从何处来。\n离别家乡岁月多，近来人事半消磨。\n惟有门前镜湖水，春风不改旧时波。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 41, "title": "闺怨", "author": "沈如筠", "body": "雁尽书难寄，愁多梦不成。\n愿随孤月影，流照伏波营[1]。\n〔注〕[1]伏波营：刘永济《唐人绝句精华》称：“天宝中讨南诏（南诏国），故用伏波事。”“伏波”，指后汉伏波将军马援，他南征交阯，有功，被封为新息侯。用“伏波营”代指诗中征人所在军营，既是唐诗中以汉代唐的惯例，又说明征人戍守的是祖国的南疆。因为征人戍守南疆，细味诗意，思妇当自北望南。而南去传书之“雁尽”，其季节似在春天。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 42, "title": "春江花月夜", "author": "张若虚", "body": "春江潮水连海平，海上明月共潮生。\n滟滟随波千万里，何处春江无月明。\n江流宛转绕芳甸，月照花林皆似霰。\n空里流霜不觉飞，汀上白沙看不见。\n江天一色无纤尘，皎皎空中孤月轮。\n江畔何人初见月？江月何年初照人？\n人生代代无穷已，江月年年只相似。\n不知江月待何人，但见长江送流水。\n白云一片去悠悠，青枫浦上不胜愁。\n谁家今夜扁舟子？何处相思明月楼？\n可怜楼上月徘徊，应照离人妆镜台。\n玉户帘中卷不去，捣衣砧上拂还来。\n此时相望不相闻，愿逐月华流照君。\n鸿雁长飞光不度，鱼龙潜跃水成文。\n昨夜闲潭梦落花，可怜春半不还家。\n江水流春去欲尽，江潭落月复西斜。\n斜月沉沉藏海雾，碣石潇湘无限路。\n不知乘月几人归，落月摇情满江树。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 43, "title": "蜀道后期", "author": "张说", "body": "客心争日月，来往预期程。\n秋风不相待，先至洛阳城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 44, "title": "送梁六自洞庭山", "author": "张说", "body": "巴陵一望洞庭秋，日见孤峰水上浮。\n闻道神仙不可接，心随湖水共悠悠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 45, "title": "奉和春日幸望春宫应制", "author": "苏颋", "body": "东望望春春可怜，更逢晴日柳含烟。\n宫中下见南山尽，城上平临北斗悬。\n细草偏承回辇处，飞花故落奉觞前。\n宸游对此欢无极，鸟弄歌声杂管弦。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 46, "title": "汾上惊秋", "author": "苏颋", "body": "北风吹白云，万里渡河汾。\n心绪逢摇落，秋声不可闻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 47, "title": "边词", "author": "张敬忠", "body": "五原春色旧来迟，二月垂杨未挂丝。\n即今河畔冰开日，正是长安花落时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 48, "title": "感遇十二首（其一）", "author": "张九龄", "body": "兰叶春葳蕤，桂华秋皎洁。\n欣欣此生意，自尔为佳节。\n谁知林栖者，闻风坐相悦。\n草木有本心，何求美人折？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 49, "title": "感遇十二首（其四）", "author": "张九龄", "body": "孤鸿海上来，池潢不敢顾。\n侧见双翠鸟，巢在三珠树。\n矫矫珍木巅，得无金丸惧？\n美服患人指，高明逼神恶。\n今我游冥冥，弋者何所慕！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 50, "title": "感遇十二首（其七）", "author": "张九龄", "body": "江南有丹橘，经冬犹绿林。\n岂伊地气暖，自有岁寒心。\n可以荐嘉客，奈何阻重深！\n运命惟所遇，循环不可寻。\n徒言树桃李，此木岂无阴？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 51, "title": "湖口望庐山瀑布水", "author": "张九龄", "body": "万丈红泉落，迢迢半紫氛。\n奔流下杂树，洒落出重云。\n日照虹霓似，天清风雨闻。\n灵山多秀色，空水共氤氲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 52, "title": "望月怀远", "author": "张九龄", "body": "海上生明月，天涯共此时。\n情人怨遥夜，竟夕起相思。\n灭烛怜光满，披衣觉露滋。\n不堪盈手赠，还寝梦佳期。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 53, "title": "归燕诗", "author": "张九龄", "body": "海燕虽微眇，乘春亦暂来。\n岂知泥滓贱，只见玉堂开。\n绣户时双入，华堂日几回。\n无心与物竞，鹰隼莫相猜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 54, "title": "赋得自君之出矣", "author": "张九龄", "body": "自君之出矣，不复理残机。\n思君如满月，夜夜减清辉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 55, "title": "登鹳雀楼[1]", "author": "王之涣", "body": "白日依山尽，黄河入海流。\n欲穷千里目，更上一层楼。\n〔注〕[1]此诗作者一作朱斌，题为《登楼》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 56, "title": "凉州词", "author": "王之涣", "body": "黄河远上白云间，一片孤城万仞山。\n羌笛何须怨杨柳，春风不度玉门关。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 57, "title": "宴词", "author": "王之涣", "body": "长堤春水绿悠悠，畎[1]入漳河一道流。\n莫听声声催去棹，桃溪浅处不胜舟。\n〔注〕[1]畎（quǎn）：田间小沟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 58, "title": "秋登万山寄张五", "author": "孟浩然", "body": "北山白云里，隐者自怡悦。\n相望始登高，心随雁飞灭。\n愁因薄暮起，兴是清秋发。\n时见归村人，平沙渡头歇。\n天边树若荠，江畔洲如月。\n何当载酒来，共醉重阳节。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 59, "title": "夏日南亭怀辛大", "author": "孟浩然", "body": "山光忽西落，池月渐东上。\n散发乘夕凉，开轩卧闲敞。\n荷风送香气，竹露滴清响。\n欲取鸣琴弹，恨无知音赏。\n感此怀故人，中宵劳梦想。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 60, "title": "彭蠡湖中望庐山[1]", "author": "孟浩然", "body": "太虚生月晕，舟子知天风。\n挂席候明发，渺漫平湖中。\n中流见匡阜，势压九江雄。\n黯黮凝黛色，峥嵘当曙空。\n香炉初上日，瀑水喷成虹。\n久欲追尚子，况兹怀远公。\n我来限于役，未暇息微躬。\n淮海途将半，星霜岁欲穷。\n寄言岩栖者，毕趣当来同。\n〔注〕[1]彭蠡湖：古泽薮名，即今江西鄱阳湖。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 61, "title": "夜归鹿门歌", "author": "孟浩然", "body": "山寺鸣钟昼已昏，渔梁渡头争渡喧。\n人随沙岸向江村，余亦乘舟归鹿门。\n鹿门月照开烟树，忽到庞公栖隐处。\n岩扉松径长寂寥，唯有幽人独来去。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 62, "title": "望洞庭湖赠张丞相", "author": "孟浩然", "body": "八月湖水平，涵虚混太清。\n气蒸云梦泽[1]，波撼岳阳城。\n欲济无舟楫，端居耻圣明。\n坐观垂钓者，徒有羡鱼情。\n〔注〕[1]云梦：水泽名。古代云、梦二泽，长江之南为梦泽，长江之北为云泽，后淤积为陆地，并称为云梦泽，约为今洞庭湖北岸一带地区。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 63, "title": "秦中感秋寄远上人", "author": "孟浩然", "body": "一丘[1]常欲卧，三径[2]苦无资。\n北土非吾愿，东林[3]怀我师。\n黄金燃桂尽[4]，壮志逐年衰。\n日夕凉风至，闻蝉但益悲。\n〔注〕[1]一丘：《晋书·谢鲲传》:“明帝问曰：‘论者以君方庾亮，自谓何如？’答曰：‘端委庙堂，使百僚准则，鲲不如亮。一丘一壑，自谓过之。'”意指隐居山林。 [2]三径：《三辅决录》卷一：“蒋诩归乡里，荆棘塞门，舍中有三径，不出，唯求仲、羊仲从之游。”后便指归隐后所住的田园。 [3]东林：晋时刺史桓伊为高僧慧远于庐山东面建房殿，是为东林寺。 [4]黄金燃桂尽：《战国策·楚策》:“楚国之食贵于玉，薪贵于桂。”这里喻处境窘困。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 64, "title": "宿桐庐江寄广陵旧游", "author": "孟浩然", "body": "山暝听猿愁，沧江急夜流。\n风鸣两岸叶，月照一孤舟。\n建德非吾土，维扬忆旧游。\n还将两行泪，遥寄海西头。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 65, "title": "早寒有怀", "author": "孟浩然", "body": "木落雁南度，北风江上寒[1]。\n我家襄水曲，遥隔楚云端。\n乡泪客中尽，归帆天际看。\n迷津欲有问，平海夕漫漫。\n〔注〕[1]“木落”二句：南朝宋鲍照《登黄鹤矶》诗有“木落江渡寒，雁还风送秋”句。此二句当从此处脱化而来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 66, "title": "留别王维", "author": "孟浩然", "body": "寂寂竟何待，朝朝空自归。\n欲寻芳草去，惜与故人违。\n当路谁相假？知音世所稀。\n只应守寂寞，还掩故园扉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 67, "title": "与诸子登岘首[1]", "author": "孟浩然", "body": "人事有代谢，往来成古今。\n江山留胜迹，我辈复登临。\n水落鱼梁[2]浅，天寒梦泽[3]深。\n羊公碑尚在，读罢泪沾襟。\n〔注〕[1]岘首：即岘山，又称岘首山，在湖北襄阳南。 [2]鱼梁：指鱼梁洲。《水经注·沔水》:“沔水中有鱼梁洲，庞德公所居。” [3]梦泽：古代有云、梦二泽，后淤积为陆地，约为今洞庭湖北岸一带地区。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 68, "title": "晚泊浔阳望庐山", "author": "孟浩然", "body": "挂席几千里，名山都未逢。\n泊舟浔阳郭，始见香炉峰。\n尝读远公传，永怀尘外踪。\n东林精舍近，日暮空闻钟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 69, "title": "题义公禅房", "author": "孟浩然", "body": "义公习禅寂，结宇依空林。\n户外一峰秀，阶前众壑深。\n夕阳连雨足，空翠落庭阴。\n看取莲花净，方知不染心。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 70, "title": "过故人庄", "author": "孟浩然", "body": "故人具鸡黍，邀我至田家。\n绿树村边合，青山郭外斜。\n开轩面场圃，把酒话桑麻。\n待到重阳日，还来就菊花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 71, "title": "舟中晓望", "author": "孟浩然", "body": "挂席东南望，青山水国遥。\n舳舻争利涉，来往接风潮。\n问我今何适？天台访石桥。\n坐看霞色晓，疑是赤城标。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 72, "title": "岁暮归南山", "author": "孟浩然", "body": "北阙休上书，南山归敝庐。\n不才明主弃，多病故人疏。\n白发催年老，青阳逼岁除。\n永怀愁不寐，松月夜窗虚。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 73, "title": "春晓", "author": "孟浩然", "body": "春眠不觉晓，处处闻啼鸟。\n夜来风雨声，花落知多少？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 74, "title": "洛中访袁拾遗不遇", "author": "孟浩然", "body": "洛阳访才子，江岭作流人。\n闻说梅花早，何如北地春？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 75, "title": "宿建德江", "author": "孟浩然", "body": "移舟泊烟渚，日暮客愁新。\n野旷天低树，江清月近人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 76, "title": "送杜十四之江南", "author": "孟浩然", "body": "荆吴相接水为乡，君去春江正渺茫。\n日暮征帆何处泊？天涯一望断人肠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 77, "title": "渡浙江问舟中人", "author": "孟浩然", "body": "潮落江平未有风，扁舟共济与君同。\n时时引领望天末，何处青山是越中？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 78, "title": "古从军行", "author": "李颀", "body": "白日登山望烽火，黄昏饮马傍交河。\n行人刁斗风沙暗，公主琵琶幽怨多。\n野云万里无城郭，雨雪纷纷连大漠。\n胡雁哀鸣夜夜飞，胡儿眼泪双双落。\n闻道玉门犹被遮，应将性命逐轻车。\n年年战骨埋荒外，空见蒲桃入汉家。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 79, "title": "送陈章甫", "author": "李颀", "body": "四月南风大麦黄，枣花未落桐叶长。\n青山朝别暮还见，嘶马出门思旧乡。\n陈侯[1]立身何坦荡，虬须虎眉仍大颡[2]。\n腹中贮书一万卷，不肯低头在草莽。\n东门酤酒饮我曹，心轻万事如鸿毛。\n醉卧不知白日暮，有时空望孤云高。\n长河浪头连天黑，津口停舟渡不得。\n郑国游人未及家，洛阳行子空叹息。\n闻道故林相识多，罢官昨日今如何？\n〔注〕[1]陈侯：对陈章甫的尊称。 [2]虬：蜷曲。大颡（sǎng）：宽脑门。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 80, "title": "听安万善吹觱篥歌", "author": "李颀", "body": "南山截竹为觱篥[1]，此乐本自龟兹[2]出。\n流传汉地曲转奇，凉州胡人为我吹。\n旁邻闻者多叹息，远客思乡皆泪垂。\n世人解听不解赏，长飙风中自来往。\n枯桑老柏寒飕飗，九雏鸣凤乱啾啾。\n龙吟虎啸一时发，万籁百泉相与秋。\n忽然更作《渔阳掺》，黄云萧条白日暗。\n变调如闻《杨柳》春，上林繁花照眼新。\n岁夜高堂列明烛，美酒一杯声一曲。\n〔注〕[1]觱篥（bìlì）：亦作“筚篥”、“悲篥”，又名“笳管”。簧管古乐器，今已失传。以竹为主，上开八孔（前七后一），管口插有芦制的哨子。 [2]龟兹（qīucí）：古西域城国名，在今新疆库车县一带。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 81, "title": "古意", "author": "李颀", "body": "男儿事长征，少小幽燕客。\n赌胜马啼下，由来轻七尺。\n杀人莫敢前，须如蝟毛磔。\n黄云陇底白云飞，未得报恩不得归。\n辽东小妇年十五，惯弹琵琶能歌舞。\n今为羌笛出塞声，使我三军泪如雨。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 82, "title": "送刘昱", "author": "李颀", "body": "八月寒苇花，秋江浪头白。\n北风吹五两，谁是浔阳客？\n鸬鹚山头微雨晴，扬州郭里暮潮生。\n行人夜宿金陵渚，试听沙边有雁声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 83, "title": "听董大弹胡笳弄兼寄语房给事", "author": "李颀", "body": "蔡女昔造胡笳声，一弹一十有八拍。\n胡人落泪沾边草，汉使断肠对归客。\n古戍苍苍烽火寒，大荒沉沉飞雪白。\n先拂商弦后角羽，四郊秋叶惊摵摵。\n董夫子，通神明，深山窃听来妖精。\n言迟更速皆应手，将往复旋如有情。\n空山百鸟散还合，万里浮云阴且晴。\n嘶酸雏雁失群夜，断绝胡儿恋母声。\n川为净其波，鸟亦罢其鸣。\n乌孙部落家乡远，逻娑沙尘哀怨生。\n幽音变调忽飘洒，长风吹林雨堕瓦。\n迸泉飒飒飞木末，野鹿呦呦走堂下。\n长安城连东掖垣，凤凰池对青琐门。\n高才脱略名与利，日夕望君抱琴至。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 84, "title": "送魏万之京", "author": "李颀", "body": "朝闻游子唱离歌，昨夜微霜初渡河。\n鸿雁不堪愁里听，云山况是客中过。\n关城树色催寒近，御苑砧声向晚多。\n莫见长安行乐处，空令岁月易蹉跎。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 85, "title": "春泛若耶溪", "author": "綦毋潜", "body": "幽意无断绝，此去随所偶。\n晚风吹行舟，花路入溪口。\n际夜转西壑，隔山望南斗。\n潭烟飞溶溶，林月低向后。\n生事且弥漫，愿为持竿叟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 86, "title": "从军行七首（其一）", "author": "王昌龄", "body": "烽火城西百尺楼，黄昏独坐海风秋。\n更吹羌笛关山月，无那[1]金闺万里愁。\n〔注〕[1]无那：无奈，指无法消除思亲之愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 87, "title": "从军行七首（其二）", "author": "王昌龄", "body": "琵琶起舞换新声，总是关山旧别情。\n撩乱边愁听不尽，高高秋月照长城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 88, "title": "从军行七首（其四）", "author": "王昌龄", "body": "青海长云暗雪山，孤城遥望玉门关。\n黄沙百战穿金甲，不破楼兰终不还。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 89, "title": "从军行七首（其五）", "author": "王昌龄", "body": "大漠风尘日色昏，红旗半卷出辕门。\n前军夜战洮河北，已报生擒吐谷浑。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 90, "title": "出塞二首（其一）", "author": "王昌龄", "body": "秦时明月汉时关，万里长征人未还。\n但使龙城[1]飞将在，不教胡马度阴山[2]。\n〔注〕[1]龙城：或解释为匈奴祭天之处，其故地在今蒙古人民共和国鄂尔浑河西侧的和硕柴达木湖附近；或解释为卢龙城，在今河北省喜峰口附近一带，为汉代右北平郡所在地。《史记·李将军传》说：“广居右北平，匈奴闻之，号曰汉之飞将军，避之数岁，不敢入右北平。”后一解较合理。 [2]阴山：在今内蒙古自治区中部。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 91, "title": "采莲曲二首（其二）", "author": "王昌龄", "body": "荷叶罗裙一色裁，芙蓉向脸两边开。\n乱入池中看不见，闻歌始觉有人来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 92, "title": "春宫曲", "author": "王昌龄", "body": "昨夜风开露井桃，未央前殿月轮高。\n平阳歌舞新承宠，帘外春寒赐锦袍。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 93, "title": "西宫春怨", "author": "王昌龄", "body": "西宫夜静百花香，欲卷珠帘春恨长。\n斜抱云和深见月，朦胧树色隐昭阳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 94, "title": "长信秋词五首（其一）", "author": "王昌龄", "body": "金井梧桐秋叶黄，珠帘不卷夜来霜。\n熏笼玉枕无颜色，卧听南宫清漏长。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 95, "title": "长信秋词五首（其三）", "author": "王昌龄", "body": "奉帚平明金殿开，且将团扇共徘徊。\n玉颜不及寒鸦色，犹带昭阳日影来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 96, "title": "长信秋词五首（其四）", "author": "王昌龄", "body": "真成薄命久寻思，梦见君王觉后疑。\n火照西宫知夜饮，分明複道奉恩时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 97, "title": "青楼曲二首", "author": "王昌龄", "body": "白马金鞍随武皇，旌旗十万宿长杨。\n楼头少妇鸣筝坐，遥见飞尘入建章。\n驰道杨花满御沟，红妆漫绾上青楼。\n金章紫绶千馀骑，夫婿朝回初拜侯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 98, "title": "闺怨", "author": "王昌龄", "body": "闺中少妇不曾[1]愁，春日凝妆上翠楼。\n忽见陌头杨柳色，悔教夫婿觅封侯。\n〔注〕[1]刘永济《唐人绝句精华》注：“不曾”一本作“不知”。作“不曾”与凝妆上楼，忽见春光，顿觉孤寂，因而引起懊悔之意，相贯而有力。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 99, "title": "听流人水调子", "author": "王昌龄", "body": "孤舟微月对枫林，分付鸣筝与客心。\n岭色千重万重雨，断弦收与泪痕深。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 100, "title": "送魏二", "author": "王昌龄", "body": "醉别江楼橘柚香，江风引雨入舟凉。\n忆君遥在潇湘月，愁听清猿梦里长。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 101, "title": "芙蓉楼送辛渐[1]", "author": "王昌龄", "body": "寒雨连江夜入吴，平明送客楚山孤。\n洛阳亲友如相问，一片冰心在玉壶。\n〔注〕[1]刘永济《唐人绝句精华》云：“此昌龄方自龙标贬所归吴，次晨即于芙蓉楼饯别辛渐之作。”可资参考。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 102, "title": "送柴侍御", "author": "王昌龄", "body": "流水通波接武冈，送君不觉有离伤。\n青山一道同云雨，明月何曾是两乡。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 103, "title": "望蓟门", "author": "祖咏", "body": "燕台一去客心惊，笳鼓喧喧汉将营。\n万里寒光生积雪，三边[1]曙色动危旌。\n沙场烽火连胡月，海畔云山拥蓟城。\n少小虽非投笔吏，论功还欲请长缨。\n〔注〕[1]三边：古称幽州、并州、凉州为三边。这里泛指当时东北、北方、西北边防地带。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 104, "title": "终南望馀雪", "author": "祖咏", "body": "终南阴岭秀，积雪浮云端。\n林表明霁色，城中增暮寒。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 105, "title": "陇西行[1]", "author": "王维", "body": "十里一走马，五里一扬鞭。\n都护军书至，匈奴围酒泉。\n关山正飞雪，烽火断无烟。\n〔注〕[1]《陇西行》：乐府旧题，又称《步出夏门行》，属《相和歌·瑟调曲》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 106, "title": "送别", "author": "王维", "body": "下马饮[1]君酒，问君何所之？\n君言不得意，归卧南山陲。\n但去莫复问，白云无尽时。\n〔注〕[1]饮：这里是使动用法，“使……饮”的意思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 107, "title": "青溪", "author": "王维", "body": "言[1]入黄花川[2]，每逐青溪[3]水。\n随山将万转，趣[4]途无百里。\n声喧乱石中，色静深松里。\n漾漾泛菱荇，澄澄映葭苇。\n我心素已闲，清川澹如此。\n请留盘石上，垂钓将已矣。\n〔注〕[1]言：发语词，无意义。 [2]黄花川：在今陕西凤县东北黄花镇附近。 [3]青溪：在今陕西沔县之东。 [4]趣：通“趋”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 108, "title": "渭川田家", "author": "王维", "body": "斜光照墟落[1]，穷巷牛羊归。\n野老念牧童，倚杖候荆扉。\n雉雊[2]麦苗秀，蚕眠桑叶稀。\n田夫荷锄至，相见语依依。\n即此羡闲逸，怅然吟《式微》。\n〔注〕[1]墟落：村落。 [2]雉雊（gòu）：野鸡鸣叫。《诗·小雅·小弁》:“雉之朝雊，尚求其雌。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 109, "title": "春中田园作", "author": "王维", "body": "屋上春鸠鸣，村边杏花白。\n持斧伐远扬，荷锄觇泉脉。\n归燕识故巢，旧人看新历。\n临觞忽不御，惆怅思远客。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 110, "title": "新晴野望", "author": "王维", "body": "新晴原野旷，极目无氛垢。\n郭门临渡头，村树连溪口。\n白水明田外，碧峰出山后。\n农月无闲人，倾家事南亩。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 111, "title": "夷门歌", "author": "王维", "body": "七雄雄雌犹未分，攻城杀将何纷纷。\n秦兵益围邯郸急，魏王不救平原君。\n公子为嬴停驷马，执辔愈恭意愈下。\n亥为屠肆鼓刀人，嬴乃夷门抱关者。\n非但慷慨献奇谋，意气兼将生命酬。\n向风刎颈送公子，七十老翁何所求！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 112, "title": "陇头吟[1]", "author": "王维", "body": "长安少年游侠客，夜上戍楼看太白[2]。\n陇头明月迥临关，陇上行人夜吹笛。\n关西老将不胜愁，驻马听之双泪流。\n身经大小百馀战，麾下偏裨万户侯。\n苏武才为典属国[3]，节旄落尽海西头。\n〔注〕[1]《陇头吟》：乐府旧题。胡才甫《沧浪诗话笺注》说：“按《乐府诗集》，《陇头吟》无古辞。《陇头》二首，其一题陈后主作，又注一本无名氏。疑即此首。” [2]太白：即金星。古人认为它主兵象，可据以预测战事。 [3]典属国：汉代掌管藩属国家事务的官职，品位不高。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 113, "title": "老将行", "author": "王维", "body": "少年十五二十时，步行夺得胡马骑。\n射杀山中白额虎，肯数邺下黄鬚儿。\n一身转战三千里，一剑曾当百万师。\n汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。\n卫青不败由天幸，李广无功缘数奇。\n自从弃置便衰朽，世事蹉跎成白首。\n昔时飞箭无全目，今日垂杨生左肘。\n路旁时卖故侯瓜，门前学种先生柳。\n苍茫古木连穷巷，寥落寒山对虚牖。\n誓令疏勒出飞泉，不似颍川空使酒。\n贺兰山下阵如云，羽檄交驰日夕闻。\n节使三河募年少，诏书五道出将军。\n试拂铁衣如雪色，聊持宝剑动星文。\n愿得燕弓射天将，耻令越甲鸣吾君。\n莫嫌旧日云中守，犹堪一战取功勋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 114, "title": "桃源行", "author": "王维", "body": "渔舟逐水爱山春，两岸桃花夹去津。\n坐看红树不知远，行尽青溪不见人。\n山口潜行始隈隩，山开旷望旋平陆。\n遥看一处攒云树，近入千家散花竹。\n樵客初传汉姓名，居人未改秦衣服。\n居人共住武陵源[1]，还从物外[2]起田园。\n月明松下房栊静，日出云中鸡犬喧。\n惊闻俗客争来集，竞引还家问都邑。\n平明闾巷扫花开，薄暮渔樵乘水入。\n初因避地去人间，及至成仙遂不还。\n峡里谁知有人事，世中遥望空云山。\n不疑灵境难闻见，尘心未尽思乡县。\n出洞无论隔山水，辞家终拟长游衍。\n自谓经过旧不迷，安知峰壑今来变。\n当时只记入山深，青溪几度到云林。\n春来遍是桃花水，不辨仙源何处寻。\n〔注〕[1]武陵源：相传在今湖南桃源西南，晋时属武陵郡。 [2]物外：世外。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 115, "title": "辋川闲居赠裴秀才迪", "author": "王维", "body": "寒山转苍翠，秋水日潺湲。\n倚杖柴门外，临风听暮蝉。\n渡头馀落日，墟里上孤烟。\n复值接舆醉，狂歌五柳前。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 116, "title": "酬张少府", "author": "王维", "body": "晚年惟好静，万事不关心。\n自顾无长策，空知返旧林。\n松风吹解带，山月照弹琴。\n君问穷通理，渔歌入浦深。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 117, "title": "送梓州李使君", "author": "王维", "body": "万壑树参天，千山响杜鹃。\n山中一夜雨[1]，树杪百重泉。\n汉女输橦布，巴人讼芋田。\n文翁翻教授，不敢倚先贤。\n〔注〕[1]一本作“山中一半雨”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 118, "title": "过香积寺", "author": "王维", "body": "不知香积寺，数里入云峰。\n古木无人径，深山何处钟。\n泉声咽危石，日色冷青松。\n薄暮空潭曲，安禅制毒龙。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 119, "title": "山居秋暝", "author": "王维", "body": "空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。\n竹喧归浣女，莲动下渔舟。\n随意春芳歇，王孙自可留。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 120, "title": "终南别业", "author": "王维", "body": "中岁颇好道，晚家南山陲。\n兴来每独往，胜事空自知。\n行到水穷处，坐看云起时。\n偶然值林叟，谈笑无还期。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 121, "title": "归嵩山作", "author": "王维", "body": "清川带长薄[1]，车马去闲闲。\n流水如有意，暮禽相与还。\n荒城临古渡，落日满秋山。\n迢递嵩高下，归来且闭关。\n〔注〕[1]长薄：绵延的草木丛。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 122, "title": "终南山", "author": "王维", "body": "太乙近天都，连山接海隅。\n白云回望合，青霭入看无。\n分野中峰变，阴晴众壑殊。\n欲投人处宿，隔水问樵夫。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 123, "title": "观猎", "author": "王维", "body": "风劲角弓鸣，将军猎渭城。\n草枯鹰眼疾，雪尽马蹄轻。\n忽过新丰市，还归细柳营。\n回看射雕处，千里暮云平。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 124, "title": "汉江临泛[1]", "author": "王维", "body": "楚塞三湘[2]接，荆门九派[3]通。\n江流天地外，山色有无中。\n郡邑浮前浦，波澜动远空。\n襄阳好风日，留醉与山翁。\n〔注〕[1]元方回《瀛奎律髓》题作《汉江临眺》。汉江：即汉水。 [2]楚塞：指古代楚国地界。三湘：湘水合漓水称漓湘，合蒸水称蒸湘，合潇水称潇湘，故又称三湘。 [3]荆门：在今湖北荆门南。九派：九条支流。《文选》郭璞《江赋》:“流九派于浔阳。”李善注引应劭《汉书》注：“江自庐江浔阳分为九。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 125, "title": "使至塞上", "author": "王维", "body": "单车欲问边，属国[1]过居延。\n征蓬出汉塞，归雁入胡天。\n大漠孤烟直[2]，长河落日圆。\n萧关逢候骑[3]，都护在燕然[4]。\n〔注〕[1]属国：典属国的简称。本为秦汉时官名，这里代指使臣，是王维自指。 [2]孤烟直：直上的燧烟。宋陆佃《埤雅》:“古之烽火用狼粪，取其烟直而聚，虽风吹之不斜。” [3]萧关：在今宁夏回族自治区固原县东南。候骑（jì）：骑马的侦察兵。 [4]都护：当时边疆重镇都护府的长官，这里指河西节度使。燕（yān）然：即杭爱山，在今蒙古人民共和国境内。后汉车骑将军窦宪大破匈奴北单于，曾登燕然山刻石记功。这里借指最前线，并非实指。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 126, "title": "秋夜独坐", "author": "王维", "body": "独坐悲双鬓，空堂欲二更。\n雨中山果落，灯下草虫鸣。\n白发终难变，黄金不可成。\n欲知除老病，惟有学无生。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 127, "title": "送秘书晁监还日本国", "author": "王维", "body": "积水不可极，安知沧海东！\n九州何处远？万里若乘空。\n向国惟看日，归帆但信风。\n鳌身映天黑，鱼眼射波红。\n乡树扶桑外，主人孤岛中。\n别离方异域，音信若为通！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 128, "title": "奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制", "author": "王维", "body": "渭水自萦秦塞曲，黄山旧绕汉宫斜。\n銮舆迥出千门柳，阁道回看上苑花。\n云里帝城双凤阙，雨中春树万人家。\n为乘阳气行时令，不是宸游重物华。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 129, "title": "和贾至舍人早朝大明宫之作", "author": "王维", "body": "绛帻鸡人报晓筹，尚衣方进翠云裘。\n九天阊阖开宫殿，万国衣冠拜冕旒。\n日色才临仙掌动，香烟欲傍衮龙浮。\n朝罢须裁五色诏，佩声归到凤池头。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 130, "title": "酬郭给事", "author": "王维", "body": "洞门高阁霭馀晖，桃李阴阴柳絮飞。\n禁里疏钟官舍晚，省中啼鸟吏人稀。\n晨摇玉佩趋金殿，夕奉天书拜琐闱。\n强欲从君无那老，将因卧病解朝衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 131, "title": "出塞作", "author": "王维", "body": "居延城外猎天骄，白草连天野火烧。\n暮云空碛时驱马，秋日平原好射雕。\n护羌校尉朝乘障，破虏将军夜渡辽。\n玉靶角弓珠勒马，汉家将赐霍嫖姚。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 132, "title": "春日与裴迪过新昌里访吕逸人不遇", "author": "王维", "body": "桃源一向绝风尘，柳市南头访隐沦。\n到门不敢题凡鸟，看竹何须问主人。\n城上青山如屋里，东家流水入西邻。\n闭户著书多岁月，种松皆作老龙鳞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 133, "title": "积雨辋川庄作", "author": "王维", "body": "积雨空林烟火迟，蒸藜[1]炊黍饷东菑[2]。\n漠漠水田飞白鹭，阴阴夏木啭黄鹂。\n山中习静观朝槿[3]，松下清斋折露葵[4]。\n野老与人争席罢，海鸥何事更相疑？\n〔注〕[1]藜：一种草本植物，嫩叶新苗皆可食。 [2]菑（zī）：已开垦一年的土地，这里泛指田亩。 [3]朝槿（jǐn）：即木槿，落叶灌木，夏秋之际开花，朝开暮谢，古人以为人生无常的象征。 [4]露葵：即绿葵，一种绿色蔬菜，可以煮来佐餐。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 134, "title": "息夫人", "author": "王维", "body": "莫以今时宠，能忘旧日恩。\n看花满眼泪，不共楚王言。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 135, "title": "孟城坳", "author": "王维", "body": "新家孟城口，古木馀衰柳。\n来者复为谁，空悲昔人有。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 136, "title": "鹿柴", "author": "王维", "body": "空山不见人，但闻人语响。\n返景入深林，复照青苔上。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 137, "title": "栾家濑", "author": "王维", "body": "飒飒秋雨中，浅浅石溜泻。\n跳波自相溅，白鹭惊复下。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 138, "title": "白石滩", "author": "王维", "body": "清浅白石滩，绿蒲向堪把。\n家住水东西，浣纱明月下。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 139, "title": "竹里馆", "author": "王维", "body": "独坐幽篁里，弹琴复长啸。\n深林人不知，明月来相照。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 140, "title": "辛夷坞", "author": "王维", "body": "木末芙蓉花，山中发红萼。\n涧户寂无人，纷纷开且落。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 141, "title": "漆园", "author": "王维", "body": "古人非傲吏，自阙经世务。\n偶寄一微官，婆娑数株树。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 142, "title": "鸟鸣涧", "author": "王维", "body": "人闲桂花落，夜静春山空。\n月出惊山鸟，时鸣春涧中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 143, "title": "山中送别", "author": "王维", "body": "山中相送罢，日暮掩柴扉。\n春草明年绿，王孙归不归？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 144, "title": "杂诗（其二）", "author": "王维", "body": "君自故乡来，应知故乡事。\n来日绮窗前，寒梅著花未？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 145, "title": "相思", "author": "王维", "body": "红豆生南国，春来[1]发几枝？\n愿君多采撷，此物最相思。\n〔注〕[1]春来：《王右丞集》作“秋来”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 146, "title": "书事", "author": "王维", "body": "轻阴阁小雨，深院昼慵开。\n坐看苍苔色，欲上人衣来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 147, "title": "山中", "author": "王维", "body": "荆溪白石出，天寒红叶稀。\n山路元[1]无雨，空翠湿人衣。\n〔注〕[1]元：通“原”，原来，本来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 148, "title": "田园乐（其六）", "author": "王维", "body": "桃红复含宿雨，柳绿更带朝烟。\n花落家童未扫，莺啼山客犹眠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 149, "title": "少年行（其一）", "author": "王维", "body": "新丰美酒斗十千，咸阳游侠多少年。\n相逢意气为君饮，系马高楼垂柳边。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 150, "title": "九月九日忆山东兄弟", "author": "王维", "body": "独在异乡为异客，每逢佳节倍思亲。\n遥知兄弟登高处，遍插茱萸少一人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 151, "title": "送元二使安西", "author": "王维", "body": "渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 152, "title": "送沈子福之江东", "author": "王维", "body": "杨柳渡头行客稀，罟师荡桨向临圻。\n惟有相思似春色，江南江北送君归。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 153, "title": "伊州歌", "author": "王维", "body": "清风明月苦相思，荡子从戎十载馀。\n征人去日殷勤嘱，归雁来时数附书。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 154, "title": "寻西山隐者不遇", "author": "丘为", "body": "绝顶一茅茨，直上三十里。\n扣关无僮仆，窥室唯案几。\n若非巾柴车，应是钓秋水。\n差池不相见，黾勉[1]空仰止。\n草色新雨中，松声晚窗里。\n及兹契幽绝，自足荡心耳。\n虽无宾主意，颇得清净理。\n兴尽方下山，何必待之子。\n〔注〕[1]黾（mǐn）勉：勉力；尽力。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 155, "title": "古风（其一）", "author": "李白", "body": "大雅久不作，吾衰竟谁陈？\n王风委蔓草，战国多荆榛。\n龙虎相啖食，兵戈逮狂秦。\n正声何微茫，哀怨起骚人。\n扬马激颓波，开流荡无垠。\n废兴虽万变，宪章亦已沦。\n自从建安来，绮丽不足珍。\n圣代复元古，垂衣贵清真。\n群才属休明，乘运共跃鳞。\n文质相炳焕，众星罗秋旻。\n我志在删述，垂辉映千春。\n希圣如有立，绝笔于获麟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 156, "title": "古风（其三）", "author": "李白", "body": "秦王扫六合，虎视何雄哉！\n挥剑决浮云，诸侯尽西来。\n明断自天启，大略驾群才。\n收兵铸金人，函谷正东开。\n铭功会稽岭，骋望琅邪台。\n刑徒七十万，起土骊山隈。\n尚采不死药，茫然使心哀。\n连弩射海鱼，长鲸正崔嵬。\n额鼻象五岳，扬波喷云雷。\n鬐鬣蔽青天，何由睹蓬莱。\n徐巿载秦女，楼船几时回？\n但见三泉下，金棺葬寒灰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 157, "title": "古风（其十五）", "author": "李白", "body": "燕昭延郭隗，遂筑黄金台。\n剧辛方赵至，邹衍复齐来。\n奈何青云士，弃我如尘埃。\n珠玉买歌笑，糟糠养贤才。\n方知黄鹄举，千里独徘徊。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 158, "title": "古风（其十九）", "author": "李白", "body": "西上莲花山，迢迢见明星。\n素手把芙蓉，虚步蹑太清。\n霓裳曳广带，飘拂升天行。\n邀我至云台，高揖卫叔卿。\n恍恍与之去，驾鸿凌紫冥。\n俯视洛阳川，茫茫走胡兵。\n流血涂野草，豺狼尽冠缨。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 159, "title": "古风（其二十四）", "author": "李白", "body": "大车扬飞尘，亭午暗阡陌。\n中贵多黄金，连云开甲宅。\n路逢斗鸡者，冠盖何辉赫！\n鼻息干虹蜺，行人皆怵惕。\n世无洗耳翁，谁知尧与跖！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 160, "title": "古风（其三十一）", "author": "李白", "body": "郑客西入关，行行未能已，\n白马华山君，相逢平原里，\n璧遗镐池君，明年祖龙死。\n秦人相谓曰：吾属可去矣！\n一往桃花源，千春隔流水。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 161, "title": "古风（其三十四）", "author": "李白", "body": "羽檄如流星，虎符合专城。\n喧呼救边急，群鸟皆夜鸣。\n白日曜紫微，三公运权衡。\n天地皆得一，澹然四海清。\n借问此何为？答言楚征兵。\n渡泸及五月，将赴云南征。\n怯卒非战士，炎方难远行。\n长号别严亲，日月惨光晶。\n泣尽继以血，心摧两无声。\n困兽当猛虎，穷鱼饵奔鲸。\n千去不一回，投躯岂全生！\n如何舞干戚，一使有苗平！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 162, "title": "古风（其四十六）", "author": "李白", "body": "一百四十年，国容何赫然。\n隐隐五凤楼，峨峨横三川[1]。\n王侯象星月[2]，宾客如云烟。\n斗鸡金宫里，蹴鞠瑶台边。\n举动摇白日，指挥回青天。\n当涂何翕忽，失路长弃捐。\n独有扬执戟，闭关草《太玄》[3]。\n〔注〕[1]三川：指流经长安一带的三条水——泾水、洛水、渭水。 [2]史载开元、天宝年间，宦官“黄衣以上三千员，衣朱紫千余人，其称旨辄拜三品将军”（《新唐书·宦官传上》）。[3]汉代的郎官执戟宿卫宫殿，扬雄曾为郎官，所以称他扬执戟。《汉书·扬雄传》载，汉哀帝时，外戚丁明、傅晏和佞幸董贤用事，“诸附离之者，或起家至二千石”，而扬雄则不肯趋附，闭门“草《太玄》，有以自守，泊如也”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 163, "title": "远别离", "author": "李白", "body": "远别离，古有皇英之二女；\n乃在洞庭之南，潇湘之浦。\n海水直下万里深，谁人不言此离苦？\n日惨惨兮云冥冥，猩猩啼烟兮鬼啸雨。\n我纵言之将何补？\n皇穹窃恐不照余之忠诚，雷凭凭兮欲吼怒。\n尧舜当之亦禅禹，君失臣兮龙为鱼，权归臣兮鼠变虎。\n或云尧幽囚，舜野死。\n九疑联绵皆相似，重瞳孤坟竟何是？\n帝子泣兮绿云间，随风波兮去无还。\n恸哭兮远望，见苍梧之深山。\n苍梧山崩湘水绝，竹上之泪乃可灭。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 164, "title": "蜀道难", "author": "李白", "body": "噫吁嚱，危乎高哉！蜀道之难难于上青天！\n蚕丛及鱼凫，开国何茫然！\n尔来四万八千岁，不与秦塞通人烟。\n西当太白有鸟道，可以横绝峨眉巅。\n地崩山摧壮士死，然后天梯石栈相钩连。\n上有六龙回日之高标，下有冲波逆折之回川。\n黄鹤之飞尚不得过，猿猱欲度愁攀援。\n青泥何盘盘，百步九折萦岩峦。\n扪参历井仰胁息，以手抚膺坐长叹。\n问君西游何时还？畏途巉岩不可攀。\n但见悲鸟号古木，雄飞雌从绕林间。\n又闻子规啼夜月，愁空山。\n蜀道之难难于上青天，使人听此凋朱颜！\n连峰去天不盈尺，枯松倒挂倚绝壁。\n飞湍瀑流争喧，砯崖转石万壑雷。\n其险也如此，嗟尔远道之人，胡为乎来哉！\n剑阁峥嵘而崔嵬，一夫当关，万夫莫开。\n所守或匪亲，化为狼与豺，\n朝避猛虎，夕避长蛇，磨牙吮血，杀人如麻。\n锦城虽云乐，不如早还家。\n蜀道之难，难于上青天，侧身西望长咨嗟！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 165, "title": "梁甫吟", "author": "李白", "body": "长啸梁甫吟，何时见阳春？\n君不见朝歌屠叟辞棘津，八十西来钓渭滨！\n宁羞白发照清水？逢时壮气思经纶。\n广张三千六百钓，风期暗与文王亲。\n大贤虎变愚不测，当年颇似寻常人。\n君不见高阳酒徒起草中，长揖山东隆准公！\n入门不拜骋雄辩，两女辍洗来趋风。\n东下齐城七十二，指挥楚汉如旋蓬。\n狂客落魄尚如此，何况壮士当群雄！\n我欲攀龙见明主，雷公砰訇震天鼓，帝旁投壶多玉女。\n三时大笑开电光，倏烁晦冥起风雨。\n阊阖九门不可通，以额扣关阍者怒。\n白日不照吾精诚，杞国无事忧天倾。\n猰㺄[1]磨牙竞人肉，驺虞[2]不折生草茎。\n手接飞猱搏雕虎，侧足焦原[3]未言苦。\n智者可卷愚者豪，世人见我轻鸿毛。\n力排南山三壮士，齐相杀之费二桃[4]。\n吴楚弄兵无剧孟[5]，亚夫咍尔为徒劳。\n梁甫吟，声正悲。\n张公两龙剑，神物合有时。\n风云感会起屠钓，大人𡸣屼当安之。\n〔注〕[1]猰㺄（yàyǔ）：古代传说中一种吃人的野兽。 [2]驺（zōu）虞：古代传说中的一种仁兽，不吃生物，不在草上践踏。这里用来比喻仁慈的统治者。 [3]焦原：传说中春秋时莒国的一块大石名。它宽五十步，下面是百丈深溪，无人敢近。 [4]据《晏子春秋》记载：春秋时齐景公手下有公孙接、田开疆、古冶子三个力能搏虎的勇士，都曾立过大功。有一次相国晏子见他们不懂君臣、尊卑之别，产生了疑忌，就建议景公除掉他们。办法是由景公派人赏赐给他们两只桃子，叫他们三人“计功而食桃”。公孙接和田开疆都以为自己功大，各拿了一只桃子，而古冶子认为自己的功劳更大，要二人退出桃子。二人感到羞愧而自杀。古冶子因二人之死而无颜独生，同样自杀身亡。 [5]剧孟：西汉初，吴楚七国叛乱，汉景帝派窦婴、周亚夫前去讨伐。周亚夫在将到河南时，找到侠士剧孟，笑吴楚不用剧孟而起兵，实是徒劳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 166, "title": "乌夜啼", "author": "李白", "body": "黄云城边乌欲栖，归飞哑哑枝上啼。\n机中织锦秦川女，碧纱如烟隔窗语。\n停梭怅然忆远人，独宿空房泪如雨。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 167, "title": "乌栖曲", "author": "李白", "body": "姑苏台上乌栖时，吴王宫里醉西施。\n吴歌楚舞欢未毕，青山欲衔半边日。\n银箭金壶漏水多，起看秋月坠江波。\n东方渐高奈乐何！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 168, "title": "战城南", "author": "李白", "body": "去年战，桑干[1]源；\n今年战，葱河[2]道。\n洗兵条支[3]海上波，放马天山雪中草。\n万里长征战，三军尽衰老。\n匈奴以杀戮为耕作，古来惟见白骨黄沙田。\n秦家筑城备胡处，汉家还有烽火燃。\n烽火燃不息，征战无已时！\n野战格斗死，败马号鸣向天悲。\n乌鸢啄人肠，衔飞上挂枯树枝。\n士卒涂草莽，将军空尔为。\n乃知兵者是凶器，圣人不得已而用之。\n〔注〕[1]桑干：河名，流经今山西、河北北部，地属北方。 [2]葱河：即葱岭河，在今新疆西南部，地属西方。 [3]条支：西域国名，即唐时的大食，在今伊朗境内。唐朝安西都护府下设有条支都督府。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 169, "title": "将进酒", "author": "李白", "body": "君不见黄河之水天上来，奔流到海不复回。\n君不见高堂明镜悲白发，朝如青丝暮成雪。\n人生得意须尽欢，莫使金樽空对月。\n天生我材必有用，千金散尽还复来。\n烹羊宰牛且为乐，会须一饮三百杯。\n岑夫子，丹丘生，将进酒，杯莫停。\n与君歌一曲，请君为我倾耳听。\n钟鼓馔玉不足贵，但愿长醉不复醒。\n古来圣贤皆寂寞，惟有饮者留其名。\n陈王昔时宴平乐，斗酒十千恣欢谑。\n主人何为言少钱，径须沽取对君酌。\n五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 170, "title": "行路难三首（其一）", "author": "李白", "body": "金樽清酒斗十千，玉盘珍羞直万钱。\n停杯投箸不能食，拔剑四顾心茫然。\n欲渡黄河冰塞川，将登太行雪满山。\n闲来垂钓碧溪上，忽复乘舟梦日边。\n行路难，行路难，多歧路，今安在？\n长风破浪会有时，直挂云帆济沧海！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 171, "title": "行路难三首（其二）", "author": "李白", "body": "大道如青天，我独不得出。\n羞逐长安社中儿，赤鸡白雉赌梨栗。\n弹剑作歌奏苦声，曳裾王门不称情。\n淮阴市井笑韩信，汉朝公卿忌贾生。\n君不见昔时燕家重郭隗，拥篲折节无嫌猜。\n剧辛乐毅感恩分，输肝剖胆效英才。\n昭王白骨萦蔓草，谁人更扫黄金台？\n行路难，归去来！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 172, "title": "日出入行", "author": "李白", "body": "日出东方隈，似从地底来。\n历天又复入西海，六龙所舍安在哉？\n其始与终古不息，人非元气[1]，安得与之久徘徊？\n草不谢荣于春风，木不怨落于秋天。\n谁挥鞭策驱四运[2]？万物兴歇皆自然。\n羲和！羲和！汝奚汩没于荒淫之波？\n鲁阳[3]何德，驻景挥戈？\n逆道违天，矫诬实多。\n吾将囊括大块，浩然与溟涬同科！\n〔注〕[1]元气：我国古代哲学家常用的术语，认为它是最原始、最本质的因素，混沌一片，浩瀚无边，天地万物都是由它派生出来的。 [2]四运：指春、夏、秋、冬四时。 [3]鲁阳：即鲁阳公。《淮南子·览冥训》说鲁阳公与韩作战，十分激烈，时近黄昏，鲁阳公援戈一挥，使太阳退了三舍（一舍三十里）。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 173, "title": "北风行", "author": "李白", "body": "烛龙栖寒门，光耀犹旦开。\n日月照之何不及此，唯有北风号怒天上来。\n燕山雪花大如席，片片吹落轩辕台。\n幽州思妇十二月，停歌罢笑双蛾摧。\n倚门望行人，念君长城苦寒良可哀。\n别时提剑救边去，遗此虎文金鞞靫。\n中有一双白羽箭，蜘蛛结网生尘埃。\n箭空在，人今战死不复回。\n不忍见此物，焚之已成灰。\n黄河捧土尚可塞，北风雨雪恨难裁！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 174, "title": "关山月", "author": "李白", "body": "明月出天山，苍茫云海间。\n长风几万里，吹度玉门关。\n汉下白登道，胡窥青海湾。\n由来征战地，不见有人还。\n戍客望边色，思归多苦颜。\n高楼当此夜，叹息未应闲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 175, "title": "杨叛儿", "author": "李白", "body": "君歌《杨叛儿》，妾劝新丰酒。\n何许最关人？乌啼白门柳。\n乌啼隐杨花，君醉留妾家。\n博山炉中沉香火，双烟一气凌紫霞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 176, "title": "长干行", "author": "李白", "body": "妾发初复额，折花门前剧[1]。\n郎骑竹马来，绕床弄青梅。\n同居长干里，两小无嫌猜。\n十四为君妇，羞颜未尝开。\n低头向暗壁，千唤不一回。\n十五始展眉，愿同尘与灰。\n常存抱柱信，岂上望夫台。\n十六君远行，瞿塘滟滪堆。\n五月不可触，猿声天上哀。\n门前迟行迹[2]，一一生绿苔。\n苔深不能扫，落叶秋风早。\n八月蝴蝶黄，双飞西园草。\n感此伤妾心，坐愁红颜老。\n早晚下三巴，预将书报家。\n相迎不道远，直至长风沙[3]。\n〔注〕[1]剧：游戏。 [2]迟：等待。“迟行迹”，一作“旧行迹”，指与丈夫共同生活时往来留下的足迹。 [3]长风沙：地名，在今安徽安庆市东长江边上。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 177, "title": "古朗月行", "author": "李白", "body": "小时不识月，呼作白玉盘。\n又疑瑶台镜，飞在青云端。\n仙人垂两足，桂树何团团。\n白兔捣药成，问言与谁餐？\n蟾蜍蚀圆影，大明夜已残。\n羿昔落九乌，天人清且安。\n阴精此沦惑，去去不足观。\n忧来其如何？凄怆摧心肝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 178, "title": "妾薄命", "author": "李白", "body": "汉帝重阿娇，贮之黄金屋。\n咳唾落九天，随风生珠玉。\n宠极爱还歇，妒深情却疏。\n长门一步地，不肯暂回车。\n雨落不上天，水覆难再收。\n君情与妾意，各自东西流。\n昔日芙蓉花，今成断根草。\n以色事他人，能得几时好？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 179, "title": "塞下曲六首（其一）", "author": "李白", "body": "五月天山雪，无花只有寒。\n笛中闻折柳，春色未曾看。\n晓战随金鼓，宵眠抱玉鞍。\n愿将腰下剑，直为斩楼兰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 180, "title": "玉阶怨", "author": "李白", "body": "玉阶生白露，夜久侵罗袜。\n却下水晶帘，玲珑望秋月。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 181, "title": "宫中行乐词八首（其一）", "author": "李白", "body": "小小生金屋，盈盈在紫微。\n山花插宝髻，石竹[1]绣罗衣。\n每出深宫里，常随步辇归。\n只愁歌舞散，化作彩云飞。\n〔注〕[1]石竹：指石竹花，细叶剪绒，娇艳㛹娟。自六朝至宋代，多取其样绣为衣服图案。见于歌咏者，如陆龟蒙《石竹花咏》:“曾看南朝画国娃，古罗衣上碎明霞”。宋王安石《石竹花》:“已向美人衣上绣”及“绣在罗衣色未真”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 182, "title": "清平调词三首", "author": "李白", "body": "云想衣裳花想容，春风拂槛露华浓。\n若非群玉山头见，会向瑶台月下逢。\n一枝红艳露凝香，云雨巫山枉断肠。\n借问汉宫谁得似？可怜飞燕倚新妆。\n名花倾国两相欢，长得君王带笑看。\n解释春风无限恨，沉香亭北倚阑干。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 183, "title": "丁都护歌", "author": "李白", "body": "云阳上征去，两岸饶商贾。\n吴牛喘月时，拖船一何苦！\n水浊不可饮，壶浆半成土。\n一唱都护歌，心摧泪如雨。\n万人系磐石，无由达江浒。\n君看石芒砀，掩泪悲千古。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 184, "title": "静夜思", "author": "李白", "body": "床前明月光[1]，疑是地上霜。\n举头望明月[2]，低头思故乡。\n〔注〕[1]明月光：一作“看月光”。 [2]望明月：一作“望山月”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 185, "title": "从军行", "author": "李白", "body": "百战沙场碎铁衣，城南已合数重围。\n突营射杀呼延将，独领残兵千骑归。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 186, "title": "春思", "author": "李白", "body": "燕草如碧丝，秦桑低绿枝。\n当君怀归日，是妾断肠时。\n春风不相识，何事入罗帏？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 187, "title": "长相思", "author": "李白", "body": "长相思，在长安。\n络纬秋啼金井阑，微霜凄凄簟色寒。\n孤灯不明思欲绝，卷帷望月空长叹。\n美人如花隔云端。\n上有青冥之高天，下有渌水之波澜。\n天长路远魂飞苦，梦魂不到关山难。\n长相思，摧心肝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 188, "title": "襄阳歌", "author": "李白", "body": "落日欲没岘山[1]西，倒著接羃花下迷。\n襄阳小儿齐拍手，拦街争唱《白铜鞮》[2]。\n旁人借问笑何事，笑杀山公醉似泥。\n鸬鹚杓，鹦鹉杯[3]。\n百年三万六千日，一日须倾三百杯。\n遥看汉水鸭头绿，恰似葡萄初酦醅[4]。\n此江若变作春酒，垒曲便筑糟丘台。\n千金骏马换小妾[5]，醉坐雕鞍歌《落梅》。\n车旁侧挂一壶酒，凤笙龙管行相催[6]。\n咸阳市中叹黄犬，何如月下倾金罍[7]？\n君不见晋朝羊公一片石，龟头[8]剥落生莓苔。\n泪亦不能为之堕，心亦不能为之哀。\n清风朗月不用一钱买，玉山自倒非人推[9]。\n舒州杓，力士铛，李白与尔同死生。\n襄王云雨今安在？江水东流猿夜声。\n〔注〕[1]岘（xiàn）山：一名岘首山，在今湖北襄阳县南。 [2]白铜鞮（dī）：南朝童谣名，流行于襄阳一带。 [3]鸬鹚杓（lúcísháo）：形如长颈水鸟鸬鹚的长柄酒杓。鹦鹉杯：用一种形状和颜色像鹦鹉嘴的螺壳制成的酒杯。 [4]酦醅（pōpēi）：重酿而未滤过的酒。[5]古乐府有《爱妾换马》诗题。三国魏时曹彰也曾用爱妾换马。这里李白是强调马的名贵。[6]催：劝酒。 [7]罍（léi）：酒器。 [8]龟头：古时碑座石刻形状像龟，名叫赑屃（bìxì）。[9]玉山自倒：三国魏嵇康风仪俊美，人家说他醉后如玉山将倒。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 189, "title": "江上吟", "author": "李白", "body": "木兰之枻沙棠[1]舟，玉箫金管坐两头。\n美酒尊中置千斛，载妓随波任去留。\n仙人有待乘黄鹤，海客无心随白鸥。\n屈平词赋悬日月，楚王台榭空山丘。\n兴酣落笔摇五岳，诗成笑傲凌沧洲。\n功名富贵若长在，汉水亦应西北流。\n〔注〕[1]枻（yì）：同“楫”，舟旁划水的工具。沙棠：木名。据《山海经·西山经》说，沙棠出昆仑山上，人吃了它的果实“入水不溺”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 190, "title": "玉壶吟", "author": "李白", "body": "烈士击玉壶，壮心惜暮年。\n三杯拂剑舞秋月，忽然高咏涕泗涟。\n凤凰初下紫泥诏[1]，谒帝称觞登御筵。\n揄扬九重万乘主，谑浪赤墀青琐贤[2]。\n朝天数换飞龙马，敕赐珊瑚白玉鞭。\n世人不识东方朔，大隐金门是谪仙。\n西施宜笑复宜颦，丑女效之徒累身。\n君王虽爱蛾眉好，无奈宫中妒杀人！\n〔注〕[1]凤凰：这里是指皇帝的诏书。据《十六国春秋》记载，后赵武帝石虎在戏马观上设置一只能回转的木凤凰，口衔五色诏书，故后来称诏书为凤凰诏。紫泥：一种紫色的印泥，封诏书用。 [2]赤墀（chí）：皇帝宫殿前的台阶涂成赤色，叫赤墀。青琐：皇帝宫殿的门雕刻成连锁文，涂以青色，叫青琐。“赤墀青琐贤”指臣僚。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 191, "title": "梁园吟", "author": "李白", "body": "我浮黄河去京阙，挂席欲进波连山。\n天长水阔厌远涉，访古始及平台间。\n平台为客忧思多，对酒遂作梁园歌。\n却忆蓬池阮公咏，因吟“渌水扬洪波”。\n洪波浩荡迷旧国，路远西归安可得！\n人生达命岂暇愁，且饮美酒登高楼。\n平头奴子摇大扇，五月不热疑清秋。\n玉盘杨梅为君设，吴盐如花皎白雪。\n持盐把酒但饮之，莫学夷齐事高洁。\n昔人豪贵信陵君，今人耕种信陵坟。\n荒城虚照碧山月，古木尽入苍梧云。\n梁王宫阙今安在？枚马先归不相待。\n舞影歌声散渌池，空馀汴水东流海。\n沈吟此事泪满衣，黄金买醉未能归。\n连呼五白行六博，分曹赌酒酣驰晖。\n歌且谣，意方远，\n东山高卧时起来，欲济苍生未应晚。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 192, "title": "横江词六首（其一）", "author": "李白", "body": "人道横江好，侬道横江恶。\n猛风吹倒天门山[1]，白浪高于瓦官阁。\n〔注〕[1]此句一作“一风三日吹倒山”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 193, "title": "横江词六首（其五）", "author": "李白", "body": "横江馆前津吏迎，向余东指海云生，\n“郎今欲渡缘何事？如此风波不可行。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 194, "title": "金陵城西楼月下吟", "author": "李白", "body": "金陵夜寂凉风发，独上高楼望吴越。\n白云映水摇空城，白露垂珠滴秋月。\n月下沉吟久不归，古来相接眼中稀。\n解道“澄江净如练”，令人长忆谢玄晖。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 195, "title": "白云歌送刘十六归山", "author": "李白", "body": "楚山秦山[1]皆白云，白云处处长随君。\n长随君，君入楚山里，云亦随君渡湘水。\n湘水上，女萝衣，白云堪卧君早归。\n〔注〕[1]楚山：这里指今湖南地区，湖南古属楚疆。秦山：这里指唐都长安，古属秦地。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 196, "title": "秋浦歌十七首（其十四）", "author": "李白", "body": "炉火照天地，红星乱紫烟。\n赧郎明月夜，歌曲动寒川。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 197, "title": "秋浦歌十七首（其十五）", "author": "李白", "body": "白发三千丈，缘愁似箇长。\n不知明镜里，何处得秋霜！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 198, "title": "当涂赵炎少府粉图山水歌", "author": "李白", "body": "峨眉高出西极天，罗浮直与南溟连。\n名公绎思挥彩笔，驱山走海置眼前。\n满堂空翠如可扫，赤城霞气苍梧烟。\n洞庭潇湘意渺绵，三江七泽情洄沿。\n惊涛汹涌向何处，孤舟一去迷归年。\n征帆不动亦不旋，飘如随风落天边。\n心摇目断兴难尽，几时可到三山巅？\n西峰峥嵘喷流泉，横石蹙水波潺湲。\n东崖合沓蔽轻雾，深林杂树空芊绵。\n此中冥昧失昼夜，隐几寂听无鸣蝉。\n长松之下列羽客，对坐不语南昌仙。\n南昌仙人赵夫子，妙年历落青云士。\n讼庭无事罗众宾，杳然如在丹青里。\n五色粉图安足珍？真仙可以全吾身。\n若待功成拂衣去，武陵桃花笑杀人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 199, "title": "永王东巡歌十一首（其二）", "author": "李白", "body": "三川北虏乱如麻，四海南奔似永嘉。\n但用东山谢安石，为君谈笑静胡沙。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 200, "title": "永王东巡歌十一首（其十一）", "author": "李白", "body": "试借君王玉马鞭，指挥戎虏坐琼筵。\n南风一扫胡尘静，西入长安到日边。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 201, "title": "峨眉山月歌", "author": "李白", "body": "峨眉山月半轮秋，影入平羌江水流。\n夜发清溪向三峡，思君[1]不见下渝州。\n〔注〕[1]一说“君”即指峨眉山月。清沈德潜《唐诗别裁集》:“月在清溪、三峡之间，半轮亦不复见矣。‘君’字即指月。”一说“君”指同住峨眉山的友人，则诗中山月兼为友情之象征。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 202, "title": "清溪行", "author": "李白", "body": "清溪清我心，水色异诸水。\n借问新安江，见底何如此？\n人行明镜中，鸟度屏风里。\n向晚猩猩啼，空悲远游子。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 203, "title": "临路歌", "author": "李白", "body": "大鹏飞兮振八裔，中天摧兮力不济。\n馀风激兮万世，游扶桑兮挂石[1]袂。\n后人得之传此，仲尼亡兮谁为出涕？\n〔注〕[1]石：清王琦辑注《李太白文集》云：当作“左”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 204, "title": "赠孟浩然", "author": "李白", "body": "吾爱孟夫子，风流天下闻。\n红颜弃轩冕，白首卧松云。\n醉月频中圣，迷花不事君。\n高山安可仰，徒此揖清芬。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 205, "title": "江夏赠韦南陵冰", "author": "李白", "body": "胡骄马惊沙尘起，胡雏饮马天津水。\n君为张掖近酒泉，我窜三巴九千里。\n天地再新法令宽，夜郎迁客带霜寒。\n西忆故人不可见，东风吹梦到长安。\n宁期此地忽相遇，惊喜茫如堕烟雾。\n玉箫金管喧四筵，苦心不得申长句。\n昨日绣衣倾绿樽，病如桃李竟何言。\n昔骑天子大宛马，今乘款段诸侯门。\n赖遇南平豁方寸，复兼夫子持清论。\n有似山开万里云，四望青天解人闷。\n人闷还心闷，苦辛长苦辛。\n愁来饮酒二千石，寒灰重暖生阳春。\n山公醉后能骑马，别是风流贤主人。\n头陀云月多僧气，山水何曾称人意。\n不然鸣笳按鼓戏沧流，呼取江南女儿歌棹讴。\n我且为君捶碎黄鹤楼，君亦为吾倒却鹦鹉洲。\n赤壁争雄如梦里，且须歌舞宽离忧。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 206, "title": "赠钱征君少阳", "author": "李白", "body": "白玉一杯酒，绿杨三月时。\n春风馀几日，两鬓各成丝。\n秉烛惟须饮，投竿也未迟。\n如逢渭水猎，犹可帝王师。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 207, "title": "赠汪伦", "author": "李白", "body": "李白乘舟将欲行，忽闻岸上踏歌声。\n桃花潭水深千尺，不及汪伦送我情！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 208, "title": "沙丘城下寄杜甫", "author": "李白", "body": "我来竟何事？高卧沙丘城。\n城边有古树，日夕连秋声。\n鲁酒不可醉，齐歌空复情。\n思君若汶水，浩荡寄南征。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 209, "title": "闻王昌龄左迁龙标，遥有此寄", "author": "李白", "body": "杨花落尽子规啼，闻道龙标过五溪[1]。\n我寄愁心与明月，随风直到夜郎西。\n〔注〕[1]五溪：雄溪、樠溪、酉溪、潕溪、辰溪之总称，均在今湖南省西部。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 210, "title": "忆旧游寄谯郡元参军", "author": "李白", "body": "忆昔洛阳董糟丘，为余天津桥南造酒楼。\n黄金白璧买歌笑，一醉累月轻王侯。\n海内贤豪青云客，就中与君心莫逆。\n回山转海不作难，倾情倒意无所惜。\n我向淮南攀桂枝，君留洛北愁梦思。\n不忍别，还相随。\n相随迢迢访仙城，三十六曲水回萦。\n一溪初入千花明，万壑度尽松风声。\n银鞍金络到平地，汉东太守来相迎。\n紫阳之真人，邀我吹玉笙。\n餐霞楼上动仙乐，嘈然宛似鸾凤鸣。\n袖长管催欲轻举，汉东太守醉起舞。\n手持锦袍覆我身，我醉横眠枕其股。\n当筵意气凌九霄，星离雨散不终朝，分飞楚关山水遥。\n余既还山寻故巢，君亦归家渡渭桥。\n君家严君勇貔虎，作尹并州遏戎虏。\n五月相呼渡太行，摧轮不道羊肠苦。\n行来北京岁月深，感君贵义轻黄金。\n琼杯绮食青玉案，使我醉饱无归心。\n时时出向城西曲，晋祠流水如碧玉。\n浮舟弄水箫鼓鸣，微波龙鳞莎草绿。\n兴来携妓恣经过，其若杨花似雪何！\n红妆欲醉宜斜日，百尺清潭写翠娥。\n翠娥婵娟初月辉，美人更唱舞罗衣。\n清风吹歌入空去，歌曲自绕行云飞。\n此时行乐难再遇，西游因献《长杨赋》。\n北阙青云不可期，东山白首还归去。\n渭桥南头一遇君，酂台之北又离群。\n问余别恨今多少，落花春暮争纷纷。\n言亦不可尽，情亦不可及。\n呼儿长跪缄此辞，寄君千里遥相忆。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 211, "title": "寄东鲁[1]二稚子", "author": "李白", "body": "吴地桑叶绿，吴蚕已三眠[2]。\n我家寄东鲁，谁种龟阴[3]田？\n春事已不及，江行复茫然。\n南风吹归心，飞堕酒楼前。\n楼东一株桃，枝叶拂青烟。\n此树我所种，别来向三年。\n桃今与楼齐，我行尚未旋。\n娇女字平阳，折花倚桃边。\n折花不见我，泪下如流泉。\n小儿名伯禽，与姊亦齐肩。\n双行桃树下，抚背复谁怜？\n念此失次第，肝肠日忧煎。\n裂素[4]写远意，因之汶阳川。\n〔注〕[1]东鲁：李白大约在开元二十四年（736）从湖北安陆移家到东鲁衮州任城，即今山东济宁市。 [2]三眠：是说春蚕将老。蚕在蜕皮时卧而不食称眠，一般四眠就老熟结茧。[3]龟阴：即指龟山以北地区，是李白家庭所在。龟山在山东新泰县西南。 [4]素：指绢素，古代作书画用的白绢。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 212, "title": "庐山谣寄卢侍御虚舟", "author": "李白", "body": "我本楚狂人，凤歌笑孔丘。\n手持绿玉杖，朝别黄鹤楼。\n五岳寻仙不辞远，一生好入名山游。\n庐山秀出南斗旁，屏风九叠云锦张，影落明湖青黛光。\n金阙前开二峰长，银河倒挂三石梁。\n香炉瀑布遥相望，回崖沓嶂凌苍苍。\n翠影红霞映朝日，鸟飞不到吴天长。\n登高壮观天地间，大江茫茫去不还。\n黄云万里动风色，白波九道流雪山。\n好为庐山谣，兴因庐山发。\n闲窥石镜清我心，谢公行处苍苔没。\n早服还丹无世情，琴心三叠道初成。\n遥见仙人彩云里，手把芙蓉朝玉京。\n先期汗漫九垓上，愿接卢敖游太清。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 213, "title": "秋日鲁郡尧祠亭上宴别杜补阙范侍御", "author": "李白", "body": "我觉秋兴逸，谁云秋兴悲？\n山将落日去，水与晴空宜。\n鲁酒白玉壶，送行驻金羁。\n歇鞍憩古木，解带挂横枝。\n歌鼓川上亭，曲度神飙吹。\n云归碧海夕，雁没青天时。\n相失各万里，茫然空尔思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 214, "title": "梦游天姥吟留别", "author": "李白", "body": "海客谈瀛洲，烟涛微茫信难求。\n越人语天姥，云霓明灭或可睹。\n天姥连天向天横，势拔五岳掩赤城。\n天台四万八千丈，对此欲倒东南倾。\n我欲因之梦吴越，一夜飞度镜湖月。\n湖月照我影，送我至剡溪。\n谢公宿处今尚在，渌水荡漾清猿啼。\n脚著谢公屐[1]，身登青云梯。\n半壁见海日，空中闻天鸡。\n千岩万转路不定，迷花倚石忽已暝。\n熊咆龙吟殷岩泉，慄深林兮惊层巅。\n云青青兮欲雨，水澹澹兮生烟。\n列缺霹雳，丘峦崩摧。\n洞天石扉，訇然中开。\n青冥浩荡不见底，日月照耀金银台。\n霓为衣兮风为马，云之君兮纷纷而来下。\n虎鼓瑟兮鸾回车，仙之人兮列如麻。\n忽魂悸以魄动，怳惊起而长嗟。\n惟觉时之枕席，失向来之烟霞。\n世间行乐亦如此，古来万事东流水。\n别君去兮何时还，且放白鹿青崖间，须行即骑访名山。\n安能摧眉折腰事权贵，使我不得开心颜！\n〔注〕[1]谢公屐：指南朝宋谢灵运特制的登山木屐。据《南史·谢灵运传》:“寻山陟岭，必造幽峻，岩嶂数十重，莫不备尽登蹑。常着木屐，上山则去其前齿，下山则去其后齿。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 215, "title": "金陵酒肆留别", "author": "李白", "body": "风吹柳花满店香，吴姬压酒劝客尝，\n金陵子弟来相送，欲行不行各尽觞。\n请君试问东流水，别意与之谁短长？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 216, "title": "黄鹤楼送孟浩然之广陵", "author": "李白", "body": "故人西辞黄鹤楼，烟花三月下扬州。\n孤帆远影碧空尽，唯见长江天际流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 217, "title": "渡荆门送别", "author": "李白", "body": "渡远荆门外，来从楚国游。\n山随平野尽，江入大荒流。\n月下飞天镜，云生结海楼。\n仍怜故乡水，万里送行舟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 218, "title": "南陵别儿童入京", "author": "李白", "body": "白酒新熟山中归，黄鸡啄黍秋正肥。\n呼童烹鸡酌白酒，儿女嬉笑牵人衣。\n高歌取醉欲自慰，起舞落日争光辉。\n游说万乘苦不早，著鞭跨马涉远道。\n会稽愚妇轻买臣，余亦辞家西入秦。\n仰天大笑出门去，我辈岂是蓬蒿人！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 219, "title": "金乡送韦八之西京", "author": "李白", "body": "客从长安来，还归长安去。\n狂风吹我心，西挂咸阳树。\n此情不可道，此别何时遇？\n望望不见君，连山起烟雾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 220, "title": "鲁郡东石门送杜二甫", "author": "李白", "body": "醉别复几日，登临遍池台。\n何时石门路，重有金樽开？\n秋波落泗水[1]，海色明徂徕[2]。\n飞蓬各自远，且尽手中杯！\n〔注〕[1]泗水：古河名，在今山东省西南部，源出山东泗水县蒙山南麓，四源并发，故名。[2]徂徕（cúlái）：山名，在今山东省泰安市东南。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 221, "title": "灞陵行送别", "author": "李白", "body": "送君灞陵亭，灞水流浩浩。\n上有无花之古树，下有伤心之春草。\n我向秦人问路岐，云是王粲南登之古道\n古道连绵走西京，紫阙落日浮云生。\n正当今夕断肠处，骊歌愁绝不忍听。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 222, "title": "送杨山人归嵩山", "author": "李白", "body": "我有万古宅，嵩阳玉女峰。\n长留一片月，挂在东溪松。\n尔去掇仙草，菖蒲花紫茸[1]。\n岁晚或相访，青天骑白龙[2]。\n〔注〕[1]紫茸：指紫色的菖蒲花。茸，形容花娇嫩美好。此二句亦作“君行到此峰，餐霞驻衰容”。 [2]骑白龙：飞升成仙的意思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 223, "title": "送友人", "author": "李白", "body": "青山横北郭，白水绕东城。\n此地一为别，孤蓬[1]万里征。\n浮云游子意，落日故人情。\n挥手自兹去，萧萧班马鸣。\n〔注〕[1]孤蓬：飞蓬，枯后根易折，随风飞旋，诗里借喻远行的朋友。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 224, "title": "送友人入蜀", "author": "李白", "body": "见说蚕丛路[1]，崎岖不易行。\n升沉应已定，不必问君平。\n芳树笼秦栈，春流绕蜀城[2]。\n山从人面起，云傍马头生。\n〔注〕[1]蚕丛路：蚕丛，是传说中蜀国的开国君王。蚕丛路，代称入蜀的道路。 [2]春流：泛指春天水涨，江水奔流。一说指流经成都的都江堰内江。蜀城：指成都。一说泛指蜀中城市。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 225, "title": "宣州谢朓楼饯别校书叔云", "author": "李白", "body": "弃我去者昨日之日不可留，\n乱我心者今日之日多烦忧。\n长风万里送秋雁，对此可以酣高楼。\n蓬莱文章建安骨，中间小谢又清发。\n俱怀逸兴壮思飞，欲上青天揽明月。\n抽刀断水水更流，举杯销愁愁更愁。\n人生在世不称意，明朝散发弄扁舟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 226, "title": "山中问答", "author": "李白", "body": "问余何意栖碧山，笑而不答心自闲。\n桃花流水窅然[1]去，别有天地非人间。\n〔注〕[1]窅（yǎo）然：远去貌。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 227, "title": "答王十二寒夜独酌有怀", "author": "李白", "body": "昨夜吴中雪，子猷佳兴发。\n万里浮云卷碧山，青天中道流孤月。\n孤月沧浪河汉清，北斗错落长庚明。\n怀余对酒夜霜白，玉床金井冰峥嵘。\n人生飘忽百年内，且须酣畅万古情。\n君不能狸膏金距[1]学斗鸡，坐令鼻息吹虹霓。\n君不能学哥舒，横行青海夜带刀，西屠石堡取紫袍。\n吟诗作赋北窗里，万言不值一杯水。\n世人闻此皆掉头，有如东风射马耳。\n鱼目亦笑我，谓与明月同。\n骅骝拳跼不能食，蹇驴得志鸣春风。\n《折杨》、《黄华》合流俗，晋君听琴枉《清角》[2]。\n《巴人》谁肯和《阳春》，楚地犹来贱奇璞。\n黄金散尽交不成，白首为儒身被轻。\n一谈一笑失颜色，苍蝇贝锦喧谤声。\n曾参岂是杀人者？谗言三及慈母惊。\n与君论心握君手，荣辱于余亦何有？\n孔圣犹闻伤凤麟，董龙[3]更是何鸡狗！\n一生傲岸苦不谐，恩疏媒劳志多乖。\n严陵高揖汉天子，何必长剑拄颐事玉阶。\n达亦不足贵，穷亦不足悲。\n韩信羞将绛灌比，祢衡耻逐屠沽儿。\n君不见李北海，英风豪气今何在！\n君不见裴尚书，土坟三尺蒿棘居！\n少年早欲五湖去，见此弥将钟鼎疏。\n〔注〕[1]狸膏：狐狸油。狸善捕食鸡，以狸膏涂鸡头，能使对方的鸡闻而胆怯。金距：距为鸡爪，鸡爪上装以金属芒刺，使之锋利。 [2]清角：相传为黄帝所制曲调，其声悲壮，只能演奏给有才德的人听。《韩非子·十过》载，春秋时晋平公德薄，却强迫师旷为他演奏，结果风雨大作，裂帏破幕，平公受惊得病，晋国大旱三年。 [3]董龙：前秦主苻生的宠臣董荣，小字龙，奸诈凶狠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 228, "title": "东鲁门泛舟二首（其一）", "author": "李白", "body": "日落沙明天倒开，波摇石动水萦回。\n轻舟泛月寻溪转，疑是山阴雪后来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 229, "title": "下终南山过斛斯山人宿置酒", "author": "李白", "body": "暮从碧山下，山月随人归。\n却顾所来径，苍苍横翠微。\n相携及田家，童稚开荆扉。\n绿竹入幽径，青萝拂行衣。\n欢言得所憩，美酒聊共挥。\n长歌吟松风，曲尽河星稀。\n我醉君复乐，陶然共忘机。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 230, "title": "把酒问月", "author": "李白", "body": "青天有月来几时？我今停杯一问之。\n人攀明月不可得，月行却与人相随。\n皎如飞镜临丹阙，绿烟灭尽清辉发。\n但见宵从海上来，宁知晓向云间没？\n白兔捣药秋复春，嫦娥孤栖与谁邻？\n今人不见古时月，今月曾经照古人。\n古人今人若流水，共看明月皆如此。\n唯愿当歌对酒时，月光长照金樽里。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 231, "title": "陪侍郎叔游洞庭醉后三首（其三）", "author": "李白", "body": "刬却君山好，平铺湘水流。\n巴陵无限酒，醉杀洞庭秋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 232, "title": "陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首（其二）", "author": "李白", "body": "南湖秋水夜无烟，耐可乘流直上天？\n且就洞庭赊月色，将船买酒白云边。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 233, "title": "登太白峰", "author": "李白", "body": "西上太白峰，夕阳穷登攀。\n太白[1]与我语，为我开天关[2]。\n愿乘泠风去，直出浮云间。\n举手可近月，前行若无山。\n一别武功[3]去，何时复更还？\n〔注〕[1]太白：这里指太白星。 [2]天关：星名。《宋史·天文志》:“东方：角宿二星为天关，其间天门也，其内天庭也。故黄道经其中，七曜之所行也。”诗里指想象中的天界门户。[3]武功：这里指武功山。太白山“南连武功山”（见《水经注·渭水》）。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 234, "title": "登金陵凤凰台", "author": "李白", "body": "凤凰台上凤凰游，凤去台空江自流。\n吴宫花草埋幽径，晋代衣冠成古丘。\n三山半落青天外，一水中分白鹭洲[1]。\n总为浮云能蔽日，长安不见使人愁。\n〔注〕[1]此句一作“二水中分白鹭洲”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 235, "title": "望庐山瀑布", "author": "李白", "body": "日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 236, "title": "与夏十二登岳阳楼", "author": "李白", "body": "楼观岳阳尽，川迥洞庭开。\n雁引愁心去，山衔好月来。\n云间连下榻，天上接行杯。\n醉后凉风起，吹人舞袖回。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 237, "title": "秋登宣城谢朓北楼", "author": "李白", "body": "江城[1]如画里，山晚望晴空。\n两水夹明镜，双桥落彩虹。\n人烟寒橘柚，秋色老梧桐。\n谁念北楼上，临风怀谢公。\n〔注〕[1]江城：泛指水边的城。“江”并不是实说长江。唐时江南地区的口语，无论大水小水都称之为“江”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 238, "title": "望天门山", "author": "李白", "body": "天门中断楚江开，碧水东流至此回。\n两岸青山相对出，孤帆一片日边来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 239, "title": "客中作[1]", "author": "李白", "body": "兰陵美酒郁金香[2]，玉碗盛来琥珀光[3]。\n但使主人能醉客，不知何处是他乡。\n〔注〕[1]题一作《客中行》。 [2]兰陵：今山东枣庄市。郁金香：一种香草。古人用以浸酒，浸后酒带金黄色。 [3]琥珀：一种树脂化石，呈黄色或赤褐色，色泽晶莹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 240, "title": "夜下征虏亭", "author": "李白", "body": "船下广陵去，月明征虏亭。\n山花如绣颊，江火似流萤。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 241, "title": "早发白帝城[1]", "author": "李白", "body": "朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。\n〔注〕[1]白帝城：古城名，在今重庆市奉节东白帝山上。东汉初公孙述筑城，其自号白帝，故以为名。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 242, "title": "秋下荆门", "author": "李白", "body": "霜落荆门江树空，布帆无恙挂秋风。\n此行不为鲈鱼鲙，自爱名山入剡中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 243, "title": "宿五松山下荀媪家", "author": "李白", "body": "我宿五松下，寂寥无所欢。\n田家秋作苦，邻女夜舂寒。\n跪进雕胡饭，月光明素盘。\n令人惭漂母，三谢不能餐。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 244, "title": "越中览古", "author": "李白", "body": "越王勾践破吴归，战士还家尽锦衣。\n宫女如花满春殿，只今惟有鹧鸪飞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 245, "title": "经下邳圯桥怀张子房", "author": "李白", "body": "子房未虎啸，破产不为家。\n沧海得壮士，椎秦博浪沙。\n报韩虽不成，天地皆振动。\n潜匿游下邳，岂曰非智勇？\n我来圯桥上，怀古钦英风。\n唯见碧流水，曾无黄石公。\n叹息此人去，萧条徐泗空。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 246, "title": "望鹦鹉洲悲祢衡", "author": "李白", "body": "魏帝营八极，蚁观一祢衡。\n黄祖斗筲人，杀之受恶名。\n吴江赋《鹦鹉》，落笔超群英。\n锵锵振金玉，句句欲飞鸣。\n鸷鹗啄孤凤，千春伤我情。\n五岳起方寸，隐然讵可平？\n才高竟何施，寡识冒天刑。\n至今芳洲上，兰蕙不忍生。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 247, "title": "谢公亭", "author": "李白", "body": "谢亭离别处，风景每生愁。\n客散青天月，山空碧水流。\n池花春映日，窗竹夜鸣秋。\n今古一相接，长歌怀旧游。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 248, "title": "夜泊牛渚怀古", "author": "李白", "body": "牛渚西江夜，青天无片云。\n登舟望秋月，空忆谢将军。\n余亦能高咏，斯人不可闻。\n明朝挂帆席，枫叶落纷纷。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 249, "title": "月下独酌四首（其一）", "author": "李白", "body": "花间一壶酒，独酌无相亲。\n举杯邀明月，对影成三人。\n月既不解饮，影徒随我身。\n暂伴月将影，行乐须及春。\n我歌月徘徊，我舞影零乱。\n醒时同交欢，醉后各分散。\n永结无情游，相期邈云汉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 250, "title": "山中与幽人对酌", "author": "李白", "body": "两人对酌山花开，一杯一杯复一杯。\n我醉欲眠卿且去，明朝有意抱琴来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 251, "title": "与史郎中钦听黄鹤楼上吹笛", "author": "李白", "body": "一为迁客去长沙，西望长安不见家。\n黄鹤楼中吹玉笛，江城五月《落梅花》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 252, "title": "独坐敬亭山", "author": "李白", "body": "众鸟高飞尽，孤云独去闲。\n相看两不厌，只有敬亭山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 253, "title": "访戴天山道士不遇", "author": "李白", "body": "犬吠水声中，桃花带露浓。\n树深时见鹿，溪午不闻钟。\n野竹分青霭，飞泉挂碧峰。\n无人知所去，愁倚两三松。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 254, "title": "忆东山二首（其一）", "author": "李白", "body": "不向东山久，蔷薇几度花。\n白云还自散，明月落谁家？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 255, "title": "拟古十二首（其九）", "author": "李白", "body": "生者为过客，死者为归人[1]。\n天地一逆旅，同悲万古尘。\n月兔空捣药，扶桑已成薪。\n白骨寂无言，青松岂知春。\n前后更叹息，浮荣何足珍？\n〔注〕[1]归人：《列子·天瑞篇》:“古者谓死人为归人。夫言死人为归人，则生人为行人矣。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 256, "title": "翰林读书言怀呈集贤诸学士", "author": "李白", "body": "晨趋紫禁中，夕待金门诏。\n观书散遗帙，探古穷至妙。\n片言苟会心，掩卷忽而笑。\n青蝇易相点，《白雪》难同调。\n本是疏散人，屡贻褊促诮。\n云天属清朗，林壑忆游眺。\n或时清风来，闲倚栏下啸。\n严光桐庐溪，谢客临海峤。\n功成谢人间，从此一投钓。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 257, "title": "听蜀僧濬弹琴", "author": "李白", "body": "蜀僧抱绿绮，西下峨眉峰。\n为我一挥手，如听万壑松。\n客心洗流水，馀响入霜钟。\n不觉碧山暮，秋云暗几重。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 258, "title": "劳劳亭", "author": "李白", "body": "天下伤心处，劳劳送客亭。\n春风知别苦，不遣柳条青。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 259, "title": "春夜洛城闻笛", "author": "李白", "body": "谁家玉笛暗飞声，散入春风满洛城。\n此夜曲中闻折柳，何人不起故园情！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 260, "title": "长门怨二首", "author": "李白", "body": "天回北斗挂西楼，金屋无人萤火流。\n月光欲到长门殿，别作深宫一段愁。\n桂殿长愁不记春，黄金四屋起秋尘。\n夜悬明镜青天上，独照长门宫里人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 261, "title": "哭晁卿衡", "author": "李白", "body": "日本晁卿辞帝都，征帆一片绕蓬壶。\n明月不归沉碧海，白云愁色满苍梧。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 262, "title": "哭宣城善酿纪叟[1]", "author": "李白", "body": "纪叟黄泉里，还应酿老春。\n夜台无李白[2]，沽酒与何人？\n〔注〕[1]题一作《题戴老酒店》，诗云：“戴老黄泉下，还应酿大春。夜台无李白，沽酒与何人？” [2]此句原作“夜台无晓日”，今改从《题戴老酒店》句。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 263, "title": "阙题", "author": "刘眘虚", "body": "道由白云尽，春与青溪长。\n时有落花至，远随流水香。\n闲门向山路，深柳读书堂。\n幽映每白日，清辉照衣裳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 264, "title": "次北固山下", "author": "王湾", "body": "客路青山外，行舟绿水前。\n潮平两岸阔，风正一帆悬。\n海日生残夜，江春入旧年。\n乡书何处达，归雁洛阳边。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 265, "title": "黄鹤楼", "author": "崔颢", "body": "昔人已乘黄鹤去，此地空馀黄鹤楼。\n黄鹤一去不复返，白云千载空悠悠。\n晴川历历汉阳树，芳草萋萋鹦鹉洲。\n日暮乡关何处是？烟波江上使人愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 266, "title": "长干曲四首（其一、其二）", "author": "崔颢", "body": "君家何处住？妾住在横塘。\n停舟暂借问，或恐是同乡。\n家临九江水，来去九江侧。\n同是长干人，生小不相识。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 267, "title": "行经华阴", "author": "崔颢", "body": "岧峣太华俯咸京，天外三峰削不成。\n武帝祠前云欲散，仙人掌上雨初晴。\n河山北枕秦关险，驿路西连汉畤平。\n借问路旁名利客，何如此处学长生？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 268, "title": "宿云门寺阁", "author": "孙逖", "body": "香阁东山下，烟花象外幽。\n悬灯千嶂夕，卷幔五湖秋。\n画壁馀鸿雁，纱窗宿斗牛。\n更疑天路近，梦与白云游。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 269, "title": "怨词二首（其一）", "author": "崔国辅", "body": "妾有罗衣裳，秦王在时作。\n为舞春风多，秋来不堪著。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 270, "title": "采莲曲", "author": "崔国辅", "body": "玉溆花争发，金塘水乱流。\n相逢畏相失，并著木兰舟[1]。\n〔注〕[1]《述异记》:“木兰舟在浔阳江中，多木兰树；昔吴王阖闾植木兰于此，用构宫殿也。七里洲中，有鲁班刻木兰为舟，舟至今在洲中；诗家云木兰舟，出于此。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 271, "title": "小长干曲", "author": "崔国辅", "body": "月暗送湖风，相寻路不通。\n菱歌唱不彻，知在此塘中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 272, "title": "凉州词", "author": "王翰", "body": "葡萄美酒夜光杯，欲饮琵琶马上催。\n醉卧沙场君莫笑，古来征战几人回。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 273, "title": "山中留客", "author": "张旭", "body": "山光物态弄春晖，莫为轻阴便拟归。\n纵使晴明无雨色，入云深处亦沾衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 274, "title": "移家别湖上亭", "author": "戎昱", "body": "好是春风湖上亭，柳条藤蔓系离情。\n黄莺久住浑相识，欲别频啼四五声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 275, "title": "咏史", "author": "戎昱", "body": "汉家青史上，计拙是和亲。\n社稷依明主，安危托妇人。\n岂能将玉貌，便拟静胡尘。\n地下千年骨，谁为辅佐臣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 276, "title": "桂州腊夜", "author": "戎昱", "body": "坐到三更尽，归仍万里赊。\n雪声偏傍竹，寒梦不离家。\n晓角分残漏，孤灯落碎花。\n二年随骠骑，辛苦向天涯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 277, "title": "早梅", "author": "戎昱", "body": "一树寒梅白玉条，迥临村路傍溪桥。\n不知近水花先发，疑是经冬雪未销。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 278, "title": "燕歌行", "author": "高適", "body": "开元二十六年，客有从御史大夫张公出塞而还者，作《燕歌行》以示適，感征戍之事，因而和焉。\n汉家烟尘在东北，汉将辞家破残贼。\n男儿本自重横行，天子非常赐颜色。\n摐金伐鼓下榆关，旌旆逶迤碣石间。\n校尉羽书飞瀚海，单于猎火照狼山。\n山川萧条极边土，胡骑凭陵杂风雨。\n战士军前半死生，美人帐下犹歌舞！\n大漠穷秋塞草腓，孤城落日斗兵稀。\n身当恩遇恒轻敌，力尽关山未解围。\n铁衣远戍辛勤久，玉箸应啼别离后。\n少妇城南欲断肠，征人蓟北空回首。\n边庭飘飖那可度，绝域苍茫更何有！\n杀气三时作阵云，寒声一夜传刁斗。\n相看白刃血纷纷，死节从来岂顾勋？\n君不见沙场征战苦，至今犹忆李将军！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 279, "title": "人日寄杜二拾遗[1]", "author": "高適", "body": "人日题诗寄草堂，遥怜故人思故乡。\n柳条弄色不忍见，梅花满枝空断肠！\n身在南蕃无所预，心怀百忧复千虑。\n今年人日空相忆，明年人日知何处？\n一卧东山三十春，岂知书剑老风尘。\n龙钟还忝二千石，愧尔东西南北人！\n〔注〕[1]人日：农历正月初七。杜二：杜甫。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 280, "title": "封丘作", "author": "高適", "body": "我本渔樵孟诸野，一生自是悠悠者。\n乍可狂歌草泽中，宁堪作吏风尘下？\n只言小邑无所为，公门百事皆有期。\n拜迎长官心欲碎，鞭挞黎庶令人悲。\n悲来向家问妻子，举家尽笑今如此。\n生事应须南亩田，世情尽付东流水。\n梦想旧山安在哉，为衔君命日迟回。\n乃知梅福徒为尔，转忆陶潜归去来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 281, "title": "别韦参军", "author": "高適", "body": "二十解书剑，西游长安城。\n举头望君门，屈指取公卿。\n国风冲融迈三五，朝廷礼乐弥寰宇。\n白璧皆言赐近臣，布衣不得干明主。\n归来洛阳无负郭[1]，东过梁宋非吾土。\n兔苑为农岁不登，雁池垂钓心长苦。\n世人遇我同众人，惟君于我最相亲。\n且喜百年见交态，未尝一日辞家贫。\n弹棋击筑白日晚，纵酒高歌杨柳春。\n欢娱未尽分散去，使我惆怅惊心神。\n丈夫不作儿女别，临岐涕泪沾衣巾。\n〔注〕[1]负郭：指近郊的良田沃土。《史记·苏秦列传》说：“且使我有雒（洛）阳负郭田二顷，吾岂能佩六国相印乎？”诗中洛阳代指诗人的故乡（河北景县）。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 282, "title": "赋得还山吟送沈四山人", "author": "高適", "body": "还山吟，天高日暮寒山深，送君还山识君心。\n人生老大须恣意，看君解作一生事。\n山间偃仰无不至，石泉淙淙若风雨，桂花松子常满地。\n卖药囊中应有钱，还山服药又长年。\n白云[1]劝尽杯中物，明月相随何处眠？\n眠时忆问醒时事，梦魂可以相周旋。\n〔注〕[1]白云：用南朝齐梁人陶弘景故事。陶弘景隐于句曲山，齐高帝萧道成有诏问他：“山中何所有？”他作诗答道：“山中何所有？岭上多白云。只可自怡悦，不堪持赠君。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 283, "title": "营州歌", "author": "高適", "body": "营州少年厌[1]原野，狐裘蒙茸猎城下。\n虏酒千钟不醉人，胡儿十岁能骑马。\n〔注〕[1]厌：同“餍”，饱。这里作饱经、习惯于之意。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 284, "title": "别董大二首（其一）", "author": "高適", "body": "千里黄云白日曛，北风吹雁雪纷纷。\n莫愁前路无知己，天下谁人不识君？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 285, "title": "塞上听吹笛", "author": "高適", "body": "雪净胡天牧马还，月明羌笛戍楼间。\n借问梅花何处落，风吹一夜满关山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 286, "title": "除夜作", "author": "高適", "body": "旅馆寒灯独不眠，客心何事转凄然？\n故乡今夜思千里，霜鬓明朝又一年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 287, "title": "听张立本女吟", "author": "无名氏", "body": "危冠广袖楚宫妆，独步闲庭逐夜凉。\n自把玉钗敲砌竹，清歌一曲月如霜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 288, "title": "钓鱼湾", "author": "储光羲", "body": "垂钓绿湾春，春深杏花乱。\n潭清疑水浅，荷动知鱼散。\n日暮待情人，维舟绿杨岸。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 289, "title": "江南曲四首（其三）", "author": "储光羲", "body": "日暮长江里，相邀归渡头。\n落花如有意，来去逐轻舟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 290, "title": "同王徵君湘中有怀", "author": "张谓", "body": "八月洞庭秋，潇湘水北流。\n还家万里梦，为客五更愁。\n不用开书帙，偏宜上酒楼。\n故人京洛满，何日复同游？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 291, "title": "题长安壁主人", "author": "张谓", "body": "世人结交须黄金，黄金不多交不深。\n纵令然诺暂相许，终是悠悠行路心。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 292, "title": "五日观妓[1]", "author": "万楚", "body": "西施谩道浣春纱，碧玉今时斗丽华。\n眉黛夺将萱草色，红裙妒杀石榴花。\n新歌一曲令人艳，醉舞双眸敛鬓斜。\n谁道五丝能续命，却知今日死君家。\n〔注〕[1]妓：歌舞女艺人。这里指乐伎。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 293, "title": "逢雪宿芙蓉山主人", "author": "刘长卿", "body": "日暮苍山远，天寒白屋贫。\n柴门闻犬吠，风雪夜归人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 294, "title": "听弹琴", "author": "刘长卿", "body": "泠泠七弦上，静听松风寒。\n古调虽自爱，今人多不弹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 295, "title": "送灵澈上人", "author": "刘长卿", "body": "苍苍竹林寺，杳杳钟声晚。\n荷笠带夕阳，青山独归远。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 296, "title": "穆陵关北逢人归渔阳", "author": "刘长卿", "body": "逢君穆陵路，匹马向桑乾。\n楚国苍山古，幽州白日寒。\n城池百战后，耆旧几家残。\n处处蓬蒿遍，归人掩泪看。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 297, "title": "余干旅舍", "author": "刘长卿", "body": "摇落暮天迥，青枫霜叶稀。\n孤城向水闭，独鸟背人飞。\n渡口月初上，邻家渔未归。\n乡心正欲绝，何处捣寒衣？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 298, "title": "饯别王十一南游", "author": "刘长卿", "body": "望君烟水阔，挥手泪沾巾。\n飞鸟没何处，青山空向人。\n长江一帆远，落日五湖春[1]。\n谁见汀洲上，相思愁白蘋。\n〔注〕[1]“落日”以下三句：出自梁代柳恽的《江南曲》。其诗为：“汀洲采白蘋，落日江南春。洞庭有归客，潇湘逢故人。故人何不返，春花复应晚。不道新知乐，只言行路难。”汀洲：水中或水边平地。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 299, "title": "重送裴郎中贬吉州", "author": "刘长卿", "body": "猿啼客散暮江头，人自伤心水自流。\n同作逐臣君更远，青山万里一孤舟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 300, "title": "酬李穆见寄", "author": "刘长卿", "body": "孤舟相访至天涯，万转云山路更赊。\n欲扫柴门迎远客，青苔黄叶满贫家。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 301, "title": "长沙过贾谊宅", "author": "刘长卿", "body": "三年谪宦此栖迟，万古惟留楚客悲。\n秋草独寻人去后，寒林空见日斜时。\n汉文有道恩犹薄，湘水无情吊岂知？\n寂寂江山摇落处，怜君何事到天涯！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 302, "title": "登余干古县城", "author": "刘长卿", "body": "孤城上与白云齐，万古荒凉楚水西。\n官舍已空秋草没，女墙犹在夜乌啼。\n平沙渺渺迷人远，落日亭亭向客低。\n飞鸟不知陵谷变，朝来暮去弋阳溪。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 303, "title": "送严士元[1]", "author": "刘长卿", "body": "春风倚棹阖闾城，水国春寒阴复晴。\n细雨湿衣看不见，闲花落地听无声。\n日斜江上孤帆影，草绿湖南万里情。\n君去若逢相识问[2]，青袍今已误儒生。\n〔注〕[1]诗题一作《别严士元》。《文苑英华》卷二七〇作《送严员外》，《中兴间气集》卷下作《送郎士元》，《唐诗纪事》卷廿六作《送严士元》，《全唐诗》卷二〇七李嘉祐名下亦收此诗，题亦作《送严员外》，因此定为送行之作。 [2]君去：一作“东道”。此据《文苑英华》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 304, "title": "寄校书七兄", "author": "李冶", "body": "无事乌程县，蹉跎岁月馀。\n不知芸阁吏，寂寞竟何如？\n远水浮仙棹，寒星伴使车。\n因过大雷岸，莫忘几行书。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 305, "title": "望岳", "author": "杜甫", "body": "岱宗夫如何？齐鲁青未了。\n造化钟神秀，阴阳割昏晓。\n荡胸生层云，决眦入归鸟。\n会当凌绝顶，一览众山小。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 306, "title": "题张氏隐居二首（其二）", "author": "杜甫", "body": "之子时相见，邀人晚兴留。\n霁潭鳣发发，春草鹿呦呦。\n杜酒偏劳劝，张梨不外求。\n前村山路险，归醉每无愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 307, "title": "房兵曹胡马", "author": "杜甫", "body": "胡马大宛名，锋棱瘦骨成。\n竹批双耳峻，风入四蹄轻。\n所向无空阔，真堪托死生。\n骁腾有如此，万里可横行。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 308, "title": "画鹰", "author": "杜甫", "body": "素练风霜起，苍鹰画作殊。\n身思狡兔，侧目似愁胡。\n绦镟光堪摘，轩楹势可呼。\n何当击凡鸟，毛血洒平芜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 309, "title": "奉赠韦左丞丈二十二韵", "author": "杜甫", "body": "纨袴不饿死，儒冠多误身。\n丈人试静听，贱子请具陈：\n甫昔少年日，早充观国宾[1]。\n读书破万卷，下笔如有神。\n赋料扬雄敌，诗看子建亲。\n李邕求识面，王翰愿卜邻。\n自谓颇挺出，立登要路津。\n致君尧舜上，再使风俗淳。\n此意竟萧条，行歌非隐沦。\n骑驴十三载，旅食京华春。\n朝扣富儿门，暮随肥马尘。\n残杯与冷炙，到处潜悲辛。\n主上顷见征，歘然欲求伸。\n青冥却垂翅，蹭蹬无纵鳞。\n甚愧丈人厚，甚知丈人真。\n每于百僚上，猥诵佳句新[2]。\n窃效贡公喜，难甘原宪贫。\n焉能心怏怏？只是走踆踆[3]。\n今欲东入海，即将西去秦[4]。\n尚怜终南山，回首清渭滨[5]。\n常拟报一饭[6]，况怀辞大臣。\n白鸥没浩荡，万里谁能驯！\n〔注〕[1]“甫昔”二句：指开元二十三年（735）杜甫二十四岁在洛阳参加进士考试一事。观国宾：是说自己有幸看到国朝文物之盛，当时还只是一个在野的宾客。《周易·观卦·象辞》:“观国之光尚宾也。” [2]猥：承蒙。诵佳句：指吟诵杜甫的诗，用意在宣扬推荐。 [3]踆踆（cún）：进退两难的样子。 [4]东入海：指避世隐居。《论语·公冶长》记孔子语：“道不行，乘桴浮于海。”西去秦：离开西方的秦地（指京城长安）。 [5]终南山：在长安城南。渭水：在长安城北。二地也都指代长安。 [6]报一饭：《史记·范雎传》:“一饭之恩必报。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 310, "title": "同诸公登慈恩寺塔", "author": "杜甫", "body": "高标跨苍穹，烈风无时休。\n自非旷士怀，登兹翻百忧。\n方知象教力，足可追冥搜。\n仰穿龙蛇窟，始出枝撑幽。\n七星在北户，河汉声西流。\n羲和鞭白日，少昊行清秋。\n秦山忽破碎，泾渭不可求。\n俯视但一气，焉能辨皇州？\n回首叫虞舜，苍梧云正愁。\n惜哉瑶池饮，日晏昆仑丘。\n黄鹄去不息，哀鸣何所投？\n君看随阳雁，各有稻粱谋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 311, "title": "兵车行", "author": "杜甫", "body": "车辚辚，马萧萧，行人弓箭各在腰。\n耶娘妻子走相送，尘埃不见咸阳桥。\n牵衣顿足拦道哭，哭声直上干云霄。\n道旁过者问行人，行人但云点行频。\n或从十五北防河，便至四十西营田；\n去时里正与裹头，归来头白还戍边。\n边庭流血成海水，武皇开边意未已。\n君不闻汉家山东二百州，千村万落生荆杞。\n纵有健妇把锄犁，禾生陇亩无东西。\n况复秦兵耐苦战，被驱不异犬与鸡。\n长者虽有问，役夫敢申恨？\n且如今年冬，未休关西卒。\n县官急索租，租税从何出？\n信知生男恶，反是生女好；\n生女犹得嫁比邻，生男埋没随百草！\n君不见青海头，古来白骨无人收。\n新鬼烦冤旧鬼哭，天阴雨湿声啾啾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 312, "title": "饮中八仙歌", "author": "杜甫", "body": "知章骑马似乘船，眼花落井水底眠。\n汝阳三斗始朝天，道逢麯车口流涎，恨不移封向酒泉。\n左相日兴费万钱，饮如长鲸吸百川，衔杯乐圣称避贤。\n宗之潇洒美少年，举觞白眼望青天，皎如玉树临风前。\n苏晋长斋绣佛前，醉中往往爱逃禅。\n李白一斗诗百篇，长安市上酒家眠。\n天子呼来不上船，自称臣是酒中仙。\n张旭三杯草圣传，脱帽露顶王公前，挥毫落纸如云烟。\n焦遂五斗方卓然，高谈雄辩惊四筵。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 313, "title": "春日忆李白", "author": "杜甫", "body": "白也诗无敌，飘然思不群。\n清新庾开府，俊逸鲍参军。\n渭北春天树，江东日暮云。\n何时一樽酒，重与细论文[1]？\n〔注〕[1]论文：六朝时有所谓文笔之分，把无韵的文章称为笔，把有韵的作品称为文。这里“论文”，也即论诗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 314, "title": "前出塞九首（其六）", "author": "杜甫", "body": "挽弓当挽强，用箭当用长。\n射人先射马，擒贼先擒王。\n杀人亦有限，列国自有疆。\n苟能制侵陵，岂在多杀伤？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 315, "title": "丽人行", "author": "杜甫", "body": "三月三日天气新，长安水边多丽人。\n态浓意远淑且真，肌理细腻骨肉匀。\n绣罗衣裳照暮春，蹙金孔雀银麒麟。\n头上何所有？翠为㔩叶垂鬓唇。\n背后何所见？珠压腰衱稳称身。\n就中云幕椒房亲，赐名大国虢与秦。\n紫驼之峰出翠釜，水精之盘行素鳞。\n犀箸厌饫久未下，鸾刀缕切空纷纶。\n黄门飞鞚不动尘，御厨络绎送八珍。\n箫鼓哀吟感鬼神，宾从杂遝实要津。\n后来鞍马何逡巡，当轩下马入锦茵。\n杨花雪落覆白苹，青鸟飞去衔红巾。\n炙手可热势绝伦，慎莫近前丞相嗔！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 316, "title": "贫交行", "author": "杜甫", "body": "翻手为云覆手雨，纷纷轻薄何须数。\n君不见管鲍贫时交，此道今人弃如土。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 317, "title": "醉时歌", "author": "杜甫", "body": "诸公衮衮登台省，广文先生官独冷。\n甲第纷纷厌粱肉，广文先生饭不足。\n先生有道出羲皇，先生有才过屈宋。\n德尊一代常坎坷，名垂万古知何用！\n杜陵野客人更嗤，被褐短窄鬓如丝。\n日籴太仓五升米，时赴郑老同襟期。\n得钱即相觅，沽酒不复疑。\n忘形到尔汝，痛饮真吾师。\n清夜沉沉动春酌，灯前细雨檐花落。\n但觉高歌有鬼神，焉知饿死填沟壑。\n相如逸才亲涤器，子云识字终投阁。\n先生早赋《归去来》，石田茅屋荒苍苔。\n儒术于我何有哉？孔丘盗跖俱尘埃！\n不须闻此意惨怆，生前相遇且衔杯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 318, "title": "后出塞五首（其二）", "author": "杜甫", "body": "朝进东门营，暮上河阳桥。\n落日照大旗，马鸣风萧萧。\n平沙列万幕，部伍各见招。\n中天悬明月，令严夜寂寥。\n悲笳数声动，壮士惨不骄。\n借问大将谁，恐是霍嫖姚。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 319, "title": "自京赴奉先县咏怀五百字", "author": "杜甫", "body": "杜陵有布衣，老大意转拙。\n许身一何愚，窃比稷与契。\n居然成濩落，白首甘契阔。\n盖棺事则已，此志常觊豁。\n穷年忧黎元，叹息肠内热。\n取笑同学翁，浩歌弥激烈。\n非无江海志，潇洒送日月。\n生逢尧舜君，不忍便永诀。\n当今廊庙具，构厦岂云缺？\n葵藿倾太阳，物性固难夺。\n顾惟蝼蚁辈，但自求其穴。\n胡为慕大鲸，辄拟偃溟渤？\n以兹误生理，独耻事干谒。\n兀兀遂至今，忍为尘埃没。\n终愧巢与由，未能易其节。\n沈饮聊自遣，放歌破愁绝。\n岁暮百草零，疾风高冈裂。\n天衢阴峥嵘，客子中夜发。\n霜严衣带断，指直不得结。\n凌晨过骊山，御榻在嵽嵲。\n蚩尤塞寒空，蹴踏崖谷滑。\n瑶池气郁律，羽林相摩戛。\n君臣留欢娱，乐动殷胶葛。\n赐浴皆长缨，与宴非短褐。\n彤庭所分帛，本自寒女出。\n鞭挞其夫家，聚敛贡城阙。\n圣人筐篚恩，实欲邦国活。\n臣如忽至理，君岂弃此物？\n多士盈朝廷，仁者宜战栗。\n况闻内金盘，尽在卫霍室。\n中堂有神仙，烟雾蒙玉质。\n煖客貂鼠裘，悲管逐清瑟。\n劝客驼蹄羹，霜橙压香橘。\n朱门酒肉臭，路有冻死骨。\n荣枯咫尺异，惆怅难再述。\n北辕就泾渭，官渡又改辙。\n群冰从西下，极目高崒兀。\n疑是崆峒来，恐触天柱折。\n河梁幸未坼，枝撑声窸窣。\n行李相攀援，川广不可越。\n老妻寄异县，十口隔风雪。\n谁能久不顾，庶往共饥渴。\n入门闻号咷，幼子饿已卒。\n吾宁舍一哀，里巷亦呜咽。\n所愧为人父，无食致夭折。\n岂知秋禾登，贫窭有仓卒。\n生常免租税，名不隶征伐。\n抚迹犹酸辛，平人固骚屑。\n默思失业徒，因念远戍卒。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 320, "title": "月夜", "author": "杜甫", "body": "今夜鄜州月，闺中只独看。\n遥怜小儿女，未解忆长安。\n香雾云鬟湿，清辉玉臂寒。\n何时倚虚幌，双照泪痕干？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 321, "title": "悲陈陶", "author": "杜甫", "body": "孟冬十郡良家子，血作陈陶泽中水。\n野旷天清无战声，四万义军同日死。\n群胡归来血洗箭，仍唱胡歌饮都市。\n都人回面向北啼，日夜更望官军至。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 322, "title": "对雪", "author": "杜甫", "body": "战哭多新鬼，愁吟独老翁。\n乱云低薄暮，急雪舞回风。\n瓢弃樽无绿，炉存火似红。\n数州消息断，愁坐正书空。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 323, "title": "春望", "author": "杜甫", "body": "国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 324, "title": "哀江头", "author": "杜甫", "body": "少陵野老[1]吞声哭，春日潜行曲江曲。\n江头宫殿锁千门，细柳新蒲为谁绿？\n忆昔霓旌下南苑，苑中万物生颜色。\n昭阳殿里第一人，同辇随君侍君侧。\n辇前才人带弓箭，白马嚼啮黄金勒。\n翻身向天仰射云，一笑正坠双飞翼。\n明眸皓齿今何在？血污游魂归不得。\n清渭东流剑阁深，去住彼此无消息！\n人生有情泪沾臆，江水江花岂终极？\n黄昏胡骑尘满城，欲往城南望城北[2]。\n〔注〕[1]少陵：在长安城东南，杜甫曾在这一带住过，故自称“少陵野老”。 [2]望城北：即“向城北”。宋陆游《老学庵笔记》云：“北人谓‘向’为‘望’。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 325, "title": "喜达行在所三首（其二）", "author": "杜甫", "body": "愁思胡笳夕，凄凉汉苑春。\n生还今日事，间道暂时人。\n司隶章初睹，南阳气已新。\n喜心翻倒极，呜咽泪沾巾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 326, "title": "北征", "author": "杜甫", "body": "皇帝二载秋，闰八月初吉。\n杜子将北征，苍茫问家室。\n维时遭艰虞，朝野少暇日。\n顾惭恩私被，诏许归蓬荜。\n拜辞诣阙下，怵惕久未出。\n虽乏谏诤姿，恐君有遗失。\n君诚中兴主，经纬固密勿。\n东胡反未已，臣甫愤所切。\n挥涕恋行在，道途犹恍惚。\n乾坤含疮痍，忧虞何时毕！\n靡靡逾阡陌，人烟眇萧瑟。\n所遇多被伤，呻吟更流血。\n回首凤翔县，旌旗晚明灭。\n前登寒山重，屡得饮马窟。\n邠郊入地底，泾水中荡潏。\n猛虎立我前，苍崖吼时裂。\n菊垂今秋花，石戴古车辙。\n青云动高兴，幽事亦可悦。\n山果多琐细，罗生杂橡栗。\n或红如丹砂，或黑如点漆。\n雨露之所濡，甘苦齐结实。\n缅思桃源内，益叹身世拙。\n坡陀望鄜畤，岩谷互出没。\n我行已水滨，我仆犹木末。\n鸱鸟鸣黄桑，野鼠拱乱穴。\n夜深经战场，寒月照白骨。\n潼关百万师，往者散何卒？\n遂令半秦民，残害为异物。\n况我堕胡尘，及归尽华发。\n经年至茅屋，妻子衣百结。\n恸哭松声回，悲泉共幽咽。\n平生所娇儿，颜色白胜雪。\n见爷背面啼，垢腻脚不袜。\n床前两小女，补绽才过膝。\n海图坼波涛，旧绣移曲折。\n天吴及紫凤，颠倒在裋褐。\n老夫情怀恶，呕泄卧数日。\n那无囊中帛，救汝寒凛栗。\n粉黛亦解包，衾裯稍罗列。\n瘦妻面复光，痴女头自栉。\n学母无不为，晓妆随手抹。\n移时施朱铅，狼藉画眉阔。\n生还对童稚，似欲忘饥渴。\n问事竞挽须，谁能即嗔喝？\n翻思在贼愁，甘受杂乱聒。\n新归且慰意，生理焉得说！\n至尊尚蒙尘，几日休练卒？\n仰观天色改，坐觉妖氛豁。\n阴风西北来，惨澹随回纥。\n其王愿助顺，其俗善驰突。\n送兵五千人，驱马一万匹。\n此辈少为贵，四方服勇决。\n所用皆鹰腾，破敌过箭疾。\n圣心颇虚伫，时议气欲夺。\n伊洛指掌收，西京不足拔。\n官军请深入，蓄锐伺俱发。\n此举开青徐，旋瞻略恒碣。\n昊天积霜露，正气有肃杀。\n祸转亡胡岁，势成擒胡月。\n胡命其能久，皇纲未宜绝。\n忆昨狼狈初，事与古先别。\n奸臣竟菹醢，同恶随荡析。\n不闻夏殷衰，中自诛褒妲。\n周汉获再兴，宣光果明哲。\n桓桓陈将军，仗钺奋忠烈。\n微尔人尽非，于今国犹活。\n凄凉大同殿，寂寞白兽闼。\n都人望翠华，佳气向金阙。\n园陵固有神，扫洒数不缺。\n煌煌太宗业，树立甚宏达。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 327, "title": "羌村三首", "author": "杜甫", "body": "峥嵘赤云西，日脚下平地。\n柴门鸟雀噪，归客千里至。\n妻孥怪我在，惊定还拭泪。\n世乱遭飘荡，生还偶然遂。\n邻人满墙头，感叹亦歔欷。\n夜阑更秉烛，相对如梦寐。\n晚岁迫偷生，还家少欢趣。\n娇儿不离膝，畏我复却去。\n忆昔好追凉，故绕池边树。\n萧萧北风劲，抚事煎百虑。\n赖知禾黍收，已觉糟床注。\n如今足斟酌，且用慰迟暮。\n群鸡正乱叫，客至鸡斗争。\n驱鸡上树木，始闻叩柴荆。\n父老四五人，问我久远行。\n手中各有携，倾榼浊复清。\n苦辞“酒味薄，黍地无人耕。\n兵革既未息，儿童尽东征”。\n请为父老歌，艰难愧深情。\n歌罢仰天叹，四座泪纵横。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 328, "title": "送郑十八虔贬台州司户伤其临老陷贼之故阙为面别情见于诗", "author": "杜甫", "body": "郑公樗散鬓成丝，酒后常称老画师。\n万里伤心严谴日，百年垂死中兴时。\n苍惶已就长途往，邂逅无端出饯迟。\n便与先生应永诀，九重泉路尽交期。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 329, "title": "春宿左省", "author": "杜甫", "body": "花隐掖垣暮，啾啾栖鸟过。\n星临万户动，月傍九霄多。\n不寝听金钥，因风想玉珂。\n明朝有封事，数问夜如何。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 330, "title": "曲江二首", "author": "杜甫", "body": "一片花飞减却春，风飘万点正愁人。\n且看欲尽花经眼，莫厌伤多酒入唇。\n江上小堂巢翡翠，苑边高冢卧麒麟。\n细推物理须行乐，何用浮荣绊此身？\n朝回日日典春衣，每日江头尽醉归。\n酒债寻常行处有，人生七十古来稀。\n穿花蛱蝶深深见，点水蜻蜓款款飞。\n传语风光共流转，暂时相赏莫相违。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 331, "title": "曲江对酒", "author": "杜甫", "body": "苑外江头坐不归，水精宫殿转霏微。\n桃花细逐杨花落，黄鸟时兼白鸟飞。\n纵饮久判人共弃，懒朝真与世相违。\n吏情更觉沧洲远，老大徒伤未拂衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 332, "title": "九日蓝田崔氏庄", "author": "杜甫", "body": "老去悲秋强自宽，兴来今日尽君欢。\n羞将短发还吹帽，笑倩旁人为正冠。\n蓝水远从千涧落，玉山高并两峰寒。\n明年此会知谁健？醉把茱萸[1]仔细看。\n〔注〕[1]茱萸：古代风俗，九月初九日，佩茱萸（植物名，有浓香）囊可以去邪辟恶，益寿延年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 333, "title": "日暮", "author": "杜甫", "body": "牛羊下来久，各已闭柴门。\n风月自清夜，江山非故园。\n石泉流暗壁，草露滴秋根。\n头白灯明里，何须花烬繁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 334, "title": "赠卫八处士", "author": "杜甫", "body": "人生不相见，动如参与商。\n今夕复何夕，共此灯烛光。\n少壮能几时？鬓发各已苍！\n访旧半为鬼，惊呼热中肠。\n焉知二十载，重上君子堂。\n昔别君未婚，儿女忽成行。\n怡然敬父执，问我来何方。\n问答乃未已，驱儿罗酒浆。\n夜雨剪春韭，新炊间黄粱。\n主称会面难，一举累十觞。\n十觞亦不醉，感子故意长。\n明日隔山岳，世事两茫茫。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 335, "title": "洗兵马", "author": "杜甫", "body": "中兴诸将收山东，捷书夜报清昼同。\n河广传闻一苇过，胡危命在破竹中。\n祗残邺城不日得，独任朔方无限功。\n京师皆骑汗血马，回纥餧肉蒲萄宫。\n已喜皇威清海岱，常思仙仗过崆峒。\n三年笛里关山月，万国兵前草木风。\n成王功大心转小，郭相谋深古来少。\n司徒清鉴悬明镜，尚书气与秋天杳。\n二三豪俊为时出，整顿乾坤济时了。\n东走无复忆鲈鱼，南飞觉有安巢鸟。\n青春复随冠冕入，紫禁正耐烟花绕。\n鹤驾通宵凤辇备，鸡鸣问寝龙楼晓。\n攀龙附凤势莫当，天下尽化为侯王。\n汝等岂知蒙帝力，时来不得夸身强！\n关中既留萧丞相，幕下复用张子房。\n张公一身江海客，身长九尺须眉苍；\n征起适遇风云会，扶颠始知筹策良。\n青袍白马更何有？后汉今周喜再昌。\n寸地尺天皆入贡，奇祥异瑞争来送。\n不知何国致白环，复道诸山得银瓮。\n隐士休歌紫芝曲，词人解撰河清颂。\n田家望望惜雨干，布谷处处催春种。\n淇上健儿归莫懒，城南思妇愁多梦。\n安得壮士挽天河，尽洗甲兵长不用！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 336, "title": "新安吏", "author": "杜甫", "body": "客行新安道，喧呼闻点兵。\n借问新安吏： “县小更无丁？”\n“府帖昨夜下，次选中男行。”\n“中男绝短小，何以守王城？”\n肥男有母送，瘦男独伶俜。\n白水暮东流，青山犹哭声。\n“莫自使眼枯，收汝泪纵横。\n眼枯即见骨，天地终无情！\n我军取相州，日夕望其平。\n岂意贼难料，归军星散营。\n就粮近故垒，练卒依旧京。\n掘壕不到水，牧马役亦轻。\n况乃王师顺，抚养甚分明。\n送行勿泣血，仆射[1]如父兄。”\n〔注〕[1]仆射（yè）：官职名。这里指郭子仪，当时因战败降职为左仆射。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 337, "title": "石壕吏", "author": "杜甫", "body": "暮投石壕村，有吏夜捉人。\n老翁逾墙走，老妇出门看。\n吏呼一何怒！妇啼一何苦！\n听妇前致词： “三男邺城戍。\n一男附书至，二男新战死。\n存者且偷生，死者长已矣！\n室中更无人，惟有乳下孙。\n有孙母未去，出入无完裙。\n老妪力虽衰，请从吏夜归。\n急应河阳役，犹得备晨炊。”\n夜久语声绝，如闻泣幽咽。\n天明登前途，独与老翁别。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 338, "title": "潼关吏", "author": "杜甫", "body": "士卒何草草，筑城潼关道。\n大城铁不如，小城万丈馀。\n借问潼关吏： “修关还备胡？”\n要我下马行，为我指山隅：\n“连云列战格，飞鸟不能逾。\n胡来但自守，岂复忧西都。\n丈人视要处，窄狭容单车。\n艰难奋长戟，万古用一夫。”\n“哀哉桃林战，百万化为鱼。\n请嘱防关将，慎勿学哥舒！”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 339, "title": "新婚别", "author": "杜甫", "body": "兔丝附蓬麻，引蔓故不长。\n嫁女与征夫，不如弃路旁。\n结发为君妻，席不暖君床。\n暮婚晨告别，无乃太匆忙！\n君行虽不远，守边赴河阳。\n妾身未分明，何以拜姑嫜？\n父母养我时，日夜令我藏。\n生女有所归，鸡狗亦得将。\n君今往死地，沉痛迫中肠。\n誓欲随君去，形势反苍黄[1]。\n勿为新婚念，努力事戎行！\n妇人在军中，兵气恐不扬。\n自嗟贫家女，久致罗襦裳。\n罗襦不复施，对君洗红妆。\n仰视百鸟飞，大小必双翔。\n人事多错迕，与君永相望！\n〔注〕[1]苍黄：本指青色和黄色。《墨子·所染》:“见染丝者而叹曰：染于苍则苍，染于黄则黄。”后因以“苍黄”比喻极大的变化。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 340, "title": "垂老别", "author": "杜甫", "body": "四郊未宁静，垂老不得安。\n子孙阵亡尽，焉用身独完！\n投杖出门去，同行为辛酸。\n幸有牙齿存，所悲骨髓干。\n男儿既介胄，长揖别上官。\n老妻卧路啼，岁暮衣裳单。\n孰知是死别，且复伤其寒。\n此去必不归，还闻劝加餐。\n土门壁甚坚，杏园度亦难[1]。\n势异邺城下，纵死时犹宽。\n人生有离合，岂择衰盛端！\n忆昔少壮日，迟回竟长叹。\n万国尽征戍，烽火被冈峦。\n积尸草木腥，流血川原丹。\n何乡为乐土？安敢尚盘桓！\n弃绝蓬室居，塌然摧肺肝。\n〔注〕[1]土门：地名，在今河南孟县附近。杏园：地名，在今河南汲县东南。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 341, "title": "无家别", "author": "杜甫", "body": "寂寞天宝后，园庐但蒿藜。\n我里百馀家，世乱各东西。\n存者无消息，死者为尘泥。\n贱子因阵败，归来寻旧蹊。\n久行见空巷，日瘦气惨凄。\n但对狐与狸，竖毛怒我啼。\n四邻何所有？一二老寡妻。\n宿鸟恋本枝，安辞且穷栖。\n方春独荷锄，日暮还灌畦。\n县吏知我至，召令习鼓鞞。\n虽从本州役，内顾无所携。\n近行止一身，远去终转迷。\n家乡既荡尽，远近理亦齐。\n永痛长病母，五年委沟溪。\n生我不得力，终身两酸嘶。\n人生无家别，何以为蒸黎！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 342, "title": "佳人", "author": "杜甫", "body": "绝代有佳人，幽居在空谷。\n自云良家子，零落依草木。\n关中昔丧乱，兄弟遭杀戮。\n官高何足论，不得收骨肉。\n世情恶衰歇，万事随转烛。\n夫婿轻薄儿，新人美如玉。\n合昏尚知时，鸳鸯不独宿。\n但见新人笑，那闻旧人哭。\n在山泉水清，出山泉水浊。\n侍婢卖珠回，牵萝补茅屋。\n摘花不插发，采柏动盈掬。\n天寒翠袖薄，日暮倚修竹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 343, "title": "梦李白二首", "author": "杜甫", "body": "死别已吞声，生别常恻恻。\n江南瘴疠地，逐客无消息。\n故人入我梦，明我长相忆。\n君今在罗网，何以有羽翼？\n恐非平生魂，路远不可测。\n魂来枫林青，魂返关塞黑。\n落月满屋梁，犹疑照颜色。\n水深波浪阔，无使蛟龙得！\n浮云终日行，游子久不至。\n三夜频梦君，情亲见君意。\n告归常局促，苦道来不易：\n江湖多风波，舟楫恐失坠。\n出门搔白首，若负平生志。\n冠盖满京华，斯人独憔悴！\n孰云网恢恢？将老身反累！\n千秋万岁名，寂寞身后事。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 344, "title": "秦州杂诗（其七）", "author": "杜甫", "body": "莽莽万重山，孤城山谷间。\n无风云出塞，不夜月临关。\n属国归何晚？楼兰斩未还。\n烟尘一长望，衰飒正摧颜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 345, "title": "天末怀李白", "author": "杜甫", "body": "凉风起天末，君子意如何？\n鸿雁几时到，江湖秋水多。\n文章憎命达，魑魅喜人过。\n应共冤魂语，投诗赠汨罗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 346, "title": "月夜忆舍弟", "author": "杜甫", "body": "戍鼓断人行，边秋一雁声。\n露从今夜白，月是故乡明。\n有弟皆分散，无家问死生。\n寄书长不达，况乃未休兵。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 347, "title": "乾元中寓居同谷县作歌七首（其七）", "author": "杜甫", "body": "男儿生不成名身已老，三年饥走荒山道。\n长安卿相多少年，富贵应须致身早。\n山中儒生旧相识，但话宿昔伤怀抱。\n呜呼七歌兮悄终曲，仰视皇天白日速。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 348, "title": "成都府", "author": "杜甫", "body": "翳翳桑榆日，照我征衣裳。\n我行山川异，忽在天一方。\n但逢新人民，未卜见故乡。\n大江东流去，游子日月长。\n曾城填华屋，季冬树木苍。\n喧然名都会，吹箫间笙簧。\n信美无与适，侧身望川梁。\n鸟雀夜各归，中原杳茫茫。\n初月出不高，众星尚争光。\n自古有羁旅，我何苦哀伤。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 349, "title": "蜀相", "author": "杜甫", "body": "丞相祠堂何处寻，锦官城外柏森森。\n映阶碧草自春色，隔叶黄鹂空好音。\n三顾频烦天下计，两朝开济老臣心。\n出师未捷身先死，长使英雄泪满襟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 350, "title": "戏题王宰画山水图歌", "author": "杜甫", "body": "十日画一水，五日画一石。\n能事不受相促迫，王宰始肯留真迹。\n壮哉昆仑方壶图，挂君高堂之素壁。\n巴陵[1]洞庭日本东[2]，赤岸[3]水与银河通，中有云气随飞龙。\n舟人渔子入浦溆，山木尽亚洪涛风。\n尤工远势古莫比，咫尺应须论万里。\n焉得并州快剪刀[4]，剪取吴淞半江水。\n〔注〕[1]巴陵：郡名。唐天宝、至德年间改岳州为巴陵郡，治所在今湖南岳阳市，地处洞庭湖东。 [2]日本东：指日本东面的海。 [3]赤岸：地名，一说在今江苏六合县东。汉枚乘《七发》:“凌赤岸，篲扶桑。”李善注：“以赤岸在广陵，而文势似在远方，非广陵也。”这里并非实指，而是泛指江海的岸。 [4]并州：地名。唐开元中为太原府，州治在今山西太原市，以产剪刀著称，有所谓“并州剪”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 351, "title": "南邻", "author": "杜甫", "body": "锦里先生乌角巾，园收芋栗未全贫。\n惯看宾客儿童喜，得食阶除鸟雀驯。\n秋水才深四五尺，野航恰受两三人。\n白沙翠竹江村暮，相送柴门月色新。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 352, "title": "狂夫", "author": "杜甫", "body": "万里桥西一草堂，百花潭水即沧浪。\n风含翠筿娟娟净，雨裛红蕖冉冉香。\n厚禄故人书断绝，恒饥稚子色凄凉。\n欲填沟壑惟疏放，自笑狂夫老更狂。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 353, "title": "江村", "author": "杜甫", "body": "清江一曲抱村流，长夏江村事事幽。\n自去自来梁上燕，相亲相近水中鸥。\n老妻画纸为棋局，稚子敲针作钓钩。\n但有故人供禄米，微躯此外更何求？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 354, "title": "野老", "author": "杜甫", "body": "野老篱边江岸回，柴门不正逐江开。\n渔人网集澄潭下，贾客船随返照来。\n长路关心悲剑阁，片云何意傍琴台？\n王师未报收东郡，城阙秋生画角哀。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 355, "title": "恨别", "author": "杜甫", "body": "洛城一别四千里，胡骑长驱五六年。\n草木变衰行剑外，兵戈阻绝老江边。\n思家步月清宵立，忆弟看云白日眠。\n闻道河阳近乘胜，司徒急为破幽燕。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 356, "title": "和裴迪登蜀州东亭送客逢早梅相忆见寄", "author": "杜甫", "body": "东阁官梅动诗兴，还如何逊在扬州。\n此时对雪遥相忆，送客逢春可自由？\n幸不折来伤岁暮，若为看去乱乡愁。\n江边一树垂垂发，朝夕催人自白头。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 357, "title": "后游", "author": "杜甫", "body": "寺忆曾游处，桥怜再渡时。\n江山如有待，花柳自无私。\n野润烟光薄，沙暄日色迟。\n客愁全为减，舍此复何之？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 358, "title": "客至", "author": "杜甫", "body": "舍南舍北皆春水，但见群鸥日日来。\n花径不曾缘客扫，蓬门今始为君开。\n盘飧市远无兼味，樽酒家贫只旧醅。\n肯与邻翁相对饮，隔篱呼取尽馀杯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 359, "title": "绝句漫兴九首（其一）", "author": "杜甫", "body": "眼见客愁愁不醒，无赖春色到江亭。\n即遣花开深造次，便教莺语太丁宁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 360, "title": "绝句漫兴九首（其三）", "author": "杜甫", "body": "熟知茅斋绝低小，江上燕子故来频。\n衔泥点污琴书内，更接飞虫打着人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 361, "title": "绝句漫兴九首（其七）", "author": "杜甫", "body": "糁径杨花铺白毡，点溪荷叶叠青钱。\n笋根雉子无人见，沙上凫雏傍母眠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 362, "title": "春夜喜雨", "author": "杜甫", "body": "好雨知时节，当春乃发生。\n随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。\n晓看红湿处，花重锦官城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 363, "title": "江亭", "author": "杜甫", "body": "坦腹江亭暖，长吟野望时。\n水流心不竞，云在意俱迟。\n寂寂春将晚，欣欣物自私。\n江东犹苦战，回首一颦眉[1]。\n〔注〕[1]“江东犹苦战，回首一颦眉”，各本作“故林归未得，排闷强裁诗”，此据草堂本。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 364, "title": "琴台", "author": "杜甫", "body": "茂陵多病后，尚爱卓文君。\n酒肆人间世，琴台日暮云。\n野花留宝靥，蔓草见罗裙。\n归凤求凰意，寥寥不复闻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 365, "title": "水槛遣心二首（其一）", "author": "杜甫", "body": "去郭轩楹敞[1]，无村眺望赊[2]。\n澄江平少岸，幽树晚多花。\n细雨鱼儿出，微风燕子斜。\n城中十万户，此地两三家。\n〔注〕[1]轩：长廊。楹：柱子。 [2]赊：远。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 366, "title": "送韩十四江东觐省[1]", "author": "杜甫", "body": "兵戈不见老莱衣[2]，叹息人间万事非。\n我已无家寻弟妹，君今何处访庭闱？\n黄牛峡静滩声转[3]，白马江[4]寒树影稀。\n此别应须各努力，故乡犹恐未同归。\n〔注〕[1]韩十四：名不详，十四是指他的排行。觐省：看望父母，探亲。 [2]老莱衣：传说春秋时代楚国有隐士老莱子，七十岁还常常穿上彩衣，模仿儿童，欢娱他的双亲。 [3]黄牛峡：长江峡名，在今湖北宜昌西。峡下有黄牛滩。 [4]白马江：在蜀州（治所在今四川崇州市）东北十里处。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 367, "title": "茅屋为秋风所破歌", "author": "杜甫", "body": "八月秋高风怒号，卷我屋上三重茅。\n茅飞渡江洒江郊，高者挂罥[1]长林梢，下者飘转沉塘坳。\n南村群童欺我老无力，忍能对面为盗贼。\n公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。\n俄顷风定云墨色，秋天漠漠向昏黑。\n布衾多年冷似铁，骄儿恶卧踏里裂。\n床头屋漏无干处，雨脚如麻未断绝。\n自经丧乱少睡眠，长夜沾湿何由彻！\n安得广厦千万间，大庇天下寒士俱欢颜，风雨不动安如山！\n呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！\n〔注〕[1]罥（juàn）：挂结。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 368, "title": "赠花卿", "author": "杜甫", "body": "锦城丝管日纷纷，半入江风半入云。\n此曲只应天上有，人间能得几回闻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 369, "title": "不见", "author": "杜甫", "body": "不见李生久，佯狂真可哀！\n世人皆欲杀，吾意独怜才。\n敏捷诗千首，飘零酒一杯。\n匡山读书处，头白好归来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 370, "title": "江畔独步寻花七绝句（其六）", "author": "杜甫", "body": "黄四娘[1]家花满蹊，千朵万朵压枝低。\n留连戏蝶时时舞，自在娇莺恰恰啼。\n〔注〕[1]“娘”或“娘子”是唐代习惯上对妇女的美称。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 371, "title": "堂成", "author": "杜甫", "body": "背郭堂成荫白茅，缘江路熟俯青郊。\n桤林[1]碍日吟风叶，笼竹和烟滴露梢。\n暂止飞乌将数子，频来语燕定新巢。\n旁人错比扬雄宅，懒惰无心作《解嘲》。\n〔注〕[1]桤（qī）林：桤木林。桤，桤木，一种落叶乔木。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 372, "title": "戏为六绝句", "author": "杜甫", "body": "庾信文章老更成，凌云健笔意纵横。\n今人嗤点流传赋，不觉前贤畏后生。\n王杨卢骆当时体，轻薄为文哂未休。\n尔曹身与名俱灭，不废江河万古流。\n纵使“卢王操翰墨，劣于汉魏近风骚”；\n龙文虎脊皆君驭，历块过都见尔曹[1]。\n才力应难跨数公，凡今谁是出群雄。\n或看翡翠兰苕上[2]，未掣鲸鱼碧海中。\n不薄今人爱古人，清词丽句必为邻。\n窃攀屈宋宜方驾，恐与齐梁作后尘。\n未及前贤更勿疑，递相祖述复先谁？\n别裁伪体亲风雅，转益多师是汝师。\n〔注〕[1]龙文虎脊：龙文、虎脊，都是毛色斑驳的骏马，用以比喻瑰丽的词采。历块过都：语本汉王褒《圣主得贤臣颂》:“过都越国，蹶如历块。”吕延济注：“言过都国，急如行一小块之间。”这里略变其意，是说历田野，过城市，指长距离的奔驰。（“块”，可作土地解。《庄子·齐物论》:“大块噫气，其名为风。”）“见尔曹”，意谓相形之下，就能见出高低。 [2]晋郭璞《游仙诗》:“翡翠戏兰苕，容色更相鲜。”“或看翡翠兰苕上”，语即本此。清人李重华在《贞一斋诗话》里有段评论杜甫绝句诗的话：\n七绝乃唐人乐章，工者最多。……李白、王昌龄后，当以刘梦得为最。缘落笔朦胧缥缈，其来无端，其去无际故也。杜老七绝欲与诸家分道扬镳，故尔别开异径。独其情怀，最得诗人雅趣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 373, "title": "奉济驿重送严公四韵", "author": "杜甫", "body": "远送从此别，青山空复情。\n几时杯重把？昨夜月同行。\n列郡讴歌惜，三朝出入荣。\n江村独归处，寂寞养残生。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 374, "title": "闻官军收河南河北", "author": "杜甫", "body": "剑外忽传收蓟北，初闻涕泪满衣裳。\n却看妻子愁何在，漫卷诗书喜欲狂。\n白首[1]放歌须纵酒，青春作伴好还乡。\n即从巴峡穿巫峡，便下襄阳向洛阳。\n〔注〕[1]白首：一作“白日”。如果作“白日”，就与下句中的“青春”显得重复，故作“白首”较好。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 375, "title": "送路六侍御入朝", "author": "杜甫", "body": "童稚情亲四十年，中间消息两茫然。\n更为后会知何地？忽漫相逢是别筵！\n不分[1]桃花红似锦，生憎[2]柳絮白于棉。\n剑南春色还无赖，触忤愁人到酒边。\n〔注〕[1]不分：犹言不满，嫌恶的意思。“分”，一作“忿”。 [2]生憎：犹言偏憎、最憎。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 376, "title": "将赴荆南寄别李剑州", "author": "杜甫", "body": "使君高义驱今古，寥落三年坐剑州。\n但见文翁能化俗，焉知李广未封侯？\n路经滟滪[1]双蓬鬓，天入沧浪一钓舟。\n戎马相逢更何日？春风回首仲宣楼。\n〔注〕[1]滟滪（yànyù）：即滟滪滩，在重庆奉节县东五公里瞿塘峡口，旧时是长江三峡的著名险滩。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 377, "title": "别房太尉墓", "author": "杜甫", "body": "他乡复行役，驻马别孤坟。\n近泪无干土，低空有断云。\n对棋陪谢傅，把剑觅徐君。\n惟见林花落，莺啼送客闻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 378, "title": "将赴成都草堂途中有作先寄严郑公五首（其四）", "author": "杜甫", "body": "常苦沙崩损药栏，也从江槛落风湍。\n新松恨不高千尺，恶竹应须斩万竿！\n生理只凭黄阁老，衰颜欲付紫金丹。\n三年奔走空皮骨，信有人间行路难。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 379, "title": "登楼", "author": "杜甫", "body": "花近高楼伤客心，万方多难此登临。\n锦江春色来天地，玉垒浮云变古今。\n北极朝廷终不改，西山寇盗莫相侵。\n可怜后主还祠庙，日暮聊为梁甫吟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 380, "title": "绝句二首（其一）", "author": "杜甫", "body": "迟日江山丽，春风花草香。\n泥融飞燕子，沙暖睡鸳鸯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 381, "title": "绝句二首（其二）", "author": "杜甫", "body": "江碧鸟逾白，山青花欲燃。\n今春看又过，何日是归年？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 382, "title": "绝句四首（其三）", "author": "杜甫", "body": "两个黄鹂鸣翠柳，一行白鹭上青天。\n窗含西岭千秋雪，门泊东吴万里船。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 383, "title": "丹青引赠曹将军霸[1]", "author": "杜甫", "body": "将军魏武之子孙，于今为庶为清门。\n英雄割据虽已矣，文采风流今尚存。\n学书初学卫夫人，但恨无过王右军。\n丹青不知老将至，富贵于我如浮云。\n开元之中常引见，承恩数上南薰殿。\n凌烟功臣少颜色，将军下笔开生面。\n良相头上进贤冠，猛将腰间大羽箭。\n褒公鄂公毛发动，英姿飒爽来酣战。\n先帝御马玉花骢，画工如山貌不同。\n是日牵来赤墀下，迥立阊阖生长风。\n诏谓将军拂绢素，意匠惨淡经营中。\n斯须九重真龙出，一洗万古凡马空。\n玉花却在御榻上，榻上庭前屹相向。\n至尊含笑催赐金，圉人太仆皆惆怅。\n弟子韩幹早入室，亦能画马穷殊相。\n幹惟画肉不画骨，忍使骅骝气凋丧。\n将军画善盖有神，必逢佳士亦写真。\n即今飘泊干戈际，屡貌寻常行路人。\n途穷反遭俗眼白，世上未有如公贫。\n但看古来盛名下，终日坎壈缠其身。\n〔注〕[1]丹青：绘画。引：唐代乐曲的一种，也是一种诗体的名称，相当于长篇歌行。曹霸：唐张彦远《历代名画记》:“曹霸，魏曹髦之后。髦画称于后代。霸在开元中已得名。天宝末，每诏写御马及功臣。官至左武卫将军。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 384, "title": "宿府", "author": "杜甫", "body": "清秋幕府井梧寒，独宿江城蜡炬残。\n永夜角声悲自语，中天月色好谁看？\n风尘荏苒音书绝，关塞萧条行路难。\n已忍伶俜十年事，强移栖息一枝安。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 385, "title": "倦夜", "author": "杜甫", "body": "竹凉侵卧内，野月满庭隅。\n重露成涓滴，稀星乍有无。\n暗飞萤自照，水宿鸟相呼。\n万事干戈里，空悲清夜徂！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 386, "title": "有感五首（其三）", "author": "杜甫", "body": "洛下舟车入，天中贡赋均。\n日闻红粟腐，寒待翠华春。\n莫取金汤固，长令宇宙新。\n不过行俭德，盗贼本王臣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 387, "title": "禹庙", "author": "杜甫", "body": "禹庙空山里，秋风落日斜。\n荒庭垂橘柚，古屋画龙蛇。\n云气嘘青壁，江声走白沙。\n早知乘四载，疏凿控三巴。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 388, "title": "旅夜书怀", "author": "杜甫", "body": "细草微风岸，危樯独夜舟。\n星垂平野阔，月涌大江流。\n名岂文章著，官应老病休。\n飘飘何所似？天地一沙鸥。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 389, "title": "八阵图", "author": "杜甫", "body": "功盖三分国，名成八阵图。\n江流石不转，遗恨失吞吴。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 390, "title": "白帝", "author": "杜甫", "body": "白帝城中云出门，白帝城下雨翻盆。\n高江急峡雷霆斗，古木苍藤日月昏。\n戎马不如归马逸，千家今有百家存。\n哀哀寡妇诛求尽，恸哭秋原何处村？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 391, "title": "夔州歌十绝句（其一）", "author": "杜甫", "body": "中巴之东巴东山，江水开辟流其间。\n白帝高为三峡镇，瞿塘险过百牢关。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 392, "title": "宿江边阁", "author": "杜甫", "body": "暝色延山径，高斋次水门。\n薄云岩际宿，孤月浪中翻。\n鹳鹤追飞静，豺狼得食喧。\n不眠忧战伐，无力正乾坤。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 393, "title": "诸将五首（其二）", "author": "杜甫", "body": "韩公本意筑三城，拟绝天骄拔汉旌。\n岂谓尽烦回纥马，翻然远救朔方兵。\n胡来不觉潼关隘，龙起犹闻晋水清。\n独使至尊忧社稷，诸君何以答升平？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 394, "title": "秋兴八首", "author": "杜甫", "body": "玉露凋伤枫树林，巫山巫峡气萧森。\n江间波浪兼天涌，塞上风云接地阴。\n丛菊两开他日泪，孤舟一系故园心。\n寒衣处处催刀尺，白帝城高急暮砧。\n夔府孤城落日斜，每依北斗望京华。\n听猿实下三声泪，奉使虚随八月槎。\n画省香炉违伏枕，山楼粉堞隐悲笳。\n请看石上藤萝月，已映洲前芦荻花。\n千家山郭静朝晖，日日江楼坐翠微。\n信宿渔人还泛泛，清秋燕子故飞飞。\n匡衡抗疏功名薄，刘向传经心事违。\n同学少年多不贱，五陵衣马自轻肥。\n闻道长安似弈棋，百年世事不胜悲。\n王侯第宅皆新主，文武衣冠异昔时。\n直北关山金鼓振，征西车马羽书驰。\n鱼龙寂寞秋江冷，故国平居有所思。\n蓬莱宫阙对南山，承露金茎霄汉间。\n西望瑶池降王母，东来紫气满函关。\n云移雉尾开宫扇，日绕龙鳞识圣颜。\n一卧沧江惊岁晚，几回青琐点朝班。\n瞿塘峡口曲江头，万里风烟接素秋。\n花萼夹城通御气，芙蓉小苑入边愁。\n珠帘绣柱围黄鹄，锦缆牙樯起白鸥。\n回首可怜歌舞地，秦中自古帝王州。\n昆明池水汉时功，武帝旌旗在眼中。\n织女机丝虚夜月，石鲸鳞甲动秋风。\n波漂菰米沉云黑，露冷莲房坠粉红。\n关塞极天惟鸟道，江湖满地一渔翁。\n昆吾御宿自逶迤，紫阁峰阴入渼陂。\n香稻啄馀鹦鹉粒，碧梧栖老凤凰枝。\n佳人拾翠春相问，仙侣同舟晚更移。\n彩笔昔曾干气象，白头吟望苦低垂。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 395, "title": "咏怀古迹五首（其二）", "author": "杜甫", "body": "摇落深知宋玉悲，风流儒雅亦吾师。\n怅望千秋一洒泪，萧条异代不同时。\n江山故宅空文藻，云雨荒台岂梦思。\n最是楚宫俱泯灭，舟人指点到今疑。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 396, "title": "咏怀古迹五首（其三）", "author": "杜甫", "body": "群山万壑赴荆门，生长明妃尚有村。\n一去紫台连朔漠，独留青冢向黄昏。\n画图省识春风面，环珮空归月夜魂。\n千载琵琶作胡语，分明怨恨曲中论。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 397, "title": "咏怀古迹五首（其五）", "author": "杜甫", "body": "诸葛大名垂宇宙，宗臣遗像肃清高。\n三分割据纡筹策，万古云霄一羽毛。\n伯仲之间见伊吕，指挥若定失萧曹。\n运移汉祚终难复，志决身歼军务劳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 398, "title": "阁夜", "author": "杜甫", "body": "岁暮阴阳催短景，天涯霜雪霁寒宵。\n五更鼓角声悲壮，三峡星河影动摇。\n野哭千家闻战伐，夷歌数处起渔樵。\n卧龙跃马终黄土，人事音书漫寂寥。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 399, "title": "孤雁", "author": "杜甫", "body": "孤雁不饮啄，飞鸣声念群。\n谁怜一片影，相失万重云？\n望尽似犹见，哀多如更闻。\n野鸦无意绪，鸣噪自纷纷。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 400, "title": "又呈吴郎", "author": "杜甫", "body": "堂前扑枣任西邻，无食无儿一妇人。\n不为困穷宁有此？只缘恐惧转须亲。\n即防远客虽多事，便插疏篱却甚真。\n已诉征求贫到骨，正思戎马泪盈巾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 401, "title": "九日", "author": "杜甫", "body": "重阳独酌杯中酒，抱病起登江上台。\n竹叶于人既无分，菊花从此不须开。\n殊方日落玄猿哭，旧国霜前白雁来。\n弟妹萧条各何在，干戈衰谢两相催！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 402, "title": "登高", "author": "杜甫", "body": "风急天高猿啸哀，渚清沙白鸟飞回。\n无边落木萧萧下，不尽长江滚滚来。\n万里悲秋常作客，百年多病独登台。\n艰难苦恨繁霜鬓，潦倒新停浊酒杯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 403, "title": "观公孙大娘弟子舞剑器行并序", "author": "杜甫", "body": "大历二年十月十九日，夔府别驾元持宅见临颍李十二娘舞剑器，壮其蔚跂。问其所师，曰：“余公孙大娘弟子也。”开元五载，余尚童稚，记于郾城观公孙氏舞剑器浑脱，浏漓顿挫，独出冠时。自高头宜春、梨园二伎坊内人洎外供奉，晓是舞者，圣文神武皇帝初，公孙一人而已。玉貌锦衣，况余白首；今兹弟子，亦匪盛颜。既辨其由来，知波澜莫二。抚事慷慨，聊为《剑器行》。昔者吴人张旭，善草书书帖，数常于邺县见公孙大娘舞西河剑器，自此草书长进，豪荡感激，即公孙可知矣。\n昔有佳人公孙氏，一舞剑器动四方。\n观者如山色沮丧，天地为之久低昂。\n㸌如羿射九日落，矫如群帝骖龙翔。\n来如雷霆收震怒，罢如江海凝清光。\n绛唇珠袖两寂寞，晚有弟子传芬芳。\n临颍美人在白帝，妙舞此曲神扬扬。\n与余问答既有以，感时抚事增惋伤。\n先帝侍女八千人，公孙剑器初第一。\n五十年间似反掌，风尘澒洞昏王室。\n梨园弟子散如烟，女乐馀姿映寒日。\n金粟堆南木已拱，瞿唐石城草萧瑟。\n玳筵急管曲复终，乐极哀来月东出。\n老夫不知其所往，足茧荒山转愁疾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 404, "title": "漫成一首", "author": "杜甫", "body": "江月去人只数尺，风灯照夜欲三更。\n沙头宿鹭联拳静，船尾跳鱼拨剌鸣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 405, "title": "短歌行赠王郎司直", "author": "杜甫", "body": "王郎酒酣拔剑斫地歌莫哀！\n我能拔尔抑塞磊落之奇才。\n豫章翻风白日动，鲸鱼跋浪沧溟开。且脱佩剑休徘徊。\n西得诸侯棹锦水，欲向何门趿珠履？\n仲宣楼头春色深，青眼高歌望吾子。眼中之人吾老矣！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 406, "title": "江汉", "author": "杜甫", "body": "江汉思归客，乾坤一腐儒。\n片云天共远，永夜月同孤。\n落日心犹壮，秋风病欲苏。\n古来存老马，不必取长途。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 407, "title": "登岳阳楼", "author": "杜甫", "body": "昔闻洞庭水，今上岳阳楼。\n吴楚东南坼，乾坤日夜浮。\n亲朋无一字，老病有孤舟。\n戎马关山北，凭轩涕泗流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 408, "title": "南征", "author": "杜甫", "body": "春岸桃花水，云帆枫树林。\n偷生长避地，适远更沾襟。\n老病南征日，君恩北望心。\n百年歌自苦，未见有知音。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 409, "title": "发潭州", "author": "杜甫", "body": "夜醉长沙酒，晓行湘水春。\n岸花飞送客，樯燕语留人。\n贾傅才未有，褚公书绝伦。\n名高前后事，回首一伤神。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 410, "title": "燕子来舟中作", "author": "杜甫", "body": "湖南为客动经春，燕子衔泥两度新。\n旧入故园尝识主，如今社日远看人。\n可怜处处巢居室，何异飘飘托此身。\n暂语船樯还起去，穿花贴水益沾巾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 411, "title": "小寒食舟中作", "author": "杜甫", "body": "佳辰强饮食犹寒，隐几萧条戴鹖冠。\n春水船如天上坐，老年花似雾中看。\n娟娟戏蝶过闲幔，片片轻鸥下急湍。\n云白山青万馀里，愁看直北是长安。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 412, "title": "江南逢李龟年", "author": "杜甫", "body": "岐王宅里寻常见，崔九堂前几度闻。\n正是江南好风景，落花时节又逢君。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 413, "title": "春行即兴", "author": "李华", "body": "宜阳城下草萋萋，涧水东流复向西。\n芳树无人花自落，春山一路鸟空啼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 414, "title": "白雪歌送武判官归京", "author": "岑参", "body": "北风卷地白草折，胡天八月即飞雪。\n忽如一夜春风来，千树万树梨花开。\n散入珠帘湿罗幕，狐裘不暖锦衾薄。\n将军角弓不得控，都护铁衣冷难着。\n瀚海阑干百丈冰，愁云惨淡万里凝。\n中军置酒饮归客，胡琴琵琶与羌笛。\n纷纷暮雪下辕门，风掣红旗冻不翻。\n轮台[1]东门送君去，去时雪满天山路。\n山回路转不见君，雪上空留马行处。\n〔注〕[1]轮台：在今新疆米泉市境。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 415, "title": "走马川行奉送出师西征", "author": "岑参", "body": "君不见走马川[1]，雪海边[2]，平沙莽莽黄入天。\n轮台[3]九月风夜吼，一川碎石大如斗，随风满地石乱走。\n匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。\n将军金甲夜不脱，半夜军行戈相拨，风头如刀面如割。\n马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝。\n虏骑闻之应胆慑，料知短兵不敢接，车师[4]西门伫献捷。\n〔注〕[1]走马川：又名左末河，即今之车尔成河，在今新疆维吾尔自治区境内。一说指冰川遗迹。 [2]雪海：泛指西域一带地区。 [3]轮台：在今新疆米泉市境。 [4]车师：唐安西都护府所在地，今新疆维吾尔自治区吐鲁番县。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 416, "title": "轮台歌奉送封大夫出师西征", "author": "岑参", "body": "轮台城头夜吹角，轮台城北旄头落。\n羽书昨夜过渠黎，单于已在金山西。\n戍楼西望烟尘黑，汉兵屯在轮台北。\n上将拥旄西出征，平明吹笛大军行。\n四边伐鼓雪海涌，三军大呼阴山动。\n虏塞兵气连云屯，战场白骨缠草根。\n剑河风急雪片阔，沙口石冻马蹄脱。\n亚相勤王甘苦辛，誓将报主静边尘。\n古来青史谁不见，今见功名胜古人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 417, "title": "送李副使赴碛西官军", "author": "岑参", "body": "火山六月应更热，赤亭道口行人绝。\n知君惯度祁连城[1]，岂能愁见轮台[2]月。\n脱鞍暂入酒家垆，送君万里西击胡。\n功名只向马上取，真是英雄一丈夫。\n〔注〕[1]祁连城：在今甘肃张掖县西南。 [2]轮台：唐代庭州有轮台县，这里指汉置古轮台（在今新疆轮台县东南），李副使赴碛西经过此地。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 418, "title": "凉州馆中与诸判官[1]夜集", "author": "岑参", "body": "弯弯月出挂城头，城头月出照凉州。\n凉州七里十万家，胡人半解弹琵琶。\n琵琶一曲肠堪断，风萧萧兮夜漫漫。\n河西幕中多故人，故人别来三五春。\n花门楼前见秋草，岂能贫贱相看老。\n一生大笑能几回，斗酒相逢须醉倒。\n〔注〕[1]判官：唐代节度使、观察使下的属官。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 419, "title": "寄左省杜拾遗", "author": "岑参", "body": "联步趋丹陛[1]，分曹限紫微[2]。\n晓随天仗[3]入，暮惹御香[4]归。\n白发悲花落，青云羡鸟飞。\n圣朝无阙事，自觉谏书稀。\n〔注〕[1]丹陛：皇宫的红色台阶，借指朝廷。 [2]曹：官署。紫微：古人以紫微星垣比喻皇帝居处，此指朝会时皇帝所居的宣政殿。中书省在殿西，门下省在殿东。 [3]天仗：皇帝的仪仗。 [4]御香：朝会时殿中设炉燃香。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 420, "title": "行军九日思长安故园", "author": "岑参", "body": "强欲登高去，无人送酒来。\n遥怜故园菊，应傍战场开。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 421, "title": "武威送刘判官赴碛西行军", "author": "岑参", "body": "火山五月行人少，看君马去疾如鸟。\n都护行营太白西，角声一动胡天晓。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 422, "title": "虢州后亭送李判官使赴晋绛[1]", "author": "岑参", "body": "西原驿路挂城头，客散江亭雨未收。\n君去试看汾水上[2]，白云犹似汉时秋？\n〔注〕[1]题下原注：“得秋字。”按：古代文人聚会作诗，有时事先作好韵签，拈得或分得某字，就用此字为韵。岑参在此得“秋”字，就用“秋”字韵作此诗的韵脚。虢（guó）州：唐属河南道，故城在今河南灵宝南。晋绛（jiàng）：指晋州、绛州。晋州治所在今山西临汾；绛州治所在今山西新绛。 [2]汾水：发源于山西宁武，向西南流入黄河。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 423, "title": "山房春事二首（其二）", "author": "岑参", "body": "梁园日暮乱飞鸦，极目萧条三两家。\n庭树不知人去尽，春来还发旧时花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 424, "title": "逢入京使", "author": "岑参", "body": "故园东望路漫漫，双袖龙钟泪不干。\n马上相逢无纸笔，凭君传语报平安。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 425, "title": "碛中作[1]", "author": "岑参", "body": "走马西来欲到天，辞家见月两回圆。\n今夜未知何处宿，平沙莽莽绝人烟[2]。\n〔注〕[1]碛（qì）：沙漠。 [2]“平沙”句：一作“平沙万里绝人烟”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 426, "title": "戏问花门酒家翁", "author": "岑参", "body": "老人七十仍沽酒[1]，千壶百瓮花门口[2]。\n道傍榆荚仍似钱[3]，摘来沽酒君肯否？\n〔注〕[1]沽：买或卖，首句是“卖”的意思。末句的“沽”是“买”的意思。 [2]花门：即花门楼，凉州（治今甘肃武威）馆舍名。花门口，指花门楼口。 [3]榆荚：榆树的果实。春天榆树未生叶时，枝条间先生榆荚，形状似钱而小，色白成串，俗称榆钱。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 427, "title": "春梦", "author": "岑参", "body": "洞房昨夜春风起，遥忆美人湘江水。\n枕上片时春梦中，行尽江南数千里。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 428, "title": "采莲曲", "author": "刘方平", "body": "落日清江里，荆歌艳楚腰。\n采莲从小惯，十五即乘潮。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 429, "title": "月夜", "author": "刘方平", "body": "更深月色半人家，北斗阑干南斗斜。\n今夜偏知春气暖，虫声新透绿窗纱。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 430, "title": "春怨", "author": "刘方平", "body": "纱窗日落渐黄昏，金屋无人见泪痕。\n寂寞空庭春欲晚，梨花满地不开门。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 431, "title": "神鸡童谣", "author": "民谣", "body": "生儿不用识文字，斗鸡走马胜读书。\n贾家小儿年十三，富贵荣华代不如。\n能令金距期胜负[1]，白罗绣衫随软舆。\n父死长安千里外，差夫持道挽丧车。\n〔注〕[1]金距：公鸡斗架，全靠脚上的角质硬距作武器。在距上安上金属套子，更利于格斗，就叫“金距”。期胜负：“必定获胜”的意思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 432, "title": "华子岗", "author": "裴迪", "body": "日落松风起，还家草露晞。\n云光侵履迹，山翠拂人衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 433, "title": "舂陵行并序", "author": "元结", "body": "癸卯[1]岁，漫叟[2]授道州刺史。道州旧四万馀户，经贼[3]已来，不满四千，大半不胜赋税。到官未五十日，承诸使征求符牒[4]二百馀封，皆曰：“失其限者，罪至贬削。”於戏！若悉应其命，则州县破乱，刺史欲焉逃罪；若不应命，又即获罪戾，必不免也。吾将守官，静以安人，待罪而已。此州是舂陵故地，故作《舂陵行》以达下情。\n军国多所需，切责在有司。\n有司临郡县，刑法竞欲施。\n供给岂不忧？征敛又可悲。\n州小经乱亡，遗人实困疲。\n大乡无十家，大族命单羸。\n朝餐是草根，暮食仍木皮。\n出言气欲绝，意速行步迟。\n追呼尚不忍，况乃鞭扑之！\n邮亭传急符，来往迹相追。\n更无宽大恩，但有迫促期。\n欲令鬻儿女，言发恐乱随。\n悉使索其家，而又无生资。\n听彼道路言，怨伤谁复知！\n“去冬山贼来，杀夺几无遗。\n所愿见王官，抚养以惠慈。\n奈何重驱逐，不使存活力！”\n安人天子命，符节我所持[5]。\n州县忽乱亡，得罪复是谁？\n逋缓[6]违诏令，蒙责固其宜。\n前贤重守分，恶以祸福移。\n亦云贵守官[7]，不爱能适时。\n顾惟孱弱者，正直当不亏。\n何人采国风，吾欲献此辞。\n〔注〕[1]癸卯：唐代宗广德元年（763）。 [2]漫叟：元结号。 [3]贼：广德元年冬，“西原蛮”少数民族占领道州月余。“贼”是对“西原蛮”的诬称。 [4]征求符牒：征敛赋税的公文。[5]“符节”句：即受朝廷任命来做官。 [6]逋缓：指缓征租税。 [7]守官：指忠于职守。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 434, "title": "贼退示官吏并序", "author": "元结", "body": "癸卯岁，西原贼入道州，焚烧杀掠，几尽而去。明年，贼又攻永破邵，不犯此州边鄙而退。岂力能制敌欤？盖蒙其伤怜而已。诸使何为忍苦征敛？故作诗一篇以示官吏。\n昔岁逢太平，山林二十年。\n泉源在庭户，洞壑当门前。\n井税有常期，日晏犹得眠。\n忽然遭世变，数岁亲戎旃。\n今来典斯郡，山夷又纷然。\n城小贼不屠，人贫伤可怜。\n是以陷邻境，此州独见全。\n使臣将王命，岂不如贼焉？\n今被征敛者，迫之如火煎。\n谁能绝人命，以作时世贤？\n思欲委符节，引竿自刺船。\n将家就鱼麦，归老江湖边。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 435, "title": "欸乃曲五首（其二）", "author": "元结", "body": "湘江二月春水平，满月和风宜夜行。\n唱桡欲过平阳戍，守吏相呼问姓名。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 436, "title": "寒食", "author": "孟云卿", "body": "二月江南花满枝，他乡寒食远堪悲。\n贫居往往无烟火，不独明朝为子推。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 437, "title": "枫桥夜泊", "author": "张继", "body": "月落乌啼霜满天，江枫渔火对愁眠。\n姑苏城外寒山寺，夜半钟声到客船。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 438, "title": "省试[1]湘灵鼓瑟", "author": "钱起", "body": "善鼓云和瑟[2]，常闻帝子[3]灵。\n冯夷[4]空自舞，楚客不堪听。\n苦调凄金石，清音入杳冥[5]。\n苍梧来怨慕，白芷[6]动芳馨。\n流水传湘浦，悲风过洞庭。\n曲终人不见，江上数峰青。\n〔注〕[1]省试：唐时各州县贡士到京师由尚书省的礼部主试，通称省试。 [2]云和瑟：云和，古山名。《周礼·春官大司乐》:“云和之琴瑟。” [3]帝子：屈原《九歌》:“帝子降兮北渚。”注者多认为帝子是尧女，即舜妻。 [4]冯（píng）夷：传说中的河神名。见《后汉书·张衡传》注。《山海经》又作冰夷。 [5]杳冥：遥远的地方。 [6]白芷：伞形科草本植物，高四尺余，夏日开小白花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 439, "title": "赠阙下[1]裴舍人", "author": "钱起", "body": "二月黄鹂飞上林[2]，春城紫禁晓阴阴。\n长乐[3]钟声花外尽，龙池[4]柳色雨中深。\n阳和不散穷途恨，霄汉常悬捧日心。\n献赋十年犹未遇，羞将白发对华簪[5]。\n〔注〕[1]阙下：宫阙之下。指帝王所居之处。 [2]上林：即上林苑。汉武帝时据旧苑扩充修建的御苑。周围至二百多里，苑内放养禽兽，供皇帝射猎，并建离宫、观、馆数十处。故址在今陕西西安市西及周至、户县界。此处泛指宫苑。 [3]长乐：即长乐宫。西汉主要宫殿之一，在长安城内。这里借指唐代长安的宫殿。 [4]龙池：唐玄宗登位前王邸中的一个小湖，后王邸改为兴庆宫，玄宗常在此听政，日常起居也多在此。 [5]华簪：古人戴帽，为使帽子固定，便用簪子连帽穿结于发髻上。《唐书·车服志》:“毳冕者，三品之服也。七旒宝饰角簪导。”这些有装饰的簪，就是华簪。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 440, "title": "暮春归故山草堂", "author": "钱起", "body": "谷口春残黄鸟稀，辛夷花尽杏花飞。\n始怜幽竹山窗下，不改清阴待我归。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 441, "title": "归雁", "author": "钱起", "body": "潇湘何事等闲回？水碧沙明两岸苔。\n二十五弦弹夜月，不胜清怨却飞来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 442, "title": "春思二首（其一）", "author": "贾至", "body": "草色青青柳色黄，桃花历乱李花香。\n东风不为吹愁去，春日偏能惹恨长。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 443, "title": "初至巴陵与李十二白裴九同泛洞庭湖三首（其二）", "author": "贾至", "body": "枫岸纷纷落叶多，洞庭秋水晚来波。\n乘兴轻舟无近远，白云明月吊湘娥。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 444, "title": "巴陵夜别王八员外", "author": "贾至", "body": "柳絮飞时别洛阳，梅花发后到三湘[1]。\n世情已逐浮云散，离恨空随江水长。\n〔注〕[1]三湘：一说潇湘、资湘、沅湘，称为三湘。诗里泛指湘江流域，洞庭湖南北一带。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 445, "title": "柏林寺南望", "author": "郎士元", "body": "溪上遥闻精舍钟，泊舟微径度深松。\n青山霁后云犹在，画出西南四五峰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 446, "title": "听邻家吹笙", "author": "郎士元", "body": "凤吹声如隔彩霞，不知墙外是谁家。\n重门深锁无寻处，疑有碧桃千树花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 447, "title": "寒食", "author": "韩翃", "body": "春城无处不飞花，寒食东风御柳斜。\n日暮汉宫传蜡烛，轻烟散入五侯[1]家。\n〔注〕[1]五侯：一说指东汉外戚梁冀一族的五侯。另一说指东汉桓帝时的宦官单超等同日封侯的五人。诗中笼统指贵近宠臣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 448, "title": "宿石邑山中", "author": "韩翃", "body": "浮云不共此山齐，山霭苍苍望转迷。\n晓月暂飞高树里，秋河隔在数峰西。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 449, "title": "云阳馆与韩绅宿别", "author": "司空曙", "body": "故人江海别，几度隔山川。\n乍见翻疑梦，相悲各问年。\n孤灯寒照雨，湿竹暗浮烟。\n更有明朝恨，离杯惜共传。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 450, "title": "金陵怀古", "author": "司空曙", "body": "辇路江枫暗，宫庭野草春。\n伤心庾开府，老作北朝臣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 451, "title": "江村即事", "author": "司空曙", "body": "钓罢归来不系船，江村月落正堪眠。\n纵然一夜风吹去，只在芦花浅水边。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 452, "title": "喜外弟卢纶见宿", "author": "司空曙", "body": "静夜四无邻，荒居旧业贫。\n雨中黄叶树，灯下白头人。\n以我独沉久，愧君相见频。\n平生自有分，况是蔡家亲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 453, "title": "寻陆鸿渐不遇", "author": "皎然", "body": "移家虽带郭，野径入桑麻。\n近种篱边菊，秋来未著花。\n扣门无犬吠，欲去问西家。\n报道山中去，归来每日斜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 454, "title": "胡腾儿", "author": "李端", "body": "胡腾身是凉州儿，肌肤如玉鼻如锥。\n桐布轻衫前后卷，葡萄长带一边垂。\n帐前跪作本音语，拈襟摆袖为君舞。\n安西旧牧收泪看，洛下词人抄曲与。\n扬眉动目踏花毡，红汗交流珠帽偏。\n醉却东倾又西倒，双靴柔弱满灯前。\n环行急蹴皆应节，反手叉腰如却月。\n丝桐忽奏一曲终，呜呜画角城头发。\n胡腾儿，胡腾儿，家乡路断知不知？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 455, "title": "拜新月", "author": "李端", "body": "开帘见新月，即便下阶拜。\n细语人不闻，北风吹罗带。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 456, "title": "鸣筝", "author": "李端", "body": "鸣筝金粟柱，素手玉房前。\n欲得周郎顾，时时误拂弦。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 457, "title": "闺情", "author": "李端", "body": "月落星稀天欲明，孤灯未灭梦难成。\n披衣更向门前望，不忿朝来鹊喜声！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 458, "title": "咏绣障", "author": "胡令能", "body": "日暮堂前花蕊娇，争拈小笔上床描。\n绣成安向春园里，引得黄莺下柳条。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 459, "title": "小儿垂钓", "author": "胡令能", "body": "蓬头稚子学垂纶，侧坐莓苔草映身。\n路人借问遥招手，怕得鱼惊不应人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 460, "title": "丹阳送韦参军", "author": "严维", "body": "丹阳郭里送行舟，一别心知两地秋。\n日晚江南望江北，寒鸦飞尽水悠悠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 461, "title": "囝", "author": "顾况", "body": "囝[1]，哀闽也。\n囝生闽方，闽吏得之，乃绝其阳[2]。\n为臧为获[3]，致金满屋。\n为髡为钳[4]，如视草木。\n天道无知，我罹其毒。\n神道无知，彼受其福。\n郎罢别囝，吾悔生汝。\n及汝既生，人劝不举[5]。\n不从人言，果获是苦。\n囝别郎罢，心摧血下。\n隔地绝天，及至黄泉，不得在郎罢前。\n〔注〕[1]诗人自注：“‘囝’，音蹇。闽俗呼子为‘囝’，父为‘郎罢’。” [2]绝：割断。阳：男性生殖器。 [3]臧、获：都是奴隶的别称。 [4]髡、钳：都是奴隶的标志。髡，剃去头发；钳，铁圈套在颈上。 [5]不举：不养育。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 462, "title": "公子行", "author": "顾况", "body": "轻薄儿，面如玉，紫陌春风缠马足。\n双镫悬金缕鹘飞，长衫刺雪生犀束。\n绿槐夹道阴初成，珊瑚几节敌流星。\n红肌拂拂酒光狞，当街背拉金吾行。\n朝游鼕鼕鼓声发，暮游鼕鼕鼓声绝。\n入门不肯自升堂，美人扶踏金阶月。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 463, "title": "过山农家[1]", "author": "顾况", "body": "板桥人渡泉声，茅檐日午鸡鸣。\n莫嗔[2]焙茶烟暗，却喜晒谷天晴。\n〔注〕[1]一作张继诗，题为《山家》。 [2]嗔（chēn）：嫌怨。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 464, "title": "题红叶", "author": "宣宗宫人", "body": "流水何太急，深宫尽日闲。\n殷勤谢红叶，好去到人间。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 465, "title": "夏夜宿表兄话旧", "author": "窦叔向", "body": "夜合花开香满庭，夜深微雨醉初醒。\n远书珍重何曾达，旧事凄凉不可听。\n去日儿童皆长大，昔年亲友半凋零。\n明朝又是孤舟别，愁见河桥酒幔青。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 466, "title": "军城早秋", "author": "严武", "body": "昨夜秋风入汉关，朔云边月满西山。\n更催飞将追骄虏，莫遣沙场匹马还。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 467, "title": "江南行", "author": "张潮", "body": "茨菰叶烂别西湾，莲子花开不见还。\n妾梦不离江上水，人传郎在凤凰山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 468, "title": "春山夜月", "author": "于良史", "body": "春山多胜事，赏玩夜忘归。\n掬水月在手，弄花香满衣。\n兴来无远近，欲去惜芳菲。\n南望鸣钟处，楼台深翠微。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 469, "title": "听筝", "author": "柳中庸", "body": "抽弦促柱听秦筝，无限秦人悲怨声。\n似逐春风知柳态，如随啼鸟识花情。\n谁家独夜愁灯影？何处空楼思月明？\n更入几重离别恨，江南歧路洛阳城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 470, "title": "征人怨", "author": "柳中庸", "body": "岁岁金河复玉关，朝朝马策与刀环。\n三春白雪归青冢，万里黄河绕黑山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 471, "title": "除夜宿石头驿", "author": "戴叔伦", "body": "旅馆谁相问？寒灯独可亲。\n一年将尽夜，万里未归人。\n寥落悲前事，支离笑此身。\n愁颜与衰鬓，明日又逢春。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 472, "title": "三闾庙", "author": "戴叔伦", "body": "沅湘流不尽，屈子怨何深！\n日暮秋风起，萧萧枫树林。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 473, "title": "淮上喜会梁州故人", "author": "韦应物", "body": "江汉曾为客，相逢每醉还。\n浮云一别后，流水十年间。\n欢笑情如旧，萧疏鬓已斑。\n何因不归去？淮上有秋山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 474, "title": "自巩洛舟行入黄河即事寄府县僚友", "author": "韦应物", "body": "夹水苍山路向东，东南山豁大河通。\n寒树依微远天外，夕阳明灭乱流中。\n孤村几岁临伊岸，一雁初晴下朔风。\n为报洛桥游宦侣，扁舟不系与心同。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 475, "title": "初发扬子寄元大校书[1]", "author": "韦应物", "body": "凄凄去亲爱，泛泛入烟雾。\n归棹洛阳人，残钟广陵树[2]。\n今朝此为别，何处还相遇？\n世事波上舟，沿洄安得住！\n〔注〕[1]扬子：当指扬子津，在长江北岸，近瓜洲。校书：官名。唐代的校书郎，掌管校勘书籍，订正讹误。 [2]广陵：扬州的古称。在唐代，由扬州经运河可以直达洛阳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 476, "title": "淮上即事寄广陵亲故", "author": "韦应物", "body": "前舟已眇眇，欲渡谁相待？\n秋山起暮钟，楚雨连沧海。\n风波离思满，宿昔容鬓改。\n独鸟下东南，广陵何处在？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 477, "title": "登楼寄王卿", "author": "韦应物", "body": "踏阁攀林恨不同，楚云沧海思无穷。\n数家砧杵秋山下，一郡荆榛寒雨中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 478, "title": "寄李儋元锡", "author": "韦应物", "body": "去年花里逢君别，今日花开已一年。\n世事茫茫难自料，春愁黯黯独成眠。\n身多疾病思田里，邑有流亡愧俸钱。\n闻道欲来相问讯，西楼望月几回圆。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 479, "title": "寄全椒[1]山中道士", "author": "韦应物", "body": "今朝郡斋冷，忽念山中客。\n涧底束荆薪，归来煮白石[2]。\n欲持一瓢酒，远慰风雨夕。\n落叶满空山，何处寻行迹？\n〔注〕[1]全椒：县名。在安徽省东部、滁河上游。 [2]煮白石：道家有“煮五石英法”，在斋戒后的农历九月九日，将薤白、黑芝麻、白蜜、山泉水和白石英放进锅里熬煮。（见《云笈七籤》卷七十四）", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 480, "title": "寒食寄京师诸弟", "author": "韦应物", "body": "雨中禁火空斋冷，江上流莺独坐听。\n把酒看花想诸弟，杜陵寒食草青青。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 481, "title": "秋夜寄邱二十二员外", "author": "韦应物", "body": "怀君属秋夜，散步咏凉天。\n山空松子落，幽人应未眠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 482, "title": "赋得暮雨送李曹", "author": "韦应物", "body": "楚江微雨里，建业暮钟时。\n漠漠帆来重，冥冥鸟去迟。\n海门深不见，浦树远含滋。\n相送情无限，沾襟比散丝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 483, "title": "长安遇冯著", "author": "韦应物", "body": "客从东方来，衣上灞陵雨。\n问客何为来？采山因买斧。\n冥冥花正开，飏飏燕新乳。\n昨别今已春，鬓丝生几缕？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 484, "title": "幽居", "author": "韦应物", "body": "贵贱虽异等，出门皆有营。\n独无外物牵，遂此幽居情。\n微雨夜来过，不知春草生。\n青山忽已曙，鸟雀绕舍鸣。\n时与道人偶，或随樵者行。\n自当安蹇劣，谁谓薄世荣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 485, "title": "滁州西涧", "author": "韦应物", "body": "独怜幽草涧边生，上有黄鹂深树鸣。\n春潮带雨晚来急，野渡无人舟自横。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 486, "title": "闻雁", "author": "韦应物", "body": "故园眇[1]何处？归思方悠哉。\n淮南秋雨夜，高斋闻雁来。\n〔注〕[1]眇：通“渺”，辽远。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 487, "title": "逢病军人", "author": "卢纶", "body": "行多有病住无粮，万里还乡未到乡。\n蓬鬓哀吟古城下，不堪秋气入金疮。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 488, "title": "塞下曲六首（其二）", "author": "卢纶", "body": "林暗草惊风，将军夜引弓。\n平明寻白羽，没在石棱中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 489, "title": "塞下曲六首（其三）", "author": "卢纶", "body": "月黑雁飞高，单于夜遁逃。\n欲将轻骑逐，大雪满弓刀。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 490, "title": "晚次鄂州", "author": "卢纶", "body": "云开远见汉阳城，犹是孤帆一日程。\n估客昼眠知浪静，舟人夜语觉潮生。\n三湘衰鬓逢秋色，万里归心对月明。\n旧业已随征战尽，更堪江上鼓鼙声！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 491, "title": "送李端", "author": "卢纶", "body": "故关衰草遍，离别自堪悲。\n路出寒云外，人归暮雪时。\n少孤为客早，多难识君迟。\n掩泪空相向，风尘何处期？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 492, "title": "竹窗闻风寄苗发司空曙", "author": "李益", "body": "微风惊暮坐，临牖思悠哉。\n开门复动竹，疑是故人来。\n时滴枝上露，稍沾阶下苔。\n何当一入幌，为拂绿琴埃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 493, "title": "喜见外弟又言别", "author": "李益", "body": "十年离乱后，长大一相逢。\n问姓惊初见，称名忆旧容。\n别来沧海事，语罢暮天钟。\n明日巴陵道，秋山又几重。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 494, "title": "过五原胡儿饮马泉", "author": "李益", "body": "绿杨著水草如烟，旧是胡儿饮马泉[1]。\n几处吹笳明月夜，何人倚剑白云天。\n从来冻合关山路，今日分流汉使前。\n莫遣行人照容鬓，恐惊憔悴入新年。\n〔注〕[1]诗原注：鹈泉在丰州城北，胡人饮马于此。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 495, "title": "立秋前一日览镜", "author": "李益", "body": "万事销身外，生涯在镜中。\n惟将两鬓雪，明日对秋风。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 496, "title": "鹧鸪词", "author": "李益", "body": "湘江斑竹枝，锦翅鹧鸪飞。\n处处湘云合，郎从何处归？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 497, "title": "洛桥", "author": "李益", "body": "金谷园中柳，春来似舞腰。\n那堪好风景，独上洛阳桥。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 498, "title": "度破讷沙二首（其二）", "author": "李益", "body": "破讷沙头雁正飞，鹈泉上战初归。\n平明日出东南地，满碛寒光生铁衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 499, "title": "汴河曲", "author": "李益", "body": "汴水东流无限春，隋家宫阙已成尘。\n行人莫上长堤望，风起杨花愁杀人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 500, "title": "塞下曲四首（其一）", "author": "李益", "body": "蕃州部落能结束，朝暮驰猎黄河曲。\n燕歌未断塞鸿飞，牧马群嘶边草绿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 501, "title": "边思", "author": "李益", "body": "腰垂锦带佩吴钩，走马曾防玉塞秋。\n莫笑关西将家子，只将诗思入凉州。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 502, "title": "从军北征", "author": "李益", "body": "天山雪后海风寒，横笛遍吹《行路难》。\n碛里征人三十万，一时回首月中看。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 503, "title": "听晓角", "author": "李益", "body": "边霜昨夜堕关榆，吹角当城汉月孤。\n无限塞鸿飞不度，秋风卷入《小单于》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 504, "title": "宫怨", "author": "李益", "body": "露湿晴花春殿香，月明歌吹在昭阳。\n似将海水添宫漏，共滴长门一夜长。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 505, "title": "诣红楼院寻广宣不遇留题", "author": "李益", "body": "柿叶翻红霜景秋，碧天如水倚红楼。\n隔窗爱竹无人问，遣向邻房觅户钩。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 506, "title": "春夜闻笛", "author": "李益", "body": "寒山吹笛唤春归，迁客相看泪满衣。\n洞庭一夜无穷雁，不待天明尽北飞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 507, "title": "行舟", "author": "李益", "body": "柳花飞入正行舟，卧引菱花信碧流。\n闻道风光满扬子，天晴共上望乡楼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 508, "title": "隋宫燕", "author": "李益", "body": "燕语如伤旧国春，宫花旋落已成尘。\n自从一闭风光后，几度飞来不见人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 509, "title": "上汝州郡楼", "author": "李益", "body": "黄昏鼓角似边州，三十年前上此楼。\n今日山川对垂泪，伤心不独为悲秋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 510, "title": "写情", "author": "李益", "body": "水纹珍簟思悠悠，千里佳期一夕休。\n从此无心爱良夜，任他明月下西楼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 511, "title": "夜上受降城[1]闻笛", "author": "李益", "body": "回乐烽前沙似雪[2]，受降城外月如霜。\n不知何处吹芦管，一夜征人尽望乡。\n〔注〕[1]贞观二十年（646），唐太宗曾亲临灵州接受突厥一部的投降，“受降城”之名即由此而来。《宋史·张舜民传》仍沿袭唐时称呼，把灵州呼作受降城。历来注家对李益此诗中“受降城”的所在地虽然说法不一，但都认为是指唐代朔方道大总管张仁愿所筑的东、西、中三受降城中的西城。考之记载，三受降城都在今内蒙古自治区境内黄河的北面，西城在临河，与唐太宗受降的灵州了不相涉。 [2]回乐烽：一作“回乐峰”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 512, "title": "江南曲", "author": "李益", "body": "嫁得瞿塘贾，朝朝误妾期。\n早知潮有信，嫁与弄潮儿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 513, "title": "江南曲", "author": "于鹄", "body": "偶向江边采白蘋, 还随女伴赛江神[1]。\n众中不敢分明语，暗掷金钱[2]卜远人。\n〔注〕[1]赛江神：旧俗用仪仗、鼓乐、杂戏迎神出会，周游街巷。届时村民游观，商贩云集，引为喜庆，谓之“迎神赛会”。“赛江神”即为其中之一。 [2]掷金钱：民间迷信的一种，以钱币占卜，其法不一。大抵于祷祝之后，以抛掷金钱的向背排列次序推断吉凶。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 514, "title": "巴女谣", "author": "于鹄", "body": "巴女骑牛唱《竹枝》[1]，藕丝菱叶傍江时。\n不愁日暮还家错，记得芭蕉出槿篱。\n〔注〕[1]《竹枝》：巴渝一带的民歌。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 515, "title": "游子吟", "author": "孟郊", "body": "慈母手中线，游子身上衣。\n临行密密缝，意恐迟迟归。\n谁言寸草心，报得三春晖！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 516, "title": "怨诗", "author": "孟郊", "body": "试妾与君泪，两处滴池水。\n看取芙蓉花，今年为谁死！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 517, "title": "巫山曲", "author": "孟郊", "body": "巴江上峡重复重，阳台碧峭十二峰。\n荆王猎时逢暮雨，夜卧高丘梦神女。\n轻红流烟湿艳姿，行云飞去明星稀。\n目极魂断望不见，猿啼三声泪滴衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 518, "title": "古别离", "author": "孟郊", "body": "欲别牵郎衣，“郎今到何处？\n不恨归来迟，莫向临邛去！”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 519, "title": "古怨别", "author": "孟郊", "body": "飒飒秋风生，愁人怨离别。\n含情两相向，欲语气先咽。\n心曲千万端，悲来却难说。\n别后唯所思，天涯共明月。\n这是一首描写情人离愁的诗歌。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 520, "title": "登科后", "author": "孟郊", "body": "昔日龌龊[1]不足夸，今朝放荡[2]思无涯。\n春风得意马蹄疾，一日看尽长安花。\n〔注〕[1]龌龊：指处境之不如意和思想上的拘谨局促，与今北方方言“窝囊”义近。[2]放荡：意谓自由自在，无所拘束，与“旷荡”（一本“放荡”即作“旷荡”）、“放达”义近。但不同于现代的“放浪”的意思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 521, "title": "秋怀（其二）", "author": "孟郊", "body": "秋月颜色冰，老客志气单。\n冷露滴梦破，峭风梳骨寒。\n席上印病文，肠中转愁盘。\n疑虑无所凭，虚听多无端。\n梧桐枯峥嵘，声响如哀弹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 522, "title": "游终南山", "author": "孟郊", "body": "南山塞天地，日月石上生。\n高峰夜留景，深谷昼未明。\n山中人自正，路险心亦平。\n长风驱松柏，声拂万壑清。\n即此悔读书，朝朝近浮名。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 523, "title": "洛桥晚望", "author": "孟郊", "body": "天津桥[1]下冰初结，洛阳陌上人行绝；\n榆柳萧疏楼阁闲，月明直见嵩山雪。\n〔注〕[1]天津桥：即洛桥，在今河南洛阳西南洛水之上。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 524, "title": "观祈雨", "author": "李约", "body": "桑条无叶土生烟，箫管迎龙水庙前。\n朱门几处看歌舞，犹恐春阴咽管弦。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 525, "title": "从军行", "author": "陈羽", "body": "海[1]畔风吹冻泥裂，梧桐叶落枝梢折。\n横笛闻声不见人，红旗直上天山雪。\n〔注〕[1]海：指湖泊。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 526, "title": "和练秀才杨柳", "author": "杨巨源", "body": "水边杨柳曲尘丝，立马烦君折一枝。\n惟有春风最相惜，殷勤更向手中吹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 527, "title": "城东早春", "author": "杨巨源", "body": "诗家清景在新春，绿柳才黄半未匀。\n若待上林花似锦，出门俱是看花人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 528, "title": "春兴", "author": "武元衡", "body": "杨柳阴阴细雨晴，残花落尽见流莺。\n春风一夜吹乡梦，又逐春风到洛城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 529, "title": "赠道者", "author": "武元衡", "body": "麻衣如雪一枝梅，笑掩微妆入梦来。\n若到越溪逢越女，红莲池里白莲开。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 530, "title": "登鹳雀楼[1]", "author": "畅诸", "body": "城楼多峻极[2]，列酌恣登攀[3]。\n迥临飞鸟上，高谢世尘间[4]。\n天势围平野，河流入断山。\n今年菊花事[5]，并是送君还。\n〔注〕[1]题一作《登观鹊楼》，此从《全唐诗》。 [2]峻极：极高。晋葛洪《抱朴子·知止》:“嵩岱不托地，则不能竦峻极，概云霄。” [3]列酌：指宴集饮酒。酌，酒杯。《楚辞·招魂》:“华酌既陈，有琼浆些。” [4]“迥临”两句：一作“迥林飞鸟上，高榭代人间。” [5]菊花事：古时重阳日有赏菊、饮菊花酒等风俗。梁宗懔《荆楚岁月记》:“九月九日宴会，未知起于何代。……今北人亦重此节，佩茱萸，食饵，饮菊花酒，云令人长寿。”唐孟浩然《过故人庄》诗：“待到重阳日，还来就菊花。”这里泛指重阳节登高、饮酒、赏菊诸事。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 531, "title": "奉诚园闻笛", "author": "窦牟", "body": "曾绝朱缨吐锦茵，欲披荒草访遗尘。\n秋风忽洒西园泪，满目山阳笛里人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 532, "title": "画石", "author": "刘商", "body": "苍藓千年粉绘传，坚贞一片色犹全。\n那知忽遇非常用，不把分铢补上天！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 533, "title": "题都城南庄", "author": "崔护", "body": "去年今日此门中，人面桃花相映红。\n人面不知何处去，桃花依旧笑春风。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 534, "title": "岭上逢久别者又别", "author": "权德舆", "body": "十年曾一别，征路此相逢。\n马首向何处？夕阳千万峰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 535, "title": "玉台体十二首（其十一）", "author": "权德舆", "body": "昨夜裙带解，今朝蟢子飞。\n铅华[1]不可弃，莫是藁砧[2]归！\n〔注〕[1]铅华：铅粉，此指粉黛之类的化妆品。 [2]藁砧：本是切草砧石，切草要用鈇（同“斧”），“鈇”与“夫”同音，故六朝人把藁砧作为代指丈夫的隐语。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 536, "title": "宿王昌龄隐居", "author": "常建", "body": "清溪深不测，隐处唯孤云。\n松际露微月，清光犹为君。\n茅亭宿花影，药院滋苔纹。\n余亦谢时去，西山鸾鹤群。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 537, "title": "题破山寺后禅院", "author": "常建", "body": "清晨入古寺，初日照高林。\n竹径通幽处，禅房花木深。\n山光悦鸟性，潭影空人心。\n万籁此俱寂，但馀钟磬音。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 538, "title": "三日寻李九庄", "author": "常建", "body": "雨歇杨林东渡头，永和三日荡轻舟。\n故人家在桃花岸，直到门前溪水流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 539, "title": "塞下曲四首（其一）", "author": "常建", "body": "玉帛朝回望帝乡，乌孙归去不称王。\n天涯静处无征战，兵气销为日月光。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 540, "title": "野老歌", "author": "张籍", "body": "老农家贫在山住，耕种山田三四亩。\n苗疏税多不得食，输入官仓化为土。\n岁暮锄犁傍空室，呼儿登山收橡实。\n西江贾客珠百斛，船中养犬长食肉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 541, "title": "猛虎行", "author": "张籍", "body": "南山北山树冥冥，猛虎白日绕村行。\n向晚一身当道食，山中麋鹿尽无声。\n年年养子在深谷，雌雄上下不相逐。\n谷中近窟有山村，长向村家取黄犊。\n五陵年少不敢射，空来林下看行迹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 542, "title": "牧童词", "author": "张籍", "body": "远牧牛，绕村四面禾黍稠。\n陂中饥鸟啄牛背，令我不得戏垅头。\n入陂草多牛散行，白犊时向芦中鸣。\n隔堤吹叶应同伴，还鼓长鞭三四声：\n“牛牛食草莫相触，官家截尔头上角！”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 543, "title": "节妇吟", "author": "张籍", "body": "君知妾有夫，赠妾双明珠；\n感君缠绵意，系在红罗襦。\n妾家高楼连苑起，良人执戟明光里。\n知君用心如日月，事夫誓拟同生死。\n还君明珠双泪垂，恨不相逢未嫁时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 544, "title": "湘江曲", "author": "张籍", "body": "湘水无潮秋水阔，湘中月落行人发。\n送人发，送人归，白蘋茫茫鹧鸪飞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 545, "title": "成都曲", "author": "张籍", "body": "锦江近西烟水绿，新雨山头荔枝熟。\n万里桥边多酒家，游人爱向谁家宿？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 546, "title": "夜到渔家", "author": "张籍", "body": "渔家在江口，潮水入柴扉。\n行客欲投宿，主人犹未归。\n竹深村路远，月出钓船稀。\n遥见寻沙岸，春风动草衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 547, "title": "秋思", "author": "张籍", "body": "洛阳城里见秋风，欲作家书意万重。\n复恐匆匆说不尽，行人临发又开封。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 548, "title": "凉州[1]词三首（其一）", "author": "张籍", "body": "边城暮雨雁飞低，芦笋初生渐欲齐。\n无数铃声遥过碛，应驮白练到安西[2]。\n〔注〕[1]凉州：州名。唐时辖境在今甘肃永昌以东，天祝以西一带。公元八世纪后期至九世纪中叶曾属吐蕃。 [2]安西：唐代六都护府之一。开元六年（718）安西都护府统辖境内龟兹、焉耆、于阗、疏勒等地，贞元六年（790）以后，以辖境尽入叶蕃而废弃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 549, "title": "江馆", "author": "王建", "body": "水面细风生，菱歌慢慢声。\n客亭临小市，灯火夜妆明。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 550, "title": "望夫石", "author": "王建", "body": "望夫处，江悠悠。化为石，不回头。\n山头日日风复雨，行人归来石应语。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 551, "title": "水夫谣", "author": "王建", "body": "苦哉生长当驿边，官家使我牵驿船。\n辛苦日多乐日少，水宿沙行如海鸟。\n逆风上水万斛重，前驿迢迢后淼淼。\n半夜缘堤雪和雨，受他驱遣还复去。\n夜寒衣湿披短蓑，臆穿足裂忍痛何！\n到明辛苦无处说，齐声腾踏牵船歌。\n一间茅屋何所值，父母之乡去不得。\n我愿此水作平田，长使水夫不怨天。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 552, "title": "羽林行", "author": "王建", "body": "长安恶少出名字，楼下劫商楼上醉。\n天明下直明光宫，散入五陵松柏中。\n百回杀人身合死，赦书尚有收城功。\n九衢一日消息定，乡吏籍中重改姓。\n出来依旧属羽林，立在殿前射飞禽。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 553, "title": "新嫁娘词三首（其一）", "author": "王建", "body": "三日入厨下，洗手作羹汤。\n未谙姑食性，先遣小姑尝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 554, "title": "雨过山村", "author": "王建", "body": "雨里鸡鸣一两家，竹溪村路板桥斜。\n妇姑相唤浴蚕去，闲着中庭栀子花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 555, "title": "赠李愬仆射二首（其一）", "author": "王建", "body": "和雪翻营一夜行，神旗冻定马无声。\n遥看火号连营赤，知是先锋已上城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 556, "title": "江陵使至汝州", "author": "王建", "body": "回看巴路在云间，寒食离家麦熟还。\n日暮数峰青似染，商人说是汝州山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 557, "title": "十五夜望月", "author": "王建", "body": "中庭地白树栖鸦，冷露无声湿桂花。\n今夜月明人尽望，不知秋思落谁家？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 558, "title": "宫词一百首（其九十）", "author": "王建", "body": "树头树底觅残红，一片西飞一片东。\n自是桃花贪结子，错教人恨五更风。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 559, "title": "牡丹", "author": "薛涛", "body": "去春零落暮春时，泪湿红笺怨别离。\n常恐便同巫峡散，因何重有武陵期？\n传情每向馨香得，不语还应彼此知。\n只欲栏边安枕席，夜深闲共说相思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 560, "title": "送友人", "author": "薛涛", "body": "水国蒹葭夜有霜，月寒山色共苍苍。\n谁言千里自今夕，离梦杳如关塞长。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 561, "title": "筹边楼", "author": "薛涛", "body": "平临云鸟八窗秋，壮压西川四十州[1]。\n诸将莫贪羌族马，最高层处见边头！\n〔注〕[1]《新唐书》卷四十二《地理志》六：“剑南道……为府一，都护府一，州三十八，县百八十九。”这里的“四十州”，是举其成数言之。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 562, "title": "山石", "author": "韩愈", "body": "山石荦确[1]行径微，黄昏到寺蝙蝠飞。\n升堂坐阶新雨足，芭蕉叶大栀子肥。\n僧言古壁佛画好，以火来照所见稀。\n铺床拂席置羹饭，疏粝亦足饱我饥。\n夜深静卧百虫绝，清月出岭光入扉。\n天明独去无道路，出入高下穷烟霏。\n山红涧碧纷烂漫，时见松枥皆十围。\n嗟哉吾党二三子，安得至老不更归！\n人生如此自可乐，岂必局束为人鞿[2]？\n当流赤足踏涧石，水声激激风吹衣。\n〔注〕[1]荦（luò）确：山石不平的样子。 [2]鞿（jī）：马缰绳。比喻受人牵制、束缚。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 563, "title": "雉带箭", "author": "韩愈", "body": "原头火烧静兀兀，野雉畏鹰出复没。\n将军欲以巧伏人，盘马弯弓惜不发。\n地形渐窄观者多，雉惊弓满劲箭加。\n冲人决起百馀尺，红翎白镞随倾斜。\n将军仰笑军吏贺，五色离披马前堕。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 564, "title": "八月十五日夜赠张功曹", "author": "韩愈", "body": "纤云四卷天无河，清风吹空月舒波。\n沙平水息声影绝，一杯相属君当歌。\n君歌声酸辞且苦，不能听终泪如雨：\n“洞庭连天九疑高，蛟龙出没猩鼯号。\n十生九死到官所，幽居默默如藏逃。\n下床畏蛇食畏药，海气湿蛰熏腥臊。\n昨者州前捶大鼓，嗣皇继圣登夔皋。\n赦书一日行万里，罪从大辟皆除死。\n迁者追回流者还，涤瑕荡垢清朝班。\n州家申名使家抑，坎轲只得移荆蛮。\n判司卑官不堪说，未免捶楚尘埃间。\n同时辈流多上道，天路幽险难追攀。”\n君歌且休听我歌，我歌今与君殊科：\n“一年明月今宵多，人生由命非由他，\n有酒不饮奈明何！”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 565, "title": "谒衡岳庙遂宿岳寺题门楼", "author": "韩愈", "body": "五岳祭秩皆三公，四方环镇嵩当中。\n火维地荒足妖怪，天假神柄专其雄。\n喷云泄雾藏半腹，虽有绝顶谁能穷？\n我来正逢秋雨节，阴气晦昧无清风。\n潜心默祷若有应，岂非正直能感通。\n须臾静扫众峰出，仰见突兀撑青空。\n紫盖连延接天柱，石廪腾掷堆祝融。\n森然魄动下马拜，松柏一径趋灵宫。\n粉墙丹柱动光彩，鬼物图画填青红。\n升阶伛偻荐脯酒，欲以菲薄明其衷。\n庙令老人识神意，睢盱侦伺能鞠躬。\n手持杯珓导我掷，云此最吉馀难同。\n窜逐蛮荒幸不死，衣食才足甘长终。\n侯王将相望久绝，神纵欲福难为功。\n夜投佛寺上高阁，星月掩映云朣胧。\n猿鸣钟动不知曙，杲杲寒日生于东。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 566, "title": "李花赠张十一署", "author": "韩愈", "body": "江陵城西二月尾，花不见桃惟见李。\n风揉雨练雪羞比，波涛翻空杳无涘。\n君知此处花何似？\n白花倒烛天夜明，群鸡惊鸣官吏起。\n金乌海底初飞来，朱辉散射青霞开。\n迷魂乱眼看不得，照耀万树繁如堆。\n念昔少年著游燕，对花岂省曾辞杯？\n自从流落忧感集，欲去未到思先回。\n只今四十已如此，后日更老谁论哉？\n力携一樽独就醉，不忍虚掷委黄埃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 567, "title": "青青水中蒲三首", "author": "韩愈", "body": "青青水中蒲[1]，下有一双鱼。\n君今上陇去，我在与谁居？\n青青水中蒲，长在水中居。\n寄语浮萍草，相随我不如。\n青青水中蒲，叶短不出水。\n妇人不下堂，行子在万里。\n〔注〕[1]蒲：即香蒲。有匍匐横生的地下根状茎，由此发生新芽，叶细长而尖，“春初生嫩叶，出水时红白色，茸茸然”（明李时珍《本草纲目·草部》）。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 568, "title": "听颖师弹琴", "author": "韩愈", "body": "昵昵儿女语[1]，恩怨相尔汝[2]。\n划然变轩昂，勇士赴敌场。\n浮云柳絮无根蒂，天地阔远随飞扬。\n喧啾百鸟群，忽见孤凤凰。\n跻攀分寸不可上，失势一落千丈强。\n嗟余有两耳，未省听丝篁。\n自闻颖师弹，起坐在一旁。\n推手遽止之，湿衣泪滂滂。\n颖乎尔诚能，无以冰炭置我肠！\n〔注〕[1]昵昵：象声词，用来形容言辞亲切。此据李汉编《韩昌黎集》，别本亦作“妮妮”或“呢呢”。 [2]尔汝：对话时你来我去，不讲客套，是关系亲密的表现。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 569, "title": "调张籍", "author": "韩愈", "body": "李杜文章在，光焰万丈长。\n不知群儿愚，那用故谤伤！\n蚍蜉撼大树，可笑不自量。\n伊我生其后，举颈遥相望。\n夜梦多见之，昼思反微茫。\n徒观斧凿痕，不瞩治水航。\n想当施手时，巨刃磨天扬。\n垠崖划崩豁，乾坤摆雷硠。\n惟此两夫子，家居率荒凉。\n帝欲长吟哦，故遣起且僵。\n剪翎送笼中，使看百鸟翔。\n平生千万篇，金薤垂琳琅。\n仙官敕六丁，雷电下取将。\n流落人间者，太山一毫芒。\n我愿生两翅，捕逐出八荒。\n精诚忽交通，百怪入我肠。\n刺手拔鲸牙，举瓢酌天浆。\n腾身跨汗漫，不着织女襄。\n顾语地上友：经营无太忙！\n乞君飞霞佩，与我高颉颃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 570, "title": "答张十一", "author": "韩愈", "body": "山净江空水见沙，哀猿啼处两三家。\n筼筜竞长纤纤笋，踯躅闲开艳艳花。\n未报恩波知死所，莫令炎瘴送生涯。\n吟君诗罢看双鬓，斗觉霜毛一半加。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 571, "title": "题木居士二首（其一）", "author": "韩愈", "body": "火透波穿不计春，根如头面干如身。\n偶然题作木居士，便有无穷求福人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 572, "title": "湘中", "author": "韩愈", "body": "猿愁鱼踊水翻波，自古流传是汨罗。\n蘋藻[1]满盘无处奠，空闻渔父扣舷歌。\n〔注〕[1]蘋藻：《诗经·召南·采蘋》写祭祀情况，蘋藻都是祭物：“于以采蘋”、“于以采藻”、“于以奠之”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 573, "title": "春雪", "author": "韩愈", "body": "新年都未有芳华，二月初惊见草芽。\n白雪却嫌春色晚，故穿庭树作飞花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 574, "title": "晚春", "author": "韩愈", "body": "草树知春不久归，百般红紫斗芳菲。\n杨花榆荚无才思，惟解漫天作雪飞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 575, "title": "游太平公主山庄", "author": "韩愈", "body": "公主当年欲占春，故将台榭压城闉[1]。\n欲知前面花多少，直到南山不属人。\n〔注〕[1]闉（īn）：古代城门外层的曲城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 576, "title": "次潼关先寄张十二阁老使君", "author": "韩愈", "body": "荆山已去华山来，日出潼关四扇开。\n刺史莫辞迎候远，相公新破蔡州回。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 577, "title": "左迁至蓝关示侄孙湘", "author": "韩愈", "body": "一封朝奏九重天，夕贬潮州路八千。\n欲为圣明除弊事，肯将衰朽惜残年！\n云横秦岭家何在？雪拥蓝关马不前。\n知汝远来应有意，好收吾骨瘴江边。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 578, "title": "同水部张员外籍曲江春游寄白二十二舍人", "author": "韩愈", "body": "漠漠轻阴晚自开，青天[1]白日映楼台。\n曲江水满花千树，有底忙时不肯来？\n〔注〕[1]青天：一本作“青春”。现据《全唐诗》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 579, "title": "早春呈水部张十八员外二首（其一）", "author": "韩愈", "body": "天街小雨润如酥，草色遥看近却无。\n最是一年春好处，绝胜烟柳满皇都。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 580, "title": "春闺思", "author": "张仲素", "body": "袅袅城边柳，青青陌上桑。\n提笼忘采叶，昨夜梦渔阳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 581, "title": "秋夜曲", "author": "张仲素", "body": "丁丁漏水夜何长，漫漫轻云露月光。\n秋逼暗虫通夕响，征衣未寄莫飞霜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 582, "title": "秋闺思二首", "author": "张仲素", "body": "碧窗斜月[1]蔼深晖，愁听寒螀[2]泪湿衣。\n梦里分明见关塞，不知何路向金微。\n秋天一夜静无云，断续鸿声到晓闻，\n欲寄征衣问消息，居延城外又移军。\n〔注〕[1]碧窗斜月：一作“碧窗斜日”。联系全篇来看，似以“月”字为佳。 [2]螀（jiāng蝉类。寒螀，寒蝉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 583, "title": "燕子楼", "author": "张仲素", "body": "楼上残灯伴晓霜，独眠人起合欢床。\n相思一夜情多少，地角天涯未是长。\n北邙松柏锁愁烟，燕子楼中思悄然。\n自埋剑履歌尘散，红袖香销已十年。\n适看鸿雁洛阳回，又睹玄禽逼社来。\n瑶瑟玉箫无意绪，任从蛛网任从灰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 584, "title": "秋思赠远二首", "author": "王涯", "body": "当年只自守空帷，梦里关山觉别离。\n不见乡书传雁足，惟看新月吐蛾眉。\n厌攀杨柳临清阁，闲采芙蕖傍碧潭。\n走马台边人不见，拂云堆畔战初酣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 585, "title": "刘郎浦[1]口号", "author": "吕温", "body": "吴蜀成婚此水浔[2]，明珠步障幄[3]黄金。\n谁将一女轻天下，欲换刘郎鼎峙[4]心？\n〔注〕[1]刘郎浦：又称刘郎洑。其地在今湖北石首县。 [2]浔：水边。 [3]步障：古代贵族出行时用来遮蔽风尘的幕布。幄：室内的帐子。 [4]鼎峙：像鼎的三足峙立。这里指魏、蜀、吴三国。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 586, "title": "插田歌", "author": "刘禹锡", "body": "连州城下，俯接村墟。偶登郡楼，适有所感。遂书其事为俚歌，以俟采诗者。\n冈头花草齐，燕子东西飞。\n田塍望如线，白水光参差。\n农妇白纻裙，农父绿蓑衣。\n齐唱郢中歌，嘤咛如竹枝。\n但闻怨响音，不辨俚语词。\n时时一大笑，此必相嘲嗤。\n水平苗漠漠，烟火生墟落。\n黄犬往复还，赤鸡鸣且啄。\n路旁谁家郎，乌帽衫袖长。\n自言上计吏[1]，年幼离帝乡。\n田夫语计吏： “君家侬定谙。\n一来长安道，眼大不相参。”\n计吏笑致辞： “长安真大处，\n省门[2]高轲峨，侬入无度数。\n昨来补卫士[3]，惟用筒竹布[4]。\n君看二三年，我作官人去。”\n〔注〕[1]上计吏：亦可简称“上计”或“计吏”，地方政府派到中央政府办公事的书吏。[2]省门：指宫禁或官署的门。汉代宫中称为“省中”，宫门称为“省闼”。“省”又是官署名。唐有尚书、门下、中书、秘书、殿中、内侍六省。 [3]补卫士：指姓名补进禁军的缺额。 [4]筒竹布：当时一种名贵的细布，亦称筒中细布。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 587, "title": "平蔡州三首（其二）", "author": "刘禹锡", "body": "汝南晨鸡喔喔鸣，城头鼓角音和平。\n路旁老人忆旧事，相与感激皆涕零。\n老人收泪前致辞： “官军入城人不知。\n忽惊元和十二载，重见天宝承平时。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 588, "title": "蜀先主庙", "author": "刘禹锡", "body": "天下英雄气，千秋尚凛然。\n势分三足鼎，业复五铢钱。\n得相能开国，生儿不象贤[1]。\n凄凉蜀故妓，来舞魏宫前。\n〔注〕[1]象贤：学习先祖的贤才。《仪礼·士冠礼》:“继世以立诸侯，象贤也。”注：“象，法也。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 589, "title": "金陵怀古", "author": "刘禹锡", "body": "潮满冶城渚[1]，日斜征虏亭[2]。\n蔡洲新草绿，幕府旧烟青。\n兴废由人事，山川空地形。\n《后庭花》一曲，幽怨不堪听。\n〔注〕[1]冶城：据《金陵记》说，位于金陵府治西北，故址在今江苏南京市朝天宫一带。[2]征虏亭：故址在今南京市玄武湖北。东晋征虏将军谢石的哥哥谢万曾送客于此亭。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 590, "title": "昼居池上亭独吟", "author": "刘禹锡", "body": "日午树阴正，独吟池上亭。\n静看蜂教诲，闲想鹤仪形。\n法酒调神气，清琴入性灵。\n浩然机已息，几杖复何铭？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 591, "title": "始闻秋风", "author": "刘禹锡", "body": "昔看黄菊与君别，今听玄蝉我却回。\n五夜飕飗枕前觉，一年颜状镜中来。\n马思边草拳毛动，雕眄青云睡眼开。\n天地肃清堪四望，为君扶病上高台。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 592, "title": "西塞山怀古", "author": "刘禹锡", "body": "王濬楼船下益州，金陵王气黯然收。\n千寻铁锁沉江底，一片降幡出石头。\n人世几回伤往事，山形依旧枕寒流。\n今逢四海为家日，故垒萧萧芦荻秋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 593, "title": "酬乐天扬州初逢席上见赠", "author": "刘禹锡", "body": "巴山楚水凄凉地，二十三年弃置身[1]。\n怀旧空吟闻笛赋[2]，到乡翻似烂柯人[3]。\n沉舟侧畔千帆过，病树前头万木春。\n今日听君歌一曲，暂凭杯酒长精神。\n〔注〕[1]二十三年：指刘禹锡于永贞元年（805）九月被贬出京，至宝历二年（826）回京的这段时间。其间刘禹锡多次迁徙，初贬朗州司马，后任夔州刺史等职。夔州治今重庆奉节，秦汉时属巴郡。朗州即今湖南常德，战国时属楚地。“巴山楚水”，概指这些贬谪之地。 [2]闻笛赋：晋人向秀经过亡友嵇康的旧居，听见邻人吹笛，不胜悲叹，写了一篇《思旧赋》。闻笛赋即指此。 [3]烂柯人：指王质。相传晋人王质进山打柴，看见两个童子下棋，便停下观看。棋到终局，王质发现手里的斧柄已烂掉。回到村里，才知道已经过去了一百年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 594, "title": "再授连州至衡阳酬柳柳州赠别", "author": "刘禹锡", "body": "去国十年同赴召，渡湘千里又分歧。\n重临事异黄丞相，三黜名惭柳士师。\n归目并随回雁尽，愁肠正遇断猿时。\n桂江东过连山下，相望长吟有所思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 595, "title": "望夫山", "author": "刘禹锡", "body": "终日望夫夫不归，化为孤石苦相思。\n望来已是几千载，只似当时初望时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 596, "title": "淮阴行五首（其四）", "author": "刘禹锡", "body": "何物令侬羡？羡郎船尾燕。\n衔泥趁樯竿，宿食长相见。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 597, "title": "秋风引", "author": "刘禹锡", "body": "何处秋风至？萧萧送雁群。\n朝来入庭树，孤客最先闻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 598, "title": "竹枝词二首（其一）", "author": "刘禹锡", "body": "杨柳青青江水平，闻郎江上唱歌声。\n东边日出西边雨，道是无晴还有晴。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 599, "title": "堤上行三首（其一、其二）", "author": "刘禹锡", "body": "酒旗相望大堤头，堤下连樯堤上楼。\n日暮行人争渡急，桨声幽轧满中流。\n江南江北望烟波，入夜行人相应歌。\n《桃叶》传情《竹枝》怨[1]，水流无限月明多。\n〔注〕[1]《桃叶》：指《桃叶歌》，是南朝《吴声歌曲》。《古今乐录》说：“《桃叶歌》者，晋王之敬之所作也。桃叶，子敬妾名，缘于笃爱，所以歌之。”这里借指民间流行的表达爱情的歌。《竹枝》：指《竹枝词》。其中也有些情歌，但多是表达怨苦之情的。夔州一带，是《竹枝词》的故乡，这里的人民又有“对歌”的习惯和风俗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 600, "title": "踏歌词四首（其一）", "author": "刘禹锡", "body": "春江月出大堤平，堤上女郎连袂行。\n唱尽新词欢不见，红霞映树鹧鸪鸣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 601, "title": "踏歌词四首（其三）", "author": "刘禹锡", "body": "新词宛转递相传，振袖倾鬟风露前。\n月落乌啼云雨散，游童陌上拾花钿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 602, "title": "阿娇怨", "author": "刘禹锡", "body": "望见葳蕤[1]举翠华，试开金屋扫庭花。\n须臾宫女传来信，言幸平阳公主家。\n〔注〕[1]葳蕤（wēiruí）：鲜丽的样子。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 603, "title": "秋词二首", "author": "刘禹锡", "body": "自古逢秋悲寂寥，我言秋日胜春朝。\n晴空一鹤排云上，便引诗情到碧霄。\n山明水净夜来霜，数树深红出浅黄。\n试上高楼清入骨，岂如春色嗾[1]人狂。\n〔注〕[1]嗾（sǒu）：教唆人做坏事。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 604, "title": "竹枝词九首（其二）", "author": "刘禹锡", "body": "山桃红花满上头，蜀江春水拍山流。\n花红易衰似郎意，水流无限似侬愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 605, "title": "竹枝词九首（其七）", "author": "刘禹锡", "body": "瞿塘嘈嘈十二滩，人言道路古来难。\n长恨人心不如水，等闲平地起波澜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 606, "title": "竹枝词九首（其九）", "author": "刘禹锡", "body": "山上层层桃李花，云间烟火是人家。\n银钏[1]金钗来负水，长刀短笠去烧畲[2]。\n〔注〕[1]银钏（chuàn）：银手镯。 [2]烧畲（shē）：在春耕时节，把地里的草木烧成灰作肥料，然后播下种子。这是山地少数民族的耕作方式。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 607, "title": "杨柳枝词（其一）", "author": "刘禹锡", "body": "塞北梅花羌笛吹，淮南桂树小山词。\n请君莫奏前朝曲，听唱新翻《杨柳枝》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 608, "title": "浪淘沙九首（其六）", "author": "刘禹锡", "body": "日照澄洲江雾开，淘金女伴满江隈。\n美人首饰侯王印，尽是沙中浪底来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 609, "title": "元和十年自朗州至京，戏赠看花诸君子", "author": "刘禹锡", "body": "紫陌红尘拂面来，无人不道看花回。\n玄都观里桃千树，尽是刘郎去后栽。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 610, "title": "再游玄都观", "author": "刘禹锡", "body": "百亩庭中半是苔，桃花净尽菜花开。\n种桃道士归何处？前度刘郎今又来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 611, "title": "与歌者米嘉荣", "author": "刘禹锡", "body": "唱得《凉州》意外声，旧人惟数米嘉荣。\n近来时世轻先辈，好染髭鬚事后生。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 612, "title": "听旧宫人穆氏唱歌", "author": "刘禹锡", "body": "曾随织女渡天河，记得云间第一歌。\n休唱贞元供奉曲，当时朝士已无多。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 613, "title": "石头城", "author": "刘禹锡", "body": "山围故国周遭在，潮打空城寂寞回。\n淮水东边旧时月，夜深还过女墙来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 614, "title": "乌衣巷", "author": "刘禹锡", "body": "朱雀桥边野草花，乌衣巷口夕阳斜。\n旧时王谢堂前燕，飞入寻常百姓家。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 615, "title": "台城", "author": "刘禹锡", "body": "台城六代竞豪华，结绮临春事最奢。\n万户千门成野草，只缘一曲《后庭花》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 616, "title": "和乐天《春词》", "author": "刘禹锡", "body": "新妆宜面下朱楼，深锁春光一院愁。\n行到中庭数花朵，蜻蜓飞上玉搔头。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 617, "title": "望洞庭", "author": "刘禹锡", "body": "湖光秋月两相和，潭面无风镜未磨。\n遥望洞庭山水色，白银盘里一青螺。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 618, "title": "柳枝词", "author": "刘禹锡", "body": "清江一曲柳千条，二十年前旧板桥。\n曾与美人桥上别，恨无消息到今朝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 619, "title": "观刈麦[1]", "author": "白居易", "body": "田家少闲月，五月人倍忙。\n夜来南风起，小麦覆陇黄。\n妇姑荷箪食，童稚携壶浆。\n相随饷田去，丁壮在南冈。\n足蒸暑土气，背灼炎天光。\n力尽不知热，但惜夏日长。\n复有贫妇人，抱子在其旁。\n右手秉遗穗，左臂悬敝筐。\n听其相顾言，闻者为悲伤。\n家田输税尽，拾此充饥肠。\n今我何功德，曾不事农桑。\n吏禄三百石，岁晏有馀粮。\n念此私自愧，尽日不能忘。\n〔注〕[1]题下自注云：时为盩厔县尉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 620, "title": "宿紫阁山北村", "author": "白居易", "body": "晨游紫阁峰，暮宿山下村。\n村老见余喜，为余开一尊。\n举杯未及饮，暴卒来入门。\n紫衣挟刀斧，草草十馀人。\n夺我席上酒，掣我盘中飧。\n主人退后立，敛手反如宾。\n中庭有奇树，种来三十春。\n主人惜不得，持斧断其根。\n口称采造家，身属神策军。\n“主人慎勿语，中尉正承恩！”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 621, "title": "村居苦寒", "author": "白居易", "body": "八年十二月，五日雪纷纷。\n竹柏皆冻死，况彼无衣民！\n回观村闾间，十室八九贫。\n北风利如剑，布絮不蔽身。\n惟烧蒿棘火，愁坐夜待晨。\n乃知大寒岁，农者尤苦辛。\n顾我当此日，草堂深掩门。\n褐裘覆絁[1]被，坐卧有馀温。\n幸免饥冻苦，又无垅亩勤。\n念彼深可愧，自问是何人？\n〔注〕[1]絁（shī）：粗绸，似布。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 622, "title": "轻肥", "author": "白居易", "body": "意气骄满路，鞍马光照尘。\n借问何为者，人称是内臣。\n朱绂皆大夫，紫绶悉将军。\n夸赴军中宴，走马去如云。\n樽罍溢九酝，水陆罗八珍。\n果擘洞庭橘，脍切天池鳞。\n食饱心自若，酒酣气益振。\n是岁江南旱，衢州人食人！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 623, "title": "买花", "author": "白居易", "body": "帝城春欲暮，喧喧车马度。\n共道牡丹时，相随买花去。\n贵贱无常价，酬值看花数。\n灼灼百朵红，戋戋五束素[1]。\n上张幄幕庇，旁织笆篱护。\n水洒复泥封，移来色如故。\n家家习为俗，人人迷不悟。\n有一田舍翁，偶来买花处。\n低头独长叹，此叹无人谕。\n一丛深色花，十户中人赋。\n〔注〕[1]戋戋（jiān）：形容众多。《易经·贲卦》:“束帛戋戋。”旧注：束帛，指五匹帛；戋戋，委积貌。五束素，即二十五匹帛；戋戋，则用以形容二十五匹帛堆积起来的庞大体积。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 624, "title": "上阳白发人", "author": "白居易", "body": "上阳人，红颜暗老白发新。\n绿衣监使守宫门，一闭上阳多少春。\n玄宗末岁初选入，入时十六今六十。\n同时采择百馀人，零落年深残此身。\n忆昔吞悲别亲族，扶入车中不教哭；\n皆云入内便承恩，脸似芙蓉胸似玉。\n未容君王得见面，已被杨妃遥侧目。\n妒令潜配上阳宫，一生遂向空房宿。\n宿空房，秋夜长，夜长无寐天不明；\n耿耿残灯背壁影，萧萧暗雨打窗声。\n春日迟，日迟独坐天难暮；\n宫莺百啭愁厌闻，梁燕双栖老休妒。\n莺归燕去长悄然，春往秋来不记年。\n惟向深宫望明月，东西四五百回圆。\n今日宫中年最老，大家遥赐尚书号。\n小头鞋履窄衣裳，青黛点眉眉细长；\n外人不见见应笑，天宝末年时世妆。\n上阳人，苦最多。\n少亦苦，老亦苦，少苦老苦两如何？\n君不见昔时吕向《美人赋》[1]；又不见今日上阳白发歌！\n〔注〕[1]此句作者自注：“天宝末，有密采艳色者，当时号花鸟使，吕向献《美人赋》以讽之。”吕向在开元十年（722）召入翰林，兼集贤院校理。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 625, "title": "杜陵叟", "author": "白居易", "body": "杜陵叟，杜陵居，岁种薄田一顷余。\n三月无雨旱风起，麦苗不秀多黄死。\n九月降霜秋早寒，禾穗未熟皆青干。\n长吏明知不申破，急敛暴征求考课。\n典桑卖地纳官租，明年衣食将何如？\n剥我身上帛，夺我口中粟。\n虐人害物即豺狼，何必钩爪锯牙食人肉？\n不知何人奏皇帝，帝心恻隐知人弊。\n白麻纸上书德音，京畿尽放今年税。\n昨日里胥方到门，手持尺牒牓乡村。\n十家租税九家毕，虚受吾君蠲免恩。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 626, "title": "缭绫", "author": "白居易", "body": "缭绫缭绫何所似？不似罗绡与纨绮；\n应似天台山上明月前，四十五尺瀑布泉。\n中有文章又奇绝，地铺白烟花簇雪。\n织者何人衣者谁？越溪寒女汉宫姬。\n去年中使宣口敕，天上取样人间织。\n织为云外秋雁行，染作江南春水色。\n广裁衫袖长制裙，金斗熨波刀剪纹。\n异彩奇文相隐映，转侧看花花不定。\n昭阳舞人恩正深，春衣一对直千金。\n汗沾粉污不再着，曳土踏泥无惜心。\n缭绫织成费功绩，莫比寻常缯与帛。\n丝细缲多女手疼，扎扎千声不盈尺。\n昭阳殿里歌舞人，若见织时应也惜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 627, "title": "卖炭翁", "author": "白居易", "body": "卖炭翁，伐薪烧炭南山中。\n满面尘灰烟火色，两鬓苍苍十指黑。\n卖炭得钱何所营？身上衣裳口中食。\n可怜身上衣正单，心忧炭贱愿天寒！\n夜来城外一尺雪，晓驾炭车辗冰辙。\n牛困人饥日已高，市南门外泥中歇。\n翩翩两骑来是谁？黄衣使者白衫儿。\n手把文书口称敕，回车叱牛牵向北。\n一车炭，千馀斤，宫使驱将惜不得。\n半匹红纱一丈绫，系向牛头充炭直。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 628, "title": "夜雪", "author": "白居易", "body": "已讶衾枕冷，复见窗户明。\n夜深知雪重，时闻折竹声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 629, "title": "长恨歌", "author": "白居易", "body": "汉皇重色思倾国，御宇多年求不得。\n杨家有女初长成，养在深闺人未识。\n天生丽质难自弃，一朝选在君王侧。\n回眸一笑百媚生，六宫粉黛无颜色。\n春寒赐浴华清池，温泉水滑洗凝脂。\n侍儿扶起娇无力，始是新承恩泽时。\n云鬓花颜金步摇，芙蓉帐暖度春宵。\n春宵苦短日高起，从此君王不早朝。\n承欢侍宴无闲暇，春从春游夜专夜。\n后宫佳丽三千人，三千宠爱在一身。\n金屋妆成娇侍夜，玉楼宴罢醉和春。\n姊妹弟兄皆列土，可怜光彩生门户。\n遂令天下父母心，不重生男重生女。\n骊宫高处入青云，仙乐风飘处处闻。\n缓歌慢舞凝丝竹，尽日君王看不足。\n渔阳鼙鼓动地来，惊破霓裳羽衣曲。\n九重城阙烟尘生，千乘万骑西南行。\n翠华摇摇行复止，西出都门百馀里。\n六军不发无奈何，宛转蛾眉马前死。\n花钿委地无人收，翠翘金雀玉搔头。\n君王掩面救不得，回看血泪相和流。\n黄埃散漫风萧索，云栈萦纡登剑阁。\n峨嵋山下少人行，旌旗无光日色薄。\n蜀江水碧蜀山青，圣主朝朝暮暮情。\n行宫见月伤心色，夜雨闻铃肠断声。\n天旋地转回龙驭，到此踌躇不能去。\n马嵬坡下泥土中，不见玉颜空死处。\n君臣相顾尽沾衣，东望都门信马归。\n归来池苑皆依旧，太液芙蓉未央柳。\n芙蓉如面柳如眉，对此如何不泪垂。\n春风桃李花开日，秋雨梧桐叶落时。\n西宫南内多秋草，落叶满阶红不扫。\n梨园弟子白发新，椒房阿监青娥老。\n夕殿萤飞思悄然，孤灯挑尽未成眠。\n迟迟钟鼓初长夜，耿耿星河欲曙天。\n鸳鸯瓦冷霜华重，翡翠衾寒谁与共。\n悠悠生死别经年，魂魄不曾来入梦。\n临邛道士鸿都客，能以精诚致魂魄。\n为感君王展转思，遂教方士殷勤觅。\n排空驭气奔如电，升天入地求之遍。\n上穷碧落下黄泉，两处茫茫皆不见。\n忽闻海上有仙山，山在虚无缥缈间。\n楼阁玲珑五云起，其中绰约多仙子。\n中有一人字太真，雪肤花貌参差是。\n金阙西厢叩玉扃，转教小玉报双成。\n闻道汉家天子使，九华帐里梦魂惊。\n揽衣推枕起徘徊，珠箔银屏迤逦开。\n云髻半偏新睡觉，花冠不整下堂来。\n风吹仙袂飘飘举，犹似霓裳羽衣舞。\n玉容寂寞泪阑干，梨花一枝春带雨。\n含情凝睇谢君王，一别音容两渺茫。\n昭阳殿里恩爱绝，蓬莱宫中日月长。\n回头下望人寰处，不见长安见尘雾。\n唯将旧物表深情，钿合金钗寄将去。\n钗留一股合一扇，钗擘黄金合分钿。\n但教心似金钿坚，天上人间会相见。\n临别殷勤重寄词，词中有誓两心知。\n七月七日长生殿，夜半无人私语时。\n在天愿作比翼鸟，在地愿为连理枝。\n天长地久有时尽，此恨绵绵无绝期。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 630, "title": "琵琶行", "author": "白居易", "body": "浔阳江头夜送客，枫叶荻花秋瑟瑟。\n主人下马客在船，举酒欲饮无管弦。\n醉不成欢惨将别，别时茫茫江浸月。\n忽闻水上琵琶声，主人忘归客不发。\n寻声暗问弹者谁，琵琶声停欲语迟。\n移船相近邀相见，添酒回灯重开宴。\n千呼万唤始出来，犹抱琵琶半遮面。\n转轴拨弦三两声，未成曲调先有情。\n弦弦掩抑声声思，似诉平生不得志。\n低眉信手续续弹，说尽心中无限事。\n轻拢慢撚抹复挑，初为《霓裳》后《六幺》。\n大弦嘈嘈如急雨，小弦切切如私语。\n嘈嘈切切错杂弹，大珠小珠落玉盘。\n间关莺语花底滑，幽咽泉流冰下难。\n冰泉冷涩弦凝绝，凝绝不通声渐歇。\n别有幽愁暗恨生，此时无声胜有声。\n银瓶乍破水浆迸，铁骑突出刀枪鸣。\n曲终收拨当心画，四弦一声如裂帛。\n东船西舫悄无言，唯见江心秋月白。\n沉吟放拨插弦中，整顿衣裳起敛容。\n自言本是京城女，家在虾蟆陵下住。\n十三学得琵琶成，名属教坊第一部。\n曲罢曾教善才伏，妆成每被秋娘妒。\n五陵年少争缠头，一曲红绡不知数。\n钿头云篦击节碎，血色罗裙翻酒污。\n今年欢笑复明年，秋月春风等闲度。\n弟走从军阿姨死，暮去朝来颜色故。\n门前冷落车马稀，老大嫁作商人妇。\n商人重利轻别离，前月浮梁买茶去。\n去来江口守空船，绕船月明江水寒。\n夜深忽梦少年事，梦啼妆泪红阑干。\n我闻琵琶已叹息，又闻此语重唧唧。\n同是天涯沦落人，相逢何必曾相识！\n我从去年辞帝京，谪居卧病浔阳城。\n浔阳地僻无音乐，终岁不闻丝竹声。\n住近湓江地低湿，黄芦苦竹绕宅生。\n其间旦暮闻何物，杜鹃啼血猿哀鸣。\n春江花朝秋月夜，往往取酒还独倾。\n岂无山歌与村笛，呕哑嘲哳难为听。\n今夜闻君琵琶语，如听仙乐耳暂明。\n莫辞更坐弹一曲，为君翻作琵琶行。\n感我此言良久立，却坐促弦弦转急。\n凄凄不似向前声，满座重闻皆掩泣。\n座中泣下谁最多？江州司马青衫湿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 631, "title": "花非花", "author": "白居易", "body": "花非花，雾非雾，夜半来，天明去。\n来如春梦几多时？去似朝云无觅处。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 632, "title": "邯郸冬至夜思家", "author": "白居易", "body": "邯郸驿里逢冬至，抱膝灯前影伴身。\n想得家中夜深坐，还应说着远行人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 633, "title": "赋得古原草送别", "author": "白居易", "body": "离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。\n远芳侵古道，晴翠接荒城。\n又送王孙去，萋萋满别情。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 634, "title": "自河南经乱，关内阻饥，兄弟离散，各在一处。因望月有感，聊书所怀，寄上浮梁大兄、於潜七兄、乌江十五兄，兼示符离及下邽弟妹", "author": "白居易", "body": "时难年荒世业空，弟兄羁旅各西东。\n田园寥落干戈后，骨肉流离道路中。\n吊影分为千里雁，辞根散作九秋蓬。\n共看明月应垂泪，一夜乡心五处同。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 635, "title": "同李十一醉忆元九", "author": "白居易", "body": "花时同醉破春愁，醉折花枝作酒筹。\n忽忆故人天际去，计程今日到梁州。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 636, "title": "惜牡丹花[1]", "author": "白居易", "body": "惆怅阶前红牡丹，晚来惟有两枝残。\n明朝风起应吹尽，夜惜衰红把火看。\n〔注〕[1]《惜牡丹花》共二首，此选其一。诗人原注：“一首翰林院北厅花下作。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 637, "title": "望驿台", "author": "白居易", "body": "靖安宅里当窗柳，望驿台前扑地花。\n两处春光同日尽，居人思客客思家！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 638, "title": "江楼月", "author": "白居易", "body": "嘉陵江曲曲江池，明月虽同人别离。\n一宵光景潜相忆，两地阴晴远不知。\n谁料江边怀我夜，正当池畔望君时。\n今朝共语方同悔，不解多情先寄诗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 639, "title": "村夜", "author": "白居易", "body": "霜草苍苍虫切切，村南村北行人绝。\n独出门前望野田，月明荞麦花如雪。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 640, "title": "欲与元八卜邻，先有是赠", "author": "白居易", "body": "平生心迹最相亲，欲隐墙东不为身。\n明月好同三径夜，绿杨[1]宜作两家春。\n每因暂出犹思伴，岂得安居不择邻。\n可独终身数相见，子孙长作隔墙人。\n〔注〕[1]《南史·陆慧晓传》:“慧晓与张融并宅，其间有池，池上有二株杨柳。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 641, "title": "燕子楼", "author": "白居易", "body": "满床明月满帘霜，被冷灯残拂卧床。\n燕子楼中霜月夜，秋来只为一人长。\n钿晕罗衫色似烟，几回欲著即潸然。\n自从不舞《霓裳曲》，叠在空箱十一年。\n今春有客洛阳回，曾到尚书墓上来。\n见说白杨堪作柱，争教红粉不成灰？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 642, "title": "蓝桥驿见元九诗", "author": "白居易", "body": "蓝桥春雪君归日，秦岭秋风我去时。\n每到驿亭先下马，循墙绕柱觅君诗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 643, "title": "舟中读元九诗", "author": "白居易", "body": "把君诗卷灯前读，诗尽灯残天未明。\n眼痛灭灯犹暗坐，逆风吹浪打船声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 644, "title": "放言五首（其一）", "author": "白居易", "body": "朝真暮伪何人辨，古往今来底事无。\n但爱臧生[1]能诈圣，可知宁子[2]解佯愚。\n草萤有耀终非火，荷露虽团岂是珠。\n不取燔柴兼照乘[3]，可怜光彩亦何殊。\n〔注〕[1]臧生：臧武仲。《左传·襄公二十二年》杜预注：“武仲多知，时人谓之圣。”《论语·宪问》:“子曰：臧武仲以防求为后于鲁。虽曰不要君，吾不信也。”防：武仲封邑。为后：确认后代的继承权。 [2]宁子：宁武子。《论语·公冶长》:“宁武子，邦有道则知，邦无道则愚。其知可及也，其愚不可及也。” [3]照乘：珠名。《史记·田敬仲完世家》:“梁王曰：‘若寡人国小也，尚有径寸之珠，照车前后各十二乘者十枚，奈何以万乘之国而无宝乎？'”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 645, "title": "放言五首（其三）", "author": "白居易", "body": "赠君一法决狐疑，不用钻龟与祝蓍[1]。\n试玉要烧三日满[2]，辨材须待七年期[3]。\n周公恐惧流言日，王莽谦恭未篡时。\n向使当初身便死，一生真伪复谁知？\n〔注〕[1]钻龟：古代用龟甲占卜吉凶。祝蓍（shī）：古代占卜的一种方法，取蓍草的茎以卜吉凶。 [2]作者自注：“真玉烧三日不热。” [3]作者自注：“豫章木生七年而后知。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 646, "title": "大林寺桃花", "author": "白居易", "body": "人间四月芳菲尽，山寺桃花始盛开。\n长恨春归无觅处，不知转入此中来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 647, "title": "建昌江", "author": "白居易", "body": "建昌江水县门前，立马教人唤渡船。\n忽似往年归蔡渡，草风沙雨渭河边！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 648, "title": "问刘十九", "author": "白居易", "body": "绿蚁新醅酒，红泥小火炉。\n晚来天欲雪，能饮一杯无？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 649, "title": "南浦别", "author": "白居易", "body": "南浦凄凄别，西风袅袅秋。\n一看肠一断，好去莫回头。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 650, "title": "后宫词", "author": "白居易", "body": "泪湿罗巾梦不成，夜深前殿按歌声。\n红颜未老恩先断，斜倚熏笼坐到明。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 651, "title": "夜筝", "author": "白居易", "body": "紫袖红弦明月中，自弹自感闇低容。\n弦凝指咽声停处，别有深情一万重。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 652, "title": "勤政楼[1]西老柳", "author": "白居易", "body": "半朽临风树，多情立马人。\n开元一枝柳，长庆二年春。\n〔注〕[1]勤政楼：《旧唐书·睿宗诸子让皇帝传》:“玄宗于兴庆宫南置楼，西面题曰花萼相辉之楼，南面题曰勤政务本之楼。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 653, "title": "暮江吟", "author": "白居易", "body": "一道残阳铺水中，半江瑟瑟[1]半江红。\n可怜九月初三夜，露似真珠[2]月似弓。\n〔注〕[1]瑟瑟：深碧色。 [2]真珠：即珍珠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 654, "title": "寒闺怨", "author": "白居易", "body": "寒月沉沉洞房静，真珠帘外梧桐影。\n秋霜欲下手先知，灯底裁缝剪刀冷。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 655, "title": "钱塘湖春行", "author": "白居易", "body": "孤山寺北贾亭[1]西，水面初平云脚低。\n几处早莺争暖树，谁家新燕啄春泥\n乱花渐欲迷人眼，浅草才能没马蹄。\n最爱湖东行不足，绿杨阴里白沙堤[2]。\n〔注〕[1]贾亭：一名贾公亭。《唐语林》卷六：“贞元中，贾全为杭州（刺史），于西湖造亭，为贾公亭；未五六十年废。”白居易作此诗时，贾亭尚在。 [2]白沙堤：即白堤，又称沙堤或断桥堤。（白居易在杭州时，曾修堤蓄水，灌溉民田，其堤在钱塘门之北。后人误以白堤混为白氏所筑之堤。）西湖三面环山，白堤中贯，在湖东一带，总揽全湖之胜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 656, "title": "西湖晚归回望孤山寺赠诸客", "author": "白居易", "body": "柳湖松岛莲花寺，晚动归桡出道场。\n卢橘子低山雨重，栟榈叶战水风凉。\n烟波淡荡摇空碧，楼殿参差倚夕阳。\n到岸请君回首望，蓬莱宫在海中央。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 657, "title": "杭州春望", "author": "白居易", "body": "望海楼明照曙霞，护江堤白踏晴沙。\n涛声夜入伍员庙，柳色春藏苏小家。\n红袖织绫夸柿蒂，青旗沽酒趁梨花。\n谁开湖寺西南路，草绿裙腰一道斜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 658, "title": "秋雨夜眠", "author": "白居易", "body": "凉冷三秋夜，安闲一老翁。\n卧迟灯灭后，睡美雨声中。\n灰宿温瓶火，香添暖被笼。\n晓晴寒未起，霜叶满阶红。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 659, "title": "与梦得沽酒闲饮且约后期", "author": "白居易", "body": "少时犹不忧生计，老后谁能惜酒钱？\n共把十千沽一斗，相看七十欠三年。\n闲征雅令穷经史，醉听清吟胜管弦。\n更待菊黄家酿熟，共君一醉一陶然。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 660, "title": "览卢子蒙侍御旧诗，多与微之唱和。感今伤昔，因赠子蒙，题于卷后", "author": "白居易", "body": "昔闻元九咏君诗，恨与卢君相识迟。\n今日逢君开旧卷，卷中多道赠微之。\n相看泪眼情难说，别有伤心事岂知？\n闻道咸阳坟上树，已抽三丈白杨枝！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 661, "title": "杨柳枝词[1]", "author": "白居易", "body": "一树春风千万枝，嫩于金色软于丝。\n永丰西角荒园里，尽日无人属阿谁？\n〔注〕[1]杨柳枝：唐教坊曲名。歌词形式就是七言绝句，此题专用于咏柳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 662, "title": "白云泉", "author": "白居易", "body": "天平山上白云泉，云自无心水自闲。\n何必奔冲山下去，更添波浪向人间！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 663, "title": "悯农二首", "author": "李绅", "body": "春种一粒粟，秋收万颗子。\n四海无闲田，农夫犹饿死。\n锄禾日当午，汗滴禾下土。\n谁知盘中餐，粒粒皆辛苦。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 664, "title": "与浩初上人同看山寄京华亲故", "author": "柳宗元", "body": "海畔尖山似剑芒，秋来处处割愁肠。\n若为化作身千亿，散向峰头望故乡。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 665, "title": "重别梦得", "author": "柳宗元", "body": "二十年来万事同，今朝岐路忽西东。\n皇恩若许归田去，晚岁当为邻舍翁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 666, "title": "登柳州城楼寄漳、汀、封、连四州刺史", "author": "柳宗元", "body": "城上高楼接大荒，海天愁思正茫茫。\n惊风乱飐芙蓉水，密雨斜侵薜荔墙。\n岭树重遮千里目，江流曲似九回肠。\n共来百粤文身地，犹自音书滞一乡！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 667, "title": "柳州榕叶落尽偶题", "author": "柳宗元", "body": "宦情羁思共凄凄，春半如秋意转迷。\n山城过雨百花尽，榕叶满庭莺乱啼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 668, "title": "别舍弟宗一", "author": "柳宗元", "body": "零落残魂倍黯然，双垂别泪越江边。\n一身去国六千里，万死投荒十二年。\n桂岭瘴来云似墨，洞庭春尽水如天。\n欲知此后相思梦，长在荆门郢树烟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 669, "title": "柳州城西北隅种柑树", "author": "柳宗元", "body": "手种黄柑[1]二百株，春来新叶遍城隅。\n方同楚客怜皇树[2]，不学荆州利木奴。\n几岁开花闻喷雪，何人摘实见垂珠？\n若教坐待成林日，滋味还堪养老夫。\n〔注〕[1]柑：司马相如《上林赋》郭璞注：“黄甘，橘属而味精。” [2]皇树：橘树。《橘颂》:“后皇嘉树，橘徕服兮。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 670, "title": "酬曹侍御过象县见寄", "author": "柳宗元", "body": "破额山前碧玉流，骚人遥驻木兰舟。\n春风无限潇湘意，欲采蘋花不自由。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 671, "title": "南涧中题", "author": "柳宗元", "body": "秋气集南涧，独游亭午时。\n回风一萧瑟，林影久参差。\n始至若有得，稍深遂忘疲。\n羁禽响幽谷，寒藻舞沦漪。\n去国魂已游，怀人泪空垂。\n孤生易为感，失路少所宜。\n索寞竟何事？徘徊只自知。\n谁为后来者，当与此心期！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 672, "title": "溪居", "author": "柳宗元", "body": "久为簪组[1]累，幸此南夷谪。\n闲依农圃邻，偶似山林客。\n晓耕翻露草，夜榜[2]响溪石。\n来往不逢人，长歌楚天碧。\n〔注〕[1]簪（zān）组：古代官吏的冠饰。 [2]榜（péng）：进船。此句意为天黑船归，船触溪石而有声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 673, "title": "秋晓行南谷经荒村", "author": "柳宗元", "body": "杪秋霜露重，晨起行幽谷。\n黄叶覆溪桥，荒村唯古木。\n寒花疏寂历，幽泉微断续。\n机心久已忘，何事惊麋鹿？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 674, "title": "雨后晓行独至愚溪北池", "author": "柳宗元", "body": "宿云散洲渚，晓日明村坞。\n高树临清池，风惊夜来雨。\n予心适无事，偶此成宾主。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 675, "title": "中夜起望西园值月上", "author": "柳宗元", "body": "觉闻繁露坠，开户临西园。\n寒月上东岭，泠泠疏竹根。\n石泉远逾响，山鸟时一喧。\n倚楹遂至旦，寂寞将何言。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 676, "title": "江雪", "author": "柳宗元", "body": "千山鸟飞绝，万径人踪灭。\n孤舟蓑笠翁，独钓寒江雪。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 677, "title": "渔翁", "author": "柳宗元", "body": "渔翁夜傍西岩宿，晓汲清湘燃楚竹。\n烟销日出不见人，欸乃一声山水绿。\n回看天际下中流，岩上无心云相逐。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 678, "title": "润州听暮角[1]", "author": "李涉", "body": "江城吹角水茫茫，曲引边声怨思长。\n惊起暮天沙上雁，海门[2]斜去两三行。\n〔注〕[1]润州：即今江苏镇江。角：古代军中乐器，有铜角、画角等。 [2]海门：《镇江府志》:“焦山东北有二岛对峙，谓之海门。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 679, "title": "再宿武关", "author": "李涉", "body": "远别秦城万里游，乱山高下出商州。\n关门不锁寒溪水，一夜潺湲送客愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 680, "title": "井栏砂宿遇夜客", "author": "李涉", "body": "暮雨潇潇江上村，绿林豪客夜知闻。\n他时不用逃名姓，世上如今半是君。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 681, "title": "幼女词", "author": "施肩吾", "body": "幼女才六岁，未知巧与拙。\n向夜在堂前，学人拜新月。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 682, "title": "望夫词", "author": "施肩吾", "body": "手爇寒灯向影频，回文机上暗生尘。\n自家夫婿无消息，却恨桥头卖卜人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 683, "title": "赠婢", "author": "崔郊", "body": "公子王孙逐后尘，绿珠垂泪滴罗巾。\n侯门一入深如海，从此萧郎是路人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 684, "title": "裴给事[1]宅白牡丹", "author": "无名氏", "body": "长安豪贵惜春残，争赏街西紫牡丹。\n别有玉盘承露冷，无人起就月中看。\n〔注〕[1]裴给事：即裴潾（? —838?），闻喜（今属山西）人。元和初以荫仕，官起居舍人，开元中终岳部侍郎。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 685, "title": "遣悲怀三首", "author": "元稹", "body": "谢公最小偏怜女，自嫁黔娄百事乖。\n顾我无衣搜荩箧[1]，泥他沽酒拔金钗。\n野蔬充膳甘长藿，落叶添薪仰古槐。\n今日俸钱过十万，与君营奠复营斋。\n昔日戏言身后意，今朝都到眼前来。\n衣裳已施行看尽，针线犹存未忍开。\n尚想旧情怜婢仆，也曾因梦送钱财。\n诚知此恨人人有，贫贱夫妻百事哀。\n闲坐悲君亦自悲，百年都是几多时！\n邓攸[2]无子寻知命，潘岳[3]悼亡犹费词。\n同穴窅冥[4]何所望？他生缘会更难期！\n惟将终夜长开眼，报答平生未展眉。\n〔注〕[1]荩箧（jìnqiè）：竹草编的箱子。 [2]邓攸：西晋人，字伯道，官河东太守。据《晋书·邓攸传》记载，永嘉末年战乱中，他舍子保侄，后终无子。 [3]潘岳：西晋诗人，字安仁。妻死，作《悼亡诗》三首，为世传诵。 [4]窅（yǎo）冥：深暗的样子。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 686, "title": "六年春遣怀八首（其二）", "author": "元稹", "body": "检得旧书三四纸，高低阔狭粗成行。\n自言并食寻常事，惟念山深驿路长。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 687, "title": "六年春遣怀八首（其五）", "author": "元稹", "body": "伴客销愁长日饮，偶然乘兴便醺醺。\n怪来醒后旁人泣，醉里时时错问君！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 688, "title": "行宫", "author": "元稹", "body": "寥落古行宫，宫花寂寞红。\n白头宫女在，闲坐说玄宗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 689, "title": "菊花", "author": "元稹", "body": "秋丛绕舍似陶家，遍绕篱边日渐斜。\n不是花中偏爱菊，此花开尽更无花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 690, "title": "西归绝句（十二首之二）", "author": "元稹", "body": "五年江上损容颜，今日春风到武关。\n两纸京书临水读，小桃花树满商山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 691, "title": "闻乐天授江州司马", "author": "元稹", "body": "残灯无焰影幢幢，此夕闻君谪九江。\n垂死病中惊坐起，暗风吹雨入寒窗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 692, "title": "得乐天书", "author": "元稹", "body": "远信入门先有泪，妻惊女哭问何如。\n寻常不省曾如此，应是江州司马书！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 693, "title": "酬乐天频梦微之", "author": "元稹", "body": "山水万重书断绝，念君怜我梦相闻。\n我今因病魂颠倒，惟梦闲人不梦君！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 694, "title": "重赠乐天", "author": "元稹", "body": "休遣玲珑唱我诗，我诗多是别君词。\n明朝又向江头别，月落潮平是去时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 695, "title": "连昌宫词", "author": "元稹", "body": "连昌宫中满宫竹，岁久无人森似束。\n又有墙头千叶桃，风动落花红蔌蔌。\n宫边老翁为余泣： “小年进食曾因入。\n上皇正在望仙楼，太真同凭阑干立。\n楼上楼前尽珠翠，炫转荧煌照天地。\n归来如梦复如痴，何暇备言宫里事！\n初届寒食一百六，店舍无烟宫树绿。\n夜半月高弦索鸣，贺老琵琶定场屋。\n力士传呼觅念奴[1]，念奴潜伴诸郎宿。\n须臾觅得又连催，特敕街中许燃烛。\n春娇满眼睡红绡，掠削云鬟旋装束。\n飞上九天歌一声，二十五郎吹管笛。\n逡巡大遍凉州彻，色色龟兹轰录续。\n李谟压笛傍宫墙[2]，偷得新翻数般曲。\n平明大驾发行宫，万人歌舞途路中。\n百官队仗避岐薛，杨氏诸姨车斗风。\n明年十月东都破，御路犹存禄山过。\n驱令供顿不敢藏，万姓无声泪潜堕。\n两京定后六七年，却寻家舍行宫前。\n庄园烧尽有枯井，行宫门闭树宛然。\n尔后相传六皇帝，不到离宫门久闭。\n往来年少说长安，玄武楼成花萼废。\n去年敕使因斫竹，偶值门开暂相逐。\n荆榛栉比塞池塘，狐兔骄痴缘树木。\n舞榭攲倾基尚在，文窗窈窕纱犹绿。\n尘埋粉壁旧花钿，乌啄风筝碎珠玉。\n上皇偏爱临砌花，依然御榻临阶斜。\n蛇出燕巢盘斗拱，菌生香案正当衙。\n寝殿相连端正楼，太真梳洗楼上头。\n晨光未出帘影动，至今反挂珊瑚钩。\n指似旁人因恸哭，却出宫门泪相续。\n自从此后还闭门，夜夜狐狸上门屋。”\n我闻此语心骨悲，“太平谁致乱者谁？”\n翁言：“野父何分别，耳闻眼见为君说。\n姚崇宋璟作相公，劝谏上皇言语切。\n燮理阴阳禾黍丰，调和中外无兵戎。\n长官清平太守好，拣选皆言由至公。\n开元之末姚宋死，朝廷渐渐由妃子。\n禄山宫里养作儿，虢国门前闹如市。\n弄权宰相不记名，依稀忆得杨与李。\n庙谟颠倒四海摇，五十年来作疮痍。\n今皇神圣丞相明，诏书才下吴蜀平。\n官军又取淮西贼，此贼亦除天下宁。\n年年耕种宫前道，今年不遣子孙耕。”\n老翁此意深望幸，努力庙谟休用兵。\n〔注〕[1]作者自注：“念奴，天宝中名倡，善歌。每岁楼下酺宴，累日之后，万众喧隘。严安之、韦黄裳辈辟易不能禁，众乐为之罢奏。明皇遣高力士大呼于楼上曰：‘欲遣念奴唱歌，邠二十五郎吹小管逐，看人能听否？’未尝不悄然奉诏。其为当时所重也如此。然而明皇不欲夺侠游之盛，未尝置在宫禁；或岁幸汤泉，时巡东洛，有司潜遣从行而已。” [2]自注：“明皇尝于上阳宫夜后按新翻一曲，属明夕正月十五日，潜游灯下，忽闻酒楼上有笛奏前夕新曲，大骇之。明日，密遣捕捉笛者诘验之。自云：‘其夕窃于天津桥玩月，闻宫中度曲，遂于桥柱上插谱记之。臣即长安少年善笛者李谟也。’明皇异而遣之。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 696, "title": "离思五首（其四）", "author": "元稹", "body": "曾经沧海难为水，除却巫山不是云。\n取次花丛懒回顾，半缘修道半缘君。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 697, "title": "赠项斯", "author": "杨敬之", "body": "几度见诗诗总好，及观标格过于诗。\n平生不解藏人善，到处逢人说项斯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 698, "title": "剑客", "author": "贾岛", "body": "十年磨一剑，霜刃未曾试。\n今日把示君，谁有不平事？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 699, "title": "题李凝幽居", "author": "贾岛", "body": "闲居少邻并，草径入荒园。\n鸟宿池边树，僧敲月下门。\n过桥分野色，移石动云根。\n暂去还来此，幽期不负言。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 700, "title": "忆江上吴处士[1]", "author": "贾岛", "body": "闽国扬帆去，蟾蜍[2]亏复圆。\n秋风生渭水[3]，落叶满长安。\n此地聚会夕，当时雷雨寒。\n兰桡殊未返[4]，消息海云端。\n〔注〕[1]处士：隐居林泉不仕的人。 [2]蟾蜍：虾蟆。此处是月的代称。《后汉书·天文志》注：“羿请不死之药于西王母，姮娥窃之以奔月，是为蟾蜍。” [3]这一句又作“秋风吹渭水”。 [4]兰桡（ráo）：用木兰树做的桨，代指船。殊：这里作“犹”字解。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 701, "title": "雪晴晚望", "author": "贾岛", "body": "倚杖望晴雪，溪云几万重。\n樵人归白屋，寒日下危峰。\n野火烧冈草，断烟生石松。\n却回山寺路，闻打暮天钟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 702, "title": "暮过山村", "author": "贾岛", "body": "数里闻寒水，山家少四邻。\n怪禽啼旷野，落日恐行人。\n初月未终夕，边烽不过秦。\n萧条桑柘外，烟火渐相亲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 703, "title": "寄韩潮州愈", "author": "贾岛", "body": "此心曾与木兰舟，直到天南潮水头。\n隔岭篇章来华岳，出关书信过泷流。\n峰悬驿路残云断，海浸城根老树秋。\n一夕瘴烟风卷尽，月明初上浪西楼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 704, "title": "题兴化寺园亭", "author": "贾岛", "body": "破却千家作一池，不栽桃李种蔷薇。\n蔷薇花落秋风起，荆棘满亭君自知。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 705, "title": "寻隐者不遇", "author": "贾岛", "body": "松下问童子，言师采药去。\n只在此山中，云深不知处。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 706, "title": "闲居", "author": "姚合", "body": "不自识疏鄙，终年住在城。\n过门无马迹，满宅是蝉声。\n带病吟虽苦，休官梦已清。\n何当学禅观，依止古先生？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 707, "title": "穷边词二首（其一）", "author": "姚合", "body": "将军作镇古汧州，水腻山春节气柔。\n清夜满城丝管散，行人不信是边头。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 708, "title": "山行", "author": "项斯", "body": "青枥林深亦有人，一渠流水数家分。\n山当日午回峰影，草带泥痕过鹿群。\n蒸茗气从茅舍出，缲丝声隔竹篱闻。\n行逢卖药归来客，不惜相随入岛云。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 709, "title": "观魏博何相公[1]猎", "author": "张祜", "body": "晓出禁城东，分围浅草中。\n红旗开向日，白马骤迎风。\n背手抽金镞，翻身控角弓。\n万人齐指处，一雁落寒空。\n〔注〕[1]何相公：即魏博节度使何进滔。《旧唐书》说他“居魏十五年，民安之”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 710, "title": "宫词二首（其一）", "author": "张祜", "body": "故国三千里，深宫二十年。\n一声《何满子》，双泪落君前。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 711, "title": "赠内人", "author": "张祜", "body": "禁门宫树月痕过，媚眼惟看宿鹭窠。\n斜拔玉钗灯影畔，剔开红焰救飞蛾。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 712, "title": "集灵台二首（其二）", "author": "张祜", "body": "虢国夫人承主恩，平明骑马入宫门。\n却嫌脂粉污颜色，淡扫蛾眉朝至尊。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 713, "title": "题金陵渡", "author": "张祜", "body": "金陵津渡小山楼，一宿行人自可愁。\n潮落夜江斜月里，两三星火是瓜洲[1]。\n〔注〕[1]瓜洲：在今江苏邗江县南，大运河入长江口，与镇江市相对。本为江中沙洲，沙渐长，状如瓜字，故名。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 714, "title": "纵游淮南", "author": "张祜", "body": "十里长街市井连，月明桥上看神仙。\n人生只合扬州死，禅智山光好墓田。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 715, "title": "长门怨（其一）", "author": "刘皂", "body": "雨滴长门秋夜长，愁心和雨到昭阳。\n泪痕不学君恩断，拭却千行更万行。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 716, "title": "旅次朔方", "author": "刘皂", "body": "客舍并州已十霜，归心日夜忆咸阳。\n无端更渡桑乾水，却望并州是故乡。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 717, "title": "采莲子（其二）", "author": "皇甫松", "body": "船动湖光滟滟[1]秋，贪看年少信船流。\n无端隔水抛莲子，遥被人知半日羞。\n〔注〕[1]滟滟（yàn）：水面闪光的样子。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 718, "title": "晚春江晴寄友人", "author": "韩琮", "body": "晚日低霞绮，晴山远画眉。\n春青河畔草，不是望乡时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 719, "title": "暮春浐水送别", "author": "韩琮", "body": "绿暗红稀出凤城，暮云楼阁古今情。\n行人莫听宫前水，流尽年光是此声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 720, "title": "骆谷晚望", "author": "韩琮", "body": "秦川如画渭如丝，去国还家一望时。\n公子王孙莫来好，岭花多是断肠枝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 721, "title": "宫词", "author": "朱庆馀", "body": "寂寂花时闭院门，美人相并立琼轩。\n含情欲说宫中事，鹦鹉前头不敢言。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 722, "title": "闺意献张水部", "author": "朱庆馀", "body": "洞房昨夜停红烛，待晓堂前拜舅姑。\n妆罢低声问夫婿：画眉深浅入时无？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 723, "title": "长安秋夜", "author": "李德裕", "body": "内官传诏问戎机，载笔金銮夜始归。\n万户千门皆寂寂，月中清露点朝衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 724, "title": "谪岭南道中作", "author": "李德裕", "body": "岭水争分路转迷，桄榔椰叶暗蛮溪。\n愁冲毒雾逢蛇草，畏落沙虫避燕泥。\n五月畬田收火米，三更津吏报潮鸡。\n不堪肠断思乡处，红槿花中越鸟啼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 725, "title": "登崖州城作", "author": "李德裕", "body": "独上高楼望帝京，鸟飞犹是半年程。\n青山似欲留人住，百匝千遭绕郡城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 726, "title": "李凭箜篌引", "author": "李贺", "body": "吴丝蜀桐张高秋，空山[1]凝云颓不流。\n江娥[2]啼竹素女愁，李凭中国[3]弹箜篌。\n昆山玉碎凤凰叫，芙蓉泣露香兰笑。\n十二门[4]前融冷光，二十三丝[5]动紫皇。\n女娲炼石补天处，石破天惊逗秋雨。\n梦入神山教神妪[6]，老鱼跳波瘦蛟舞。\n吴质[7]不眠倚桂树，露脚斜飞湿寒兔。\n〔注〕[1]空山：宋本作“空白”。 [2]江娥：即“湘娥”，亦称“湘妃”、“湘夫人”，传说为舜之二妃。《博物志》:“舜崩，二妃以涕挥竹，竹尽斑。”素女：传为古之乐伎，善于鼓瑟。 [3]中国：即国中，此指京城长安。 [4]十二门：据《三辅黄图》，长安城共四面，每面三门，合计十二门。 [5]二十三丝：代指箜篌。箜篌有多种，有种名叫“竖箜篌”的，“体曲而长，二十有三弦”（《通典》）。 [6]神妪：传说中善弹箜篌的仙人。 [7]吴质：即吴刚。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 727, "title": "示弟", "author": "李贺", "body": "别弟三年后，还家一日馀。\n醁醽[1]今夕酒，缃帙[2]去时书。\n病骨犹能在，人间底事无？\n何须问牛马，抛掷任枭卢！\n〔注〕[1]醁醽（lùlíng）：亦作“醽醁”、“酃渌”、“绿酃”，美酒名。《通鉴注》:“衡阳县东二十里有酃湖，其水湛然绿色，取以酿酒，甘美，谓之酃渌。” [2]缃帙：黄色的包书布。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 728, "title": "咏怀二首（其一）", "author": "李贺", "body": "长卿怀茂陵[1]，绿草垂石井。\n弹琴看文君，春风吹鬓影。\n梁王[2]与武帝，弃之如断梗。\n惟留一简书，金泥泰山顶[3]。\n〔注〕[1]茂陵：汉武帝墓，在今陕西兴平东南。 [2]梁王：指梁孝王刘武。刘武和汉景帝刘启是同母弟兄。《史记·司马相如列传》:“会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之，因病免，客游梁。梁孝王令与诸生同舍。” [3]据《汉书·武帝纪第六》，武帝曾于元封元年（前110）登封泰山。金泥：水银和金屑和成的泥，用以涂封玉牒（祭告天地的文章）。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 729, "title": "咏怀二首（其二）", "author": "李贺", "body": "日夕著书[1]罢，惊霜落素丝。\n镜中聊自笑，讵是南山期[2]！\n头上无幅巾[3]，苦蘗已染衣。\n不见清溪鱼，饮水得相宜[4]？\n〔注〕[1]著书：明姚佺、清姚文燮本均作“看书”，此据王琦《汇解》本。 [2]南山期：长寿的意思。语本《诗经》:“如南山之寿，不骞不崩。” [3]幅巾：又称“襆头”，是一种裹头的绸布，风行于东汉。当时王公名士，头裹幅巾，以示儒雅。 [4]相宜：宋吴正子本作“自宜”，此亦据王本。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 730, "title": "雁门太守行", "author": "李贺", "body": "黑云压城城欲摧，甲光向日金鳞开。\n角声满天秋色里，塞上燕脂凝夜紫。\n半卷红旗临易水，霜重鼓寒声不起。\n报君黄金台上意，提携玉龙为君死。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 731, "title": "苏小小墓", "author": "李贺", "body": "幽兰露，如啼眼。\n无物结同心，烟花不堪剪。\n草如茵，松如盖，\n风为裳，水为珮。\n油壁车，夕相待。\n冷翠烛，劳光彩。\n西陵[1]下，风吹雨。\n〔注〕[1]西陵：地名，在今杭州，钱塘江之西。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 732, "title": "梦天", "author": "李贺", "body": "老兔寒蟾泣天色，云楼半开壁斜白。\n玉轮轧露湿团光，鸾珮相逢桂香陌。\n黄尘清水三山下，更变千年如走马。\n遥望齐州九点烟，一泓海水杯中泻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 733, "title": "天上谣", "author": "李贺", "body": "天河夜转漂回星，银浦流云学水声。\n玉宫桂树花未落，仙妾采香垂珮缨。\n秦妃卷帘北窗晓，窗前植桐青凤小；\n王子吹笙鹅管长，呼龙耕烟种瑶草。\n粉霞红绶藕丝裙，青洲步拾兰苕春。\n东指羲和能走马，海尘新生石山下。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 734, "title": "浩歌", "author": "李贺", "body": "南风吹山作平地，帝[1]遣天吴移海水。\n王母桃花千遍红，彭祖巫咸几回死？\n青毛骢马参差钱，娇春杨柳含细烟。\n筝人劝我金屈卮[2]，神血未凝身问谁？\n不须浪饮丁都护，世上英雄本无主。\n买丝绣作平原君[3]，有酒唯浇赵州土。\n漏催水咽玉蟾蜍，卫娘发薄不胜梳。\n羞见秋眉换新绿[4]，二十男儿那刺促！\n〔注〕[1]帝：天帝。天吴：古代神话中的水神，八首、人面、八足、八尾，背呈青黄色。详见《山海经》。 [2]金屈卮（zhī）：一种有弯柄的金属酒杯。 [3]平原君：赵国人，名胜。战国时代以养士著名的四公子之一。下句的“赵州”，即指赵国。 [4]秋眉：衰白的眉毛。新绿：少年人黑中带绿的眉毛。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 735, "title": "秋来", "author": "李贺", "body": "桐风惊心壮士[1]苦，衰灯络纬啼寒素。\n谁看青简一编书，不遣花虫粉空蠹？\n思牵今夜肠应直，雨冷香魂吊书客。\n秋坟鬼唱鲍家诗[2]，恨血千年土中碧[3]！\n〔注〕[1]壮士：指有才有志的人。 [2]鲍家诗：指南朝宋文学家鲍照的作品。前缀以“秋坟”与“鬼唱”，概由“鲍家诗”的挽歌性质引申出“鬼唱”，又由“鬼唱”推衍出“秋坟”。清王琦在《李长吉歌诗汇解》中说：“鬼唱鲍家诗，或古有其事，唐宋以后失传。” [3]土中碧：用苌弘碧血典。《庄子》中记载：“苌弘死于蜀，藏其血，三年化为碧。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 736, "title": "秦王饮酒", "author": "李贺", "body": "秦王骑虎游八极，剑光照空天自碧。\n羲和敲日玻璃声，劫灰飞尽古今平。\n龙头泻酒邀酒星，金槽琵琶夜枨枨。\n洞庭雨脚来吹笙，酒酣喝月使倒行。\n银云栉栉瑶殿明，宫门掌事报一更。\n花楼玉凤声娇狞，海绡红文香浅清，\n黄娥跌舞千年觥。\n仙人烛树蜡烟轻，青琴醉眼泪泓泓。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 737, "title": "南园十三首（其一）", "author": "李贺", "body": "花枝草蔓眼中开，小白长红越女腮。\n可怜日暮嫣香[1]落，嫁与春风不用媒。\n〔注〕[1]嫣香：指娇艳的花朵。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 738, "title": "南园十三首（其五）", "author": "李贺", "body": "男儿何不带吴钩[1]，收取关山五十州[2]？\n请君暂上凌烟阁[3]，若个书生万户侯？\n〔注〕[1]吴钩：“吴钩，刀名也。刃弯，今南蛮用之，谓之葛党刀。”（宋沈括《梦溪笔谈》）[2]关山五十州：指当时唐代中央政府不能控制的地区。《资治通鉴》元和七年（812）载李绛云：“今法令所不能制者，河南北五十馀州；犬戎腥膻，近接泾陇，烽火屡惊。加之水旱时作，仓廪空虚……” [3]凌烟阁：在长安，唐太宗贞观十七年（643）在阁上画开国功臣二十四人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 739, "title": "南园十三首（其六）", "author": "李贺", "body": "寻章摘句老雕虫[1]，晓月当帘挂玉弓。\n不见年年辽海上，文章何处哭秋风？\n〔注〕[1]雕虫：雕虫小技，表示轻视辞章。语出汉扬雄《法言》:“童子雕虫篆刻，壮夫不为也。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 740, "title": "南园十三首（其七）", "author": "李贺", "body": "长卿牢落悲空舍，曼倩诙谐取自容。\n见买若耶溪水剑[1]，明朝归去事猿公[2]。\n〔注〕[1]若耶溪水剑：若耶溪在今浙江绍兴境内，春秋时欧冶子曾以溪底所出铜铸成利剑。（事见《吴越春秋》） [2]猿公：《吴越春秋》卷九载越王勾践曾聘请一位善剑的处女到王都去。女在途中遇一老翁，自称袁公，与女以竹竿试剑术。后来老翁飞上树梢，化为白猿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 741, "title": "南园十三首（其十三）", "author": "李贺", "body": "小树开朝径，长茸湿夜烟。\n柳花惊雪浦，麦雨涨溪田。\n古刹疏钟度，遥岚破月悬。\n沙头敲石火，烧竹照渔船。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 742, "title": "金铜仙人辞汉歌并序", "author": "李贺", "body": "魏明帝青龙元年八月[1]，诏宫官牵车西取汉孝武捧露盘仙人，欲立置前殿。宫官既拆盘，仙人临载，乃潸然泪下。唐诸王孙李长吉[2]遂作《金铜仙人辞汉歌》。\n茂陵刘郎秋风客，夜闻马嘶晓无迹。\n画栏桂树悬秋香，三十六宫土花碧。\n魏官牵车指千里，东关酸风射眸子。\n空将汉月出宫门，忆君清泪如铅水。\n衰兰送客咸阳道[3]，天若有情天亦老。\n携盘独出月荒凉，渭城已远波声小。\n〔注〕[1]一本作“青龙九年”，皆误。据南朝宋裴松之《三国志》注引《魏略》，青龙五年三月改为景初元年四月，“是岁，徙长安诸钟簴、骆驼、铜人、承露盘”。 [2]李贺是唐宗室郑王之后，故自称“唐诸王孙”。 [3]咸阳：秦都城名，汉改为渭城县，离长安不远。咸阳道：此指长安城外的道路。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 743, "title": "马诗二十三首（其四）", "author": "李贺", "body": "此马非凡马，房星本是星。\n向前敲瘦骨，犹自带铜声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 744, "title": "马诗二十三首（其五）", "author": "李贺", "body": "大漠沙如雪，燕山月似钩。\n何当金络脑，快走踏清秋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 745, "title": "马诗二十三首（其二十三）", "author": "李贺", "body": "武帝爱神仙，烧金得紫烟。\n厩中皆肉马，不解上青天。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 746, "title": "老夫采玉歌", "author": "李贺", "body": "采玉采玉须水碧，琢作步摇徒好色。\n老夫饥寒龙为愁，蓝溪水气无清白。\n夜雨冈头食蓁子，杜鹃口血老夫泪。\n蓝溪之水厌生人，身死千年恨溪水。\n斜山柏风雨如啸，泉脚挂绳青袅袅。\n村寒白屋念娇婴，古台石磴悬肠草。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 747, "title": "南山田中行", "author": "李贺", "body": "秋野明，秋风白，塘水漻漻虫啧啧。\n云根苔藓山上石，冷红泣露娇啼色。\n荒畦九月稻叉牙，蛰萤低飞陇径斜。\n石脉水流泉滴沙，鬼灯如漆点松花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 748, "title": "罗浮山人与葛篇[1]", "author": "李贺", "body": "依依宜织江雨空，雨中六月兰台风[2]。\n博罗老仙[3]时出洞，千岁石床啼鬼工。\n蛇毒浓凝洞堂湿，江鱼不食衔沙立。\n欲剪湘中一尺天，吴娥莫道吴刀涩。\n〔注〕[1]罗浮：山名。《艺文类聚》:“《罗浮山记》曰，罗浮者，盖总称焉。罗，罗山也；浮，浮山也。二山合体，谓之罗浮。”按：山在今广东省增城、博罗二县境。山人：隐居山林的人。[2]兰台风：指使人感到舒畅的风。宋玉《风赋》:“楚襄王游于兰台之宫，宋玉、景差侍。有风飒然而至，王乃披襟而当之，曰：‘快哉，此风！寡人所与庶人共者耶？'” [3]博罗老仙：即罗浮山人。因山在博罗县，故称。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 749, "title": "致酒行", "author": "李贺", "body": "零落栖迟一杯酒，主人奉觞客长寿。\n主父西游困不归，家人折断门前柳。\n吾闻马周昔作新丰客，天荒地老无人识。\n空将笺上两行书，直犯龙颜请恩泽。\n我有迷魂招不得，雄鸡一声天下白。\n少年心事当拏云，谁念幽寒坐呜呃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 750, "title": "长歌续短歌", "author": "李贺", "body": "长歌破衣襟，短歌断白发。\n秦王不可见，旦夕成内热[1]。\n渴饮壶中酒，饥拔陇头粟。\n凄凉四月阑，千里一时绿。\n夜峰何离离[2]，明月落石底。\n俳徊沿石寻，照[3]出高峰外。\n不得与之游，歌成鬓先改。\n〔注〕[1]内热：内心灼热，此处形容焦急烦闷。《后汉书·刘陶传》:“每闻羽书告急之声，心灼内热，四体惊悚。” [2]离离：此处形容群峰攒簇的样子。 [3]照：代指明月。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 751, "title": "昌谷北园新笋四首（其二）", "author": "李贺", "body": "斫取青光写楚辞，腻香春粉黑离离。\n无情有恨何人见？露压烟啼千万枝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 752, "title": "感讽五首（其五）", "author": "李贺", "body": "石根秋水明，石畔秋草瘦。\n侵衣野竹香，蛰蛰[1]垂叶厚。\n岑中月归来，蟾光挂空秀[2]。\n桂露[3]对仙娥，星星下云逗。\n凄凉栀子落，山璺[4]泣清漏。\n下有张仲蔚，披书案将朽。\n〔注〕[1]蛰蛰：群集貌。此形容竹叶攒簇。 [2]空秀：一作“云秀”。 [3]桂露：一作“秋露”。 [4]璺（wèn）：玉石上的裂痕。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 753, "title": "开愁歌[1]", "author": "李贺", "body": "秋风吹地百草干，华容碧影生晚寒。\n我当二十不得意，一心愁谢如枯兰。\n衣如飞鹑马如狗[2]，临歧击剑生铜吼。\n旗亭[3]下马解秋衣，请贳宜阳[4]一壶酒。\n壶中唤天云不开，白昼万里闲凄迷。\n主人劝我养心骨，莫受俗物相填[5]。\n〔注〕[1]题下自注：“花下作。”“花下”，旧本作“笔下”，误。 [2]飞鹑：形容衣衫褴褛。《荀子·大略》:“子夏贫，衣若悬鹑。”马如狗：形容马极瘦小。《后汉书》:“车如鸡栖马如狗。”[3]旗亭：此指酒肆。 [4]贳（shì）：赊欠。宜阳：地名，即福昌县，在今河南省。 [5]填：明胡震亨《唐音统签》云：“‘’即‘豗’字，音灰，相击也。‘填'，写俗物填塞心胸之意也。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 754, "title": "杨生青花紫石砚歌", "author": "李贺", "body": "端州石工巧如神，踏天磨刀割紫云。\n傭刓抱水含满唇，暗洒苌弘冷血痕。\n纱帷昼暖墨花春，轻沤漂沫松麝薰。\n干腻薄重立脚匀，数寸光秋无日昏。\n圆毫促点声静新： ——孔砚宽硕何足云！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 755, "title": "苦昼短", "author": "李贺", "body": "飞光飞光，劝尔一杯酒。\n吾不识青天高，黄地厚；\n惟见月寒日暖，来煎人寿。\n食熊则肥，食蛙则瘦。\n神君何在？太一安有？\n天东有若木，下置衔烛龙。\n吾将斩龙足，嚼龙肉，\n使之朝不得回，夜不得伏。\n自然老者不死，少者不哭。\n何为服黄金，吞白玉？\n谁是任公子，云中骑碧驴？\n刘彻茂陵多滞骨，嬴政梓棺费鲍鱼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 756, "title": "将进酒", "author": "李贺", "body": "琉璃钟，琥珀浓，小槽酒滴真珠红。\n烹龙炮凤玉脂泣，罗帏绣幕围香风。\n吹龙笛，击鼍鼓；皓齿歌，细腰舞。\n况是青春日将暮，桃花乱落如红雨。\n劝君终日酩酊醉，酒不到刘伶坟上土！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 757, "title": "官街鼓", "author": "李贺", "body": "晓声隆隆催转日，暮声隆隆呼月出。\n汉城黄柳映新帘，柏陵飞燕埋香骨。\n磓碎千年日长白，孝武秦皇听不得。\n从君翠发芦花色，独共南山守中国。\n几回天上葬神仙，漏声相将无断绝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 758, "title": "走笔谢孟谏议寄新茶", "author": "卢仝", "body": "日高丈五睡正浓，军将打门惊周公[1]。\n口云谏议送书信，白绢斜封三道印。\n开缄宛见谏议面，手阅月团三百片。\n闻道新年入山里，蛰虫惊动春风起。\n天子须尝阳羡茶[2]，百草不敢先开花。\n仁风暗结珠琲瓃，先春抽出黄金芽。\n摘鲜焙芳旋封裹，至精至好且不奢。\n至尊之馀合王公，何事便到山人家。\n柴门反关无俗客，纱帽笼头[3]自煎吃。\n碧云引风吹不断，白花浮光凝碗面。\n一碗喉吻润，两碗破孤闷。\n三碗搜枯肠，唯有文字五千卷。\n四碗发轻汗，平生不平事，尽向毛孔散。\n五碗肌骨清，六碗通仙灵。\n七碗吃不得也，唯觉两腋习习清风生。\n蓬莱山，在何处？玉川子，乘此清风欲归去。\n山上群仙司下土，地位清高隔风雨。\n安得知百万亿苍生命，堕在巅崖受辛苦！\n便为谏议问苍生，到头还得苏息否？\n〔注〕[1]周公：指梦。孔子说：“甚矣吾衰也，久矣，吾不复梦见周公！”（《论语·述而》）后世就把见周公作为睡梦的代称。 [2]阳羡茶：阳羡，古属常州。宋沈括《梦溪笔谈》:“古人论茶，唯言阳羡、顾渚、天柱、蒙顶之类。”张芸叟云：“有唐茶品，以阳羡为上。”（《茶事拾遗》）[3]纱帽笼头：纱帽最初只用于官员贵胄，隋唐时已成为士大夫的普通服饰。有时亦指一般人的纱巾之类。葛长庚《茶歌》:“文正范公对茶笑，纱帽笼头煎石铫”；明文征明《煎茶》:“山人纱帽笼头处，禅榻风花绕鬓飞。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 759, "title": "月蚀诗", "author": "卢仝", "body": "新天子即位五年，岁次庚寅，\n斗柄插子，律调黄钟[1]。\n森森万木夜僵立，寒气赑屃顽无风。\n烂银盘从海底出，出来照我草屋东。\n天色绀滑凝不流，冰光交贯寒朣胧。\n初疑白莲花，浮出龙王宫。\n八月十五夜，比并不可双。\n此时怪事发，有物吞食来。\n轮如壮士斧斫坏，桂似雪山风拉摧。\n百炼镜，照见胆，平地埋寒灰。\n火龙珠，飞出脑，却入蚌蛤胎。\n摧环破璧眼看尽，当天一搭如煤炲[2]。\n磨踪灭迹须臾间，便似万古不可开。\n不料至神物，有此大狼狈。\n星如撒沙出，争头事光大。\n奴婢炷暗灯，揜菼如玳瑁[3]。\n今夜吐焰长如虹，孔隙千道射户外。\n玉川子，涕泗下，中庭独自行。\n念此日月者，太阴太阳精。\n皇天要识物，日月乃化生。\n走天汲汲劳四体，与天作眼行光明。\n此眼不自保，天公行道何由行？\n吾见阴阳家有说，望日蚀月月光灭，\n朔月掩日日光缺。\n两眼不相攻，此说吾不容。\n又孔子师老子云：五色令人目盲。\n吾恐天似人，好色即丧明。\n幸且非春时，万物不娇荣。\n青山破瓦色，绿水冰峥嵘。\n花枯无女艳，鸟死沉歌声。\n顽冬何所好？偏使一目盲。\n传闻古老说，食月虾蟆精。\n径圆千里入汝腹，汝此痴骸阿谁生？\n可从海窟来？便解缘青冥。\n恐是眶睫间，揜塞所化成。\n黄帝有二目，帝舜重瞳明。\n二帝悬四目，四海生光辉。\n吾不遇二帝，滉漭不可知。\n何故瞳子上，坐受虫豸欺？\n长嗟白兔捣灵药，恰似有意防奸非。\n药成满臼不中度，委任白兔夫何为？\n忆昔尧为天，十日烧九州。\n金烁水银流，玉煼[4]丹砂焦。\n六合烘为窯[5]，尧心增百忧。\n帝见尧心忧，勃然发怒决洪流。\n立拟沃杀九日妖，\n天高日走沃不及，但见万国赤子[6]生鱼头。\n此时九御导九日，争持节幡麾幢旒。\n驾车六九五十四头蛟螭纠，掣电九火辀。\n汝若蚀开齱齵[7]轮，御辔执索相爬钩，\n推荡轰訇入汝喉。\n红鳞焰鸟烧口快，翎鬣倒侧声醆邹[8]。\n撑肠拄肚礧傀[9]如山丘，自可饱死更不偷。\n不独填饥坑，亦解尧心忧。\n恨汝时当食，藏头擫脑不肯食；\n不当食，张唇哆觜食不休。\n食天之眼养逆命，安得上帝请汝刘[10]！\n呜呼！\n人养虎，被虎啮；\n天媚蟆，被蟆瞎。\n乃知恩非类，一一自作孽。\n吾见患眼人，必索良工诀。\n想天不异人，爱眼固应一。\n安得常娥氏，来习扁鹊术？\n手操舂喉戈[11]，去此睛上物。\n其初犹朦胧，既久如抹漆[12]。\n但恐功业成，便此不吐出。\n玉川子又渧泗下，心祷再拜额榻沙土中。\n地上虮虱臣仝告愬帝天皇：\n臣心有铁一寸，可刳妖蟆痴肠。\n上天不为臣立梯磴，臣血肉身，\n无由飞上天，扬天光。\n封词付与小心风，颰[13]排阊阖入紫宫。\n密迩玉几前擘坼，奏上臣仝顽愚胸。\n敢死横干天，代天谋其长。\n东方苍龙角，插戟尾捭风[14]。\n当心开明堂，统领三百六十鳞虫，\n坐理东方宫。\n月蚀不救援，安用东方龙？\n南方火鸟赤泼血，项长尾短飞跋躠[15]，\n头戴丹冠高逵枿[16]。\n月蚀鸟宫十三度，鸟为居停主人不觉察。\n贪向何人家？行赤口毒舌。\n毒虫头上喫却月，不啄杀。\n虚眨鬼眼明䆕䆷[17]，鸟罪不可雪。\n西方攫虎立踦踦[18]，\n斧为牙，凿为齿。\n偷牺牲，食封豕[19]。\n大蟆一脔，固当软美。\n见似不见，是何道理？\n爪牙根天不念天，天若准拟错准拟[20]。\n北方寒龟被蛇缚，藏头入壳如入狱，\n蛇筋束紧束破壳。\n寒龟夏鳖一种味，且当以其肉充臛[21]。\n死壳没信处，唯堪支床脚，\n不堪钻灼与天卜。\n岁星[22]主福德，官爵奉董秦[23]。\n忍使黔娄[24]生，覆尸无衣巾。\n天失眼不吊，岁星胡其仁？\n荧惑[25]矍铄翁，执法大不中。\n月明无罪过，不纠蚀月虫。\n年年十月朝太微[26]，支卢[27]谪罚何灾凶。\n土星与土性相背，反养福德生祸害[28]。\n到人头上死破败，今夜月蚀安可会？\n太白[29]真将军，怒激锋芒生。\n恒州阵斩郦定进，项骨脆甚春蔓菁。\n天唯两眼失一眼，将军何处行天兵？\n辰星任廷尉[30]，天律自主持。\n人命在盆底，固应乐见天盲时。\n天若不肯信，试唤皋陶[31]鬼一问。\n一如今日，三台文昌宫[32]，\n作上天纪纲。\n环天二十八宿，磊磊尚书郎，\n整顿排班行。\n剑握他人将，一四太阳侧，\n一四天市[33]傍。\n操斧代大匠，两手不怕伤。\n弧矢[34]引满反射人，天狼呀啄明煌煌[35]。\n痴牛与騃女[36]，不肯勤农桑。\n徒劳含淫思，旦夕遥相望。\n蚩尤[37]簸旗弄旬朔，始搥天鼓[38]鸣珰琅。\n枉矢[39]能蛇行，眊目森森张。\n天狗[40]下舐地，血流何滂滂！\n谲险万万党，架构何可当？\n眯目釁成就，害我光明王。\n请留北斗一星相北极，指麾万国悬中央。\n此外尽扫除，堆积如山冈，\n赎我父母光。\n当时常星没，殒雨如迸浆。\n似天会事发，叱喝诛奸强。\n何故中道废？自遗今日殃。\n善善又恶恶[41]，郭公[42]所以亡。\n愿天袖圣心，勿信他人忠。\n玉川子词迄，风色紧格格。\n近月黑暗边，有似动剑戟。\n须臾痴蟆精，两吻自决坼。\n初露半个璧，渐吐满轮魄。\n众星尽原赦，一蟆独诛磔。\n腹肚忽脱落，依旧挂穹碧。\n光彩未苏来，惨澹一片白。\n奈何万里光，受此吞吐厄。\n再得见天眼，感荷天地力。\n或问玉川子：孔子修《春秋》，\n二百四十年，月蚀尽不收。\n今子咄咄词，颇合孔意不？\n玉川子笑答：或请听逗留。\n孔子父母鲁，讳鲁不讳周。\n书外书大恶，故月蚀不见收。\n予命唐天，口食唐土。\n唐礼过三，唐乐过五。\n小犹不说，大不可数。\n灾沴无有小大瘉[43]，安得引衰周，\n研覈其可否？\n日分昼，月分夜，辨寒暑。\n一主刑，一主德，政乃举。\n孰为人面上，一目偏可去？\n愿天完两目，照下万方土，\n万古更不瞽。\n万万古，更不瞽，照万古。\n〔注〕[1]“斗柄”二句：《淮南子·时则训》：“仲冬之月，招摇（即摇光）指子。……律中黄钟。”斗柄，即北斗星中的第五至七星玉衡、开阳、摇光，排列之形如斗杓，故称。子，十二时辰之一，以记星次。黄钟，十二律之一。 [2]煤炲（tái）：亦作煤炱。《吕氏春秋·任数》:“向者煤炱入甑中，弃食不祥。”高诱注：“煤炱，烟尘也。” [3]揜菼（yǎntǎn）：指光线昏暗。玳瑁：一种海龟，其壳有黑色块斑。 [4]煼（chǎo）:《广韵·巧韵》:“煼，熬也。”同“炒”。 [5]窯（yáo）:《说文解字·穴部》:“窯，烧瓦灶也。”即“窑”。 [6]（jí）：亦作，簇集貌。 [7]齱齵（zōu óu）:《说文解字·齿部》:“齱齵，齿不正也。”亦形容参差不齐。 [8]醆（zhǎn）邹：象声词。[9]礧傀（léikuǐ）：同礧磈。高低不平貌。 [10]刘：杀。 [11]舂喉戈：《史记·鲁周公世家》：“获长乔如，富父终甥舂其喉，以戈杀之。”舂，冲击。 [12]抹漆：谓眼之瞳仁黑如点漆。 [13]颰（bá）:《龙龛手镜·风部》:“颰，疾风皃（貌）也。”阊阖（chānghé）：天门。 [14]捭（bǎi）风：分开风。 [15]跋躠（xiè）：形容行动迟缓困难。 [16]逵枿（niè）：分叉昂起。 [17]䆕䆷（yuè xuè）：孔穴幽深貌。 [18]踦（jī）踦：独自伫立貌。 [19]封豕：大猪。 [20]准拟：希望，打算。[21]臛（hùo）：肉羹。 [22]岁星：木星。《晋书·天文志》:“岁星以德。” [23]董秦：指董贤、秦宫。董为西汉时哀帝之幸臣，秦为东汉时权臣大将军梁冀之奴，皆以媚上得宠，显耀一时。[24]黔娄：战国时齐国高士，修身清节，不求进于诸侯，鲁恭公欲以为相，辞不受。齐王又以黄金百斤聘为师，亦不就。卒，尸横草席，衣服不完，覆以布被，覆头则足见，覆足则头见。见皇甫谧《高士传》、刘向《列女传》。 [25]荧惑：火星。《晋书·天文志》:“荧惑以礼。” [26]太微：星官名，三垣之一，古以为天庭。《楚辞·远游》:“问大（太）微之所居。”王逸注：“博访天庭在何处也。” [27]支卢：谓纪功。卢，卢弓，黑弓。古时诸侯有大功，则天子赐彤弓、卢弓，以之象征伐之权。 [28]“反养”句：谓土星与其本性相背。《晋书·天文志》:“镇（土）星有福。” [29]太白：金星。《晋书·天文志》:“太白兵强。” [30]辰星：水星。《晋书·天文志》:“辰星阴阳和。”廷尉：官名，古时九卿之一，秦始置，为司法官，后世改名为大理寺卿。 [31]皋陶（yáo）：舜时掌刑法的贤臣。 [32]三台文昌：二星官名。《晋书·天文志》:“三台六星，两两而居，起文昌，列抵太微。”又：“文昌六星，在北斗魁前，天之六府也，主集计天道。” [33]天市：天市垣，星官名。《晋书·天文志》:“在房、心东北，主权衡，主聚众。” [34]弧矢：星官名。《晋书·天文志》:“弧九星，在狼东南，天弓张，……弧矢移动不如常者，多盗贼，胡兵大起。……天弓张，天下尽兵。”[35]天狼：星官名。《晋书·天文志》:“狼为野将，主侵掠。” [36]痴牛：指牵牛，星官名，即牛郎星。《晋书·天文志》:“牵牛六星，天之关梁，主牺牲事。”騃女：指织女，星官名。《晋书·天文志》:“织女三星，在天纪东端，天女也，主果蓏丝帛珍宝也。” [37]蚩尤：即蚩尤旗，星名。古人认为是妖星。《晋书·天文志》:“妖星。……六曰蚩尤旗，类彗而后曲，象旗。……主伐枉逆，主惑乱，所见之方下有兵，兵大起；不然，有丧。” [38]天鼓：即河鼓，星官名。《晋书·天文志》:“河鼓三星，……在牵牛北，天鼓也，主军鼓，主斧钺。” [39]枉矢：星名。《晋书·天文志》:“枉矢，类流星，色苍黑，蛇行，望之如有毛，……见则谋反之兵合射所诛，亦为以乱伐乱。” [40]天狗：星名。《晋书·天文志》:“天狗，状如大奔星，色黄，有声，其止地，类狗。……见则四方相射，千里破军杀将。” [41]善善又恶恶：奖善嫉恶，好恶分明。《荀子·强国》:“彼先王之道也，善善恶恶之应也，治必由之。”按：此句应理解为否定句，即不善善又恶恶。 [42]郭公：春秋时失地之君。《春秋·庄公二十四年》:“冬，戎侵曹，……赤归于曹。郭公。”《公羊传》:“郭公者何？失地之君也。”又，也可代指北齐后主高纬。《乐府诗集·杂歌谣辞·邯郸郭公歌》解题引《乐府广题》谓高纬“雅好傀儡，谓之郭公。时人戏为《郭公歌》，及将败，果营邯郸。高、郭声相近，……后败于邓林，尽如歌言。”《北史·齐本纪下》谓其即位后“隔以正人，闭其善道，……罕接朝士，不亲政事，一日万机，委诸凶族”。 [43]灾沴（lì）：气不和而生的灾害。瘉：病，引申为灾难。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 760, "title": "冰柱", "author": "刘叉", "body": "师干久不息，农为兵兮民重嗟。\n骚然县宇[1]，土崩水溃，畹中无熟谷，垅上无桑麻。\n王春判序[2]，百卉茁甲含葩。\n有客避兵奔游僻，跋履险阨至三巴。\n貂裘蒙茸已敝缕，鬓发蓬舥[3]。\n雀惊鼠伏，宁遑安处，独卧旅舍无好梦，更堪走风沙！\n天人一夜剪瑛琭[4]，诘旦都成六出花。\n南亩未盈尺，纤片乱舞空纷拏。\n旋落旋逐朝暾化，檐间冰柱若削出交加。\n或低或昂，小大莹洁，随势无等差。\n始疑玉龙下界来人世，齐向茅檐布爪牙。\n又疑汉高帝，西方来斩蛇。\n人不识，谁为当风杖莫邪。\n铿锵冰有韵，的皪玉无暇。\n不为四时雨，徒于道路成泥柤[5]。\n不为九江浪，徒为汩没天之涯。\n不为双井水，满瓯泛泛烹春茶。\n不为中山浆[6]，清新馥鼻盈百车。\n不为池与沼，养鱼种芰成霪霪；\n不为醴泉与甘露，使名异瑞世俗夸。\n特禀朝沏气，洁然自许靡间其迩遐。\n森然气结一千里，滴沥声沉十万家。\n明也虽小，暗之大不可遮。\n勿被曲瓦，直下不能抑群邪。\n奈何时逼，不得时在我梦中，倏然漂去无馀㱔[7]。\n自是成毁任天理，天于此物岂宜有忒赊。\n反令井蛙壁虫变容易，背人缩首竞呀呀。\n我愿天子回造化，藏之韫椟玩之生光华。\n〔注〕[1]县宇：指全国。 [2]序：时序，季节。 [3]舥（pā）：联舟为桥叫舥。此处形容鬓发蓬乱之状。 [4]瑛琭：瑛，玉光；琭，玉貌。此处皆作“玉”解。 [5]柤（zhā）：木栏杆。[6]中山浆：中山，地名，今河北定县地。浆，酒。传说古时中山人狄希能造千日酒，饮之千日始醒。见《搜神记》。 [7]㱔:“些”的异体字，“少”的意思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 761, "title": "偶书", "author": "刘叉", "body": "日出扶桑一丈高，人间万事细如毛。\n野夫怒见不平处，磨损胸中万古刀。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 762, "title": "姚秀才爱予小剑因赠", "author": "刘叉", "body": "一条古时水，向我手心流。\n临行泻赠君，勿薄细碎仇。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 763, "title": "忆扬州", "author": "徐凝", "body": "萧娘[1]脸薄难胜泪，桃叶[2]眉长易觉愁。\n天下三分明月夜，二分无赖是扬州。\n〔注〕[1]萧娘：南朝以来，诗词中男所恋女子常称萧娘，女所恋男子则称萧郎。 [2]桃叶：《古今乐录》:“晋王献之爱妾名桃叶。”这里用以代指所思念的佳人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 764, "title": "自君之出矣", "author": "雍裕之", "body": "自君之出矣，宝镜为谁明？\n思君如陇水，长闻呜咽声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 765, "title": "江边柳", "author": "雍裕之", "body": "嫋嫋古堤边，青青一树烟。\n若为丝不断，留取系郎船。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 766, "title": "柳絮", "author": "雍裕之", "body": "无风才到地，有风还满空。\n缘渠偏似雪，莫近鬓毛生。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 767, "title": "农家望晴", "author": "雍裕之", "body": "尝闻秦地西风雨，为问西风早晚回？\n白发老农如鹤立，麦场高处望云开。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 768, "title": "秋日赴阙题潼关驿楼", "author": "许浑", "body": "红叶晚萧萧，长亭酒一瓢。\n残云归太华，疏雨过中条。\n树色随关迥，河声入海遥。\n帝乡明日到，犹自梦渔樵。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 769, "title": "金陵怀古", "author": "许浑", "body": "玉树歌残王气终，景阳兵合戍楼空。\n松楸远近千官冢，禾黍[1]高低六代宫。\n石燕[2]拂云晴亦雨，江豚[3]吹浪夜还风。\n英雄一去豪华尽，惟有青山似洛中。\n〔注〕[1]禾黍：《诗经·王风·黍离》小序说，周大夫行役过故宗庙宫室之地，看见到处长着禾黍，感伤王都颠覆，作《黍离》诗。 [2]石燕：《浙中记》:“零陵有石燕，得风雨则飞翔，风雨止还为石。” [3]江豚：《南越志》:“江豚如猪，居水中，每于浪间跳跃，风辄起。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 770, "title": "登洛阳故城", "author": "许浑", "body": "禾黍离离半野蒿，昔人城此岂知劳？\n水声东去市朝变，山势北来宫殿高。\n鸦噪暮云归古堞，雁迷寒雨下空壕。\n可怜缑岭登仙子，犹自吹笙醉碧桃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 771, "title": "咸阳城西楼晚眺", "author": "许浑", "body": "一上高城万里愁，蒹葭杨柳似汀洲。\n溪云初起日沉阁，山雨欲来风满楼。\n鸟下绿芜秦苑夕，蝉鸣黄叶汉宫秋。\n行人莫问当年事，故国东来渭水流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 772, "title": "汴河亭", "author": "许浑", "body": "广陵花盛帝东游，先劈昆仑一派流。\n百二[1]禁兵辞象阙，三千宫女下龙舟。\n凝云鼓震星辰动，拂浪旗开日月浮。\n四海义师归有道，迷楼[2]还似景阳楼。\n〔注〕[1]百二：《史记·高祖本纪》:“秦，形胜之国，带河山之险，县（悬）隔千里，持戟百万，秦得百二焉。”苏林注：“秦地险固，二万人足当诸侯百万人也。”诗中“百二禁兵”，指炀帝的卫兵。 [2]迷楼：炀帝晚年，尤沉迷女色，浙人项升为造迷楼。可参看罗隐《迷楼赋》及宋传奇《迷楼记》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 773, "title": "塞下曲", "author": "许浑", "body": "夜战桑乾北，秦兵半不归。\n朝来有乡信，犹自寄寒衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 774, "title": "谢亭送别", "author": "许浑", "body": "劳歌一曲解行舟，红叶青山水急流。\n日暮酒醒人已远，满天风雨下西楼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 775, "title": "客有卜居不遂薄游汧陇因题", "author": "许浑", "body": "海燕西飞白日斜，天门遥望五侯家。\n楼台深锁无人到，落尽东风第一花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 776, "title": "途经秦始皇墓", "author": "许浑", "body": "龙盘虎踞树层层，势入浮云亦是崩。\n一种青山秋草里，路人唯拜汉文陵。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 777, "title": "河湟", "author": "杜牧", "body": "元载[1]相公曾借箸[2]，宪宗皇帝亦留神。\n旋见衣冠就东市[3]，忽遗弓剑[4]不西巡。\n牧羊驱马虽戎服，白发丹心尽汉臣。\n唯有凉州歌舞曲，流传天下乐闲人。\n〔注〕[1]元载：字公辅，唐代宗时宰相，曾任西州刺史。大历八年（773）上书代宗，对西北边防措施多所筹策。大历十二年，因事被捕下狱，诏令自杀。 [2]借箸：《史记·留侯世家》载，张良在刘邦吃饭时进策说：“臣请借前箸为大王筹之。” [3]衣冠就东市：指汉景帝时晁错任御史大夫，他对于削藩巩固中央集权有很好的意见，却被皇帝听信谗言，仓卒错杀，“衣朝衣，就东市”。 [4]忽遗弓剑：《水经注·河水篇》:“阳周县桥山上有黄帝冢，帝崩，惟弓剑存焉。”\n杜牧像——清刊本《古圣贤像传略》", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 778, "title": "过勤政楼", "author": "杜牧", "body": "千秋佳节名空在，承露丝囊世已无[1]。\n唯有紫苔偏称意，年年因雨上金铺。\n〔注〕[1]承露丝囊：《续齐谐记》载：“弘农邓绍，尝以八月旦入华山采药，见一童子执五彩囊，承柏叶上露，皆如珠满囊。绍问：‘用此何为？’答曰：‘赤松先生取以明目。’言终便失所在。荆楚岁时八月十四日以锦彩为眼明囊，递相饷遗。”从这段记载知道，此诗中的“承露囊”，可能就是当时人们借赤松子的“承露囊”而取名的。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 779, "title": "念昔游三首（其一）", "author": "杜牧", "body": "十载飘然绳检外，樽前自献自为酬。\n秋山春雨闲吟处，倚遍江南寺寺楼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 780, "title": "念昔游三首（其三）", "author": "杜牧", "body": "李白题诗水西寺，古木回岩楼阁风。\n半醒半醉游三日，红白花开山雨中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 781, "title": "过华清宫绝句三首（其一）", "author": "杜牧", "body": "长安回望绣成堆，山顶千门次第开。\n一骑红尘妃子笑，无人知是荔枝来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 782, "title": "过华清宫绝句三首（其二）", "author": "杜牧", "body": "新丰绿树起黄埃，数骑渔阳探使回。\n霓裳一曲千峰上，舞破中原始下来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 783, "title": "沈下贤", "author": "杜牧", "body": "斯人清唱何人和，草径苔芜不可寻。\n一夕小敷山下梦，水如环珮月如襟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 784, "title": "长安秋望", "author": "杜牧", "body": "楼倚霜树外，镜天无一毫。\n南山与秋色，气势两相高。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 785, "title": "将赴吴兴登乐游原一绝", "author": "杜牧", "body": "清时有味是无能，闲爱孤云静爱僧。\n欲把一麾江海去，乐游原上望昭陵。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 786, "title": "润州二首（其一）", "author": "杜牧", "body": "向吴亭东千里秋，放歌曾作昔年游。\n青苔寺里无马迹，绿水桥边多酒楼。\n大抵南朝皆旷达，可怜东晋最风流。\n月明更想桓伊在，一笛闻吹出塞愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 787, "title": "题扬州禅智寺", "author": "杜牧", "body": "雨过一蝉噪，飘萧松桂秋。\n青苔满阶砌，白鸟故迟留。\n暮霭生深树，斜阳下小楼。\n谁知竹西路，歌吹是扬州。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 788, "title": "江南春", "author": "杜牧", "body": "千里莺啼绿映红，水村山郭酒旗风。\n南朝四百八十寺，多少楼台烟雨中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 789, "title": "题宣州开元寺水阁，阁下宛溪，夹溪居人", "author": "杜牧", "body": "六朝文物草连空，天淡云闲今古同。\n鸟去鸟来山色里，人歌人哭水声中。\n深秋帘幕千家雨，落日楼台一笛风。\n惆怅无因见范蠡，参差烟树五湖东。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 790, "title": "宣州送裴坦判官往舒州，时牧欲赴官归京", "author": "杜牧", "body": "日暖泥融雪半消，行人芳草马声骄。\n九华山路云遮寺，清弋江村柳拂桥。\n君意如鸿高的的，我心悬旆正摇摇。\n同来不得同归去，故国逢春一寂寥！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 791, "title": "登九峰楼[1]寄张祜", "author": "杜牧", "body": "百感衷来不自由，角声孤起夕阳楼。\n碧山终日思无尽，芳草何年恨即休。\n睫在眼前长不见，道[2]非身外更何求？\n谁人得似张公子，千首诗轻万户侯[3]！\n〔注〕[1]九峰楼：一作九华楼。清《一统志》云：“在贵池县九华门上，唐建。” [2]道：指宇宙的本体及其规律，这里有“真理”的意思。 [3]万户侯：食邑万户的列侯。这里比喻高官厚禄。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 792, "title": "九日齐山登高", "author": "杜牧", "body": "江涵秋影雁初飞，与客携壶上翠微。\n尘世难逢开口笑，菊花须插满头归。\n但将酩酊酬佳节，不用登临恨落晖。\n古往今来只如此，牛山何必独沾衣？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 793, "title": "齐安郡[1]中偶题二首（其一）", "author": "杜牧", "body": "两竿落日溪桥上，半缕轻烟柳影中。\n多少绿荷相倚恨，一时回首背西风。\n〔注〕[1]齐安郡：唐天宝元年（742）改黄州为齐安郡。治所在今湖北新洲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 794, "title": "齐安郡[1]后池绝句", "author": "杜牧", "body": "菱透浮萍绿锦池，夏莺千啭弄蔷薇。\n尽日无人看微雨，鸳鸯相对浴红衣。\n〔注〕[1]齐安郡：唐天宝元年（742）改黄州为齐安郡。治所在今湖北新洲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 795, "title": "题齐安城楼", "author": "杜牧", "body": "呜轧江楼角一声，微阳潋潋落寒汀。\n不用凭栏苦回首，故乡七十五长亭。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 796, "title": "初冬夜饮", "author": "杜牧", "body": "淮阳多病偶求欢，客袖侵霜与烛盘。\n砌下梨花一堆雪，明年谁此凭栏杆？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 797, "title": "早雁", "author": "杜牧", "body": "金河秋半虏弦开，云外惊飞四散哀。\n仙掌月明孤影过，长门灯暗数声来。\n须知胡骑纷纷在，岂逐春风一一回。\n莫厌潇湘少人处，水多菰米岸莓苔。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 798, "title": "屏风绝句", "author": "杜牧", "body": "屏风周昉画纤腰，岁久丹青色半销。\n斜倚玉窗鸾发女，拂尘犹自妒娇娆。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 799, "title": "赤壁", "author": "杜牧", "body": "折戟沉沙铁未销，自将磨洗认前朝。\n东风不与周郎便，铜雀春深锁二乔。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 800, "title": "泊秦淮", "author": "杜牧", "body": "烟笼寒水月笼沙，夜泊秦淮近酒家。\n商女[1]不知亡国恨，隔江犹唱《后庭花》。\n〔注〕[1]商女：歌女，一说是商人的妻女。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 801, "title": "秋浦途中", "author": "杜牧", "body": "萧萧山路穷秋雨，淅淅溪风一岸蒲。\n为问寒沙新到雁，来时还下杜陵无？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 802, "title": "题桃花夫人庙", "author": "杜牧", "body": "细腰宫里露桃新，脉脉无言几度春。\n至竟息亡缘底事？可怜金谷坠楼人！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 803, "title": "题乌江亭", "author": "杜牧", "body": "胜败兵家事不期，包羞忍耻是男儿。\n江东子弟多才俊，卷土重来未可知。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 804, "title": "寄扬州韩绰判官", "author": "杜牧", "body": "青山隐隐水迢迢，秋尽江南草未凋[1]。\n二十四桥明月夜，玉人何处教吹箫？\n〔注〕[1]江南：南北朝时，南朝与北朝隔江对峙，因称南朝及其统治下的地区为江南。《南史·魏虏传》:“［拓跋宏］甚重齐人，常谓其臣下曰：‘江南多好臣。'……”扬州地属南朝，故称“江南”。唐时仍沿用其称。“草未凋”一作“草木凋”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 805, "title": "题木兰庙", "author": "杜牧", "body": "弯弓征战作男儿，梦里曾经与画眉。\n几度思归还把酒，拂云堆上祝明妃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 806, "title": "赠别二首（其一）", "author": "杜牧", "body": "娉娉袅袅十三馀，豆蔻梢头二月初。\n春风十里扬州路，卷上珠帘总不如。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 807, "title": "赠别二首（其二）", "author": "杜牧", "body": "多情却似总无情，唯觉樽前笑不成。\n蜡烛有心还惜别，替人垂泪到天明。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 808, "title": "南陵道中", "author": "杜牧", "body": "南陵水面漫悠悠，风紧云轻欲变秋。\n正是客心孤迥处，谁家红袖凭江楼？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 809, "title": "遣怀", "author": "杜牧", "body": "落魄江湖载酒行，楚腰纤细掌中轻。\n十年一觉扬州梦，赢得青楼薄倖[1]名。\n〔注〕[1]薄倖：近人张相《诗词曲语辞汇释》:“薄倖，犹云薄情也。……然普通使用之义，则为所欢之暱称，犹之冤家，恨之深正见其爱之深也。杜牧《遣怀》:‘十年一觉扬州梦，赢得青楼薄倖名。’知已为妓女对于游婿之名称矣。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 810, "title": "叹花", "author": "杜牧", "body": "自是寻春去校迟，不须惆怅怨芳时。\n狂风落尽深红色，绿叶成阴子满枝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 811, "title": "山行", "author": "杜牧", "body": "远上寒山石径斜，白云生处有人家。\n停车坐爱枫林晚[1]，霜叶红于二月花。\n〔注〕[1]坐：因为。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 812, "title": "秋夕", "author": "杜牧", "body": "银烛秋光冷画屏，轻罗小扇扑流萤。\n天阶夜色凉如水，坐看牵牛织女星[1]。\n〔注〕[1]坐看：一作“卧看”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 813, "title": "金谷园", "author": "杜牧", "body": "繁华事散逐香尘，流水无情草自春。\n日暮东风怨啼鸟，落花犹似坠楼人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 814, "title": "清明[1]", "author": "杜牧", "body": "清明时节雨纷纷，路上行人欲断魂。\n借问酒家何处有，牧童遥指杏花村。\n〔注〕[1]此诗由于《樊川集》不收，仅首见于《后村千家诗》，《千家诗》继之，故近人多疑其伪。但宋初乐史《太平寰宇记》卷九十《昇州（治今江苏南京）》，已有“杏花村在（江宁）县理西，相传为杜牧之沽酒处”之记，可见至少在五代时就已将此诗的作者定为杜牧了。伪诗之说尚无确凿的根据。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 815, "title": "题情尽桥", "author": "雍陶", "body": "从来只有情难尽，何事名为情尽桥。\n自此改名为折柳，任他离恨一条条。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 816, "title": "题君山", "author": "雍陶", "body": "烟波不动影沉沉，碧色全无翠色深。\n疑是水仙梳洗处，一螺青黛镜中心。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 817, "title": "访城西友人别墅", "author": "雍陶", "body": "澧水桥西小路斜，日高犹未到君家。\n村园门巷多相似，处处春风枳壳花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 818, "title": "天津桥春望", "author": "雍陶", "body": "津桥春水浸红霞，烟柳风丝拂岸斜。\n翠辇不来金殿闭，宫莺衔出上阳花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 819, "title": "达摩支曲", "author": "温庭筠", "body": "捣麝成尘香不灭，拗莲作寸丝难绝。\n红泪文姬洛水春，白头苏武天山雪。\n君不见无愁高纬花漫漫，漳浦宴馀清露寒。\n一旦臣僚共囚虏，欲吹羌管先汍澜。\n旧臣头鬓霜华早，可惜雄心醉中老。\n万古春归梦不归，邺城风雨连天草。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 820, "title": "过陈琳墓", "author": "温庭筠", "body": "曾于青史见遗文，今日飘蓬过此坟。\n词客有灵应识我，霸才无主始怜君。\n石麟埋没藏春草，铜雀荒凉对暮云。\n莫怪临风倍惆怅，欲将书剑学从军。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 821, "title": "经五丈原", "author": "温庭筠", "body": "铁马云雕共绝尘，柳营高压汉宫春。\n天清杀气屯关右，夜半妖星照渭滨。\n下国卧龙空寤主，中原得鹿[1]不由人。\n象床宝帐[2]无言语，从此谯周是老臣。\n〔注〕[1]得鹿：语出《史记·淮阴侯列传》。蒯通对汉高祖云：“秦失其鹿，天下共逐之，于是高材疾足者先得焉。”比喻在夺取政权的斗争中获得胜利。 [2]象床宝帐：祠庙中神龛里的陈设。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 822, "title": "赠少年", "author": "温庭筠", "body": "江海相逢客恨多，秋风叶下洞庭波。\n酒酣夜别淮阴市，月照高楼一曲歌。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 823, "title": "蔡中郎坟", "author": "温庭筠", "body": "古坟零落野花春，闻说中郎有后身。\n今日爱才非昔日，莫抛心力作词人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 824, "title": "咸阳值雨", "author": "温庭筠", "body": "咸阳桥上雨如悬，万点空蒙隔钓船。\n还似洞庭春水色，晓云将入岳阳天。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 825, "title": "瑶瑟怨", "author": "温庭筠", "body": "冰簟银床梦不成，碧天如水夜云轻。\n雁声远过潇湘去，十二楼中月自明。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 826, "title": "过分水岭", "author": "温庭筠", "body": "溪水无情似有情，入山三日得同行。\n岭头便是分头处，惜别潺湲一夜声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 827, "title": "处士卢岵山居", "author": "温庭筠", "body": "西溪问樵客，遥识主人家。\n古树老连石，急泉清露沙。\n千峰随雨暗，一径入云斜。\n日暮鸟飞散，满山荞麦花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 828, "title": "碧涧驿晓思", "author": "温庭筠", "body": "香灯伴残梦，楚国在天涯。\n月落子规歇，满庭山杏花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 829, "title": "商山早行", "author": "温庭筠", "body": "晨起动征铎，客行悲故乡。\n鸡声茅店月，人迹板桥霜。\n槲叶落山路，枳花明驿墙。\n因思杜陵梦，凫雁满回塘。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 830, "title": "送人东归", "author": "温庭筠", "body": "荒戍落黄叶，浩然离故关。\n高风汉阳渡，初日郢门山。\n江上几人在，天涯孤棹还。\n何当重相见，尊酒慰离颜。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 831, "title": "苏武庙", "author": "温庭筠", "body": "苏武魂销汉使前，古祠高树两茫然。\n云边雁断胡天月，陇上羊归塞草烟。\n回日楼台非甲帐，去时冠剑是丁年。\n茂陵不见封侯印，空向秋波哭逝川。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 832, "title": "陇西行", "author": "陈陶", "body": "誓扫匈奴不顾身，五千貂锦丧胡尘。\n可怜无定河[1]边骨，犹是春闺梦里人。\n〔注〕[1]无定河：黄河中游支流，在今陕西北部。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 833, "title": "锦瑟", "author": "李商隐", "body": "锦瑟无端五十弦[1]，一弦一柱思[2]华年。\n庄生晓梦迷蝴蝶，望帝春心托杜鹃。\n沧海月明珠有泪，蓝田日暖玉生烟。\n此情可待成追忆，只是当时已惘然。\n〔注〕[1]五十弦：一般说法，古瑟是五十条弦，后来有二十五弦或十七弦等不同的瑟。 [2]柱：是调整弦的音调高低的“支柱”，用来把弦“架”住。它是可以移动的“活”柱，把它都用胶粘住了，瑟也就“死”了。有人把“柱”注成“系弦”的柱，误。“思”字应变读去声（sì）。律诗中不许有一连三个平声的出现。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 834, "title": "重过圣女祠", "author": "李商隐", "body": "白石岩扉碧藓滋，上清沦谪得归迟。\n一春梦雨常飘瓦，尽日灵风不满旗。\n萼绿华来无定所，杜兰香去未移时。\n玉郎会此通仙籍，忆向天阶问紫芝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 835, "title": "霜月", "author": "李商隐", "body": "初闻征雁已无蝉，百尺楼高水接天。\n青女素娥[1]俱耐冷，月中霜里斗婵娟[2]。\n〔注〕[1]青女：即青霄玉女，主霜雪的女神。素娥：即月里的嫦娥。 [2]婵娟：美好的容态。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 836, "title": "蝉", "author": "李商隐", "body": "本以高难饱，徒劳恨费声。\n五更疏欲断，一树碧无情。\n薄宦梗犹泛[1]，故园芜已平[2]。\n烦君最相警，我亦举家清。\n〔注〕[1]梗犹泛：《战国策·齐策》：桃梗（桃木人）谓土偶人（泥人）曰：“子（你），西岸之土也，挺（塑起）子以为人。至岁八月，降雨下，淄水至，则汝残矣。”土偶曰：“不然。吾，西岸之土也；吾残，则复西岸耳。今子，东国之桃梗也，刻削子以为人。降雨下，淄水至，流子而去，则子漂漂者将何如耳。”《说苑·正谏》里引“漂漂”作“泛泛”。 [2]故园芜已平：晋陶渊明《归去来兮辞》:“田园将芜胡不归。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 837, "title": "赠刘司户蕡", "author": "李商隐", "body": "江风扬浪动云根，重碇危樯白日昏。\n已断燕鸿初起势，更惊骚客后归魂。\n汉廷急诏谁先入，楚路高歌自欲翻。\n万里相逢欢复泣，凤巢西隔九重门。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 838, "title": "悼伤后赴东蜀辟至散关遇雪", "author": "李商隐", "body": "剑外从军远，无家与寄衣。\n散关三尺雪，回梦旧鸳机。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 839, "title": "乐游原", "author": "李商隐", "body": "向晚意不适，驱车登古原；\n夕阳无限好，只是近黄昏。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 840, "title": "北齐二首", "author": "李商隐", "body": "一笑相倾国便亡，何劳荆棘始堪伤。\n小怜玉体横陈夜，已报周师入晋阳。\n巧笑知堪敌万机，倾城最在著戎衣。\n晋阳已陷休回顾，更请君王猎一围。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 841, "title": "夜雨寄北", "author": "李商隐", "body": "君问归期未有期，巴山夜雨涨秋池。\n何当共剪西窗烛，却话巴山夜雨时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 842, "title": "忆梅", "author": "李商隐", "body": "定定住天涯，依依向物华。\n寒梅最堪恨，长作去年花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 843, "title": "赠柳", "author": "李商隐", "body": "章台[1]从掩映，郢[2]路更参差。\n见说风流极，来当婀娜时。\n桥回行欲断，堤远意相随。\n忍放花如雪，青楼[3]扑酒旗。\n〔注〕[1]章台：汉代京城长安街道名，街多柳树，唐时称为“章台柳”。 [2]郢：即今湖北江陵，战国时楚国建都于此。 [3]青楼：古代歌舞宴饮之地。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 844, "title": "宿骆氏亭寄怀崔雍崔衮", "author": "李商隐", "body": "竹坞无尘水槛清，相思迢递隔重城。\n秋阴不散霜飞晚，留得枯荷听雨声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 845, "title": "风雨", "author": "李商隐", "body": "凄凉宝剑篇，羁泊欲穷年。\n黄叶仍风雨，青楼自管弦。\n新知遭薄俗，旧好隔良缘。\n心断新丰酒，销愁斗几千？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 846, "title": "梦泽", "author": "李商隐", "body": "梦泽悲风动白茅，楚王葬尽满城娇。\n未知歌舞能多少，虚减宫厨为细腰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 847, "title": "寄令狐郎中", "author": "李商隐", "body": "嵩云秦树久离居，双鲤迢迢一纸书。\n休问梁园旧宾客，茂陵秋雨病相如。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 848, "title": "哭刘蕡", "author": "李商隐", "body": "上帝深宫闭九阍，巫咸不下问衔冤。\n黄陵别后春涛隔，湓浦书来秋雨翻。\n只有安仁能作诔，何曾宋玉解招魂！\n平生风义兼师友，不敢同君哭寝门。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 849, "title": "杜司勋", "author": "李商隐", "body": "高楼风雨感斯文，短翼差池不及群。\n刻意伤春复伤别，人间唯有杜司勋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 850, "title": "杜工部蜀中离席", "author": "李商隐", "body": "人生何处不离群？世路干戈惜暂分。\n雪岭未归天外使，松州犹驻殿前军。\n座中醉客延醒客，江上晴云杂雨云。\n美酒成都堪送老，当垆仍是卓文君。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 851, "title": "隋宫", "author": "李商隐", "body": "紫泉宫殿锁烟霞，欲取芜城[1]作帝家。\n玉玺不缘归日角[2]，锦帆应是到天涯。\n于今腐草无萤火，终古垂杨有暮鸦。\n地下若逢陈后主，岂宜重问《后庭花》！\n〔注〕[1]芜城：即广陵城，故址在今江苏省江都市境。因鲍照曾作《芜城赋》，写兵乱后扬州荒芜之况，故称芜城。这里仅用其字面。 [2]日角：指人的额骨突出饱满如日的样子。古人迷信骨相之术，认为人的一生贵贱，存乎骨相。《旧唐书·唐俭传》载：李渊起兵前，唐俭说他“日角龙庭”，必能取天下。诗中以“日角”指李渊。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 852, "title": "二月二日", "author": "李商隐", "body": "二月二日江上行，东风日暖闻吹笙。\n花鬚柳眼各无赖，紫蝶黄蜂俱有情。\n万里忆归元亮井，三年从事亚夫营。\n新滩莫悟游人意，更作风檐夜雨声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 853, "title": "筹笔驿", "author": "李商隐", "body": "猿鸟犹疑畏简书，风云长为护储胥。\n徒令上将挥神笔，终见降王走传车。\n管乐有才真不忝，关张无命欲何如？\n他年锦里经祠庙，梁父吟[1]成恨有馀。\n〔注〕[1]梁父吟：即《梁甫吟》，乐府楚调曲名。言人死葬梁甫山，为挽歌，歌词悲凉慷慨。今所传古辞相传为诸葛亮作。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 854, "title": "无题二首（其一）", "author": "李商隐", "body": "昨夜星辰昨夜风，画楼西畔桂堂东。\n身无彩凤双飞翼，心有灵犀一点通。\n隔座送钩春酒暖，分曹射覆蜡灯红。\n嗟余听鼓应官去，走马兰台类转蓬。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 855, "title": "无题四首（其一）", "author": "李商隐", "body": "来是空言去绝踪，月斜楼上五更钟。\n梦为远别啼难唤，书被催成墨未浓。\n蜡照半笼金翡翠，麝熏微度绣芙蓉。\n刘郎已恨蓬山远，更隔蓬山一万重！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 856, "title": "无题四首（其二）", "author": "李商隐", "body": "飒飒东风细雨来，芙蓉塘外有轻雷。\n金蟾啮锁烧香入，玉虎牵丝汲井回。\n贾氏窥帘韩掾少，宓妃留枕魏王才。\n春心莫共花争发，一寸相思一寸灰！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 857, "title": "无题四首（其四）", "author": "李商隐", "body": "何处哀筝随急管，樱花永巷垂杨岸。\n东家老女嫁不售，白日当天三月半。\n溧阳公主年十四，清明暖后同墙看。\n归来展转到五更，梁间燕子闻长叹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 858, "title": "王十二兄与畏之员外相访见招小饮时予以悼亡日近不去因寄", "author": "李商隐", "body": "谢傅门庭旧末行，今朝歌管属檀郎。\n更无人处帘垂地，欲拂尘时簟竟床。\n嵇氏幼男犹可悯，左家娇女岂能忘？\n愁霖腹疾俱难遣，万里西风夜正长。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 859, "title": "隋宫", "author": "李商隐", "body": "乘兴南游不戒严，九重谁省谏书函？\n春风举国裁宫锦，半作障泥半作帆。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 860, "title": "落花", "author": "李商隐", "body": "高阁客竟去，小园花乱飞。\n参差连曲陌，迢递送斜晖。\n肠断未忍扫，眼穿仍欲稀。\n芳心向春尽，所得是沾衣。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 861, "title": "柳", "author": "李商隐", "body": "曾逐东风拂舞筵，乐游春苑[1]断肠天。\n如何肯到清秋日，已带斜阳又带蝉！\n〔注〕[1]乐游春苑：指乐游苑，又称乐游原。长安东南名胜。地势很高，可俯瞰长安全城，是当时士女节日游赏之处。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 862, "title": "为有", "author": "李商隐", "body": "为有云屏无限娇，凤城寒尽怕春宵。\n无端嫁得金龟婿[1]，辜负香衾事早朝。\n〔注〕[1]金龟婿：佩有金龟袋的夫婿。《新唐书·车服志》:“天授二年，改佩鱼皆为龟。其后三品以上龟袋饰以金。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 863, "title": "无题", "author": "李商隐", "body": "相见时难别亦难，东风无力百花残。\n春蚕到死丝方尽，蜡炬成灰泪始干。\n晓镜但愁云鬓改，夜吟应觉月光寒。\n蓬山此去无多路，青鸟殷勤为探看。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 864, "title": "碧城三首（其一）", "author": "李商隐", "body": "碧城十二曲阑干，犀辟尘埃玉辟寒。\n阆苑有书多附鹤，女床无树不栖鸾。\n星沉海底当窗见，雨过河源隔座看[1]。\n若是晓珠明又定，一生长对水精盘。\n〔注〕[1]看（kān）：此处读阴平，不读去声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 865, "title": "端居", "author": "李商隐", "body": "远书归梦两悠悠，只有空床敌素秋。\n阶下青苔与红树，雨中寥落月中愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 866, "title": "咏史", "author": "李商隐", "body": "北湖南埭水漫漫，一片降旗百尺竿。\n三百年间同晓梦，钟山何处有龙盘？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 867, "title": "日射", "author": "李商隐", "body": "日射纱窗风撼扉，香罗拭手春事违。\n回廊四合掩寂寞，碧鹦鹉对红蔷薇。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 868, "title": "齐宫词", "author": "李商隐", "body": "永寿兵来夜不扃，金莲无复印中庭。\n梁台歌管三更罢，犹自风摇九子铃。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 869, "title": "十一月中旬至扶风界见梅花", "author": "李商隐", "body": "匝路亭亭艳，非时裛裛香。\n素娥惟与月，青女不饶霜[1]。\n赠远虚盈手，伤离适断肠。\n为谁成早秀？不待作年芳。\n〔注〕[1]“素娥”两句：《瀛奎律髓》方回批：“此谓梅花最宜月，不畏霜耳。添用素娥青女四字，则谓月若私之而独怜，霜若挫之而莫屈者，亦奇。”似与原意不符。同书纪昀批：“三、四爱之者虚而无益，妒之者实而有损。”似与原意较接近。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 870, "title": "汉宫词", "author": "李商隐", "body": "青雀西飞竟未回，君王长在集灵台[1]。\n侍臣最有相如渴，不赐金茎露一杯。\n〔注〕[1]集灵台：指汉武帝为求仙而兴造的建筑物。有集灵宫、望仙台等。唐亦有集灵台，在华清宫长生殿侧。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 871, "title": "马嵬（其二）", "author": "李商隐", "body": "海外徒闻更九州，他生未卜此生休。\n空闻虎旅鸣宵柝，无复鸡人报晓筹。\n此日六军同驻马，当时七夕笑牵牛。\n如何四纪[1]为天子，不及卢家有莫愁？\n〔注〕[1]纪：古代以十二年为一纪。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 872, "title": "富平少侯", "author": "李商隐", "body": "七国三边未到忧，十三身袭富平侯。\n不收金弹抛林外，却惜银床在井头。\n彩树转灯珠错落，绣檀回枕玉雕锼。\n当关不报侵晨客，新得佳人字莫愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 873, "title": "离亭赋得折杨柳（二首）", "author": "李商隐", "body": "暂凭尊酒送无憀，莫损愁眉与细腰。\n人世死前惟有别，春风争拟惜长条？\n含烟惹雾每依依，万绪千条拂落晖。\n为报行人休尽折，半留相送半迎归。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 874, "title": "宫妓", "author": "李商隐", "body": "珠箔轻明拂玉墀，披香新殿斗腰支。\n不须看尽鱼龙戏，终遣君王怒偃师。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 875, "title": "宫辞", "author": "李商隐", "body": "君恩如水向东流，得宠忧移失宠愁。\n莫向樽前奏《花落》，凉风只在殿西头。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 876, "title": "代赠二首（其一）", "author": "李商隐", "body": "楼上黄昏欲望休，玉梯横绝月如钩。\n芭蕉不展丁香结，同向春风各自愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 877, "title": "楚吟", "author": "李商隐", "body": "山上离宫宫上楼，楼前宫畔暮江流。\n楚天长短黄昏雨，宋玉无愁亦自愁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 878, "title": "瑶池", "author": "李商隐", "body": "瑶池阿母绮窗开，《黄竹》歌声动地哀。\n八骏[1]日行三万里，穆王何事不重来？\n〔注〕[1]八骏：穆王所乘的八匹骏马。《穆天子传》载其名为赤骥、盗骊、白义、逾轮、山子、渠黄、骅骝、绿耳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 879, "title": "韩冬郎即席为诗相送，一座尽惊。他日余方追吟“连宵侍坐徘徊久”之句，有老成之风，因成二绝寄酬，兼呈畏之员外（其一）", "author": "李商隐", "body": "十岁裁诗走马成，冷灰残烛动离情。\n桐花万里丹山路，雏凤清于老凤声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 880, "title": "板桥晓别", "author": "李商隐", "body": "回望高城落晓河，长亭窗户压微波。\n水仙欲上鲤鱼去，一夜芙蓉红泪多。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 881, "title": "银河吹笙", "author": "李商隐", "body": "怅望银河吹玉笙，楼寒院冷接平明。\n重衾幽梦他年断，别树羁雌昨夜惊。\n月榭故香因雨发，风帘残烛隔霜清。\n不须浪作缑山意，湘瑟秦箫自有情。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 882, "title": "重有感", "author": "李商隐", "body": "玉帐牙旗得上游，安危须共主君忧。\n窦融表已来关右，陶侃军宜次石头。\n岂有蛟龙愁失水？更无鹰隼與高秋！\n昼号夜哭兼幽显，早晚星关雪涕收？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 883, "title": "夕阳楼", "author": "李商隐", "body": "花明柳暗绕天愁，上尽重城更上楼。\n欲问孤鸿向何处，不知身世自悠悠。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 884, "title": "春雨", "author": "李商隐", "body": "怅卧新春白袷衣，白门寥落意多违。\n红楼隔雨相望冷，珠箔飘灯独自归。\n远路应悲春晼晚[1]，残宵犹得梦依稀。\n玉珰缄札何由达？万里云罗一雁飞。\n〔注〕[1]晼（wǎn）晚：双声叠韵联绵词，这里形容春将暮时景色暗淡的样子。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 885, "title": "楚宫", "author": "李商隐", "body": "湘波如泪色漻漻，楚厉迷魂逐恨遥。\n枫树夜猿愁自断，女萝山鬼语相邀。\n空归腐败犹难复，更困腥臊岂易招？\n但使故乡三户在，彩丝谁惜惧长蛟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 886, "title": "晚晴", "author": "李商隐", "body": "深居俯夹城，春去夏犹清。\n天意怜幽草，人间重晚晴。\n并添高阁迥，微注小窗明。\n越鸟巢干后，归飞体更轻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 887, "title": "安定城楼", "author": "李商隐", "body": "迢递高城百尺楼，绿杨枝外尽汀洲。\n贾生年少虚垂涕，王粲春来更远游。\n永忆江湖归白发，欲回天地入扁舟。\n不知腐鼠成滋味，猜意鹓鶵竟未休。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 888, "title": "天涯", "author": "李商隐", "body": "春日在天涯，天涯日又斜。\n莺啼如有泪，为湿最高花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 889, "title": "日日", "author": "李商隐", "body": "日日春光斗日光，山城斜路杏花香。\n几时心绪浑无事，得及游丝百尺长？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 890, "title": "龙池", "author": "李商隐", "body": "龙池赐酒敞云屏，羯鼓声高众乐停。\n夜半宴归宫漏永，薛王沉醉寿王醒。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 891, "title": "泪", "author": "李商隐", "body": "永巷长年怨绮罗，离情终日思风波。\n湘江竹上痕无限，岘首碑前洒几多？\n人去紫台秋入塞，兵残楚帐夜闻歌。\n朝来灞水[1]桥边问，未抵青袍送玉珂[2]！\n〔注〕[1]灞水：在长安城东面，过灞桥北流入渭河，唐代长安人常在桥边送别。 [2]青袍：古代读书人穿的衣服，诗中用以指贫寒之士。玉珂：为贝制的马络头上的饰物，诗中借指骑着骏马的达官贵人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 892, "title": "流莺", "author": "李商隐", "body": "流莺漂荡复参差，度陌临流不自持。\n巧啭岂能无本意，良辰未必有佳期。\n风朝露夜阴晴里，万户千门开闭时。\n曾苦伤春不忍听，凤城何处有花枝？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 893, "title": "七月二十九日崇让宅宴作", "author": "李商隐", "body": "露如微霰[1]下前池，风过回塘万竹悲。\n浮世本来多聚散，红蕖[2]何事亦离披？\n悠扬归梦惟灯见，濩落[3]生涯独酒知。\n岂到白头长只尔，嵩阳松雪有心期。\n〔注〕[1]霰（xián）：指由水汽凝成的微细冰粒。 [2]蕖（qú）：即芙蓉，也就是荷花。[3]濩（huò）落：空虚冷落的意思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 894, "title": "吴宫", "author": "李商隐", "body": "龙槛沉沉水殿清，禁门深掩断人声。\n吴王宴罢满宫醉，日暮水漂花出城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 895, "title": "嫦娥", "author": "李商隐", "body": "云母屏风烛影深，长河渐落晓星沉。\n嫦娥应悔偷灵药，碧海青天夜夜心。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 896, "title": "忆住一师", "author": "李商隐", "body": "无事经年别远公，帝城钟晓忆西峰。\n烟炉销尽寒灯晦，童子开门雪满松。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 897, "title": "微雨", "author": "李商隐", "body": "初随林霭动，稍共夜凉分。\n窗迥侵灯冷，庭虚近水闻。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 898, "title": "细雨", "author": "李商隐", "body": "帷飘白玉堂，簟卷碧牙床。\n楚女当时意，萧萧发彩凉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 899, "title": "无题二首", "author": "李商隐", "body": "凤尾香罗薄几重，碧文圆顶夜深缝。\n扇裁月魄羞难掩，车走雷声语未通。\n曾是寂寥金烬暗，断无消息石榴红。\n斑骓只系垂杨岸，何处西南待好风？\n重帏深下莫愁堂，卧后清宵细细长。\n神女生涯原是梦，小姑居处本无郎。\n风波不信菱枝弱，月露谁教桂叶香？\n直道相思了无益，未妨惆怅是清狂。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 900, "title": "贾生", "author": "李商隐", "body": "宣室求贤访逐臣，贾生才调更无伦。\n可怜夜半虚前席，不问苍生问鬼神。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 901, "title": "谒山", "author": "李商隐", "body": "从来系日乏长绳，水去云回恨不胜。\n欲就麻姑买沧海，一杯春露冷如冰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 902, "title": "哭刘司户蕡", "author": "李商隐", "body": "路有论冤谪，言皆在中兴。\n空闻迁贾谊，不待相孙弘。\n江阔惟回首，天高但抚膺。\n去年相送地，春雪满黄陵。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 903, "title": "凉思", "author": "李商隐", "body": "客去波平槛，蝉休露满枝。\n永怀当此节，倚立自移时。\n北斗兼春远，南陵寓使迟。\n天涯占梦数，疑误有新知。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 904, "title": "花下醉", "author": "李商隐", "body": "寻芳不觉醉流霞，倚树沉眠日已斜。\n客散酒醒深夜后，更持红烛赏残花。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 905, "title": "正月崇让宅", "author": "李商隐", "body": "密锁重关掩绿苔，廊深阁迥此徘徊。\n先知风起月含晕，尚自露寒花未开。\n蝙拂帘旌终展转，鼠翻窗网小惊猜。\n背灯独共馀香语，不觉犹歌《起夜来》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 906, "title": "曲江[1]", "author": "李商隐", "body": "望断平时翠辇过，空闻子夜鬼悲歌。\n金舆不返倾城色，玉殿犹分下苑波。\n死忆华亭闻唳鹤，老忧王室泣铜驼。\n天荒地变心虽折，若比伤春意未多。\n〔注〕[1]此诗主旨，旧有“专咏明皇、贵妃事”（张采田），“前四句追感玄宗与贵妃临幸时事，后四句则言王涯等被祸”（朱鹤龄），“伤文宗崩后杨贤妃赐死”（冯浩）及“专言文宗”（程梦星）诸说，此取程说。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 907, "title": "骄儿诗", "author": "李商隐", "body": "衮师我骄儿，美秀乃无匹。\n文葆未周晬，固已知六七。\n四岁知姓名，眼不视梨栗。\n交朋颇窥观，谓是丹穴物。\n前朝尚器貌，流品方第一。\n不然神仙姿，不尔燕鹤骨。\n安得此相谓？欲慰衰朽质。\n青春妍和月，朋戏浑甥侄。\n绕堂复穿林，沸若金鼎溢。\n门有长者来，造次请先出。\n客前问所须，含意不吐实。\n归来学客面，䦱败秉爷笏。\n或谑张飞胡，或笑邓艾吃。\n豪鹰毛崱屴，猛马气佶傈。\n截得青筼筜，骑走恣唐突。\n忽复学参军，按声唤苍鹘。\n又复纱灯旁，稽首礼夜佛。\n仰鞭罥蛛网，俯首饮花蜜。\n欲争蛱蝶轻，未谢柳絮疾。\n阶前逢阿姊，六甲颇输失。\n凝走弄香奁，拔脱金屈戌。\n抱持多反倒，威怒不可律。\n曲躬牵窗网，衉唾拭琴漆。\n有时看临书，挺立不动膝。\n古锦请裁衣，玉轴亦欲乞。\n请爷书春胜，春胜宜春日。\n芭蕉斜卷笺，辛夷低过笔。\n爷昔好读书，恳苦自著述。\n憔悴欲四十，无肉畏蚤虱。\n儿慎勿学爷，读书求甲乙。\n穰苴司马法，张良黄石术。\n便为帝王师，不假更纤悉。\n况今西与北，羌戎正狂悖。\n诛赦两未成，将养如痼疾。\n儿当速成大，探雏入虎穴。\n当为万户侯，勿守一经帙。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 908, "title": "黄陵庙", "author": "李群玉", "body": "小姑洲北浦云边，二女啼妆自俨然。\n野庙向江春寂寂，古碑无字草芊芊。\n风回日暮吹芳芷，月落山深哭杜鹃。\n犹似含颦望巡狩，九疑如黛隔湘川。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 909, "title": "放鱼", "author": "李群玉", "body": "早觅为龙去，江湖莫漫游。\n须知香饵下，触口是铦钩！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 910, "title": "火炉前坐", "author": "李群玉", "body": "孤灯照不寐，风雨满西林。\n多少关心事，书灰到夜深。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 911, "title": "引水行", "author": "李群玉", "body": "一条寒玉走秋泉，引出深萝洞口烟。\n十里暗流声不断，行人头上过潺湲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 912, "title": "黄陵庙", "author": "李群玉", "body": "黄陵庙前莎草[1]春，黄陵女儿蒨裙新。\n轻舟短棹唱歌去，水远山长愁杀人。\n〔注〕[1]莎（suō）草：为常见野草，地下块根称香附子，供药用。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 913, "title": "赠人", "author": "李群玉", "body": "曾留宋玉旧衣裳，惹得巫山梦里香。\n云雨无情难管领，任他别嫁楚襄王。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 914, "title": "鸂鶒", "author": "李群玉", "body": "锦羽相呼暮沙曲，波上双声戛哀玉。\n霞明川静极望中，一时飞灭青山绿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 915, "title": "书院二小松", "author": "李群玉", "body": "一双幽色出凡尘，数粒秋烟二尺鳞。\n从此静窗闻细韵，琴声长伴读书人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 916, "title": "秋寄从兄贾岛", "author": "无可", "body": "暝虫喧暮色，默思坐西林。\n听雨寒更彻，开门落叶深。\n昔因京邑病，并起洞庭心。\n亦是吾兄事，迟回共至今。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 917, "title": "贾客词", "author": "刘驾", "body": "贾客灯下起，犹言发已迟，\n高山有疾路，暗行终不疑。\n寇盗伏其路，猛兽来相追。\n金玉四散去，空囊委路歧。\n扬州有大宅，白骨无地归。\n少妇当此日，对镜弄花枝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 918, "title": "经炀帝行宫", "author": "刘沧", "body": "此地曾经翠辇[1]过，浮云流水竟如何？\n香销南国美人尽，怨入东风芳草多。\n残柳宫前空露叶，夕阳川上浩烟波。\n行人遥起广陵思，古渡月明闻棹歌。\n〔注〕[1]辇（niǎn）：皇帝坐的车。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 919, "title": "湖口送友人", "author": "李频", "body": "中流欲暮见湘烟，岸苇无穷接楚田。\n去雁远冲云梦雪，离人独上洞庭船。\n风波尽日依山转，星汉通霄向水悬。\n零落梅花过残腊，故园归去又新年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 920, "title": "哭李商隐（其二）", "author": "崔珏", "body": "虚负凌云万丈才，一生襟抱未曾开。\n鸟啼花落人何在，竹死桐枯凤不来。\n良马足因无主踠，旧交心为绝弦哀。\n九泉莫叹三光隔，又送文星[1]入夜台。\n〔注〕[1]文星：文曲星的省称，旧时谓此星主管文事。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 921, "title": "和友人鸳鸯之什[1]（其一）", "author": "崔珏", "body": "翠鬣红毛舞夕晖，水禽情似此禽稀。\n暂分烟岛犹回首，只渡寒塘亦并飞。\n映雾尽迷珠殿瓦，逐梭齐上玉人机。\n采莲无限兰桡女，笑指中流羡尔归。\n〔注〕[1]什：《诗经》雅、颂十篇为一什，故诗章有篇什之称。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 922, "title": "宫怨", "author": "司马札", "body": "柳色参差掩画楼，晓莺啼送满宫愁。\n年年花落无人见，空逐春泉出御沟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 923, "title": "宫词", "author": "薛逢", "body": "十二楼中尽晓妆，望仙楼上望君王。\n锁衔金兽连环冷，水滴铜龙昼漏长。\n云髻罢梳还对镜，罗衣欲换更添香。\n遥窥正殿帘开处，袍袴宫人扫御床。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 924, "title": "长安秋望", "author": "赵嘏", "body": "云物凄清拂曙流，汉家宫阙动高秋。\n残星几点雁横塞，长笛一声人倚楼。\n紫艳半开篱菊静，红衣落尽渚莲愁。\n鲈鱼正美不归去[1]，空戴南冠学楚囚[2]。\n〔注〕[1]“鲈鱼”句：《晋书·张翰传》:“翰因见秋风起，乃思吴中菰菜、莼羹、鲈鱼脍，曰：‘人生贵得适志，何能羁宦数千里，以要名爵乎？’遂命驾而归。” [2]南冠、楚囚：《左传·成公九年》:“楚子重侵陈以救郑。晋侯观于军府，见钟仪，问之曰：‘南冠而絷者，谁也？’有司对曰：‘郑人所献楚囚也。'”后以“南冠”、“楚囚”为囚徒的代称。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 925, "title": "寒塘", "author": "赵嘏", "body": "晓发梳临水，寒塘坐见秋。\n乡心正无限，一雁度南楼。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 926, "title": "江楼感旧", "author": "赵嘏", "body": "独上江楼思渺然，月光如水水如天。\n同来望月人何处？风景依稀似去年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 927, "title": "落日怅望", "author": "马戴", "body": "孤云与归鸟，千里片时间。\n念我何留滞，辞家久未还。\n微阳下乔木，远烧入秋山。\n临水不敢照，恐惊平昔颜！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 928, "title": "楚江怀古（其一）", "author": "马戴", "body": "露气寒光集，微阳下楚丘。\n猿啼洞庭树，人在木兰舟。\n广泽生明月，苍山夹乱流。\n云中君不见，竟夕自悲秋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 929, "title": "灞上秋居", "author": "马戴", "body": "灞原风雨定，晚见雁行频。\n落叶他乡树，寒灯独夜人。\n空园白露滴，孤壁野僧邻。\n寄卧郊扉久，何年致此身？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 930, "title": "出塞", "author": "马戴", "body": "金带连环束战袍，马头冲雪过临洮。\n卷旗夜劫单于帐，乱斫胡兵缺宝刀。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 931, "title": "三月晦日送客", "author": "崔橹", "body": "野酌乱无巡，送君兼送春。\n明年春色至，莫作未归人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 932, "title": "华清宫三首（其一、其三）", "author": "崔橹", "body": "草遮回磴绝鸣鸾，云树深深碧殿寒。\n明月自来还自去，更无人倚玉阑干。\n门横金锁悄无人，落日秋声渭水滨。\n红叶下山寒寂寂，湿云如梦雨如尘。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 933, "title": "题报恩寺上方[1]", "author": "方干", "body": "来来先上上方看，眼界无穷世界宽。\n岩溜喷空晴似雨，林萝碍日夏多寒。\n众山迢递皆相叠，一路高低不记盘。\n清峭关心惜归去，他时梦到亦难判。\n〔注〕[1]上方：住持僧居住的内室，这里借指佛寺。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 934, "title": "旅次洋州寓居郝氏林亭", "author": "方干", "body": "举目纵然非我有，思量似在故山时。\n鹤盘远势投孤屿，蝉曳残声过别枝。\n凉月照窗攲枕倦，澄泉绕石泛觞迟。\n青云未得平行去，梦到江南身旅羁。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 935, "title": "题君山[1]", "author": "方干", "body": "曾于方外见麻姑，闻说君山自古无。\n元是昆仑山顶石，海风吹落洞庭湖。\n〔注〕[1]此诗一作程贺《咏君山》，“自古”作“此本”，“元”作“云”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 936, "title": "官仓鼠", "author": "曹邺", "body": "官仓老鼠大如斗，见人开仓亦不走。\n健儿无粮百姓饥，谁遣朝朝入君口？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 937, "title": "山亭夏日", "author": "高骈", "body": "绿树阴浓夏日长，楼台倒影入池塘。\n水精帘动微风起，满架蔷薇一院香。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 938, "title": "马嵬坡", "author": "郑畋", "body": "玄宗回马杨妃死，云雨难忘日月新。\n终是圣明天子事，景阳宫井又何人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 939, "title": "雪诗", "author": "张孜", "body": "长安大雪天，鸟雀难相觅。\n其中豪贵家，捣椒泥四壁。\n到处爇红炉，周回下罗幂。\n暖手调金丝，蘸甲[1]斟琼液。\n醉唱玉尘[2]飞，困融香汗滴。\n岂知饥寒人，手脚生皴劈。\n〔注〕[1]蘸甲：酒斟满，捧觞必蘸指甲，故古人称斟满酒为蘸甲。 [2]玉尘：指雪。南朝梁何逊《和司马博士咏雪》:“若逐微风起，谁言非玉尘。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 940, "title": "辛苦吟", "author": "于濆", "body": "垅上扶犁儿，手种腹长饥。\n窗下投梭女，手织身无衣。\n我愿燕赵姝，化为嫫母姿。\n一笑不值钱，自然家国肥。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 941, "title": "古宴曲", "author": "于濆", "body": "雉扇合蓬莱，朝车回紫陌。\n重门集嘶马，言宴金张宅。\n燕娥奉卮酒，低鬟若无力。\n十户手胼胝，凤凰钗一只。\n高楼齐下视，日照罗衣色。\n笑指负薪人，不信生中国。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 942, "title": "里中女", "author": "于濆", "body": "吾闻池中鱼，不识海水深；\n吾闻桑下女，不识华堂阴。\n贫窗苦机杼，富家鸣杵砧。\n天与双明眸，只教识蒿簪。\n徒惜越娃貌，亦蕴韩娥音[1]。\n珠玉不到眼，遂无奢侈心。\n岂知赵飞燕，满髻钗黄金。\n〔注〕[1]韩娥音：《列子·汤问》:“昔韩娥东之齐，匮粮。过雍门，鬻歌假食。既去，而余音绕梁欐，三日不绝。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 943, "title": "赠妓云英", "author": "罗隐", "body": "钟陵醉别十馀春，重见云英掌上身。\n我未成名君未嫁，可能俱是不如人？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 944, "title": "黄河", "author": "罗隐", "body": "莫把阿胶向此倾，此中天意固难明。\n解通银汉应须曲，才出昆仑便不清。\n高祖誓功衣带小，仙人占斗客槎轻。\n三千年后知谁在？何必劳君报太平！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 945, "title": "西施", "author": "罗隐", "body": "家国兴亡自有时，吴人何苦怨西施。\n西施若解倾吴国，越国亡来又是谁？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 946, "title": "自遣[1]", "author": "罗隐", "body": "得即高歌失即休，多愁多恨亦悠悠。\n今朝有酒今朝醉，明日愁来明日愁。\n〔注〕[1]此诗作者一作权审。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 947, "title": "鹦鹉", "author": "罗隐", "body": "莫恨雕笼翠羽残，江南地暖陇西寒。\n劝君不用分明语，语得分明出转难。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 948, "title": "金钱花", "author": "罗隐", "body": "占得佳名绕树芳，依依相伴向秋光。\n若教此物堪收贮，应被豪门尽劚[1]将。\n〔注〕[1]劚（zhú）：掘，砍。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 949, "title": "柳", "author": "罗隐", "body": "灞岸晴来送别频，相偎相倚不胜春。\n自家飞絮犹无定，争解垂丝绊路人？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 950, "title": "雪", "author": "罗隐", "body": "尽道丰年瑞，丰年事若何？\n长安有贫者，为瑞不宜多。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 951, "title": "绵谷回寄蔡氏昆仲", "author": "罗隐", "body": "一年两度锦江游，前值东风后值秋。\n芳草有情皆碍马，好云无处不遮楼。\n山牵别恨和肠断，水带离声入梦流。\n今日因君试回首，淡烟乔木隔绵州。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 952, "title": "蜂", "author": "罗隐", "body": "不论平地与山尖，无限风光尽被占。\n采得百花成蜜后，为谁辛苦为谁甜？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 953, "title": "感弄猴人赐朱绂", "author": "罗隐", "body": "十二三年就试期，五湖烟月奈相违。\n何如学取孙供奉，一笑君王便着绯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 954, "title": "橡媪叹", "author": "皮日休", "body": "秋深橡子熟，散落榛芜冈。\n伛偻黄发媪，拾之践晨霜。\n移时始盈掬，尽日方满筐。\n几曝复几蒸，用作三冬粮。\n山前有熟稻，紫穗袭人香。\n细获又精舂，粒粒如玉珰。\n持之纳于官，私室无仓箱。\n如何一石馀，只作五斗量！\n狡吏不畏刑，贪官不避赃。\n农时作私债，农毕归官仓。\n自冬及于春，橡实诳饥肠。\n吾闻田成子[1]，诈仁犹自王。\n吁嗟逢橡媪，不觉泪沾裳。\n〔注〕[1]田成子：名陈恒，又名田常，是春秋时齐简公相。他以大斗出贷、小斗收取，获得齐人拥护。后来，田成子杀齐简公，立简公之弟平公，田成子为相。后田成子的后人夺齐国王位而自立。（事见《史记·田敬仲完世家》）作者是说，田成子假仁假义，却还不失为王，而现在的官吏只知残害百姓，连假仁假义都没有了。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 955, "title": "馆娃宫怀古五绝（其一）", "author": "皮日休", "body": "绮阁飘香下太湖，乱兵侵晓上姑苏。\n越王大有堪羞处，只把西施赚得吴。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 956, "title": "春夕酒醒", "author": "皮日休", "body": "四弦才罢醉蛮奴[1]，酃醁[2]馀香在翠炉。\n夜半醒来红蜡短，一枝寒泪作珊瑚。\n〔注〕[1]蛮奴：也可指歌舞伎，如罗邺“江上吹笛舞蛮奴”（《自遣》）。此处“蛮奴”，是皮日休的自称。在宋代以前，男女尊卑，皆可自称“奴”。《通典》:“襄阳，春秋以来楚地也。”当时中原地区诸国称楚为“荆蛮”。日休，襄阳人，故自称“蛮奴”。 [2]酃醁（línglù）：酒名。《北堂书钞》引《吴录》：湘东酃县有酃水，能酿美酒，因以水为酒名。据说唐初宰相魏徵善治酒，名曰“酃醁”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 957, "title": "汴河怀古（其二）", "author": "皮日休", "body": "尽道隋亡为此河，至今千里赖通波。\n若无水殿龙舟事，共禹论功不较多？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 958, "title": "别离", "author": "陆龟蒙", "body": "丈夫非无泪，不洒离别间。\n杖剑对尊酒，耻为游子颜。\n蝮蛇一螫手，壮士即解腕。\n所志在功名，离别何足叹。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 959, "title": "和袭美春夕酒醒", "author": "陆龟蒙", "body": "几年无事傍江湖，醉倒黄公旧酒垆。\n觉后不知明月上，满身花影倩人扶。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 960, "title": "白莲", "author": "陆龟蒙", "body": "素蘤[1]多蒙别艳欺，此花端合在瑶池。\n无情有恨何人觉，月晓风清欲堕时。\n〔注〕[1]蘤（huā）：古“花”字。这里的素蘤，就是素质的意思。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 961, "title": "新沙", "author": "陆龟蒙", "body": "渤澥[1]声中涨小堤，官家知后海鸥知。\n蓬莱有路教人到，应亦年年税紫芝。\n〔注〕[1]渤澥（xiè）：即渤海。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 962, "title": "怀宛陵旧游", "author": "陆龟蒙", "body": "陵阳佳地昔年游，谢朓青山李白楼。\n唯有日斜溪上思，酒旗风影落春流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 963, "title": "忆昔", "author": "韦庄", "body": "昔年曾向五陵游，子夜歌清月满楼。\n银烛树前长似昼，露桃花里不知秋。\n西园公子[1]名无忌，南国佳人号莫愁[2]。\n今日乱离俱是梦，夕阳唯见水东流！\n〔注〕[1]西园公子：指三国魏文帝及其弟曹植等。曹氏有西园，曹丕为公子时尝夜宴文士于此，丕有“乘辇夜行游，逍遥步西园”之句，曹植《公宴诗》也说：“公子敬爱客，终宴不知疲。清夜游西园，飞盖相追随。” [2]莫愁：乐府诗《莫愁乐》云：“莫愁在何处，莫愁石城西。”梁武帝有“河中之水向东流，洛阳女儿名莫愁”（《河中之水歌》）之句。历来注家均以为莫愁是传说中善歌谣的少女名。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 964, "title": "送日本国僧敬龙归", "author": "韦庄", "body": "扶桑已在渺茫中，家在扶桑东更东。\n此去与师谁共到？一船明月一帆风。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 965, "title": "金陵图", "author": "韦庄", "body": "谁谓伤心画不成？画人心逐世人情。\n君看六幅南朝事，老木寒云满故城。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 966, "title": "陪金陵府相中堂夜宴", "author": "韦庄", "body": "满耳笙歌满眼花，满楼珠翠胜吴娃[1]。\n因知海上神仙窟，只似人间富贵家。\n绣户夜攒红烛市，舞衣晴曳碧天霞。\n却愁宴罢青娥[2]散，扬子江头月半斜。\n〔注〕[1]吴娃：《文选·左思〈吴都赋〉》:“幸乎馆娃之宫。”刘良注：“吴俗谓好女为娃。”[2]青娥：指年轻貌美的女子。曹松《夜饮》诗：“席上未知帘幕晓，青娥低语指东方。”", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 967, "title": "台城", "author": "韦庄", "body": "江雨霏霏江草齐，六朝如梦鸟空啼。\n无情最是台城柳，依旧烟笼十里堤。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 968, "title": "与东吴生相遇", "author": "韦庄", "body": "十年身事各如萍，白首相逢泪满缨。\n老去不知花有态，乱来唯觉酒多情。\n贫疑陋巷春偏少，贵想豪家月最明。\n且对一尊开口笑，未衰应见泰阶平。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 969, "title": "古离别", "author": "韦庄", "body": "晴烟漠漠柳毵毵[1]，不那[2]离情酒半酣。\n更把玉鞭云外指，断肠春色在江南。\n〔注〕[1]毵毵（sān）：柳叶纷披下垂貌。 [2]不那：同“不奈”，即无奈。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 970, "title": "秦妇吟", "author": "韦庄", "body": "中和癸卯春三月，洛阳城外花如雪。\n东西南北路人绝，绿杨悄悄香尘灭。\n路旁忽见如花人，独向绿杨阴下歇。\n凤侧鸾欹鬓脚斜，红攒黛敛眉心折。\n借问女郎何处来？含嚬欲语声先咽。\n回头敛袂谢行人，丧乱漂沦何堪说！\n三年陷贼留秦地，依稀记得秦中事。\n君能为妾解金鞍，妾亦与君停玉趾。\n前年庚子腊月五，正闭金笼教鹦鹉。\n斜开鸾镜懒梳头，闲凭雕栏慵不语。\n忽看门外起红尘，已见街中擂金鼓。\n居人走出半仓皇，朝士归来尚疑误。\n是时四面官军入，拟向潼关为警急；\n皆言博野自相持，尽道贼军来未及。\n须臾主父乘奔至，下马入门痴似醉。\n适逢紫盖去蒙尘，已见白旗来匝地。\n扶羸携幼竞相呼，上屋缘墙不知次。\n南邻走入北邻藏，东邻走向西邻避；\n北邻诸妇咸相凑，户外崩腾如走兽。\n轰轰崐崐乾坤动，万马雷声从地涌。\n火迸金星上九天，十二官街烟烘烔。\n日轮西下寒光白，上帝无言空脉脉。\n阴云晕气若重围，宦者流星如血色。\n紫气潜随帝座移，妖光暗射台星拆。\n家家流血如泉沸，处处冤声声动地。\n舞伎歌姬尽暗损，婴儿稚女皆生弃。\n东邻有女眉新画，倾国倾城不知价。\n长戈拥得上戎车，回首香闺泪盈把。\n旋抽金线学缝旗，才上雕鞍教走马。\n有时马上见良人，不敢回眸空泪下。\n西邻有女真仙子，一寸横波剪秋水。\n妆成只对镜中春，年幼不知门外事。\n一夫跳跃上金阶，斜袒半肩欲相耻。\n牵衣不肯出朱门，红粉香脂刀下死。\n南邻有女不记姓，昨日良媒新纳聘。\n瑠瓈阶上不闻行，翡翠帘间空见影。\n忽看庭际刀刃鸣，身首支离在俄顷。\n仰天掩面哭一声，女弟女兄同入井。\n北邻少妇行相促，旋解云鬟拭眉绿。\n已闻击托坏高门，不觉攀缘上重屋。\n须臾四面火光来，欲下回梯梯又摧。\n烟中大叫犹求救，梁上悬尸已作灰。\n妾身幸得全刀锯，不敢踟蹰久回顾。\n旋梳蝉鬓逐军行，强展蛾眉出门去。\n旧里从兹不得归，六亲自此无寻处。\n一从陷贼经三载，终日惊忧心胆碎。\n夜卧千重剑戟围，朝餐一味人肝脍。\n鸳帏纵入岂成欢？宝货虽多非所爱。\n蓬头面垢狵眉赤，几转横波看不得。\n衣裳颠倒言语异，面上夸功雕作字。\n柏台多士尽狐精，兰省诸郎皆鼠魅。\n还将短发戴华簪，不脱朝衣缠绣被；\n翻持象笏作三公，倒佩金鱼为两史。\n朝闻奏对入朝堂，暮见喧呼来酒市。\n一朝五鼓人惊起，呼啸喧争如窃语。\n夜来探马入皇城，昨日官军收赤水；\n赤水去城一百里，朝若来兮暮应至。\n凶徒马上暗吞声，女伴闺中潜生喜。\n皆言冤愤此时销，必谓妖徒今日死。\n逡巡走马传声急，又道官军全阵入；\n大彭小彭相顾忧，二郎四郎抱鞍泣。\n沉沉数日无消息，必谓军前已衔璧；\n簸旗掉剑却来归，又道官军悉败绩。\n四面从兹多厄束，一斗黄金一升粟。\n尚让厨中食木皮，黄巢机上刲人肉。\n东南断绝无粮道，沟壑渐平人渐少。\n六军门外倚僵尸，七架营中填饿殍。\n长安寂寂今何有，废市荒街麦苗秀。\n采樵斫尽杏园花，修寨诛残御沟柳。\n华轩绣毂皆销散，甲第朱门无一半。\n含元殿上狐兔行，花萼楼前荆棘满。\n昔时繁盛皆埋没，举目凄凉无故物。\n内库烧为锦绣灰，天街踏尽公卿骨。\n来时晓出城东陌，城外风烟如塞色。\n路旁时见游奕军，坡下寂无迎送客。\n霸陵东望人烟绝，树锁骊山金翠灭。\n大道俱成棘子林，行人夜宿墙匡月。\n明朝晓至三峰路，百万人家无一户。\n破落田园但有蒿，催残竹树皆无主。\n路旁试问金天神，金天无语愁于人。\n庙前古柏有残枿，殿上金炉生暗尘。\n一从狂寇陷中国，天地晦冥风雨黑；\n案前神水咒不成，壁上阴兵驱不得。\n闲日徒歆奠飨恩，危时不助神通力。\n我今愧恧拙为神，且向山中深避匿；\n寰中箫管不曾闻，筵上牺牲无处觅。\n旋教魇鬼傍乡村，诛剥生灵过朝夕。\n妾闻此语愁更愁，天遣时灾非自由。\n神在山中犹避难，何须责望东诸侯！\n前年又出杨震关，举头云际见荆山。\n如从地府到人间，顿觉时清天地闲。\n陕州主帅忠且贞，不动干戈唯守城。\n蒲津主帅能兵，千里晏然无戈声。\n朝携宝货无人问，夜插金钗唯独行。\n明朝又过新安东，路上乞浆逢一翁。\n苍苍面带苔藓色，隐隐身藏蓬荻中。\n问翁本是何乡曲？底是寒天霜露宿？\n老翁蹔起欲陈辞，却坐支颐仰天哭。\n乡园本贯东畿县，岁岁耕桑临近甸；\n岁种良田二百廛，年输户税三千万。\n小姑惯织褐絁袍，中妇能炊红黍饭。\n千间仓兮万丝箱，黄巢过后犹残半。\n自从洛下屯师旅，日夜巡兵入村坞；\n匣中秋水拔青蛇，旗上高风吹白虎。\n入门下马若旋风，罄室倾囊如卷土。\n家财既尽骨肉离，今日垂年一身苦。\n一身苦兮何足嗟，山中更有千万家。\n朝饥山上寻蓬子，夜宿霜中卧荻花。\n妾闻此父伤心语，竟日阑干泪如雨。\n出门唯见乱枭鸣，更欲东奔何处所？\n仍闻汴路舟车绝，又道彭门自相杀；\n野色徒销战士魂，河津半是冤人血。\n适闻有客金陵至，见说江南风景异。\n自从大寇犯中原，戎马不曾生四鄙；\n诛锄窃盗若神功，惠爱生灵如赤子。\n城壕固护教金汤，赋税如云送军垒。\n奈何四海尽滔滔，湛然一境平如砥。\n避难徒为阙下人，怀安却羡江南鬼。\n愿君举棹东复东，咏此长歌献相公。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 971, "title": "题菊花", "author": "黄巢", "body": "飒飒西风满院栽，蕊寒香冷蝶难来。\n他年我若为青帝，报与桃花一处开。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 972, "title": "菊花", "author": "黄巢", "body": "待到秋来九月八，我花开后百花杀。\n冲天香阵透长安，满城尽带黄金甲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 973, "title": "续韦蟾句", "author": "武昌妓", "body": "悲莫悲兮生别离，登山临水送将归。\n武昌无限新栽柳，不见杨花扑面飞。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 974, "title": "伤田家", "author": "聂夷中", "body": "二月卖新丝，五月粜新谷。\n医得眼前疮，剜却心头肉。\n我愿君王心，化作光明烛。\n不照绮罗筵，只照逃亡屋。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 975, "title": "云", "author": "来鹄", "body": "千形万象竟还空，映水藏山片复重。\n无限旱苗枯欲尽，悠悠闲处作奇峰。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 976, "title": "江行无题（百首选一）", "author": "钱珝", "body": "咫尺愁风雨，匡庐不可登。\n只疑云雾窟，犹有六朝僧。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 977, "title": "未展芭蕉", "author": "钱珝", "body": "冷烛无烟绿蜡干，芳心犹卷怯春寒。\n一缄书札藏何事，会被东风暗拆看。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 978, "title": "书边事", "author": "张乔", "body": "调角断清秋，征人倚戍楼。\n春风对青冢，白日落梁州。\n大漠无兵阻，穷边有客游。\n蕃情似此水，长愿向南流。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 979, "title": "河湟旧卒", "author": "张乔", "body": "少年随将讨河湟，头白时清返故乡。\n十万汉军零落尽，独吹边曲向残阳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 980, "title": "下第后上永崇[1]高侍郎", "author": "高蟾", "body": "天上碧桃和露种，日边红杏倚云栽。\n芙蓉生在秋江上，不向东风怨未开。\n〔注〕[1]永崇：唐时长安的坊名。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 981, "title": "焚书坑", "author": "章碣", "body": "竹帛烟销帝业虚，关河空锁祖龙[1]居。\n坑灰未冷山东[2]乱，刘项原来不读书。\n〔注〕[1]祖龙：《史记·秦始皇本纪》集解引苏林说：“祖，始也。龙，人君象。谓始皇也。”[2]山东：崤函以东，一说指太行山以东的地区，即战国末年秦以外六国的地盘。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 982, "title": "东都望幸", "author": "章碣", "body": "懒修珠翠上高台，眉月连娟恨不开。\n纵使东巡也无益，君王自领美人来。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 983, "title": "写真寄外", "author": "薛媛", "body": "欲下丹青笔，先拈宝镜寒。\n已惊颜索寞，渐觉鬓凋残。\n泪眼描将易，愁肠写出难。\n恐君浑忘却，时展画图看。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 984, "title": "己亥岁（二首选一）", "author": "曹松", "body": "泽国江山入战图，生民何计乐樵苏。\n凭君莫话封侯事，一将功成万骨枯。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 985, "title": "南海旅次", "author": "曹松", "body": "忆归休上越王台，归思临高不易裁。\n为客正当无雁处，故园谁道有书来。\n城头早角吹霜尽，郭里残潮荡月回。\n心似百花开未得，年年争发被春催。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 986, "title": "西施滩", "author": "崔道融", "body": "宰嚭亡吴国，西施陷恶名。\n浣纱春水急，似有不平声。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 987, "title": "溪上遇雨二首（其二）", "author": "崔道融", "body": "坐看黑云衔猛雨，喷洒前山此独晴。\n忽惊云雨在头上，却是山前晚照明。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 988, "title": "溪居即事", "author": "崔道融", "body": "篱外谁家不系船，春风吹入钓鱼湾。\n小童疑是有村客，急向柴门去却关。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 989, "title": "故都", "author": "韩偓", "body": "故都遥想草萋萋，上帝深疑亦自迷。\n塞雁已侵池籞宿，宫鸦犹恋女墙啼。\n天涯烈士空垂涕，地下强魂必噬脐。\n掩鼻计成终不觉，冯驩无路学鸣鸡。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 990, "title": "自沙县抵龙溪县，值泉州军过后，村落皆空，因有一绝", "author": "韩偓", "body": "水自潺湲[1]日自斜，尽无鸡犬有鸣鸦。\n千村万落如寒食[2]，不见人烟空见花。\n〔注〕[1]潺湲：水慢慢流动的样子。 [2]寒食：指寒食节，旧俗此节禁烟火，吃冷食。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 991, "title": "深院", "author": "韩偓", "body": "鹅儿唼喋栀黄嘴，凤子轻盈腻粉腰。\n深院下帘人昼寝，红蔷薇架碧芭蕉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 992, "title": "安贫", "author": "韩偓", "body": "手风慵展八行书，眼暗休寻九局图。\n窗里日光飞野马，案头筠管长蒲卢。\n谋身拙为安蛇足，报国危曾捋虎须。\n举世可能无默识，未知谁拟试齐竽？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 993, "title": "惜花", "author": "韩偓", "body": "皱白离情高处切，腻红愁态静中深。\n眼随片片沿流去，恨满枝枝被雨淋。\n总得苔遮犹慰意，若教泥污更伤心。\n临轩一盏悲春酒，明日池塘是绿阴。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 994, "title": "春尽", "author": "韩偓", "body": "惜春连日醉昏昏，醒后衣裳见酒痕。\n细水浮花归别涧，断云含雨入孤村。\n人闲易有芳时恨，地迥难招自古魂。\n惭愧流莺相厚意，清晨犹为到西园。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 995, "title": "已凉", "author": "韩偓", "body": "碧阑干外绣帘垂，猩色屏风画折枝。\n八尺龙须方锦褥，已凉天气未寒时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 996, "title": "寒食夜", "author": "韩偓", "body": "恻恻轻寒翦翦风，小梅飘雪杏花红[1]。\n夜深斜搭秋千索，楼阁朦胧烟雨中。\n〔注〕[1]这句诗一作“杏花飘雪小桃红”，但参证《偶见》中“手搓梅子”句及另一首《寒食夜有寄》诗中“隔帘微雨杏花香”句，似宜定为“小梅飘雪杏花红”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 997, "title": "效崔国辅体四首", "author": "韩偓", "body": "淡月照中庭，海棠花自落。\n独立俯闲阶，风动秋千索。\n酒力滋睡眸，卤莽闻街鼓。\n欲明天更寒，东风打窗雨。\n雨后碧苔院，霜来红叶楼。\n闲阶上斜日，鹦鹉伴人愁。\n罗幕生春寒，绣窗愁未眠。\n南湖一夜雨，应湿采莲船。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 998, "title": "卖花翁", "author": "吴融", "body": "和烟和露一丛花，担入宫城许史家。\n惆怅东风无处说，不教闲地著春华。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 999, "title": "金桥感事", "author": "吴融", "body": "太行和雪叠晴空，二月郊原尚朔风。\n饮马早闻临渭北，射雕今欲过山东。\n百年徒有伊川叹，五利宁无魏绛功？\n日暮长亭正愁绝，哀笳一曲戍烟中。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1000, "title": "子规", "author": "吴融", "body": "举国繁华委逝川，羽毛飘荡一年年。\n他山叫处花成血，旧苑春来草似烟。\n雨暗不离浓绿树，月斜长吊欲明天。\n湘江日暮声凄切，愁杀行人归去船。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1001, "title": "途中见杏花", "author": "吴融", "body": "一枝红艳出墙头，墙外行人正独愁。\n长得看来犹有恨，可堪逢处更难留！\n林空色暝莺先到，春浅香寒蝶未游。\n更忆帝乡千万树，澹烟笼日暗神州。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1002, "title": "登单于台", "author": "张蠙", "body": "边兵春尽回，独上单于台。\n白日地中出，黄河天外来。\n沙翻痕似浪，风急响疑雷。\n欲向阴关度，阴关晓不开。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1003, "title": "夏日题老将林亭", "author": "张蠙", "body": "百战功成翻爱静，侯门渐欲似仙家。\n墙头雨细垂纤草，水面风回聚落花。\n井放辘轳闲浸酒，笼开鹦鹉报煎茶。\n几人图在凌烟阁，曾不交锋向塞沙？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1004, "title": "怀良人", "author": "葛鸦儿", "body": "蓬鬓荆钗世所稀，布裙犹是嫁时衣。\n胡麻好种无人种，正是归时底不归？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1005, "title": "春怨", "author": "金昌绪", "body": "打起黄莺儿，莫教枝上啼。\n啼时惊妾梦，不得到辽西。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1006, "title": "赠卖松人", "author": "于武陵", "body": "入市虽求利，怜君意独真。\n欲将寒涧树，卖与翠楼人。\n瘦叶几经雪，淡花应少春。\n长安重桃李，徒染六街尘！", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1007, "title": "劝酒", "author": "于武陵", "body": "劝君金屈卮，满酌不须辞。\n花发多风雨，人生足别离。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1008, "title": "江陵愁望有寄", "author": "鱼玄机", "body": "枫叶千枝复万枝，江桥掩映暮帆迟。\n忆君心似西江水，日夜东流无歇时。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1009, "title": "席上贻歌者", "author": "郑谷", "body": "花月楼台近九衢，清歌一曲倒金壶。\n座中亦有江南客，莫向春风唱《鹧鸪》。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1010, "title": "菊", "author": "郑谷", "body": "王孙莫把比蓬蒿，九日枝枝近鬓毛。\n露湿秋香满池岸，由来不羡瓦松高。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1011, "title": "淮上与友人别", "author": "郑谷", "body": "扬子江头杨柳春，杨花愁杀渡江人。\n数声风笛离亭晚，君向潇湘我向秦。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1012, "title": "鹧鸪", "author": "郑谷", "body": "暖戏烟芜锦翼齐，品流应得近山鸡。\n雨昏青草湖边过，花落黄陵庙里啼。\n游子乍闻征袖湿，佳人才唱翠眉低。\n相呼相应湘江阔，苦竹丛深日向西。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1013, "title": "海棠", "author": "郑谷", "body": "春风用意匀颜色，销得[1]携觞与赋诗。\n秾丽最宜新著雨，娇娆全在欲开时。\n莫愁粉黛临窗懒，梁广丹青点笔迟。\n朝醉暮吟看不足，羡他蝴蝶宿深枝。\n〔注〕[1]销得：值得之意。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1014, "title": "中年", "author": "郑谷", "body": "漠漠秦云淡淡天，新年景象入中年。\n情多最恨花无语，愁破方知酒有权。\n苔色满墙寻故第，雨声一夜忆春田。\n衰迟自喜添诗学，更把前题改数联。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1015, "title": "春宫怨", "author": "杜荀鹤", "body": "早被婵娟误，欲妆临镜慵。\n承恩不在貌，教妾若为容？\n风暖鸟声碎，日高花影重。\n年年越溪女，相忆采芙蓉。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1016, "title": "送友游吴越", "author": "杜荀鹤", "body": "去越从吴过，吴疆与越连。\n有园多种橘，无水不生莲。\n夜市桥边火，春风寺外船。\n此中偏重客，君去必经年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1017, "title": "山中寡妇", "author": "杜荀鹤", "body": "夫因兵死守蓬茅，麻苎衣衫鬓发焦。\n桑柘废来犹纳税，田园荒后尚征苗。\n时挑野菜和根煮，旋斫生柴带叶烧。\n任是深山更深处，也应无计避征徭。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1018, "title": "自叙", "author": "杜荀鹤", "body": "酒瓮琴书伴病身，熟谙时事乐于贫。\n宁为宇宙闲吟客，怕作乾坤窃禄人。\n诗旨未能忘救物，世情奈值不容真。\n平生肺腑无言处，白发吾唐一逸人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1019, "title": "再经胡城县[1]", "author": "杜荀鹤", "body": "去岁曾经此县城，县民无口不冤声。\n今来县宰加朱绂[2]，便是生灵血染成。\n〔注〕[1]胡城县：唐时县名，故址在今安徽阜阳县西北。 [2]朱绂（fú）：红色官服。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1020, "title": "溪兴", "author": "杜荀鹤", "body": "山雨溪风卷钓丝，瓦瓯篷底独斟时。\n醉来睡着无人唤，流到前溪也不知。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1021, "title": "赠质上人", "author": "杜荀鹤", "body": "枿坐云游出世尘，兼无瓶钵可随身。\n逢人不说人间事，便是人间无事人。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1022, "title": "小松", "author": "杜荀鹤", "body": "自小刺头深草里，而今渐觉出蓬蒿。\n时人不识凌云木，直待凌云始道高。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1023, "title": "比红儿诗（百首选一）", "author": "罗虬", "body": "薄罗轻剪越溪纹，鸦翅低从两鬓分。\n料得相如偷见面，不应琴里挑文君。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1024, "title": "春晚书山家屋壁二首", "author": "贯休", "body": "柴门寂寂黍饭馨，山家烟火春雨晴。\n庭花蒙蒙水泠泠，小儿啼索树上莺。\n水香塘黑蒲森森，鸳鸯鸂鶒如家禽。\n前村后垄桑柘深，东邻西舍无相侵。\n蚕娘洗茧前溪渌，牧童吹笛和衣浴。\n山翁留我宿又宿，笑指西坡瓜豆熟。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1025, "title": "孤雁", "author": "崔涂", "body": "几行归塞尽，念尔独何之？\n暮雨相呼失，寒塘欲下迟。\n渚云低暗度，关月冷相随。\n未必逢矰缴[1]，孤飞自可疑。\n〔注〕[1]矰（zēng）：短箭。缴（zhuó）：系箭的丝绳。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1026, "title": "春夕", "author": "崔涂", "body": "水流花谢两无情，送尽东风过楚城。\n蝴蝶梦中家万里，子规枝上月三更。\n故园书动经年绝，华发春唯满镜生。\n自是不归归便得，五湖[1]烟景有谁争？\n〔注〕[1]五湖：春秋时越国大夫范蠡归隐之处。这里诗人指他的家乡浙江桐庐一带的大好山水。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1027, "title": "初渡汉江", "author": "崔涂", "body": "襄阳好向岘亭看，人物萧条属岁阑。\n为报习家多置酒，夜来风雪过江寒。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1028, "title": "贫女", "author": "秦韬玉", "body": "蓬门未识绮罗香，拟托良媒益自伤。\n谁爱风流高格调，共怜时世俭梳妆[1]。\n敢将十指夸针巧，不把双眉斗画长。\n苦恨年年压金线[2]，为他人作嫁衣裳！\n〔注〕[1]俭梳妆：“俭”通“险”，怪异的意思；“险梳妆”，就是奇形怪状的穿着打扮。[2]压金线：用金线刺绣。压：手指按住，刺绣的一种手法。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1029, "title": "画松", "author": "景云", "body": "画松一似真松树，且待寻思记得无？\n曾在天台山上见，石桥南畔第三株。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1030, "title": "采桑女", "author": "唐彦谦", "body": "春风吹蚕细如蚁，桑芽才努青鸦嘴。\n侵晨采桑谁家女，手挽长条泪如雨。\n去岁初眠当此时，今岁春寒叶放迟。\n愁听门外催里胥，官家二月收新丝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1031, "title": "垂柳", "author": "唐彦谦", "body": "绊惹春风别有情，世间谁敢斗轻盈？\n楚王江畔无端种，饿损纤腰学不成。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1032, "title": "社日", "author": "王驾", "body": "鹅湖山下稻粱肥，豚栅鸡栖半掩扉。\n桑柘影斜春社散，家家扶得醉人归。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1033, "title": "雨晴", "author": "王驾", "body": "雨前初见花间蕊，雨后全无叶底花[1]。\n蜂蝶纷纷过墙去[2]，却疑春色在邻家。\n〔注〕[1]全：一作“兼”。 [2]蜂：一作“蛱”。纷纷：一作“飞来”。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1034, "title": "古意", "author": "王驾", "body": "夫戍边关妾在吴，西风吹妾妾忧夫。\n一行书信千行泪，寒到君边衣到无？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1035, "title": "早梅", "author": "齐己", "body": "万木冻欲折，孤根暖独回。\n前村深雪里，昨夜一枝开。\n风递幽香出，禽窥素艳来。\n明年如应律，先发望春台。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1036, "title": "绣岭宫词", "author": "李洞", "body": "春日迟迟春草绿，野棠开尽飘香玉。\n绣岭宫前鹤发翁，犹唱开元太平曲。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1037, "title": "和李秀才边庭四时怨（其四）", "author": "卢汝弼", "body": "朔风吹雪透刀瘢，饮马长城窟更寒。\n半夜火来知有敌，一时齐保贺兰山。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1038, "title": "述国亡诗", "author": "花蕊夫人", "body": "君王城上竖降旗，妾在深宫那得知？\n十四万人齐解甲，更无一个是男儿。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1039, "title": "寄人[1]", "author": "张佖", "body": "别梦依依到谢家，小廊回合曲阑斜。\n多情只有春庭月，犹为离人照落花。\n〔注〕[1]清人李良年《词坛纪事》云：“张佖（一作泌）仕南唐为内史舍人。初与邻女浣衣相善，作《江神子》词。……后经年不复相见，张夜梦之，写绝句云云。”即是此诗。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1040, "title": "诗", "author": "捧剑仆", "body": "青鸟衔葡萄，飞上金井栏。\n美人恐惊去，不敢卷帘看。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1041, "title": "公子行", "author": "孟宾于", "body": "锦衣红夺彩霞明，侵晓春游向野庭。\n不识农夫辛苦力，骄骢踏烂麦青青。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1042, "title": "题玉泉溪", "author": "湘驿女子", "body": "红树醉秋色，碧溪弹夜弦。\n佳期不可再，风雨杳如年。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1043, "title": "幽恨诗", "author": "安邑坊女", "body": "卜得上峡日，秋江风浪多。\n巴陵一夜雨，肠断木兰歌。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1044, "title": "金缕衣", "author": "无名氏", "body": "劝君莫惜金缕衣，劝君须惜少年时。\n有花堪折直须折，莫待无花空折枝。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1045, "title": "杂诗", "author": "无名氏", "body": "旧山虽在不关身，且向长安过暮春。\n一树梨花一溪月，不知今夜属何人？", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1046, "title": "杂诗", "author": "无名氏", "body": "无定河边暮角声，赫连台畔旅人情。\n函关归路千馀里，一夕秋风白发生。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1047, "title": "水调歌", "author": "无名氏", "body": "平沙落日大荒西，陇上明星高复低。\n孤山几处看烽火，壮士连营候鼓鼙。", "category": "唐诗", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1048, "title": "点绛唇", "author": "王禹偁", "body": "雨恨云愁，江南依旧称佳丽。水村渔市，一缕孤烟细。\n天际征鸿，遥认行如缀。平生事，此时凝睇，谁会凭栏意！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1049, "title": "踏莎行 春暮", "author": "寇準", "body": "春色将阑，莺声渐老，红英落尽青梅小。画堂人静雨蒙蒙，屏山半掩余香袅。 密约沉沉，离情杳杳，菱花尘满慵将照。倚楼无语欲销魂，长空暗淡连芳草。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1050, "title": "江南春", "author": "寇準", "body": "波渺渺，柳依依。孤村芳草远，斜日杏花飞。江南春尽离肠断，蘋满汀洲人未归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1051, "title": "玉楼春", "author": "钱惟演", "body": "城上风光莺语乱，城下烟波春拍岸。绿杨芳草几时休，泪眼愁肠先已断。 情怀渐觉成衰晚，鸾镜朱颜惊暗换。昔时多病厌芳尊，今日芳尊惟恐浅。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1052, "title": "踏莎行", "author": "陈尧佐", "body": "二社良辰，千秋庭院。翩翩又见新来燕。凤凰巢稳许为邻，潇湘烟暝来何晚。 乱入红楼，低飞绿岸。画梁时拂歌尘散。为谁归去为谁来，主人恩重珠帘卷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1053, "title": "酒泉子", "author": "潘阆", "body": "长忆西湖，尽日凭阑楼上望：三三两两钓鱼舟，岛屿正清秋。 笛声依约芦花里，白鸟成行忽惊起。别来闲整钓鱼竿，思入水云寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1054, "title": "酒泉子", "author": "潘阆", "body": "长忆西山，灵隐寺前三竺后，冷泉亭上旧曾游，三伏似清秋。 白猿时见攀高树，长啸一声何处去？别来几向画图看，终是欠峰峦！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1055, "title": "酒泉子", "author": "潘阆", "body": "长忆观潮，满郭人争江上望，来疑沧海尽成空，万面鼓声中。 弄潮儿向涛头立，手把红旗旗不湿。别来几向梦中看，梦觉尚心寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1056, "title": "长相思", "author": "林逋", "body": "吴山青，越山青。两岸青山相送迎，谁知离别情？ 君泪盈，妾泪盈。罗带同心结未成，江头潮已平。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1057, "title": "点绛唇", "author": "林逋", "body": "金谷年年，乱生春色谁为主？余花落处，满地和烟雨。\n又是离歌，一阕长亭暮。王孙去。萋萋无数，南北东西路。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1058, "title": "少年游", "author": "杨亿", "body": "江南节物，水昏云淡，飞雪满前村。千寻翠岭，一枝芳艳，迢递寄归人。 寿阳妆罢，冰姿玉态，的的写天真。等闲风雨又纷纷，更忍向、笛中闻。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1059, "title": "生查子 药名闺情", "author": "陈亚", "body": "相思意已深，白纸书难足。字字苦参商，故要檀郎①读。\n分明记得约当归，远至樱桃熟。何事菊花时，犹未回乡曲？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1060, "title": "鹧鸪天①", "author": "夏竦", "body": "镇日无心扫黛眉，临行愁见理征衣。尊前只恐伤郎意，阁泪汪汪不敢垂。 停宝马，捧瑶卮，相斟相劝忍分离？不如饮待奴先醉，图得不知郎去时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1061, "title": "苏幕遮", "author": "范仲淹", "body": "碧云天，黄叶地，秋色连波，波上寒烟翠。山映斜阳天接水，芳草无情，更在斜阳外。 黯乡魂，追旅思，夜夜除非，好梦留人睡。明月楼高休独倚。酒入愁肠，化作相思泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1062, "title": "渔家傲", "author": "范仲淹", "body": "塞下秋来风景异，衡阳雁去无留意。四面边声连角起。千嶂里，长烟落日孤城闭。 浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地。人不寐，将军白发征夫泪！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1063, "title": "御街行", "author": "范仲淹", "body": "纷纷坠叶飘香砌。夜寂静，寒声碎。真珠帘卷玉楼空，天淡银河垂地。年年今夜，月华如练，长是人千里。 愁肠已断无由醉，酒未到，先成泪。残灯明灭枕头敧，谙尽孤眠滋味。都来此事，眉间心上，无计相回避。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1064, "title": "剔银灯", "author": "范仲淹", "body": "与欧阳公席上分题①\n昨夜因看蜀志②，笑曹操孙权刘备。用尽机关，徒劳心力，只得三分天地。屈指细寻思，争③如共、刘伶④一醉？ 人世都⑤无百岁。少痴騃⑥、老成尪悴⑦。只有中间，些子⑧少年，忍把浮名⑨牵系？一品⑩与千金，问白发、如何回避？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1065, "title": "甘草子", "author": "柳永", "body": "秋暮，乱洒衰荷，颗颗真珠雨。雨过月华生，冷彻鸳鸯浦。\n池上凭阑愁无侣，奈此个、单栖情绪！却傍金笼共鹦鹉，念粉郎言语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1066, "title": "昼夜乐", "author": "柳永", "body": "洞房记得初相遇。便只合、长相聚。何期小会幽欢，变作离情别绪。况值阑珊春色暮。对满目、乱花狂絮。直恐好风光，尽随伊归去。 一场寂寞凭谁诉。算前言，总轻负。早知恁地难拚，悔不当时留住。其奈风流端正外，更别有、系人心处。一日不思量，也攒眉千度。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1067, "title": "曲玉管", "author": "柳永", "body": "陇首云飞，江边日晚，烟波满目凭阑久。一望关河萧索，千里清秋，忍凝眸？ 杳杳神京，盈盈仙子，别来锦字终难偶。断雁无凭，冉冉飞下汀洲，思悠悠。 暗想当初，有多少、幽欢佳会，岂知聚散难期，翻成雨恨云愁？阻追游。每登山临水，惹起平生心事，一场消黯，永日无言，却下层楼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1068, "title": "雨霖铃", "author": "柳永", "body": "寒蝉凄切。对长亭晚，骤雨初歇。都门帐饮无绪，留恋处、兰舟催发。执手相看泪眼，竟无语凝噎。念去去、千里烟波，暮霭沉沉楚天阔。 多情自古伤离别，更那堪冷落清秋节！今宵酒醒何处？杨柳岸、晓风残月。此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说？\n雨霖铃（寒蝉凄切） 柳 永\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1069, "title": "迷仙引", "author": "柳永", "body": "才过笄年，初绾云鬟，便学歌舞。席上尊前，王孙随分相许。算等闲、酬一笑，便千金慵觑。常只恐、容易蕣华偷换，光阴虚度。 已受君恩顾，好与花为主。万里丹霄，何妨携手同归去。永弃却、烟花伴侣。免教人见妾，朝云暮雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1070, "title": "归朝欢", "author": "柳永", "body": "别岸扁舟三两只。葭苇萧萧风淅淅。沙汀宿雁破烟飞，溪桥残月和霜白。渐渐分曙色。路遥山远多行役。往来人，只轮双桨，尽是利名客。 一望乡关烟水隔。转觉归心生羽翼。愁云恨雨两牵萦，新春残腊相催逼。岁华都瞬息。浪萍风梗诚何益。归去来，玉楼深处，有个人相忆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1071, "title": "婆罗门令", "author": "柳永", "body": "昨宵里恁和衣睡，今宵里又恁和衣睡。小饮归来，初更过，醺醺醉。中夜后、何事还惊起？霜天冷，风细细，触疏窗、闪闪灯摇曳。 空床展转重追想，云雨梦、任敧枕难继。寸心万绪，咫尺千里。好景良天，彼此，空有相怜意，未有相怜计。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1072, "title": "蝶恋花", "author": "柳永", "body": "伫倚危楼风细细，望极春愁，黯黯生天际。草色烟光残照里，无言谁会凭阑意。 拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1073, "title": "卜算子慢", "author": "柳永", "body": "江枫渐老，汀蕙半凋，满目败红衰翠。楚客登临，正是暮秋天气。引疏碪、断续残阳里。对晚景、伤怀念远，新愁旧恨相继。 脉脉人千里。念两处风情，万重烟水。雨歇天高，望断翠峰十二。尽无言、谁会凭高意？纵写得、离肠万种，奈归云谁寄？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1074, "title": "浪淘沙慢", "author": "柳永", "body": "梦觉、透窗风一线，寒灯吹息。那堪酒醒，又闻空阶，夜雨频滴。嗟因循、久作天涯客。负佳人、几许盟言，更忍把、从前欢会，陡顿翻成忧戚。 愁极。再三追思，洞房深处，几度饮散歌阕。香暖鸳鸯被，岂暂时疏散，费伊心力。殢雨尤云，有万般千种，相怜相惜。 恰到如今、天长漏永，无端自家疏隔。知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1075, "title": "破阵乐", "author": "柳永", "body": "露花倒影，烟芜蘸碧，灵沼①波暖。金柳摇风树树，系彩舫龙舟遥岸。千步虹桥，参差雁齿②，直趋水殿。绕金堤，曼衍鱼龙③戏，簇娇春罗绮，喧天丝管。霁色荣光④，望中似睹，蓬莱清浅。 时见。凤辇宸游，鸾觞禊饮，临翠水，开镐宴⑤。两两轻舠⑥飞画楫，竞夺锦标霞烂⑦。罄欢娱，歌《鱼藻》⑧，徘徊宛转。别有盈盈游女，各委明珠，争收翠羽，相将归远。渐觉云海沈沈，洞天日晚。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1076, "title": "二郎神", "author": "柳永", "body": "炎光谢。过暮雨、芳尘轻洒。乍露冷风清庭户爽，天如水、玉钩遥挂。应是星娥嗟久阻，叙旧约、飙轮欲驾。极目处、微云暗度，耿耿银河高泻。 闲雅。须知此景，古今无价。运巧思穿针楼上女，抬粉面、云鬟相亚。钿合金钗私语处，算谁在、回廊影下。愿天上人间，占得欢娱，年年今夜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1077, "title": "锦堂春", "author": "柳永", "body": "坠髻慵梳，愁蛾懒画，心绪是事阑珊。觉新来憔悴，金缕衣宽。认得这疏狂意下，向人诮譬如闲。把芳容整顿，恁地轻孤，争忍心安。 依前过了旧约，甚当初赚我，偷剪云鬟。几时得归来，香阁深关。待伊要、尤云殢雨，缠绣衾、不与同欢。尽更深、款款问伊，今后敢更无端。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1078, "title": "定风波", "author": "柳永", "body": "自春来、惨绿愁红，芳心是事可可。日上花梢，莺穿柳带，犹压香衾卧。暖酥消，腻云亸，终日厌厌倦梳裹。无那！恨薄情一去，音书无个。 早知恁么，悔当初、不把雕鞍锁。向鸡窗，只与蛮笺象管，拘束教吟课。镇相随，莫抛躲，针线闲拈伴伊坐。和我，免使年少光阴虚过。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1079, "title": "诉衷情近", "author": "柳永", "body": "雨晴气爽，伫立江楼望处。澄明远水生光，重叠暮山耸翠。遥认断桥幽径，隐隐渔村，向晚孤烟起。 残阳里。脉脉朱阑静倚。黯然情绪，未饮先如醉。愁无际。暮云过了，秋光老尽，故人千里。尽日空凝睇。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1080, "title": "集贤宾", "author": "柳永", "body": "小楼深巷狂游遍，罗绮成丛。就中堪人属意，最是虫虫。有画难描雅态，无花可比芳容。几回饮散良宵永，鸳衾暖、凤枕香浓。算得人间天上，惟有两心同。 近来云雨忽西东。诮恼损情悰。纵然偷期暗会，长是匆匆。争似和鸣偕老，免教敛翠啼红。眼前时、暂疏欢宴，盟言在、更莫忡忡。待作真个宅院，方信有初终。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1081, "title": "少年游", "author": "柳永", "body": "长安古道马迟迟，高柳乱蝉嘶。夕阳鸟外，秋风原上，目断四天垂。 归云一去无踪迹，何处是前期？狎兴生疏，酒徒萧索，不似少年时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1082, "title": "少年游", "author": "柳永", "body": "参差烟树霸陵桥，风物尽前朝。衰杨古柳，几经攀折，憔悴楚宫腰。 夕阳闲淡秋光老，离思满蘅皋。一曲《阳关》，断肠声尽，独自凭兰桡。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1083, "title": "驻马听", "author": "柳永", "body": "凤枕鸾帷。二三载，如鱼似水相知。良天好景，深怜多爱，无非尽意依随。奈何伊。恣性灵、忒煞些儿。无事孜煎，万回千度，怎忍分离。 而今渐行渐远，渐觉虽悔难追。漫寄消寄息，终久奚为。也拟重论缱绻，争奈翻覆思维。纵再会，只恐恩情，难似当时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1084, "title": "戚氏", "author": "柳永", "body": "晚秋天，一霎微雨洒庭轩。槛菊萧疏，井梧零乱，惹残烟。凄然，望江关，飞云黯淡夕阳闲。当时宋玉悲感，向此临水与登山。远道迢递，行人凄楚，倦听陇水潺湲。正蝉吟败叶，蛩响衰草，相应喧喧。 孤馆，度日如年。风露渐变，悄悄至更阑。长天净，绛河清浅，皓月婵娟。思绵绵。夜永对景那堪，屈指暗想从前。未名未禄，绮陌红楼，往往经岁迁延。 帝里风光好，当年少日，暮宴朝欢。况有狂朋怪侣，遇当歌对酒竞留连。别来迅景如梭，旧游似梦，烟水程何限。念利名憔悴长萦绊。追往事、空惨愁颜。漏箭移，稍觉轻寒。渐呜咽画角数声残。对闲窗畔，停灯向晓，抱影无眠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1085, "title": "夜半乐", "author": "柳永", "body": "冻云黯淡天气，扁舟一叶，乘兴离江渚。渡万壑千岩，越溪深处。怒涛渐息，樵风①乍起，更闻商旅相呼，片帆高举。泛画鹢、翩翩过南浦。 望中酒旆闪闪，一簇烟村，数行霜树。残日下、渔人鸣榔归去。败荷零落，衰柳掩映，岸边两两三三、浣纱游女。避行客、含羞笑相语。 到此因念，绣阁轻抛，浪萍难驻。叹后约、丁宁竟何据！惨离怀、空恨岁晚归期阻。凝泪眼、杳杳神京路。断鸿声远长天暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1086, "title": "望海潮", "author": "柳永", "body": "东南形胜，三吴都会，钱塘自古繁华。烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙。怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。 重湖叠巘清嘉。有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。千骑拥高牙。乘醉听箫鼓，吟赏烟霞。异日图将好景，归去凤池夸。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1087, "title": "玉蝴蝶", "author": "柳永", "body": "望处雨收云断，凭阑悄悄，目送秋光。晚景萧疏，堪动宋玉悲凉。水风轻、蘋花渐老，月露冷、梧叶飘黄。遣情伤。故人何在，烟水茫茫。 难忘。文期酒会，几孤风月，屡变星霜。海阔山遥，未知何处是潇湘！念双燕、难凭远信，指暮天、空识归航。黯相望。断鸿声里，立尽斜阳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1088, "title": "满江红", "author": "柳永", "body": "暮雨初收，长川静，征帆夜落。临岛屿，蓼烟疏淡，苇风萧索。几许渔人飞短艇，尽载灯火归村落。遣行客、当此念回程，伤漂泊。 桐江好，烟漠漠。波似染，山如削。绕严陵滩畔，鹭飞鱼跃。游宦区区成底事？平生况有云泉约。归去来，一曲仲宣吟，从军乐。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1089, "title": "引驾行", "author": "柳永", "body": "红尘紫陌，斜阳暮草长安道，是离人。断魂处，迢迢匹马西征。新晴。韶光明媚，轻烟淡薄和气暖，望花村。路隐映，摇鞭时过长亭。愁生。伤凤城仙子，别来千里重行行。又记得、临歧泪眼，湿莲脸盈盈。 消凝。花朝月夕，最苦冷落银屏。想媚容、耿耿无眠，屈指已算回程。相萦。空万般思忆，争如归去睹倾城。向绣帏、深处并枕，说如此牵情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1090, "title": "八声甘州", "author": "柳永", "body": "对潇潇暮雨洒江天，一番洗清秋。渐霜风凄紧，关河冷落，残照当楼。是处红衰翠减，苒苒物华休。惟有长江水，无语东流。 不忍登高临远，望故乡渺邈，归思难收。叹年来踪迹，何事苦淹留？想佳人妆楼颙望，误几回、天际识归舟。争知我，倚阑干处，正恁凝愁！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1091, "title": "竹马子", "author": "柳永", "body": "登孤垒荒凉，危亭旷望，静临烟渚。对雌霓挂雨，雄风拂槛，微收烦暑。渐觉一叶惊秋，残蝉噪晚，素商时序。览景想前欢，指神京，非雾非烟深处。 向此成追感，新愁易积，故人难聚。凭高尽日凝伫。赢得消魂无语。极目霁霭霏微，暝鸦零乱，萧索江城暮。南楼画角，又送残阳去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1092, "title": "迷神引", "author": "柳永", "body": "一叶扁舟轻帆卷。暂泊楚江南岸。孤城暮角，引胡笳怨。水茫茫，平沙雁，旋惊散。烟敛寒林簇，画屏展。天际遥山小，黛眉浅。 旧赏轻抛，到此成游宦。觉客程劳，年光晚。异乡风物，忍萧索、当愁眼。帝城赊，秦楼阻，旅魂乱。芳草连空阔，残照满。佳人无消息，断云远。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1093, "title": "木兰花慢", "author": "柳永", "body": "拆桐花烂熳，乍疏雨、洗清明。正艳杏烧林，缃桃绣野，芳景如屏。倾城，尽寻胜去，骤雕鞍绀幰出郊坰。风暖繁弦脆管，万家竞奏新声。 盈盈，斗草踏青。人艳冶，递逢迎。向路旁往往，遗簪堕珥，珠翠纵横。欢情，对佳丽地，信金罍罄竭玉山倾。拚却明朝永日，画堂一枕春酲。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1094, "title": "忆帝京", "author": "柳永", "body": "薄衾小枕凉天气，乍觉别离滋味。展转数寒更，起了还重睡。毕竟不成眠，一夜长如岁。 也拟待、却回征辔；又争奈、已成行计。万种思量，多方开解，只恁寂寞厌厌地。系我一生心，负你千行泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1095, "title": "安公子", "author": "柳永", "body": "远岸收残雨，雨残稍觉江天暮。拾翠①汀洲人寂静，立双双鸥鹭。望几点、渔灯隐映蒹葭浦。停画桡、两两舟人语。道去程今夜，遥指前村烟树。 游宦成羁旅，短樯吟倚闲凝伫。万水千山迷远近，想乡关何处？自别后、风亭月榭孤欢聚。刚断肠、惹得离情苦。听杜宇声声，劝人不如归去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1096, "title": "倾杯", "author": "柳永", "body": "鹜落霜洲，雁横烟渚，分明画出秋色。暮雨乍歇，小楫夜泊，宿苇村山驿。何人月下临风处，起一声羌笛。离愁万绪，闲岸草、切切蛩吟似织。 为忆芳容别后，水遥山远，何计凭鳞翼。想绣阁深沉，争知憔悴损，天涯行客。楚峡云归，高阳人散，寂寞狂踪迹。望京国。空目断、远峰凝碧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1097, "title": "鹤冲天", "author": "柳永", "body": "黄金榜上，偶失龙头望。明代暂遗贤，如何向？未遂风云便，争不恣狂荡？何须论得丧。才子词人，自是白衣卿相。 烟花巷陌，依约丹青屏障。幸有意中人，堪寻访。且恁偎红倚翠，风流事，平生畅。青春都一饷。忍把浮名，换了浅斟低唱！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1098, "title": "醉垂鞭", "author": "张先", "body": "双蝶绣罗裙，东池宴，初相见。朱粉不深匀，闲花淡淡春。\n细看诸处好，人人道，柳腰身。昨日乱山昏，来时衣上云。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1099, "title": "菩萨蛮", "author": "张先", "body": "忆郎还上层楼曲。楼前芳草年年绿。绿似去时袍。回头风袖飘。 郎袍应已旧。颜色非长久。惜恐镜中春。不如花草新。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1100, "title": "谢池春慢", "author": "张先", "body": "玉仙观道中逢谢媚卿\n缭墙重院，时闻有、啼莺到。绣被掩余寒，画阁明新晓。朱槛连空阔，飞絮知多少？径莎平，池水渺。日长风静，花影闲相照。 尘香拂马，逢谢女、城南道。秀艳过施粉，多媚生轻笑。斗色鲜衣薄，碾玉双蝉小。欢难偶，春过了。琵琶流怨，都入相思调。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1101, "title": "惜双双 溪桥寄意", "author": "张先", "body": "城上层楼天边路，残照里、平芜绿树。伤远更惜春暮，有人还在高高处。 断梦归云经日去，无计使、哀弦寄语。相望恨不相遇，倚桥临水谁家住。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1102, "title": "江南柳", "author": "张先", "body": "隋堤远，波急路尘轻。今古柳桥多送别，见人分袂亦愁生。何况自关情。 斜照后，新月上西城。城上楼高重倚望，愿身能似月亭亭，千里伴君行。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1103, "title": "一丛花令", "author": "张先", "body": "伤高怀远几时穷？无物似情浓。离愁正引千丝乱，更东陌、飞絮濛濛。嘶骑渐遥，征尘不断，何处认郎踪！ 双鸳池沼水溶溶，南北小桡通。梯横画阁黄昏后，又还是、斜月帘栊。沉恨细思，不如桃杏，犹解嫁东风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1104, "title": "相思令", "author": "张先", "body": "蘋满溪。柳绕堤。相送行人溪水西。回时陇月低。\n烟霏霏。风凄凄。重倚朱门听马嘶。寒鸥相对飞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1105, "title": "更漏子", "author": "张先", "body": "锦筵红，罗幕翠。侍宴美人姝丽。十五六，解怜才。劝人深酒杯。 黛眉长，檀口小。耳畔向人轻道。柳阴曲，是儿家。门前红杏花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1106, "title": "蝶恋花", "author": "张先", "body": "移得绿杨栽后院，学舞宫腰，二月青犹短。不比灞陵多送远，残丝乱絮东西岸。 几叶小眉寒不展，莫唱《阳关》，真个肠先断。分付与春休细看，条条尽是离人怨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1107, "title": "诉衷情", "author": "张先", "body": "花前月下暂相逢。苦恨阻从容。何况酒醒梦断，花谢月朦胧。 花不尽，月无穷。两心同。此时愿作，杨柳千丝，绊惹春风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1108, "title": "减字木兰花", "author": "张先", "body": "垂螺近额，走上红裀初趁拍。只恐轻飞，拟倩游丝惹住伊。\n文鸳绣履，去似杨花尘不起。舞彻《伊州》，头上宫花颤未休。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1109, "title": "天仙子", "author": "张先", "body": "《水调》数声持酒听，午醉醒来愁未醒。送春春去几时回？临晚镜，伤流景，往事后期空记省。 沙上并禽池上暝，云破月来花弄影。重重帘幕密遮灯，风不定，人初静，明日落红应满径。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1110, "title": "千秋岁", "author": "张先", "body": "数声鶗鴂，又报芳菲歇。惜春更把残红折。雨轻风色暴，梅子青时节。永丰柳，无人尽日花飞雪。 莫把幺弦拨，怨极弦能说。天不老，情难绝。心似双丝网，中有千千结。夜过也，东窗未白凝残月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1111, "title": "渔家傲", "author": "张先", "body": "和程公辟赠别\n巴子城头青草暮，巴山重叠相逢处。燕子占巢花脱树，杯且举，瞿塘水阔舟难渡。 天外吴门清霅路。君家正在吴门住。赠我柳枝情几许。春满缕，为君将入江南去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1112, "title": "木兰花", "author": "张先", "body": "乙卯吴兴寒食\n龙头舴艋吴儿竞，笋柱秋千游女并。芳洲拾翠暮忘归，秀野踏青来不定。 行云去后遥山暝，已放笙歌池院静。中庭月色正清明，无数杨花过无影。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1113, "title": "剪牡丹", "author": "张先", "body": "舟中闻双琵琶\n野绿连空，天青垂水，素色溶漾都净。柳径无人，堕絮飞无影。汀洲日落人归，修巾薄袂，撷香拾翠相竞。如解凌波，泊烟渚春暝。 彩绦朱索新整。宿绣屏、画船风定。金凤响双槽，弹出今古幽思谁省。玉盘大小乱珠迸。酒上妆面，花艳眉相并。重听。尽汉妃一曲，江空月静。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1114, "title": "画堂春", "author": "张先", "body": "外湖莲子长参差，霁山青处鸥飞。水天溶漾画桡迟，人影鉴中移。 桃叶浅声双唱，杏红深色轻衣。小荷障面避斜晖，分得翠阴归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1115, "title": "浣溪沙", "author": "张先", "body": "楼倚春江百尺高，烟中还未见归桡，几时期信似江潮？\n花片片飞风弄蝶，柳阴阴下水平桥，日长才过又今宵。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1116, "title": "惜琼花", "author": "张先", "body": "汀蘋白，苕水碧。每逢花驻乐，随处欢席。别时携手看春色。萤火而今，飞破秋夕。 汴河流，如带窄。任身轻似叶，何计归得？断云孤鹜青山极。楼上徘徊，无尽相忆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1117, "title": "青门引", "author": "张先", "body": "乍暖还轻冷，风雨晚来方定。庭轩寂寞近清明，残花中酒，又是去年病。 楼头画角风吹醒，入夜重门静。那堪更被明月，隔墙送过秋千影。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1118, "title": "满江红", "author": "张先", "body": "飘尽寒梅，笑粉蝶游蜂未觉。渐迤逦、水明山秀，暖生帘幕。过雨小桃红未透，舞烟新柳青犹弱。记画桥深处水边亭，曾偷约。 多少恨，今犹昨；愁和闷，都忘却。拚从前烂醉，被花迷著。晴鸽试铃风力软，雏莺弄舌春寒薄。但只愁、锦绣闹妆时，东风恶。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1119, "title": "浣溪沙", "author": "晏殊", "body": "一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？\n无可奈何花落去，似曾相识燕归来。小园香径独徘徊。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1120, "title": "浣溪沙", "author": "晏殊", "body": "小阁重帘有燕过，晚花红片落庭莎。曲栏干影入凉波。\n一霎好风生翠幕，几回疏雨滴圆荷。酒醒人散得愁多。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1121, "title": "浣溪沙", "author": "晏殊", "body": "一向年光有限身，等闲离别易销魂。酒筵歌席莫辞频。\n满目山河空念远，落花风雨更伤春。不如怜取眼前人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1122, "title": "浣溪沙", "author": "晏殊", "body": "玉碗冰寒滴露华，粉融香雪透轻纱。晚来妆面胜荷花。\n鬓亸欲迎眉际月，酒红初上脸边霞。一场春梦日西斜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1123, "title": "蝶恋花", "author": "晏殊", "body": "槛菊愁烟兰泣露，罗幕轻寒，燕子双飞去。明月不谙离恨苦，斜光到晓穿朱户。 昨夜西风凋碧树，独上高楼，望尽天涯路。欲寄彩笺兼尺素，山长水阔知何处！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1124, "title": "清平乐", "author": "晏殊", "body": "金风细细，叶叶梧桐坠。绿酒初尝人易醉。一枕小窗浓睡。\n紫薇朱槿花残。斜阳却照阑干。双燕欲归时节，银屏昨夜微寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1125, "title": "清平乐", "author": "晏殊", "body": "红笺小字，说尽平生意。鸿雁在云鱼在水，惆怅此情难寄。\n斜阳独倚西楼，遥山恰对帘钩。人面不知何处，绿波依旧东流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1126, "title": "采桑子", "author": "晏殊", "body": "时光只解催人老，不信多情，长恨离亭，泪滴春衫酒易醒。\n梧桐昨夜西风急，淡月胧明，好梦频惊，何处高楼雁一声？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1127, "title": "喜迁莺", "author": "晏殊", "body": "花不尽，柳无穷，应与我情同。觥船一棹百分空，何处不相逢。朱弦悄，知音少，天若有情应老。劝君看取利名场，今古梦茫茫。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1128, "title": "撼庭秋", "author": "晏殊", "body": "别来音信千里，恨此情难寄。碧纱秋月，梧桐夜雨，几回无寐！ 楼高目断，天遥云黯，只堪憔悴。念兰堂红烛，心长焰短，向人垂泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1129, "title": "少年游", "author": "晏殊", "body": "重阳过后，西风渐紧，庭树叶纷纷。朱阑向晓，芙蓉妖艳，特地斗芳新。 霜前月下，斜红淡蕊，明媚欲回春。莫将琼萼等闲分，留赠意中人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1130, "title": "木兰花", "author": "晏殊", "body": "燕鸿过后莺归去，细算浮生千万绪。长于春梦几多时？散似秋云无觅处。 闻琴解佩神仙侣，挽断罗衣留不住。劝君莫作独醒人，烂醉花间应有数。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1131, "title": "木兰花", "author": "晏殊", "body": "池塘水绿风微暖，记得玉真初见面。重头歌韵响琤琮，入破舞腰红乱旋。 玉钩阑下香阶畔，醉后不知斜日晚。当时共我赏花人，点检如今无一半。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1132, "title": "木兰花", "author": "晏殊", "body": "玉楼朱阁横金锁，寒食清明春欲破。窗间斜月两眉愁，帘外落花双泪堕。 朝云聚散真无那，百岁相看能几个？别来将为不牵情，万转千回思想过。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1133, "title": "诉衷情", "author": "晏殊", "body": "青梅煮酒斗时新，天气欲残春。东城南陌花下，逢着意中人。\n回绣袂，展香茵，叙情亲。此时拚作，千尺游丝，惹住朝云。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1134, "title": "诉衷情", "author": "晏殊", "body": "东风杨柳欲青青，烟淡雨初晴。恼他香阁浓睡，撩乱有啼莺。 眉叶细，舞腰轻，宿妆成。一春芳意，三月和风，牵系人情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1135, "title": "诉衷情", "author": "晏殊", "body": "芙蓉金菊斗馨香，天气欲重阳。远村秋色如画，红树间疏黄。 流水淡，碧天长，路茫茫。凭高目断，鸿雁来时，无限思量。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1136, "title": "踏莎行", "author": "晏殊", "body": "细草愁烟，幽花怯露，凭栏总是销魂处。日高深院静无人，时时海燕双飞去。 带缓罗衣，香残蕙炷，天长不禁迢迢路。垂杨只解惹春风，何曾系得行人住！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1137, "title": "踏莎行", "author": "晏殊", "body": "祖席离歌，长亭别宴。香尘已隔犹回面。居人匹马映林嘶，行人去棹依波转。 画阁魂消，高楼目断。斜阳只送平波远。无穷无尽是离愁，天涯地角寻思遍。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1138, "title": "踏莎行", "author": "晏殊", "body": "碧海无波，瑶台有路。思量便合双飞去。当时轻别意中人，山长水远知何处？ 绮席凝尘，香闺掩雾。红笺小字凭谁附？高楼目尽欲黄昏，梧桐叶上萧萧雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1139, "title": "踏莎行", "author": "晏殊", "body": "小径红稀，芳郊绿遍。高台树色阴阴见。春风不解禁杨花，濛濛乱扑行人面。 翠叶藏莺，珠帘隔燕。炉香静逐游丝转。一场愁梦酒醒时，斜阳却照深深院。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1140, "title": "山亭柳 赠歌者", "author": "晏殊", "body": "家住西秦，赌博艺随身。花柳上，斗尖新。偶学念奴声调，有时高遏行云。蜀锦缠头无数，不负辛勤。 数年来往咸京道，残杯冷炙漫销魂。衷肠事，托何人？若有知音见采，不辞遍唱阳春。一曲当筵落泪，重掩罗巾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1141, "title": "破阵子", "author": "晏殊", "body": "燕子来时新社，梨花落后清明。池上碧苔三四点，叶底黄鹂一两声，日长飞絮轻。 巧笑东邻女伴，采桑径里逢迎。疑怪昨宵春梦好，原是今朝斗草赢，笑从双脸生。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1142, "title": "玉楼春", "author": "晏殊", "body": "绿杨芳草长亭路，年少抛人容易去。楼头残梦五更钟，花底离愁三月雨。 无情不似多情苦，一寸还成千万缕。天涯地角有穷时，只有相思无尽处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1143, "title": "离亭燕", "author": "张昪", "body": "一带江山如画，风物向秋潇洒。水浸碧天何处断？霁色冷光相射。蓼屿荻花洲，掩映竹篱茅舍。 云际客帆高挂，烟外酒旗低亚。多少六朝兴废事，尽入渔樵闲话。怅望倚层楼，寒日无言西下。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1144, "title": "燕归梁 春愁", "author": "石延年", "body": "芳草年年惹恨幽。想前事悠悠。伤春伤别几时休。算从古、为风流。 春山总把，深匀翠黛，千叠在眉头。不知供得几多愁。更斜日、凭危楼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1145, "title": "蝶恋花 春暮", "author": "李冠", "body": "遥夜亭皋闲信步，才过清明，渐觉伤春暮。数点雨声风约住，朦胧淡月云来去。 桃杏依稀香暗度。谁在秋千，笑里轻轻语？一寸相思千万绪，人间没个安排处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1146, "title": "六州歌头 项羽庙", "author": "李冠", "body": "秦亡草昧①，刘、项起吞并。鞭寰宇，驱龙虎，扫欃枪②，斩长鲸。血染中原战。视余、耳③，皆鹰犬，平祸乱，归炎汉，势奔倾。兵散月明。风急旌旗乱，刁斗三更④。共虞姬相对，泣听楚歌声，玉帐魂惊。泪盈盈。 念花无主，凝愁苦，挥雪刃，掩泉扃⑤。时不利，骓不逝，困阴陵⑥，叱追兵。呜咽摧天地，望归路，忍偷生！功盖世，何处见遗灵？江静水寒烟冷，波纹细、古木凋零。遣行人到此，追念益伤情，胜负难凭！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1147, "title": "木兰花", "author": "宋祁", "body": "东城渐觉风光好，縠皱波纹迎客棹。绿杨烟外晓寒轻，红杏枝头春意闹。 浮生长恨欢娱少，肯爱千金轻一笑。为君持酒劝斜阳，且向花间留晚照。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1148, "title": "蝶恋花 情景", "author": "宋祁", "body": "绣幕茫茫罗帐卷。春睡腾腾，困入娇波慢。隐隐枕痕留玉脸，腻云斜溜钗头燕。 远梦无端欢又散。泪落胭脂，界破蜂黄浅。整了翠鬟匀了面，芳心一寸情何限。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1149, "title": "锦缠道", "author": "宋祁", "body": "燕子呢喃，景色乍长春昼。睹园林、万花如绣。海棠经雨胭脂透。柳展宫眉，翠拂行人首。 向郊原踏青，恣歌携手。醉醺醺、尚寻芳酒。问牧童、遥指孤村道：“杏花深处，那里人家有。”", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1150, "title": "苏幕遮 草", "author": "梅尧臣", "body": "露堤平，烟墅杳。乱碧萋萋，雨后江天晓。独有庾郎年最少。窣地春袍，嫩色宜相照。 接长亭，迷远道。堪怨王孙，不记归期早。落尽梨花春又了。满地残阳，翠色和烟老。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1151, "title": "贺圣朝 留别", "author": "叶清臣", "body": "满斟绿醑留君住，莫匆匆归去。三分春色二分愁，更一分风雨。 花开花谢，都来几许？且高歌休诉。不知来岁牡丹时，再相逢何处？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1152, "title": "采桑子", "author": "欧阳修", "body": "轻舟短棹西湖好，绿水逶迤，芳草长堤，隐隐笙歌处处随。\n无风水面琉璃滑，不觉船移，微动涟漪，惊起沙禽掠岸飞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1153, "title": "采桑子", "author": "欧阳修", "body": "画船载酒西湖好，急管繁弦，玉盏催传，稳泛平波任醉眠。\n行云却在行舟下，空水澄鲜，俯仰留连，疑是湖中别有天。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1154, "title": "采桑子", "author": "欧阳修", "body": "群芳过后西湖好，狼籍残红，飞絮濛濛，垂柳阑干尽日风。\n笙歌散尽游人去，始觉春空，垂下帘栊，双燕归来细雨中。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1155, "title": "采桑子", "author": "欧阳修", "body": "天容水色西湖好，云物俱鲜。鸥鹭闲眠，应惯寻常听管弦。\n风清月白偏宜夜，一片琼田。谁羡骖鸾，人在舟中便是仙。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1156, "title": "采桑子", "author": "欧阳修", "body": "残霞夕照西湖好，花坞苹汀。十顷波平，野岸无人舟自横。\n西南月上浮云散，轩槛凉生。莲芰香清，水面风来酒面醒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1157, "title": "采桑子", "author": "欧阳修", "body": "平生为爱西湖好，来拥朱轮。富贵浮云，俯仰流年二十春。\n归来恰似辽东鹤，城郭人民，触目皆新，谁识当年旧主人？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1158, "title": "采桑子", "author": "欧阳修", "body": "十年前是尊前客，月白风清。忧患凋零，老去光阴速可惊。\n鬓华虽改心无改，试把金觥。旧曲重听，犹似当年醉里声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1159, "title": "朝中措", "author": "欧阳修", "body": "送刘仲原甫出守维扬\n平山阑槛倚晴空，山色有无中。手种堂前垂柳，别来几度春风。 文章太守，挥毫万字，一饮千钟。行乐直须年少，尊前看取衰翁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1160, "title": "诉衷情", "author": "欧阳修", "body": "清晨帘幕卷轻霜，呵手试梅妆①。都缘自有离恨，故画作远山长。 思往事，惜流芳，易成伤。拟歌先敛，欲笑还颦，最断人肠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1161, "title": "踏莎行", "author": "欧阳修", "body": "候馆梅残，溪桥柳细，草薰风暖摇征辔。离愁渐远渐无穷，迢迢不断如春水。 寸寸柔肠，盈盈粉泪，楼高莫近危阑倚。平芜尽处是春山，行人更在春山外。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1162, "title": "望江南", "author": "欧阳修", "body": "江南蝶，斜日一双双。身似何郎全傅粉，心如韩寿爱偷香，天赋与轻狂。 微雨后，薄翅腻烟光。才伴游蜂来小院，又随飞絮过东墙，长是为花忙。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1163, "title": "生查子", "author": "欧阳修", "body": "去年元夜时，花市灯如昼。月上柳梢头，人约黄昏后。\n今年元夜时，月与灯依旧。不见去年人，泪满春衫袖。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1164, "title": "生查子", "author": "欧阳修", "body": "含羞整翠鬟，得意频相顾。雁柱十三弦，一一春莺语。\n娇云容易飞，梦断知何处？深院锁黄昏，阵阵芭蕉雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1165, "title": "蝶恋花", "author": "欧阳修", "body": "越女采莲秋水畔。窄袖轻罗，暗露双金钏。照影摘花花似面。芳心只共丝争乱。 㶉鶒滩头风浪晚。露重烟轻，不见来时伴。隐隐歌声归棹远。离愁引著江南岸。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1166, "title": "渔家傲", "author": "欧阳修", "body": "花底忽闻敲两桨，逡巡女伴来寻访。酒盏旋将荷叶当①。莲舟荡，时时盏里生红浪。 花气酒香清厮②酿，花腮酒面红相向。醉倚绿阴眠一饷，惊起望，船头搁在沙滩上。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1167, "title": "玉楼春", "author": "欧阳修", "body": "尊前拟把归期说，欲语春容先惨咽。人生自是有情痴，此恨不关风与月。 离歌且莫翻新阕，一曲能教肠寸结。直须看尽洛城花，始共春风容易别。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1168, "title": "玉楼春", "author": "欧阳修", "body": "洛阳正值芳菲节，秾艳清香相间发。游丝有意苦相萦，垂柳无端争赠别。 杏花红处青山缺，山畔行人山下歇。今宵谁肯远相随，唯有寂寥孤馆月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1169, "title": "玉楼春", "author": "欧阳修", "body": "西湖南北烟波阔，风里丝簧声韵咽。舞余裙带绿双垂，酒入香腮红一抹。 杯深不觉琉璃滑，贪看六幺花十八。明朝车马各西东，惆怅画桥风与月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1170, "title": "玉楼春", "author": "欧阳修", "body": "别后不知君远近，触目凄凉多少闷。渐行渐远渐无书，水阔鱼沉何处问。 夜深风竹敲秋韵，万叶千声皆是恨。故欹单枕梦中寻，梦又不成灯又烬。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1171, "title": "南歌子", "author": "欧阳修", "body": "凤髻金泥带，龙纹玉掌梳。走来窗下笑相扶，爱道画眉深浅入时无？ 弄笔偎人久，描花试手初。等闲妨了绣功夫，笑问“鸳鸯两字怎生书？”", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1172, "title": "临江仙", "author": "欧阳修", "body": "柳外轻雷池上雨，雨声滴碎荷声。小楼西角断虹明。阑干倚处，待得月华生。 燕子飞来窥画栋，玉钩垂下帘旌。凉波不动簟纹平。水精双枕，傍有堕钗横。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1173, "title": "浪淘沙", "author": "欧阳修", "body": "把酒祝东风，且共从容，垂杨紫陌洛城东。总是当时携手处，游遍芳丛。 聚散苦匆匆，此恨无穷。今年花胜去年红。可惜明年花更好，知与谁同？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1174, "title": "浪淘沙", "author": "欧阳修", "body": "五岭麦秋残，荔子初丹。绛纱囊里水晶丸。可惜天教生处远，不近长安。 往事忆开元，妃子偏怜。一从魂散马嵬关，只有红尘无驿使，满眼骊山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1175, "title": "浣溪沙", "author": "欧阳修", "body": "堤上游人逐画船，拍堤春水四垂天。绿杨楼外出秋千。\n白发戴花君莫笑，六幺催拍盏频传。人生何处似尊前！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1176, "title": "浣溪沙", "author": "欧阳修", "body": "湖上朱桥响画轮，溶溶春水浸春云，碧琉璃滑净无尘。\n当路游丝萦醉客，隔花啼鸟唤行人，日斜归去奈何春。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1177, "title": "渔家傲", "author": "欧阳修", "body": "近日门前溪水涨，郎船几度偷相访。船小难开红斗帐，无计向，合欢影里空惆怅。 愿妾身为红菡萏，年年生在秋江上；重愿郎为花底浪，无隔障，随风逐雨长来往。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1178, "title": "少年游", "author": "欧阳修", "body": "栏干十二独凭春，晴碧远连云。千里万里，二月三月，行色苦愁人。 谢家池上，江淹浦畔，吟魄与离魂。那堪疏雨滴黄昏，更特地、忆王孙。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1179, "title": "阮郎归", "author": "欧阳修", "body": "南园春半踏青时，风和闻马嘶。青梅如豆柳如眉，日长蝴蝶飞。 花露重，草烟低；人家帘幕垂。秋千慵困解罗衣，画堂双燕“栖”。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1180, "title": "蝶恋花", "author": "欧阳修", "body": "庭院深深深几许？杨柳堆烟，帘幕无重数。玉勒雕鞍游冶处，楼高不见章台路。 雨横风狂三月暮。门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1181, "title": "望江南", "author": "王琪", "body": "江南月，清夜满西楼。云落开时冰吐鉴，浪花深处玉沉钩。圆缺几时休。 星汉迥，风露入新秋。丹桂不知摇落恨，素娥应信别离愁。天上共悠悠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1182, "title": "永遇乐 春情", "author": "解昉", "body": "风暖莺娇，露浓花重，天气和煦。院落烟收，垂杨舞困，无奈堆金缕。谁家巧纵，青楼弦管，惹起梦云情绪。忆当时、纹衾粲枕，未尝暂孤鸳侣。 芳菲易老，故人难聚，到此翻成轻误。阆苑仙遥，蛮笺纵写，何计传深诉。青山绿水，古今长在，惟有旧欢何处。空赢得、斜阳暮草，淡烟细雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1183, "title": "点绛唇", "author": "韩琦", "body": "病起恹恹，画堂花谢添憔悴。乱红飘砌，滴尽胭脂泪。\n惆怅前春，谁向花前醉？愁无际。武陵回睇，人远波空翠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1184, "title": "鹤冲天", "author": "杜安世", "body": "清明天气，永日愁如醉。台榭绿阴浓，薰风细。燕子巢方就，盆池小，新荷蔽。恰是逍遥际。单夹衣裳，半笼软玉肌体。 石榴美艳，一撮红绡比。窗外数修篁，寒相倚。有个关心处，难相见，空凝睇。行坐深闺里，懒更妆梳，自知新来憔悴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1185, "title": "菩萨蛮", "author": "杜安世", "body": "游丝欲堕还重上，春残日永人相望。花共燕争飞，青梅细雨枝。 离愁终未解，忘了依前在。拟待不寻思，刚眠梦见伊。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1186, "title": "卜算子", "author": "杜安世", "body": "尊前一曲歌，歌里千重意。才欲歌时泪已流，恨应更、多于泪。 试问缘何事？不语如痴醉。我亦情多不忍闻，怕和我、成憔悴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1187, "title": "菩萨蛮", "author": "李师中", "body": "子规啼破城楼月，画船晓载笙歌发。两岸荔枝红，万家烟雨中。 佳人相对泣，泪下罗衣湿。从此信音稀，岭南无雁飞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1188, "title": "喜迁莺", "author": "蔡挺", "body": "霜天秋晓，正紫塞故垒，黄云衰草。汉马嘶风，边鸿叫月，陇上铁衣寒早。剑歌骑曲悲壮，尽道君恩须报。塞垣乐，尽櫜鞬锦领，山西年少。 谈笑。刁斗静，烽火一把，时送平安耗。圣主忧边，威怀遐远，骄虏尚宽天讨。岁华向晚愁思，谁念玉关人老？太平也，且欢娱，莫惜金樽频倒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1189, "title": "阮郎归", "author": "司马光", "body": "渔舟容易入春山，仙家日月闲。绮窗纱幌映朱颜，相逢醉梦间。 松露冷，海霞殷。匆匆整棹还。落花寂寂水潺潺，重寻此路难。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1190, "title": "西江月", "author": "司马光", "body": "宝髻松松挽就，铅华淡淡妆成。青烟翠雾罩轻盈，飞絮游丝无定。 相见争如不见，有情何似无情。笙歌散后酒初醒，深院月斜人静。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1191, "title": "凤箫吟", "author": "韩缜", "body": "锁离愁、连绵无际，来时陌上初熏。绣帏人念远，暗垂珠露，泣送征轮。长行长在眼，更重重、远水孤云。但望极楼高，尽日目断王孙。 销魂。池塘别后，曾行处、绿妒轻裙。恁时携素手，乱花飞絮里，缓步香茵。朱颜空自改，向年年、芳意长新。遍绿野，嬉游醉眼，莫负青春。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1192, "title": "花心动 春词", "author": "阮逸女", "body": "仙苑春浓，小桃开，枝枝已堪攀折。乍雨乍晴，轻暖轻寒，渐近赏花时节。柳摇台榭东风软，帘栊静，幽禽调舌。断魂远，闲寻翠径，顿成愁结。 此恨无人共说。还立尽黄昏，寸心空切。强整绣衾，独掩朱扉，枕簟为谁铺设。夜长更漏传声远，纱窗映、银缸明灭。梦回处，梅梢半笼残月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1193, "title": "桂枝香", "author": "王安石", "body": "登临送目，正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。征帆去棹残阳里，背西风酒旗斜矗。彩舟云淡，星河鹭起，画图难足。 念往昔，繁华竞逐，叹门外楼头，悲恨相续。千古凭高对此，谩嗟荣辱。六朝旧事随流水，但寒烟衰草凝绿。至今商女，时时犹唱，《后庭》遗曲。\n桂枝香（登临送目） 王安石\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1194, "title": "菩萨蛮", "author": "王安石", "body": "数间茅屋闲临水，窄衫短帽垂杨里。花是去年红，吹开一夜风①。 梢梢新月偃，午醉醒来晚。何物最关情，黄鹂三两声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1195, "title": "渔家傲", "author": "王安石", "body": "灯火已收正月半，山南山北花撩乱。闻说洊亭新水漫，骑款段，穿云入坞寻游伴。 却拂僧床褰素幔，千岩万壑春风暖。一弄松声悲急管，吹梦断，西看窗日犹嫌短。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1196, "title": "渔家傲", "author": "王安石", "body": "平岸小桥千嶂抱，柔蓝一水萦花草。茅屋数间窗窈窕。尘不到，时时自有春风扫。 午枕觉来闻语鸟，欹眠似听朝鸡早。忽忆故人今总老。贪梦好，茫然忘了邯郸道。\n渔家傲（平岸小桥千嶂抱） 王安石\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1197, "title": "浪淘沙令", "author": "王安石", "body": "伊吕两衰翁，历遍穷通。一为钓叟一耕佣。若使当时身不遇，老了英雄。 汤武偶相逢，风虎云龙。兴王只在笑谈中。直至如今千载后，谁与争功！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1198, "title": "千秋岁引", "author": "王安石", "body": "别馆寒砧，孤城画角，一派秋声入寥廓。东归燕从海上去，南来雁向沙头落。楚台风，庾楼月，宛如昨。 无奈被些名利缚，无奈被他情担阁。可惜风流总闲却。当初谩留华表语，而今误我秦楼约。梦阑时，酒醒后，思量着。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1199, "title": "水龙吟", "author": "章楶", "body": "燕忙莺懒芳残，正堤上、柳花飘坠。轻飞乱舞，点画青林，全无才思。闲趁游丝，静临深院，日长门闭。傍珠帘散漫，垂垂欲下，依前被、风扶起。 兰帐玉人睡觉，怪春衣、雪霑琼缀。绣床旋满，香球无数，才圆却碎。时见蜂儿，仰粘轻粉，鱼吞池水。望章台路杳，金鞍游荡，有盈盈泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1200, "title": "清平乐 春晚", "author": "王安国", "body": "留春不住，费尽莺儿语。满地残红宫锦污，昨夜南园风雨。\n小怜初上琵琶，晓来思绕天涯。不肯画堂朱户，春风自在杨花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1201, "title": "减字木兰花", "author": "王安国", "body": "画桥流水，雨湿落红飞不起。月破黄昏，帘里余香马上闻。\n徘徊不语，今夜梦魂何处去。不似垂杨，犹解飞花入洞房。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1202, "title": "菩萨蛮", "author": "孙洙", "body": "楼头尚有三通鼓，何须抵死催人去！上马苦匆匆，琵琶曲未终。 回头凝望处，那更廉纤雨。漫道玉为堂，玉堂今夜长。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1203, "title": "临江仙", "author": "晏几道", "body": "斗草阶前初见，穿针楼上曾逢。罗裙香露玉钗风。靓妆眉沁绿，羞脸粉生红。 流水便随春远，行云终与谁同？酒醒长恨锦屏空。相寻梦里路，飞雨落花中。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1204, "title": "临江仙", "author": "晏几道", "body": "梦后楼台高锁，酒醒帘幕低垂。去年春恨却来时。落花人独立，微雨燕双飞。 记得小蘋初见，两重心字罗衣。琵琶弦上说相思。当时明月在，曾照彩云归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1205, "title": "蝶恋花", "author": "晏几道", "body": "初撚霜纨生怅望。隔叶莺声，似学秦娥唱。午睡醒来慵一饷，双纹翠簟铺寒浪。 雨罢蘋风吹碧涨。脉脉荷花，泪脸红相向。斜贴绿云新月上，弯环正是愁眉样。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1206, "title": "蝶恋花", "author": "晏几道", "body": "醉别西楼醒不记，春梦秋云，聚散真容易。斜月半窗还少睡，画屏闲展吴山翠。 衣上酒痕诗里字，点点行行，总是凄凉意。红烛自怜无好计，夜寒空替人垂泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1207, "title": "蝶恋花", "author": "晏几道", "body": "梦入江南烟水路，行尽江南，不与离人遇。睡里消魂无说处，觉来惆怅消魂误。 欲尽此情书尺素，浮雁沉鱼，终了无凭据。却倚缓弦歌别绪，断肠移破①秦筝柱。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1208, "title": "鹧鸪天", "author": "晏几道", "body": "彩袖殷勤捧玉钟，当年拚却醉颜红。舞低杨柳楼心月，歌尽桃花扇影风。 从别后，忆相逢，几回魂梦与君同？今宵剩把银釭照，犹恐相逢是梦中。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1209, "title": "鹧鸪天", "author": "晏几道", "body": "一醉醒来春又残，野棠梨雨泪阑干。玉笙声里鸾空怨，罗幕香中燕未还。 终易散，且长闲。莫教离恨损朱颜。谁堪共展鸳鸯锦，同过西楼此夜寒！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1210, "title": "鹧鸪天", "author": "晏几道", "body": "守得莲开结伴游，约开萍叶上兰舟。来时浦口云随棹，采罢江边月满楼。 花不语，水空流，年年拚得为花愁。明朝万一西风动，争奈朱颜不耐秋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1211, "title": "鹧鸪天", "author": "晏几道", "body": "斗鸭池南夜不归，酒阑纨扇有新诗。云随碧玉歌声转，雪绕红琼舞袖回。 今感旧，欲沾衣。可怜人似水东西。回头满眼凄凉事，秋月春风岂得知！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1212, "title": "鹧鸪天", "author": "晏几道", "body": "醉拍春衫惜旧香。天将离恨恼疏狂。年年陌上生秋草，日日楼中到夕阳。 云渺渺，水茫茫。征人归路许多长。相思本是无凭语，莫向花笺费泪行！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1213, "title": "鹧鸪天", "author": "晏几道", "body": "小令尊前见玉箫，银灯一曲太妖娆。歌中醉倒谁能恨？唱罢归来酒未消。 春悄悄，夜迢迢。碧云天共楚宫遥。梦魂惯得无拘检，又踏杨花过谢桥。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1214, "title": "鹧鸪天", "author": "晏几道", "body": "十里楼台倚翠微，百花深处杜鹃啼。殷勤自与行人语，不似流莺取次飞。 惊梦觉，弄晴时。声声只道不如归。天涯岂是无归意，争奈归期未可期。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1215, "title": "生查子", "author": "晏几道", "body": "金鞭美少年，去跃青骢马。牵系玉楼人，绣被春寒夜。\n消息未归来，寒食梨花谢。无处说相思，背面秋千下。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1216, "title": "生查子", "author": "晏几道", "body": "长恨涉江遥，移近溪头住。闲荡木兰舟，误入双鸳浦。\n无端轻薄云，暗作帘纤雨。翠袖不胜寒，欲向荷花语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1217, "title": "南乡子", "author": "晏几道", "body": "新月又如眉。长笛谁教月下吹？楼倚暮云初见雁，南飞。漫道行人雁后归。 意欲梦佳期。梦里关山路不知。却待短书来破恨，应迟。还是凉生玉枕时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1218, "title": "清平乐", "author": "晏几道", "body": "留人不住，醉解兰舟去。一棹碧涛春水路，过尽晓莺啼处。 渡头杨柳青青，枝枝叶叶离情。此后锦书休寄，画楼云雨无凭。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1219, "title": "木兰花", "author": "晏几道", "body": "秋千院落重帘暮，彩笔闲来题绣户。墙头丹杏雨余花，门外绿杨风后絮。 朝云信断知何处？应作襄王春梦去。紫骝认得旧游踪，嘶过画桥东畔路。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1220, "title": "木兰花", "author": "晏几道", "body": "小莲未解论心素，狂似钿筝弦底柱。脸边霞散酒初醒，眉上月残人欲去。 旧时家近章台住，尽日东风吹柳絮。生憎繁杏绿阴时，正碍粉墙偷眼觑。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1221, "title": "菩萨蛮", "author": "晏几道", "body": "哀筝一弄湘江曲，声声写尽湘波绿。纤指十三弦，细将幽恨传。当筵秋水慢，玉柱斜飞雁。弹到断肠时，春山眉黛低。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1222, "title": "玉楼春", "author": "晏几道", "body": "东风又作无情计，艳粉娇红吹满地。碧楼帘影不遮愁，还似去年今日意。 谁知错管春残事，到处登临曾费泪。此时金盏①直须深，看尽落花能几醉！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1223, "title": "阮郎归", "author": "晏几道", "body": "旧香残粉似当初，人情恨不如。一春犹有数行书，秋来书更疏。 衾凤冷，枕鸳孤。愁肠待酒舒。梦魂纵有也成虚，那堪和梦无？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1224, "title": "阮郎归", "author": "晏几道", "body": "天边金掌露成霜，云随雁字长。绿杯红袖趁重阳，人情似故乡。 兰佩紫，菊簪黄，殷勤理旧狂。欲将沉醉换悲凉，清歌莫断肠！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1225, "title": "归田乐", "author": "晏几道", "body": "试把花期数。便早有、感春情绪。看即梅花吐。愿花更不谢，春且长住。只恐花飞又春去。 花开还不语。问此意、年年春还会否？绛唇青鬓，渐少花前侣。对花又记得，旧曾游处。门外垂杨未飘絮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1226, "title": "浣溪沙", "author": "晏几道", "body": "二月和风到碧城，万条千缕绿相迎，舞烟眠雨过清明。\n妆镜巧眉偷叶样，歌楼妍曲借枝名。晚秋霜霰莫无情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1227, "title": "浣溪沙", "author": "晏几道", "body": "日日双眉斗画长，行云飞絮共轻狂。不将心嫁冶游郎。\n溅酒滴残歌扇字，弄花熏得舞衣香。一春弹泪说凄凉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1228, "title": "浣溪沙", "author": "晏几道", "body": "唱得红梅字字香，柳枝桃叶尽深藏。遏云声里送离觞。\n才听便拚衣袖湿，欲歌先倚黛眉长。曲终敲损燕钗梁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1229, "title": "六么令", "author": "晏几道", "body": "绿阴春尽，飞絮绕香阁。晚来翠眉宫样，巧把远山学。一寸狂心未说，已向横波觉。画帘遮帀。新翻曲妙，暗许闲人带偷掐。 前度书多隐语，意浅愁难答；昨夜诗有回文，韵险还慵押。都待笙歌散了，记取留时霎。不消红蜡。闲云归后，月在庭花旧栏角。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1230, "title": "更漏子", "author": "晏几道", "body": "柳丝长，桃叶小。深院断无人到。红日淡，绿烟晴。流莺三两声。 雪香浓，檀晕少。枕上卧枝花好。春思重，晓妆迟。寻思残梦时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1231, "title": "河满子", "author": "晏几道", "body": "绿绮琴中心事，齐纨扇上时光。五陵年少浑薄倖，轻如曲水飘香。夜夜魂消梦峡，年年泪尽啼湘。 归雁行边远字，惊鸾舞处离肠。蕙楼多少铅华在，从来错倚红妆。可羡邻姬十五，金钗早嫁王昌。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1232, "title": "御街行", "author": "晏几道", "body": "街南绿树春饶絮，雪满游春路。树头花艳杂娇云，树底人家朱户。北楼闲上，疏帘高卷，直见街南树。 阑干倚尽犹慵去，几度黄昏雨。晚春盘马踏青苔，曾傍绿阴深驻。落花犹在，香屏空掩，人面知何处？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1233, "title": "少年游", "author": "晏几道", "body": "离多最是，东西流水，终解两相逢。浅情终似，行云无定，犹到梦魂中。 可怜人意，薄于云水，佳会更难重。细想从来，断肠多处，不与者番同。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1234, "title": "虞美人", "author": "晏几道", "body": "曲阑干外天如水，昨夜还曾倚。初将明月比佳期，长向月圆时候望人归。 罗衣著破前香在，旧意谁教改？一春离恨懒调弦，犹有两行闲泪宝筝前。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1235, "title": "采桑子", "author": "晏几道", "body": "西楼月下当时见，泪粉偷匀。歌罢还颦。恨隔炉烟看未真。 别来楼外垂杨缕，几换青春。倦客红尘，长记楼中粉泪人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1236, "title": "留春令", "author": "晏几道", "body": "画屏天畔，梦回依约，十洲云水。手撚红笺寄人书，写无限伤春事。 别浦高楼曾漫倚。对江南千里。楼下分流水声中，有当日凭高泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1237, "title": "思远人", "author": "晏几道", "body": "红叶黄花秋意晚，千里念行客。飞云过尽，归鸿无信，何处寄书得？ 泪弹不尽当窗滴。就砚旋研墨。渐写到别来，此情深处，红笺为无色。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1238, "title": "长相思", "author": "晏几道", "body": "长相思，长相思。若问相思甚了期，除非相见时。\n长相思，长相思。欲把相思说似谁，浅情人不知。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1239, "title": "卜算子", "author": "王观", "body": "送鲍浩然之浙东\n水是眼波横，山是眉峰聚。欲问行人去那边？眉眼盈盈处。\n才始送春归，又送君归去。若到江南赶上春，千万和春住。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1240, "title": "清平乐", "author": "王观", "body": "黄金殿里，烛影双龙戏。劝得官家真个醉，进酒犹呼万岁。\n折旋舞彻《伊州》。君恩与整搔头。一夜御前宣住，六宫多少人愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1241, "title": "庆清朝慢 踏青", "author": "王观", "body": "调雨为酥，催冰做水，东君①分付春还。何人便将轻暖，点破残寒？结伴踏青去好，平头鞋子小双鸾②。烟郊外，望中秀色，如有无间。 晴则个，阴则个，饾饤③得天气有许多般。须教镂花拨柳，争要先看。不道吴绫绣袜，香泥斜沁几行斑。东风巧，尽收翠绿，吹在眉山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1242, "title": "木兰花令", "author": "王观", "body": "铜驼陌上新正后，第一风流除是柳。勾牵春事不如梅，断送离人强似酒。 东君有意偏撋就，惯得腰肢真个瘦。阿谁道你不思量，因甚眉头长恁皱。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1243, "title": "卖花声 题岳阳楼", "author": "张舜民", "body": "木叶下君山。空水漫漫。十分斟酒敛芳颜。不是渭城西去客，休唱《阳关》。 醉袖抚危阑。天淡云闲。何人此路得生还？回首夕阳红尽处，应是长安。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1244, "title": "好事近", "author": "魏夫人", "body": "雨后晓寒轻，花外早莺啼歇。愁听隔溪残漏，正一声凄咽。\n不堪西望去程赊，离肠万回结。不似海棠阴下，按《凉州》时节。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1245, "title": "菩萨蛮", "author": "魏夫人", "body": "溪山掩映斜阳里。楼台影动鸳鸯起。隔岸两三家，出墙红杏花。 绿杨堤下路，早晚溪边走。三见柳绵飞，离人犹未归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1246, "title": "点绛唇", "author": "魏夫人", "body": "波上清风，画船明月人归后。渐消残酒，独自凭栏久。\n聚散匆匆，此恨年年有。重回首，淡烟疏柳，隐隐芜城漏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1247, "title": "卷珠帘", "author": "魏夫人", "body": "记得来时春未暮，执手攀花，袖染花梢露。暗卜春心共花语，争寻双朵争先去。 多情因甚相辜负，轻拆轻离，欲向谁分诉。泪湿海棠花枝处，东君空把奴分付。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1248, "title": "忆故人", "author": "王诜", "body": "烛影摇红，向夜阑，乍酒醒、心情懒。尊前谁为唱《阳关》，离恨天涯远。 无奈云沉雨散。凭阑干、东风泪眼。海棠开后，燕子来时，黄昏庭院。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1249, "title": "蝶恋花", "author": "王诜", "body": "小雨初晴回晚照。金翠楼台，倒影芙蓉沼。杨柳垂垂风袅袅。嫩荷无数青钿小。 似此园林无限好。流落归来，到了心情少。坐到黄昏人悄悄。更应添得朱颜老。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1250, "title": "水龙吟", "author": "苏轼", "body": "次韵章质夫杨花词\n似花还似非花，也无人惜从教坠。抛家傍路，思量却是，无情有思。萦损柔肠，困酣娇眼，欲开还闭。梦随风万里，寻郎去处，又还被、莺呼起。 不恨此花飞尽，恨西园、落红难缀。晓来雨过，遗踪何在，一池萍碎。春色三分，二分尘土，一分流水。细看来，不是杨花，点点是离人泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1251, "title": "满庭芳", "author": "苏轼", "body": "元丰七年四月一日，余将去黄移汝，留别雪堂①邻里二三君子，会李仲览自江东来别，遂书以遗之。\n归去来兮，吾归何处？万里家在岷峨②。百年强半，来日苦无多。坐见黄州再闰③，儿童尽、楚语吴歌。山中友，鸡豚社酒，相劝老东坡。 云何，当此去，人生底事，来往如梭。待闲看秋风，洛水清波④。好在堂前细柳，应念我，莫剪柔柯。仍传语，江南父老，时与晒渔蓑。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1252, "title": "满庭芳", "author": "苏轼", "body": "蜗角①虚名，蝇头微利，算来着甚干忙。事皆前定，谁弱又谁强。且趁闲身未老，须放我、些子疏狂。百年里，浑教是醉，三万六千场。 思量、能几许？忧愁风雨，一半相妨。又何须抵死，说短论长。幸对清风皓月，苔茵展、云幕高张。江南好，千钟美酒，一曲《满庭芳》。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1253, "title": "满庭芳", "author": "苏轼", "body": "有王长官者，弃官黄州三十三年，黄人谓之王先生。因送陈慥来过余，因为赋此。\n三十三年，今谁存者，算只君与长江。凛然苍桧，霜干苦难双。闻道司州古县，云溪上、竹坞松窗。江南岸、不因送子，宁肯过吾邦？ 摐摐，疏雨过，风林舞破，烟盖云幢。愿持此邀君，一饮空缸。居士先生老矣，真梦里相对残釭。歌声断，行人未起，船鼓已逢逢。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1254, "title": "水调歌头", "author": "苏轼", "body": "黄州快哉亭赠张偓佺\n落日绣帘卷，亭下水连空。知君为我新作，窗户湿青红。长记平山堂上，欹枕江南烟雨，杳杳没孤鸿。认得醉翁语：“山色有无中。” 一千顷，都镜净，倒碧峰。忽然浪起，掀舞一叶白头翁。堪笑兰台公子，未解庄生天籁①，刚道有雌雄。一点浩然气，千里快哉风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1255, "title": "水调歌头", "author": "苏轼", "body": "丙辰中秋，欢饮达旦，大醉，作此篇。兼怀子由。\n明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间！ 转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1256, "title": "水调歌头", "author": "苏轼", "body": "欧阳文忠公尝问余：琴诗何者最善？答以退之听颖师琴诗最善。公曰：此诗最奇丽，然非听琴，乃听琵琶也。余深然之。建安章质夫家善琵琶者，乞为歌词。余久不作，特取退之词，稍加隐括，使就声律，以遗之云。\n昵昵儿女语，灯火夜微明。恩怨尔汝来去，弹指泪和声。忽变轩昂勇士，一鼓填然作气，千里不留行。回首暮云远，飞絮搅青冥。 众禽里，真彩凤，独不鸣。跻攀寸步千险，一落百寻轻。烦子指间风雨，置我肠中冰炭，起坐不能平。推手从归去，无泪与君倾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1257, "title": "满江红", "author": "苏轼", "body": "寄鄂州朱使君寿昌\n江汉西来，高楼下、蒲萄深碧。犹自带、岷峨雪浪，锦江春色。君是南山遗爱守，我为剑外思归客。对此间、风物岂无情，殷勤说。 《江表传》，君休读；狂处士，真堪惜。空洲对鹦鹉，苇花萧瑟。不独笑书生争底事，曹公黄祖俱飘忽。愿使君、还赋谪仙诗，追黄鹤。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1258, "title": "归朝欢 和苏坚伯固", "author": "苏轼", "body": "我梦扁舟浮震泽，雪浪摇空千顷白。觉来满眼是庐山，倚天无数开青壁。此生长接淅，与君同是江南客。梦中游、觉来清赏，同作飞梭掷。 明日西风还挂席，唱我新词泪沾臆。灵均去后楚山空，澧阳兰芷无颜色。君才如梦得，武陵更在西南极。《竹枝词》①、莫徭②新唱，谁谓古今隔。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1259, "title": "念奴娇 赤壁怀古", "author": "苏轼", "body": "大江东去，浪淘尽、千古风流人物。故垒西边，人道是、三国周郎赤壁。乱石崩云，惊涛裂岸，卷起千堆雪。江山如画，一时多少豪杰！ 遥想公瑾当年，小乔初嫁了，雄姿英发。羽扇纶巾，谈笑间、樯橹灰飞烟灭。故国神游，多情应笑我、早生华发。人间如梦，一樽还酹江月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1260, "title": "沁园春", "author": "苏轼", "body": "孤馆灯青，野店鸡号，旅枕梦残。渐月华收练，晨霜耿耿；云山摛锦，朝露漙漙。世路无穷，劳生有限，似此区区长鲜欢。微吟罢，凭征鞍无语，往事千端。 当时共客长安，似二陆初来俱少年。有笔头千字，胸中万卷；致君尧舜，此事何难。用舍由时，行藏在我，袖手何妨闲处看。身长健，但优游卒岁，且斗尊前。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1261, "title": "一丛花 初春病起", "author": "苏轼", "body": "今年春浅腊侵年，冰雪破春妍。东风有信无人见，露微意、柳际花边。寒夜纵长，孤衾易暖，钟鼓渐清圆。 朝来初日半衔山，楼阁淡疏烟。游人便作寻芳计，小桃杏、应已争先。衰病少悰，疏慵自放，惟爱日高眠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1262, "title": "木兰花令", "author": "苏轼", "body": "次欧公西湖韵①\n霜余已失长淮阔，空听潺潺清颍咽。佳人犹唱醉翁词，四十三年如电抹。 草头秋露流珠滑，三五盈盈还二八。与余同是识翁人，惟有西湖波底月！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1263, "title": "西江月", "author": "苏轼", "body": "世事一场大梦，人生几度新凉？夜来风叶已鸣廊，看取眉头鬓上。 酒贱常愁客少，月明多被云妨。中秋谁与共孤光，把盏凄然北望。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1264, "title": "西江月", "author": "苏轼", "body": "玉骨那愁瘴雾，冰肌自有仙风。海仙时遣探芳丛，倒挂绿毛么凤。 素面常嫌粉涴，洗妆不褪唇红。高情已逐晓云空，不与梨花①同梦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1265, "title": "西江月", "author": "苏轼", "body": "顷在黄州，春夜行蕲水①中，过酒家饮，酒醉，乘月至一溪桥上，解鞍，曲肱醉卧少休。及觉已晓，乱山攒拥，流水锵然，疑非尘世也。书此语桥柱上。\n照野弥弥浅浪，横空隐隐层霄。障泥未解玉骢骄，我欲醉眠芳草。 可惜一溪风月，莫教踏碎琼瑶。解鞍欹枕绿杨桥，杜宇一声春晓。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1266, "title": "西江月 平山堂①", "author": "苏轼", "body": "三过平山堂下，半生弹指②声中。十年不见老仙翁，壁上龙蛇飞动。 欲吊文章太守，仍歌杨柳春风。休言万事转头空，未转头时皆梦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1267, "title": "临江仙 送王缄", "author": "苏轼", "body": "忘却成都来十载，因君未免思量。凭将清泪洒江阳。故山知好在，孤客自悲凉。 坐上别愁君未见，归来欲断无肠。殷勤且更尽离觞。此身如传舍，何处是吾乡！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1268, "title": "临江仙 送钱穆父", "author": "苏轼", "body": "一别都门三改火①，天涯踏尽红尘。依然一笑作春温。无波真古井，有节是秋筠。 惆怅孤帆连夜发，送行淡月微云。尊前不用翠眉颦。人生如逆旅，我亦是行人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1269, "title": "临江仙", "author": "苏轼", "body": "夜饮东坡醒复醉，归来仿佛三更。家童鼻息已雷鸣。敲门都不应，倚杖听江声。 长恨此身非我有，何时忘却营营？夜阑风静縠纹平。小舟从此逝，江海寄馀生。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1270, "title": "鹧鸪天", "author": "苏轼", "body": "林断山明竹隐墙，乱蝉衰草小池塘。翻空白鸟时时见，照水红蕖细细香。 村舍外，古城旁，杖藜徐步转斜阳。殷勤昨夜三更雨，又得浮生一日凉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1271, "title": "少年游", "author": "苏轼", "body": "润州作，代人寄远\n去年相送，余杭门外，飞雪似杨花。今年春尽，杨花似雪，犹不见还家。 对酒卷帘邀明月，风露透窗纱。恰似姮娥怜双燕，分明照、画梁斜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1272, "title": "定风波", "author": "苏轼", "body": "三月七日沙湖道中遇雨。雨具先去，同行皆狼狈，余独不觉。已而遂晴，故作此。\n莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。 料峭春风吹酒醒，微冷，山头斜照却相迎。回首向来萧瑟处，归去，也无风雨也无晴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1273, "title": "定风波 红梅", "author": "苏轼", "body": "好睡慵开莫厌迟。自怜冰脸不时宜。偶作小红桃杏色，闲雅，尚馀孤瘦雪霜姿。 休把闲心随物态，何事，酒生微晕沁瑶肌。诗老不知梅格在，吟咏，更看绿叶与青枝。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1274, "title": "定风波", "author": "苏轼", "body": "常羡人间琢玉郎，天教分付点酥娘。自作清歌传皓齿，风起，雪飞炎海变清凉。 万里归来年愈少，微笑，笑时犹带岭梅香。试问岭南应不好？却道，此心安处是吾乡。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1275, "title": "南乡子", "author": "苏轼", "body": "晚景落琼杯，照眼云山翠作堆。认得岷峨春雪浪，初来，万顷蒲萄涨渌醅①。 春雨暗阳台，乱洒歌楼湿粉腮。一阵东风来卷地，吹回，落照江天一半开。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1276, "title": "南乡子", "author": "苏轼", "body": "梅花词和杨元素\n寒雀满疏篱，争抱寒柯看玉蕤。忽见客来花下坐，惊飞。踏散芳英落酒卮。 痛饮又能诗。坐客无毡醉不知。花谢酒阑春到也，离离，一点微酸已着枝。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1277, "title": "南乡子", "author": "苏轼", "body": "重九涵辉楼呈徐君猷\n霜降水痕收，浅碧鳞鳞露远洲。酒力渐消风力软，飕飕。破帽多情却恋头。 佳节若为酬，但把清樽断送秋。万事到头都是梦，休休。明日黄花蝶也愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1278, "title": "南乡子 送述古", "author": "苏轼", "body": "回首乱山横，不见居人只见城。谁似临平山上塔，亭亭，迎客西来送客行。 归路晚风清，一枕初寒梦不成。今夜残灯斜照处，荧荧，秋雨晴时泪不晴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1279, "title": "南乡子 集句", "author": "苏轼", "body": "怅望送春杯杜牧。渐老逢春能几回杜甫。花满楚城愁远别许浑，伤怀。何况清丝急管催刘禹锡。 吟断望乡台李商隐。万里归心独上来许浑。景物登临闲始见杜牧，徘徊。一寸相思一寸灰。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1280, "title": "南歌子 游赏", "author": "苏轼", "body": "山与歌眉敛，波同醉眼流。游人都上十三楼。不羡竹西歌吹古扬州。 菰黍连昌歜①，琼彝倒玉舟。谁家水调唱歌头。声绕碧山飞去晚云留。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1281, "title": "南歌子", "author": "苏轼", "body": "雨暗初疑夜，风回便报晴，淡云斜照著山明。细草软沙溪路马蹄轻。 卯酒醒还困，仙村梦不成，蓝桥何处觅云英？只有多情流水伴人行。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1282, "title": "鹊桥仙", "author": "苏轼", "body": "七夕送陈令举\n缑山仙子，高情云渺，不学痴牛騃女。凤箫声断月明中，举手谢时人欲去。 客槎曾犯，银河波浪，尚带天风海雨。相逢一醉是前缘，风雨散、飘然何处？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1283, "title": "望江南 超然台作", "author": "苏轼", "body": "春未老，风细柳斜斜。试上超然台上看，半壕春水一城花。烟雨暗千家。 寒食后，酒醒却咨嗟。休对故人思故国，且将新火试新茶。诗酒趁年华。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1284, "title": "卜算子", "author": "苏轼", "body": "黄州定慧院寓居作\n缺月挂疏桐，漏断人初静。谁见幽人独往来，缥缈孤鸿影。\n卜算子（缺月挂疏桐） 苏轼\n——明刊本《诗馀画谱》\n惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1285, "title": "昭君怨", "author": "苏轼", "body": "金山送柳子玉\n谁作桓伊三弄①，惊破绿窗幽梦？新月与愁烟，满江天。\n欲去又还不去，明日落花飞絮。飞絮送行舟，水东流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1286, "title": "贺新郎", "author": "苏轼", "body": "乳燕飞华屋，悄无人、桐阴转午，晚凉新浴。手弄生绡白团扇，扇手一时似玉。渐困倚、孤眠清熟。帘外谁来推绣户？枉教人梦断瑶台曲。又却是、风敲竹。 石榴半吐红巾蹙，待浮花浪蕊都尽，伴君幽独。秾艳一枝细看取，芳心千重似束。又恐被、西风惊绿。若待得君来向此，花前对酒不忍触。共粉泪、两簌簌。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1287, "title": "洞仙歌", "author": "苏轼", "body": "江南腊尽，早梅花开后。分付新春与垂柳。细腰肢、自有入格风流。仍更是、骨体清英雅秀。 永丰坊那畔，尽日无人，谁见金丝弄晴昼？断肠是飞絮时，绿叶成阴，无箇事、一成消瘦。又莫是东风逐君来，便吹散眉间，一点春皱。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1288, "title": "洞仙歌", "author": "苏轼", "body": "冰肌玉骨，自清凉无汗。水殿风来暗香满。绣帘开，一点明月窥人，人未寝，欹枕钗横鬓乱。 起来携素手，庭户无声，时见疏星渡河汉。试问夜如何？夜已三更，金波淡，玉绳低转。但屈指西风几时来，又不道流年暗中偷换。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1289, "title": "八声甘州 寄参寥子", "author": "苏轼", "body": "有情风万里卷潮来，无情送潮归。问钱塘江上，西兴浦口，几度斜晖？不用思量今古，俯仰昔人非。谁似东坡老，白首忘机。 记取西湖西畔，正春山好处，空翠烟霏。算诗人相得，如我与君稀。约它年、东还海道，愿谢公雅志莫相违。西州路，不应回首，为我沾衣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1290, "title": "阮郎归 初夏", "author": "苏轼", "body": "绿槐高柳咽新蝉，薰风初入弦。碧纱窗下水沉烟，棋声惊昼眠。 微雨过，小荷翻。榴花开欲燃。玉盆纤手弄清泉，琼珠碎却圆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1291, "title": "江城子", "author": "苏轼", "body": "陶渊明以正月五日游斜川，临流班坐，顾瞻南阜，爱曾城之独秀，乃作斜川诗，至今使人想见其处。元丰壬戌之春，余躬耕于东坡，筑雪堂居之，南挹四望亭之后丘，西控北山之微泉，慨然而叹，此亦斜川之游也。乃作长短句，以《江城子》歌之。\n梦中了了醉中醒。只渊明，是前生。走遍人间，依旧却躬耕。昨夜东坡春雨足，乌鹊喜，报新晴。 雪堂西畔暗泉鸣。北山倾，小溪横。南望亭丘，孤秀耸曾城。都是斜川当日景，吾老矣，寄馀龄。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1292, "title": "江城子", "author": "苏轼", "body": "孤山竹阁送述古\n翠蛾羞黛怯人看。掩霜纨，泪偷弹。且尽一尊，收泪唱《阳关》。漫道帝城天样远，天易见，见君难。 画堂新构近孤山。曲栏干，为谁安？飞絮落花，春色属明年。欲棹小舟寻旧事，无处问，水连天。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1293, "title": "江城子", "author": "苏轼", "body": "湖上与张先同赋，时闻弹筝。\n凤凰山下雨初晴，水风清，晚霞明。一朵芙蕖，开过尚盈盈。\n何处飞来双白鹭，如有意，慕娉婷。 忽闻江上弄哀筝，苦含情，遣谁听！烟敛云收，依约是湘灵。欲待曲终寻问取，人不见，数峰青。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1294, "title": "江城子 密州出猎", "author": "苏轼", "body": "老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。为报倾城随太守，亲射虎，看孙郎①。 酒酣胸胆尚开张，鬓微霜，又何妨。持节云中，何日遣冯唐？会挽雕弓如满月，西北望，射天狼②。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1295, "title": "江城子 别徐州", "author": "苏轼", "body": "天涯流落思无穷！既相逢，却匆匆。携手佳人，和泪折残红。为问东风余几许？春纵在，与谁同！ 隋堤三月水溶溶。背归鸿，去吴中。回首彭城，清泗与淮通。欲寄相思千点泪，流不到，楚江东。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1296, "title": "江城子", "author": "苏轼", "body": "乙卯正月二十日夜记梦\n十年生死两茫茫。不思量，自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。 夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行。料得年年肠断处：明月夜，短松冈。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1297, "title": "蝶恋花", "author": "苏轼", "body": "花褪残红青杏小。燕子飞时，绿水人家绕。枝上柳绵吹又少，天涯何处无芳草！ 墙里秋千墙外道。墙外行人，墙里佳人笑。笑渐不闻声渐悄，多情却被无情恼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1298, "title": "蝶恋花", "author": "苏轼", "body": "暮春别李公择\n簌簌无风花自堕。寂寞园林，柳老樱桃过。落日有情还照坐，山青一点横云破。 路尽河回人转舵。系缆渔村，月暗孤灯火。凭仗飞魂招楚些，我思君处君思我。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1299, "title": "蝶恋花 密州上元", "author": "苏轼", "body": "灯火钱塘三五夜，明月如霜，照见人如画。帐底吹笙香吐麝，更无一点尘随马。 寂寞山城人老也！击鼓吹箫，却入农桑社。火冷灯稀霜露下，昏昏雪意云垂野。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1300, "title": "采桑子", "author": "苏轼", "body": "多情多感仍多病，多景楼中。尊酒相逢，乐事回头一笑空。\n停杯且听琵琶语，细撚轻拢。醉脸春融，斜照江天一抹红。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1301, "title": "永遇乐", "author": "苏轼", "body": "孙巨源以八月十五日离海州，坐别于景疏楼上。既而与余会于润州，至楚州乃别。余以十一月①十五日至海州，与太守会于景疏楼上，作此词以寄巨源。\n长忆别时，景疏楼上，明月如水。美酒清歌，留连不住，月随人千里。别来三度，孤光又满，冷落共谁同醉？卷珠帘、凄然顾影，共伊到明无寐。 今朝有客，来从濉上，能道使君深意。凭仗清淮，分明到海，中有相思泪。而今何在？西垣清禁，夜永露华侵被。此时看、回廊晓月，也应暗记。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1302, "title": "永遇乐", "author": "苏轼", "body": "彭城夜宿燕子楼，梦盼盼，因作此词。\n明月如霜，好风如水，清景无限。曲港跳鱼，圆荷泻露，寂寞无人见。紞如三鼓，铿然一叶，黯黯梦云惊断。夜茫茫、重寻无处，觉来小园行遍。 天涯倦客，山中归路，望断故园心眼。燕子楼空，佳人何在，空锁楼中燕。古今如梦，何曾梦觉，但有旧欢新怨。异时对、黄楼夜景，为余浩叹。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1303, "title": "行香子", "author": "苏轼", "body": "清夜无尘，月色如银。酒斟时、须满十分。浮名浮利，虚苦劳神。叹隙中驹，石中火，梦中身。 虽抱文章，开口谁亲。且陶陶、乐尽天真。几时归去，作个闲人。对一张琴，一壶酒，一溪云。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1304, "title": "行香子", "author": "苏轼", "body": "携手江村，梅雪飘裙。情何限、处处消魂。故人不见，旧曲重闻。向望湖楼，孤山寺，涌金门。 寻常行处，题诗千首，绣罗衫、与拂红尘。别来相忆，知是何人。有湖中月，江边柳，陇头云。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1305, "title": "行香子 过七里濑①", "author": "苏轼", "body": "一叶舟轻，双桨鸿惊。水天清、影湛波平。鱼翻藻鉴，鹭点烟汀。过沙溪急，霜溪冷，月溪明。 重重似画，曲曲如屏。算当年、虚老严陵。君臣一梦，今古空名。但远山长，云山乱，晓山青。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1306, "title": "菩萨蛮 回文。夏闺怨", "author": "苏轼", "body": "柳庭风静人眠昼，昼眠人静风庭柳。香汗薄衫凉，凉衫薄汗香。 手红冰碗藕，藕碗冰红手。郎笑藕丝长，长丝藕笑郎。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1307, "title": "虞美人", "author": "苏轼", "body": "有美堂①赠述古\n湖山信是东南美，一望弥千里。使君能得几回来？便使樽前醉倒更徘徊。 沙河塘②里灯初上，水调③谁家唱？夜阑风静欲归时，惟有一江明月碧琉璃。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1308, "title": "虞美人", "author": "苏轼", "body": "波声拍枕长淮晓，隙月窥人小。无情汴水自东流，只载一船离恨向西州。 竹溪花浦曾同醉，酒味多于泪。谁教风鉴在尘埃？酝造一场烦恼送人来！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1309, "title": "河满子", "author": "苏轼", "body": "湖州作，寄益守冯当世\n见说岷峨凄怆，旋闻江汉澄清。但觉秋来归梦好，西南自有长城。东府三人最少①，西山八国初平。 莫负花溪纵赏，何妨药市微行。试问当垆人在否，空教是处闻名。唱著子渊新曲，应须分外含情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1310, "title": "更漏子 送孙巨源", "author": "苏轼", "body": "水涵空，山照市，西汉二疏乡里。新白发，旧黄金，故人恩义深。 海东头，山尽处，自古客槎来去。槎有信，赴秋期，使君行不归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1311, "title": "醉落魄", "author": "苏轼", "body": "苏州阊门留别\n苍颜华发，故山归计何时决！旧交新贵音书绝，惟有佳人，犹作殷勤别。 离亭欲去歌声咽，潇潇细雨凉吹颊。泪珠不用罗巾浥，弹在罗衫，图得见时说。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1312, "title": "醉落魄 离京口作", "author": "苏轼", "body": "轻云微月，二更酒醒船初发。孤城回望苍烟合。记得歌时，不记归时节。 巾偏扇坠藤床滑，觉来幽梦无人说。此生飘荡何时歇？家在西南，常作东南别。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1313, "title": "如梦令", "author": "苏轼", "body": "为向东坡传语，人在玉堂深处。别后有谁来？雪压小桥无路。归去，归去，江上一犁春雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1314, "title": "阳关曲 中秋月", "author": "苏轼", "body": "暮云收尽溢清寒，银汉无声转玉盘。此生此夜不长好，明月明年何处看。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1315, "title": "减字木兰花", "author": "苏轼", "body": "维熊佳梦，释氏老君亲抱送。壮气横秋，未满三朝已食牛。 犀钱玉果①，利市平分沾四座。多谢无功，此事如何着得侬！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1316, "title": "减字木兰花", "author": "苏轼", "body": "钱塘西湖有诗僧清顺，所居藏春坞，门前有二古松，各有凌霄花络其上，顺常昼卧其下。余为郡①，一日屏骑从过之，松风骚然，顺指落花求韵，余为赋此。\n双龙对起，白甲苍髯烟雨里。疏影微香，下有幽人昼梦长。 湖风清软，双鹊飞来争噪晚。翠飐②红轻，时下凌霄百尺英。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1317, "title": "减字木兰花", "author": "苏轼", "body": "己卯儋耳春词\n春牛春杖，无限春风来海上。便丐春工，染得桃红似肉红。\n春幡春胜，一阵春风吹酒醒。不似天涯，卷起杨花似雪花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1318, "title": "浣溪沙", "author": "苏轼", "body": "游蕲水清泉寺，寺临兰溪，溪水西流。\n山下兰芽短浸溪，松间沙路净无泥，萧萧暮雨子规啼。\n谁道人生无再少？门前流水尚能西，休将白发唱黄鸡。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1319, "title": "浣溪沙", "author": "苏轼", "body": "万顷风涛不记苏，雪晴江上麦千车。但令人饱我愁无。\n翠袖倚风萦柳絮，绛唇得酒烂樱珠。樽前呵手镊霜须。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1320, "title": "浣溪沙 咏橘", "author": "苏轼", "body": "菊暗荷枯一夜霜。新苞绿叶照林光。竹篱茅舍出青黄。\n香雾噀人惊半破，清泉流齿怯初尝。吴姬三日手犹香。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1321, "title": "浣溪沙", "author": "苏轼", "body": "徐州石潭谢雨，道上作五首。潭在城东二十里，常与泗水增减清浊相应。\n照日深红暖见鱼，连村绿暗晚藏乌，黄童白叟聚睢盱。\n麋鹿逢人虽未惯，猿猱闻鼓不须呼，归来说与采桑姑。\n旋抹红妆看使君，三三五五棘篱门，相排踏破蒨罗裙。\n老幼扶携收麦社，乌鸢翔舞赛神村，道逢醉叟卧黄昏。\n麻叶层层檾叶光，谁家煮茧一村香？隔篱娇语络丝娘。\n垂白杖藜抬醉眼，捋青捣麨软饥肠，问言豆叶几时黄？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1322, "title": "浣溪沙", "author": "苏轼", "body": "簌簌衣巾落枣花，村南村北响缫车，牛衣古柳卖黄瓜。\n酒困路长惟欲睡，日高人渴漫思茶，敲门试问野人家。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1323, "title": "浣溪沙", "author": "苏轼", "body": "软草平莎过雨新，轻沙走马路无尘。何时收拾耦耕身？\n日暖桑麻光似泼，风来蒿艾气如薰。使君元是此中人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1324, "title": "浣溪沙 春情", "author": "苏轼", "body": "道字娇讹语未成。未应春阁梦多情。朝来何事绿鬟倾。\n彩索身轻长趁燕，红窗睡重不闻莺。困人天气近清明。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1325, "title": "浣溪沙", "author": "苏轼", "body": "风压轻云贴水飞，乍晴池馆燕争泥。沈郎多病不胜衣。\n沙上不闻鸿雁信，竹间时听鹧鸪啼。此情惟有落花知！\n浣溪沙（风压轻云贴水飞） 苏 轼\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1326, "title": "浣溪沙", "author": "苏轼", "body": "元丰七年十二月二十四日，从泗州刘倩叔游南山。\n细雨斜风作晓寒，淡烟疏柳媚晴滩。入淮清洛渐漫漫。\n雪沫乳花浮午盏，蓼茸蒿笋试春盘。人间有味是清欢。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1327, "title": "浣溪沙", "author": "苏轼", "body": "送梅庭老赴上党学官\n门外东风雪洒裾。山头回首望三吴。不应弹铗为无鱼。\n上党从来天下脊，先生元是古之儒。时平不用鲁连书。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1328, "title": "点绛唇", "author": "苏轼", "body": "红杏飘香，柳含烟翠拖轻缕。水边朱户。尽卷黄昏雨。\n烛影摇风，一枕伤春绪。归不去。凤楼何处。芳草迷归路。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1329, "title": "蝶恋花", "author": "苏轼", "body": "记得画屏初会遇。好梦惊回，望断高唐路。燕子双飞来又去。纱窗几度春光暮。 那日绣帘相见处。低眼佯行，笑整香云缕。敛尽春山羞不语。人前深意难轻诉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1330, "title": "蝶恋花", "author": "苏轼", "body": "蝶懒莺慵春过半。花落狂风，小院残红满。午醉未醒红日晚，黄昏帘幕无人卷。 云鬓鬅松眉黛浅。总是愁媒，欲诉谁消遣。未信此情难系绊，杨花犹有东风管。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1331, "title": "醉翁操", "author": "苏轼", "body": "琅琊幽谷，山水奇丽，泉鸣空涧，若中音会，醉翁喜之，把酒临听，辄欣然忘归。既去十余年，而好奇之士沈遵闻之往游，以琴写其声，曰《醉翁操》，节奏疏宕而音指华畅，知琴者以为绝伦。然有其声而无其辞。翁虽为作歌，而与琴声不合。又依《楚词》作《醉翁引》，好事者亦倚其辞以制曲。虽粗合韵度而琴声为词所绳约，非天成也。后三十余年，翁既捐馆舍，遵亦没久矣。有庐山玉涧道人崔闲，特妙于琴，恨此曲之无词，乃谱其声，而请于东坡居士以补之云。\n琅然，清圆，谁弹，响空山。无言，惟翁醉中知①其天。月明风露娟娟，人未眠。荷蒉过山前，曰有心也哉此贤。 醉翁啸咏，声和流泉。醉翁去后，空有朝吟夜怨②。山有时而童颠，水有时而回川。思翁无岁年，翁今为飞仙。此意在人间，试听徽外三两弦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1332, "title": "沁园春", "author": "苏轼", "body": "情若连环，恨如流水，甚时是休。也不须惊怪，沈郎易瘦；也不须惊怪，潘鬓先愁。总是难禁，许多魔难，奈好事教人不自由。空追想，念前欢杳杳，后会悠悠。 凝眸。悔上层楼。谩惹起新愁压旧愁。向彩笺写遍，相思字了，重重封卷，密寄书邮。料到伊行，时时开看，一看一回和泪收。须知道，□这般病染，两处心头。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1333, "title": "谢池春", "author": "李之仪", "body": "残寒销尽，疏雨过，清明后。花径敛余红，风沼萦新皱。乳燕穿庭户，飞絮沾襟袖。正佳时，仍晚昼。著人滋味，真个浓如酒。 频移带眼，空只恁、厌厌瘦。不见又相思，见了还依旧。为问频相见，何似长相守？天不老，人未偶。且将此恨，分付庭前柳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1334, "title": "卜算子", "author": "李之仪", "body": "我住长江头，君住长江尾。日日思君不见君，共饮长江水。 此水几时休，此恨何时已。只愿君心似我心，定不负相思意。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1335, "title": "忆秦娥 用太白韵", "author": "李之仪", "body": "清溪咽。霜风洗出山头月。山头月。迎得云归，还送云别。 不知今是何时节。凌歊望断音尘绝。音尘绝。帆来帆去，天际双阙。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1336, "title": "临江仙 登凌歊台① 感怀", "author": "李之仪", "body": "偶向凌歊台上望，春光已过三分。江山重叠倍销魂。风花飞有态，烟絮坠无痕。 已是年来伤感甚，那堪旧恨仍存！清愁满眼共谁论？却应台下草，不解忆王孙？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1337, "title": "虞美人 寄公度", "author": "舒亶", "body": "芙蓉落尽天涵水，日暮沧波起。背飞双燕贴云寒，独向小楼东畔倚阑看。 浮生只合尊前老，雪满长安道。故人早晚上高台，赠我江南春色一枝梅。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1338, "title": "一落索", "author": "舒亶", "body": "蒋园和李朝奉\n正是看花天气，为春一醉。醉来却不带花归，诮不解看花意。 试问此花明媚，将花谁比？只应花好似年年，花不似人憔悴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1339, "title": "菩萨蛮", "author": "舒亶", "body": "画船捶鼓催君去，高楼把酒留君住。去住若为情，西江潮欲平。 江潮容易得，只是人南北。今日此樽空，知君何日同！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1340, "title": "减字木兰花 竞渡", "author": "黄裳", "body": "红旗高举，飞出深深杨柳渚。鼓击春雷，直破烟波远远回。 欢声震地，惊退万人争战气。金碧楼西，衔得锦标第一归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1341, "title": "倦寻芳慢", "author": "王雱", "body": "露晞向晚，帘幕风轻，小院闲昼。翠径莺来，惊下乱红铺绣。倚危墙，登高榭，海棠经雨胭脂透。算韶华，又因循过了，清明时候。 倦游燕，风光满目，好景良辰，谁共携手？恨被榆钱，买断两眉长斗。忆高阳，人散后，落花流水仍依旧。这情怀，对东风，尽成消瘦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1342, "title": "念奴娇", "author": "黄庭坚", "body": "八月十七日，同诸生①步自永安城楼，过张宽夫园待月。偶有名酒，因以金荷酌众客。客有孙彦立，善吹笛。援笔作乐府长短句，文不加点。\n断虹霁雨，净秋空，山染修眉新绿。桂影扶疏，谁便道，今夕清辉不足？万里青天，姮娥何处，驾此一轮玉。寒光零乱，为谁偏照醽醁？ 年少从我追游，晚凉幽径，绕张园森木。共倒金荷，家万里，难得尊前相属。老子平生，江南江北，最爱临风笛。孙郎微笑，坐来声喷霜竹。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1343, "title": "水调歌头", "author": "黄庭坚", "body": "瑶草一何碧，春入武陵溪。溪上桃花无数，枝上有黄鹂。我欲穿花寻路，直入白云深处，浩气展虹霓。祇恐花深里，红露湿人衣。 坐玉石，倚玉枕，拂金徽。谪仙何处，无人伴我白螺杯。我为灵芝仙草，不为朱唇丹脸，长啸亦何为？醉舞下山去，明月逐人归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1344, "title": "满庭芳 茶", "author": "黄庭坚", "body": "北苑春风，方圭圆璧，万里名动京关。碎身粉骨、功合上凌烟。尊俎风流战胜，降春睡、开拓愁边。纤纤捧，研膏溅乳，金缕鹧鸪斑。 相如虽病渴，一觞一咏，宾有群贤。为扶起灯前，醉玉颓山。搜搅胸中万卷，还倾动、三峡词源。归来晚，文君未寝，相对小窗前。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1345, "title": "醉蓬莱", "author": "黄庭坚", "body": "对朝云叆叇，暮雨霏微，乱峰相倚。巫峡高唐，锁楚宫朱翠。画戟移春，靓妆迎马，向一川都会。万里投荒，一身吊影，成何欢意！ 尽道黔南，去天尺五，望极神州，万重烟水。樽酒公堂，有中朝佳士。荔颊红深，麝脐香满，醉舞裀歌袂。杜宇声声，催人到晓，不如归是。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1346, "title": "蓦山溪", "author": "黄庭坚", "body": "赠衡阳妓陈湘\n鸳鸯翡翠，小小思珍偶。眉黛敛秋波，尽湖南、山明水秀。娉娉嫋嫋，恰似十三馀，春未透，花枝瘦，正是愁时候。 寻花载酒，肯落谁人后。只恐远归来，绿成阴，青梅如豆。心期得处，每自不由人，长亭柳，君知否，千里犹回首？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1347, "title": "定风波", "author": "黄庭坚", "body": "次高左藏使君韵\n万里黔中一漏天，屋居终日似乘船。及至重阳天也霁，催醉，鬼门关外蜀江前。 莫笑老翁犹气岸，君看，几人黄菊上华颠？戏马台南追两谢，驰射，风流犹拍古人肩。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1348, "title": "阮郎归", "author": "黄庭坚", "body": "效福唐独木桥体作茶词\n烹茶留客驻金鞍。月斜窗外山。别郎容易见郎难。有人思远山。 归去后，忆前欢。画屏金博山。一杯春露莫留残。与郎扶玉山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1349, "title": "清平乐", "author": "黄庭坚", "body": "春归何处？寂寞无行路。若有人知春去处，唤取归来同住。 春无踪迹谁知？除非问取黄鹂。百啭无人能解，因风飞过蔷薇。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1350, "title": "鹧鸪天", "author": "黄庭坚", "body": "座中有眉山隐客史应之和前韵，即席答之\n黄菊枝头生晓寒。人生莫放酒杯干。风前横笛斜吹雨，醉里簪花倒著冠。 身健在，且加餐。舞裙歌板尽清欢。黄花白发相牵挽，付与时人冷眼看。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1351, "title": "南歌子", "author": "黄庭坚", "body": "槐绿低窗暗，榴红照眼明。玉人邀我少留行。无奈一帆烟雨画船轻。 柳叶随歌皱，梨花与泪倾。别时不似见时情。今夜月明江上酒初醒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1352, "title": "谒金门 示知命弟", "author": "黄庭坚", "body": "山又水，行尽吴头楚尾。兄弟灯前家万里，相看如梦寐。\n君似成蹊桃李，入我草堂松桂。莫厌岁寒无气味，馀生今已矣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1353, "title": "渔家傲", "author": "黄庭坚", "body": "三十年来无孔竅，几回得眼还迷照。一见桃花参学了。呈法要，无弦琴上单于调。 摘叶寻枝虚半老，看花特地重年少。今后水云人欲晓。非玄妙，灵云合被桃花笑。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1354, "title": "诉衷情", "author": "黄庭坚", "body": "在戎州登临胜景，未尝不歌渔父家风，以谢江山。门生请问：先生家风如何？为拟金华道人作此章。\n一波才动万波随，蓑笠一钩丝。金鳞正在深处，千尺也须垂。 吞又吐，信还疑，上钩迟。水寒江静，满目青山，载月明归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1355, "title": "菩萨蛮", "author": "黄庭坚", "body": "半烟半雨溪桥畔，渔翁醉着无人唤。疏懒意何长，春风花草香。 江山如有待，此意陶潜解。问我去何之，君行到自知。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1356, "title": "西江月", "author": "黄庭坚", "body": "老夫既戒酒不饮，遇宴集，独醒其旁。坐客欲得小词，援笔为赋。\n断送一生惟有，破除万事无过。远山横黛蘸秋波，不饮旁人笑我。 花病等闲瘦弱，春愁无处遮拦。杯行到手莫留残，不道月斜人散。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1357, "title": "虞美人 宜州见梅作", "author": "黄庭坚", "body": "天涯也有江南信，梅破知春近。夜阑风细得香迟，不道晓来开遍向南枝。 玉台弄粉花应妒，飘到眉心住。平生个里愿杯深，去国十年老尽少年心。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1358, "title": "西江月", "author": "黄庭坚", "body": "月仄金盆堕水，雁回醉墨书空。君诗秀绝雨园葱，想见衲衣寒拥。 蚁穴梦魂人世，杨花踪迹风中。莫将社燕笑秋鸿，处处春山翠重。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1359, "title": "木兰花令", "author": "黄庭坚", "body": "当涂解印后一日，郡中置酒，呈郭功甫。\n凌歊台上青青麦，姑孰堂前馀翰墨。暂分一印管江山，稍为诸公分皂白。 江山依旧云空碧，昨日主人今日客。谁分宾主强惺惺，问取矶头新妇石。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1360, "title": "品令 茶词", "author": "黄庭坚", "body": "凤舞团团饼。恨分破，教孤令。金渠体净，只轮慢碾，玉尘光莹。汤响松风，早减了二分酒病。 味浓香永。醉乡路，成佳境。恰如灯下，故人万里，归来对影。口不能言，心下快活自省。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1361, "title": "归田乐引", "author": "黄庭坚", "body": "对景还消瘦。被箇人、把人调戏，我也心儿有。忆我又唤我，见我嗔我，天甚教人怎生受。 看承幸厮勾，又是尊前眉峰皱。是人惊怪，冤我忒撋就。拚了又舍了，定是这回休了，及至相逢又依旧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1362, "title": "南乡子", "author": "黄庭坚", "body": "重阳日，宜州城楼宴集，即席作。\n诸将说封侯，短笛长歌独倚楼。万事尽随风雨去，休休，戏马台南金络头。 催酒莫迟留，酒味今秋似去秋。花向老人头上笑，羞羞，白发簪花不解愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1363, "title": "千秋岁", "author": "黄庭坚", "body": "少游得谪，尝梦中作词云：“醉卧古藤阴下，了不知南北。”竟以元符庚辰①，死于藤州②光华亭上。崇宁甲申③，庭坚窜宜州④，道过衡阳⑤。览其遗墨，始追和其《千秋岁》词。\n苑边花外，记得同朝退。飞骑轧⑥，鸣珂碎⑦。齐歌云绕扇⑧，赵舞⑨风回带。严鼓断⑩，杯盘狼藉犹相对。 洒泪谁能会？醉卧藤阴盖。人已去，词空在。兔园⑪高宴悄，虎观⑫英游改。重感慨，波涛万顷珠沉海。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1364, "title": "望江东", "author": "黄庭坚", "body": "江水西头隔烟树，望不见江东路。思量只有梦来去，更不怕、江拦住。 灯前写了书无数，算没个、人传与。直饶寻得雁分付，又还是秋将暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1365, "title": "诉衷情", "author": "黄庭坚", "body": "小桃灼灼柳鬖鬖①，春色满江南。雨晴风暖烟淡，天气正醺酣。 山泼黛，水挼②蓝，翠相搀。歌楼酒旆③，故故招人，权典④青衫。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1366, "title": "瑞鹤仙", "author": "黄庭坚", "body": "环滁皆山也。望蔚然深秀，琅琊山也。山行六七里，有翼然泉上，醉翁亭也。翁之乐也。得之心、寓之酒也。更野芳佳木，风高日出，景无穷也。 游也。山肴野蔌，酒洌泉香，沸筹觥也。太守醉也。喧哗众宾欢也。况宴酣之乐、非丝非竹，太守乐其乐也。问当时、太守为谁，醉翁是也。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1367, "title": "绿头鸭 咏月", "author": "晁端礼", "body": "晚云收，淡天一片琉璃。烂银盘、来从海底，皓色千里澄辉。莹无尘、素娥澹伫；静可数、丹桂参差。玉露初零，金风未凛，一年无似此佳时。露坐久，疏萤时度，乌鹊正南飞。瑶台冷，栏干凭暖，欲下迟迟。 念佳人音尘别后，对此应解相思。最关情、漏声正永，暗断肠、花影偷移。料得来宵，清光未减，阴晴天气又争知？共凝恋，如今别后，还是隔年期。人强健，清樽素影，长愿相随。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1368, "title": "水龙吟", "author": "晁端礼", "body": "倦游京洛风尘，夜来病酒无人问。九衢雪少，千门月淡，元宵灯近。香散梅梢，冻消池面，一番春信。记南楼醉里，西城宴阕，都不管、人春困。 屈指流年未几，早人惊、潘郎双鬓。当时体态，如今情绪，多应瘦损。马上墙头，纵教瞥见，也难相认。凭阑干，但有盈盈泪眼，把罗襟揾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1369, "title": "茶瓶儿", "author": "李元膺", "body": "去年相逢深院宇，海棠下、曾歌《金缕》。歌罢花如雨。翠罗衫上，点点红无数。 今岁重寻携手处，空物是人非春暮。回首青门①路。乱红飞絮，相逐东风去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1370, "title": "洞仙歌", "author": "李元膺", "body": "一年春物，惟梅柳间意味最深。至莺花烂熳时，则春已衰迟，使人无复新意。予作《洞仙歌》，使探春者歌之，无后时之悔。\n雪云散尽，放晓晴池院。杨柳于人便青眼。更风流多处，一点梅心，相映远，约略颦轻笑浅。 一年春好处，不在浓芳，小艳疏香最娇软。到清明时候，百紫千红，花正乱，已失春风一半。早占取韶光共追游，但莫管春寒，醉红自暖。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1371, "title": "渔家傲", "author": "朱服", "body": "小雨纤纤风细细，万家杨柳青烟里。恋树湿花飞不起。愁无比，和春付与东流水。 九十光阴能有几？金龟解尽留无计。寄语东城沽酒市。拚一醉，而今乐事他年泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1372, "title": "清平乐", "author": "刘弇", "body": "东风依旧，著意隋堤柳。搓得鹅儿黄欲就，天气清明时候。 去年紫陌青门，今宵雨魄云魂。断送一生憔悴，能消几个黄昏！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1373, "title": "青门饮 寄宠人", "author": "时彦", "body": "胡马嘶风，汉旗翻雪，彤云又吐，一竿残照。古木连空，乱山无数，行尽暮沙衰草。星斗横幽馆，夜无眠、灯花空老。雾浓香鸭，冰凝泪烛，霜天难晓。 长记小妆才了。一杯未尽，离怀多少。醉里秋波，梦中朝雨，都是醒时烦恼。料有牵情处，忍思量、耳边曾道。甚时跃马归来，认得迎门轻笑。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1374, "title": "望海潮", "author": "秦观", "body": "梅英疏淡，冰凘溶泄，东风暗换年华。金谷俊游，铜驼巷陌，新晴细履平沙。长记误随车。正絮翻蝶舞，芳思交加。柳下桃蹊，乱分春色到人家。 西园夜饮鸣笳。有华灯碍月，飞盖妨花。兰苑未空，行人渐老，重来是事堪嗟！烟暝酒旗斜。但倚楼极目，时见栖鸦。无奈归心，暗随流水到天涯。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1375, "title": "水龙吟", "author": "秦观", "body": "小楼连苑横空，下窥绣毂雕鞍骤①。朱帘半卷，单衣初试，清明时候。破暖轻风，弄晴微雨，欲无还有。卖花声过尽，斜阳院落；红成阵，飞鸳甃。 玉珮丁东别后。怅佳期、参差难又。名缰利锁，天还知道，和天也瘦。花下重门，柳边深巷，不堪回首。念多情、但有当时皓月，向人依旧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1376, "title": "八六子", "author": "秦观", "body": "倚危亭，恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊。 无端天与娉婷，夜月一帘幽梦，春风十里柔情。怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。正销凝，黄鹂又啼数声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1377, "title": "满庭芳", "author": "秦观", "body": "山抹微云，天连衰草，画角声断谯门。暂停征棹，聊共引离尊。多少蓬莱旧事，空回首，烟霭纷纷。斜阳外，寒鸦万点，流水绕孤村。 销魂。当此际，香囊暗解，罗带轻分。谩赢得青楼，薄幸名存。此去何时见也，襟袖上，空惹啼痕。伤情处，高城望断，灯火已黄昏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1378, "title": "满庭芳", "author": "秦观", "body": "红蓼花繁，黄芦叶乱，夜深玉露初零。霁天空阔，云淡楚江清。独棹孤篷小艇，悠悠过、烟渚沙汀。金钩细，丝纶慢卷，牵动一潭星。 时时横短笛，清风皓月，相与忘形。任人笑生涯，泛梗飘萍。饮罢不妨醉卧，尘劳事、有耳谁听？江风静，日高未起，枕上酒微醒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1379, "title": "满庭芳", "author": "秦观", "body": "碧水惊秋，黄云凝暮，败叶零乱空阶。洞房人静，斜月照徘徊。又是重阳近也，几处处、砧杵声催。西窗下，风摇翠竹，疑是故人来。 伤怀！增怅望，新欢易失，往事难猜。问篱边黄菊，知为谁开？谩道愁须殢酒，酒未醒、愁已先回。凭栏久，金波渐转，白露点苍苔。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1380, "title": "江城子", "author": "秦观", "body": "西城杨柳弄春柔，动离忧，泪难收。犹记多情曾为系归舟。碧野朱桥当日事，人不见，水空流。 韶华不为少年留。恨悠悠，几时休？飞絮落花时候一登楼。便做春江都是泪，流不尽，许多愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1381, "title": "鹊桥仙", "author": "秦观", "body": "纤云弄巧，飞星传恨，银汉迢迢暗渡。金风玉露一相逢，便胜却人间无数。 柔情似水，佳期如梦，忍顾鹊桥归路。两情若是久长时，又岂在朝朝暮暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1382, "title": "减字木兰花", "author": "秦观", "body": "天涯旧恨，独自凄凉人不问。欲见回肠，断尽金炉小篆香。 黛蛾长敛，任是春风吹不展。困倚危楼，过尽飞鸿字字愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1383, "title": "画堂春", "author": "秦观", "body": "落红铺径水平池，弄晴小雨霏霏。杏园憔悴杜鹃啼，无奈春归。 柳外画楼独上，凭栏手撚花枝。放花无语对斜晖，此恨谁知。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1384, "title": "千秋岁", "author": "秦观", "body": "水边沙外，城郭春寒退。花影乱，莺声碎。飘零疏酒盏，离别宽衣带。人不见，碧云暮合空相对。 忆昔西池会，鹓鹭同飞盖。携手处，今谁在？日边清梦断，镜里朱颜改。春去也，飞红万点愁如海。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1385, "title": "踏莎行", "author": "秦观", "body": "雾失楼台，月迷津渡，桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。 驿寄梅花①，鱼传尺素②，砌成此恨无重数。郴江幸自③绕郴山，为谁流下潇湘去？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1386, "title": "南乡子", "author": "秦观", "body": "妙手写徽真，水剪双眸点绛唇。疑是昔年窥宋玉，东邻；只露墙头一半身。 往事已酸辛，谁记当年翠黛颦？尽道有些堪恨处，无情；任是无情也动人！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1387, "title": "浣溪沙", "author": "秦观", "body": "漠漠轻寒上小楼，晓阴无赖似穷秋。淡烟流水画屏幽。\n自在飞花轻似梦，无边丝雨细如愁。宝帘闲挂小银钩。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1388, "title": "如梦令", "author": "秦观", "body": "遥夜沉沉如水，风紧驿亭深闭。梦破鼠窥灯，霜送晓寒侵被。无寐，无寐，门外马嘶人起。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1389, "title": "阮郎归", "author": "秦观", "body": "湘天风雨破寒初，深沉庭院虚。丽谯吹罢《小单于》，迢迢清夜徂。 乡梦断，旅魂孤。峥嵘岁又除。衡阳犹有雁传书，郴阳和雁无。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1390, "title": "满庭芳", "author": "秦观", "body": "晓色云开，春随人意，骤雨才过还晴。古台芳榭，飞燕蹴红英。舞困榆钱自落，秋千外、绿水桥平。东风里，朱门映柳，低按小秦筝。 多情，行乐处，珠钿翠盖，玉辔红缨。渐酒空金榼，花困蓬瀛。豆蔻梢头旧恨，十年梦、屈指堪惊。凭阑久，疏烟淡日，寂寞下芜城。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1391, "title": "桃源忆故人", "author": "秦观", "body": "玉楼深锁薄情种，清夜悠悠谁共？羞见枕衾鸳凤，闷则和衣拥。 无端画角严城动，惊破一番新梦。窗外月华霜重，听彻《梅花弄》。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1392, "title": "调笑令 莺莺", "author": "秦观", "body": "春梦，神仙洞。冉冉拂墙花影动。西厢待月知谁共？更觉玉人情重。红娘深夜行云送，困亸钗横金凤。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1393, "title": "虞美人", "author": "秦观", "body": "碧桃天上栽和露，不是凡花数。乱山深处水潆回，可惜一枝如画为谁开？ 轻寒细雨情何限，不道春难管。为君沉醉又何妨，只怕酒醒时候断人肠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1394, "title": "点绛唇", "author": "秦观", "body": "醉漾轻舟，信流引到花深处。尘缘相误，无计花间住。\n烟水茫茫，千里斜阳暮。山无数，乱红如雨，不记来时路。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1395, "title": "南歌子", "author": "秦观", "body": "玉漏迢迢尽，银潢淡淡横。梦回宿酒未全醒，已被邻鸡催起怕天明。 臂上妆犹在，襟间泪尚盈。水边灯火渐人行，天外一钩残月带三星。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1396, "title": "南歌子", "author": "秦观", "body": "香墨弯弯画，燕脂淡淡匀。揉蓝衫子杏黄裙，独倚玉阑无语点檀唇。 人去空流水，花飞半掩门。乱山何处觅行云？又是一钩新月照黄昏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1397, "title": "临江仙", "author": "秦观", "body": "千里潇湘挼蓝①浦，兰桡昔日曾经。月高风定露华清。微波澄不动，冷浸一天星。 独倚危樯情悄悄，遥闻妃瑟泠泠。新声含尽古今情。曲终人不见，江上数峰青。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1398, "title": "好事近 梦中作", "author": "秦观", "body": "春路雨添花，花动一山春色。行到小溪深处，有黄鹂千百。\n飞云当面舞龙蛇，夭矫转空碧。醉卧古藤阴下，了不知南北。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1399, "title": "画堂春", "author": "秦观", "body": "东风吹柳日初长，雨余芳草斜阳。杏花零落燕泥香，睡损红妆。 宝篆烟销龙凤，画屏云锁潇湘。夜寒微透薄罗裳，无限思量。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1400, "title": "行香子①", "author": "秦观", "body": "树绕村庄，水满陂塘。倚东风、豪兴徜徉。小园几许，收尽春光。有桃花红，李花白，菜花黄。 远远围墙，隐隐茅堂。飏青旗、流水桥旁。偶然乘兴，步过东冈。正莺儿啼，燕儿舞，蝶儿忙。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1401, "title": "水调歌头 中秋", "author": "米芾", "body": "砧声送风急，蟋蟀思高秋。我来对景，不学宋玉解悲愁。收拾凄凉兴况，分付尊中醽醁，倍觉不胜幽。自有多情处，明月挂南楼。 怅襟怀，横玉笛，韵悠悠。清时良夜，借我此地倒金瓯。可爱一天风物，遍倚栏干十二，宇宙若萍浮。醉困不知醒，欹枕卧江流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1402, "title": "蝶恋花", "author": "米芾", "body": "海岱楼玩月作\n千古涟漪清绝地。海岱楼高，下瞰秦淮尾。水浸碧天天似水。广寒宫阙人间世。 霭霭春和生海市。鳌戴三山，顷刻随轮至。宝月圆时多异气。夜光一颗千金贵。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1403, "title": "满庭芳 咏茶", "author": "米芾", "body": "雅燕飞觞，清谈挥麈，使君高会群贤。密云双凤，初破缕金团。窓外炉烟自动，开瓶试、一品香泉。轻涛起，香生玉乳，雪溅紫瓯圆。 娇鬟，宜美盼，双擎翠袖，稳步红莲。座中客翻愁，酒醒歌阑。点上纱笼画烛，花骢弄、月影当轩。频相顾，馀欢未尽，欲去且留连。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1404, "title": "帝台春", "author": "李甲", "body": "芳草碧色，萋萋遍南陌。暖絮乱红，也知人春愁无力。忆得盈盈拾翠侣，共携赏、凤城寒食。到今来，海角逢春，天涯为客。 愁旋释，还似织；泪暗拭，又偷滴。谩伫立、遍倚危阑，尽黄昏，也只是暮云凝碧。拚则而今已拚了，忘则怎生便忘得。又还问鳞鸿，试重寻消息。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1405, "title": "蝶恋花", "author": "赵令畤", "body": "庭院黄昏春雨霁。一缕深心，百种成牵系。青翼蓦然来报喜，鱼笺微谕相容意。 待月西厢人不寐。帘影摇光，朱户犹慵闭。花动拂墙红萼坠，分明疑是情人至。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1406, "title": "菩萨蛮", "author": "赵令畤", "body": "春风试手先梅蕊，頩姿冷艳明沙水。不受众芳知，端须月与期。 清香闲自远，先向钗头见。雪后燕瑶池，人间第一枝。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1407, "title": "蝶恋花", "author": "赵令畤", "body": "欲减罗衣寒未去，不卷珠帘，人在深深处。红杏枝头花几许？啼痕止恨清明雨。 尽日沉烟香一缕，宿酒醒迟，恼破春情绪。飞燕又将归信误，小屏风上西江路。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1408, "title": "蝶恋花", "author": "赵令畤", "body": "卷絮风头寒欲尽。坠粉飘香，日日红成阵。新酒又添残酒困。今春不减前春恨。 蝶去莺飞无处问。隔水高楼，望断双鱼信。恼乱横波秋一寸。斜阳只与黄昏近。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1409, "title": "浣溪沙", "author": "赵令畤", "body": "水满池塘花满枝。乱香深里语黄鹂。东风轻软弄帘帏。\n日正长时春梦短，燕交飞处柳烟低。玉窗红子斗棋时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1410, "title": "乌夜啼 春思", "author": "赵令畤", "body": "楼上萦帘弱絮，墙头碍月低花。年年春事关心事，肠断欲栖鸦。 舞镜鸾衾翠减，啼珠凤蜡红斜。重门不锁相思梦，随意绕天涯。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1411, "title": "半死桐", "author": "贺铸", "body": "（思越人，又名鹧鸪天）\n重过阊门万事非，同来何事不同归？梧桐半死①清霜后，头白鸳鸯失伴飞。 原上草，露初晞。旧栖新垅两依依。空床卧听南窗雨，谁复挑灯夜补衣！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1412, "title": "夜捣衣 （古捣练子）", "author": "贺铸", "body": "收锦字，下鸳机，净拂床砧夜捣衣。马上少年①今健否？过瓜时见雁南归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1413, "title": "杵声齐 （古捣练子）", "author": "贺铸", "body": "砧面莹，杵声齐。捣就征衣泪墨题。寄到玉关应万里，戍人犹在玉关西。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1414, "title": "夜如年 （古捣练子）", "author": "贺铸", "body": "斜月下，北风前。万杵千砧捣欲穿。不为捣衣勤不睡，破除今夜夜如年。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1415, "title": "望书归 （古捣练子）", "author": "贺铸", "body": "边堠①远，置邮②稀，附与征衣衬铁衣。连夜不妨频梦见，过年③惟望得书归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1416, "title": "南歌子", "author": "贺铸", "body": "疏雨池塘见，微风襟袖知。阴阴夏木啭黄鹂。何处飞来白鹭立移时。 易醉扶头酒，难逢敌手棋。日长偏与睡相宜。睡起芭蕉叶上自题诗。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1417, "title": "梦江南 （太平时）", "author": "贺铸", "body": "九曲池头三月三，柳毵毵。香尘扑马喷金衔，涴春衫。\n苦笋鲥鱼乡味美，梦江南。阊门烟水晚风恬，落归帆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1418, "title": "愁风月 （生查子）", "author": "贺铸", "body": "风清月正圆，信是佳时节。不会长年来，处处愁风月。\n心将熏麝焦，吟伴寒虫切。欲遽就床眠，解带翻成结。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1419, "title": "陌上郎 （生查子）", "author": "贺铸", "body": "西津海鹘舟，径度沧江雨。双艫本无情，鸦轧如人语。\n“挥金陌上郎，化石山头妇。何物系君心？三岁扶床女！”", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1420, "title": "惜余春 （踏莎行）", "author": "贺铸", "body": "急雨收春，斜风约水，浮红涨绿鱼文起。年年游子惜余春，春归不解招游子。 留恨城隅，关情纸尾，阑干长对西曛倚。鸳鸯俱是白头时，江南渭北三千里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1421, "title": "阳羡歌 （踏莎行）", "author": "贺铸", "body": "山秀芙蓉，溪明罨画。真游洞穴沧波下。临风慨想斩蛟灵，长桥千载犹横跨。 解组投簪，求田问舍。黄鸡白酒渔樵社。元龙非复少时豪，耳根清净功名话。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1422, "title": "踏莎行", "author": "贺铸", "body": "杨柳回塘，鸳鸯别浦，绿萍涨断莲舟路。断无蜂蝶慕幽香，红衣脱尽芳心苦。 返照迎潮，行云带雨，依依似与骚人语。当年不肯嫁春风，无端却被秋风误。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1423, "title": "将进酒 （小梅花）", "author": "贺铸", "body": "城下路，凄风露，今人犁田古人墓。岸头沙，带蒹葭，漫漫昔时流水今人家①。黄埃赤日长安道，倦客无浆马无草②。开函关，掩函关，千古如何不见一人闲？ 六国扰，三秦③扫，初谓商山遗四老。驰单车，致缄书，裂荷焚芰④接武曳长裾。高流端得酒中趣，深入醉乡安稳处。生忘形，死忘名，谁论二豪初不数刘伶⑤？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1424, "title": "行路难 （小梅花）", "author": "贺铸", "body": "缚虎手，悬河口，车如鸡栖马如狗。白纶巾，扑黄尘，不知我辈可是蓬嵩人？衰兰送客咸阳道，天若有情天亦老。作雷颠，不论钱①，谁问旗亭美酒斗十千？ 酌大斗，更为寿，青鬓长青古无有。笑嫣然，舞翩然，当垆秦女十五语如弦。遗音能记秋风曲，事去千年犹恨促。揽流光，系扶桑，争奈愁来一日却为长。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1425, "title": "凌歊", "author": "贺铸", "body": "（铜人捧露盘引）\n控沧江，排青嶂，燕台凉。驻彩仗、乐未渠央。岩花磴蔓，妒千门珠翠倚新妆。舞闲歌悄，恨风流不管余香。 繁华梦，惊俄顷；佳丽地，指苍茫。寄一笑、何与兴亡！量船载酒，赖使君相对两胡床。缓调清管，更为侬三弄斜阳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1426, "title": "台城游 （水调歌头）", "author": "贺铸", "body": "南国本潇洒，六代浸豪奢。台城①游冶，襞笺能赋属宫娃。云观登临清夏，璧月流连长夜，吟醉送年华。回首飞鸳瓦，却羡井中蛙。 访乌衣，成白社，不容车。旧时王谢，堂前双燕过谁家？楼外河横斗挂，淮上潮平霜下，樯影落寒沙。商女蓬窗罅，犹唱《后庭花》。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1427, "title": "青玉案", "author": "贺铸", "body": "凌波不过横塘路，但目送、芳尘去。锦瑟华年谁与度？月桥花院，琐窗朱户，只有春知处。 飞云冉冉蘅皋暮，彩笔新题断肠句。若问闲情都几许？一川烟草，满城风絮，梅子黄时雨！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1428, "title": "人南渡 （感皇恩）", "author": "贺铸", "body": "兰芷满汀洲，游丝横路。罗袜尘生步，迎顾。整鬟颦黛，脉脉两情难语。细风吹柳絮，人南渡。 回首旧游，山无重数。花底深朱户，何处？半黄梅子，向晚一帘疏雨。断魂分付与，春将去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1429, "title": "薄幸", "author": "贺铸", "body": "淡妆多态，更的的频回眄睐。便认得琴心先许，欲绾合欢双带。记画堂风月逢迎，轻颦浅笑娇无奈。向睡鸭炉边，翔鸾屏里，羞把香罗暗解。 自过了烧灯后，都不见踏青挑菜。几回凭双燕，丁宁深意，往来却恨重帘碍。约何时再。正春浓酒困，人闲昼永无聊赖。厌厌睡起，犹有花梢日在。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1430, "title": "伴云来 （天香）", "author": "贺铸", "body": "烟络横林，山沉远照①，逦迤黄昏钟鼓。烛映帘栊，蛩催机杼②，共苦清秋风露。不眠思妇，齐应和、几声砧杵。惊动天涯倦宦，骎骎岁华行暮③。 当年酒狂自负④，谓东君、以春相付。流浪征骖北道、客樯南浦。幽恨无人晤语。赖明月、曾知旧游处⑤，好伴云来，还将梦去⑥。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1431, "title": "国门东 （好女儿）", "author": "贺铸", "body": "车马匆匆，会国门东。信人间自古消魂处，指红尘北道，碧波南浦，黄叶西风。 候馆娟娟新月，从今夜、与谁同？想深闺独守空床思，但频占镜鹊①，悔分钗燕，长望书鸿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1432, "title": "梦相亲 （木兰花）", "author": "贺铸", "body": "清琴再鼓求凰弄，紫陌屡盘骄马鞚①。远山眉样认心期，流水车音②牵目送③。 归来翠被和衣拥，醉解寒生钟鼓动。此欢只许梦相亲，每向梦中还说梦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1433, "title": "菩萨蛮", "author": "贺铸", "body": "彩舟载得离愁动，无端更借樵风送。波渺夕阳迟，销魂不自持。 良宵谁与共，赖有窗间梦。可奈梦回时，一番新别离！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1434, "title": "琴调相思引", "author": "贺铸", "body": "送范殿监赴黄岗\n终日怀归翻送客，春风祖席南城陌。便莫惜离觞频卷白。动管色，催行色；动管色，催行色。 何处投鞍风雨夕？临水驿，空山驿；临水驿，空山驿。纵明月相思千里隔。梦咫尺，勤书尺；梦咫尺，勤书尺。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1435, "title": "芳草渡", "author": "贺铸", "body": "留征辔，送离杯。羞泪下，撚青梅。低声问道几时回。秦筝雁促，此夜为谁排？ 君去也，远蓬莱。千里地，信音乖。相思成病底情怀？和烦恼，寻个便，送将来。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1436, "title": "点绛唇", "author": "贺铸", "body": "一幅霜绡，麝煤熏纹丝缕。掩妆无语，的是消凝处。\n薄暮兰桡，漾下苹花渚。风留住。绿杨归路，燕子西飞去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1437, "title": "西江月", "author": "贺铸", "body": "携手看花深径，扶肩待月斜廊。临分少伫已伥伥，此段不堪回想。 欲寄书如天远，难销夜似年长。小窗风雨碎人肠，更在孤舟枕上。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1438, "title": "小重山", "author": "贺铸", "body": "花院深疑无路通。碧纱窗影下，玉芙蓉。当时偏恨五更钟。分携处，斜月小帘栊。 楚梦冷沉踪。一双金缕枕，半床空。画桥临水凤城东。楼前柳，憔悴几秋风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1439, "title": "减字浣溪沙", "author": "贺铸", "body": "秋水斜阳演漾金，远山隐隐隔平林。几家村落几声砧。\n记得西楼凝醉眼，昔年风物似如今。只无人与共登临。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1440, "title": "减字浣溪沙", "author": "贺铸", "body": "闲把琵琶旧谱寻，四弦声怨却沉吟。燕飞人静画堂深。\n欹枕有时成雨梦，隔帘无处说春心。一从灯夜到如今。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1441, "title": "减字浣溪沙", "author": "贺铸", "body": "楼角初销一缕霞，淡黄杨柳暗栖鸦，玉人和月摘梅花。\n笑撚粉香归洞户，更垂帘幕护窗纱，东风寒似夜来些。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1442, "title": "天门谣", "author": "贺铸", "body": "牛渚天门险，限南北、七雄豪占。清雾敛，与闲人登览。 待月上潮平波滟滟，塞管轻吹新阿滥。风满槛，历历数、西州更点。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1443, "title": "六州歌头", "author": "贺铸", "body": "少年侠气，交结五都①雄。肝胆洞，毛发耸。立谈②中，死生同。一诺千金重③。推翘勇，矜豪纵。轻盖拥，联飞鞚，斗城④东。轰饮酒垆，春色⑤浮寒瓮，吸海垂虹⑥。间呼鹰嗾犬，白羽⑦摘雕弓，狡穴⑧俄空。乐匆匆。 似黄粱梦。辞丹凤⑨，明月共，漾孤篷。官冗从⑩，怀倥偬，落尘笼。簿书丛，鹖弁如云众⑪，供粗用，忽奇功。笳鼓动，渔阳弄⑫，思悲翁⑬。不请长缨，系取天骄种⑭，剑吼⑮西风。恨登山临水，手寄七弦桐⑯，目送归鸿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1444, "title": "石州引", "author": "贺铸", "body": "薄雨收寒，斜照弄晴，春意空阔。长亭柳色才黄，远客一枝先折。烟横水际，映带几点归鸿，东风销尽龙沙雪。还记出关来，恰而今时节。 将发。画楼芳酒，红泪清歌，顿成轻别。回首经年，杳杳音尘都绝。欲知方寸，共有几许新愁？芭蕉不展丁香结。枉望断天涯，两厌厌风月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1445, "title": "望湘人", "author": "贺铸", "body": "厌莺声到枕，花气动帘，醉魂愁梦相半。被惜余薰，带惊剩眼①。几许伤春春晚。泪竹②痕鲜，佩兰③香老，湘天浓暖。记小江风月佳时，屡约非烟④游伴。 须信鸾弦⑤易断。奈云和⑥再鼓，曲终人远。认罗袜无踪，旧处弄波清浅。青翰棹舣，白苹洲畔。尽目临皋飞观。不解寄、一字相思，幸有归来双燕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1446, "title": "画眉郎 （好女儿）", "author": "贺铸", "body": "雪絮雕章，梅粉华妆。小芒台①、榧机罗缃素②，古铜蟾砚滴，金雕琴荐，玉燕钗梁。 五马徘徊长路，漫非意，凤求凰。认兰情、自有怜才处，似题桥贵客，栽花潘令，真画眉郎③。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1447, "title": "南柯子 忆旧", "author": "仲殊", "body": "十里青山远，潮平路带沙。数声啼鸟怨年华，又是凄凉时候在天涯。 白露收残月，清风散晓霞。绿杨堤畔问荷花：记得年时沽酒那人家？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1448, "title": "诉衷情 宝月山作", "author": "仲殊", "body": "清波门外拥轻衣，杨花相送飞。西湖又还春晚，水树乱莺啼。 闲院宇，小帘帏。晚初归。钟声已过，篆香才点，月到门时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1449, "title": "诉衷情 寒食", "author": "仲殊", "body": "涌金门外小瀛洲，寒食更风流。红船满湖歌吹，花外有高楼。 晴日暖，淡烟浮，恣嬉游。三千粉黛，十二阑干，一片云头。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1450, "title": "八声甘州", "author": "晁补之", "body": "扬州次韵和东坡钱塘作\n谓东坡、未老赋归来，天未遣公归。向西湖两处，秋波一种，飞霭澄辉。又拥竹西歌吹，僧老木兰非。一笑千秋事，浮世危机。 应倚平山栏槛，是醉翁饮处，江雨霏霏。送孤鸿相接，今古眼中稀。念平生、相从江海，任飘蓬、不遣此心违。登临事，更何须惜，吹帽淋衣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1451, "title": "摸鱼儿 东皋寓居", "author": "晁补之", "body": "买陂塘、旋栽杨柳，依稀淮岸湘浦。东皋嘉雨新痕涨，沙嘴鹭来鸥聚。堪爱处，最好是、一川夜月光流渚。无人独舞。任翠幄张天，柔茵藉地，酒尽未能去。 青绫被①，莫忆金闺②故步。儒冠曾把身误。弓刀千骑成何事？荒了邵平瓜圃③。君试觑，满青镜、星星鬓影今如许！功名浪语。便似得班超④，封侯万里，归计恐迟暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1452, "title": "水龙吟", "author": "晁补之", "body": "次韵林圣予惜春\n问春何苦匆匆，带风伴雨如驰骤。幽葩细萼，小园低槛，壅培未就。吹尽繁红，占春长久，不如垂柳。算春常不老，人愁春老，愁只是、人间有。 春恨十常八九，忍轻辜、芳醪经口。那知自是，桃花结子，不因春瘦。世上功名，老来风味，春归时候。纵樽前痛饮，狂歌似旧，情难依旧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1453, "title": "迷神引", "author": "晁补之", "body": "贬玉溪，对江山作\n黯黯青山红日暮，浩浩大江东注。余霞散绮，向烟波路。使人愁，长安远，在何处。几点渔灯小，迷近坞。一片客帆低，傍前浦。 暗想平生，自悔儒冠误。觉阮途穷，归心阻。断魂素月，一千里、伤平楚。怪竹枝歌，声声怨，为谁苦。猿鸟一时啼，惊岛屿。烛暗不成眠，听津鼓。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1454, "title": "临江仙 信州作", "author": "晁补之", "body": "谪宦江城无屋买，残僧野寺相依。松间药臼竹间衣。水穷行到处，云起坐看时。 一个幽禽缘底事，苦来醉耳边啼？月斜西院愈声悲。青山无限好，犹道不如归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1455, "title": "洞仙歌 泗州中秋作", "author": "晁补之", "body": "青烟幂处，碧海飞金镜。永夜闲阶卧桂影。露凉时，零乱多少寒螀，神京远，惟有蓝桥路近。 水晶帘不下，云母屏开，冷浸佳人淡脂粉。待都将许多明，付与金尊，投晓共流霞倾尽。更携取胡床上南楼，看玉做人间，素秋千顷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1456, "title": "临江仙", "author": "晁补之", "body": "绿暗汀州三月暮，落花风静帆收。垂杨低映木兰舟。半篙春水滑，一段夕阳愁。 灞水桥东回首处，美人新上帘钩。青鸾无计入红楼。行云归楚峡，飞梦到扬州。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1457, "title": "风流子", "author": "张耒", "body": "木叶亭皋下，重阳近，又是捣衣秋。奈愁入庾肠，老侵潘鬓，谩簪黄菊，花也应羞。楚天晚，白蘋烟尽处，红蓼水边头。芳草有情，夕阳无语，雁横南浦，人倚西楼。 玉容知安否？香笺共锦字，两处悠悠。空恨碧云离合，青鸟沉浮。向风前懊恼，芳心一点，寸眉两叶，禁甚闲愁。情到不堪言处，分付东流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1458, "title": "秋蕊香", "author": "张耒", "body": "帘幕疏疏风透，一线香飘金兽。朱栏倚遍黄昏后，廊上月华如昼。 别离滋味浓于酒，著人瘦。此情不及墙东柳，春色年年如旧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1459, "title": "瑞龙吟", "author": "周邦彦", "body": "章台路，还见褪粉梅梢，试花桃树。愔愔坊陌人家，定巢燕子，归来旧处。 黯凝竚。因念个人痴小，乍窥门户。侵晨浅约宫黄，障风映袖，盈盈笑语。 前度刘郎重到，访邻寻里，同时歌舞，唯有旧家秋娘，声价如故。吟笺赋笔，犹记燕台句。知谁伴、名园露饮，东城闲步？事与孤鸿去。探春尽是，伤离意绪。官柳低金缕。归骑晚，纤纤池塘飞雨。断肠院落，一帘风絮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1460, "title": "琐窗寒", "author": "周邦彦", "body": "暗柳啼鸦，单衣竚立，小帘朱户。桐花半亩，静锁一庭愁雨。洒空阶、夜阑未休，故人剪烛西窗语。似楚江瞑宿，风灯零乱①，少年羁旅。 迟暮，嬉游处，正店舍无烟，禁城百五②。旗亭③唤酒，付与高阳俦侣④。想东园、桃李自春，小唇秀靥⑤今在否？到归时、定有残英，待客携尊俎。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1461, "title": "风流子", "author": "周邦彦", "body": "新绿小池塘，风帘动、碎影舞斜阳。羡金屋去来，旧时巢燕；土花缭绕，前度莓墙。绣阁里，凤帏深几许，听得理丝簧。欲说又休，虑乖芳信；未歌先咽，愁近清觞。 遥知新妆了，开朱户，应自待月西厢。最苦梦魂，今宵不到伊行。问甚时说与，佳音密耗，寄将秦镜，偷换韩香？天便教人，霎时厮见何妨！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1462, "title": "渡江云", "author": "周邦彦", "body": "晴岚低楚甸，暖回雁翼，阵势起平沙。骤惊春在眼，借问何时，委曲到山家。涂香晕色，盛粉饰、争作妍华。千万丝、陌头杨柳，渐渐可藏鸦。 堪嗟。清江东注，画舸西流，指长安日下。愁宴阑、风翻旗尾，潮溅乌纱。今宵正对初弦月，傍水驿、深舣蒹葭。沈恨处，时时自剔灯花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1463, "title": "应天长", "author": "周邦彦", "body": "条风布暖，霏雾弄晴，池塘遍满春色。正是夜堂无月，沉沉暗寒食。梁间燕，前社客。似笑我、闭门愁寂。乱花过，隔院芸香，满地狼藉。 长记那回时，邂逅相逢，郊外驻油壁。又见汉宫传烛，飞烟五侯宅。青青草，迷路陌。强载酒、细寻前迹。市桥远，柳下人家，犹自相识。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1464, "title": "还京乐", "author": "周邦彦", "body": "禁烟近，触处浮香秀色相料理。正泥花时候，奈何客里，光阴虚费。望箭波无际。迎风漾日黄云委。任去远，中有万点相思清泪。 到长淮底。过当时楼下，殷勤为说，春来羁旅况味。堪嗟误约乖期，向天涯、自看桃李。想而今、应恨墨盈笺，愁妆照水。怎得青鸾翼，飞归教见憔悴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1465, "title": "解连环", "author": "周邦彦", "body": "怨怀无托。嗟情人断绝，信音辽邈。纵妙手、能解连环，似风散雨收，雾轻云薄。燕子楼空，暗尘锁、一床弦索。想移根换叶，尽是旧时，手种红药。 汀洲渐生杜若。料舟移岸曲，人在天角。谩记得、当日音书，把闲语闲言，待总烧却。水驿春回，望寄我、江南梅萼。拚今生，对花对酒，为伊泪落。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1466, "title": "满江红", "author": "周邦彦", "body": "昼日移阴，揽衣起，春帷睡足。临宝鉴，绿云撩乱，未忺妆束。蝶粉蜂黄都褪了，枕痕一线红生玉。背画栏、脉脉悄无言，寻棋局。 重会面，犹未卜。无限事，萦心曲。想秦筝依旧，尚鸣金屋。芳草连天迷远望，宝香薰被成孤宿。最苦是、蝴蝶满园飞，无心扑。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1467, "title": "瑞鹤仙", "author": "周邦彦", "body": "悄郊原带郭，行路永，客去车尘漠漠。斜阳映山落，敛馀红犹恋，孤城阑角。凌波步弱，过短亭、何用素约。有流莺劝我，重解绣鞍，缓引春酌。 不记归时早暮，上马谁扶，醒眠朱阁。惊飙动幕，扶残醉，绕红药。叹西园已是花深无地，东风何事又恶？任流光过却，犹喜洞天自乐。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1468, "title": "西平乐", "author": "周邦彦", "body": "元丰初，予以布衣西上，过天长道中。后四十馀年，辛丑正月二十六日，避贼复游故地。感叹岁月，偶成此词。\n稚柳苏晴，故溪歇雨，川迥未觉春赊。驼褐寒侵，正怜初日，轻阴抵死须遮。叹事与孤鸿尽去，身与塘蒲共晚，争知向此，征途迢递，伫立尘沙。念朱颜翠发，曾到处，故地使人嗟。 道连三楚，天低四野，乔木依前，临路攲斜。重慕想、东陵晦迹，彭泽归来，左右琴书自乐，松菊相依，何况风流鬓未华。多谢故人，亲驰郑驿，时倒融尊，劝此淹留，共过芳时，翻令倦客思家。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1469, "title": "浪淘沙慢", "author": "周邦彦", "body": "晓阴重，霜凋岸草，雾隐城堞。南陌脂车待发，东门帐饮乍阕。正拂面垂杨堪揽结。掩红泪、玉手亲折。念汉浦离鸿去何许，经时信音绝。 情切。望中地远天阔。向露冷风清无人处，耿耿寒漏咽。嗟万事难忘，唯是轻别。翠樽未竭，凭断云、留取西楼残月。 罗带光销纹衾叠，连环解，旧香顿歇。怨歌永、琼壶敲尽缺。恨春去、不与人期，弄夜色，空馀满地梨花雪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1470, "title": "忆旧游", "author": "周邦彦", "body": "记愁横浅黛，泪洗红铅，门掩秋宵。坠叶惊离思，听寒螀夜泣，乱雨潇潇。凤钗半脱云鬓，窗影烛光摇。渐暗竹敲凉，疏萤照晚，两地魂消。 迢迢。问音信，道径底花阴，时认鸣镳。也拟临朱户，叹因郎憔悴，羞见郎招。旧巢更有新燕，杨柳拂河桥。但满目京尘，东风竟日吹露桃。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1471, "title": "少年游", "author": "周邦彦", "body": "朝云漠漠散轻丝，楼阁淡春姿。柳泣花啼，九街泥重，门外燕飞迟。 而今丽日明金屋，春色在桃枝。不似当时，小楼冲雨，幽恨两人知。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1472, "title": "渔家傲", "author": "周邦彦", "body": "灰暖香融销永昼。蒲萄架上春藤秀。曲角栏干群雀斗。清明后。风梳万缕亭前柳。 日照钗梁光欲溜。循阶竹粉沾衣袖。拂拂面红如著酒。沉吟久。昨宵正是来时候。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1473, "title": "望江南", "author": "周邦彦", "body": "游妓散，独自绕回堤。芳草怀烟迷水曲，密云衔雨暗城西。九陌未沾泥。 桃李下，春晚未成蹊。墙外见花寻路转，柳阴行马过莺啼。无处不凄凄。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1474, "title": "浣溪沙", "author": "周邦彦", "body": "雨过残红湿未飞，疏篱一带透斜晖。游蜂酿蜜窃香归。\n金屋无人风竹乱，衣篝尽日水沉微。一春须有忆人时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1475, "title": "浣溪沙", "author": "周邦彦", "body": "楼上晴天碧四垂，楼前芳草接天涯。劝君莫上最高梯。\n新笋已成堂下竹，落花都上燕巢泥。忍听林表杜鹃啼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1476, "title": "一落索", "author": "周邦彦", "body": "眉共春山争秀，可怜长皱。莫将清泪滴花枝，恐花也、如人瘦。 清润玉箫闲久，知音稀有。欲知日日倚栏愁，但问取、亭前柳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1477, "title": "满庭芳", "author": "周邦彦", "body": "夏日溧水无想山作\n风老莺雏，雨肥梅子，午阴嘉树清圆。地卑山近，衣润费炉烟。人静乌鸢自乐，小桥外、新绿溅溅。凭栏久，黄芦苦竹，疑泛九江船。 年年，如社燕，飘流瀚海，来寄修椽。且莫思身外，长近尊前。憔悴江南倦客，不堪听急管繁弦。歌筵畔，先安簟枕，容我醉时眠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1478, "title": "隔浦莲近拍", "author": "周邦彦", "body": "中山县圃姑射亭避暑作\n新篁摇动翠葆。曲径通深窈。夏果收新脆，金丸落，惊飞鸟。浓翠迷岸草。蛙声闹，骤雨鸣池沼。 水亭小。浮萍破处，帘花檐影颠倒。纶巾羽扇，困卧北窗清晓。屏里吴山梦自到。惊觉，依然身在江表。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1479, "title": "过秦楼", "author": "周邦彦", "body": "水浴清蟾，叶喧凉吹，巷陌马声初断。闲依露井，笑扑流萤，惹破画罗轻扇。人静夜久凭阑，愁不归眠，立残更箭。叹年华一瞬，人今千里，梦沉书远。 空见说、鬓怯琼梳，容销金镜，渐懒趁时匀染。梅风地溽，虹雨苔滋，一架舞红都变。谁信无聊为伊，才减江淹，情伤荀倩。但明河影下，还看稀星数点。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1480, "title": "苏幕遮", "author": "周邦彦", "body": "燎沈香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。 故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1481, "title": "诉衷情", "author": "周邦彦", "body": "出林杏子落金盘。齿软怕尝酸。可惜半残青紫，犹印小唇丹。 南陌上，落花闲。雨斑斑。不言不语，一段伤春，都在眉间。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1482, "title": "风流子", "author": "周邦彦", "body": "枫林凋晚叶，关河迥，楚客惨将归。望一川暝霭，雁声哀怨；半规凉月，人影参差。酒醒后，泪花销凤蜡，风幕卷金泥。砧杵韵高，唤回残梦；绮罗香减，牵起馀悲。 亭皋分襟地，难拚处，偏是掩面牵衣。何况怨怀长结，重见无期。想寄恨书中，银钩空满；断肠声里，玉筯还垂。多少暗愁密意，唯有天知。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1483, "title": "齐天乐", "author": "周邦彦", "body": "绿芜凋尽台城路，殊乡又逢秋晚。暮雨生寒，鸣蛩劝织，深阁时闻裁剪。云窗静掩。叹重拂罗裀，顿疏花簟。尚有綀囊，露萤清夜照书卷。 荆江留滞最久，故人相望处，离思何限。渭水西风，长安乱叶，空忆诗情宛转。凭高眺远。正玉液新篘，蟹螯初荐。醉倒山翁，但愁斜照敛。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1484, "title": "四园竹", "author": "周邦彦", "body": "浮云护月，未放满朱扉。鼠摇暗壁，萤度破窗，偷入书帏。秋意浓，闲伫立，庭柯影里。好风襟袖先知。 夜何其。江南路绕重山，心知谩与前期。奈向灯前堕泪。肠断萧娘，旧日书辞。犹在纸。雁信绝，清宵梦又稀。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1485, "title": "氐州第一", "author": "周邦彦", "body": "波落寒汀，村渡向晚，遥看数点帆小。乱叶翻鸦，惊风破雁，天角孤云缥缈。官柳萧疏，甚尚挂、微微残照？景物关情，川途换目，顿来催老。 渐解狂朋欢意少，奈犹被、思牵情绕。座上琴心，机中锦字，觉最萦怀抱。也知人、悬望久，蔷薇谢，归来一笑。欲梦高唐，未成眠、霜空已晓。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1486, "title": "少年游", "author": "周邦彦", "body": "并刀如水，吴盐胜雪，纤手破新橙。锦幄初温，兽烟不断，相对坐调笙。 低声问：向谁行宿？城上已三更。马滑霜浓，不如休去，直是少人行。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1487, "title": "庆春宫", "author": "周邦彦", "body": "云接平岗，山围寒野，路回渐转孤城。衰柳啼鸦，惊风驱雁，动人一片秋声。倦途休驾，淡烟里、微茫见星。尘埃憔悴，生怕黄昏，离思牵萦。 华堂旧日逢迎。花艳参差，香雾飘零。弦管当头，偏怜娇凤，夜深簧暖笙清。眼波传意，恨密约、匆匆未成。许多烦恼，只为当时，一饷留情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1488, "title": "醉桃源", "author": "周邦彦", "body": "冬衣初染远山青，双丝云雁绫。夜寒袖湿欲成冰，都缘珠泪零。 情黯黯，闷腾腾，身如秋后蝇。若教随马逐郎行，不辞多少程。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1489, "title": "夜游宫", "author": "周邦彦", "body": "叶下斜阳照水，卷轻浪、沈沈千里。桥上酸风射眸子。立多时，看黄昏，灯火市。 古屋寒窗底，听几片、井桐飞坠。不恋单衾再三起。有谁知，为萧娘，书一纸。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1490, "title": "解语花 上元", "author": "周邦彦", "body": "风销绛蜡，露浥红莲，花市光相射。桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女、纤腰一把。箫鼓喧，人影参差，满路飘香麝。 因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处，自有暗尘随马。年光是也。唯只见、旧情衰谢。清漏移，飞盖归来，从舞休歌罢。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1491, "title": "大酺 春雨", "author": "周邦彦", "body": "对宿烟收，春禽静，飞雨时鸣高屋。墙头青玉斾，洗铅霜都尽，嫩梢相触。润逼琴丝，寒侵枕障，虫网吹粘帘竹。邮亭无人处，听檐声不断，困眠初熟。奈愁极频惊，梦轻难记，自怜幽独。 行人归意速。最先念、流潦妨车毂。怎奈向、兰成憔悴，卫玠清羸，等闲时、易伤心目。未怪平阳客，双泪落、笛中哀曲。况萧索、青芜国。红糁铺地，门外荆桃如菽。夜游共谁秉烛？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1492, "title": "花犯梅花", "author": "周邦彦", "body": "粉墙低，梅花照眼，依然旧风味。露痕轻缀。疑净洗铅华，无限佳丽。去年胜赏曾孤倚。冰盘同燕喜。更可惜、雪中高树，香篝熏素被。 今年对花最匆匆，相逢似有恨，依依愁悴。吟望久，青苔上、旋看飞坠。相将见、脆丸荐酒，人正在、空江烟浪里。但梦想、一枝潇洒，黄昏斜照水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1493, "title": "水龙吟 梨花", "author": "周邦彦", "body": "素肌应怯馀寒，艳阳占立青芜地。樊川照日，灵关遮路，残红敛避。传火楼台，妒花风雨，长门深闭。亚帘栊半湿，一枝在手，偏勾引、黄昏泪。 别有风前月底。布繁英，满园歌吹。朱铅退尽，潘妃却酒，昭君乍起。雪浪翻空，粉裳缟夜，不成春意。恨玉容不见，琼英谩好，与何人比？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1494, "title": "六丑① 蔷薇谢后作", "author": "周邦彦", "body": "正单衣试酒，怅客里光阴虚掷。愿春暂留，春归如过翼②，一去无迹。为问花何在？夜来风雨，葬楚宫倾国③。钗钿堕处遗香泽。乱点桃蹊④，轻翻柳陌，多情为谁追惜？但蜂媒蝶使，时叩窗槅⑤。 东园岑寂，渐蒙笼暗碧。静绕珍丛⑥底，成叹息。长条故惹行客。似牵衣待话，别情无极。残英小，强簪巾帻；终不似、一朵钗头颤袅⑦，向人欹侧⑧。漂流处，莫趁潮汐。恐断红⑨尚有相思字，何由见得。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1495, "title": "虞美人", "author": "周邦彦", "body": "廉纤小雨池塘遍。细点看萍面。一双燕子守朱门，比似寻常时候易黄昏。 宜城酒泛浮香絮，细作更阑语。相将羁思乱如云，又是一窗灯影两愁人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1496, "title": "兰陵王 柳", "author": "周邦彦", "body": "柳阴直，烟里丝丝弄碧。隋堤上、曾见几番，拂水飘绵送行色。登临望故国，谁识京华倦客？长亭路，年去岁来，应折柔条过千尺。 闲寻旧踪迹，又酒趁哀弦，灯照离席。梨花榆火催寒食。愁一箭风快，半篙波暖，回头迢递便数驿，望人在天北。凄恻，恨堆积！渐别浦萦回，津堠岑寂，斜阳冉冉春无极。念月榭携手，露桥闻笛。沉思前事，似梦里，泪暗滴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1497, "title": "西河 金陵", "author": "周邦彦", "body": "佳丽地，南朝盛事谁记？山围故国绕清江，髻鬟对起；怒涛寂寞打孤城，风樯遥度天际。 断崖树，犹倒倚；莫愁艇子曾系。空余旧迹郁苍苍，雾沉半垒。夜深月过女墙来，伤心东望淮水。 酒旗戏鼓甚处市？想依稀、王谢邻里。燕子不知何世；入寻常巷陌人家，相对如说兴亡，斜阳里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1498, "title": "拜星月慢", "author": "周邦彦", "body": "夜色催更，清尘收露，小曲幽坊月暗。竹槛灯窗，识秋娘庭院。笑相遇，似觉琼枝玉树相倚，暖日明霞光烂。水盼兰情，总平生稀见。 画图中、旧识春风面。谁知道、自到瑶台畔。眷恋雨润云温，苦惊风吹散。念荒寒、寄宿无人馆。重门闭、败壁秋虫叹。怎奈向、一缕相思，隔溪山不断。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1499, "title": "尉迟杯 离恨", "author": "周邦彦", "body": "隋堤路。渐日晚、密霭生深树。阴阴淡月笼沙，还宿河桥深处。无情画舸，都不管、烟波隔前浦。等行人、醉拥重衾，载将离恨归去。 因思旧客京华，长偎傍疏林，小槛欢聚。冶叶倡条俱相识，仍惯见、珠歌翠舞。如今向、渔村水驿，夜如岁、焚香独自语。有何人、念我无聊，梦魂凝想鸳侣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1500, "title": "蝶恋花", "author": "周邦彦", "body": "月皎惊乌栖不定，更漏将残，辘轳牵金井。唤起两眸清炯炯。泪花落枕红绵冷。 执手霜风吹鬓影。去意徊徨，别语愁难听。楼上阑干横斗柄，露寒人远鸡相应。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1501, "title": "点绛唇 伤感", "author": "周邦彦", "body": "辽鹤归来，故乡多少伤心地。寸书不寄，鱼浪空千里。\n凭仗桃根，说与凄凉意。愁无际。旧时衣袂，犹有东门泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1502, "title": "玉楼春", "author": "周邦彦", "body": "桃溪不作从容住，秋藕绝来无续处。当时相候赤阑桥，今日独寻黄叶路。 烟中列岫青无数，雁背夕阳红欲暮。人如风后入江云，情似雨馀粘地絮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1503, "title": "夜飞鹊", "author": "周邦彦", "body": "河桥送人处，良夜何其？斜月远堕余辉。铜盘烛泪已流尽，霏霏凉露沾衣。相将散离会，探风前津鼓，树杪参旗。花骢会意，纵扬鞭、亦自行迟。 迢递路回清野，人语渐无闻，空带愁归。何意重经前地，遗钿不见，斜径都迷。兔葵燕麦，向斜阳、影与人齐。但徘徊班草，欷歔酹酒，极望天西。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1504, "title": "芳草渡", "author": "周邦彦", "body": "昨夜里，又再宿桃源，醉邀仙侣。听碧窗风快，珠帘半卷疏雨。多少离恨苦。方留连啼诉。凤帐晓，又是匆匆，独自归去。 愁顾。满怀泪粉，瘦马冲泥寻去路。谩回首、烟迷望眼，依稀见朱户。似痴似醉，暗恼损、凭阑情绪。淡暮色，看尽栖鸦乱舞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1505, "title": "虞美人", "author": "周邦彦", "body": "灯前欲去仍留恋。肠断朱扉远。未须红雨洗香腮。待得蔷薇花谢便归来。 舞腰歌板闲时按。一任旁人看。金炉应见旧残煤。莫使恩情容易似寒灰。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1506, "title": "长相思慢", "author": "周邦彦", "body": "夜色澄明，天街如水，风力微冷帘旌。幽期再偶，坐久相看，才喜欲叹还惊。醉眼重醒。映雕阑修竹，共数流萤。细语轻轻。尽银台、挂蜡潜听。 自初识伊①来，便惜妖娆，艳质美盼柔情。桃溪换世，鸾驭凌空，有愿须成。游丝荡絮，任轻狂、相逐牵萦。但连环不解，流水长东，难负深盟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1507, "title": "关河令", "author": "周邦彦", "body": "秋阴时晴渐向暝。变一庭凄冷。伫听寒声，云深无雁影。 更深人去寂静。但照壁孤灯相映。酒已都醒，如何消夜永！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1508, "title": "虞美人", "author": "李廌", "body": "玉阑干外清江浦，渺渺天涯雨。好风如扇雨如帘，时见岸花汀草涨痕添。 青林枕上关山路，卧想乘鸾处。碧芜千里思悠悠，惟有霎时凉梦到南州。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1509, "title": "洞仙歌", "author": "阮阅", "body": "赠宜春官妓赵佛奴\n赵家姊妹，合在昭阳殿。因甚人间有飞燕？见伊底，尽道独步江南，便江北、也何曾惯见。 惜伊情性好，不解嗔人，长带桃花笑时脸。向尊前酒底，得见些时，似恁地、能得几回细看？待不眨眼儿觑着伊，将眨眼底工夫，剩看几遍。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1510, "title": "眼儿媚", "author": "阮阅", "body": "楼上黄昏杏花寒，斜月小栏干。一双燕子，两行征雁，画角声残。 绮窗人在东风里，无语对春闲。也应似旧，盈盈秋水，淡淡春山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1511, "title": "感皇恩 别情", "author": "赵企", "body": "骑马踏红尘，长安重到。人面依然似花好。旧欢才展，又被新愁分了。未成云雨梦，巫山晓。 千里断肠，关山古道。回首高城似天杳。满怀离恨，付与落花啼鸟。故人何处也？青春老。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1512, "title": "蝶恋花", "author": "谢逸", "body": "豆蔻梢头春色浅。新试纱衣，拂袖东风软。红日三竿帘幕卷，画楼影里双飞燕。 拢鬓步摇青玉碾。缺样花枝，叶叶蜂儿颤。独倚阑干凝望远，一川烟草平如剪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1513, "title": "菩萨蛮", "author": "谢逸", "body": "暄风迟日春光闹，葡萄水绿摇轻棹。两岸草烟低，青山啼子规。 归来愁未寝，黛浅眉痕沁。花影转廊腰，红添酒面潮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1514, "title": "江神子", "author": "谢逸", "body": "杏花村馆酒旗风。水溶溶，飏残红。野渡舟横，杨柳绿阴浓。望断江南山色远，人不见，草连空。 夕阳楼外晚烟笼。粉香融，淡眉峰。记得年时，相见画屏中。只有关山今夜月，千里外，素光同。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1515, "title": "卜算子", "author": "谢逸", "body": "烟雨幂横塘，绀色涵清浅。谁把并州快剪刀，剪取吴江半。\n隐几岸乌巾，细葛含风软。不见柴桑避俗翁，心共孤云远。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1516, "title": "临江仙", "author": "晁冲之", "body": "忆昔西池池上饮，年年多少欢娱。别来不寄一行书。寻常相见了，犹道不如初。 安稳锦屏今夜梦，月明好渡江湖。相思休问定何如。情知春去后，管得落花无？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1517, "title": "汉宫春 梅", "author": "晁冲之", "body": "潇洒江梅，向竹梢稀处，横两三枝。东君也不爱惜，雪压风欺。无情燕子，怕春寒、轻失花期。惟是有、南来归雁，年年长见开时。 清浅小溪如练，问玉堂何似，茅舍疏篱？伤心故人去后，冷落新诗。微云淡月，对孤芳、分付他谁。空自倚、清香未减，风流不在人知。\n汉宫春（潇洒江梅） 晁冲之\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1518, "title": "鹧鸪天", "author": "苏庠", "body": "枫落河梁野水秋，澹烟衰草接郊丘。醉眠小坞黄茅店，梦倚高城赤叶楼。 天杳杳，路悠悠。钿筝歌扇等闲休。灞桥杨柳年年恨，鸳浦芙蓉叶叶愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1519, "title": "菩萨蛮 宜兴作", "author": "苏庠", "body": "北风振野云平屋，寒溪淅淅流冰谷。落日送归鸿，夕岚千万重。 荒陂垂斗柄，直北乡山近。何必苦言归，石亭春满枝。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1520, "title": "摊声浣溪沙", "author": "毛滂", "body": "天雨新晴，孙使君宴客双石堂，遣官奴试小龙茶\n日照门前千万峰，晴飙先扫冻云空。谁作素涛翻玉手，小团龙。 定国精明过少壮，次公烦碎本雍容。听讼阴中苔自绿，舞衣红。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1521, "title": "惜分飞", "author": "毛滂", "body": "富阳僧舍作别语赠妓琼芳\n泪湿阑干花著露，愁到眉峰碧聚。此恨平分取，更无言语空相觑。 断雨残云无意绪，寂寞朝朝暮暮。今夜山深处，断魂分付潮回去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1522, "title": "烛影摇红", "author": "毛滂", "body": "松窗午梦初觉\n一亩清阴，半天潇洒松窗午。床头秋色小屏山，碧帐垂烟缕。 枕畔风摇绿户，唤人醒，不教梦去。可怜恰到，瘦石寒泉，冷云幽处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1523, "title": "临江仙 都城元夕", "author": "毛滂", "body": "闻道长安灯夜好，雕轮宝马如云。蓬莱清浅对觚棱。玉皇开碧落，银界失黄昏。 谁见江南憔悴客，端忧懒步芳尘。小屏风畔冷香凝。酒浓春入梦，窗破月寻人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1524, "title": "黄金缕", "author": "司马槱", "body": "妾本钱塘江上住。花落花开，不管流年度。燕子衔将春色去，纱窗几阵黄梅雨。 斜插犀梳云半吐，檀板轻敲，唱彻黄金缕。望断行云无觅处，梦回明月生南浦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1525, "title": "鹊桥仙", "author": "谢薖", "body": "月胧星淡，南飞乌鹊，暗数秋期天上。锦楼不到野人家，但门外清流叠嶂。 一杯相属，佳人何在？不见绕梁清唱。人间平地亦崎岖，叹银汉何曾风浪！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1526, "title": "青玉案", "author": "惠洪", "body": "绿槐烟柳长亭路，恨取次、分离去。日永如年愁难度。高城回首，暮云遮尽，目断人何处。 解鞍旅舍天将暮，暗忆叮咛千万句。一寸柔肠情几许？薄衾孤枕，梦回人静，彻晓潇潇雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1527, "title": "忆君王", "author": "谢克家", "body": "依依宫柳拂宫墙，楼殿无人春昼长。燕子归来依旧忙。忆君王，月破黄昏人断肠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1528, "title": "卜算子 春情", "author": "秦湛", "body": "春透水波明，寒峭花枝瘦。极目天涯百尺楼，人在楼中否？ 四和袅金凫，双陆思纤手。拟倩东风浣此情，情更浓于酒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1529, "title": "卜算子", "author": "徐俯", "body": "天生百种愁，挂在斜阳树。绿叶阴阴自得春，草满莺啼处。 不见凌波步，空忆如簧语。柳外重重叠叠山，遮不断、愁来路。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1530, "title": "点绛唇", "author": "王安中", "body": "岘首亭空，劝君休堕羊碑泪。宦游如寄，且伴山翁醉。\n说与鲛人，莫解江皋珮。将归思，晕红萦翠，细织回文字。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1531, "title": "贺新郎", "author": "叶梦得", "body": "睡起流莺语。掩苍苔、房栊向晚，乱红无数。吹尽残花无人见，惟有垂杨自舞。渐暖霭、初回轻暑。宝扇重寻明月影，暗尘侵、上有乘鸾女。惊旧恨，遽如许。 江南梦断横江渚。浪粘天、葡萄涨绿，半空烟雨。无限楼前沧波意，谁采蘋花寄与。但怅望、兰舟容与。万里云帆何时到，送孤鸿、目断千山阻。谁为我，唱金缕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1532, "title": "水调歌头", "author": "叶梦得", "body": "九月望日，与客习射西园，余病不能射\n霜降碧天静，秋事促西风。寒声隐地初听，中夜入梧桐。起瞰高城回望，寥落关河千里，一醉与君同。叠鼓闹清晓，飞骑引雕弓。 岁将晚，客争笑，问衰翁：平生豪气安在？走马为谁雄？何似当筵虎士，挥手弦声响处，双雁落遥空。老矣真堪愧，回首望云中。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1533, "title": "水调歌头", "author": "叶梦得", "body": "秋色渐将晚，霜信报黄花。小窗低户深映，微路绕攲斜。为问山翁何事，坐看流年轻度，拚却鬓双华。徙倚望沧海，天净水明霞。 念平昔，空飘荡，遍天涯。归来三径重扫，松竹本吾家。却恨悲风时起，冉冉云间新雁，边马怨胡笳。谁似东山老，谈笑静胡沙！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1534, "title": "八声甘州", "author": "叶梦得", "body": "寿阳楼八公山作\n故都迷岸草，望长淮、依然绕孤城。想乌衣年少，芝兰秀发，戈戟云横。坐看骄兵南渡，沸浪骇奔鲸。转盼东流水，一顾功成。 千载八公山下，尚断崖草木，遥拥峥嵘。漫云涛吞吐，无处问豪英。信劳生、空成今古，笑我来、何事怆遗情①。东山老②，可堪岁晚，独听桓筝③。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1535, "title": "念奴娇", "author": "叶梦得", "body": "云峰横起，障吴关三面，真成尤物。倒卷回潮，目尽处、秋水粘天无壁。绿鬓人归，如今虽在，空有千茎雪。追寻如梦，漫馀诗句犹杰。 闻道尊酒登临，孙郎终古恨，长歌时发。万里云屯，瓜步晚、落日旌旗明灭。鼓吹风高，画船遥想，一笑吞穷发。当时曾照，更谁重问山月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1536, "title": "临江仙", "author": "叶梦得", "body": "与客湖上饮归\n不见跳鱼翻曲港，湖边特地经过。萧萧疏雨乱风荷。微云吹散，凉月堕平波。 白酒一杯还径醉，归来散发婆娑。无人能唱采莲歌。小轩倚枕，檐影挂星河。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1537, "title": "虞美人", "author": "叶梦得", "body": "雨后同干誉、才卿置酒来禽花下作\n落花已作风前舞，又送黄昏雨。晓来庭院半残红，惟有游丝千丈罥晴空。 殷勤花下同携手，更尽杯中酒。美人不用敛蛾眉，我亦多情无奈酒阑时。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1538, "title": "点绛唇", "author": "叶梦得", "body": "绍兴乙卯登绝顶小亭\n缥缈危亭，笑谈独在千峰上。与谁同赏，万里横烟浪。\n老去情怀，犹作天涯想。空惆怅。少年豪放，莫学衰翁样。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1539, "title": "喜迁莺 晓行", "author": "刘一止", "body": "晓光催角。听宿鸟未惊，邻鸡先觉。迤逦烟村，马嘶人起，残月尚穿林薄。泪痕带霜微凝，酒力冲寒犹弱。叹倦客、悄①不禁重染，风尘京洛。 追念人别后，心事万重，难觅孤鸿托。翠幌娇深，曲屏香暖，争念岁寒飘泊。怨月恨花烦恼，不是不曾经著。这情味，望一成②消减，新来还恶。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1540, "title": "点绛唇", "author": "汪藻", "body": "新月娟娟，夜寒江静山衔斗。起来搔首，梅影横窗瘦。\n好个霜天，闲却传杯手。君知否？乱鸦啼后，归兴浓于酒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1541, "title": "如梦令", "author": "曹组", "body": "门外绿阴千顷，两两黄鹂相应。睡起不胜情，行到碧梧金井。人静，人静。风动一庭花影。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1542, "title": "忆少年", "author": "曹组", "body": "年时酒伴，年时去处，年时春色。清明又近也，却天涯为客。 念过眼光阴难再得。想前欢，尽成陈迹。登临恨无语，把阑干暗拍。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1543, "title": "青玉案", "author": "曹组", "body": "碧山锦树明秋霁。路转陡，疑无地。忽有人家临曲水。竹篱茅舍，酒旗沙岸，一簇成村市。 凄凉只恐乡心起。凤楼远、回头谩凝睇。何处今宵孤馆里，一声征雁，半窗残月，总是离人泪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1544, "title": "卜算子", "author": "曹组", "body": "松竹翠萝寒，迟日江山暮。幽径无人独自芳，此恨凭谁诉？\n似共梅花语，尚有寻芳侣。着意闻时不肯香，香在无心处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1545, "title": "昭君怨", "author": "万俟咏", "body": "春到南楼雪尽，惊动灯期花信。小雨一番寒，倚栏干。\n莫把栏干频倚，一望几重烟水。何处是京华，暮云遮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1546, "title": "诉衷情", "author": "万俟咏", "body": "一鞭清晓喜还家，宿醉困流霞。夜来小雨新霁，双燕舞风斜。 山不尽，水无涯，望中赊。送春滋味，念远情怀，分付杨花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1547, "title": "长相思 （二首）", "author": "万俟咏", "body": "雨\n一声声，一更更。窗外芭蕉窗里灯，此时无限情。梦难成，恨难平。不道愁人不喜听，空阶滴到明。\n山驿\n短长亭，古今情。楼外凉蟾一晕生，雨余秋更清。暮云平，暮山横。几叶秋声和雁声，行人不要听。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1548, "title": "木兰花慢", "author": "万俟咏", "body": "恨莺花渐老，但芳草、绿汀洲。纵岫壁千寻，榆钱万叠，难买春留。梅花向来始别，又匆匆结子满枝头。门外垂杨岸侧，画桥谁系兰舟？ 悠悠。岁月如流。叹水覆、杳难收。凭画栏，往往抬头举眼，都是春愁。东风晚来更恶，怕飞红拍絮入书楼。双燕归来问我，怎生不上帘钩？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1549, "title": "南柯子 春景", "author": "田为", "body": "梦怕愁时断，春从醉里回。凄凉怀抱向谁开？些子清明时候被莺催。 柳外都成絮，栏边半是苔。多情帘燕独徘徊，依旧满身花雨又归来。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1550, "title": "南柯子 春思", "author": "田为", "body": "团玉梅梢重，香罗芰扇低。帘风不动蝶交飞。一样绿阴庭院锁斜晖。 对月怀歌扇，因风念舞衣。何须惆怅惜芳菲，拚却一生憔悴待春归！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1551, "title": "转调二郎神", "author": "徐伸", "body": "闷来弹鹊，又搅碎、一帘花影。漫试著春衫，还思纤手，熏彻金猊烬冷。动是愁端如何向，但怪得、新来多病。嗟旧日沈腰，如今潘鬓，怎堪临镜？ 重省。别时泪湿，罗衣犹凝。料为我厌厌，日高慵起，长托春酲未醒。雁足不来，马蹄难驻，门掩一庭芳景。空伫立，尽日阑干倚遍，昼长人静。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1552, "title": "临江仙", "author": "陈克", "body": "四海十年兵不解，胡尘直到江城。岁华销尽客心惊。疏髯浑如雪，衰涕欲生冰。 送老齑盐何处是？我缘应在吴兴。故人相望若为情。别愁深夜雨，孤影小窗灯。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1553, "title": "谒金门", "author": "陈克", "body": "愁脉脉，目断江南江北。烟树重重芳信隔，小楼山几尺。\n细草孤云斜日，一向①弄晴天色。帘外落花飞不得，东风无气力。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1554, "title": "菩萨蛮", "author": "陈克", "body": "赤栏桥尽香街直，笼街细柳娇无力。金碧上青空，花晴帘影红。 黄衫飞白马，日日青楼下。醉眼不逢人，午香吹暗尘。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1555, "title": "菩萨蛮", "author": "陈克", "body": "绿芜墙绕青苔院，中庭日淡芭蕉卷。蝴蝶上阶飞，烘帘自在垂。 玉钩双语燕，宝甃杨花转。几处簸钱声，绿窗春睡轻。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1556, "title": "雨中花 岭南作", "author": "朱敦儒", "body": "故国当年得意，射麋上苑，走马长楸。对葱葱佳气，赤县神州。好景何曾虚过，胜友是处相留。向伊川雪夜，洛浦花朝，占断狂游。 胡尘卷地，南走炎荒，曳裾强学应刘。空漫说、螭蟠龙卧，谁取封侯。塞雁年年北去，蛮江日日西流。此生老矣，除非春梦，重到东周。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1557, "title": "水调歌头 淮阴作", "author": "朱敦儒", "body": "当年五陵下，结客占春游。红缨翠带，谈笑跋马水西头。落日经过桃叶，不管插花归去，小袖挽人留。换酒春壶碧，脱帽醉青楼。 楚云惊，陇水散，两漂流。如今憔悴，天涯何处可销忧。长揖飞鸿旧月，不知今夕烟水，都照几人愁。有泪看芳草，无路认西州。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1558, "title": "水龙吟", "author": "朱敦儒", "body": "放船千里凌波去，略为吴山留顾。云屯水府，涛随神女，九江东注。北客翩然，壮心偏感，年华将暮。念伊、嵩旧隐①，巢、由故友②，南柯梦，遽如许！ 回首妖氛未扫，问人间、英雄何处？奇谋报国，可怜无用，尘昏白羽③。铁锁横江，锦帆冲浪，孙郎良苦④。但愁敲桂棹，悲吟《梁父》，泪流如雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1559, "title": "念奴娇", "author": "朱敦儒", "body": "插天翠柳，被何人、推上一轮明月？照我藤床凉似水，飞入瑶台琼阙。雾冷笙箫，风轻环佩，玉锁无人掣。闲云收尽，海光天影相接。 谁信有药长生，素娥新炼就，飞霜凝雪。打碎珊瑚，争似看、仙桂扶疏横绝。洗尽凡心，满身清露，冷浸萧萧发。明朝尘世，记取休向人说。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1560, "title": "念奴娇", "author": "朱敦儒", "body": "晚凉可爱，是黄昏人静，风生蘋叶。谁做秋声穿细柳？初听寒蝉凄切。旋采芙蓉，重熏沉水，暗里香交彻。拂开冰簟，小床独卧明月。 老来应免多情，还因风景好，愁肠重结。可惜良宵人不见，角枕烂衾虚设。宛转无眠，起来闲步，露草时明灭。银河西去，画楼残角呜咽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1561, "title": "临江仙", "author": "朱敦儒", "body": "堪笑一场颠倒梦，元来恰似浮云。尘劳何事最相亲。今朝忙到夜，过腊又逢春。 流水滔滔无住处，飞光忽忽西沉。世间谁是百年人。个中须著眼，认取自家身。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1562, "title": "临江仙", "author": "朱敦儒", "body": "直自凤凰城破后，擘钗破镜分飞。天涯海角信音稀。梦回辽海北，魂断玉关西。 月解重圆星解聚，如何不见人归？今春还听杜鹃啼。年年看塞雁，一十四番回。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1563, "title": "临江仙", "author": "朱敦儒", "body": "信取虚空无一物，个中著甚商量。风头紧后白云忙。风元无去住，云自没行藏。 莫听古人闲话语，终归失马亡羊。自家肠肚自端详。一齐都打碎，放出大圆光。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1564, "title": "鹧鸪天 西都作", "author": "朱敦儒", "body": "我是清都山水郎，天教分付与疏狂。曾批给雨支风券，累上留云借月章。 诗万首，酒千觞。几曾着眼看侯王？玉楼金阙慵归去，且插梅花醉洛阳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1565, "title": "鹧鸪天", "author": "朱敦儒", "body": "唱得梨园绝代声。前朝惟数李夫人。自从惊破霓裳后，楚奏吴歌扇里新。 秦嶂雁，越溪砧。西风北客两飘零。尊前忽听当时曲，侧帽停杯泪满巾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1566, "title": "感皇恩", "author": "朱敦儒", "body": "一个小园儿，两三亩地。花竹随宜旋装缀。槿篱茅舍，便有山家风味。等闲池上饮，林间醉。 都为自家，胸中无事。风景争来趁游戏。称心如意，剩活人间几岁。洞天谁道在、尘寰外。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1567, "title": "好事近", "author": "朱敦儒", "body": "春雨细如尘，楼外柳丝黄湿。风约绣帘斜去，透窗纱寒碧。 美人慵剪上元灯，弹泪倚瑶瑟。却卜紫姑香火，问辽东消息。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1568, "title": "好事近 渔父词", "author": "朱敦儒", "body": "摇首出红尘，醒醉更无时节。活计绿蓑青笠，惯披霜冲雪。\n晚来风定钓丝闲，上下是新月。千里水天一色，看孤鸿明灭。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1569, "title": "西江月", "author": "朱敦儒", "body": "世事短如春梦，人情薄似秋云。不须计较苦劳心，万事原来有命。 幸遇三杯酒好，况逢一朵花新。片时欢笑且相亲，明日阴晴未定。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1570, "title": "西江月", "author": "朱敦儒", "body": "日日深杯酒满，朝朝小圃花开。自歌自舞自开怀，且喜无拘无碍。 青史几番春梦，黄泉多少奇才。不须计较与安排，领取而今现在。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1571, "title": "减字木兰花", "author": "朱敦儒", "body": "刘郎已老，不管桃花依旧笑。要听琵琶，重院莺啼觅谢家。 曲终人醉，多似浔阳江上泪。万里东风，国破山河落照红。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1572, "title": "采桑子 彭浪矶", "author": "朱敦儒", "body": "扁舟去作江南客，旅雁孤云。万里烟尘，回首中原泪满巾。\n碧山对晚汀洲冷，枫叶芦根。日落波平，愁损辞乡去国人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1573, "title": "采桑子", "author": "朱敦儒", "body": "一番海角凄凉梦，却到长安。翠帐犀帘，依旧屏斜十二山。\n玉人为我调琴瑟，颦黛低鬟。云散香残，风雨蛮溪半夜寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1574, "title": "卜算子", "author": "朱敦儒", "body": "旅雁向南飞，风雨群相失。饥渴辛勤两翅垂，独下寒汀立。\n鸥鹭苦难亲，矰缴忧相逼。云海茫茫无处归，谁听哀鸣急！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1575, "title": "相见欢", "author": "朱敦儒", "body": "金陵城上西楼，倚清秋。万里夕阳垂地大江流。 中原乱，簪缨散，几时收？试倩悲风吹泪过扬州。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1576, "title": "浣溪沙", "author": "慕容岩卿妻", "body": "满目江山忆旧游，汀洲花草弄春柔。长亭舣住木兰舟。\n好梦易随流水去，芳心犹逐晓云愁，行人莫上望京楼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1577, "title": "鹧鸪天", "author": "周紫芝", "body": "一点残红欲尽时，乍凉秋气满屏帷。梧桐叶上三更雨，叶叶声声是别离。 调宝瑟，拨金猊。那时同唱鹧鸪词。如今风雨西楼夜，不听清歌也泪垂。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1578, "title": "醉落魄", "author": "周紫芝", "body": "江天云薄，江头雪似杨花落。寒灯不管人离索。照得人来，真个睡不著。 归期已负梅花约，又还春动空飘泊。晓寒谁看伊梳掠。雪满西楼，人在阑干角。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1579, "title": "生查子", "author": "周紫芝", "body": "春寒入翠帷，月淡云来去。院落半晴天，风撼梨花树。\n人醉掩金铺，闲倚秋千柱。满眼是相思，无说相思处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1580, "title": "踏莎行", "author": "周紫芝", "body": "情似游丝，人如飞絮。泪珠阁定空相觑。一溪烟柳万丝垂，无因系得兰舟住。 雁过斜阳，草迷烟渚。如今已是愁无数。明朝且做莫思量，如何过得今宵去？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1581, "title": "临江仙", "author": "周紫芝", "body": "送光州曾使君\n记得武陵相见日，六年往事堪惊。回头双鬓已星星。谁知江上酒，还与故人倾。 铁马红旗寒日暮，使君犹寄边城。只愁飞诏下青冥。不应霜塞晚，横槊看诗成。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1582, "title": "眼儿媚", "author": "赵佶", "body": "玉京曾忆昔繁华。万里帝王家。琼林玉殿，朝喧弦管，暮列笙琶。 花城人去今萧索，春梦绕胡沙。家山何处，忍听羌笛，吹彻梅花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1583, "title": "燕山亭 北行见杏花", "author": "赵佶", "body": "裁剪冰绡，轻叠数重，淡著胭脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少无情风雨。愁苦。问院落凄凉，几番春暮。 凭寄离恨重重，这双燕，何曾会人言语。天遥地远，万水千山，知他故宫何处。怎不思量，除梦里有时曾去。无据。和梦也新来不做。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1584, "title": "喜迁莺 晋师胜淝上", "author": "李纲", "body": "长江千里，限南北，雪浪云涛无际。天险难逾，人谋克壮，索虏岂能吞噬！阿坚百万南牧，倏忽长驱吾地。破强敌，在谢公处画，从容颐指。 奇伟！淝水上，八千戈甲，结阵当蛇豕。鞭弭周旋，旌旗麾动，坐却北军风靡。夜闻数声鸣鹤，尽道王师将至。延晋祚，庇烝民，周雅何曾专美。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1585, "title": "六幺令", "author": "李纲", "body": "次韵和贺方回金陵怀古，鄱阳席上作\n长江千里，烟淡水云阔。歌沉玉树，古寺空有疏钟发。六代兴亡如梦，苒苒惊时月。兵戈凌灭。豪华销尽，几见银蟾自圆缺。 潮落潮生波渺，江树森如发。谁念迁客归来，老大伤名节。纵使岁寒途远，此志应难夺。高楼谁设。倚阑凝望，独立渔翁满江雪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1586, "title": "点绛唇", "author": "李祁", "body": "楼下清歌，水流歌断春风暮。梦云烟树，依约江南路。\n碧水黄沙，梦到寻梅处。花无数。问花无语。明月随人去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1587, "title": "宴清都", "author": "何籀", "body": "细草沿阶软。迟日薄，惠风轻霭微暖。春工靳惜，桃英尚小，柳芽犹短。罗帏绣幕高卷，早已是歌慵笑懒。凭画楼，那更天远，山远，水远，人远！ 堪怨：傅粉疏狂，窃香俊雅，无计拘管；青丝绊马，红巾寄羽，甚处迷恋！无言泪珠零乱，翠袖尽重重渍遍；故要得别后思量，归时觑见。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1588, "title": "烛影摇红", "author": "廖世美", "body": "题安陆浮云楼\n霭霭春空，画楼森耸凌云渚。紫薇登览最关情，绝妙夸能赋。惆怅相思迟暮。记当日、朱阑共语。塞鸿难问，岸柳何穷，别愁纷絮。 催促年光，旧来流水知何处？断肠何必更残阳，极目伤平楚。晚霁波声带雨。悄无人、舟横野渡。数峰江上，芳草天涯，参差烟树。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1589, "title": "点绛唇", "author": "李清照", "body": "蹴罢秋千，起来慵整纤纤手。露浓花瘦，薄汗轻衣透。\n见客入来，袜刬金钗溜。和羞走。倚门回首，却把青梅嗅。\n易安居士三十一岁写真\n蕙风簃藏本", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1590, "title": "孤雁儿", "author": "李清照", "body": "藤床纸帐朝眠起，说不尽、无佳思。沉香断续玉炉寒，伴我情怀如水。笛声三弄，梅心惊破，多少游春意。 小风疏雨萧萧地，又催下、千行泪。吹箫人去玉楼空，肠断与谁同倚？一枝折得，人间天上，没个人堪寄。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1591, "title": "满庭芳", "author": "李清照", "body": "小阁藏春，闲窗锁昼，画堂无限深幽。篆香烧尽，日影下帘钩。手种江梅渐好，又何必、临水登楼。无人到，寂寥浑似，何逊在扬州。 从来知韵胜，难堪雨藉，不耐风揉。更谁家横笛，吹动浓愁。莫恨香消雪减，须信道、扫迹情留。难言处，良宵淡月，疏影尚风流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1592, "title": "玉楼春", "author": "李清照", "body": "红酥肯放琼苞碎，探著南枝开遍未。不知酝藉几多香，但见包藏无限意。 道人憔悴春窗底，闷损阑干愁不倚。要来小酌便来休，未必明朝风不起。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1593, "title": "清平乐", "author": "李清照", "body": "年年雪里，常插梅花醉。挼尽梅花无好意，赢得满衣清泪。 今年海角天涯，萧萧两鬓生华。看取晚来风势，故应难看梅花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1594, "title": "南歌子", "author": "李清照", "body": "天上星河转，人间帘幕垂。凉生枕簟泪痕滋。起解罗衣聊问夜何其。 翠贴莲蓬小，金销藕叶稀。旧时天气旧时衣，只有情怀不似旧家时！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1595, "title": "渔家傲", "author": "李清照", "body": "天接云涛连晓雾，星河欲转千帆舞。仿佛梦魂归帝所。闻天语，殷勤问我归何处？ 我报路长嗟日暮，学诗谩有惊人句。九万里风鹏正举。风休住，蓬舟吹取三山去！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1596, "title": "如梦令", "author": "李清照", "body": "常记溪亭日暮，沉醉不知归路。兴尽晚回舟，误入藕花深处。争渡，争渡，惊起一滩鸥鹭。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1597, "title": "如梦令", "author": "李清照", "body": "昨夜雨疏风骤。浓睡不消残酒。试问卷帘人，——却道“海棠依旧”。知否，知否？应是绿肥红瘦！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1598, "title": "菩萨蛮", "author": "李清照", "body": "风柔日薄春犹早，夹衫乍著心情好。睡起觉微寒，梅花鬓上残。 故乡何处是，忘了除非醉。沉水卧时烧，香消酒未消。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1599, "title": "菩萨蛮", "author": "李清照", "body": "归鸿声断残云碧。背窗雪落炉烟直。烛底凤钗明，钗头人胜轻。 角声催晓漏，曙色回牛斗。春意看花难，西风留旧寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1600, "title": "浣溪沙", "author": "李清照", "body": "淡荡春光寒食天，玉炉沉水袅残烟，梦回山枕隐花钿。\n海燕未来人斗草，江梅已过柳生绵。黄昏疏雨湿秋千。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1601, "title": "凤凰台上忆吹箫", "author": "李清照", "body": "香冷金猊，被翻红浪，起来慵自梳头。任宝奁尘满，日上帘钩。生怕离怀别苦，多少事、欲说还休。新来瘦，非干病酒，不是悲秋。 休休！这回去也，千万遍《阳关》，也则难留。念武陵人远，烟锁秦楼。惟有楼前流水，应念我、终日凝眸。凝眸处，从今又添，一段新愁。\n凤凰台上忆吹箫（香冷金猊） 李清照\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1602, "title": "一剪梅", "author": "李清照", "body": "红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来？雁字回时，月满西楼。 花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1603, "title": "蝶恋花 离情", "author": "李清照", "body": "暖雨晴风初破冻。柳眼梅腮，已觉春心动。酒意诗情谁与共？泪融残粉花钿重。 乍试夹衫金缕缝。山枕斜攲，枕损钗头凤。独抱浓愁无好梦，夜阑犹剪灯花弄。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1604, "title": "鹧鸪天", "author": "李清照", "body": "寒日萧萧上琐窗，梧桐应恨夜来霜。酒阑更喜团茶苦，梦断偏宜瑞脑香。 秋已尽，日犹长。仲宣怀远更凄凉。不如随分尊前醉，莫负东篱菊蕊黄。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1605, "title": "小重山", "author": "李清照", "body": "春到长门春草青。江梅些子破，未开匀。碧云笼碾玉成尘。留晓梦，惊破一瓯春。 花影压重门。疏帘舖淡月，好黄昏。二年三度负东君。归来也，著意过今春。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1606, "title": "怨王孙", "author": "李清照", "body": "湖上风来波浩渺，秋已暮、红稀香少。水光山色与人亲，说不尽、无穷好。 莲子已成荷叶老，清露洗、蘋花汀草。眠沙鸥鹭不回头，似也恨、人归早。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1607, "title": "临江仙①", "author": "李清照", "body": "庭院深深深几许？云窗雾阁常扃②。柳梢梅萼渐分明。春归秣陵③树，人老建康④城。 感月吟风多少事，如今老去无成。谁怜憔悴更雕零。试灯⑤无意思，踏雪没心情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1608, "title": "醉花阴", "author": "李清照", "body": "薄雾浓云愁永昼，瑞脑消金兽。佳节又重阳，玉枕纱厨，半夜凉初透。 东篱把酒黄昏后，有暗香盈袖。莫道不消魂，帘卷西风，人比黄花瘦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1609, "title": "行香子", "author": "李清照", "body": "草际鸣蛩，惊落梧桐。正人间天上愁浓。云阶月地，关锁千重。纵浮槎来，浮槎去，不相逢。 星桥鹊驾，经年才见，想离情别恨难穷。牵牛织女，莫是离中。甚霎儿晴，霎儿雨，霎儿风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1610, "title": "鹧鸪天", "author": "李清照", "body": "暗淡轻黄体性柔，情疏迹远只香留。何须浅碧深红色，自是花中第一流。 梅定妒，菊应羞。画栏开处冠中秋。骚人可煞无情思，何事当年不见收。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1611, "title": "念奴娇", "author": "李清照", "body": "萧条庭院，又斜风细雨，重门须闭。宠柳娇花寒食近，种种恼人天气。险韵诗成，扶头酒醒，别是闲滋味。征鸿过尽，万千心事难寄。 楼上几日春寒，帘垂四面，玉阑干慵倚。被冷香销新梦觉，不许愁人不起。清露晨流，新桐初引，多少游春意。日高烟敛，更看今日晴未？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1612, "title": "永遇乐", "author": "李清照", "body": "落日熔金，暮云合璧，人在何处？染柳烟浓，吹梅笛怨，春意知几许！元宵佳节，融和天气，次第岂无风雨？来相召，香车宝马，谢他酒朋诗侣。 中州盛日，闺门多暇，记得偏重三五。铺翠冠儿，撚金雪柳，簇带争济楚。如今憔悴，风鬟霜鬓，怕见夜间出去。不如向、帘儿底下，听人笑语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1613, "title": "武陵春", "author": "李清照", "body": "风住尘香花已尽，日晚倦梳头。物是人非事事休，欲语泪先流。 闻说双溪春尚好，也拟泛轻舟。只恐双溪舴艋舟，载不动许多愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1614, "title": "蝶恋花 上巳召亲族", "author": "李清照", "body": "永夜恹恹欢意少。空梦长安，认取长安道。为报今年春色好。花光月影宜相照。 随意杯盘虽草草。酒美梅酸，恰称人怀抱。醉里插花花莫笑。可怜春似人将老。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1615, "title": "声声慢", "author": "李清照", "body": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他晓来风急？雁过也，正伤心，却是旧时相识。 满地黄花堆积，憔悴损，如今有谁堪摘？守著窗儿独自，怎生得黑！梧桐更兼细雨，到黄昏、点点滴滴。这次第，怎一个愁字了得！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1616, "title": "点绛唇", "author": "李清照", "body": "寂寞深闺，柔肠一寸愁千缕。惜春春去，几点催花雨。\n倚遍阑干，祇是无情绪。人何处，连天芳草，望断归来路。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1617, "title": "减字木兰花", "author": "李清照", "body": "卖花担上，买得一枝春欲放。泪染轻匀，犹带彤霞晓露痕。 怕郎猜道，奴面不如花面好。云鬓斜簪，徒要教郎比并看。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1618, "title": "摊破浣溪沙", "author": "李清照", "body": "病起萧萧两鬓华，卧看残月上窗纱。豆蔻连梢煎熟水，莫分茶。 枕上诗书闲处好，门前风景雨来佳。终日向人多酝藉，木犀花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1619, "title": "浣溪沙", "author": "李清照", "body": "髻子伤春懒更梳，晚风庭院落梅初。淡云来往月疏疏。\n玉鸭熏炉闲瑞脑，朱樱斗帐掩流苏。通犀还解辟寒无？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1620, "title": "采桑子", "author": "吕本中", "body": "恨君不似江楼月，南北东西。南北东西，只有相随无别离。 恨君却似江楼月，暂满还亏。暂满还亏，待得团圆是几时？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1621, "title": "南歌子", "author": "吕本中", "body": "驿路侵斜月，溪桥度晓霜。短篱残菊一枝黄，正是乱山深处过重阳。 旅枕元无梦，寒更每自长。只言江左好风光，不道中原归思转凄凉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1622, "title": "踏莎行", "author": "吕本中", "body": "雪似梅花，梅花似雪。似和不似都奇绝。恼人风味阿谁知？请君问取南楼月。 记得去年，探梅时节。老来旧事无人说。为谁醉倒为谁醒？到今犹恨轻离别。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1623, "title": "酹江月", "author": "胡世将", "body": "秋夕兴元使院作，用东坡赤壁韵\n神州沉陆，问谁是、一范一韩人物。北望长安应不见，抛却关西半壁。塞马晨嘶，胡笳夕引，赢得头如雪。三秦往事，只数汉家三杰。 试看百二山河，奈君门万里，六师不发。阃外何人，回首处、铁骑千群都灭。拜将台欹，怀贤阁杳，空指冲冠发。阑干拍遍，独对中天明月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1624, "title": "蝶恋花 河中作", "author": "赵鼎", "body": "尽日东风吹绿树。向晚轻寒，数点催花雨。年少凄凉天付与，更堪春思萦离绪！ 临水高楼携酒处。曾倚哀弦，歌断黄金缕。楼下水流何处去，凭栏目送苍烟暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1625, "title": "点绛唇 春愁", "author": "赵鼎", "body": "香冷金炉，梦回鸳帐馀香嫩。更无人问，一枕江南恨。\n消瘦休文，顿觉春衫褪。清明近，杏花吹尽，薄暮东风紧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1626, "title": "满江红", "author": "赵鼎", "body": "丁未九月南渡，泊舟仪真江口作\n惨结秋阴，西风送、霏霏雨湿。凄望眼，征鸿几字，暮投沙碛。试问乡关何处是，水云浩荡迷南北。但一抹寒青有无中，遥山色。 天涯路，江上客。肠欲断，头应白。空搔首兴叹，暮年离拆。须信道消忧除是酒，奈酒行有尽情无极。便挽取长江入尊，浇胸肊。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1627, "title": "鹧鸪天 建康上元作", "author": "赵鼎", "body": "客路那知岁序移，忽惊春到小桃枝。天涯海角悲凉地，记得当年全盛时。 花弄影，月流辉，水精宫殿五云飞。分明一觉华胥梦，回首东风泪满衣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1628, "title": "洞仙歌", "author": "赵鼎", "body": "空山雨过，月色浮新酿。把盏无人共心赏。漫悲吟，独自拈断霜须。还就寝，秋入孤衾渐爽。 可怜窗外竹，不怕西风，一夜潇潇弄疏响。奈此九回肠，万斛清愁，人何处、邈如天样。纵陇水秦云阻归音，便不许时闲，梦中寻访？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1629, "title": "鹧鸪天", "author": "向子諲", "body": "有怀京师上元，与韩叔夏司谏、王夏卿侍郎、曹仲谷少卿同赋\n紫禁烟花一万重，鳌山宫阙倚晴空。玉皇端拱彤云上，人物嬉游陆海中。 星转斗，驾回龙。五侯池馆醉春风。而今白发三千丈，愁对寒灯数点红。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1630, "title": "秦楼月", "author": "向子諲", "body": "芳菲歇，故园目断伤心切。伤心切，无边烟水，无穷山色。 可堪更近乾龙节，眼中泪尽空啼血。空啼血，子规声外，晓风残月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1631, "title": "阮郎归", "author": "向子諲", "body": "绍兴乙卯大雪行鄱阳道中\n江南江北雪漫漫。遥知易水寒。同云深处望三关。断肠山又山。 天可老，海能翻。消除此恨难。频闻遣使问平安。几时鸾辂还。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1632, "title": "西江月", "author": "向子諲", "body": "政和间，余卜筑宛丘，手植众芗，自号芗林居士。建炎初，解六路漕事，中原俶扰，故庐不得返，卜居清江之五柳坊。绍兴癸丑，罢帅南海，即弃官不仕。乙卯起，以九江郡复转漕江东，入为户部侍郎。辞荣避谤，出守姑苏。到郡少日，请又力焉，诏可，且赐舟曰泛宅，送之以归。己未暮春，复还旧隐。时仲舅李公休亦辞舂陵郡守致仕，喜赋是词。\n五柳坊中烟绿，百花洲上云红。萧萧白发两衰翁，不与时人同梦。 抛掷麟符虎节，徜徉江月林风。世间万事转头空，个里如如不动。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1633, "title": "明月逐人来", "author": "李持正", "body": "星河明淡，春来深浅。红莲正、满城开遍。禁街行乐，暗尘香拂面。皓月随人近远。 天半鳌山，光动凤楼两观。东风静、珠帘不卷。玉辇将归，云外闻弦管。认得宫花影转。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1634, "title": "人月圆", "author": "李持正", "body": "小桃枝上春风早，初试薄罗衣。年年乐事，华灯竞处，人月圆时。 禁街箫鼓，寒轻夜永，纤手重携。更阑人散，千门笑语，声在帘帏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1635, "title": "浪淘沙", "author": "幼卿", "body": "目送楚云空，前事无踪。漫留遗恨锁眉峰。自是荷花开较晚，孤负东风。 客馆叹飘蓬，聚散匆匆。扬鞭那忍骤花骢。望断斜阳人不见，满袖啼红。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1636, "title": "减字木兰花 题雄州驿", "author": "蒋兴祖女", "body": "朝云横度，辘辘车声如水去。白草黄沙，月照孤村三两家。 飞鸿过也，万结愁肠无昼夜。渐近燕山，回首乡关归路难。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1637, "title": "江梅引 忆江梅", "author": "洪皓", "body": "天涯除馆忆江梅。几枝开？使南来，还带余杭春信到燕台①？准拟寒英聊慰远，隔山水，应销落，赴愬谁！ 空恁遐想笑摘蕊②，断回肠，思故里③。漫弹绿绮，引《三弄》，不觉魂飞。更听胡笳，哀怨泪沾衣④。乱插繁花须异日，待孤讽⑤，怕东风，一夜吹。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1638, "title": "苏武慢", "author": "蔡伸", "body": "雁落平沙，烟笼寒水，古垒鸣笳声断。青山隐隐，败叶萧萧，天际暝鸦零乱。楼上黄昏，片帆千里归程，年华将晚。望碧云空暮，佳人何处？梦魂俱远。 忆旧游，邃馆朱扉，小园香径，尚想桃花人面。书盈锦轴，恨满金徽，难写寸心幽怨。两地离愁，一尊芳酒，凄凉危栏倚遍。尽迟留，凭仗西风，吹干泪眼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1639, "title": "苍梧谣", "author": "蔡伸", "body": "天！休使圆蟾照客眠。人何在？桂影自婵娟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1640, "title": "忆王孙 春词", "author": "李重元", "body": "萋萋芳草忆王孙。柳外高楼空断魂。杜宇声声不忍闻。欲黄昏。雨打梨花深闭门。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1641, "title": "贺新郎 春情", "author": "李玉", "body": "篆缕销金鼎。醉沉沉、庭阴转午，画堂人静。芳草王孙知何处？惟有杨花糁径。渐玉枕、腾腾春醒。帘外残红春已透，镇无聊、殢酒厌厌病。云鬓乱，未忺整。 江南旧事休重省。遍天涯寻消问息，断鸿难倩。月满西楼凭阑久，依旧归期未定。又只恐、瓶沉金井。嘶骑不来银烛暗，枉教人、立尽梧桐影。谁伴我，对鸾镜！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1642, "title": "小重山", "author": "吴淑姬", "body": "谢了荼蘼春事休。无多花片子，缀枝头。庭槐影碎被风揉。莺虽老，声尚带娇羞。 独自倚妆楼。一川烟草浪，衬云浮。不如归去下帘钩。心儿小，难着许多愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1643, "title": "卜算子 答施", "author": "乐婉", "body": "相思似海深，旧事如天远。泪滴千千万万行，更使人、愁肠断。 要见无因见，拚了终难拚。若是前生未有缘，待重结、来生愿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1644, "title": "鹧鸪天 寄李之问", "author": "聂胜琼", "body": "玉惨花愁出凤城①。莲花楼下柳青青。尊前一唱《阳关》后，别个人人第五程。 寻好梦，梦难成。况谁知我此时情。枕前泪共帘前雨，隔个窗儿滴到明。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1645, "title": "水调歌头 呈汉阳使君", "author": "王以宁", "body": "大别我知友，突兀起西州。十年重见，依旧秀色照清眸。常记鲒碕狂客，邀我登楼雪霁，杖策拥羊裘。山吐月千仞，残夜水明楼。 黄粱梦，未觉枕，几经秋。与君邂逅，相逐飞步碧山头。举酒一觞今古，叹息英雄骨冷，清泪不能收。鹦鹉更谁赋，遗恨满芳洲。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1646, "title": "临江仙", "author": "陈与义", "body": "高咏楚词酬午日①，天涯节序匆匆。榴花不似舞裙红②。无人知此意，歌罢满帘风。 万事一身伤老矣，戎葵③凝笑墙东。酒杯深浅去年同。试浇桥下水，今夕到湘中④。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1647, "title": "虞美人", "author": "陈与义", "body": "大光祖席，醉中赋长短句\n张帆欲去仍搔首，更醉君家酒。吟诗日日待春风，及至桃花开后却匆匆。 歌声频为行人咽，记著樽前雪。明朝酒醒大江流，满载一船离恨向衡州。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1648, "title": "虞美人", "author": "陈与义", "body": "余甲寅岁自春官出守湖州，秋杪，道中荷花无复存者。乙卯岁，自琐闼以病得请奉祠，卜居青墩镇。立秋后三日行，舟之前后如朝霞相映，望之不断也。以长短句记之。\n扁舟三日秋塘路，平度荷花去。病夫因病得来游，更值满川微雨洗新秋。 去年长恨拏舟晚，空见残荷满。今年何以报君恩？一路繁花相送到青墩。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1649, "title": "临江仙", "author": "陈与义", "body": "夜登小阁，忆洛中旧游\n忆昔午桥桥上饮，坐中多是豪英。长沟流月去无声。杏花疏影里，吹笛到天明。 二十馀年如一梦，此身虽在堪惊。闲登小阁看新晴。古今多少事，渔唱起三更。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1650, "title": "贺新郎", "author": "张元幹", "body": "寄李伯纪丞相\n曳杖危楼去。斗垂天，沧波万顷，月流烟渚。扫尽浮云风不定，未放扁舟夜渡。宿雁落、寒芦深处。怅望关河空吊影，正人间鼻息鸣鼍鼓。谁伴我，醉中舞。 十年一梦扬州路，倚高寒、愁生故国，气吞骄虏。要斩楼兰三尺剑，遗恨琵琶旧语。谩暗涩铜华尘土。唤取谪仙平章看，过苕溪尚许垂纶否？风浩荡，欲飞举。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1651, "title": "贺新郎", "author": "张元幹", "body": "送胡邦衡待制\n梦绕神州路。怅秋风，连营画角，故宫离黍。底事昆仑倾砥柱①，九地黄流乱注？聚万落千村狐兔。天意从来高难问，况人情，老易悲难诉！更南浦，送君去。 凉生岸柳催残暑。耿斜河、疏星淡月，断云微度。万里江山知何处？回首对床夜语。雁不到、书成谁与？目尽青天怀今古，肯儿曹恩怨相尔汝？举大白，听《金缕》。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1652, "title": "满江红", "author": "张元幹", "body": "自豫章阻风吴城山作\n春水迷天，桃花浪、几番风恶。云乍起、远山遮尽，晚风还作。绿卷芳洲生杜若，数帆带雨烟中落。傍向来沙嘴共停桡，伤飘泊。 寒犹在，衾偏薄。肠欲断，愁难著。倚篷窗无寐，引杯孤酌。寒食清明都过却，最怜轻负年时约。想小楼、终日望归舟，人如削。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1653, "title": "兰陵王 春恨", "author": "张元幹", "body": "卷珠箔。朝雨轻阴乍阁。阑干外、烟柳弄晴，芳草侵阶映红药。东风妒花恶。吹落梢头嫩萼。屏山掩、沉水倦熏，中酒心情怕杯勺。 寻思旧京洛。正年少疏狂，歌笑迷著。障泥油壁催梳掠。曾驰道同载，上林携手，灯夜初过早共约。又争信飘泊？ 寂寞。念行乐。甚粉淡衣襟，音断弦索。琼枝璧月春如昨。怅别后华表，那回双鹤。相思除是，向醉里、暂忘却。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1654, "title": "石州慢", "author": "张元幹", "body": "寒水依痕，春意渐回，沙际烟阔。溪梅晴照生香，冷蕊数枝争发。天涯旧恨，试看几许消魂？长亭门外山重叠。不尽眼中青，是愁来时节。 情切。画楼深闭，想见东风，暗消肌雪。孤负枕前云雨，尊前花月。心期切处，更有多少凄凉，殷勤留与归时说。到得再相逢，恰经年离别。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1655, "title": "石州慢", "author": "张元幹", "body": "己酉秋，吴兴舟中作\n雨急云飞，惊散暮鸦，微弄凉月。谁家疏柳低迷，几点流萤明灭。夜帆风驶，满湖烟水苍茫，菰蒲零乱秋声咽。梦断酒醒时，倚危樯清绝。 心折。长庚光怒，群盗纵横，逆胡猖獗。欲挽天河，一洗中原膏血。两宫何处？塞垣只隔长江，唾壶空击悲歌缺。万里想龙沙，泣孤臣吴越。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1656, "title": "水调歌头 追和", "author": "张元幹", "body": "举手钓鳌客，削迹种瓜侯。重来吴会，三伏行见五湖秋。耳畔风波摇荡，身外功名飘忽，何路射旄头？孤负男儿志，怅望故园愁。 梦中原，挥老泪，遍南州。元龙湖海豪气，百尺卧高楼。短发霜粘两鬓，清夜盆倾一雨，喜听瓦鸣沟。犹有壮心在，付与百川流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1657, "title": "鱼游春水", "author": "张元幹", "body": "芳洲生蘋芷，宿雨收晴浮暖翠。烟光如洗，几片花飞点泪。清镜空余白发添，新恨谁传红绫寄①。溪涨岸痕，浪吞沙尾。 老去情怀易醉。十二阑干慵遍倚。双凫②人惯风流，功名万里。梦想浓妆碧云边，目断孤帆夕阳里。何时送客，更临春水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1658, "title": "浣溪沙", "author": "张元幹", "body": "山绕平湖波撼城，湖光倒影浸山青，水晶楼下欲三更。\n雾柳暗时云度月，露荷翻处水流萤，萧萧散发到天明。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1659, "title": "点绛唇", "author": "张元幹", "body": "呈洛滨、筠溪二老\n清夜沉沉，暗蛩啼处檐花落。乍凉帘幕，香绕屏山角。\n堪恨归鸿，情似秋云薄。书难托，尽交寂寞，忘了前时约。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1660, "title": "渔家傲 题玄真子图", "author": "张元幹", "body": "钓笠披云青嶂绕，绿蓑细雨春江渺。白鸟飞来风满棹。收纶了，渔童拍手樵青笑。 明月太虚同一照，浮家泛宅忘昏晓。醉眼冷看城市闹。烟波老，谁能惹得闲烦恼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1661, "title": "瑞鹧鸪", "author": "张元幹", "body": "彭德器出示胡邦衡新句次韵\n白衣苍狗变浮云，千古功名一聚尘。好是悲歌将进酒，不妨同赋惜馀春。 风光全似中原日，臭味要须我辈人。雨后飞花知底数？醉来赢取自由身。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1662, "title": "菩萨蛮", "author": "张元幹", "body": "三月晦，送春有集，坐中偶书\n春来春去催人老，老夫争肯输年少。醉后少年狂，白髭殊未妨。 插花还起舞，管领风光处。把酒共留春，莫教花笑人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1663, "title": "薄幸", "author": "吕渭老", "body": "青楼春晚。昼寂寂、梳匀又懒。乍听得、鸦啼莺弄，惹起新愁无限。记年时、偷掷春心，花间隔雾遥相见。便角枕①题诗，宝钗②贳酒，共醉青苔深院。 怎忘得、回廊下，携手处、花明月满。如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。却谁拘管。尽无言、闲品秦筝，泪满参差雁。腰支渐小，心与杨花共远。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1664, "title": "如梦令", "author": "王之道", "body": "一饷凝情无语，手撚梅花何处。倚竹不胜愁，暗想江头归路。东去，东去，短艇淡烟疏雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1665, "title": "薄媚 （排遍第九）", "author": "董颖", "body": "西子词\n自笑平生，英气凌云，凛然万里宣威。那知此际，熊虎途穷，来伴麋鹿卑栖！既甘臣妾，犹不许，何为计。争若都燔宝器。尽诛吾妻子。径将死战决雄雌。天意恐怜之。 偶闻太宰，正擅权，贪赂市恩私。因将宝玩献诚，虽脱霜戈，石室囚系。忧嗟又经时。恨不如巢燕自由归。残月朦胧，寒雨萧萧，有血都成泪。备尝险厄返邦畿。冤愤刻肝脾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1666, "title": "点绛唇", "author": "朱翌", "body": "流水泠泠，断桥横路梅枝亚。雪花飞下，浑似江南画。\n白璧青钱，欲买春无价。归来也，风吹平野，一点香随马。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1667, "title": "南浦", "author": "鲁逸仲", "body": "风悲画角，听单于三弄落谯门。投宿骎骎征骑，飞雪满孤村。酒市渐阑灯火，正敲窗乱叶舞纷纷。送数声惊雁，乍离烟水，嘹唳度寒云。 好在半胧淡月，到如今、无处不销魂。故国梅花归梦，愁损绿罗裙。为问暗香闲艳，也相思万点付啼痕。算翠屏应是，两眉余恨倚黄昏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1668, "title": "蓦山溪 寄宝学", "author": "刘子", "body": "浮烟冷雨，今日还重九。秋去又秋来，但黄花、年年如旧。平台戏马，无处问英雄；茅舍底，竹篱东，伫立时搔首。 客来何有？草草三杯酒。一醉万缘空，莫贪伊、金印如斗。病翁老矣，谁共赋归来？芟垅麦，网溪鱼，未落他人后。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1669, "title": "好事近", "author": "胡铨", "body": "富贵本无心，何事故乡轻别？空使猿惊鹤怨，误薜萝秋月。 囊锥刚要出头来，不道甚时节！欲驾巾车归去，有豺狼当辙！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1670, "title": "小重山", "author": "岳飞", "body": "昨夜寒蛩不住鸣。惊回千里梦，已三更。起来独自绕阶行。人悄悄，帘外月胧明。 白首为功名。旧山松竹老，阻归程。欲将心事付瑶琴①。知音少，弦断有谁听？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1671, "title": "满江红", "author": "岳飞", "body": "怒发冲冠，凭栏处、潇潇雨歇。抬望眼，仰天长啸，壮怀激烈。三十功名尘与土，八千里路云和月。莫等闲、白了少年头，空悲切。 靖康耻，犹未雪。臣子恨，何时灭！驾长车，踏破贺兰山缺。壮志饥餐胡虏肉，笑谈渴饮匈奴血。待从头收拾旧山河，朝天阙。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1672, "title": "满江红", "author": "岳飞", "body": "登黄鹤楼有感\n遥望中原，荒烟外、许多城郭。想当年，花遮柳护，凤楼龙阁。万岁山前珠翠绕，蓬壶殿里笙歌作。到而今、铁骑满郊畿，风尘恶。 兵安在？膏锋锷。民安在？填沟壑。叹江山如故，千村寥落。何日请缨提锐旅，一鞭直渡清河洛。却归来、再续汉阳游，骑黄鹤。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1673, "title": "滴滴金 梅", "author": "孙道绚", "body": "月光飞入林前屋。风策策，度庭竹。夜半江城击柝声，动寒梢栖宿。 等闲老去年华促，只有江梅伴幽独。梦绕夷门旧家山，恨惊回难续。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1674, "title": "临江仙 佳人", "author": "李石", "body": "烟柳疏疏人悄悄，画楼风外吹笙。倚栏闻唤小红声。熏香临欲睡，玉漏已三更。 坐待不来来又去，一方明月中庭。粉墙东畔小桥横。起来花影下，扇子扑飞萤。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1675, "title": "望江南 重九遇雨", "author": "康与之", "body": "重阳日，阴雨四郊垂。戏马台前泥拍肚，龙山会上水平脐。直浸到东篱。 茱萸胖，菊蕊湿滋滋。落帽孟嘉寻篛笠，休官陶令觅蓑衣。都道不如归。①", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1676, "title": "菩萨蛮令 金陵怀古", "author": "康与之", "body": "龙蟠虎踞金陵郡，古来六代豪华盛。缥凤不来游，台空江自流。 下临全楚地，包举中原势。可惜草连天，晴郊狐兔眠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1677, "title": "长相思 游西湖", "author": "康与之", "body": "南高峰，北高峰，一片湖光烟霭中。春来愁杀侬。\n郎意浓，妾意浓。油壁车轻郎马骢，相逢九里松。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1678, "title": "满庭芳 寒夜", "author": "康与之", "body": "霜幕风帘，闲斋小户，素蟾初上雕笼。玉杯醽醁，还与可人同。古鼎沉烟篆细，玉笋破、橙橘香浓。梳妆懒，脂轻粉薄，约略淡眉峰。 清新歌几许，低随慢唱，语笑相供。道文书针线，今夜休攻。莫厌兰膏更继，明朝又、纷冗匆匆。酩酊也，冠儿未卸，先把被儿烘。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1679, "title": "金人捧露盘", "author": "曾觌", "body": "庚寅岁春，奉使过京师，感怀作\n记神京，繁华地，旧游踪。正御沟、春水溶溶。平康巷陌，绣鞍金勒跃青骢。解衣沽酒醉弦管，柳绿花红。 到如今、馀霜鬓，嗟前事、梦魂中。但寒烟、满目飞蓬。雕栏玉砌，空锁三十六离宫。塞笳惊起暮天雁，寂寞东风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1680, "title": "阮郎归", "author": "曾觌", "body": "柳阴庭院占风光，呢喃清昼长。碧波新涨小池塘，双双蹴水忙。 萍散漫，絮飘飏，轻盈体态狂。为怜流去落红香，衔将归画梁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1681, "title": "忆秦娥", "author": "曾觌", "body": "邯郸道上望丛台①有感\n风萧瑟，邯郸古道伤行客。伤行客。繁华一瞬，不堪思忆。 丛台歌舞无消息，金樽玉管空陈迹。空陈迹，连天衰草，暮云凝碧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1682, "title": "青玉案", "author": "黄公度", "body": "邻鸡不管离怀苦，又还是、催人去。回首高城音信阻。霜桥月馆，水村烟市，总是思君处。 裛残别袖燕支雨，谩留得、愁千缕。欲倩归鸿分付与。鸿飞不住，倚阑无语，独立长天暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1683, "title": "卜算子", "author": "葛立方", "body": "袅袅水芝红，脉脉蒹葭浦。淅淅西风淡淡烟，几点疏疏雨。\n草草展杯觞，对此盈盈女。叶叶红衣当酒船，细细流霞举。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1684, "title": "长相思令", "author": "吴淑姬", "body": "烟霏霏，雪霏霏。雪向梅花枝上堆，春从何处回！\n醉眼开，睡眼开，疏影横斜安在哉？从教塞管催。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1685, "title": "渔家傲引", "author": "洪适", "body": "子月水寒风又烈。巨鱼漏网成虚设。圉圉从它归丙穴。谋自拙。空归不管旁人说。 昨夜醉眠西浦月。今宵独钓南溪雪。妻子一船衣百结。长欢悦。不知人世多离别。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1686, "title": "霜天晓角", "author": "韩元吉", "body": "题采石蛾眉亭\n倚天绝壁，直下江千尺。天际两蛾凝黛，愁与恨，几时极！ 暮潮风正急，酒阑闻塞笛。试问谪仙何处？青山外，远烟碧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1687, "title": "薄幸 送安伯弟", "author": "韩元吉", "body": "送君南浦。对烟柳、青青万缕。更满眼、残红吹尽，叶底黄鹂自语。甚动人、多少离情，楼头水阔山无数。记竹里题诗，花边载酒，魂断江干春暮。 都莫问功名事，白发渐、星星如许。任鸡鸣起舞，乡关何在，凭高目尽孤鸿去。漫留君住。趁酴醿香暖，持杯且醉瑶台露。相思记取，愁绝西窗夜雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1688, "title": "好事近", "author": "韩元吉", "body": "汴京赐宴闻教坊乐有感\n凝碧旧池头，一听管弦凄切。多少梨园声在，总不堪华发。\n杏花无处避春愁，也傍野烟发。惟有御沟声断，似知人呜咽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1689, "title": "六州歌头 桃花", "author": "韩元吉", "body": "东风着意，先上小桃枝。红粉腻，娇如醉，倚朱扉。记年时。隐映新妆面，临水岸，春将半，云日暖，斜桥转，夹城西。草软莎平，跋马垂杨渡，玉勒争嘶。认蛾眉凝笑，脸薄拂燕脂。绣户曾窥，恨依依。 共携手处，香如雾，红随步，怨春迟。消瘦损，凭谁问？只花知，泪空垂。旧日堂前燕，和烟雨，又双飞。人自老，春长好，梦佳期。前度刘郎，几许风流地，花也应悲。但茫茫暮霭，目断武陵溪①。往事难追。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1690, "title": "谒金门 春半", "author": "朱淑真", "body": "春已半，触目此情无限。十二阑干闲倚遍，愁来天不管。\n好是风和日暖，输与莺莺燕燕。满院落花帘不卷，断肠芳草远。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1691, "title": "减字木兰花 春怨", "author": "朱淑真", "body": "独行独坐，独倡独酬还独卧。伫立伤神，无奈轻寒著摸人。 此情谁见，泪洗残妆无一半。愁病相仍，剔尽寒灯梦不成。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1692, "title": "眼儿媚", "author": "朱淑真", "body": "迟迟春日弄轻柔，花径暗香流。清明过了，不堪回首，云锁朱楼。 午窗睡起莺声巧，何处唤春愁？绿杨影里，海棠亭畔，红杏梢头。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1693, "title": "清平乐", "author": "朱淑真", "body": "风光紧急，三月俄三十。拟欲留连计无及，绿野烟愁露泣。 倩谁寄语春宵？城头画鼓轻敲。缱绻临歧嘱付，来年早到梅梢。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1694, "title": "蝶恋花 送春", "author": "朱淑真", "body": "楼外垂杨千万缕，欲系青春，少住春还去。犹自风前飘柳絮，随春且看归何处？ 绿满山川闻杜宇，便做无情，莫也愁人苦。把酒送春春不语，黄昏却下潇潇雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1695, "title": "清平乐", "author": "朱淑真", "body": "恼烟撩露，留我须臾住。携手藕花湖上路，一霎黄梅细雨。 娇痴不怕人猜，和衣睡倒人怀。最是分携时候，归来懒傍妆台。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1696, "title": "菩萨蛮", "author": "朱淑真", "body": "山亭水榭秋方半，凤帏寂寞无人伴。愁闷一番新，双蛾只旧颦。 起来临绣户，时有疏萤度。多谢月相怜，今宵不忍圆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1697, "title": "四犯令", "author": "侯寘", "body": "月破轻云天淡注，夜悄花无语。莫听《阳关》牵离绪。拚酩酊花深处。 明日江郊芳草路，春逐行人去。不似荼蘼开独步，能着意留春住。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1698, "title": "点绛唇 途中逢管倅", "author": "赵彦端", "body": "憔悴天涯，故人相遇情如故。别离何遽，忍唱《阳关》句！\n我是行人，更送行人去。愁无据。寒蝉鸣处，回首斜阳暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1699, "title": "醉落魄", "author": "王千秋", "body": "惊鸥扑蔌。萧萧卧听鸣幽屋。窗明怪得鸡啼速。墙角烂斑①，一半露松绿。 歌楼管竹谁翻曲？丹唇冰面喷馀馥。遗珠满地无人掬。归著红靴，踏碎一街玉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1700, "title": "鹧鸪天 寄情", "author": "李吕", "body": "脸上残霞酒半消，晚妆匀罢却无聊。金泥帐小教谁共？银字笙寒懒更调。 人悄悄，漏迢迢。琐窗虚度可怜宵。一从恨满丁香结，几度春深豆蔻梢。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1701, "title": "生查子 情景", "author": "姚宽", "body": "郎如陌上尘，妾似堤边絮。相见两悠扬，踪迹无寻处。\n酒面扑春风，泪眼零秋雨。过了别离时，还解相思否？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1702, "title": "踏莎行", "author": "洪迈", "body": "院落深沉，池塘寂静。帘钩卷上梨花影。宝筝拈得雁难寻，篆香消尽山空冷。 钗凤斜攲，鬓蝉不整。残红立褪慵看镜。杜鹃啼月一声声，等闲又是三春尽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1703, "title": "南乡子", "author": "绍兴太学生", "body": "洪迈被拘留，稽首①垂哀告敌仇②。一日忍饥犹不耐，堪羞！苏武争禁十九秋？ 厥父既无谋，厥子安能解国忧？万里归来夸舌辩，村牛！好摆头时便摆头。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1704, "title": "水调歌头 定王台", "author": "袁去华", "body": "雄跨洞庭野，楚望古湘州。何王台殿，危基百尺自西刘。尚想霓旌千骑，依约入云歌吹，屈指几经秋。叹息繁华地，兴废两悠悠。 登临处，乔木老，大江流。书生报国无地，空白九分头。一夜寒生关塞，万里云埋陵阙，耿耿恨难休。徙倚霜风里，落日伴人愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1705, "title": "瑞鹤仙", "author": "袁去华", "body": "郊原初过雨。见败叶零乱，风定犹舞。斜阳挂深树。映浓愁浅黛，遥山媚妩。来时旧路，尚岩花、娇黄半吐。到而今唯有，溪边流水，见人如故。 无语。邮亭深静，下马还寻，旧曾题处。无聊倦旅。伤离恨，最愁苦。纵收香藏镜，他年重到，人面桃花在否？念沉沉、小阁幽窗，有时梦去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1706, "title": "剑器近", "author": "袁去华", "body": "夜来雨。赖倩得、东风吹住。海棠正妖娆处。且留取。\n悄庭户。试细听、莺啼燕语。分明共人愁绪。怕春去。\n佳树。翠阴初转午。重帘未卷，乍睡起、寂寞看风絮。偷弹清泪寄烟波，见江头故人，为言憔悴如许。彩笺无数。去却寒暄，到了浑无定据。断肠落日千山暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1707, "title": "安公子", "author": "袁去华", "body": "弱柳丝千缕。嫩黄匀遍鸦啼处。寒入罗衣春尚浅，过一番风雨。问燕子来时，绿水桥边路。曾画楼、见个人人否。料静掩云窗，尘满哀弦危柱。 庾信愁如许。为谁都著眉端聚。独立东风弹泪眼，寄烟波东去。念永昼春闲，人倦如何度。闲傍枕、百啭黄鹂语。唤觉来厌厌，残照依然花坞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1708, "title": "瑞鹤仙", "author": "陆淞", "body": "脸霞红印枕。睡觉来、冠儿还是不整。屏间麝煤冷。但眉峰压翠，泪珠弹粉。堂深昼永。燕交飞、风帘露井。恨无人与说相思，近日带围宽尽。 重省。残灯朱幌，淡月纱窗，那时风景。阳台路迥。云雨梦，便无准。待归来，先指花梢教看，却把心期细问。问因循过了青春，怎生意稳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1709, "title": "如梦令", "author": "向滈", "body": "谁伴明窗独坐，和我影儿两个。灯烬欲眠时，影也把人抛躲。无那，无那，好个恓惶的我。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1710, "title": "凤栖梧 兰溪", "author": "曹冠", "body": "桂棹悠悠分浪稳。烟幂层峦，绿水连天远。赢得锦囊诗句满，兴来豪饮挥金碗。 飞絮撩人花照眼。天阔风微，燕外晴丝卷。翠竹谁家门可款？舣舟闲上斜阳岸。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1711, "title": "念奴娇", "author": "曹冠", "body": "宋玉《高唐赋》述楚怀王遇神女事，后世信之。愚①独以为不然，因赋《念奴娇》，洗千载之诬蔑，以祛流俗②之惑。\n蜀川三峡，有高唐奇观③，神仙幽处④。巨石巉岩临积水，波浪轰天声怒。十二灵峰⑤，云阶月地⑥，中有巫山女。须臾变化⑦，阳台朝暮云雨。 堪笑楚国怀襄，分⑧当严父子，胡然无度⑨？幻梦俱迷，应感逢魑魅⑩，虚言冥遇⑪。女耻求媒，况神清直，岂可轻诬污？逢⑫君之恶，鄙哉宋玉词赋！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1712, "title": "醉落魄", "author": "管鉴", "body": "正月二十日张园赏海棠作\n春阴漠漠，海棠花底东风恶。人情不似春情薄，守定花枝，不放花零落。 绿尊细细供春酌，酒醒无奈愁如昨。殷勤待与东风约：莫苦吹花，何似吹愁却。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1713, "title": "水调歌头 多景楼", "author": "陆游", "body": "江左占形胜，最数古徐州①。连山如画，佳处缥缈著危楼。鼓角临风悲壮，烽火连空明灭，往事忆孙刘。千里曜戈甲，万灶宿貔貅。 露沾草，风落木，岁方秋。使君宏放，谈笑洗尽古今愁。不见襄阳登览，磨灭游人无数，遗恨黯难收。叔子独千载，名与汉江流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1714, "title": "南乡子", "author": "陆游", "body": "归梦寄吴樯，水驿江程去路长。想见芳洲初系缆，斜阳，烟树参差认武昌。 愁鬓点新霜，曾是朝衣染御香。重到故乡交旧少，凄凉，却恐他乡胜故乡。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1715, "title": "感皇恩", "author": "陆游", "body": "小阁倚秋空，下临江渚。漠漠孤云未成雨。数声新雁，回首杜陵何处。壮心空万里，人谁许！ 黄阁紫枢，筑坛开府。莫怕功名欠人做。如今熟计，只有故乡归路。石帆山脚下，菱三亩。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1716, "title": "好事近", "author": "陆游", "body": "秋晓上莲峰，高蹑倚天青壁。谁与放翁为伴？有天坛轻策。 铿然忽变赤龙飞，雷雨四山黑。谈笑做成丰岁，笑禅龛楖栗。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1717, "title": "鹧鸪天", "author": "陆游", "body": "家住苍烟落照间，丝毫尘事不相关。斟残玉瀣行穿竹，卷罢黄庭卧看山。 贪啸傲，任衰残，不妨随处一开颜。元知造物心肠别，老却英雄似等闲！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1718, "title": "鹧鸪天", "author": "陆游", "body": "懒向青门学种瓜，只将渔钓送年华。双双新燕飞春岸，片片轻鸥落晚沙。 歌缥缈，㯭呕哑，酒如清露鲊如花。逢人问道归何处，笑指船儿此是家。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1719, "title": "木兰花 立春日作", "author": "陆游", "body": "三年流落巴山道，破尽青衫尘满帽。身如西瀼渡头云，愁抵瞿塘关上草。 春盘春酒年年好，试戴银旛判醉倒。今朝一岁大家添，不是人间偏我老。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1720, "title": "临江仙 离果州作", "author": "陆游", "body": "鸠雨催成新绿，燕泥收尽残红。春光还与美人同：论心空眷眷，分袂却匆匆。 只道真情易写，那知怨句难工。水流云散各西东。半廊花院月，一帽柳桥风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1721, "title": "蝶恋花", "author": "陆游", "body": "桐叶晨飘蛩夜语。旅思秋光，黯黯长安路。忽记横戈盘马处，散关清渭应如故。 江海轻舟今已具。一卷兵书，叹息无人付。早信此生终不遇，当年悔草《长杨赋》。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1722, "title": "钗头凤", "author": "陆游", "body": "红酥手，黄縢酒。满城春色宫墙柳。东风恶，欢情薄。一怀愁绪，几年离索。错，错，错。 春如旧，人空瘦。泪痕红浥鲛绡透。桃花落，闲池阁。山盟虽在，锦书难托。莫，莫，莫！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1723, "title": "清商怨 葭萌驿作", "author": "陆游", "body": "江头日暮痛饮，乍雪晴犹凛。山驿凄凉，灯昏人独寝。\n鸳机新寄断锦，叹往事、不堪重省。梦破南楼，绿云堆一枕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1724, "title": "秋波媚", "author": "陆游", "body": "七月十六晚登高兴亭望长安南山\n秋到边城角声哀，烽火照高台。悲歌击筑，凭高酹酒，此兴悠哉！ 多情谁似南山月，特地暮云开。灞桥烟柳，曲江池馆，应待人来。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1725, "title": "卜算子 咏梅", "author": "陆游", "body": "驿外断桥边，寂寞开无主。已是黄昏独自愁，更著风和雨。 无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1726, "title": "汉宫春", "author": "陆游", "body": "初自南郑来成都作\n羽箭雕弓，忆呼鹰古垒，截虎平川。吹笳暮归野帐，雪压青毡。淋漓醉墨，看龙蛇飞落蛮笺。人误许、诗情将略，一时才气超然。 何事又作南来，看重阳药市，元夕灯山？花时万人乐处，欹帽垂鞭。闻歌感旧，尚时时流涕尊前。君记取、封侯事在，功名不信由天。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1727, "title": "乌夜啼", "author": "陆游", "body": "金鸭馀香尚暖，绿窗斜日偏明。兰膏香染云鬟腻，钗坠滑无声。 冷落秋千伴侣，阑珊打马心情。绣屏惊断潇湘梦，花外一声莺。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1728, "title": "乌夜啼", "author": "陆游", "body": "纨扇婵娟素月，纱巾缥缈轻烟。高槐叶长阴初合，清润雨余天。 弄笔斜行小草，钩帘浅醉闲眠。更无一点尘埃到，枕上听新蝉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1729, "title": "夜游宫", "author": "陆游", "body": "记梦寄师伯浑\n雪晓清笳乱起，梦游处、不知何地。铁骑无声望似水。想关河：雁门西，青海际。 睡觉寒灯里，漏声断、月斜窗纸。自许封侯在万里。有谁知，鬓虽残，心未死！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1730, "title": "渔家傲 寄仲高", "author": "陆游", "body": "东望山阴何处是？往来一万三千里。写得家书空满纸。流清泪，书回已是明年事。 寄语红桥桥下水，扁舟何日寻兄弟？行遍天涯真老矣。愁无寐，鬓丝几缕茶烟里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1731, "title": "双头莲", "author": "陆游", "body": "呈范至能待制\n华鬓星星，惊壮志成虚，此身如寄。萧条病骥。向暗里、消尽当年豪气。梦断故国山川，隔重重烟水。身万里，旧社凋零，青门俊游谁记？ 尽道锦里繁华，叹官闲昼永，柴荆添睡。清愁自醉。念此际、付与何人心事。纵有楚柁吴樯，知何时东逝？空怅望，鲙美菰香，秋风又起。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1732, "title": "鹊桥仙", "author": "陆游", "body": "华灯纵博，雕鞍驰射，谁记当年豪举？酒徒一半取封侯，独去作江边渔父。 轻舟八尺，低篷三扇，占断蘋洲烟雨。镜湖元自属闲人，又何必官家赐与！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1733, "title": "鹊桥仙", "author": "陆游", "body": "一竿风月，一蓑烟雨，家在钓台西住。卖鱼生怕近城门，况肯到红尘深处？ 潮生理棹，潮平系缆，潮落浩歌归去。时人错把比严光，我自是无名渔父。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1734, "title": "鹊桥仙 夜闻杜鹃", "author": "陆游", "body": "茅檐人静，蓬窗灯暗，春晚连江风雨。林莺巢燕总无声，但月夜、常啼杜宇。 催成清泪，惊残孤梦，又拣深枝飞去。故山犹自不堪听，况半世、飘然羁旅！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1735, "title": "诉衷情", "author": "陆游", "body": "当年万里觅封侯，匹马戍梁州①。关河梦断何处，尘暗旧貂裘。 胡未灭，鬓先秋，泪空流。此身谁料，心在天山，身老沧洲。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1736, "title": "诉衷情", "author": "陆游", "body": "青衫初入九重城，结友尽豪英。蜡封夜半传檄，驰骑谕幽并。 时易失，志难成，鬓丝生。平章风月，弹压江山，别是功名。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1737, "title": "点绛唇", "author": "陆游", "body": "采药归来，独寻茅店沽新酿。暮烟千嶂，处处闻渔唱。\n醉弄扁舟，不怕黏天浪。江湖上，遮回疏放，作个闲人样。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1738, "title": "谢池春", "author": "陆游", "body": "壮岁从戎，曾是气吞残虏。阵云高、狼烟夜举。朱颜青鬓，拥雕戈西戍。笑儒冠自来多误。 功名梦断，却泛扁舟吴楚。漫悲歌、伤怀吊古。烟波无际，望秦关何处？叹流年又成虚度。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1739, "title": "钗头凤", "author": "唐琬", "body": "世情薄，人情恶，雨送黄昏花易落。晓风干，泪痕残。欲笺心事，独语斜阑①。难，难，难！ 人成各，今非昨，病魂常似秋千索②。角声寒，夜阑珊③。怕人寻问，咽泪装欢。瞒，瞒，瞒！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1740, "title": "生查子", "author": "传陆游妾", "body": "只知眉上愁，不识愁来路。窗外有芭蕉，阵阵黄昏雨。\n晓起理残妆，整顿教愁去。不合画春山，依旧留愁住。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1741, "title": "鹊桥仙", "author": "蜀妓", "body": "说盟说誓，说情说意，动便春愁满纸。多应念得脱空经，是那个先生教底？ 不茶不饭，不言不语，一味供他憔悴。相思已是不曾闲，又那得功夫咒你。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1742, "title": "蝶恋花", "author": "范成大", "body": "春涨一篙添水面。芳草鹅儿，绿满微风岸。画舫夷犹湾百转，横塘塔近依前远。 江国多寒农事晚。村北村南，谷雨才耕遍。秀麦连冈桑叶贱，看看尝面收新茧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1743, "title": "南柯子", "author": "范成大", "body": "怅望梅花驿，凝情杜若洲。香云低处有高楼，可惜高楼不近木兰舟。 缄素双鱼远，题红片叶秋。欲凭江水寄离愁，江已东流那肯更西流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1744, "title": "水调歌头", "author": "范成大", "body": "细数十年事，十处过中秋。今年新梦，忽到黄鹤旧山头。老子个中不浅，此会天教重见，今古一南楼。星汉淡无色，玉镜独空浮。 敛秦烟，收楚雾，熨江流。关河离合，南北依旧照清愁。想见姮娥冷眼，应笑归来霜鬓，空敝黑貂裘。酾酒问蟾兔，肯去伴沧洲？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1745, "title": "鹊桥仙 七夕", "author": "范成大", "body": "双星良夜，耕慵织懒，应被群仙相妒。娟娟月姊满眉颦，更无奈、风姨吹雨。 相逢草草，争如休见，重搅别离心绪。新欢不抵旧愁多，倒添了、新愁归去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1746, "title": "秦楼月", "author": "范成大", "body": "楼阴缺，栏干影卧东厢月。东厢月，一天风露，杏花如雪。 隔烟催漏金虬①咽，罗帏暗淡灯花结。灯花结，片时春梦，江南天阔。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1747, "title": "鹧鸪天", "author": "范成大", "body": "休舞银貂小契丹，满堂宾客尽关山。从今嫋嫋盈盈处，谁复端端正正看。 模泪易，写愁难。潇湘江上竹枝斑。碧云日暮无书寄，寥落烟中一雁寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1748, "title": "鹧鸪天", "author": "范成大", "body": "嫩绿重重看得成，曲阑幽槛小红英。酴醿架上蜂儿闹，杨柳行间燕子轻。 春婉娩，客飘零，残花残酒片时清。一杯且买明朝事，送了斜阳月又生。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1749, "title": "霜天晓角 梅", "author": "范成大", "body": "晚晴风歇，一夜春威折。脉脉花疏天淡，云来去，数枝雪。 胜绝，愁亦绝。此情谁共说。惟有两行低雁，知人倚、画楼月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1750, "title": "眼儿媚", "author": "范成大", "body": "萍乡道中乍晴，卧舆中困甚，小憩柳塘\n酣酣日脚紫烟浮，妍暖破轻裘。困人天色，醉人花气，午梦扶头。 春慵恰似春塘水，一片縠纹愁。溶溶泄泄，东风无力，欲皱还休。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1751, "title": "卜算子", "author": "游次公", "body": "风雨送人来，风雨留人住。草草杯柈话别离，风雨催人去。 泪眼不曾晴，眉黛愁还聚。明日相思莫上楼，楼上多风雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1752, "title": "八声甘州", "author": "王质", "body": "读诸葛武侯①传\n过隆中。桑柘②倚斜阳，禾黍战悲风。世若无徐庶③，更无庞统④，沉了英雄。本计东荆西益⑤，观变取奇功。转尽青天粟⑥，无路能通。 他日杂耕渭上，忽一星飞堕⑦，万事成空。使一曹三马，云雨动蛟龙⑧。看璀璨⑨、出师一表，照乾坤、牛斗气常冲。千年后，锦城⑩相吊，遇草堂翁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1753, "title": "好事近", "author": "杨万里", "body": "月未到诚斋，先到万花川谷。不是诚斋无月，隔一庭修竹。\n如今才是十三夜，月色已如玉。未是秋光奇艳，看十五十六。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1754, "title": "昭君怨 咏荷上雨", "author": "杨万里", "body": "午梦扁舟花底，香满西湖烟水。急雨打篷声，梦初惊。\n却是池荷跳雨，散了真珠还聚。聚作水银窝，泛清波。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1755, "title": "水调歌头", "author": "朱熹", "body": "隐括杜牧之齐山诗\n江水浸云影，鸿雁欲南飞。携壶结客何处？空翠渺烟霏。尘世难逢一笑，况有紫萸黄菊，堪插满头归。风景今朝是，身世昔人非。 酬佳节，须酩酊，莫相违。人生如寄，何事辛苦怨斜晖。无尽今来古往，多少春花秋月，那更有危机。与问牛山客，何必独沾衣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1756, "title": "如梦令", "author": "严蕊", "body": "道是梨花不是。道是杏花不是。白白与红红，别是东风情味。曾记。曾记。人在武陵微醉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1757, "title": "卜算子", "author": "严蕊", "body": "不是爱风尘，似被前缘误。花落花开自有时，总赖东君主。\n去也终须去，住也如何住！若得山花插满头，莫问奴归处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1758, "title": "六州歌头", "author": "张孝祥", "body": "长淮望断，关塞莽然平。征尘暗，霜风劲，悄边声。黯销凝。追想当年事，殆天数，非人力；洙泗上，弦歌地，亦膻腥。隔水毡乡，落日牛羊下，区脱纵横。看名王宵猎，骑火一川明，笳鼓悲鸣，遣人惊。 念腰间箭，匣中剑，空埃蠹，竟何成！时易失，心徒壮，岁将零。渺神京。干羽方怀远，静烽燧，且休兵。冠盖使，纷驰骛，若为情！闻道中原遗老，常南望、翠葆霓旌。使行人到此，忠愤气填膺，有泪如倾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1759, "title": "水调歌头 泛湘江", "author": "张孝祥", "body": "濯足夜滩急，晞发北风凉。吴山楚泽行徧，只欠到潇湘。买得扁舟归去，此事天公付我，六月下沧浪。蝉蜕尘埃外，蝶梦水云乡。 制荷衣，纫兰佩，把琼芳。湘妃起舞一笑，抚瑟奏清商。唤起九歌忠愤，拂拭三闾文字，还与日争光。莫遣儿辈觉，此乐未渠央。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1760, "title": "水调歌头 金山观月", "author": "张孝祥", "body": "江山自雄丽，风露与高寒。寄声月姊，借我玉鉴此中看。幽壑鱼龙悲啸，倒影星辰摇动，海气夜漫漫。涌起白银阙，危驻紫金山。 表独立，飞霞珮，切云冠。漱冰濯雪，眇视万里一毫端。回首三山何处，闻道群仙笑我，要我欲俱还。挥手从此去，翳凤更骖鸾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1761, "title": "水调歌头 闻采石战胜", "author": "张孝祥", "body": "雪洗虏尘静，风约楚云留。何人为写悲壮，吹角古城楼？湖海平生豪气①，关塞如今风景，剪烛看吴钩②。剩喜③然犀处④，骇浪与天浮。 忆当年，周与谢，富春秋。小乔初嫁，香囊未解，勋业故优游。赤壁矶头落照，肥水桥边衰草，渺渺唤人愁。我欲乘风去⑤，击楫誓中流⑥。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1762, "title": "木兰花慢", "author": "张孝祥", "body": "送归云去雁，淡寒采满溪楼。正佩解湘腰，钗孤楚鬓，鸾鉴分收。凝情望行处路，但疏烟远树织离忧。只有楼前流水，伴人清泪长流。 霜华夜永逼衾裯，唤谁护衣篝？念粉馆重来，芳尘未扫，争见嬉游！情知闷来殢酒，奈回肠不醉只添愁。脉脉无言竟日，断魂双鹜南州。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1763, "title": "木兰花慢", "author": "张孝祥", "body": "紫箫吹散后，恨燕子、只空楼。念璧月长亏，玉簪中断，覆水难收。青鸾送碧云句，道霞扃雾锁不堪忧。情与文梭共织，怨随宫叶同流。 人间天上两悠悠，暗泪洒灯篝。记谷口园林，当时驿舍，梦里曾游。银屏低闻笑语，但梦时冉冉醒时愁。拟把菱花一半，试寻高价皇州。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1764, "title": "念奴娇 过洞庭", "author": "张孝祥", "body": "洞庭青草，近中秋、更无一点风色。玉鉴琼田三万顷，着我扁舟一叶。素月分辉，明河共影，表里俱澄澈。悠然心会，妙处难与君说。 应念岭表经年，孤光自照，肝胆皆冰雪。短发萧疏襟袖冷，稳泛沧溟空阔。尽吸西江，细斟北斗，万象为宾客。扣舷独啸，不知今夕何夕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1765, "title": "雨中花慢", "author": "张孝祥", "body": "一叶凌波，十里驭风，烟鬟雾鬓萧萧。认得兰皋琼珮，水馆冰绡。秋霁明霞乍吐，曙凉宿霭初消。恨微颦不语，少进还收，伫立超遥。 神交冉冉，愁思盈盈，断魂欲遣谁招。犹自待、青鸾传信，乌鹊成桥。怅望胎仙琴叠，忍看翡翠兰苕。梦回人远，红云一片，天际笙箫。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1766, "title": "转调二郎神", "author": "张孝祥", "body": "闷来无那，暗数尽、残更不寐。念楚馆香车，吴溪兰棹，多少愁云恨水。阵阵回风吹雪霰，更旅雁、一声沙际。想静拥孤衾，频挑寒灺，数行珠泪。 凝睇。傍人笑我，终朝如醉。便锦织回鸾，素传双鲤，难写衷肠密意。绿鬓点霜，玉肌消雪，两处十分憔悴。争忍见、旧时娟娟素月，照人千里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1767, "title": "浣溪沙 洞庭", "author": "张孝祥", "body": "行尽潇湘到洞庭。楚天阔处数峰青。旗梢不动晚波平。\n红蓼一湾纹缬乱，白鱼双尾玉刀明。夜凉船影浸疏星。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1768, "title": "浣溪沙", "author": "张孝祥", "body": "霜日明霄水蘸空，鸣鞘声里绣旗红，澹烟衰草有无中。\n万里中原烽火北，一尊浊酒戍楼东，酒阑挥泪向悲风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1769, "title": "西江月", "author": "张孝祥", "body": "题溧阳三塔寺\n问讯湖边春色，重来又是三年。东风吹我过湖船，杨柳丝丝拂面。 世路如今已惯，此心到处悠然。寒光亭下水连天，飞起沙鸥一片。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1770, "title": "西江月 黄陵庙", "author": "张孝祥", "body": "满载一船明月，平铺千里秋江。波神留我看斜阳，唤起鳞鳞细浪。 明日风回更好，今朝露宿何妨。水晶宫里奏霓裳，准拟岳阳楼上。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1771, "title": "生查子", "author": "张孝祥", "body": "远山眉黛横，媚柳开青眼。楼阁断霞明，帘幕春寒浅。\n杯延玉漏迟，烛怕金刀剪。明月忽飞来，花影和帘卷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1772, "title": "念奴娇", "author": "张孝祥", "body": "风帆更起，望一天秋色，离愁无数。明日重阳尊酒里，谁与黄花为主？别岸风烟，孤舟灯火，今夕知何处？不如江月，照伊清夜同去。 船过采石江边，望夫山下，酌水应怀古。德耀归来，虽富贵，忍弃平生荆布！默想音容，遥怜儿女，独立衡皋暮。桐乡君子，念予憔悴如许！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1773, "title": "水调歌头 过岳阳楼作", "author": "张孝祥", "body": "湖海倦游客，江汉有归舟。西风千里，送我今夜岳阳楼。日落君山云气，春到沅湘草木，远思渺难收。徙倚栏干久，缺月挂帘钩。 雄三楚，吞七泽，隘九州。人间好处，何处更似此楼头？欲吊沉累无所，但有渔儿樵子，哀此写离忧。回首叫虞舜，杜若满芳洲。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1774, "title": "探春令", "author": "赵长卿", "body": "笙歌间错华筵启。喜新春新岁。菜传纤手，青丝轻细。和气入、东风里。 幡儿胜儿都姑媂。戴得更忔戏。愿新春以后，吉吉利利，百事都如意。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1775, "title": "临江仙 暮春", "author": "赵长卿", "body": "过尽征鸿来尽燕，故园消息茫然。一春憔悴有谁怜？怀家寒食夜，中酒落花天。 见说江头春浪渺，殷勤欲送归船。别来此处最萦牵。短篷南浦雨，疏柳断桥烟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1776, "title": "阮郎归 客中见梅", "author": "赵长卿", "body": "年年为客遍天涯。梦迟归路赊。无端星月浸窗纱。一枝寒影斜。 肠未断，鬓先华。新来瘦转加。角声吹彻《小梅花》。夜长人忆家。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1777, "title": "更漏子", "author": "赵长卿", "body": "烛消红，窗送白，冷落一衾寒色。鸦唤起，马跎行，月来衣上明。 酒香唇，妆印臂，忆共人人①睡。魂蝶乱，梦鸾孤，知他睡也无？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1778, "title": "瑞鹤仙", "author": "赵长卿", "body": "归宁都，因成，寄暖香诸院。\n无言屈指也。算年年底事，长为旅也。凄惶受尽也。把良辰美景，总成虚也。自嗟叹也。这情怀、如何诉也。谩愁明怕暗，单栖独宿，怎生禁也。 闲也。有时临镜，渐觉形容，日销减也。光阴换也。空辜负、少年也。念仙源深处，暖香小院，赢得群花怨也。是亏他，见了多教骂几句也。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1779, "title": "水调歌头", "author": "京镗", "body": "伏蒙都运、都大、判院以某新建驷马楼落成有日①，宠赐佳词，为郡邑之光②，辄勉继严韵③，以谢万分④。\n百堞⑤龟城北，江势远连空。杠梁济涉⑥，浑似溪涧饮长虹⑦。覆以翚飞⑧华宇，载以鱼浮⑨叠石，守护有神龙⑩。好看发源水，滚滚尽流东。 司马氏，凌云气⑪，盖群公。当年题柱，从此奏赋动天容⑫。果驾轺车⑬使蜀，能致诸蛮臣汉⑭，邛筰⑮道仍通。寄语登桥者，努力继前功。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1780, "title": "江城子 癸酉春社", "author": "王炎", "body": "清波渺渺日晖晖，柳依依，草离离。老大逢春，情绪有谁知？帘箔四垂庭院静，人独处，燕双飞。 怯寒未敢试春衣。踏青时，懒追随。野蔌山肴，村酿可从宜。不向花边拚一醉，花不语，笑人痴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1781, "title": "南柯子", "author": "王炎", "body": "山冥云阴重，天寒雨意浓。数枝幽艳湿啼红。莫为惜花惆怅对东风。 蓑笠朝朝出，沟塍处处通。人间辛苦是三农。要得一犁水足望年丰。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1782, "title": "卜算子", "author": "杨冠卿", "body": "秋晚集杜句吊贾傅\n苍生喘未苏，贾笔论孤愤①。文采风流今尚存，毫发无遗恨。 凄恻近长沙，地僻秋将尽。长使英雄泪满襟，天意高难问。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1783, "title": "摸鱼儿", "author": "辛弃疾", "body": "淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，为赋。\n更能消、几番风雨？匆匆春又归去。惜春长怕花开早，何况落红无数。春且住。见说道、天涯芳草无归路。怨春不语。算只有殷勤，画檐蛛网，尽日惹飞絮。 长门事，准拟佳期又误。蛾眉曾有人妒。千金纵买相如赋，脉脉此情谁诉？君莫舞，君不见、玉环飞燕皆尘土！闲愁最苦。休去倚危栏，斜阳正在、烟柳断肠处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1784, "title": "沁园春", "author": "辛弃疾", "body": "带湖新居将成\n三径初成，鹤怨猿惊，稼轩未来。甚云山自许，平生意气；衣冠人笑，抵死尘埃。意倦须还，身闲贵早，岂为莼羹鲈脍哉？秋江上，看惊弦雁避，骇浪船回。 东冈更葺茅斋。好都把轩窗临水开。要小舟行钓，先应种柳；疏篱护竹，莫碍观梅。秋菊堪餐，春兰可佩，留待先生手自栽。沉吟久，怕君恩未许，此意徘徊。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1785, "title": "水龙吟", "author": "辛弃疾", "body": "甲辰岁寿韩南涧尚书\n渡江天马南来①，几人真是经纶手？长安父老②，新亭风景③，可怜依旧！夷甫诸人，神州沉陆④，几曾回首！算平戎万里，功名本是，真儒事，公知否？ 况有文章山斗⑤，对桐阴⑥、满庭清昼。当年堕地，而今试看，风云奔走。绿野风烟⑦，平泉草木⑧，东山歌酒⑨。待他年，整顿乾坤事了，为先生寿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1786, "title": "水龙吟", "author": "辛弃疾", "body": "登建康赏心亭\n楚天千里清秋，水随天去秋无际。遥岑远目，献愁供恨，玉簪螺髻。落日楼头，断鸿声里，江南游子。把吴钩看了，栏干拍遍，无人会、登临意。 休说鲈鱼堪脍，尽西风、季鹰归未？求田问舍，怕应羞见，刘郎才气。可惜流年，忧愁风雨，树犹如此！倩何人唤取，红巾翠袖，揾英雄泪！\n宋人词意\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1787, "title": "满江红", "author": "辛弃疾", "body": "江行和杨济翁韵\n过眼溪山，怪都似、旧时曾识。还记得、梦中行遍，江南江北。佳处径须携杖去，能消几两平生屐？笑尘劳、三十九年非，长为客。 吴楚地，东南坼。英雄事，曹刘敌。被西风吹尽，了无陈迹。楼观才成人已去，旌旗未卷头先白。叹人间、哀乐转相寻，今犹昔。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1788, "title": "水调歌头 盟鸥", "author": "辛弃疾", "body": "带湖吾甚爱，千丈翠奁开。先生杖屦无事，一日走千回。凡我同盟鸥鹭，今日既盟之后，来往莫相猜。白鹤在何处？尝试与偕来。 破青萍，排翠藻，立苍苔。窥鱼笑汝痴计，不解举吾杯。废沼荒丘畴昔，明月清风此夜，人世几欢哀？东岸绿阴少，杨柳更须栽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1789, "title": "水调歌头", "author": "辛弃疾", "body": "汤朝美司谏见和，用韵为谢\n白日射金阙，虎豹九关开。见君谏疏频上，谈笑挽天回。千古忠肝义胆，万里蛮烟瘴雨，往事莫惊猜。政恐不免耳，消息日边来。 笑吾庐，门掩草，径封苔。未应两手无用，要把蟹螯杯。说剑论诗余事，醉舞狂歌欲倒，老子颇堪哀。白发宁有种？一一醒时栽！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1790, "title": "水调歌头", "author": "辛弃疾", "body": "舟次扬州，和杨济翁、周显先韵。\n落日塞尘起，胡骑猎清秋。汉家组练十万，列舰耸层楼。谁道投鞭飞渡，忆昔鸣髇血污，风雨佛狸愁。季子正年少，匹马黑貂裘。 今老矣，搔白首，过扬州。倦游欲去江上，手种橘千头。二客东南名胜，万卷诗书事业，尝试与君谋。莫射南山虎，直觅富民侯。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1791, "title": "念奴娇", "author": "辛弃疾", "body": "登建康赏心亭①，呈史留守致道②\n我来吊古，上危楼，赢得闲愁千斛③。虎踞龙蟠何处是？只有兴亡满目。柳外斜阳，水边归鸟，陇上吹乔木。片帆西去，一声谁喷霜竹④？ 却忆安石风流，东山岁晚⑤，泪落哀筝曲⑥。儿辈功名都付与，长日惟消棋局。宝镜难寻，碧云将暮，谁劝杯中绿⑦？江头风怒，朝来波浪翻屋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1792, "title": "念奴娇 书东流村壁", "author": "辛弃疾", "body": "野棠花落，又匆匆过了，清明时节。刬地东风欺客梦，一枕云屏寒怯。曲岸持觞，垂杨系马，此地曾轻别。楼空人去，旧游飞燕能说。 闻道绮陌东头，行人长见，帘底纤纤月。旧恨春江流不断，新恨云山千叠。料得明朝，尊前重见，镜里花难折。也应惊问：近来多少华发？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1793, "title": "鹧鸪天 代人赋", "author": "辛弃疾", "body": "晚日寒鸦一片愁，柳塘新绿却温柔。若教眼底无离恨，不信人间有白头。 肠已断，泪难收。相思重上小红楼。情知已被山遮断，频倚阑干不自由。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1794, "title": "鹧鸪天 送人", "author": "辛弃疾", "body": "唱彻《阳关》泪未干，功名馀事且加餐。浮天水送无穷树，带雨云埋一半山。 今古恨，几千般，只应离合是悲欢？江头未是风波恶，别有人间行路难。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1795, "title": "鹧鸪天 东阳道中", "author": "辛弃疾", "body": "扑面征尘去路遥，香篝渐觉水沉销。山无重数周遭碧，花不知名分外娇。 人历历，马萧萧，旌旗又过小红桥。愁边剩有相思句，摇断吟鞭碧玉梢。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1796, "title": "鹧鸪天", "author": "辛弃疾", "body": "鹅湖①归，病起作。\n枕簟溪堂②冷欲秋，断云依水晚来收。红莲相倚浑如醉，白鸟无言定自愁。 书咄咄，且休休。一丘一壑也风流。不知筋力衰多少，但觉新来懒上楼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1797, "title": "丑奴儿近", "author": "辛弃疾", "body": "博山道中效李易安体\n千峰云起，骤雨一霎儿价。更远树斜阳，风景怎生图画？青旗卖酒，山那畔别有人家。只消山水光中，无事过这一夏。\n午醉醒时，松窗竹户，万千潇洒。野鸟飞来，又是一般闲暇。却怪白鸥，觑着人欲下未下。旧盟都在，新来莫是，别有说话？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1798, "title": "蝶恋花", "author": "辛弃疾", "body": "月下醉书雨岩①石浪\n九畹芳菲兰佩好。空谷无人，自怨蛾眉巧。宝瑟泠泠千古调，朱丝弦断知音少。 冉冉年华吾自老。水满汀洲，何处寻芳草？唤起湘累②歌未了，石龙舞罢松风晓。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1799, "title": "菩萨蛮", "author": "辛弃疾", "body": "书江西造口壁\n郁孤台下清江水，中间多少行人泪。西北望长安，可怜无数山。 青山遮不住，毕竟东流去。江晚正愁余，山深闻鹧鸪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1800, "title": "菩萨蛮", "author": "辛弃疾", "body": "金陵赏心亭为叶丞相赋\n青山欲共高人语，联翩万马来无数。烟雨却低回，望来终不来。 人言头上发，总向愁中白。拍手笑沙鸥，一身都是愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1801, "title": "木兰花慢", "author": "辛弃疾", "body": "席上送张仲固帅兴元\n汉中开汉业，问此地，是耶非？想剑指三秦，君王得意，一战东归。追亡事，今不见；但山川满目泪沾衣。落日胡尘未断，西风塞马空肥。 一编书是帝王师，小试去征西。更草草离筵，匆匆去路，愁满旌旗。君思我，回首处，正江涵秋影雁初飞。安得车轮四角，不堪带减腰围。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1802, "title": "木兰花慢", "author": "辛弃疾", "body": "滁州送范倅①\n老来情味减，对别酒，怯流年。况屈指中秋，十分好月，不照人圆。无情水都不管，共西风、只管送归船。秋晚莼鲈②江上，夜深儿女灯前③。 征衫，便好去朝天，玉殿正思贤。想夜半承明，留教视草，却遣筹边。长安故人问我，道愁肠殢酒只依然。目断秋霄落雁，醉来时响空弦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1803, "title": "祝英台近 晚春", "author": "辛弃疾", "body": "宝钗分①，桃叶渡②，烟柳暗南浦③。怕上层楼，十日九风雨。断肠片片飞红，都无人管，更谁劝啼莺声住？ 鬓边觑。试把花卜心期，才簪又重数。罗帐灯昏，哽咽梦中语：是他春带愁来，春归何处？却不解带将愁去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1804, "title": "青玉案", "author": "辛弃疾", "body": "东风夜放花千树。更吹落，星如雨。宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞。 蛾儿雪柳黄金缕，笑语盈盈暗香去。众里寻他千百度，——蓦然回首，那人却在，灯火阑珊处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1805, "title": "阮郎归", "author": "辛弃疾", "body": "耒阳道中为张处父推官赋\n山前灯火欲黄昏，山头来去云。鹧鸪声里数家村，潇湘逢故人①。 挥羽扇，整纶巾，少年鞍马尘。如今憔悴赋招魂，儒冠多误身。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1806, "title": "清平乐", "author": "辛弃疾", "body": "博山道中即事\n柳边飞鞚①，露湿征衣重。宿鹭窥沙孤影动，应有鱼虾入梦。 一川明月疏星，浣纱人影娉婷②。笑背行人归去，门前稚子啼声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1807, "title": "清平乐 村居", "author": "辛弃疾", "body": "茅檐低小，溪上青青草。醉里吴音相媚好，白发谁家翁媪。 大儿锄豆溪东，中儿正织鸡笼；最喜小儿无赖，溪头卧剥莲蓬。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1808, "title": "清平乐", "author": "辛弃疾", "body": "独宿博山王氏庵\n绕床饥鼠，蝙蝠翻灯舞。屋上松风吹急雨，破纸窗间自语。\n平生塞北江南，归来华发苍颜。布被秋宵梦觉，眼前万里江山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1809, "title": "清平乐", "author": "辛弃疾", "body": "检校山园，书所见\n连云松竹，万事从今足。拄杖东家分社肉，白酒床头初熟。\n西风梨枣山园，儿童偷把长竿。莫遣旁人惊去，老夫静处闲看。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1810, "title": "山鬼谣", "author": "辛弃疾", "body": "雨岩有石，状怪甚，取《离骚》《九歌》，名曰“山鬼”，因赋《摸鱼儿》，改今名。\n问何年、此山来此？西风落日无语。看君似是羲皇上，直作太初名汝。溪上路，算只有、红尘不到今犹古。一杯谁举？笑我醉呼君，崔嵬①未起，山鸟覆杯去。 须记取：昨夜龙湫风雨，门前石浪掀舞。四更山鬼吹灯②啸，惊倒世间儿女。依约③处，还问我：清游杖履公良苦。神交心许。待万里携君，鞭笞鸾凤，诵我《远游》赋。石浪，庵外巨石也，长三十余丈。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1811, "title": "满江红 题冷泉亭", "author": "辛弃疾", "body": "直节堂堂，看夹道冠缨拱立。渐翠谷、群仙东下，珮环声急。谁信天峰飞堕地，傍湖千丈开青壁。是当年、玉斧削方壶，无人识。 山木润，琅玕湿。秋露下，琼珠滴。向危亭横跨，玉渊澄碧。醉舞且摇鸾凤影，浩歌莫遣鱼龙泣。恨此中、风物本吾家，今为客。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1812, "title": "满江红", "author": "辛弃疾", "body": "饯郑衡州厚卿席上再赋\n莫折荼䕷，且留取一分春色。还记得，青梅如豆，共伊同摘。少日对花浑醉梦，而今醒眼看风月。恨牡丹笑我倚东风，头如雪。 榆荚阵，菖蒲叶。时节换，繁华歇。算怎禁风雨，怎禁鹈鴂！老冉冉兮花共柳，是栖栖者蜂和蝶。也不因春去有闲愁，因离别。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1813, "title": "满江红", "author": "辛弃疾", "body": "敲碎离愁，纱窗外、风摇翠竹。人去后、吹箫声断，倚楼人独。满眼不堪三月暮，举头已觉千山绿。但试把一纸寄来书，从头读。 相思字，空盈幅；相思意，何时足？滴罗襟点点，泪珠盈掬。芳草不迷行客路，垂杨只碍离人目。最苦是、立尽月黄昏，阑干曲。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1814, "title": "满江红 暮春", "author": "辛弃疾", "body": "家住江南，又过了、清明寒食。花径里、一番风雨，一番狼藉。红粉暗随流水去，园林渐觉清阴密。算年年、落尽刺桐花，寒无力。 庭院静，空相忆。无说处，闲愁极。怕流莺乳燕，得知消息。尺素如今何处也，绿云依旧无踪迹。谩教人、羞去上层楼，平芜碧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1815, "title": "贺新郎", "author": "辛弃疾", "body": "陈同父自东阳来过余，留十日。与之同游鹅湖，且会朱晦庵于紫溪，不至，飘然东归。既别之明日，余意中殊恋恋，复欲追路。至鹭鸶林，则雪深泥滑，不得前矣。独饮方村，怅然久之，颇恨挽留之不遂也。夜半投宿吴氏泉湖四望楼，闻邻笛悲甚，为赋《贺新郎》以见意。又五日，同父书来索词，心所同然者如此，可发千里一笑。\n把酒长亭说。看渊明、风流酷似，卧龙诸葛。何处飞来林间鹊，蹙踏松梢微雪。要破帽多添华发。剩水残山无态度，被疏梅料理成风月。两三雁，也萧瑟。 佳人重约还轻别。怅清江、天寒不渡，水深冰合。路断车轮生四角，此地行人销骨。问谁使、君来愁绝？铸就而今相思错，料当初、费尽人间铁。长夜笛，莫吹裂。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1816, "title": "贺新郎", "author": "辛弃疾", "body": "同父见和再用韵答之\n老大那堪说。似而今、元龙①臭味，孟公②瓜葛。我病君来高歌饮，惊散楼头飞雪。笑富贵千钧如发。硬语盘空谁来听？记当时、只有西窗月。重进酒，换鸣瑟。 事无两样人心别。问渠侬：神州毕竟，几番离合？汗血盐车③无人顾，千里空收骏骨④。正目断关河路绝。我最怜君中宵舞⑤，道“男儿到死心如铁”。看试手，补天裂。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1817, "title": "贺新郎", "author": "辛弃疾", "body": "用前韵送杜叔高\n细把君诗说：恍余音、钧天浩荡①，洞庭胶葛②。千丈阴崖尘不到，惟有层冰积雪。乍一见、寒生毛发。自昔佳人多薄命，对古来、一片伤心月。金屋③冷，夜调瑟。 去天尺五君家别。看乘空、鱼龙惨淡，风云开合。起望衣冠神州路，白日消残战骨。叹夷甫④诸人清绝！夜半狂歌悲风起，听铮铮、阵马檐间铁⑤。南共北，正分裂！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1818, "title": "贺新郎 赋琵琶", "author": "辛弃疾", "body": "凤尾龙香拨，自开元霓裳曲罢，几番风月？最苦浔阳江头客，画舸亭亭待发。记出塞、黄云堆雪。马上离愁三万里，望昭阳宫殿孤鸿没，弦解语，恨难说。 辽阳驿使音尘绝，琐窗寒，轻拢慢撚，泪珠盈睫。推手含情还却手，一抹《梁州》哀彻。千古事，云飞烟灭。贺老定场无消息，想沉香亭北繁华歇。弹到此，为呜咽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1819, "title": "念奴娇", "author": "辛弃疾", "body": "瓢泉酒酣，和东坡韵。\n倘来轩冕，问还是、今古人间何物？旧日重城愁万里，风月而今坚壁。药笼功名，酒垆身世，可惜蒙头雪。浩歌一曲，坐中人物三杰。 休叹黄菊凋零，孤标应也有，梅花争发。醉里重揩西望眼，惟有孤鸿明灭。万事从教，浮云来去，枉了冲冠发。故人何在？长庚应伴残月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1820, "title": "水龙吟", "author": "辛弃疾", "body": "用些语再题瓢泉，歌以饮客，声韵甚谐，客为之釂。\n听兮清珮琼瑶些。明兮镜秋毫些。君无去此，流昏涨腻，生蓬蒿些。虎豹甘人，渴而饮汝，宁猿猱些。大而流江海，覆舟如芥，君无助、狂涛些。 路险兮山高些。块予独处无聊些。冬槽春盎，归来为我，制松醪些。其外芳芬，团龙片凤，煮云膏些。古人兮既往，嗟予之乐，乐箪瓢些。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1821, "title": "最高楼", "author": "辛弃疾", "body": "吾拟乞归，犬子以田产未置止我，赋此骂之。\n吾衰矣，须富贵何时？富贵是危机。暂忘设醴抽身去，未曾得米弃官归。穆先生，陶县令，是吾师。 待葺个园儿名“佚老”，更作个亭儿名“亦好”，闲饮酒，醉吟诗。千年田换八百主，一人口插几张匙？便休休，更说甚，是和非！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1822, "title": "水龙吟", "author": "辛弃疾", "body": "过南剑双溪楼\n举头西北浮云，倚天万里须长剑。人言此地，夜深长见，斗牛光焰。我觉山高，潭空水冷，月明星淡。待燃犀下看，凭栏却怕，风雷怒，鱼龙惨。 峡束苍江对起，过危楼，欲飞还敛。元龙老矣！不妨高卧，冰壶凉簟。千古兴亡，百年悲笑，一时登览。问何人又卸，片帆沙岸，系斜阳缆？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1823, "title": "鹧鸪天 代人赋", "author": "辛弃疾", "body": "陌上柔桑破嫩芽，东邻蚕种已生些。平岗细草鸣黄犊，斜日寒林点暮鸦。 山远近，路横斜，青旗沽酒有人家。城中桃李愁风雨，春在溪头荠菜花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1824, "title": "鹧鸪天", "author": "辛弃疾", "body": "游鹅湖，醉书酒家壁。\n春入平原荠菜花，新耕雨后落群鸦。多情白发春无奈，晚日青帘酒易赊。 闲意态，细生涯。牛栏西畔有桑麻。青裙缟袂谁家女，去趁蚕生看外家。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1825, "title": "西江月", "author": "辛弃疾", "body": "夜行黄沙道中\n明月别枝惊鹊，清风半夜鸣蝉。稻花香里说丰年，听取蛙声一片。 七八个星天外，两三点雨山前。旧时茅店社林边，路转溪桥忽见。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1826, "title": "鹊桥仙", "author": "辛弃疾", "body": "己酉山行书所见\n松冈避暑，茅檐避雨，闲去闲来几度？醉扶怪石看飞泉，又却是、前回醒处。 东家娶妇，西家归女，灯火门前笑语。酿成千顷稻花香，夜夜费、一天风露。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1827, "title": "蝶恋花", "author": "辛弃疾", "body": "戊申元日立春席间作\n谁向椒盘簪彩胜？整整韶华，争上春风鬓。往日不堪重记省，为花长把新春恨。 春未来时先借问，晚恨开迟，早又飘零近。今岁花期消息定，只愁风雨无凭准。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1828, "title": "生查子 独游雨岩", "author": "辛弃疾", "body": "溪边照影行，天在清溪底。天上有行云，人在行云里。\n高歌谁和余？空谷清音起。非鬼亦非仙，一曲桃花水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1829, "title": "忆王孙", "author": "辛弃疾", "body": "秋江送别，集古句\n登山临水送将归。悲莫悲兮生别离。不用登临怨落晖。昔人非。惟有年年秋雁飞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1830, "title": "木兰花慢", "author": "辛弃疾", "body": "中秋饮酒将旦，客谓前人诗词有赋待月，无送月者，因用《天问》体赋。\n可怜今夕月，向何处、去悠悠？是别有人间，那边才见，光影东头？是天外空汗漫，但长风浩浩送中秋？飞镜无根谁系？姮娥不嫁谁留？ 谓经海底问无由，恍惚使人愁。怕万里长鲸，纵横触破，玉殿琼楼。虾蟆故堪浴水，问云何玉兔解沉浮？若道都齐无恙，云何渐渐如钩？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1831, "title": "八声甘州", "author": "辛弃疾", "body": "夜读《李广传》，不能寐。因念晁楚老、杨民瞻约同居山间，戏用李广事，赋以寄之。\n故将军饮罢夜归来，长亭解雕鞍。恨灞陵醉尉，匆匆未识，桃李无言①。射虎山横一骑，裂石响惊弦。落魄封侯事，岁晚田园。 谁向桑麻杜曲，要短衣匹马，移住南山②？看风流慷慨，谈笑过残年。汉开边、功名万里，甚当时、健者也曾闲？纱窗外、斜风细雨，一阵轻寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1832, "title": "水调歌头", "author": "辛弃疾", "body": "壬子三山被召，陈端仁给事饮饯席上作\n长恨复长恨，裁作短歌行。何人为我楚舞，听我楚狂声？余既滋兰九畹，又树蕙之百亩，秋菊更餐英。门外沧浪水，可以濯吾缨。 一杯酒，问何似，身后名？人间万事，毫发常重泰山轻。悲莫悲生离别，乐莫乐新相识，儿女古今情。富贵非吾事，归与白鸥盟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1833, "title": "贺新郎", "author": "辛弃疾", "body": "别茂嘉十二弟\n绿树听鹈鴂，更那堪、鹧鸪声住，杜鹃声切。啼到春归无寻处，苦恨芳菲都歇。算未抵、人间离别。马上琵琶关塞黑，更长门翠辇辞金阙。看燕燕，送归妾。 将军百战身名裂。向河梁、回头万里，故人长绝。易水萧萧西风冷，满座衣冠似雪。正壮士、悲歌未彻。啼鸟还知如许恨，料不啼清泪长啼血。谁共我，醉明月？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1834, "title": "贺新郎", "author": "辛弃疾", "body": "邑中园亭，仆皆为赋此词。一日，独坐停云，水声山色竞来相娱。意溪山欲援例者，遂作数语，庶几仿佛渊明思亲友之意云。\n甚矣吾衰矣。怅平生、交游零落，只今馀几！白发空垂三千丈，一笑人间万事。问何物、能令公喜？我见青山多妩媚，料青山见我应如是。情与貌，略相似。 一尊搔首东窗里。想渊明《停云》诗就，此时风味。江左沉酣求名者，岂识浊醪妙理？回首叫、云飞风起。不恨古人吾不见，恨古人不见吾狂耳。知我者，二三子。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1835, "title": "沁园春", "author": "辛弃疾", "body": "将止酒，戒酒杯使勿近。\n杯汝来前！老子今朝，点检形骸。甚长年抱渴，咽如焦釜；于今喜睡，气似奔雷。汝说“刘伶，古今达者，醉后何妨死便埋”。浑如此，叹汝于知己，真少恩哉！ 更凭歌舞为媒，算合作人间鸩毒猜。况怨无大小，生于所爱；物无美恶，过则为灾。与汝成言，勿留亟退，吾力犹能肆汝杯。杯再拜，道“麾之即去，招则须来”。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1836, "title": "感皇恩", "author": "辛弃疾", "body": "读《庄子》，闻朱晦庵即世\n案上数编书，非庄即老。会说忘言始知道；万言千句，不自能忘堪笑。今朝梅雨霁，青天好。 一壑一丘，轻衫短帽。白发多时故人少。子云何在，应有玄经遗草。江河流日夜，何时了。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1837, "title": "粉蝶儿", "author": "辛弃疾", "body": "和晋臣赋落花\n昨日春如十三女儿学绣，一枝枝不教花瘦。甚无情便下得雨僝风僽，向园林铺作地衣红绉。 而今春似轻薄荡子难久。记前时送春归后。把春波都酿作一江春酎，约清愁杨柳岸边相候。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1838, "title": "丑奴儿", "author": "辛弃疾", "body": "书博山道中壁\n少年不识愁滋味，爱上层楼。爱上层楼，为赋新词强说愁。\n而今识尽愁滋味，欲说还休。欲说还休，却道天凉好个秋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1839, "title": "踏莎行", "author": "辛弃疾", "body": "赋稼轩，集经句。\n进退存亡，行藏用舍。小人请学樊须稼。衡门之下可栖迟，日之夕矣牛羊下。 去卫灵公，遭桓司马。东西南北之人也。长沮桀溺耦而耕，丘何为是栖栖者①？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1840, "title": "汉宫春 立春日", "author": "辛弃疾", "body": "春已归来，看美人头上，袅袅春幡。无端风雨，未肯收尽余寒。年时燕子，料今宵、梦到西园。浑未办、黄柑荐酒，更传青韭堆盘？ 却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜。清愁不断，问何人、会解连环？生怕见、花开花落，朝来塞雁先还。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1841, "title": "鹧鸪天", "author": "辛弃疾", "body": "寻菊花无有，戏作\n掩鼻人间臭腐场，古今惟有酒偏香。自从来住云烟畔，直到而今歌舞忙。 呼老伴，共秋光。黄花何处避重阳？要知烂熳开时节，直待秋风一夜霜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1842, "title": "太常引", "author": "辛弃疾", "body": "建康中秋夜，为吕叔潜赋\n一轮秋影转金波。飞镜又重磨。把酒问姮娥：被白发欺人奈何？ 乘风好去，长空万里，直下看山河。斫去桂婆娑，人道是清光更多。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1843, "title": "清平乐", "author": "辛弃疾", "body": "忆吴江赏木樨\n少年痛饮，忆向吴江醒。明月团团高树影，十里水沉烟冷。\n大都一点宫黄，人间直恁芬芳。怕是秋天风露，染教世界都香。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1844, "title": "水龙吟", "author": "辛弃疾", "body": "老来曾识渊明，梦中一见参差是。觉来幽恨，停觞不御，欲歌还止。白发西风，折腰五斗，不应堪此。问北窗高卧，东篱自醉，应别有，归来意。 须信此翁未死，到如今凛然生气。吾侪心事，古今长在，高山流水。富贵他年，直饶未免，也应无味。甚东山何事，当时也道，为苍生起。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1845, "title": "水调歌头", "author": "辛弃疾", "body": "赵昌父七月望日用东坡韵叙太白、东坡事见寄，过相褒借，且有秋水之约。八月十四日余卧病博山寺中，因用韵为谢，兼寄吴子似。\n我志在寥阔，畴昔梦登天。摩挲素月，人世俯仰已千年。有客骖鸾并凤，云遇青山赤壁，相约上高寒。酌酒援北斗，我亦蝨其间。 少歌曰：“神甚放，形则眠。鸿鹄一再高举，天地睹方圆。”欲重歌兮梦觉，推枕惘然独念：人事底亏全？有美人可语，秋水隔婵娟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1846, "title": "沁园春", "author": "辛弃疾", "body": "灵山齐庵赋，时筑偃湖未成①\n叠嶂西驰，万马回旋，众山欲东。正惊湍直下，跳珠倒溅；小桥横截，缺月初弓。老合投闲，天教多事，检校长身十万松。吾庐小，在龙蛇影外，风雨声中。 争先见面重重，看爽气朝来三数峰。似谢家子弟，衣冠磊落②；相如庭户，车骑雍容③。我觉其间，雄深雅健，如对文章太史公④。新堤路，问偃湖何日，烟水濛濛？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1847, "title": "喜迁莺", "author": "辛弃疾", "body": "赵晋臣敷文赋芙蓉词见寿，用韵为谢\n暑风凉月。爱亭亭无数，绿衣持节。掩冉如羞，参差似妒，拥出芙蓉花发。步衬潘娘堪恨，貌比六郎谁洁？添白鹭，晚晴时，公子佳人并列。 休说，搴木末；当日灵均，恨与君王别。心阻媒劳，交疏怨极，恩不甚兮轻绝。千古《离骚》文字，芳至今犹未歇。都休问，但千杯快饮，露荷翻叶。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1848, "title": "永遇乐", "author": "辛弃疾", "body": "戏赋辛字，送茂嘉十二弟赴调\n烈日秋霜，忠肝义胆，千载家谱。得姓何年，细参辛字，一笑君听取。艰辛做就，悲辛滋味，总是辛酸辛苦。更十分、向人辛辣，椒桂捣残堪吐。 世间应有，芳甘浓美，不到吾家门户。比着儿曹，锳锳却有，金印光垂组。付君此事，从今直上，休忆对床风雨。但赢得、靴纹绉面，记余戏语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1849, "title": "破阵子", "author": "辛弃疾", "body": "为陈同甫赋壮词以寄\n醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。 马作的卢飞快，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1850, "title": "鹧鸪天", "author": "辛弃疾", "body": "有客慨然谈功名，因追忆少年时事，戏作\n壮岁旌旗拥万夫，锦襜突骑渡江初。燕兵夜娖银胡䩮，汉箭朝飞金仆姑。 追往事，叹今吾，春风不染白髭须。却将万字平戎策，换得东家种树书。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1851, "title": "千年调", "author": "辛弃疾", "body": "开山径得石壁，因名曰苍壁。事出望外，意天之所赐邪，喜而赋\n左手把青霓，右手挟明月。吾使丰隆前导，叫开阊阖。周游上下，径入寥天一。览玄圃，万斛泉，千丈石。 钧天广乐，燕我瑶之席。帝饮予觞甚乐，赐汝苍壁。嶙峋突兀，正在一丘壑。余马怀，仆夫悲，下恍惚。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1852, "title": "玉楼春 戏赋云山", "author": "辛弃疾", "body": "何人半夜推山去？四面浮云猜是汝。常时相对两三峰，走遍溪头无觅处。 西风瞥起云横度，忽见东南天一柱。老僧拍手笑相夸，且喜青山依旧住。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1853, "title": "西江月 遣兴", "author": "辛弃疾", "body": "醉里且贪欢笑，要愁那得工夫。近来始觉古人书，信着全无是处。 昨夜松边醉倒，问松“我醉何如”。只疑松动要来扶，以手推松曰：“去！”", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1854, "title": "生查子 独游西岩", "author": "辛弃疾", "body": "青山招不来，偃蹇谁怜汝？岁晚太寒生，劝我溪边住。\n山头明月来，本在天高处。夜夜入青溪，听读《离骚》去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1855, "title": "卜算子 漫兴", "author": "辛弃疾", "body": "千古李将军，夺得胡儿马。李蔡为人在下中，却是封侯者。\n芸草去陈根，笕竹添新瓦。万一朝家举力田，舍我其谁也？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1856, "title": "满江红", "author": "辛弃疾", "body": "点火樱桃，照一架、荼䕷如雪。春正好，见龙孙①穿破，紫苔苍壁。乳燕引雏飞力弱，流莺唤友娇声怯。问春归、不肯带愁归，肠千结。 层楼望，春山叠；家何在？烟波隔。把古今遗恨，向他谁说？蝴蝶不传千里梦，子规叫断三更月。听声声、枕上劝人归，归难得。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1857, "title": "满江红", "author": "辛弃疾", "body": "游清风峡，和赵晋臣敷文韵\n两峡崭岩，问谁占、清风旧筑？更满眼、云来鸟去，涧红山绿。世上无人供笑傲，门前有客休迎肃。怕凄凉、无物伴君时，多栽竹。 风采妙，凝冰玉。诗句好，馀膏馥。叹只今人物，一夔应足。人似秋鸿无定住，事如飞弹须圆熟。笑君侯，陪酒又陪歌，《阳春曲》。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1858, "title": "永遇乐", "author": "辛弃疾", "body": "京口北固亭怀古\n千古江山，英雄无觅，孙仲谋处。舞榭歌台，风流总被，雨打风吹去。斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎。 元嘉草草，封狼居胥，赢得仓皇北顾。四十三年，望中犹记，烽火扬州路。可堪回首，佛狸祠下，一片神鸦社鼓。凭谁问：廉颇老矣，尚能饭否？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1859, "title": "汉宫春", "author": "辛弃疾", "body": "会稽蓬莱阁观雨\n秦望山头，看乱云急雨，倒立江湖。不知云者为雨，雨者云乎。长空万里，被西风、变灭须臾。回首听、月明天籁，人间万窍号呼。 谁向若耶溪上，倩美人西去，麋鹿姑苏？至今故国人望，一舸归欤。岁云暮矣，问何不鼓瑟吹竽。君不见、王亭谢馆，冷烟寒树啼乌。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1860, "title": "千年调", "author": "辛弃疾", "body": "蔗庵小阁名曰“卮言”，作此词以嘲之。\n卮酒向人时，和气先倾倒。最要然然可可，万事称好。滑稽坐上，更对鸱夷笑。寒与热，总随人，甘国老。 少年使酒，出口人嫌拗。此个和合道理，近日方晓。学人言语，未会十分巧。看他们，得人怜，秦吉了。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1861, "title": "踏莎行", "author": "辛弃疾", "body": "庚戌中秋后二夕带湖篆冈小酌\n夜月楼台，秋香院宇。笑吟吟地下来去。是谁秋到便凄凉？当年宋玉悲如许。 随分杯盘，等闲歌舞。问他有甚堪悲处？思量却也有悲时，重阳节近多风雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1862, "title": "南乡子", "author": "辛弃疾", "body": "登京口北固亭有怀\n何处望神州？满眼风光北固楼。千古兴亡多少事？悠悠，不尽长江滚滚流！ 年少万兜鍪①，坐断东南战未休。天下英雄谁敌手？曹刘。生子当如孙仲谋！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1863, "title": "最高楼", "author": "程垓", "body": "旧时心事，说着两眉羞。长记得、凭肩游。缃裙罗袜桃花岸，薄衫轻扇杏花楼。几番行，几番醉，几番留。 也谁料、春风吹已断。又谁料、朝云飞亦散。天易老，恨难酬。蜂儿不解知人苦，燕儿不解说人愁。旧情怀，消不尽，几时休。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1864, "title": "水龙吟", "author": "程垓", "body": "夜来风雨匆匆，故园定是花无几。愁多怨极，等闲孤负，一年芳意。柳困花慵，杏青梅小，对人容易。算好事长在，好花长见，元只是、人憔悴。 回首池南①旧事，恨星星、不堪重记。如今但有，看花老眼，伤时清泪。不怕逢花瘦，只愁怕、老来风味。待繁红乱处，留云借月，也须拚醉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1865, "title": "渔家傲", "author": "程垓", "body": "独木小舟烟雨湿。燕儿乱点春江碧。江上青山随意觅。人寂寂，落花芳草催寒食。 昨夜青楼今日客，吹愁不得东风力。细拾残红书怨泣。流水急，不知那个传消息。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1866, "title": "酷相思", "author": "程垓", "body": "月挂霜林寒欲坠。正门外、催人起。奈离别如今真个是。欲住也、留无计。欲去也、来无计。 马上离魂衣上泪。各自个、供憔悴。问江路梅花开也未？春到也、须频寄。人到也、须频寄。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1867, "title": "卜算子", "author": "程垓", "body": "独自上层楼，楼外青山远。望到斜阳欲尽时，不见西飞雁。\n独自下层楼，楼下蛩声怨。待到黄昏月上时，依旧柔肠断。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1868, "title": "愁倚阑", "author": "程垓", "body": "春犹浅，柳初芽，杏初花。杨柳杏花交影处，有人家。\n玉窗明暖烘霞。小屏上、水远山斜。昨夜酒多春睡重，莫惊他。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1869, "title": "眼儿媚", "author": "石孝友", "body": "愁云淡淡雨萧萧，暮暮复朝朝。别来应是，眉峰翠减，腕玉香销。 小轩独坐相思处，情绪好无聊。一丛萱草，数竿修竹，几叶芭蕉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1870, "title": "卜算子", "author": "石孝友", "body": "见也如何暮。别也如何遽。别也应难见也难，后会无凭据。\n去也如何去。住也如何住。住也应难去也难，此际难分付。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1871, "title": "浪淘沙", "author": "石孝友", "body": "好恨这风儿，催俺分离！船儿吹得去如飞，因甚眉儿吹不展？叵耐风儿！ 不是这船儿，载起相思？船儿若念我孤恓①，载取人人②篷底睡，感谢风儿！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1872, "title": "惜奴娇", "author": "石孝友", "body": "我已多情，更撞著、多情底你。把一心、十分向你。尽他们，劣心肠、偏有你。共你。风了人，只为个你。 宿世冤家，百忙里、方知你。没前程、阿谁似你。坏却才名，到如今、都因你。是你。我也没星儿恨你。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1873, "title": "谒金门 耽冈迓陆尉", "author": "赵师侠", "body": "沙畔路，记得旧时行处。蔼蔼①疏烟迷远树，野航②横不渡。 竹里疏花梅吐，照眼一川鸥鹭。家在清江江上住，水流愁不去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1874, "title": "水调歌头", "author": "陈亮", "body": "送章德茂大卿使虏\n不见南师久，漫说北群空。当场只手，毕竟还我万夫雄。自笑堂堂汉使，得似洋洋河水，依旧只流东？且复穹庐拜，会向藁街逢！ 尧之都，舜之壤，禹之封。于中应有，一个半个耻臣戎！万里腥膻如许，千古英灵安在，磅礴几时通？胡运何须问，赫日自当中！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1875, "title": "桂枝香", "author": "陈亮", "body": "观木樨有感，寄吕郎中\n天高气肃，正月色分明，秋容新沐。桂子初收，三十六宫都足。不辞散落人间去，怕群花、自嫌凡俗。向他秋晚，唤回春意，几曾幽独！ 是天上余香剩馥。怪一树香风，十里相续。坐对花旁，但见色浮金粟。芙蓉只解添愁思，况东篱、凄凉黄菊。入时太浅，背时太远，爱寻高躅。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1876, "title": "念奴娇 登多景楼", "author": "陈亮", "body": "危楼还望，叹此意、今古几人曾会？鬼设神施，浑认作、天限南疆北界。一水横陈，连岗三面，做出争雄势。六朝何事，只成门户私计？ 因笑王谢诸人，登高怀远，也学英雄涕。凭却长江，管不到、河洛腥膻无际。正好长驱，不须反顾，寻取中流誓。小儿破贼，势成宁问强对！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1877, "title": "贺新郎", "author": "陈亮", "body": "寄辛幼安，和见怀韵\n老去凭谁说？看几番、神奇臭腐，夏裘冬葛！父老长安今余几？后死无仇可雪。犹未燥、当时生发！二十五弦多少恨，算世间、那有平分月！胡妇弄，汉宫瑟。 树犹如此堪重别！只使君、从来与我，话头多合。行矣置之无足问，谁换妍皮痴骨？但莫使伯牙弦绝！九转丹砂牢拾取，管精金只是寻常铁。龙共虎，应声裂。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1878, "title": "贺新郎", "author": "陈亮", "body": "酬辛幼安，再用韵见寄\n离乱从头说，爱吾民、金缯不爱，蔓藤累葛。壮气尽消人脆好，冠盖阴山观雪。亏杀我、一星星发！涕出女吴成倒转，问鲁为齐弱何年月？丘也幸，由之瑟。 斩新换出旗麾别，把当时、一桩大义，拆开收合。据地一呼吾往矣，万里摇肢动骨，这话霸、只成痴绝！天地洪炉谁扇鞴？算于中、安得长坚铁！淝水破，关东裂。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1879, "title": "鹧鸪天 怀王道甫", "author": "陈亮", "body": "落魄行歌记昔游，头颅如许尚何求？心肝吐尽无馀事，口腹安然岂远谋！ 才怕暑，又伤秋。天涯梦断有书不？大都眼孔新来浅，羡尔微官作计周。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1880, "title": "贺新郎", "author": "陈亮", "body": "怀辛幼安，用前韵\n话杀浑闲说！不成教、齐民也解，为伊为葛？樽酒相逢成二老，却忆去年风雪。新著了、几茎华发。百世寻人犹接踵，叹只今、两地三人月！写旧恨，向谁瑟？ 男儿何用伤离别？况古来、几番际会，风从云合。千里情亲长晤对，妙体本心次骨。卧百尺高楼斗绝。天下适安耕且老，看买犁卖剑平家铁！壮士泪，肺肝裂！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1881, "title": "好事近 咏梅", "author": "陈亮", "body": "的皪两三枝，点破暮烟苍碧。好在屋檐斜入，傍玉奴①吹笛。 月华如水过林塘，花阴弄苔石。欲向梦中飞蝶，恐幽香难觅。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1882, "title": "小重山", "author": "陈亮", "body": "碧幕霞绡一缕红。槐枝啼宿鸟，冷烟浓。小楼愁倚画阑东。黄昏月，一笛碧云风。 往事已成空。梦魂飞不到，楚王宫。翠绡和泪暗偷封。江南阔，无处觅征鸿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1883, "title": "最高楼 咏梅", "author": "陈亮", "body": "春乍透，香早暗偷传。深院落，斗清妍。紫檀枝似流苏带①，黄金鬚胜辟寒钿②。更朝朝，琼树好，笑当年。 花不向沉香亭上看；树不着唐昌宫里玩。衣带水，隔风烟。铅华不御凌波处③，蛾眉淡扫至尊前④。管如今，浑似了，更堪怜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1884, "title": "一丛花 溪堂玩月作", "author": "陈亮", "body": "冰轮斜辗镜天长，江练隐寒光。危阑醉倚人如画，隔烟村、何处鸣桹？乌鹊倦栖，鱼龙惊起，星斗挂垂杨。 芦花千顷水微茫，秋色满江乡。楼台恍似游仙梦，又疑是、洛浦潇湘。风露浩然，山河影转，今古照凄凉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1885, "title": "水龙吟 春恨", "author": "陈亮", "body": "闹花深处层楼，画帘半卷东风软。春归翠陌，平莎茸嫩，垂杨金浅。迟日催花，淡云阁雨，轻寒轻暖。恨芳菲世界，游人未赏，都付与、莺和燕。 寂寞凭高念远，向南楼、一声归雁。金钗斗草，青丝勒马，风流云散。罗绶分香，翠绡封泪，几多幽怨！正销魂又是，疏烟淡月，子规声断。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1886, "title": "虞美人 春愁", "author": "陈亮", "body": "东风荡飏轻云缕，时送萧萧雨。水边台榭燕新归，一口香泥、湿带落花飞。 海棠糁径铺香绣，依旧成春瘦。黄昏庭院柳啼鸦，记得那人和月折梨花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1887, "title": "水调歌头", "author": "杨炎正", "body": "把酒对斜日，无语问西风。胭脂何事，都做颜色染芙蓉。放眼暮江千顷，中有离愁万斛，无处落征鸿。天在阑干角，人倚醉醒中。 千万里，江南北，浙西东。吾生如寄，尚想三径菊花丛。谁是中州豪杰，借我五湖舟楫，去作钓鱼翁。故国且回首，此意莫匆匆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1888, "title": "蝶恋花 别范南伯", "author": "杨炎正", "body": "离恨做成春夜雨。添得春江，刬地东流去。弱柳系船都不住，为君愁绝听鸣艣。 君到南徐芳草渡。想得寻春，依旧当年路。后夜独怜回首处，乱山遮隔无重数。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1889, "title": "小重山", "author": "章良能", "body": "柳暗花明春事深。小阑红芍药，已抽簪。雨余风软碎鸣禽。迟迟日，犹带一分阴。 往事莫沉吟。身闲时序好，且登临。旧游无处不堪寻。无寻处，惟有少年心。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1890, "title": "昭君怨 园池夜泛", "author": "张镃", "body": "月在碧虚中住，人向乱荷中去。花气杂风凉，满船香。\n云被歌声摇动，酒被诗情掇送。醉里卧花心，拥红衾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1891, "title": "菩萨蛮 芭蕉", "author": "张镃", "body": "风流不把花为主，多情管定烟和雨。潇洒绿衣长，满身无限凉。 文笺舒卷处，似索题诗句。莫凭小阑干，月明生夜寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1892, "title": "满庭芳 促织儿", "author": "张镃", "body": "月洗高梧，露漙幽草，宝钗楼外秋深。土花沿翠，萤火坠墙阴。静听寒声断续，微韵转、凄咽悲沉。争求侣，殷勤劝织，促破晓机心。 儿时曾记得，呼灯灌穴，敛步随音。任满身花影，犹自追寻。携向华堂戏斗，亭台小、笼巧妆金。今休说，从渠床下，凉夜伴孤吟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1893, "title": "念奴娇", "author": "张镃", "body": "宜雨亭咏千叶海棠\n绿云影里，把明霞织就，千重文绣。紫腻红娇扶不起，好是未开时候。半怯春寒，半宜晴色，养得胭脂透。小亭人静，嫩莺啼破清昼。 犹记携手芳阴，一枝斜戴，娇艳双波秀。小语轻怜花总见，争得似花长久。醉浅休归，夜深同睡，明日还相守。免教春去，断肠空叹诗瘦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1894, "title": "沁园春", "author": "刘过", "body": "卢蒲江席上，时有新第宗室\n一剑横空，飞过洞庭，又为此来。有汝阳琎者①，唱名殿陛②；玉川公子③，开宴尊罍。四举无成，十年不调，大宋神仙刘秀才。如何好？将百千万事，付两三杯。 未尝戚戚于怀。问自古英雄安在哉？任钱塘江④上，潮生潮落；姑苏台⑤畔，花谢花开。盗号书生，强名举子，未老雪从头上催。谁羡汝、拥三千珠履⑥，十二金钗⑦！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1895, "title": "沁园春", "author": "刘过", "body": "寄辛承旨①。时承旨招，不赴。\n斗酒彘肩，风雨渡江，岂不快哉！被香山居士，约林和靖，与坡仙老，驾勒吾回②。坡谓西湖，正如西子，浓抹淡妆临镜台。二公者，皆掉头不顾，只管衔杯。 白云天竺去来，图画里、峥嵘楼观开。爱东西双涧，纵横水绕；两峰南北，高下云堆。逋曰不然，暗香浮动，争似孤山先探梅。须晴去，访稼轩未晚，且此徘徊。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1896, "title": "沁园春 张路分秋阅", "author": "刘过", "body": "万马不嘶，一声寒角，令行柳营①。见秋原如掌，枪刀突出，星驰铁骑，阵势纵横。人在油幢，戎韬总制，羽扇从容裘带轻。君知否，是山西将种②，曾系诗盟。 龙蛇纸上飞腾，看落笔、四筵风雨惊③。便尘沙出塞，封侯万里，印金如斗，未惬平生。拂拭腰间，吹毛剑在，不斩楼兰④心不平。归来晚，听随军鼓吹，已带边声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1897, "title": "水调歌头", "author": "刘过", "body": "弓剑出榆塞，铅椠上蓬山。得之浑不费力，失亦匹如闲。未必古人皆是，未必今人俱错，世事沐猴冠。老子不分别，内外与中间。 酒须饮，诗可作，铗休弹。人生行乐，何自催得鬓毛斑？达则牙旗金甲，穷则蹇驴破帽，莫作两般看。世事只如此，自有识鸮鸾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1898, "title": "念奴娇", "author": "刘过", "body": "留别辛稼轩①\n知音者少，算乾坤许大，著身何处？直待功成方肯退，何日可寻归路。多景楼前，垂虹亭下，一枕眠秋雨。虚名相误，十年枉费辛苦。 不是奏赋明光，上书北阙，无惊人之语。我自匆忙天未许，赢得衣裾尘土。白璧追欢，黄金买笑，付与君为主。莼鲈江上，浩然明日归去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1899, "title": "糖多令", "author": "刘过", "body": "安远楼小集，侑觞歌板之姬黄其姓者，乞词于龙洲道人，为赋此《糖多令》。同柳阜之、刘去非、石民瞻、周嘉仲、陈孟参、孟容。时八月五日也。\n芦叶满汀洲，寒沙带浅流。二十年重过南楼。柳下系船犹未稳，能几日，又中秋。 黄鹤断矶头，故人今在不？旧江山浑是新愁。欲买桂花同载酒，终不似、少年游。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1900, "title": "贺新郎", "author": "刘过", "body": "老去相如倦。向文君、说似而今，怎生消遣？衣袂京尘曾染处，空有香红尚软①。料彼此、魂消肠断。一枕新凉眠客舍，听梧桐疏雨秋风颤。灯晕冷，记初见。 楼低不放珠帘卷。晚妆残，翠蛾狼藉，泪痕凝脸。人道愁来须殢酒②，无奈愁深酒浅。但托意焦琴纨扇。莫鼓琵琶江上曲，怕荻花枫叶俱凄怨。云万叠，寸心远。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1901, "title": "贺新郎", "author": "刘过", "body": "弹铗西来路。记匆匆、经行数日，几番风雨。梦里寻秋秋不见，秋在平芜远渚。想雁信家山何处？万里西风吹客鬓，把菱花、自笑人憔悴。留不住，少年去。 男儿事业无凭据。记当年、击筑悲歌，酒酣箕踞。腰下光芒三尺剑，时解挑灯夜语；更忍对灯花弹泪？唤起杜陵风雨手，写江东渭北相思句。歌此恨，慰羁旅。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1902, "title": "水龙吟 寄陆放翁", "author": "刘过", "body": "谪仙狂客何如？看来毕竟归田好。玉堂无此，三山海上，虚无缥缈。读罢《离骚》，酒香犹在，觉人间小。任菜花葵麦，刘郎去后，桃开处、春多少。 一夜雪迷兰棹。傍寒溪、欲寻安道。而今纵有，新诗《冰柱》，有知音否？想见鸾飞，如椽健笔，檄书亲草。算平生白傅风流，未可向、香山老。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1903, "title": "柳梢青 送卢梅坡", "author": "刘过", "body": "泛菊杯深，吹梅角远，同在京城。聚散匆匆，云边孤雁，水上浮萍。 教人怎不伤情？觉几度、魂飞梦惊。后夜相思，尘随马去，月逐舟行。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1904, "title": "醉太平", "author": "刘过", "body": "情高意真，眉长鬓青。小楼明月调筝，写春风数声。\n思君忆君，魂牵梦萦。翠销香减云屏，更那堪酒醒！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1905, "title": "六州歌头 题岳鄂王庙", "author": "刘过", "body": "中兴诸将，谁是万人英？身草莽，人虽死，气填膺，尚如生。年少起河朔，弓两石，剑三尺，定襄汉，开虢洛，洗洞庭。北望帝京，狡兔依然在，良犬先烹。过旧时营垒，荆鄂有遗民。忆故将军，泪如倾。 说当年事，知恨苦：不奉诏，伪耶真？臣有罪，陛下圣，可鉴临，一片心。万古分茅土①，终不到，旧奸臣。人世夜，白日照，忽开明。衮珮冕圭百拜，九泉下、荣感君恩。看年年三月，满地野花春，卤簿②迎神。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1906, "title": "西江月", "author": "刘过", "body": "堂上谋臣尊俎①，边头将士干戈。天时地利与人和，“燕可伐欤？”曰：“可。” 今日楼台鼎鼐②，明年带砺山河。大家齐唱《大风歌》，不日四方来贺。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1907, "title": "小重山令 赋潭州红梅", "author": "姜夔", "body": "人绕湘皋月坠时。斜横花树小，浸愁漪。一春幽事有谁知？东风冷，香远茜裙归。 鸥去昔游非。遥怜花可可，梦依依。九疑云杳断魂啼。相思血，都沁绿筠枝。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1908, "title": "江梅引", "author": "姜夔", "body": "人间离别易多时。见梅枝，忽相思。几度小窗幽梦手同携。今夜梦中无觅处，漫徘徊，寒侵被，尚未知。 湿红恨墨浅封题。宝筝空，无雁飞。俊游巷陌，算空有、古木斜晖。旧约扁舟，心事已成非。歌罢淮南春草赋，又萋萋。漂零客，泪满衣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1909, "title": "鬲溪梅令", "author": "姜夔", "body": "丙辰冬，自无锡归，作此寓意。\n好花不与殢香人。浪粼粼。又恐春风归去绿成阴。玉钿何处寻。 木兰双桨梦中云。小横陈。漫向孤山山下觅盈盈。翠禽啼一春。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1910, "title": "点绛唇", "author": "姜夔", "body": "丁未冬过吴松作\n燕雁无心，太湖西畔随云去。数峰清苦。商略黄昏雨。\n第四桥边，拟共天随住。今何许。凭栏怀古。残柳参差舞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1911, "title": "点绛唇", "author": "姜夔", "body": "金谷人归，绿杨低扫吹笙道。数声啼鸟，也学相思调。\n月落潮生，掇送刘郎老。淮南好，甚时重到？陌上生春草。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1912, "title": "忆王孙", "author": "姜夔", "body": "冷红叶叶下塘秋，长与行云共一舟。零落江南不自由。两绸缪，料得吟鸾夜夜愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1913, "title": "鹧鸪天", "author": "姜夔", "body": "己酉之秋，苕溪记所见。\n京洛风流绝代人，因何风絮落溪津？笼鞋浅出鸦头袜，知是凌波缥缈身。 红乍笑，绿长嚬。与谁同度可怜春？鸳鸯独宿何曾惯，化作西楼一缕云。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1914, "title": "鹧鸪天", "author": "姜夔", "body": "正月十一日观灯\n巷陌风光纵赏时，笼纱未出马先嘶。白头居士无呵殿，只有乘肩小女随。 花满市，月侵衣，少年情事老来悲。沙河塘上春寒浅，看了游人缓缓归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1915, "title": "鹧鸪天 元夕有所梦", "author": "姜夔", "body": "肥水东流无尽期，当初不合种相思。梦中未比丹青见，暗里忽惊山鸟啼。 春未绿，鬓先丝。人间别久不成悲。谁教岁岁红莲夜，两处沉吟各自知。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1916, "title": "踏莎行", "author": "姜夔", "body": "自沔东来，丁未元日至金陵，江上感梦而作。\n燕燕轻盈，莺莺娇软。分明又向华胥见。夜长争得薄情知？春初早被相思染。 别后书辞，别时针线。离魂暗逐郎行远。淮南皓月冷千山，冥冥归去无人管。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1917, "title": "杏花天影", "author": "姜夔", "body": "丙午之冬，发沔口。丁未正月二日，道金陵。北望淮楚，风日清淑，小舟挂席，容与波上。\n绿丝低拂鸳鸯浦。想桃叶、当时唤渡。又将愁眼与春风，待去；倚兰桡，更少驻。 金陵路、莺吟燕舞。算潮水、知人最苦。满汀芳草不成归，日暮；更移舟，向甚处？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1918, "title": "浣溪沙", "author": "姜夔", "body": "予女须家沔之山阳，左白湖，右云梦，春水方生，浸数千里，冬寒沙露，衰草入云。丙午之秋，予与安甥或荡舟采菱，或举火罝兔，或观鱼簺下；山行野吟，自适其适；凭虚怅望，因赋是阕。\n著酒行行满袂风。草枯霜鹘落晴空。销魂都在夕阳中。\n恨入四弦人欲老，梦寻千驿意难通。当时何似莫匆匆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1919, "title": "浣溪沙", "author": "姜夔", "body": "辛亥正月二十四日，发合肥。\n钗燕笼云晚不忺。拟将裙带系郎船。别离滋味又今年。\n杨柳夜寒犹自舞，鸳鸯风急不成眠。些儿闲事莫萦牵。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1920, "title": "浣溪沙", "author": "姜夔", "body": "丙辰岁不尽五日，吴松作。\n雁怯重云不肯啼。画船愁过石塘西。打头风浪恶禁持。\n春浦渐生迎棹绿，小梅应长亚门枝。一年灯火要人归。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1921, "title": "霓裳中序第一", "author": "姜夔", "body": "丙午岁，留长沙，登祝融，因得其祠神之曲，曰《黄帝盐》、《苏合香》①。又于乐工故书中得商调《霓裳曲》十八阕②，皆虚谱无辞。按沈氏《乐律》:《霓裳》道调③。此乃商调④。乐天诗云：“散序六阕。”此特二阕⑤。未知孰是。然音节闲雅，不类今曲。予不暇尽作，作中序一阕传于世⑥。予方羁游，感此古音，不自知其辞之怨抑也。\n亭皋正望极。乱落江莲归未得。多病却无气力。况纨扇渐疏，罗衣初索。流光过隙。叹杏梁、双燕如客。人何在，一帘淡月，仿佛照颜色。 幽寂。乱蛩吟壁。动庾信、清愁似织。沉思年少浪迹。笛里关山，柳下坊陌。坠红无信息。漫暗水、涓涓溜碧。飘零久，而今何意，醉卧酒垆侧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1922, "title": "庆宫春", "author": "姜夔", "body": "绍熙辛亥除夕，予别石湖归吴兴，雪后夜过垂虹，尝赋诗云：“笠泽茫茫雁影微，玉峰重叠护云衣。长桥寂寞春寒夜，只有诗人一舸归。”后五年冬，复与俞商卿、张平甫、铦朴翁自封禺同载诣梁溪，道经吴松。山寒天迥，云浪四合。中夕相呼步垂虹，星斗下垂，错杂渔火，朔吹凛凛，卮酒不能支。朴翁以衾自缠，犹相与行吟。因赋此阕，盖过旬涂稿乃定。朴翁咎余无益，然意所耽，不能自已也。平甫、商卿、朴翁皆工于诗，所出奇诡，予亦强追逐之。此行既归，各得五十余解。\n双桨莼波，一蓑松雨，暮愁渐满空阔。呼我盟鸥，翩翩欲下，背人还过木末。那回归去，荡云雪，孤舟夜发。伤心重见，依约眉山，黛痕低压。 采香径里春寒，老子婆娑，自歌谁答。垂虹西望，飘然引去，此兴平生难遏。酒醒波远，政凝想、明珰素袜。如今安在，唯有阑干，伴人一霎。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1923, "title": "齐天乐", "author": "姜夔", "body": "庾郎先自吟愁赋，凄凄更闻私语。露湿铜铺，苔侵石井，都是曾听伊处。哀音似诉。正思妇无眠，起寻机杼。曲曲屏山，夜凉独自甚情绪？ 西窗又吹暗雨。为谁频断续，相和砧杵？候馆迎秋，离宫吊月，别有伤心无数。豳诗①漫与。笑篱落呼灯，世间儿女。写入琴丝，一声声更苦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1924, "title": "满江红", "author": "姜夔", "body": "仙姥来时，正一望、千顷翠澜。旌旗共、乱云俱下，依约前山。命驾群龙金作轭，相从诸娣玉为冠。向夜深、风定悄无人，闻佩环。 神奇处，君试看。奠淮右，阻江南。遣六丁雷电，别守东关。却笑英雄无好手，一篙春水走曹瞒。又怎知、人在小红楼，帘影间。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1925, "title": "一萼红", "author": "姜夔", "body": "丙午人日，予客长沙别驾之观政堂。堂下曲沼，沼西负古垣，有卢橘①幽篁，一径深曲。穿径而南，官梅数十株，如椒、如菽，或红破白露，枝影扶疏。著屐苍苔细石间，野兴横生，亟命驾②登定王台，乱③湘流、入麓山。湘云低昂，湘波容与④。兴尽悲来，醉吟成调。\n古城阴。有官梅几许，红萼未宜簪。池面冰胶，墙阴雪老，云意还又沉沉。翠藤共、闲穿径竹，渐笑语、惊起卧沙禽。野老林泉，故王台榭，呼唤登临。 南去北来何事，荡湘云楚水，目极伤心。朱户粘鸡，金盘簇燕，空叹时序侵寻。记曾共、西楼雅集，想垂柳、还袅万丝金。待得归鞍到时，只怕春深。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1926, "title": "念奴娇", "author": "姜夔", "body": "余客武陵，湖北宪治在焉。古城野水，乔木参天。余与二三友日荡舟其间，薄荷花而饮，意象幽闲，不类人境。秋水且涸，荷叶出地寻丈，因列坐其下，上不见日，清风徐来，绿云自动。间于疏处窥见游人画船，亦一乐也。朅来吴兴，数得相羊荷花中。又夜泛西湖，光景奇绝。故以此句写之。\n闹红一舸，记来时尝与鸳鸯为侣。三十六陂人未到，水佩风裳无数。翠叶吹凉，玉容销酒，更洒菰蒲雨。嫣然摇动，冷香飞上诗句。 日暮青盖亭亭，情人不见，争忍凌波去。只恐舞衣寒易落，愁入西风南浦。高柳垂阴，老鱼吹浪，留我花间住。田田多少，几回沙际归路。\n念奴娇（闹红一舸） 姜 夔", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1927, "title": "月下笛", "author": "姜夔", "body": "与客携壶，梅花过了，夜来风雨。幽禽自语。啄香心，度墙去。春衣都是柔荑剪，尚沾惹、残茸半缕。怅玉钿似扫，朱门深闭，再见无路。 凝竚，曾游处。但系马垂杨，认郎鹦鹉。扬州梦觉，彩云飞过何许？多情须倩梁间燕，问吟袖弓腰在否？怎知道、误了人，年少自恁虚度！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1928, "title": "琵琶仙", "author": "姜夔", "body": "《吴都赋》云：“户藏烟浦，家具画船。①”唯吴兴为然。春游之盛，西湖未能过也。己酉岁，予与萧时父载酒南郭②，感遇成歌。\n双桨来时，有人似、旧曲桃根桃叶。歌扇轻约飞花，蛾眉正奇绝。春渐远，汀洲自绿，更添了、几声啼鴂。十里扬州，三生杜牧，前事休说。 又还是、宫烛分烟，奈愁里、匆匆换时节。都把一襟芳思，与空阶榆荚。千万缕、藏鸦细柳，为玉尊、起舞回雪。想见西出阳关，故人初别。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1929, "title": "侧犯 咏芍药", "author": "姜夔", "body": "恨春易去，甚春却向扬州住。微雨，正茧栗①梢头弄诗句。红桥二十四，总是行云处。无语，渐半脱宫衣笑相顾。 金壶细叶，千朵围歌舞。谁念我、鬓成丝，来此共尊俎。后日西园，绿阴无数。寂寞刘郎，自修花谱。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1930, "title": "水龙吟", "author": "姜夔", "body": "黄庆长夜泛鉴湖，有怀归之曲，课予和之。\n夜深客子移舟处，两两沙禽惊起。红衣入桨，青灯摇浪，微凉意思。把酒临风，不思归去，有如此水。况茂陵游倦，长干望久，芳心事、箫声里。 屈指归期尚未。鹊南飞、有人应喜。画阑桂子，留香小待，提携影底。我已情多，十年幽梦，略曾如此。甚谢郎、也恨飘零，解道月明千里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1931, "title": "探春慢", "author": "姜夔", "body": "予自孩幼从先人宦于古沔，女须因嫁焉。中去复来几二十年，岂惟姊弟之爱，沔之父老儿女子亦莫不予爱也。丙午冬，千岩老人约予过苕霅，岁晚乘涛载雪而下，顾念依依，殆不能去。作此曲别郑次皋、辛克清、姚刚中诸君。\n衰草愁烟，乱鸦送日，风沙回旋平野。拂雪金鞭，欺寒茸帽，还记章台走马。谁念漂零久，漫赢得幽怀难写。故人清沔相逢，小窗闲共情话。 长恨离多会少，重访问竹西，珠泪盈把。雁碛波平，渔汀人散，老去不堪游冶。无奈苕溪月，又照我扁舟东下。甚日归来，梅花零乱春夜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1932, "title": "八归", "author": "姜夔", "body": "湘中送胡德华\n芳莲坠粉，疏桐吹绿，庭院暗雨乍歇。无端抱影销魂处，还见篠墙萤暗，藓阶蛩切。送客重寻西去路，问水面琵琶谁拨？最可惜、一片江山，总付与啼鴂。 长恨相从未款，而今何事，又对西风离别？渚寒烟淡，棹移人远，缥缈行舟如叶。想文君望久，倚竹愁生步罗袜。归来后，翠尊双饮，下了珠帘，玲珑闲看月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1933, "title": "解连环", "author": "姜夔", "body": "玉鞍重倚。却沉吟未上，又萦离思①。为大乔能拨春风，小乔妙移筝，雁啼秋水。柳怯云松，更何必、十分梳洗。道郎携羽扇，那日隔帘，半面②曾记。 西窗夜凉雨霁。叹幽欢未足，何事轻弃。问后约、空指蔷薇，算如此溪山，甚时重至。水驿灯昏，又见在、曲屏近底③。念唯有夜来皓月，照伊自睡。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1934, "title": "扬州慢", "author": "姜夔", "body": "淳熙丙申至日，予过维扬，夜雪初霁，荠麦弥望。入其城则四顾萧条，寒水自碧。暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲，千岩老人以为有黍离之悲也。\n淮左名都，竹西佳处，解鞍少驻初程。过春风十里，尽荠麦青青。自胡马窥江去后；废池乔木，犹厌言兵。渐黄昏，清角吹寒，都在空城。 杜郎俊赏，算而今、重到须惊。纵豆蔻词工，青楼梦好，难赋深情。二十四桥仍在，波心荡、冷月无声。念桥边红药，年年知为谁生！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1935, "title": "长亭怨慢", "author": "姜夔", "body": "予颇喜自制曲，初率意为长短句，然后协以律，故前后阕多不同。桓大司马云：“昔年种柳，依依汉南；今看摇落，凄怆江潭；树犹如此，人何以堪！”此语予深爱之。\n渐吹尽、枝头香絮，是处人家，绿深门户。远浦萦回，暮帆零乱向何许？阅人多矣，谁得似长亭树。树若有情时，不会得青青如此！ 日暮，望高城不见，只见乱山无数。韦郎去也，怎忘得玉环分付。第一是早早归来，怕红萼无人为主。算空有并刀，难剪离愁千缕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1936, "title": "淡黄柳", "author": "姜夔", "body": "客居合肥南城赤阑桥之西，巷陌凄凉，与江左异，惟柳色夹道，依依可怜。因度此阕，以纾客怀。\n空城晓角，吹入垂杨陌。马上单衣寒恻恻。看尽鹅黄嫩绿，都是江南旧相识。 正岑寂。明朝又寒食。强携酒，小桥宅。怕梨花落尽成秋色。燕燕飞来，问春何在，唯有池塘自碧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1937, "title": "暗香疏影", "author": "姜夔", "body": "辛亥之冬，予载雪诣石湖。止既月，授简索句，且征新声，作此两曲。石湖把玩不已，做工伎肄习之，音节谐婉，乃名之曰《暗香》、《疏影》。\n旧时月色，算几番照我，梅边吹笛？唤起玉人，不管清寒与攀摘。何逊而今渐老，都忘却、春风词笔。但怪得、竹外疏花，香冷入瑶席。 江国，正寂寂。叹寄与路遥，夜雪初积。翠尊易泣，红萼无言耿相忆。长记曾携手处，千树压、西湖寒碧。又片片吹尽也，几时见得？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1938, "title": "惜红衣", "author": "姜夔", "body": "吴兴号水晶宫，荷花盛丽。陈简斋云：“今年何以报君恩，一路荷花相送到青墩。”亦可见矣。丁未之夏，予游千岩，数往来红香中，自度此曲，以无射宫歌之。\n簟枕邀凉，琴书换日，睡馀无力。细洒冰泉，并刀破甘碧。墙头唤酒，谁问讯、城南诗客。岑寂。高柳晚蝉，说西风消息。\n虹梁水陌。鱼浪吹香，红衣半狼藉。维舟试望故国。眇天北。可惜渚边沙外，不共美人游历。问甚时同赋，三十六陂秋色。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1939, "title": "角招", "author": "姜夔", "body": "为春瘦，何堪更、绕西湖尽是垂柳。自看烟外岫，记得与君，湖上携手。君归未久，早乱落香红千亩。一叶凌波缥缈，过三十六离宫，遣游人回首。 犹有，画船障袖，青楼倚扇，相映人争秀。翠翘光欲溜，爱著宫黄，而今时候。伤春似旧，荡一点、春心如酒。写入吴丝自奏。问谁识、曲中心，花前友。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1940, "title": "凄凉犯", "author": "姜夔", "body": "绿杨巷陌秋风起，边城一片离索。马嘶渐远，人归甚处，戍楼吹角。情怀正恶，更衰草寒烟淡薄。似当时、将军部曲，迤逦度沙漠。 追念西湖上，小舫携歌，晚花行乐。旧游在否？想如今、翠凋红落。漫写羊裙，等新雁来时系著。怕匆匆、不肯寄与误后约。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1941, "title": "翠楼吟", "author": "姜夔", "body": "淳熙丙午冬，武昌安远楼成，与刘去非诸友落之，度曲见志。予去武昌十年，故人有泊舟鹦鹉洲者，闻小姬歌此词，问之，颇能道其事，还吴为余言之；兴怀昔游，且伤今之离索也。\n月冷龙沙，尘清虎落，今年汉酺初赐。新翻胡部曲，听毡幕元戎歌吹。层楼高峙。看槛曲萦红，檐牙飞翠。人姝丽，粉香吹下，夜寒风细。 此地，宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草萋萋千里。天涯情味。仗酒祓清愁，花销英气。西山外，晚来还卷，一帘秋霁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1942, "title": "湘月", "author": "姜夔", "body": "长溪①杨声伯典长沙楫棹②，居濒湘江，窗间所见，如燕公③、郭熙④画图，卧起幽适。丙午七月既望，声伯约予与赵景鲁、景望、萧和父、裕父、时父、恭父，大舟浮湘，放乎中流，山水空寒，烟月交映，凄然其为秋也。坐客皆小冠綀服，或弹琴，或浩歌，或自酌，或援笔搜句。予度此曲，即念奴娇之鬲指声也，于双调中吹之。鬲指亦谓之“过腔”，见晁无咎集⑤。凡能吹竹者，便能过腔也。\n五湖旧约，问经年底事，长负清景？暝入西山，渐唤我，一叶夷犹⑥乘兴。倦网都收，归禽时度，月上汀洲冷。中流容与⑦，画桡不点清镜。 谁解唤起湘灵，烟鬟雾鬓，理哀弦鸿阵。玉麈谈玄⑧，叹坐客、多少风流名胜。暗柳萧萧，飞星冉冉，夜久知秋信。鲈鱼应好，旧家乐事谁省⑨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1943, "title": "永遇乐", "author": "姜夔", "body": "次韵辛克清先生\n我与先生，夙期已久。人间无此。不学杨郎，南山种豆，十一征微利。云霄直上，诸公衮衮，乃作道边苦李。五千言、老来受用，肯教造物儿戏？ 东冈记得，同来胥宇，岁月几何难计。柳老悲桓，松高对阮，未办为邻地。长干白下，青楼朱阁，往往梦中槐蚁。却不如、窪尊放满，老夫未醉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1944, "title": "永遇乐", "author": "姜夔", "body": "次稼轩北固楼词韵\n云鬲迷楼①，苔封很石②，人向何处？数骑秋烟，一篙寒汐，千古空来去。使君心在，苍厓绿嶂，苦被北门留住。有尊中酒差可饮，大旗尽绣熊虎。 前身诸葛，来游此地，数语便酬三顾。楼外冥冥，江皋隐隐，认得征西路。中原生聚，神京耆老，南望长淮金鼓。问当时依依种柳，至今在否？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1945, "title": "沁园春 忆黄山", "author": "汪莘", "body": "三十六峰，三十六溪，长锁清秋。对孤峰绝顶，云烟竞秀；悬崖峭壁，瀑布争流。洞里桃花，仙家芝草，雪后春正取次游。亲曾见，是龙潭白昼，海涌潮头。 当年黄帝浮丘，有玉枕玉床还在不？向天都月夜，遥闻凤管；翠微霜晓，仰盼龙楼。砂穴长红，丹炉已冷，安得灵方闻早①修？谁知此，问源头白鹿，水畔青牛。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1946, "title": "杏花天 有感", "author": "汪莘", "body": "美人家在江南住，每惆怅江南日暮。白蘋洲畔花无数，还忆潇湘风度。 幸自是断肠无处，怎强作莺声燕语？东风占断秦筝柱，也逐落花归去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1947, "title": "水调歌头 题剑阁①", "author": "崔与之", "body": "万里云间戍，立马剑门关。乱山极目无际，直北是长安。人苦百年涂炭，鬼哭三边锋镝，天道久应还。手写留屯奏，炯炯寸心丹。 对青灯，搔白首，漏声残。老来勋业未就，妨却一身闲。蒲涧②清泉白石，梅岭③绿阴青子，怪我旧盟寒。烽火平安夜，归梦绕家山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1948, "title": "酹江月 观潮应制", "author": "吴琚", "body": "玉虹遥挂，望青山隐隐，一眉如抹。忽觉天风吹海立，好似春霆初发。白马凌空，琼鳌驾水，日夜朝天阙。飞龙舞凤，郁葱环拱吴越。 此景天下应无，东南形胜，伟观真奇绝。好是吴儿飞彩帜，蹴起一江秋雪。黄屋天临，水犀云拥，看击中流楫。晚来波静，海门飞上明月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1949, "title": "酹江月 石头城", "author": "杜 旟", "body": "江山如此，是天开万古，东南王气。一自髯孙横短策，坐使英雄鹊起。玉树声销，金莲影散，多少伤心事！千年辽鹤，并疑城郭非是。 当日万驷云屯，潮生潮落处，石头孤峙。人笑褚渊今齿冷，只有袁公不死。斜日荒烟，神州何在？欲堕新亭泪。元龙老矣，世间何限馀子。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1950, "title": "贺新郎 题吴江", "author": "刘仙伦", "body": "重唤松江渡。叹垂虹亭下，销磨几番今古！依旧四桥风景在，为问坡仙甚处。但遗爱、沙边鸥鹭。天水相连苍茫外，更碧云去尽山无数。潮正落，日还暮。 十年到此长凝伫①。恨无人、与共秋风，鲙丝莼缕。小转朱弦弹九奏②，拟致湘妃伴侣③。俄皓月、飞来烟渚。恍若乘槎河汉上，怕客星犯斗蛟龙怒。歌欸乃④，过江去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1951, "title": "念奴娇", "author": "刘仙伦", "body": "送张明之赴京西幕\n艅艎东下，望西江千里，苍茫烟水。试问襄州何处是？雉堞连云天际。叔子残碑，卧龙陈迹，遗恨斜阳里。后来人物，如君瓌伟能几？ 其肯为我来耶？河阳下士，差足强人意。勿谓时平无事也，便以言兵为讳。眼底河山，楼头鼓角，都是英雄泪。功名机会，要须闲暇先备。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1952, "title": "婆罗门引", "author": "赵昂", "body": "暮霞照水，水边无数木芙蓉。晓来露湿轻红。十里锦丝步障，日转影重重。向楚天空迥，人立西风。 夕阳道中。叹秋色、与愁浓。寂寞三千粉黛，临鉴妆慵。施朱太赤，空惆怅、教妾若为容。花易老、烟水无穷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1953, "title": "贺新郎", "author": "韩淲", "body": "坐上有举昔人《贺新郎》一词，极壮，酒半用其韵。\n万事佯休去。漫栖迟、灵山起雾，玉溪流渚。击楫凄凉千古意，怅怏衣冠南渡。泪暗洒、神州沉处。多少胸中经济略，气□□、郁郁愁金鼓。空自笑，听鸡舞。 天关九虎寻无路。叹都把、生民膏血，尚交胡虏。吴蜀江山元自好，形势何能尽语。但目尽、东南风土。赤壁楼船应似旧，问子瑜公瑾今安否。割舍了，对君举。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1954, "title": "鹧鸪天 兰溪舟中", "author": "韩淲", "body": "雨湿西风水面烟。一巾华发上溪船。帆迎山色来还去，橹破滩痕散复圆。 寻浊酒，试吟篇。避人鸥鹭更翩翩。五更犹作钱塘梦，睡觉方知过眼前。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1955, "title": "风入松", "author": "俞国宝", "body": "一春长费买花钱，日日醉湖边。玉骢惯识西湖路，骄嘶过、沽酒楼前。红杏香中箫鼓，绿杨影里秋千。 暖风十里丽人天，花压鬓云偏。画船载取春归去，馀情付、湖水湖烟。明日重扶残醉，来寻陌上花钿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1956, "title": "水调歌头", "author": "程珌", "body": "登甘露寺多景楼望淮有感\n天地本无际，南北竟谁分？楼前多景，中原一恨杳难论。却似长江万里，忽有孤山两点，点破水晶盆。为借鞭霆力，驱去附昆仑。 望淮阴，兵冶处，俨然存。看来天意，止欠士雅与刘琨。三拊当时顽石，唤醒隆中一老，细与酌芳尊。孟夏正须雨，一洗北尘昏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1957, "title": "沁园春", "author": "程珌", "body": "读《史记》有感\n试课①阳坡，春后添栽，多少杉松。正桃坞昼浓，云溪风软，从容延叩②，太史丞公③：底事④越人，见垣一壁⑤，比过秦关遽失瞳⑥？江神吏⑦，灵能脱罟⑧，不发卫平蒙⑨？ 休言唐举无功，更休笑丘轲自阨穷⑩。算汨罗醒处⑪，元来⑫醉里；真敖假孟，毕竟谁封⑬？太史亡言⑭，床头酿熟⑮，人在晴岚⑯烟霭中。新堤路，喜樛枝⑰鳞角，夭矫苍龙⑱。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1958, "title": "昭君怨 梅花", "author": "郑域", "body": "道是花来春未，道是雪来香异。竹外一枝斜，野人家。\n冷落竹篱茅舍，富贵玉堂琼榭。两地不同栽，一般开。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1959, "title": "满江红 赤壁怀古", "author": "戴复古", "body": "赤壁矶头，一番过、一番怀古。想当时，周郎年少，气吞区宇。万骑临江貔虎噪，千艘列炬鱼龙怒。卷长波、一鼓困曹瞒，今如许？ 江上渡，江边路。形胜地，兴亡处。览遗踪，胜读史书言语。几度东风吹世换，千年往事随潮去。问道傍、杨柳为谁春，摇金缕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1960, "title": "水调歌头", "author": "戴复古", "body": "题李季允侍郎鄂州吞云楼\n轮奂半天上，胜概压南楼。筹边独坐，岂欲登览快双眸。浪说胸吞云梦，直把气吞残虏，西北望神州。百载一机会，人事恨悠悠。 骑黄鹤，赋鹦鹉，谩风流。岳王祠畔，杨柳烟锁古今愁。整顿乾坤手段，指授英雄方略，雅志若为酬。杯酒不在手，双鬓恐惊秋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1961, "title": "柳梢青 岳阳楼", "author": "戴复古", "body": "袖剑飞吟。洞庭青草，秋水深深。万顷波光，岳阳楼上，一快披襟。 不须携酒登临。问有酒、何人共斟？变尽人间，君山一点，自古如今。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1962, "title": "洞仙歌", "author": "戴复古", "body": "卖花担上，菊蕊金初破。说着重阳怎虚过。看画城，簇簇①酒肆歌楼，奈没个、巧处安排着我。 家乡煞远②哩，抵死③思量，枉把眉头万千锁。一笑且开怀，小阁团栾④，旋簇着⑤、几般蔬果。把三杯两盏记时光，问有甚曲儿，好唱一个⑥？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1963, "title": "望江南", "author": "戴复古", "body": "石屏老，家住海东云。本是寻常田舍子，如何呼唤作诗人？无益费精神。 千首富，不救一生贫。贾岛形模元自瘦，杜陵言语不妨村。谁解学西昆？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1964, "title": "木兰花慢", "author": "戴复古", "body": "莺啼啼不尽，任燕语、语难通。这一点闲愁，十年不断，恼乱春风。重来故人不见，但依然、杨柳小楼东。记得同题粉壁，而今壁破无踪。 兰皋新涨绿溶溶。流恨落花红。念著破春衫，当时送别，灯下裁缝。相思谩然自苦，算云烟、过眼总成空。落日楚天无际，凭栏目送飞鸿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1965, "title": "祝英台近", "author": "戴复古妻", "body": "惜多才，怜薄命，无计可留汝。揉碎花笺，忍写断肠句。道旁杨柳依依，千丝万缕，抵不住、一分愁绪。 如何诉。便教缘尽今生，此身已轻许。捉月盟言，不是梦中语。后回君若重来，不相忘处，把杯酒、浇奴坟土。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1966, "title": "柳梢青", "author": "黄简", "body": "病酒心情。唤愁无限，可奈流莺。又是一年，花惊寒食，柳认清明。 天涯翠巘层层。是多少、长亭短亭。倦倚东风，只凭好梦，飞到银屏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1967, "title": "绮罗香 春雨", "author": "史达祖", "body": "做冷欺花，将烟困柳，千里偷催春暮。尽日冥迷，愁里欲飞还住。惊粉重、蝶宿西园，喜泥润、燕归南浦。最妨它、佳约风流，钿车不到杜陵路。 沈沈江上望极，还被春潮晚急，难寻官渡。隐约遥峰，和泪谢娘眉妩。临断岸、新绿生时，是落红、带愁流处。记当日、门掩梨花，剪灯深夜语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1968, "title": "双双燕 咏燕", "author": "史达祖", "body": "过春社了，度帘幕中间，去年尘冷。差池欲住，试入旧巢相并。还相雕梁藻井，又软语商量不定。飘然快拂花梢，翠尾分开红影。 芳径，芹泥雨润。爱贴地争飞，竞夸轻俊。红楼归晚，看足柳昏花暝。应自栖香正稳，便忘了、天涯芳信。愁损翠黛双蛾，日日画栏独凭。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1969, "title": "夜行船", "author": "史达祖", "body": "正月十八日闻卖杏花有感\n不剪春衫愁意态。过收灯、有些寒在。小雨空帘，无人深巷，已早杏花先卖。 白发潘郎宽沈带。怕看山、忆他眉黛。草色拖裙，烟光惹鬓，常记故园挑菜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1970, "title": "东风第一枝 咏春雪", "author": "史达祖", "body": "巧沁兰心，偷粘草甲，东风欲障新暖。谩凝碧瓦难留，信知暮寒较浅。行天入镜，做弄出、轻松纤软。料故园、不卷重帘，误了乍来双燕。 青未了、柳回白眼，红欲断、杏开素面。旧游忆着山阴，后盟遂妨上苑。熏炉重熨，便放慢、春衫针线。恐凤鞋挑菜归来，万一灞桥相见。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1971, "title": "万年欢 春思", "author": "史达祖", "body": "两袖梅风，谢桥边、岸痕犹带残雪。过了匆匆灯市，草根青发。燕子春愁未醒，误几处、芳音辽绝。烟溪上、采绿人归，定应愁沁花骨。 非干厚情易歇。奈燕台句老，难道离别。小径吹衣，曾记故里风物。多少惊心旧事，第一是、侵阶罗袜。如今但、柳发晞春，夜来和露梳月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1972, "title": "三姝媚", "author": "史达祖", "body": "烟光摇缥瓦。望晴檐多风，柳花如洒。锦瑟横床，想泪痕尘影，凤弦常下。倦出犀帷，频梦见、王孙骄马。讳道相思，偷理绡裙，自惊腰衩。 惆怅南楼遥夜，记翠箔张灯，枕肩歌罢。又入铜驼，遍旧家门巷，首询声价。可惜东风，将恨与、闲花俱谢。记取崔徽模样，归来暗写。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1973, "title": "寿楼春 寻春服感念", "author": "史达祖", "body": "裁春衫寻芳。记金刀素手，同在晴窗。几度因风残絮，照花斜阳。谁念我，今无裳？自少年、消磨疏狂。但听雨挑灯，攲床病酒，多梦睡时妆。 飞花去，良宵长。有丝阑①旧曲，金谱新腔。最恨湘云人散，楚兰魂伤。身是客、愁为乡。算玉箫、犹逢韦郎。近寒食人家，相思未忘蘋藻香。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1974, "title": "解佩令", "author": "史达祖", "body": "人行花坞，衣沾香雾。有新词、逢春分付。屡欲传情，奈燕子、不曾飞去。倚珠帘、咏郎秀句。 相思一度，秾愁一度。最难忘、遮灯私语。淡月梨花，借梦来、花边廊庑。指春衫、泪曾溅处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1975, "title": "留春令 咏梅花", "author": "史达祖", "body": "故人溪上，挂愁无奈，烟梢月树。一涓春月点黄昏，便没顿、相思处。 曾把芳心深相许。故梦劳诗苦。闻说东风亦多情，被竹外、香留住。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1976, "title": "蝶恋花", "author": "史达祖", "body": "二月东风吹客袂①。苏小②门前，杨柳如腰细。蝴蝶识人游冶③地，旧曾来处花开未？ 几夜湖山生梦寐。评泊④寻芳，只怕春寒里。今岁清明逢上巳⑤，相思先到溅裙⑥水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1977, "title": "临江仙", "author": "史达祖", "body": "倦客如今老矣，旧时可奈春何！几曾湖上不经过。看花南陌醉，驻马翠楼歌。 远眼愁随芳草，湘裙忆着春罗。枉教装得旧时多。向来歌舞地，犹见柳婆娑。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1978, "title": "临江仙", "author": "史达祖", "body": "愁与西风应有约，年年同赴清秋。旧游帘幕记扬州。一灯人著梦，双燕月当楼。 罗带鸳鸯尘暗淡，更须整顿风流。天涯万一见温柔。瘦应缘此瘦，羞亦为郎羞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1979, "title": "湘江静", "author": "史达祖", "body": "暮草堆青云浸浦。记匆匆倦篙曾驻。渔榔四起，沙鸥未落，怕愁沾诗句。碧袖一声歌，石城怨、西风随去。沧波荡晚，菰蒲弄秋，还重到、断魂处。 酒易醒，思正苦。想空山、桂香悬树。三年梦冷，孤吟意短，屡烟钟津鼓。屐齿厌登临，移橙后、几番凉雨。潘郎渐老，风流顿减，《闲居》未赋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1980, "title": "齐天乐 白发", "author": "史达祖", "body": "秋风早入潘郎鬓，斑斑遽惊如许。暖雪侵梳，晴丝拂领，栽满愁城深处。瑶簪谩妒。便羞插宫花，自怜衰暮。尚想春情，旧吟凄断茂陵女。 人间公道惟此，叹朱颜也恁，容易堕去。涅不重缁，搔来更短，方悔风流相误。郎潜几缕。渐疏了铜驼，俊游俦侣。纵有黟黟，奈何诗思苦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1981, "title": "秋霁", "author": "史达祖", "body": "江水苍苍，望倦柳愁荷，共感秋色。废阁先凉，古帘空暮，雁程最嫌风力。故园信息。爱渠入眼南山碧。念上国。谁是、脍鲈江汉未归客。 还又岁晚，瘦骨临风，夜闻秋声，吹动岑寂。露蛩悲、清灯冷屋，翻书愁上鬓毛白。年少俊游浑断得。但可怜处，无奈苒苒魂惊，采香南浦，剪梅烟驿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1982, "title": "满江红 中秋夜潮", "author": "史达祖", "body": "万水归阴，故潮信盈虚因月。偏只到、凉秋半破，斗成双绝。有物揩磨金镜净，何人拏攫银河决？想子胥今夜见嫦娥，沉冤①雪。 光直下，蛟龙穴；声直上，蟾蜍窟②。对望中天地，洞然如刷。激气已能驱粉黛，举杯便可吞吴越。待明朝说似与儿曹，心应折③！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1983, "title": "满江红 书怀", "author": "史达祖", "body": "好领青衫①，全不向、诗书中得。还也费、区区造物，许多心力。未暇买田清颍尾②，尚须索米长安陌③。有当时黄卷④满前头，多惭德。 思往事，嗟儿剧⑤；怜牛后，怀鸡肋⑥。奈稜稜⑦虎豹，九重九隔。三径就荒秋自好，一钱不值贫相逼。对黄花常待不吟诗，诗成癖。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1984, "title": "满江红", "author": "史达祖", "body": "九月二十一日出京怀古\n缓辔西风，叹三宿、迟迟行客。桑梓外，锄耰渐入，柳坊花陌。双阙远腾龙凤影，九门空锁鸳鸾翼。更无人擫笛傍宫墙，苔花碧。 天相汉，民怀国。天厌虏，臣离德。趁建瓴①一举，并收鳌极②。老子岂无经世术，诗人不预平戎策。办一襟风月看升平，吟春色。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1985, "title": "龙吟曲", "author": "史达祖", "body": "陪节欲行，留别社友\n道人越布单衣①，兴高爱学苏门啸②。有时也伴，四佳公子③，五陵年少④。歌里眠香，酒酣喝月，壮怀无挠。楚江南，每为神州未复，阑干静，慵登眺。 今日征夫在道，敢辞劳，风沙短帽？休吟稷穗，休寻乔木⑤，独怜遗老。同社诗囊，小窗针线，断肠秋早。看归来，几许吴霜染鬓，验愁多少！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1986, "title": "齐天乐", "author": "史达祖", "body": "中秋宿真定驿\n西风来劝凉云去，天东放开金镜。照野霜凝，入河桂湿①，一一冰壶②相映。殊方路永。更分破秋光，尽成悲境。有客踌躇，古庭空自吊孤影。 江南朋旧在许，也能怜天际，诗思谁领？梦断刀头，书开虿尾③，别有相思随定。忧心耿耿。对风鹊残枝，露蛩荒井。斟酌姮娥，九秋宫殿冷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1987, "title": "玉蝴蝶", "author": "高观国", "body": "唤起一襟凉思，未成晚雨，先做秋阴。楚客悲残，谁解此意登临。古台荒、断霞斜照，新梦黯、微月疏砧。总难禁。尽将幽恨，分付孤斟。 从今。倦看青镜，既迟勋业，可负烟林。断梗无凭，岁华摇落又惊心。想莼汀、水云愁凝，闲蕙帐、猿鹤悲吟。信沉沉。故园归计，休更侵寻。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1988, "title": "金人捧露盘 水仙花", "author": "高观国", "body": "梦湘云，吟湘月，吊湘灵。有谁见、罗袜尘生。凌波步弱，背人羞整六铢轻。娉娉嫋嫋，晕娇黄、玉色轻明。 香心静，波心冷，琴心怨，客心惊。怕佩解、却返瑶京。杯擎清露，醉春兰友与梅兄。苍烟万顷，断肠是、雪冷江清。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1989, "title": "菩萨蛮", "author": "高观国", "body": "春风吹绿湖边草，春光依旧湖边道。玉勒锦障泥，少年游冶时。 烟明花似绣，且醉旗亭酒。斜日照花西，归鸦花外啼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1990, "title": "菩萨蛮", "author": "高观国", "body": "何须急管吹云暝，高寒滟滟开金饼。今夕不登楼，一年空过秋。 桂花香雾冷，梧叶西风影。客醉倚河桥，清光愁玉箫。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1991, "title": "霜天晓角", "author": "高观国", "body": "春云粉色。春水和云湿。试问西湖杨柳，东风外、几丝碧。望极。连翠陌。兰桡双桨急。欲访莫愁何处，旗亭在、画桥侧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1992, "title": "少年游 草", "author": "高观国", "body": "春风吹碧，春云映绿，晓梦入芳裀。软衬飞花，远随流水，一望隔香尘。 萋萋多少江南恨，翻忆翠罗裙。冷落闲门，凄迷古道，烟雨正愁人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1993, "title": "雨中花", "author": "高观国", "body": "旆拂西风，客应星汉，行参玉节征鞍。缓带轻裘，争看盛世衣冠。吟倦西湖风月，去看北塞关山。过离宫禾黍，故垒烟尘，有泪应弹。 文章俊伟，颖露囊锥，名动万里呼韩。知素有、平戎手段，小试何难。情寄吴梅香冷，梦随陇雁霜寒。立勋未晚，归来依旧，酒社诗坛。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1994, "title": "醉落魄", "author": "魏了翁", "body": "人日南山约应提刑懋之\n无边春色。人情苦向南山觅。村村箫鼓家家笛。祈麦祈蚕，来趁元正七。 翁前子后孙扶掖。商行贾坐农耕织。须知此意无今昔。会得为人，日日是人日。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1995, "title": "朝中措", "author": "魏了翁", "body": "次韵同官约瞻叔兄（□□）及杨仲博（约）赏郡圃牡丹并遣酒代劝\n玳筵绮席绣芙蓉。客意乐融融。吟罢风头摆翠，醉馀日脚沉红。 简书绊我，赏心无托，笑口难逢。梦草闲眠暮雨，落花独倚春风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1996, "title": "清平乐", "author": "李从周", "body": "美人娇小。镜里容颜好。秀色侵人春帐晓。郎去几时重到？\n叮咛记取儿家：碧云隐映红霞；直下小桥流水，门前一树桃花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1997, "title": "木兰花慢", "author": "卢祖皋", "body": "别西湖两诗僧\n嫩寒催客棹，载酒去，载诗归。正红叶漫山，清泉漱石，多少心期。三生溪桥话别，怅薜萝犹惹翠云衣。不似今番醉梦，帝城几度斜晖。 鸿飞，烟水瀰瀰。回首处，只君知。念吴江鹭忆，孤山鹤怨，依旧东西。高峰梦醒云起，是瘦吟窗底忆君时。何日还寻后约，为余先寄梅枝。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1998, "title": "贺新郎", "author": "卢祖皋", "body": "彭传师于吴江三高堂之前作钓雪亭，盖擅渔人之窟宅以供诗境也，赵子野约余赋之。\n挽住风前柳，问鸱夷当日扁舟，近曾来否？月落潮生无限事，零落茶烟未久。谩留得莼鲈依旧。可是功名从来误，抚荒祠、谁继风流后？今古恨，一搔首。 江涵雁影梅花瘦，四无尘、雪飞云起，夜窗如昼。万里乾坤清绝处，付与渔翁钓叟。又恰是、题诗时候。猛拍阑干呼鸥鹭，道他年、我亦垂纶手。飞过我，共樽酒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 1999, "title": "眼儿媚", "author": "洪咨夔", "body": "平沙芳草渡头村，绿遍去年痕。游丝下上，流莺来往，无限销魂。 绮窗深静人归晚，金鸭水沉温。海棠影下，子规声里，立尽黄昏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2000, "title": "西河", "author": "王埜", "body": "天下事，问天怎忍如此！陵图谁把献君王，结愁未已。少豪气概总成尘，空馀白骨黄苇。 千古恨，吾老矣。东游曾吊淮水。绣春台上一回登，一回揾泪。醉归抚剑倚西风，江涛犹壮人意。 只今袖手野色里，望长淮、犹二千里。纵有英心谁寄！近新来又报胡尘起。绝域张骞归来未？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2001, "title": "西河 和王潜斋韵", "author": "曹豳", "body": "今日事，何人弄得如此！漫漫白骨蔽川原，恨何日已！关河万里寂无烟，月明空照芦苇。 谩哀痛，无及矣。无情莫问江水。西风落日惨新亭，几人堕泪！战和何者是良筹，扶危但看天意。 只今寂寞薮泽里，岂无人、高卧闾里，试问安危谁寄？定相将有诏催公起。须信前书言犹未？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2002, "title": "浪淘沙 题酒家壁", "author": "周文璞", "body": "还了酒家钱，便好安眠。大槐宫里着貂蝉。行到江南知是梦，雪压渔船。 盘礴古梅边，也是前缘。鹅黄雪白又醒然。一事最奇君记取：明日新年。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2003, "title": "高阳台 除夜", "author": "韩疁", "body": "频听银签，重燃绛蜡，年华衮衮惊心。饯旧迎新，能消几刻光阴。老来可惯通宵饮？待不眠、还怕寒侵。掩清尊，多谢梅花，伴我微吟。 邻娃已试春妆了，更蜂腰簇翠，燕股横金。勾引东风，也知芳思难禁。朱颜那有年年好，逞艳游、赢取如今。恣登临：残雪楼台，迟日园林。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2004, "title": "烛影摇红", "author": "孙惟信", "body": "一朵鞓红，宝钗压髻东风溜。年时也是牡丹时，相见花边酒。初试夹纱半袖。与花枝、盈盈斗秀。对花临景，为景牵情，因花感旧。 题叶无凭，曲沟流水空回首。梦云不入小山屏，真个欢难偶。别后知他安否。软红街、清明还又。絮飞春尽，天远书沉，日长人瘦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2005, "title": "满江红", "author": "岳珂", "body": "小院深深，悄镇日、阴晴无据。春未足，闺愁难寄，琴心谁与？曲径穿花寻蛱蝶，虚阑傍日教鹦鹉。笑十三杨柳女儿腰，东风舞。 云外月，风前絮。情与恨，长如许。想绮窗今夜，为谁凝伫？洛浦梦回留珮客，秦楼声断吹箫侣。正黄昏时候杏花寒，廉纤雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2006, "title": "祝英台近 北固亭", "author": "岳珂", "body": "淡烟横，层雾敛。胜概分雄占。月下鸣榔，风急怒涛飐。关河无限清愁，不堪临鉴。正霜鬓、秋风尘染。 漫登览。极目万里沙场，事业频看剑。古往今来，南北限天堑。倚楼谁弄新声，重城正掩。历历数、西州更点。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2007, "title": "霜天晓角", "author": "黄机", "body": "仪真江上夜泊\n寒江夜宿，长啸江之曲。水底鱼龙惊动，风卷地，浪翻屋。 诗情吟未足，酒兴断还续。草草兴亡休问，功名泪，欲盈掬。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2008, "title": "忆秦娥", "author": "黄机", "body": "秋萧索，梧桐落尽西风恶。西风恶，数声新雁，数声残角。离愁不管人飘泊，年年孤负黄花约。黄花约，几重庭院，几重帘幕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2009, "title": "满江红", "author": "严羽", "body": "送廖叔仁赴阙\n日近觚棱，秋渐满、蓬莱双阙。正钱塘江上，潮头如雪。把酒送君天上去，琼琚玉珮鹓鸿列。丈夫儿、富贵等浮云，看名节。 天下事，吾能说；今老矣，空凝绝。对西风慷慨，唾壶歌缺。不洒世间儿女泪，难堪亲友中年别。问相思、他日镜中看，萧萧发。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2010, "title": "鹧鸪天 惜别", "author": "严仁", "body": "一曲危弦断客肠。津桥捩柂①转牙樯。江心云带蒲帆重，楼上风吹粉泪香。 瑶草碧，柳芽黄。载将离恨过潇湘。请君看取东流水，方识人间别意长。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2011, "title": "玉楼春 春思", "author": "严仁", "body": "春风只在园西畔，荠菜花繁蝴蝶乱。冰池晴绿照还空，香径落红吹已断。 意长翻恨游丝短，尽日相思罗带缓。宝奁明月不欺人，明日归来君试看。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2012, "title": "醉桃源 春景", "author": "严仁", "body": "拍堤春水蘸垂杨，水流花片香。弄花噆柳小鸳鸯，一双随一双。 帘半卷，露新妆，春衫是柳黄。倚阑看处背斜阳，风流暗断肠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2013, "title": "疏帘淡月 秋思", "author": "张辑", "body": "梧桐雨细，渐滴作秋声，被风惊碎。润逼衣篝，线袅蕙炉沉水。悠悠岁月天涯醉。一分秋、一分憔悴。紫箫吹断，素笺恨切，夜寒鸿起。 又何苦、凄凉客里。负草堂春绿，竹溪空翠。落叶西风，吹老几番尘世。从前谙尽江湖味。听商歌、归兴千里。露侵宿酒，疏帘淡月，照人无寐。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2014, "title": "月上瓜洲", "author": "张辑", "body": "南徐多景楼作\n江头又见新秋，几多愁？塞草连天何处是神州？ 英雄恨，古今泪，水东流。惟有渔竿明月上瓜洲。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2015, "title": "水龙吟 采药径", "author": "葛长庚", "body": "云屏漫锁空山，寒猿啼断松枝翠。芝英安在，术苗已老，徒劳屐齿。应记洞中，凤箫锦瑟，镇常歌吹。怅苍苔路杳，石门信断，无人问、溪头事。 回首暝烟无际，但纷纷、落花如泪。多情易老，青鸾何处，书成难寄。欲问双娥，翠蝉金凤，向谁娇媚。想分香旧恨，刘郎去后，一溪流水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2016, "title": "水调歌头", "author": "葛长庚", "body": "江上春山远，山下暮云长。相留相送，时见双燕语风樯。满目飞花万点，回首故人千里，把酒沃愁肠。回雁峰前路，烟树正苍苍。 漏声残，灯焰短，马蹄香。浮云飞絮，一身将影向潇湘。多少风前月下，迤逦天涯海角，魂梦亦凄凉。又是春将暮，无语对斜阳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2017, "title": "行香子 题罗浮", "author": "葛长庚", "body": "满洞苔钱。买断风烟。笑桃花流落晴川。石楼高处，夜夜啼猿。看二更云，三更月，四更天。 细草如毡。独枕空拳。与山麋野鹿同眠。残霞未散，淡雾沈绵。是晋时人，唐时洞，汉时仙。（原注：洞府自唐尧时始开，至东晋葛稚川方来。及伪刘称汉，此时方显，遂兴观。）", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2018, "title": "沁园春 梦孚若", "author": "刘克庄", "body": "何处相逢？登宝钗楼，访铜雀台。唤厨人斫就，东溟鲸脍；圉人呈罢，西极龙媒。天下英雄，使君与操，馀子谁堪共酒杯？车千乘，载燕南赵北，剑客奇才。 饮酣画鼓如雷，谁信被晨鸡轻唤回。叹年光过尽，功名未立；书生老去，机会方来。使李将军，遇高皇帝，万户侯何足道哉！披衣起，但凄凉感旧，慷慨生哀。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2019, "title": "沁园春", "author": "刘克庄", "body": "答九华叶贤良\n一卷《阴符》，二石硬弓，百斤宝刀。更玉花驄喷，鸣鞭电抹；乌丝阑展，醉墨龙跳。牛角书生，虬须豪客，谈笑皆堪折简招。依稀记，曾请缨系粤，草檄征辽。 当年目视云霄，谁信道、凄凉今折腰。怅燕然未勒，南归草草；长安不见，北望迢迢。老去胸中，有些磊块，歌罢犹须著酒浇。休休也，但帽边鬓改，镜里颜凋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2020, "title": "木兰花慢 渔父词", "author": "刘克庄", "body": "海滨蓑笠叟，驼背曲，鹤形臞。定不是凡人，古来贤哲，多隐于渔。任公子，龙伯氏，思量来岛大上钩鱼；又说巨𪓴吞饵，牵翻员峤方壶。 磻溪老子雪眉须，肘后有丹书。被西伯载归，营丘茅土①，牧野檀车②。世间久无是事，问苔矶痴坐待谁欤？只怕先生渴睡，钓竿拂着珊瑚。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2021, "title": "摸鱼儿 海棠", "author": "刘克庄", "body": "甚春来、冷烟凄雨，朝朝迟了芳信。蓦然作暖晴三日，又觉万姝娇困。霜点鬓。潘令老，年年不带看花分①。才情减尽。怅玉局飞仙，石湖绝笔，孤负这风韵。 倾城色，懊恼佳人薄命。墙头岑寂谁问？东风日暮无聊赖，吹得胭脂成粉。君细认。花共酒，古来二事天尤吝。年光去迅。漫绿叶成阴，青苔满地，做得异时恨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2022, "title": "长相思 惜梅", "author": "刘克庄", "body": "寒相催。暖相催。催了开时催谢时。丁宁花放迟。\n角声吹。笛声吹。吹了南枝吹北枝。明朝成雪飞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2023, "title": "昭君怨 牡丹", "author": "刘克庄", "body": "曾看洛阳旧谱，只许姚黄独步。若比广陵花，太亏他。\n旧日王侯园圃，今日荆榛狐兔。君莫说中州，怕花愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2024, "title": "满江红", "author": "刘克庄", "body": "夜雨凉甚，忽动从戎之兴\n金甲雕戈，记当日辕门初立。磨盾鼻，一挥千纸，龙蛇犹湿。铁马晓嘶营壁冷，楼船夜渡风涛急。有谁怜、猿臂故将军，无功级？ 平戎策，从军什；零落尽，慵收拾。把《茶经》《香传》①，时时温习。生怕客谈榆塞事，且教儿诵《花间集》。叹臣之壮也不如人，今何及②！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2025, "title": "满江红 题范尉梅谷", "author": "刘克庄", "body": "赤日黄埃，梦不到清溪翠麓。空健羡、君家别墅，几株幽独。骨冷肌清偏要月，天寒日暮尤宜竹。想主人杖履绕千回，山南北。 宁委涧，嫌金屋；宁映水，羞银烛。叹出群风韵，背时装束。竞爱东邻姬傅粉，谁怜空谷人如玉？笑林逋何逊漫为诗，无人读。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2026, "title": "满江红", "author": "刘克庄", "body": "和王实之韵送郑伯昌\n怪雨盲风，留不住江边行色。烦问讯、冥鸿高士，钓鳌词客。千百年传吾辈语，二三子系斯文脉。听王郎一曲玉箫声，凄金石。 晞发处，怡山碧；垂钓处，沧溟白。笑而今拙宦，他年遗直。只愿常留相见面，未宜轻屈平生膝。有狂谈欲吐且休休，惊邻壁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2027, "title": "贺新郎", "author": "刘克庄", "body": "送陈真州子华\n北望神州路，试平章、这场公事，怎生分付？记得太行山百万，曾入宗爷驾驭。今把作握蛇骑虎。君去京东豪杰喜，想投戈下拜真吾父。谈笑里，定齐鲁。 两淮萧瑟惟狐兔。问当年、祖生去后，有人来否？多少新亭挥泪客，谁梦中原块土？算事业须由人做。应笑书生心胆怯，向车中、闭置如新妇。空目送，塞鸿去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2028, "title": "贺新郎 九日", "author": "刘克庄", "body": "湛湛长空黑，更那堪、斜风细雨，乱愁如织。老眼平生空四海，赖有高楼百尺。看浩荡、千崖秋色。白发书生神州泪，尽凄凉、不向牛山滴。追往事，去无迹。 少年自负凌云笔。到而今、春华落尽，满怀萧瑟。常恨世人新意少，爱说南朝狂客。把破帽年年拈出。若对黄花孤负酒，怕黄花也笑人岑寂。鸿北去，日西匿。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2029, "title": "贺新郎", "author": "刘克庄", "body": "席上闻歌有感\n妾出于微贱。少年时、朱弦弹绝，玉笙吹遍。粗识《国风·关雎》乱①，羞学流莺百啭。总不涉、闺情春怨。谁向西邻公子说，要珠鞍、迎入梨花院。身未动，意先懒。 主家十二楼连苑。那人人、靓妆按曲，绣帘初卷。道是华堂箫管唱，笑杀街坊拍衮②。回首望、侯门天远。我有平生《离鸾操》，颇哀而不愠③微而婉。聊一奏，更三叹④。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2030, "title": "贺新郎", "author": "刘克庄", "body": "实之三和有忧边之语，走笔答之\n国脉微如缕。问长缨何时入手，缚将戎主？未必人间无好汉，谁与宽些尺度？试看取当年韩五。岂有谷城公付授，也不干曾遇骊山母。谈笑起，两河路。 少时棋柝曾联句。叹而今登楼揽镜，事机频误。闻说北风吹面急，边上冲梯屡舞。君莫道投鞭虚语。自古一贤能制难，有金汤便可无张许？快投笔，莫题柱。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2031, "title": "风入松", "author": "刘克庄", "body": "归鞍尚欲小徘徊。逆境难排。人言酒是消忧物，奈病余孤负金罍。萧瑟擣衣时候，凄凉鼓缶情怀。 远林摇落晚风哀，野店犹开。多情惟是灯前影，伴此翁同去同来。逆旅主人相问，今回老似前回。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2032, "title": "一剪梅 袁州解印", "author": "刘克庄", "body": "陌上行人怪府公，还是诗穷，还是文穷？下车上马太匆匆，来是春风，去是秋风。 阶衔免得带兵农，嬉到昏钟，睡到斋钟。不消提岳与知宫，唤作山翁，唤作溪翁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2033, "title": "一剪梅", "author": "刘克庄", "body": "余赴广东，实之夜饯于风亭\n束缊宵行十里强，挑得诗囊，抛了衣囊。天寒路滑马蹄僵，元是王郎，来送刘郎。 酒酣耳热说文章，惊倒邻墙，推倒胡床。旁观拍手笑疏狂，疏又何妨，狂又何妨！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2034, "title": "玉楼春", "author": "刘克庄", "body": "戏呈林节推乡兄\n年年跃马长安市，客舍似家家似寄。青钱换酒日无何，红烛呼卢宵不寐。 易挑锦妇机中字，难得玉人心下事。男儿西北有神州，莫滴水西桥畔泪！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2035, "title": "卜算子", "author": "刘克庄", "body": "片片蝶衣轻，点点猩红小。道是天公不惜花，百种千般巧。\n朝见树头繁，暮见枝头少。道是天公果惜花，雨洗风吹了。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2036, "title": "清平乐", "author": "刘克庄", "body": "五月十五夜玩月\n纤云扫迹，万顷玻璃色。醉跨玉龙游八极，历历天青海碧。\n水晶宫殿飘香，群仙方按《霓裳》。消得几多风露，变教人世清凉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2037, "title": "清平乐", "author": "刘克庄", "body": "五月十五夜玩月\n风高浪快，万里骑蟾背。曾识姮娥真体态，素面原无粉黛。\n身游银阙珠宫，俯看积气濛濛。醉里偶摇桂树，人间唤作凉风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2038, "title": "清平乐", "author": "刘克庄", "body": "顷在维扬，陈师文参议家舞姬绝妙，赋此\n宫腰束素，只怕能轻举。好筑避风台护取，莫遣惊鸿飞去。\n一团香玉温柔，笑颦俱有风流。贪与萧郎眉语，不知舞错《伊州》。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2039, "title": "忆秦娥", "author": "刘克庄", "body": "梅谢了，塞垣冻解鸿归早。鸿归早，凭伊问讯，大梁遗老。\n浙河西面边声悄，淮河北去炊烟少。炊烟少。宣和宫殿，冷烟衰草。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2040, "title": "扬州慢", "author": "赵以夫", "body": "琼花①，唯扬州后土殿②前一本。比聚八仙③大率相类，而不同者有三：琼花大而瓣厚，其色淡黄，聚八仙花小而瓣薄，其色微青，不同者一也。琼花叶柔而莹泽，聚八仙叶粗而有芒，不同者二也。琼花蕊与花平，不结子而香，聚八仙蕊低于花，结子而不香，不同者三也。友人折赠数枝，云移根自鄱阳之洪氏④。赋而感之。其调曰《扬州慢》。\n十里春风，二分明月，蕊仙⑤飞下琼楼。看冰花翦翦⑥，拥碎玉成毬。想长日、云阶⑦伫立，太真肌骨，飞燕风流。敛群芳、清丽精神，都付扬州。 雨窗数朵，梦惊回、天际香浮。似阆苑⑧花神，怜人冷落，骑鹤来游⑨。为问竹西风景，长空淡、烟水悠悠。又黄昏，羌管孤城，吹起新愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2041, "title": "鹊桥仙", "author": "赵以夫", "body": "富沙七夕为友人赋\n翠绡心事，红楼欢宴，深夜沉沉无暑。竹边荷外再相逢，又还是、浮云飞去。 锦笺尚湿，珠香未歇，空惹闲愁千缕。寻思不似鹊桥人，犹自得、一年一度。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2042, "title": "扬州慢 琼花", "author": "郑觉斋", "body": "弄玉轻盈，飞琼淡泞，袜尘步下迷楼。试新妆才了，炷沉水香毬。记晓剪、春冰驰送，金瓶露湿，缇骑星流。甚天中月色，被风吹梦南州。 尊前相见，似羞人、踪迹萍浮。问弄雪飘枝，无双亭上，何日重游？我欲缠腰骑鹤，烟霄远、旧事悠悠。但凭阑无语，烟花三月春愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2043, "title": "青玉案", "author": "张榘", "body": "被檄出郊题陈氏山居\n西风乱叶溪桥树，秋在黄花羞涩处。满袖尘埃推不去。马蹄浓露，鸡声淡月，寂历荒村路。 身名都被儒冠误，十载重来漫如许。且尽清樽公莫舞。六朝旧事，一江流水，万感天涯暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2044, "title": "霜天晓角", "author": "华岳", "body": "情刀无斸，割尽相思肉。说后说应难尽，除非是、写成轴。\n帖儿烦付祝，休对旁人读。恐怕那懑知后，和它也泪瀑漱。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2045, "title": "满江红", "author": "赵希蓬", "body": "劲节刚姿，谁与比、岁寒松柏？几度欲、排云呈腹，叩头流血。杜老爱君□谩苦，贾生流涕衣空湿。为国家、子细计安危，渊然识。 英雄士，非全阙。东南富，尤难匹。却甘心修好，无心逐北！螳怒空横林影臂，鹰扬不展秋空翼。但只将南北限藩篱，长江隔！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2046, "title": "念奴娇", "author": "吴渊", "body": "我来牛渚，聊登眺、客里襟怀如豁。谁著危亭当此处，占断古今愁绝。江势鲸奔，山形虎踞，天险非人设。向来舟舰，曾扫百万胡羯。 追念照水然犀，男儿当似此，英雄豪杰。岁月匆匆留不住，鬓已星星堪镊。云暗江天，烟昏淮地，是断魂时节。栏干捶碎，酒狂忠愤俱发。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2047, "title": "江城子", "author": "李好古", "body": "平沙浅草接天长。路茫茫，几兴亡。昨夜波声，洗岸骨如霜。千古英雄成底事，徒感慨，漫悲凉。 少年有意伏中行，馘名王，扫沙场。击楫中流，曾记泪沾裳。欲上治安双阙远，空怅望，过维扬。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2048, "title": "水调歌头", "author": "哀长吉", "body": "贺人新娶，集曲名。\n紫陌风光好，绣阁绮罗香。相将人月圆夜，早庆贺新郎。先自少年心意，为惜殢①人娇态，久俟②愿成双。此夕于飞乐，共学燕归梁。 索酒子③，迎仙客，醉红妆。诉衷情处，些儿④好语意难忘。但愿千秋岁里，结取万年欢会，恩爱应天长。行⑤喜长春宅，兰玉满庭芳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2049, "title": "喜迁莺", "author": "冯去非", "body": "凉生遥渚。正绿芰擎霜，黄花招雨。雁外渔村，蛩边蟹舍，绛叶满秋来路。世事不离双鬓，远梦偏欺孤旅。送望眼，但凭舷微笑，书空无语。 慵觑。清镜里，十载征尘，长把朱颜污。借箸青油，挥毫紫塞，旧事不堪重举。间阔故山猿鹤，冷落同盟鸥鹭。倦游也，便樯云舵月，浩歌归去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2050, "title": "满江红 送李御带珙", "author": "吴潜", "body": "红玉阶前，问何事、翩然引去？湖海上、一汀鸥鹭，半帆烟雨。报国无门空自怨，济时有策从谁吐？过垂虹、亭下系扁舟，鲈堪煮。 拚一醉，留君住。歌一曲，送君路。遍江南江北，欲归何处？世事悠悠浑未了，年光冉冉今如许！试举头、一笑问青天，天无语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2051, "title": "满江红 豫章滕王阁", "author": "吴潜", "body": "万里西风，吹我上、滕王高阁。正槛外、楚山云涨，楚江涛作。何处征帆木末去，有时野鸟沙边落。近帘钩、暮雨掩空来，今犹昨。 秋渐紧，添离索。天正远，伤飘泊。叹十年心事，休休莫莫。岁月无多人易老，乾坤虽大愁难着。向黄昏、断送客魂消，城头角。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2052, "title": "满江红 金陵乌衣园", "author": "吴潜", "body": "柳带榆钱，又还过、清明寒食。天一笑、满园罗绮，满城箫笛。花树得晴红欲染，远山过雨青如滴。问江南池馆有谁来？江南客。 乌衣巷，今犹昔。乌衣事，今难觅。但年年燕子，晚烟斜日。抖擞一春尘土债，悲凉万古英雄迹。且芳尊随分趁芳时，休虚掷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2053, "title": "水调歌头 焦山", "author": "吴潜", "body": "铁瓮古形势，相对立金焦。长江万里东注，晓吹卷惊涛。天际孤云来去，水际孤帆上下，天共水相邀。远岫忽明晦，好景画难描。 混隋陈，分宋魏，战孙曹。回头千载陈迹，痴绝倚亭皋。惟有汀边鸥鹭，不管人间兴废，一抹度青霄。安得身飞去，举手谢尘嚣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2054, "title": "南柯子", "author": "吴潜", "body": "池水凝新碧，栏花驻老红。有人独立画桥东，手把一枝杨柳系春风。 鹊绊游丝坠，蜂拈落蕊空。秋千庭院小帘栊，多少闲情闲绪雨声中。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2055, "title": "鹊桥仙", "author": "吴潜", "body": "扁舟昨泊，危亭孤啸，目断闲云千里。前山急雨过溪来，尽洗却、人间暑气。 暮鸦木末，落凫天际，都是一团秋意。痴儿騃女贺新凉，也不道、西风又起。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2056, "title": "海棠春", "author": "吴潜", "body": "己未清明对海棠有赋\n海棠亭午沾疏雨，便一饷、胭脂尽吐。老去惜花心，相对花无语。 羽书万里飞来处，报扫荡、狐嗥兔舞。濯锦古江头，飞景还如许！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2057, "title": "减字木兰花", "author": "淮上女", "body": "淮山隐隐，千里云峰千里恨。淮水悠悠，万顷烟波万顷愁。 山长水远，遮断行人东望眼。恨旧愁新，有泪无言对晚春。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2058, "title": "湘春夜月", "author": "黄孝迈", "body": "近清明，翠禽枝上消魂。可惜一片清歌，都付与黄昏。欲共柳花低诉，怕柳花轻薄，不解伤春。念楚乡旅宿，柔情别绪，谁与温存！ 空樽夜泣，青山不语，残照当门。翠玉楼前，惟是有、一波湘水，摇荡湘云。天长梦短，问甚时、重见桃根？这次第，算人间没个并刀，剪断心上愁痕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2059, "title": "点绛唇", "author": "周晋", "body": "访牟存叟南漪钓隐\n午梦初回，卷帘尽放春愁去。昼长无侣，自对黄鹂语。\n絮影蘋香，春在无人处。移舟去。未成新句，一砚梨花雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2060, "title": "清平乐", "author": "周晋", "body": "图书一室。香暖垂帘密。花满翠壶熏研席。睡觉满窗晴日。\n手寒不了残棋。篝香细勘唐碑。无酒无诗情绪，欲梅欲雪天时。\n宋人词意\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2061, "title": "长相思", "author": "陈东甫", "body": "花深深。柳阴阴。度柳穿花觅信音。君心负妾心。\n怨鸣琴。恨孤衾。钿誓钗盟何处寻？当初谁料今。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2062, "title": "沁园春 饯税巽甫", "author": "李曾伯", "body": "唐人以处士辟幕府如石、温辈甚多。税君巽甫以命士来淮幕三年矣，略不能挽之以寸。巽甫虽安之，如某歉何！临别，赋《沁园春》以饯。\n水北洛南，未尝无人，不同者时。赖交情兰臭，绸缪相好；宦情云薄，得失何知？夜观论兵，春原吊古，慷慨事功千载期。萧如也，料行囊如水，只有新诗。 归兮，归去来兮，我亦办征帆非晚归。正姑苏台畔，米廉酒好；吴松江上，莼嫩鱼肥。我住孤村，相连一水，载月不妨时过之。长亭路，又何须回首，折柳依依。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2063, "title": "沁园春", "author": "李曾伯", "body": "丙午登多景楼和吴履斋韵\n天下奇观，江浮两山，地雄一州。对晴烟抹翠，怒涛翻雪；离离塞草，拍拍风舟。春去春来，潮生潮落，几度斜阳人倚楼。堪怜处，怅英雄白发，空敝貂裘。 淮头，虏尚虔刘，谁为把中原一战收？问只今人物，岂无安石；且容老子，还访浮丘。鸥鹭眠沙，渔樵唱晚，不管人间半点愁。危栏外，渺沧波无极，去去归休。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2064, "title": "青玉案 癸未道间", "author": "李曾伯", "body": "栖鸦啼破烟林暝，把旅梦、俄惊醒。猛拍征鞍登小岭。峰回路转，月明人静，幻出清凉境。 马蹄踏碎琼瑶影，任露压巾纱未忺整。贪看前山云隐隐。翠微深处，有人家否，试击柴扃问。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2065, "title": "水调歌头", "author": "方岳", "body": "平山堂用东坡韵\n秋雨一何碧，山色倚晴空。江南江北愁思，分付酒螺红。芦叶蓬舟千里，菰菜莼羹一梦，无语寄归鸿。醉眼渺河洛，遗恨夕阳中。 蘋洲外，山欲暝，敛眉峰。人间俯仰陈迹，叹息两仙翁。不见当时杨柳，只是从前烟雨，磨灭几英雄。天地一孤啸，匹马又西风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2066, "title": "瑞鹤仙 寿丘提刑", "author": "方岳", "body": "一年寒尽也。问秦沙、梅放未也。幽寻者谁也。有何郎佳约，岁云除也。南枝暖也。正同云、商量雪也。喜乐皇，一转洪钧，依旧春风中也。 香也。骚情酿就，书味熏成，这些情也。玉堂深也。莫道年华归也。是循环、三百六旬六日，生意无穷已也。但丁宁，留取微酸，调商鼎也。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2067, "title": "霜天晓角 梅", "author": "萧泰来", "body": "千霜万雪。受尽寒磨折。赖是生来瘦硬，浑不怕、角吹彻。\n清绝。影也别。知心惟有月。原没春风情性，如何共、海棠说。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2068, "title": "喜迁莺", "author": "许棐", "body": "鸠雨细，燕风斜。春悄谢娘家。一重帘外即天涯，何必暮云遮？ 钏金寒，钗玉冷。薄醉欲成还醒。一春梳洗不簪花，辜负几韶华。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2069, "title": "摸鱼儿", "author": "李昴英", "body": "送王子文知太平州\n怪朝来、片红初瘦，半分春事风雨。丹山碧水含离恨，有脚阳春难驻。芳草渡。似叫住东君，满树黄鹂语。无端杜宇。报采石矶头，惊涛屋大，寒色要春护。 阳关唱，画鹢徘徊东渚。相逢知又何处。摩挲老剑雄心在，对酒细评今古。君此去。几万里东南，只手擎天柱。长生寿母。更稳坐安舆，三槐堂上，好看彩衣舞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2070, "title": "水调歌头", "author": "李昴英", "body": "题斗南楼和刘朔斋韵\n万顷黄湾口，千仞白云头。一亭收拾，便觉炎海豁清秋。潮候朝昏来去，山色雨晴浓淡，天末送双眸。绝域远烟外，高浪舞连艘。 风景别，胜滕阁，压黄楼。胡床老子，醉挥珠玉落南州。稳驾大鹏八极，叱起仙羊五石，飞佩过丹丘。一笑人间世，机动早惊鸥。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2071, "title": "霜叶飞 重九", "author": "吴文英", "body": "断烟离绪。关心事，斜阳红隐霜树。半壶秋水荐黄花，香噀西风雨。纵玉勒、轻飞迅羽，凄凉谁吊荒台古？记醉蹋南屏，彩扇咽寒蝉，倦梦不知蛮素。 聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。小蟾斜影转东篱，夜冷残蛩语。早白发、缘愁万缕。惊飙从卷乌纱去。谩细将、茱萸看，但约明年，翠微高处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2072, "title": "瑞鹤仙", "author": "吴文英", "body": "晴丝牵绪乱。对沧江斜日，花飞人远。垂杨暗吴苑。正旗亭烟冷，河桥风暖。兰情蕙盼。惹相思，春根酒畔。又争知、吟骨萦销，渐把旧衫重剪。 凄断。流红千浪，缺月孤楼，总难留燕。歌尘凝扇。待凭信，拌分钿。试挑灯欲写，还依不忍，笺幅偷和泪卷。寄残云剩雨蓬莱，也应梦见。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2073, "title": "解连环", "author": "吴文英", "body": "暮檐凉薄。疑清风动竹，故人来邈。渐夜久、闲引流萤，弄微照素怀，暗呈纤白。梦远双成，凤笙杳、玉绳西落。掩綀帷倦入，又惹旧愁，汗香阑角。 银瓶恨沉断索。叹梧桐未秋，露井先觉。抱素影、明月空闲，早尘损丹青，楚山依约。翠冷红衰，怕惊起、西池鱼跃。记湘娥、绛绡暗解，褪花坠萼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2074, "title": "宴清都 连理海棠", "author": "吴文英", "body": "绣幄鸳鸯柱。红情密，腻云低护秦树。芳根兼倚，花梢钿合①，锦屏人妒。东风睡足交枝，正梦枕、瑶钗燕股。障滟蜡、满照欢丛，嫠蟾②冷落羞度。 人间万感幽单，华清③惯浴，春盎风露。连鬟并暖，同心共结，向承恩处。凭谁为歌长恨？暗殿锁、秋灯夜雨。叙旧期、不负春盟，红朝翠暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2075, "title": "齐天乐", "author": "吴文英", "body": "与冯深居登禹陵\n三千年事残鸦外，无言倦凭秋树。逝水移川，高陵变谷，那识当时神禹。幽云怪雨。翠蓱湿空梁，夜深飞去。雁起青天，数行书似旧藏处。 寂寥西窗久坐，故人悭会遇，同翦灯语。积藓残碑，零圭断璧，重拂人间尘土。霜红罢舞。漫山色青青，雾朝烟暮。岸锁春船，画旗喧赛鼓。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2076, "title": "齐天乐", "author": "吴文英", "body": "烟波桃叶西陵路，十年断魂潮尾。古柳重攀，轻鸥骤别①，陈迹危亭独倚。凉飔乍起。渺烟碛飞帆，暮山横翠。但有江花，共临秋镜照憔悴。 华堂烛暗送客，眼波回盼处，芳艳流水。素骨凝冰，柔葱蘸雪，犹忆分瓜深意。清尊未洗。梦不湿行云，漫沾残泪。可惜秋宵，乱蛩疏雨里。\n宋人词意\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2077, "title": "过秦楼", "author": "吴文英", "body": "藻国凄迷，麹澜澄映，怨入粉烟蓝雾。香笼麝水，腻涨红波，一镜万妆争妒。湘女归魂，佩环玉冷无声，凝情谁诉。又江空月堕，凌波尘起，彩鸳愁舞。 还暗忆、钿合兰桡，丝牵琼腕，见的更怜心苦。玲珑翠屋，轻薄冰绡，稳称锦云留住。生怕哀蝉，暗惊秋被红衰，啼珠零露。能去声西风老尽，羞趁东风嫁与。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2078, "title": "浣溪沙", "author": "吴文英", "body": "门隔花深梦旧游，夕阳无语燕归愁。玉纤香动小帘钩。\n落絮无声春堕泪，行云有影月含羞。东风临夜冷于秋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2079, "title": "玉楼春 京市舞女", "author": "吴文英", "body": "茸茸狸帽遮梅额，金蝉罗翦胡衫窄。乘肩争看小腰身，倦态强随闲鼓笛。 问称家住城东陌，欲买千金应不惜。归来困顿殢春眠，犹梦婆娑斜趁拍。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2080, "title": "点绛唇 试灯夜初晴", "author": "吴文英", "body": "卷尽愁云，素娥临夜新梳洗。暗尘不起，酥润凌波地。\n辇路重来，仿佛灯前事。情如水。小楼熏被，春梦笙歌里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2081, "title": "定风波", "author": "吴文英", "body": "密约偷香□踏青，小车随马过南屏。回首东风销鬓影，重省，十年心事夜船灯。 离骨渐尘桥下水，到头难灭景中情。两岸落花残酒醒，烟冷，人家垂柳未清明。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2082, "title": "祝英台近", "author": "吴文英", "body": "春日客龟溪游废园\n采幽香，巡古苑，竹冷翠微路。斗草溪根，沙印小莲步。自怜两鬓清霜，一年寒食，又身在、云山深处。 昼闲度。因甚天也悭春，轻阴便成雨。绿暗长亭，归梦趁风絮。有情花影阑干，莺声门径，解留我、霎时凝伫。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2083, "title": "祝英台近 除夜立春", "author": "吴文英", "body": "剪红情，裁绿意，花信上钗股。残日东风，不放岁华去。有人添烛西窗，不眠侵晓，笑声转、新年莺语。 旧尊俎。玉纤曾擘黄柑，柔香系幽素。归梦湖边，还迷镜中路。可怜千点吴霜，寒销不尽，又相对、落梅如雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2084, "title": "澡兰香 淮安重午", "author": "吴文英", "body": "盘丝系腕，巧篆垂簪，玉隐绀纱睡觉。银瓶露井，彩箑云窗，往事少年依约。为当时曾写榴裙，伤心红绡褪萼。黍梦光阴，渐老汀洲烟蒻。 莫唱江南古调，怨抑难招，楚江沉魄。薰风燕乳，暗雨梅黄，午镜澡兰帘幕。念秦楼也拟人归，应剪菖蒲自酌。但怅望、一缕新蟾，随人天角。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2085, "title": "风入松", "author": "吴文英", "body": "听风听雨过清明，愁草瘗花铭。楼前绿暗分携路，一丝柳，一寸柔情。料峭春寒中酒，交加晓梦啼莺。 西园日日扫林亭，依旧赏新晴。黄蜂频扑秋千索，有当时、纤手香凝。惆怅双鸳不到，幽阶一夜苔生。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2086, "title": "莺啼序", "author": "吴文英", "body": "残寒正欺病酒，掩沈香绣户。燕来晚、飞入西城，似说春事迟暮。画船载、清明过却，晴烟冉冉吴宫树。念羁情、游荡随风，化为轻絮。 十载西湖，傍柳系马，趁娇尘软雾。溯红渐、招入仙溪，锦儿偷寄幽素。倚银屏、春宽梦窄，断红湿、歌纨金缕。暝堤空，轻把斜阳，总还鸥鹭。 幽兰旋老，杜若还生，水乡尚寄旅。别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。青楼仿佛，临分败壁题诗，泪墨惨淡尘土。 危亭望极，草色天涯，叹鬓侵半苧。暗点检：离痕欢唾，尚染鲛绡，亸凤迷归，破鸾慵舞。殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。伤心千里江南，怨曲重招，断魂在否？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2087, "title": "莺啼序", "author": "吴文英", "body": "横塘棹穿艳锦，引鸳鸯弄水。断霞晚、笑折花归，绀纱低护灯蕊。润玉瘦，冰轻倦浴，斜拖凤股盘云坠。听银床、声细梧桐，渐搅凉思。 窗隙流光，冉冉迅羽，诉空梁燕子。误惊起、风竹敲门，故人还又不至。记琅玕、新诗细掐，早陈迹、香痕纤指。怕因循，罗扇恩疏，又生秋意。 西湖旧日，画舸频移，叹几萦梦寐。霞佩冷，叠澜不定，麝霭飞雨，乍湿鲛绡，暗盛红泪。綀单夜共，波心宿处，琼箫吹月霓裳舞，向明朝、未觉花容悴。嫣香易落，回头澹碧销烟，镜空画罗屏里。 残蝉度曲，唱彻西园，也感红怨翠。念省惯、吴宫幽憩，暗柳追凉，晓岸参斜，露零沤起。丝萦寸藕，留连欢事，桃笙平展湘浪影，有昭华秾李冰相倚。如今鬓点凄霜，半箧秋词，恨盈蠹纸。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2088, "title": "绛都春", "author": "吴文英", "body": "燕亡久矣，京口适见似人，怅怨有感。\n南楼坠燕。又灯晕夜凉，疏帘空卷。叶吹暮喧，花露晨晞秋光短。当时明月娉婷伴。怅客路、幽扃俱远。雾鬟依约，除非照影，镜空不见。 别馆。秋娘乍识，似人处、最在双波凝盼。旧色旧香，闲雨闲云情终浅。丹青谁画真真①面，便只作、梅花频看。更愁花变梨霙，又随梦散。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2089, "title": "惜黄花慢", "author": "吴文英", "body": "次吴江小泊，夜饮僧窗惜别，邦人赵簿携小伎侑尊，连歌数阕，皆清真词。酒尽已四鼓，赋此词饯尹梅津。\n送客吴皋。正试霜夜冷，枫落长桥。望天不尽，背城渐杳；离亭黯黯，恨水迢迢。翠香零落红衣老，暮愁锁、残柳眉梢。念瘦腰，沈郎旧日，曾系兰桡。 仙人凤咽琼箫，怅断魂送远，《九辩》难招。醉鬟留盼，小窗翦烛；歌云载恨，飞上银霄。素秋不解随船去，败红趁、一叶寒涛。梦翠翘。怨鸿料过南谯。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2090, "title": "丑奴儿慢 双清楼", "author": "吴文英", "body": "空濛乍敛，波影帘花晴乱；正西子梳妆楼上，镜舞青鸾。润逼风襟，满湖山色入阑干。天虚鸣籁，云多易雨，长带秋寒。 遥望翠凹，隔江时见，越女低鬟。算堪羡、烟沙白鹭，暮往朝还。歌管重城，醉花春梦半香残。乘风邀月，持杯对影，云海人间。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2091, "title": "木兰花慢", "author": "吴文英", "body": "游虎丘，陪仓幕，时魏益斋已被亲擢，陈芬窟，李方庵皆将满秩\n紫骝嘶冻草，晓云锁，岫眉颦。正蕙雪初消，松腰玉瘦，憔悴真真①。轻藜渐穿险磴，步荒苔、犹认瘗花痕。千古兴亡旧恨，半丘残日孤云。 开尊，重吊吴魂。岚翠冷，洗微醺。问几曾夜宿，月明起看，剑水星纹。登临总成去客，更软红、先有探芳人。回首沧波故苑，落梅烟雨黄昏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2092, "title": "高阳台", "author": "吴文英", "body": "丰乐楼分韵得如字\n修竹凝妆，垂杨驻马，凭阑浅画成图。山色谁题？楼前有雁斜书。东风紧送斜阳下，弄旧寒、晚酒醒馀。自消凝，能几花前，顿老相如。 伤春不在高楼上，在灯前攲枕，雨外熏炉。怕舣游船，临流可奈清臞？飞红若到西湖底，搅翠澜、总是愁鱼。莫重来，吹尽香绵，泪满平芜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2093, "title": "高阳台 落梅", "author": "吴文英", "body": "宫粉雕痕，仙云堕影，无人野水荒湾。古石埋香，金沙锁骨连环。南楼不恨吹横笛，恨晓风、千里关山。半飘零，庭上黄昏，月冷阑干。 寿阳空理愁鸾。问谁调玉髓，暗补香瘢？细雨归鸿，孤山无限春寒。离魂难倩招清些，梦缟衣、解珮①溪边。最愁人，啼鸟晴明，叶底青圆。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2094, "title": "高阳台 过种山", "author": "吴文英", "body": "帆落回潮，人归故国，山椒感慨重游。弓折霜寒，机心已堕沙鸥。灯前宝剑清风断，正五湖、雨笠扁舟。最无情，岩上闲花，腥染春愁。 当时白石苍松路，解勒回玉辇，雾掩山羞。木客歌阑，青春一梦荒丘。年年古苑西风到，雁怨啼、绿水葓秋。莫登临，几树残烟，西北高楼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2095, "title": "三姝媚", "author": "吴文英", "body": "过都城旧居有感\n湖山经醉惯。渍春衫、啼痕酒痕无限。又客长安，叹断襟零袂，涴尘谁浣？紫曲门荒，沿败井、风摇青蔓。对语东邻，犹是曾巢，谢堂双燕。 春梦人间须断。但怪得当年，梦缘能短！绣屋秦筝，傍海棠偏爱，夜深开宴。舞歇歌沉，花未减、红颜先变。伫久河桥欲去，斜阳泪满。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2096, "title": "八声甘州", "author": "吴文英", "body": "渺空烟、四远是何年，青天坠长星？幻、苍厓云树，名娃金屋，残霸宫城。箭径酸风射眼，腻水染花腥。时靸双鸳响，廊叶秋声。 宫里吴王沉醉，倩五湖倦客，独钓醒醒。问苍波无语，华发奈山青。水涵空、阑干高处，送乱鸦斜日落渔汀。连呼酒，上琴台去，秋与云平。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2097, "title": "新雁过妆楼", "author": "吴文英", "body": "梦醒芙蓉。风檐近、浑疑佩玉丁东。翠微流水，都是惜别行踪。宋玉秋花相比瘦，赋情更苦似秋浓。小黄昏，绀①云暮合，不见征鸿。 宜城当时放客②，认燕泥旧迹，返照楼空。夜阑心事，灯外败壁哀蛩③。江寒夜枫怨落，怕流作题情肠断红④。行云远，料淡蛾人在，秋香月中。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2098, "title": "夜合花", "author": "吴文英", "body": "自鹤江入京，泊葑门外有感\n柳暝河桥，莺晴台苑，短策频惹春香。当时夜泊，温柔便入深乡。词韵窄，酒杯长。剪蜡花，壶箭催忙。共追游处，凌波翠陌，连棹横塘。 十年一梦凄凉。似西湖燕去，吴馆巢荒。重来万感，依前唤酒银罂。溪雨急，岸花狂。趁残鸦，飞过苍茫。故人楼上，凭谁指与，芳草斜阳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2099, "title": "点绛唇 越山见梅", "author": "吴文英", "body": "春未来时，酒携不到千岩路。瘦还如许，晚色天寒处。\n无限新愁，难对风前语。行人去，暗消春素，横笛空山暮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2100, "title": "踏莎行", "author": "吴文英", "body": "润玉笼绡，檀樱倚扇。绣圈犹带脂香浅。榴心空叠舞裙红，艾枝应压愁鬟乱。 午梦千山，窗阴一箭。香瘢新褪红丝腕。隔江人在雨声中，晚风菰叶生秋怨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2101, "title": "思佳客", "author": "吴文英", "body": "赋半面女髑髅\n钗燕拢云睡起时。隔墙折得杏花枝。青春半面妆如画，细雨三更花又飞。 轻爱别，旧相知。断肠青冢几斜晖。断红一任风吹起，结习空时不点衣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2102, "title": "望江南", "author": "吴文英", "body": "三月暮，花落更情浓。人去秋千闲挂月，马停杨柳倦嘶风。堤畔画船空。 恹恹醉，尽日小帘栊。宿燕夜归银烛外，流莺声在绿阴中。无处觅残红。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2103, "title": "鹧鸪天 化度寺作", "author": "吴文英", "body": "池上红衣伴倚栏，栖鸦常带夕阳还。殷云度雨疏桐落，明月生凉宝扇闲。 乡梦窄，水天宽。小窗愁黛淡秋山。吴鸿好为传归信，杨柳阊门屋数间。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2104, "title": "唐多令", "author": "吴文英", "body": "何处合成愁？离人心上秋。纵芭蕉不雨也飕飕。都道晚凉天气好；有明月，怕登楼。 年事梦中休，花空烟水流。燕辞归、客尚淹留。垂柳不萦裙带住，谩长是、系行舟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2105, "title": "贺新郎", "author": "吴文英", "body": "陪履斋先生沧浪看梅\n乔木生云气。访中兴、英雄陈迹，暗追前事。战舰东风悭借便，梦断神州故里。旋小筑、吴宫闲地。华表月明归夜鹤，叹当时花竹今如此！枝上露，溅清泪。 遨头小簇行春队。步苍苔、寻幽别坞，问梅开未？重唱梅边新度曲，催发寒梢冻蕊。此心与、东君同意。后不如今今非昔，两无言、相对沧浪水。怀此恨，寄残醉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2106, "title": "思佳客", "author": "吴文英", "body": "迷蝶无踪晓梦沉，寒香深闭小庭心。欲知湖上春多少，但看楼前柳浅深。 愁自遣，酒孤斟。一帘芳景燕同吟。杏花宜带斜阳看，几阵东风晚又阴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2107, "title": "古香慢 赋沧浪看桂", "author": "吴文英", "body": "怨娥坠柳，离佩摇葓，霜讯南圃。漫忆桥扉，倚竹袖寒日暮。还问月中游，梦飞过、金风翠羽。把残云剩水万顷，暗薰冷麝凄苦。 渐浩渺、凌山高处。秋澹无光，残照谁主。露粟侵肌，夜约羽林轻误。翦碎惜秋心，更肠断、珠尘藓路。怕重阳，又催近、满城风雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2108, "title": "南乡子", "author": "潘牥", "body": "题南剑州妓馆\n生怕倚阑干，阁下溪声阁外山。惟有旧时山共水，依然，暮雨朝云去不还。 应是蹑飞鸾，月下时时整佩环。月又渐低霜又下，更阑，折得梅花独自看。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2109, "title": "菩萨蛮 宿水口", "author": "洪瑹", "body": "断虹远饮横江水，万山紫翠斜阳里。系马短亭西，丹枫明酒旗。 浮生常客路，事逐孤鸿去。又是月黄昏，寒灯人闭门。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2110, "title": "浪淘沙 云藏鹅湖山", "author": "章谦亨", "body": "台上凭栏干，犹怯春寒。被谁偷了最高山？将谓六丁移取去，不在人间。 却是晓云闲，特地遮拦。与天一样白漫漫。喜得东风收卷尽，依旧追还。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2111, "title": "祝英台近", "author": "李彭老", "body": "杏花初，梅花过，时节又春半。帘影飞梭，轻阴小庭院。旧时月底秋千，吟香醉玉，曾细听、歌珠一串。 忍重见。描金小字题情，生绡合欢扇。老了刘郎，天远玉箫伴。几番莺外斜阳，阑干倚遍，恨杨柳、遮愁不断。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2112, "title": "四字令", "author": "李彭老", "body": "兰汤晚凉，鸾钗半妆，红巾腻雪初香。擘莲房赌双。 罗纨素珰，冰壶露床，月移花影西厢。数流萤过墙。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2113, "title": "浣溪沙 题草窗词", "author": "李彭老", "body": "玉雪庭心夜色空。移花小槛斗春红。轻衫短帽醉歌重。\n彩扇旧题烟雨外，玉箫新谱燕莺中。阑干到处是春风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2114, "title": "浪淘沙", "author": "李莱老", "body": "宝押绣帘斜，莺燕谁家。银筝初试合琵琶。柳色春罗裁袖小，双戴桃花。 芳草满天涯。流水韶华。晚风杨柳绿交加。闲倚阑干无藉在，数尽归鸦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2115, "title": "贺新郎 多景楼落成", "author": "李演", "body": "笛叫东风起。弄尊前、杨花小扇，燕毛初紫。万点淮峰孤角外，惊下斜阳似绮。又婉娩、一番春意。歌舞相缪愁自猛，卷长波、一洗空人世。闲热我，醉时耳。 绿芜冷叶瓜州市。最怜予、洞箫声尽，阑干独倚。落落东南墙一角，谁护山河万里！问人在、玉关归未？老矣青山灯火客，抚佳期、漫洒新亭泪。歌哽咽，事如水！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2116, "title": "南柯子 丁酉清明", "author": "黄昇", "body": "天上传新火，人间试裌衣。定巢新燕觅香泥。不为绣帘朱户说相思。 侧帽吹飞絮，凭栏送落晖。粉痕销淡锦书稀。怕见山南山北子规啼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2117, "title": "清平乐 宫怨", "author": "黄昇", "body": "珠帘寂寂，愁背银釭泣。记得少年初选入，三十六宫第一。\n当年掌上承恩，而今冷落长门。又是羊车过也，月明花落黄昏。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2118, "title": "鹧鸪天 暮春", "author": "黄昇", "body": "沉水香销梦半醒，斜阳恰照竹间亭。戏临小草书团扇，自拣残花插净瓶。 莺宛转，燕丁宁。晴波不动晚山青。玉人只怨春归去，不道槐云绿满庭。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2119, "title": "南乡子 冬夜", "author": "黄昇", "body": "万籁寂无声，衾铁稜稜近五更。香断灯昏吟未稳，凄清。只有霜华伴月明。 应是夜寒凝，恼得梅花睡不成。我念梅花花念我，关情。起看清冰满玉瓶。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2120, "title": "念奴娇 雪", "author": "陈郁", "body": "没巴没鼻，霎时间、做出漫天漫地。不论高低并上下，平白都教一例。鼓动滕六，招邀巽二，一任张威势。识他不破，只今道是祥瑞。 却恨鹅鸭池边，三更半夜，误了吴元济。东郭先生都不管，关上门儿稳睡。一夜东风，三竿暖日，万事随流水。东皇笑道，山河原是我底。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2121, "title": "瑞鹤仙", "author": "张枢", "body": "卷帘人睡起。放燕子归来，商量春事。风光又能几？减芳菲、都在卖花声里。吟边眼底，被嫩绿、移红换紫。甚等闲、半委东风，半委小溪流水。 还是，苔痕湔雨，竹影留云，待晴犹未。兰舟静舣，西湖上、多少歌吹。粉蝶儿、守定落花不去，湿重寻香两翅。怎知人、一点新愁，寸心万里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2122, "title": "念奴娇 送陈正言", "author": "家铉翁", "body": "南来数骑，问征尘、正是江头风恶。耿耿孤忠磨不尽，唯有老天知得。短棹浮淮，轻毡渡汉，回首觚棱泣。缄书欲上，惊传天外清跸。 路人指示荒台，昔汉家使者，曾留行迹。我节君袍雪样明，俯仰都无愧色。送子先归，慈颜未老，三径有馀乐。逢人问我，为说肝肠如昨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2123, "title": "柳梢青", "author": "罗椅", "body": "萼绿华身，小桃花扇，安石榴裙。子野闻歌，周郎顾曲，曾恼夫君。 悠悠羁旅愁人，似零落、青天断云。何处销魂？初三夜月，第四桥春。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2124, "title": "酹江月 淮城感兴", "author": "张绍文", "body": "举杯呼月，问神京何在？淮山隐隐。抚剑频看勋业事，惟有孤忠挺挺。宫阙腥膻，衣冠沦没，天地凭谁整？一枰棋坏，救时著数宜紧。 虽是幕府文书，玉关烽火，暂送平安信。满地干戈犹未戢，毕竟中原谁定？便欲凌空，飘然直上，拂拭山河影。倚风长啸，夜深霜露凄冷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2125, "title": "点绛唇 送李琴泉", "author": "吴大有", "body": "江上旗亭，送君还是逢君处。酒阑呼渡，云压沙鸥暮。\n漠漠萧萧，香冻梨花雨。添愁绪。断肠柔橹，相逐寒潮去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2126, "title": "沁园春 问杜鹃", "author": "陈人杰", "body": "为问杜鹃，抵死①催归，汝胡②不归？似辽东白鹤，尚寻华表；海中玄鸟③，犹记乌衣④。吴蜀非遥，羽毛自好，合⑤趁东风飞向西。何为者⑥，却身羁荒树，血洒芳枝⑦？ 兴亡常事休悲。算人世荣华都几时？看锦江⑧好在，卧龙已矣⑨；玉山⑩无恙，跃马何之⑪？不解自宽⑫，徒然相劝，我辈行藏⑬君岂知？闽山⑭路，待封侯事了⑮，归去非迟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2127, "title": "沁园春", "author": "陈人杰", "body": "诗不穷人，人道得诗，胜如得官。有山川草木，纵横纸上；虫鱼鸟兽，飞动毫端。水到渠成，风来帆速，廿四中书考不难。惟诗也，是乾坤清气，造物须悭。 金张许史浑闲，未必有功名久后看。算南朝将相，到今几姓；西湖名胜，只说孤山。象笏堆床，蝉冠满座，无此新诗传世间。杜陵老，向年时也自，井冻衣寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2128, "title": "沁园春", "author": "陈人杰", "body": "予弱冠之年，随牒江东漕闱，尝与友人暇日命酒层楼。不惟钟阜、石城之胜班班在目，而平淮如席，亦横陈樽俎间。既而北历淮山，自齐安溯江泛湖，薄游巴陵，又得登岳阳楼，以尽荆州之伟观。孙、刘虎视遗迹依然；山川草木，差强人意。洎回京师，日诣丰乐楼以观西湖。因诵友人“东南妩媚，雌了男儿”之句，叹息者久之。酒酣，大书东壁，以写胸中之勃郁。时嘉熙庚子秋季下浣也。\n记上层楼，与岳阳楼，酾酒赋诗。望长山远水，荆州形胜；夕阳枯木，六代兴衰。扶起仲谋，唤回玄德，笑杀景升豚犬儿。归来也，对西湖叹息，是梦耶非？ 诸君傅粉涂脂，问南北战争都不知。恨孤山霜重，梅凋老叶；平堤雨急，柳泣残丝。玉垒腾烟，珠淮飞浪，万里腥风送鼓鼙。原夫辈，算事今如此，安用毛锥！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2129, "title": "沁园春 丁酉岁感事", "author": "陈人杰", "body": "谁使神州，百年陆沉，青毡未还？怅晨星残月，北州豪杰；西风斜日，东帝江山。刘表坐谈，深源轻进，机会失之弹指间。伤心事，是年年冰合，在在风寒。 说和说战都难，算未必江沱堪宴会。叹封侯心在，鳣鲸失水；平戎策就，虎豹当关。渠自无谋，事犹可做，更剔残灯抽剑看。麒麟阁，岂中兴人物，不画儒冠？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2130, "title": "沁园春", "author": "陈人杰", "body": "次韵林南金赋愁\n抚剑悲歌，纵有杜康，可能解忧？为修名不立，此身易老；古心自许，与世多尤。平子诗中，庾生赋里，满目江山无限愁。关情处，是闻鸡半夜，击楫中流。 淡烟衰草连秋，听鸣鴂声声相应酬。叹霸才重耳，泥涂在楚；雄心玄德，岁月依刘。梦落莼边，神游菊外，已分他年专一丘。长安道，且身如王粲，时复登楼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2131, "title": "齐天乐 泽国楼偶赋", "author": "陈允平", "body": "湖光只在阑干外，凭虚远迷三楚。旧柳犹青，平芜自碧，几度朝昏烟雨。天涯倦旅。爱小却游鞭，共挥谈麈。顿觉尘清，宦情高下等风絮。 芝山苍翠缥缈，黯然仙梦杳，吟思飞去。故国楼台，斜阳巷陌，回首白云何处？无心访古。对双塔栖鸦，半汀归鹭。立尽荷香，月明人笑语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2132, "title": "清平乐", "author": "陈允平", "body": "凤城春浅，寒压花梢颤。有约不来梁上燕，十二绣帘空卷。\n去年共倚秋千，今年独上阑干。误了海棠时候，不成直待花残。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2133, "title": "唐多令 秋暮有感", "author": "陈允平", "body": "休去采芙蓉。秋江烟水空。带斜阳、一片征鸿。欲顿闲愁无顿处，都著在两眉峰。 心事寄题红。画桥流水东。断肠人、无奈秋浓。回首层楼归去懒，早新月、挂梧桐。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2134, "title": "贺新凉 游西湖有感", "author": "文及翁", "body": "一勺西湖水。渡江来、百年歌舞，百年酣醉。回首洛阳花石尽，烟渺黍离之地①，更不复、新亭堕泪②。簇乐红妆摇画舫，问中流击楫③谁人是？千古恨，几时洗？ 余生自负澄清志。更有谁、磻溪未遇④，傅岩未起⑤？国事如今谁倚仗？衣带一江而已。便都道、江神堪恃。借问孤山林处士，但掉头、笑指梅花蕊。天下事，可知矣！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2135, "title": "沁园春", "author": "谢枋得", "body": "寒食郓州道中\n十五年来，逢寒食节，皆在天涯。叹雨濡露润，还思宰柏；风柔日媚，羞见飞花。麦饭纸钱，只鸡斗酒，几误林间噪喜鸦。天笑道：此不由乎我，也不由他。 鼎中炼熟丹砂。把紫府清都作一家。想前人鹤驭，常游绛阙；浮生蝉蜕，岂恋黄沙？帝命守坟，王令修墓，男子正当如是耶。又何必，待过家上冢，昼锦荣华！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2136, "title": "贺新郎 萤", "author": "赵闻礼", "body": "池馆收新雨。耿幽丛、流光几点，半侵疏户。入夜凉风吹不灭，冷焰微茫暗度。碎影落、仙盘秋露。漏断长门空照泪，袖纱寒、映竹无心顾。孤枕掩，残灯炷。 练囊不照诗人苦。夜沉沉、拍手相亲，騃儿痴女。栏外扑来罗扇小，谁在风廊笑语。竞戏踏、金钗双股。故苑荒凉悲旧赏，怅寒芜衰草隋宫路。同燐火，遍秋圃。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2137, "title": "玲珑四犯 被召赋荼䕷①", "author": "曹邍", "body": "一架②幽芳，自过了梅花，独占清绝③。露叶檀心④，香满万条晴雪。肌素净洗铅华，似弄玉、乍离瑶阙。看翠蛟白凤飞舞，不管暮烟啼鴂⑤。 酒中风格天然别。记唐宫、赐樽芳冽。玉蕤⑥唤得馀春住，犹醉迷飞蝶。天气乍雨乍晴，长是伴、牡丹时节。夜散琼楼宴，金铺⑦深掩，一庭香月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2138, "title": "汉宫春", "author": "赵汝茪", "body": "着破荷衣，笑西风吹我，又落西湖。湖间旧时饮者，今与谁俱？山山映带，似携来、画卷重舒。三十里、芙蓉步障，依然红翠相扶。 一目清无留处，任屋浮天上，身集空虚。残烧夕阳过雁，点点疏疏。故人老大，好襟怀、消减全无。慢赢得、秋声两耳，冷泉亭①下骑驴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2139, "title": "菩萨蛮 商妇怨", "author": "江开", "body": "春时江上廉纤雨，张帆打鼓开船去。秋晚恰归来，看看船又开。 嫁郎如未嫁，长是凄凉夜。情少利心多，郎如年少何！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2140, "title": "谒金门", "author": "李好古", "body": "花过雨，又是一番红素。燕子归来愁不语，旧巢无觅处。\n谁在玉关劳苦？谁在玉楼歌舞？若使胡尘吹得去，东风侯万户。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2141, "title": "忆秦娥", "author": "刘辰翁", "body": "中斋上元客散感旧，赋《忆秦娥》见属，一读凄然。随韵寄情，不觉悲甚。\n烧灯节，朝京道上风和雪。风和雪，江山如旧，朝京人绝。\n百年短短兴亡别，与君犹对当时月。当时月，照人烛泪，照人梅髮。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2142, "title": "西江月 新秋写兴", "author": "刘辰翁", "body": "天上低昂似旧，人间儿女成狂。夜来处处试新妆，却是人间天上。 不觉新凉似水，相思两鬓如霜。梦从海底跨枯桑，阅尽银河风浪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2143, "title": "浣溪沙 春日即事", "author": "刘辰翁", "body": "远远游蜂不记家，数行新柳自啼鸦，寻思旧事即天涯。\n睡起有情和画卷，燕归无语傍人斜，晚风吹落小瓶花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2144, "title": "浣溪沙 感别", "author": "刘辰翁", "body": "点点疏林欲雪天，竹篱斜闭自清妍，为伊憔悴得人怜。\n欲与那人携素手，粉香和泪落君前，相逢恨恨总无言。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2145, "title": "山花子", "author": "刘辰翁", "body": "此处情怀欲问天，相期相就复何年。行过章江三十里，泪依然。 早宿半程芳草路，犹寒欲雨暮春天。小小桃花三两处，得人怜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2146, "title": "柳梢青 春感", "author": "刘辰翁", "body": "铁马蒙毡，银花洒泪，春入愁城。笛里番腔，街头戏鼓，不是歌声。 那堪独坐青灯，想故国、高台月明。辇下风光，山中岁月，海上心情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2147, "title": "鹊桥仙 自寿二首", "author": "刘辰翁", "body": "轻风澹月，年年去路。谁识小年初度。桥边曾弄碧莲花，悄不记、人间今古。 吹箫江上，沾衣微露。依约凌波曾步。寒机何意待人归，但寂历、小窗斜雨。\n天香吹下，烟霏成路。飒飒神光暗度。桥边犹记泛槎人，看赤岸、苔痕如古。 长空皓月，小风斜露。寂寞江头独步。人间何处得飘然，归梦入、梨花春雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2148, "title": "踏莎行 雨中观海棠", "author": "刘辰翁", "body": "命薄佳人，情钟我辈。海棠开后心如碎。斜风细雨不曾晴，倚阑滴尽胭脂泪。 恨不能开，开时又背。春寒只了房栊闭。待他晴后得君来，无言掩帐羞憔悴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2149, "title": "兰陵王 丙子送春", "author": "刘辰翁", "body": "送春去，春去人间无路。秋千外、芳草连天，谁遣风沙暗南浦？依依甚意绪？漫忆海门飞絮。乱鸦过，斗转城荒，不见来时试灯处。 春去，最谁苦？但箭雁沉边，梁燕无主，杜鹃声里长门暮。想玉树凋土，泪盘如露。咸阳送客屡回顾，斜日未能度。 春去，尚来否？正江令恨别，庾信愁赋。（二人皆北去）苏堤尽日风和雨。叹神游故国，花记前度。人生流落，顾孺子，共夜语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2150, "title": "宝鼎现 春月", "author": "刘辰翁", "body": "红妆春骑，踏月影、竿旗穿市。望不尽楼台歌舞，习习香尘莲步底。箫声断，约彩鸾归去，未怕金吾呵醉。甚辇路喧阗且止，听得念奴歌起。 父老犹记宣和事，抱铜仙、清泪如水。还转盼沙河多丽。滉漾明光连邸第，帘影动、散红光成绮。月浸葡萄十里。看往来神仙才子，肯把菱花扑碎？ 肠断竹马儿童，空见说、三千乐指。等多时、春不归来，到春时欲睡。又说向灯前拥髻，暗滴鲛珠坠。便当日亲见《霓裳》，天上人间梦里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2151, "title": "永遇乐", "author": "刘辰翁", "body": "余自乙亥上元诵李易安《永遇乐》，为之涕下。今三年矣，每闻此词，辄不自堪。遂依其声，又托之易安自喻。虽辞情不及，而悲苦过之。\n璧月初晴，黛云远淡，春事谁主？禁苑娇寒，湖堤倦暖，前度遽如许！香尘暗陌，华灯明昼，长是懒携手去。谁知道，断烟禁夜，满城似愁风雨！ 宣和旧日，临安南渡，芳景犹自如故。缃帙流离，风鬟三五，能赋词最苦。江南无路，鄜州今夜，此苦又谁知否？空相对，残釭无寐，满村社鼓。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2152, "title": "虞美人", "author": "刘辰翁", "body": "用李后主韵二首\n梅梢腊尽春归了。毕竟春寒少。乱山残烛雪和风。犹胜阴山海上窖群中。 年光老去才情在。唯有华风改。醉中幸自不曾愁。谁唱春花秋叶泪偷流。\n情知是梦无凭了。好梦依然少。单于吹尽五更风。谁见梅花如泪不言中。 儿童问我今何在。烟雨楼台改。江山画出古今愁。人与落花何处水空流。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2153, "title": "六州歌头", "author": "刘辰翁", "body": "乙亥二月，贾平章似道督师至太平州鲁港，未见敌，鸣锣而溃。后半月闻报，赋此。\n向来人道，真个胜周公。燕然眇，浯溪小，万世功，再建隆。十五年宇宙，宫中赝，堂中伴，翻虎鼠，搏鹯雀，覆蛇龙。鹤发庞眉，憔悴空山久，来上东封。便一朝符瑞，四十万人同。说甚东风，怕西风。 甚边尘起，渔阳惨，霓裳断，广寒宫。青楼杳，朱门悄，镜湖空，里湖通。大纛高牙去，人不见，港重重。斜阳外，芳草碧，落花红。抛尽黄金无计，方知道、前此和戎。但千年传说，夜半一声铜。何面江东。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2154, "title": "沁园春 送春", "author": "刘辰翁", "body": "春，汝归欤？风雨蔽江，烟尘暗天。况雁门阨塞①，龙沙②渺莽，东连吴会③，西至秦川④。芳草迷津，飞花拥道，小为蓬壶借百年。江南好，问夫君何事，不少留连？ 江南正是堪怜！但满眼杨花化白毡。看兔葵燕麦，华清宫里；蜂黄蝶粉，凝碧池边。我已无家，君归何里？中路徘徊七宝鞭。风回处，寄一声珍重，两地潸然！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2155, "title": "金缕曲 闻杜鹃", "author": "刘辰翁", "body": "少日都门路。听长亭、青山落日，不如归去。十八年间来往断，白首人间今古。又惊绝、五更一句。道是流离蜀天子，甚当初、一似吴儿语。臣再拜，泪如雨。 画堂客馆真无数。记画桥、黄竹歌声，桃花前度。风雨断魂苏季子，春梦家山何处？谁不愿、封侯万户？寂寞江南轮四角，问长安、道上无人住。啼尽血，向谁诉？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2156, "title": "摸鱼儿", "author": "刘辰翁", "body": "酒边留同年徐云屋\n怎知他、春归何处，相逢且尽尊酒。少年嫋嫋天涯恨，长结西湖烟柳。休回首。但细雨断桥，憔悴人归后。东风似旧。问前度桃花，刘郎能记，花复认郎否？ 君且住，草草留君剪韭。前宵正恁时候。深杯欲共歌声滑，翻湿春衫半袖。空眉皱。看白发尊前，已似人人有。临分把手。叹一笑论文，清狂顾曲，此会几时又。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2157, "title": "柳梢青 灯花", "author": "张林", "body": "白玉枝头，忽看蓓蕾，金粟珠垂。半颗安榴，一枝秾杏，五色蔷薇。 何须羯鼓声催。银釭里、春工四时。却笑灯蛾，学他蝴蝶，照影频飞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2158, "title": "市桥柳 送行", "author": "蜀中妓", "body": "欲寄意、浑无所有。折尽市桥官柳。看君著上征衫，又相将放船楚江口。 后会不知何日又。是男儿，休要镇长相守。苟富贵、无相忘，若相忘，有如此酒！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2159, "title": "木兰花慢 断桥残雪", "author": "周密", "body": "觅梅花信息，拥吟袖，暮鞭寒。自放鹤人归，月香水影，诗冷孤山。等闲。泮寒晛暖，看融城、御水到人间。瓦陇竹根更好，柳边小驻游鞍。 琅玕。半倚云湾。孤棹晚，载诗还。是醉魂醒处，画桥第二，奁月初三。东阑。有人步玉，怪冰泥、沁湿锦鹓斑。还见晴波涨绿，谢池梦草相关。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2160, "title": "瑶花慢", "author": "周密", "body": "后土之花，天下无二本。方其初开，帅臣以金瓶飞骑进之天上，间亦分致贵邸。余客辇下，有以一枝……①\n朱钿宝玦，天上飞琼，比人间春别。江南江北曾未见，谩拟梨云梅雪。淮山春晚，问谁识、芳心高洁？消几番、花落花开，老了玉关豪杰！ 金壶翦送琼枝，看一骑红尘，香度瑶阙。韶华正好，应自喜、初识长安蜂蝶。杜郎老矣，想旧事、花须能说。记少年，一梦扬州，二十四桥明月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2161, "title": "玉京秋", "author": "周密", "body": "长安独客，又见西风，素月丹枫，凄然其为秋也。因调夹钟羽一解。\n烟水阔。高林弄残照，晚蜩凄切①。碧砧度韵，银床飘叶。衣湿桐阴露冷，采凉花，时赋秋雪。叹轻别，一襟幽事，砌蛩能说。 客思吟商还怯。怨歌长、琼壶暗缺。翠扇恩疏，红衣香褪，翻成消歇。玉骨西风，恨最恨、闲却新凉时节。楚箫咽，谁倚②西楼淡月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2162, "title": "曲游春", "author": "周密", "body": "禁烟湖上薄游，施中山赋词甚佳，余因次其韵。盖平时游舫，至午后则尽入里湖，抵暮始出，断桥小驻而归，非习于游者不知也。故中山极击节余“闲却半湖春色”之句，谓能道人之所未云。\n禁苑东风外，飏暖丝晴絮，春思如织。燕约莺期，恼芳情、偏在翠深红隙。漠漠香尘隔。沸十里乱弦丛笛。看画船尽入西泠，闲却半湖春色。 柳陌。新烟凝碧。映帘底宫眉，堤上游勒。轻暝笼寒，怕梨云梦冷，杏香愁幂。歌管酬寒食。奈蝶怨良宵岑寂。正满湖碎月摇花，怎生去得！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2163, "title": "齐天乐", "author": "周密", "body": "丁卯七月既望，余偕同志放舟邀凉于三汇之交，远修太白采石、坡仙赤壁数百年故事，游兴甚逸。余尝赋诗三百言以纪清适。坐客和篇交属，意殊快也。越明年秋，复寻前盟于白荷凉月间。风露浩然，毛发森爽，遂命苍头奴横小笛于舵尾，作悠扬杳渺之声，使人真有乘查飞举想也。举白尽醉，继以浩歌。\n清溪数点芙蓉雨，蘋飙泛凉吟艗。洗玉空明，浮珠沆瀣，人静籁沉波息。仙潢咫尺。想翠宇琼楼，有人相忆。天上人间，未知今夕是何夕。 此生此夜此景，自仙翁去后，清致谁识？散发吟商，簪花弄水，谁伴凉宵横笛？流年暗惜。怕一夕西风，井梧吹碧。底事闲愁，醉歌浮大白。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2164, "title": "清平乐 再次前韵", "author": "周密", "body": "晚莺娇咽，庭户溶溶月。一树桃花飞茜雪，红豆相思暗结。\n看看芳草平沙，游鞯犹未归家。自是萧郎飘荡，错教人恨杨花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2165, "title": "乳燕飞", "author": "周密", "body": "辛未首夏，以书舫载客游苏湾，徙倚危亭，极登览之趣。所谓浮玉山、碧浪湖者，皆横陈于前，特吾几席中一物耳。遥望具区，渺如烟云，洞庭、缥缈诸峰，矗矗献状，盖王右丞、李将军著色画也。松风怒号，暝色四起，使人浩然忘归。慨然怀古，高歌举白，不知身世为何如也。溪山不老，临赏无穷，后之视今，当有契余言者。因大书山楹，以纪来游。\n波影摇涟甃。趁熏风、一舸来时，翠阴清昼。去郭轩楹才数里，藓磴松关云岫。快屐齿筇枝先后。空半危亭堪聚远，看洞庭缥缈争奇秀。人自老，景如旧。 来帆去棹还知否。问古今、几度斜阳，几番回首？晚色一川谁管领，都付雨荷烟柳。知我者、燕朋鸥友。笑拍阑干呼范蠡，甚平吴、却倩垂纶手？吁万古，付卮酒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2166, "title": "闻鹊喜 吴山观涛", "author": "周密", "body": "天水碧，染就一江秋色。鳌戴雪山龙起蛰，快风吹海立。\n数点烟鬟青滴，一杼霞绡红湿，白鸟明边帆影直，隔江闻夜笛。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2167, "title": "疏影 梅影", "author": "周密", "body": "冰条冻叶，又横斜照水，一花初发。素壁秋屏，招得芳魂，仿佛玉容明灭。疏疏满地珊瑚冷，全误却、扑花幽蝶。甚美人、忽到窗前，镜里好春难折。 闲想孤山旧事，浸清漪、倒映千树残雪。暗里东风，可惯无情，搅碎一帘香月。轻妆谁写崔徽面，认隐约、烟绡重叠。记梦回，纸帐残灯，瘦倚数枝清绝。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2168, "title": "齐天乐 蝉", "author": "周密", "body": "槐薰忽送清商怨，依稀正闻还歇。故苑愁深，危弦调苦，前梦蜕痕枯叶。伤情念别。是几度斜阳，几回残月。转眼西风，一襟幽恨向谁说。 轻鬟犹记动影，翠蛾应妒我，双鬓如雪。枝冷频移，叶疏犹抱，孤负好秋时节。凄凄切切。渐迤逦黄昏，砌蛩相接。露洗馀悲，暮烟声更咽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2169, "title": "玉漏迟", "author": "周密", "body": "题吴梦窗《霜花腴词集》\n老来欢意少。锦鲸仙去，紫箫①声杳。怕展金奁，依旧故人怀抱。犹想乌丝醉墨，惊俊语、香红围绕。闲自笑。与君共是、承平年少。 雨窗短梦难凭，是几番宫商，几番吟啸？泪眼东风，回首四桥烟草。载酒倦游甚处？已换却、花间啼鸟。春恨悄。天涯暮云残照。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2170, "title": "一萼红", "author": "周密", "body": "登蓬莱阁①有感\n步深幽。正云黄天淡，雪意未全休。鉴曲寒沙，茂林烟草，俯仰千古悠悠。岁华晚、飘零渐远，谁念我、同载五湖舟？磴古松斜，厓阴苔老，一片清愁。 回首天涯归梦，几魂飞西浦，泪洒东州。故国山川，故园心眼，还似王粲登楼。最负他、秦鬟妆镜，好江山、何事此时游！为唤狂吟老监，共赋消忧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2171, "title": "扫花游 九日怀归", "author": "周密", "body": "江蓠怨碧，早过了霜花，锦空洲渚。孤蛩暗语。正长安乱叶，万家砧杵。尘染秋衣，谁念西风倦旅。恨无据。怅望极归舟，天际烟树。 心事曾细数。怕水叶沉红，梦云离去。情丝恨缕。倩回纹为织，那时愁句。雁字无多，写得相思几许。暗凝伫。近重阳、满城风雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2172, "title": "献仙音 吊雪香亭梅", "author": "周密", "body": "松雪飘寒，岭云吹冻，红破数椒春浅。衬舞台荒，浣妆池冷，凄凉市朝轻换。叹花与人凋谢，依依岁华晚。 共悽黯。问东风、几番吹梦？应惯识当年，翠屏金辇。一片古今愁，但废绿平烟空远。无语消魂，对斜阳衰草泪满。又西泠残笛，低送数声春怨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2173, "title": "高阳台", "author": "周密", "body": "送陈君衡被召\n照野旌旗，朝天车马，平沙万里天低。宝带金章，尊前茸帽风欹。秦关汴水经行地，想登临、都付新诗。纵英游，叠鼓清笳，骏马名姬。 酒酣应对燕山雪，正冰河月冻，晓陇云飞。投老残年，江南谁念方回。东风渐绿西湖岸，雁已还、人未南归。最关情，折尽梅花，难寄相思。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2174, "title": "高阳台 寄越中诸友", "author": "周密", "body": "小雨分江，残寒迷浦，春容浅入蒹葭。雪霁空城，燕归何处人家？梦魂欲渡苍茫去，怕梦轻、还被愁遮。感流年，夜汐东还，冷照西斜。 萋萋望极王孙草，认云中烟树，鸥外春沙。白发青山，可怜相对苍华。归鸿自趁潮回去，笑倦游、犹是天涯。问东风，先到垂杨，后到梅花？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2175, "title": "花犯 赋水仙", "author": "周密", "body": "楚江湄，湘娥乍见，无言洒清泪。淡然春意。空独倚东风，芳思谁寄。凌波路冷秋无际，香云随步起。谩记得、汉宫仙掌，亭亭明月底。 冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。春思远，谁叹赏、国香风味。相将共、岁寒伴侣，小窗净、沈烟熏翠袂。幽梦觉，涓涓清露，一枝灯影里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2176, "title": "摸鱼儿", "author": "朱嗣发", "body": "对西风、鬓摇烟碧，参差前事流水。紫丝罗带鸳鸯结，的的镜盟钗誓。浑不记、漫手织回文，几度欲心碎。安花著蒂。奈雨覆云翻，情宽分窄，石上玉簪脆。 朱楼外，愁压空云欲坠。月痕犹照无寐。阴晴也只随天意，枉了玉消香碎。君且醉。君不见、长门青草春风泪。一时左计。悔不早荆钗，暮天修竹，头白倚寒翠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2177, "title": "酹江月 和", "author": "文天祥", "body": "乾坤能大，算蛟龙、元不是池中物。风雨牢愁无着处，那更寒虫四壁。横槊题诗，登楼作赋，万事空中雪。江流如此，方来还有英杰。 堪笑一叶漂零，重来淮水，正凉风新发。镜里朱颜都变尽，只有丹心难灭。去去龙沙，江山回首，一线青如发。故人应念，杜鹃枝上残月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2178, "title": "满江红", "author": "文天祥", "body": "和王夫人《满江红》韵，以庶几后山《妾薄命》之意。\n燕子楼中，又捱过、几番秋色。相思处、青年如梦，乘鸾仙阙。肌玉暗消衣带缓，泪珠斜透花钿侧。最无端蕉影上窗纱，青灯歇。 曲池合，高台灭。人间事，何堪说！向南阳阡上，满襟清血。世态便如翻覆雨，妾身元是分明月。笑乐昌一段好风流，菱花缺。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2179, "title": "满江红 代王夫人作", "author": "文天祥", "body": "试问琵琶，胡沙外、怎生风色。最苦是、姚黄一朵，移根仙阙。王母欢阑琼宴罢，仙人泪满金盘侧。听行宫、半夜雨淋铃，声声歇。 彩云散，香尘灭。铜驼恨，那堪说。想男儿慷慨，嚼穿龈血。回首昭阳离落日，伤心铜雀迎秋月。算妾身、不愿似天家，金瓯缺。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2180, "title": "沁园春", "author": "文天祥", "body": "题潮阳张许二公庙\n为子死孝，为臣死忠，死又何妨。自光岳气分，士无全节；君臣义缺，谁负刚肠。骂贼张巡，爱君许远，留取声名万古香。后来者，无二公之操，百炼之钢。 人生翕歘云亡。好烈烈轰轰做一场。使当时卖国，甘心降虏，受人唾骂，安得流芳。古庙幽沉，仪容俨雅，枯木寒鸦几夕阳。邮亭下，有奸雄过此，仔细思量。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2181, "title": "酹江月 驿中言别", "author": "邓剡", "body": "水天空阔，恨东风不惜世间英物。蜀鸟吴花残照里，忍见荒城颓壁。铜雀春情，金人秋泪，此恨凭谁雪？堂堂剑气，斗牛空认奇杰。 那信江海余生，南行万里，属扁舟齐发。正为鸥盟留醉眼，细看涛生云灭。睨柱吞嬴，回旗走懿，千古冲冠发。伴人无寐，秦淮应是孤月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2182, "title": "浪淘沙", "author": "邓剡", "body": "疏雨洗天清。枕簟凉生。井桐一叶做秋声。谁念客身轻似叶，千里飘零？ 梦断古台城。月淡潮平。便须携酒访新亭。不见当时王谢宅，烟草青青。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2183, "title": "唐多令", "author": "邓剡", "body": "雨过水明霞，潮回岸带沙。叶声寒，飞透窗纱。堪恨西风吹世换，更吹我，落天涯。 寂寞古豪华，乌衣日又斜。说兴亡，燕入谁家？惟有南来无数雁，和明月，宿芦花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2184, "title": "一剪梅", "author": "杨佥判", "body": "襄樊四载弄干戈，不见渔歌，不见樵歌。试问如今事若何？金也消磨，谷也消磨。 《柘枝》①不用舞婆娑，丑也能②多，恶也能多！朱门日日买朱娥。军事如何？民事如何？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2185, "title": "传言玉女 钱塘元夕", "author": "汪元量", "body": "一片风流，今夕与谁同乐？月台花馆，慨尘埃漠漠。豪华荡尽，只有青山如洛。钱塘依旧，潮生潮落。 万点灯光，羞照舞钿歌箔。玉梅消瘦，恨东皇命薄。昭君泪流，手撚琵琶弦索。离愁聊寄，画楼哀角。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2186, "title": "洞仙歌", "author": "汪元量", "body": "毗陵赵府，兵后僧多占作佛屋。\n西园春暮。乱草迷行路。风卷残花堕红雨。念旧巢燕子，飞傍谁家，斜阳外，长笛一声今古。 繁华流水去，舞歇歌沉，忍见遗钿种香土。渐橘树方生，桑枝才长，都付与、沙门为主。便关防不放贵游来，又突兀梯空，梵王宫宇。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2187, "title": "莺啼序 重过金陵", "author": "汪元量", "body": "金陵故都最好，有朱楼迢递。嗟倦客、又此凭高，槛外已少佳致。更落尽梨花，飞尽杨花，春也成憔悴。问青山，三国英雄，六朝奇伟？ 麦甸葵丘，荒台败垒，鹿豕衔枯荠。正潮打孤城，寂寞斜阳影里。听楼头、哀笳怨角，未把酒、愁心先醉。渐夜深，月满秦淮，烟笼寒水。 凄凄惨惨，冷冷清清，灯火渡头市。慨商女不知兴废，隔江犹唱庭花，余音亹亹。伤心千古，泪痕如洗。乌衣巷口青芜路，认依稀、王谢旧邻里。临春结绮，可怜红粉成灰，萧索白杨风起。 因思畴昔，铁索千寻，漫沉江底。挥羽扇、障西尘，便好角巾私第。清谈到底成何事？回首新亭，风景今如此。楚囚对泣何时已。叹人间、今古真儿戏！东风岁岁还来，吹入钟山，几重苍翠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2188, "title": "水龙吟", "author": "汪元量", "body": "淮河舟中夜闻宫人琴声\n鼓鼙惊破霓裳，海棠亭北多风雨。歌阑酒罢，玉啼金泣，此行良苦。驼背模糊，马头匼匝①，朝朝暮暮。自都门宴别，龙艘锦缆，空载得、春归去。 目断东南半壁，怅长淮、已非吾土。受降城下，草如霜白，凄凉酸楚。粉阵红围，夜深人静，谁宾谁主？对渔灯一点，羁愁一搦②，谱琴中语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2189, "title": "满江红 和王昭仪韵", "author": "汪元量", "body": "天上人家，醉王母、蟠桃春色。被午夜、漏声催箭，晓光侵阙。花覆千官鸾阁外，香浮九鼎龙楼侧。恨黑风吹雨湿霓裳，歌声歇。 人去后，书应绝。肠断处，心难说。更那堪杜宇，满山啼血。事去空流东汴水，愁来不见西湖月。有谁知、海上泣婵娟，菱花缺。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2190, "title": "满江红", "author": "王清惠", "body": "太液芙蓉，浑不似、旧时颜色。曾记得，春风雨露，玉楼金阙。名播兰馨妃后里，晕潮莲脸君王侧。忽一声鼙鼓揭天来，繁华歇。 龙虎散，风云灭。千古恨，凭谁说？对山河百二，泪盈襟血。驿馆夜惊尘土梦，宫车晓辗关山月。问姮娥、于我肯从容，同圆缺。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2191, "title": "长相思", "author": "袁正真", "body": "南高峰，北高峰，南北高峰云淡浓。湖山图画中。\n采芙蓉，赏芙蓉，小小红船西复东。相思无路通。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2192, "title": "望江南", "author": "金德淑", "body": "春睡起，积雪满燕山。万里长城横缟带，六街灯火已阑珊。人立玉楼间。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2193, "title": "齐天乐", "author": "詹玉", "body": "送童瓮天兵后归杭\n相逢唤醒京华梦，吴尘暗斑吟发。倚担评花，认旗沽酒，历历行歌奇迹。吹香弄碧。有坡柳风情，逋梅月色。画鼓红船，满湖春水断桥客。 当时何限俊侣，甚花天月地，人被云隔。却载苍烟，更招白鹭，一醉修江又别。今回记得。再折柳穿鱼，赏梅催雪。如此湖山，忍教人更说！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2194, "title": "天香 咏龙涎香", "author": "王沂孙", "body": "孤峤蟠烟，层涛蜕月，骊宫夜采铅水。汛远槎风，梦深薇露，化作断魂心字。红甆候火，还乍识、冰环玉指。一缕萦帘翠影，依稀海天云气。 几回殢娇半醉。剪春灯、夜寒花碎。更好故溪飞雪、小窗深闭。荀令如今顿老，总忘却、樽前旧风味。谩惜余熏，空篝素被。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2195, "title": "花犯 苔梅", "author": "王沂孙", "body": "古婵娟，苍鬟素靥，盈盈瞰流水。断魂十里。叹绀缕飘零，难系离思。故山岁晚谁堪寄。琅玕聊自倚。谩记我、绿蓑冲雪，孤舟寒浪里。 三花两蕊破蒙茸，依依似有恨，明珠轻委。云卧稳，蓝衣正、护春憔悴。罗浮梦、半蟾挂晓，幺凤冷、山中人乍起。又唤取、玉奴归去，余香空翠被。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2196, "title": "南浦 春水", "author": "王沂孙", "body": "柳下碧粼粼，认麹尘乍生，色嫩如染。清溜满银塘，东风细，参差縠纹初遍。别君南浦，翠眉曾照波痕浅。再来涨绿迷旧处，添却残红几片。 葡萄过雨新痕，正拍拍轻鸥，翩翩小燕。帘影蘸楼阴，芳流去，应有泪珠千点。沧浪一舸，断魂重唱蘋花怨。采香幽泾鸳鸯睡，谁道湔裙人远。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2197, "title": "眉妩 新月", "author": "王沂孙", "body": "渐新痕悬柳，淡彩穿花，依约破初暝。便有团圆意，深深拜，相逢谁在香径。画眉未稳。料素娥、犹带离恨。最堪爱、一曲银钩小，宝帘挂秋冷。 千古盈亏休问。叹慢磨玉斧①，难补金镜。太液池犹在，凄凉处、何人重赋清景。故山夜永。试待他、窥户端正。看云外山河，还老尽、桂花影。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2198, "title": "水龙吟 落叶", "author": "王沂孙", "body": "晓霜初著青林，望中故国凄凉早。萧萧渐积，纷纷犹坠，门荒径悄。渭水风生，洞庭波起，几番秋杪。想重厓半没，千峰尽出，山中路，无人到。 前度题红杳杳，溯宫沟、暗流空绕。啼螀未歇，飞鸿欲过，此时怀抱。乱影翻窗，碎声敲砌，愁人多少！望吾庐甚处？只应今夜，满庭谁扫？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2199, "title": "绮罗香 红叶", "author": "王沂孙", "body": "玉杵馀丹，金刀剩彩，重染吴江孤树。几点朱铅，几度怨啼秋暮。惊旧梦、绿鬓轻凋，诉新恨、绛唇微注。最堪怜，同拂新霜，绣蓉一镜晚妆妒。 千林摇落渐少，何事西风老色，争妍如许。二月残花，空误小车山路。重认取、流水荒沟，怕犹有、寄情芳语。但凄凉、秋苑斜阳，冷枝留醉舞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2200, "title": "齐天乐 萤", "author": "王沂孙", "body": "碧痕初化池塘草，荧荧野光相趁。扇薄星流，盘明露滴，零落秋原飞燐。练裳暗近。记穿柳生凉，度荷分暝。误我残编，翠囊空叹梦无准。 楼阴时过数点，倚阑人未睡，曾赋幽恨。汉苑飘苔，秦陵坠叶，千古凄凉不尽。何人为省？但隔水余晖，傍林残影。已觉萧疏，更堪秋夜永！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2201, "title": "齐天乐 蝉", "author": "王沂孙", "body": "绿槐千树西窗悄，厌厌昼眠惊起。饮露身轻，吟风翅薄，半剪冰笺谁寄。凄凉倦耳。漫重拂琴丝，怕寻冠珥。短梦深宫，向人犹自诉憔悴。 残虹收尽过雨，晚来频断续，都是秋意。病叶难留，纤柯易老，空忆斜阳身世。窗明月碎。甚已绝馀音，尚遗枯蜕。鬓影参差，断魂青镜里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2202, "title": "齐天乐 蝉", "author": "王沂孙", "body": "一襟馀恨宫魂断，年年翠阴庭树。乍咽凉柯，还移暗叶，重把离愁深诉。西窗过雨。怪瑶珮流空，玉筝调柱。镜暗妆残，为谁娇鬓尚如许。 铜仙铅泪似洗，叹携盘去远，难贮零露。病翼惊秋，枯形阅世，消得斜阳几度？馀音更苦。甚独抱清高，顿成凄楚？谩想熏风，柳丝千万缕。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2203, "title": "庆清朝 榴花", "author": "王沂孙", "body": "玉局歌残，金陵句绝，年年负却熏风。西邻窈窕，独怜入户飞红。前度绿阴载酒，枝头色比舞裙同。何须拟，蜡珠作蒂，缃彩成丛。 谁在旧家殿阁？自太真仙去，扫地春空。朱幡护取，如今应误花工。颠倒绛英满径，想无车马到山中。西风后，尚余数点，犹胜春浓。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2204, "title": "庆春宫① 水仙花", "author": "王沂孙", "body": "明玉擎金，纤罗飘带，为君起舞回雪。柔影参差，幽芳零乱，翠围腰瘦一捻。岁华相误，记前度湘皋怨别。哀弦重听，都是凄凉，未须弹彻。 国香到此谁怜？烟冷沙昏，顿成愁绝。花恼难禁，酒销欲尽，门外冰澌初结。试招仙魄，怕今夜瑶簪冻折。携盘独出，空想咸阳，故宫落月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2205, "title": "高阳台", "author": "王沂孙", "body": "残萼梅酸，新沟水绿，初晴节序暄妍。独立雕阑，谁怜枉度华年。朝朝准拟清明近，料燕翎、须寄银笺。又争知、一字相思，不到吟边。 双蛾不拂青鸾冷，任花阴寂寂，掩户闲眠。屡卜佳期，无凭却恨金钱。何人寄与天涯信，趁东风、急整归船。纵飘零，满院杨花，犹是春前。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2206, "title": "高阳台", "author": "王沂孙", "body": "和周草窗寄越中诸友韵\n残雪庭阴，轻寒帘影，霏霏玉管春葭。小帖金泥，不知春在谁家。相思一夜窗前梦，奈个人、水隔天遮。但凄然，满树幽香，满地横斜。 江南自是离愁苦，况游骢古道，归雁平沙。怎得银笺，殷勤与说年华。如今处处生芳草，纵凭高、不见天涯。更消他，几度春风，几度飞花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2207, "title": "扫花游 秋声", "author": "王沂孙", "body": "商飙乍发，渐淅淅初闻，萧萧还住。顿惊倦旅。背青灯吊影，起吟愁赋。断续无凭，试立荒庭听取。在何许。但落叶满阶，惟有高树。 迢递归梦阻。正老耳难禁，病怀凄楚。故山院宇。想边鸿孤唳，砌蛩私语。数点相和，更著芭蕉细雨。避无处。这闲愁，夜深尤苦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2208, "title": "醉蓬莱 归故山", "author": "王沂孙", "body": "扫西风门径，黄叶凋零，白云萧散。柳换枯阴，赋归来何晚！爽气霏霏，翠蛾眉妩，聊慰登临眼。故国如尘，故人如梦，登高还懒。 数点寒英，为谁零落，楚魄难招，暮寒堪揽。步屧荒篱，谁念幽芳远。一室秋灯，一庭秋雨，更一声秋雁。试引芳樽，不知消得，几多依黯。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2209, "title": "长亭怨慢", "author": "王沂孙", "body": "重过中庵故园\n泛孤艇、东皋过遍。尚记当日，绿阴门掩。屐齿莓苔，酒痕罗袖事何限。欲寻前迹，空惆怅、成秋苑。自约赏花人，别后总、风流云散。 水远。怎知流水外，却是乱山尤远。天涯梦短，想忘了、绮疏雕槛。望不尽、冉冉斜阳，抚乔木、年华将晚。但数点红英，犹记西园凄婉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2210, "title": "齐天乐 蝉", "author": "仇远", "body": "夕阳门巷荒城曲，清音早鸣秋树。薄剪绡①衣，凉生鬓影，独饮天边风露。朝朝暮暮。奈一度凄吟，一番凄楚。尚有残声，蓦然飞过别枝去。 齐宫往事谩省，行人犹与说，当时齐女②。雨歇空山，月笼古柳，仿佛旧曾听处。离情正苦。甚懒拂冰笺，倦拈琴谱。满地霜红，浅莎寻蜕羽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2211, "title": "一剪梅", "author": "醴陵士人", "body": "宰相巍巍坐庙堂，说着经量，便要经量。那个臣僚上一章，头说经量，尾说经量。 轻狂太守在吾邦，闻说经量，星夜经量。山东河北久抛荒，好去经量，胡不经量？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2212, "title": "百字令 德祐乙亥", "author": "褚生", "body": "半堤花雨，对芳辰、消遣无奈情绪。春色尚堪描画在，万紫千红尘土。鹃促归期，莺收佞舌，燕作留人语。绕栏红药，韶华留此孤主。 真个恨杀东风，几番过了，不似今番苦。乐事赏心磨灭尽，忽见飞书传羽。湖水湖烟，峰南峰北，总是堪伤处。新塘杨柳，小腰犹自歌舞。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2213, "title": "满庭芳", "author": "徐君宝妻", "body": "汉上繁华，江南人物，尚遗宣政风流。绿窗朱户，十里烂银钩。一旦刀兵齐举，旌旗拥、百万貔貅。长驱入，歌楼舞榭，风卷落花愁。 清平三百载，典章文物，扫地俱休。幸此身未北，犹客南州。破鉴徐郎何在？空惆怅、相见无由。从今后，断魂千里，夜夜岳阳楼。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2214, "title": "齐天乐 客长安赋", "author": "王易简", "body": "宫烟晓散春如雾，参差护晴窗户。柳色初分，饧香未冷，正是清明百五。临流笑语。映十二栏干，翠颦红妒。短帽轻鞍，倦游曾遍断桥路。 东风为谁媚妩？岁华频感慨，双鬓何许！前度刘郎，三生杜牧，赢得征衫尘土。心期暗数。总寂寞当年，酒筹花谱。付与春愁，小楼今夜雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2215, "title": "水龙吟", "author": "唐珏", "body": "浮翠山房拟赋白莲\n淡妆人更婵娟，晚奁净洗铅华腻。泠泠月色，萧萧风度，娇红敛避。太液池空，霓裳舞倦，不堪重记。叹冰魂犹在，翠舆难驻，玉簪为谁轻坠。 别有凌空一叶，泛清寒、素波千里。珠房泪湿，明珰恨远，旧游梦里。羽扇生秋，琼楼不夜，尚遗仙意。奈香云易散，绡衣半脱，露凉如水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2216, "title": "贺新郎 秋晓", "author": "蒋捷", "body": "渺渺啼鸦了。亘鱼天，寒生峭屿，五湖秋晓。竹几一灯人做梦，嘶马谁行古道。起搔首、窥星多少。月有微黄篱无影，挂牵牛数朵青花小。秋太淡，添红枣。 愁痕倚赖西风扫。被西风、翻催鬓鬒，与秋俱老。旧院隔霜帘不卷，金粉屏边醉倒。计无此、中年怀抱。万里江南吹箫恨，恨参差白雁横天杪。烟未敛，楚山杳。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2217, "title": "贺新郎 吴江", "author": "蒋捷", "body": "浪涌孤亭起，是当年、蓬莱顶上，海风飘坠。帝①遣江神长守护，八柱蛟龙缠尾。斗吐出、寒烟寒雨。昨夜鲸翻坤轴动，卷雕翚②、掷向虚空里。但留得，绛虹住。 五湖③有客扁舟舣④，怕群仙、重游到此，翠旌⑤难驻。手拍阑干呼白鹭，为我殷勤寄语；奈鹭也、惊飞沙渚。星月一天云万壑，览茫茫、宇宙知何处？鼓双楫，浩歌去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2218, "title": "贺新郎", "author": "蒋捷", "body": "梦冷黄金屋。叹秦筝、斜鸿阵里，素弦尘扑。化作娇莺飞归去，犹认纱窗旧绿。正过雨、荆桃如菽。此恨难平君知否，似琼台涌起弹棋局。消瘦影，嫌明烛。 鸳楼碎泻东西玉。问芳踪、何时再展，翠钗难卜。待把宫眉横云样，描上生绡画幅。怕不是、新来装束。彩扇红牙今都在，恨无人解听开元曲。空掩袖，倚寒竹。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2219, "title": "贺新郎 兵后寓吴", "author": "蒋捷", "body": "深阁帘垂绣。记家人、软语灯边，笑涡红透。万叠城头哀怨角，吹落霜花满袖。影厮伴、东奔西走。望断乡关知何处，羡寒鸦、到着黄昏后。一点点，归杨柳。 相看只有山如旧。叹浮云、本是无心，也成苍狗。明日枯荷包冷饭，又过前头小阜。趁未发、且尝村酒。醉探枵囊毛锥在，问邻翁、要写《牛经》否。翁不应，但摇手。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2220, "title": "女冠子 元夕", "author": "蒋捷", "body": "蕙花香也。雪晴池馆如画。春风飞到，宝钗楼上，一片笙箫，琉璃光射。而今灯漫挂。不是暗尘明月，那时元夜。况年来、心懒意怯，羞与蛾儿争耍。 江城人悄初更打。问繁华谁解，再向天公借。剔残红灺。但梦里隐隐，钿车罗帕。吴笺银粉砑。待把旧家风景，写成闲话。笑绿鬟邻女，倚窗犹唱，夕阳西下。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2221, "title": "声声慢 秋声", "author": "蒋捷", "body": "黄花深巷，红叶低窗，凄凉一片秋声。豆雨声来，中间夹带风声。疏疏二十五点，丽谯门、不锁更声。故人远，问谁摇玉佩，檐底铃声？ 彩角声吹月堕，渐连营马动，四起笳声。闪烁邻灯，灯前尚有砧声。知他诉愁到晓，碎哝哝、多少蛩声！诉未了，把一半、分与雁声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2222, "title": "尾犯 寒夜", "author": "蒋捷", "body": "夜倚读书床，敲碎唾壶，灯晕明灭。多事西风，把斋铃频掣。人共语、温温芋火，雁孤飞、萧萧桧雪。遍阑干外，万顷鱼天，未了予愁绝。 鸡边长剑舞，念不到、此样豪杰。瘦骨棱棱，但凄其衾铁。是非梦、无痕堪忆，似双瞳、缤纷翠缬。浩然心在，我逢着、梅花便说。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2223, "title": "梅花引 荆溪阻雪", "author": "蒋捷", "body": "白鸥问我泊孤舟，是身留，是心留？心若留时，何事锁眉头？风拍小帘灯晕舞，对闲影，冷清清，忆旧游。 旧游旧游今在否？花外楼，柳下舟。梦也梦也，梦不到，寒水空流。漠漠黄云，湿透木棉裘。都道无人愁似我，今夜雪，有梅花，似我愁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2224, "title": "一剪梅 舟过吴江", "author": "蒋捷", "body": "一片春愁待酒浇。江上舟摇，楼上帘招。秋娘渡与泰娘桥①，风又飘飘，雨又萧萧。 何日归家洗客袍？银字笙调，心字香烧。流光容易把人抛，红了樱桃，绿了芭蕉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2225, "title": "虞美人 梳楼", "author": "蒋捷", "body": "丝丝杨柳丝丝雨，春在溟濛处。楼儿忒小不藏愁。几度和云飞去觅归舟。 天怜客子乡关远，借与花消遣。海棠红近绿栏杆。才卷朱帘却又晚风寒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2226, "title": "虞美人 听雨", "author": "蒋捷", "body": "少年听雨歌楼上，红烛昏罗帐。壮年听雨客舟中，江阔云低断雁叫西风。 而今听雨僧庐下，鬓已星星也。悲欢离合总无情，一任阶前点滴到天明。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2227, "title": "燕归梁 风莲", "author": "蒋捷", "body": "我梦唐宫春昼迟，正舞到、曳裾时。翠云队仗绛霞衣，慢腾腾，手双垂。 忽然急鼓催将起，似彩凤、乱惊飞。梦回不见万琼妃，见荷花，被风吹。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2228, "title": "贺新郎", "author": "蒋捷", "body": "乡士以狂得罪，赋此饯行\n甚矣君狂矣。想胸中、些儿磊磈，酒浇不去。据我看来何所似，一似韩家五鬼。又一似、杨家风子。怪鸟啾啾鸣未了，被天公、捉在樊笼里。这一错，铁难铸。 濯溪雨涨荆溪水。送君归、斩蛟桥外，水光清处。世上恨无楼百尺，装着许多俊气。做弄得、栖栖如此。临别赠言朋友事，有殷勤、六字君听取：节饮食，慎言语。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2229, "title": "少年游", "author": "蒋捷", "body": "枫林红透晚烟青，客思满鸥汀。二十年来，无家种竹，犹借竹为名。 春风未了秋风到，老去万缘轻。只把平生，闲吟闲咏，谱作棹歌声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2230, "title": "霜天晓角", "author": "蒋捷", "body": "人影窗纱，是谁来折花？折则从他折去，知折去、向谁家？檐牙，枝最佳。折时高折些。说与折花人道：须插向、鬓边斜。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2231, "title": "水龙吟 西湖怀古", "author": "陈德武", "body": "东南第一名州，西湖自古多佳丽。临堤台榭，画船楼阁，游人歌吹。十里荷花，三秋桂子，四山晴翠。使百年南渡，一时豪杰，都忘却、平生志。 可惜天旋时异，藉何人、雪当年耻？登临形胜，感伤今古，发挥英气。力士推山，天吴移水，作农桑地。借钱塘潮汐，为君洗尽，岳将军泪！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2232, "title": "南浦 春水", "author": "张炎", "body": "波暖绿粼粼，燕飞来，好是苏堤才晓。鱼没浪痕圆，流红去，翻笑东风难扫。荒桥断浦，柳阴撑出扁舟小。回首池塘青欲遍，绝似梦中芳草。 和云流出空山，甚年年净洗，花香不了？新绿乍生时，孤村路，犹忆那回曾到。余情渺渺，茂林觞咏如今悄。前度刘郎归去后，溪上碧桃多少。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2233, "title": "高阳台 西湖春感", "author": "张炎", "body": "接叶巢莺，平波卷絮，断桥斜日归船。能几番游？看花又是明年。东风且伴蔷薇住，到蔷薇、春已堪怜。更凄然，万绿西泠，一抹荒烟。 当年燕子知何处？但苔深韦曲，草暗斜川。见说新愁，如今也到鸥边。无心再续笙歌梦，掩重门、浅醉闲眠。莫开帘，怕见飞花，怕听啼鹃。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2234, "title": "壶中天", "author": "张炎", "body": "夜渡古黄河，与沈尧道、曾子敬同赋\n扬舲万里，笑当年底事，中分南北。须信平生无梦到，却向而今游历。老柳官河，斜阳古道，风定波犹直。野人惊问，泛槎何处狂客？ 迎面落叶萧萧，水流沙共远，都无行迹。衰草凄迷秋更绿，唯有闲鸥独立。浪挟天浮，山邀云去，银浦横空碧。扣舷歌断，海蟾飞上孤白。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2235, "title": "八声甘州", "author": "张炎", "body": "辛卯岁①，沈尧道②同余北归③，各处杭越④。逾岁，尧道来问寂寞，语笑数日，又复别去。赋此曲，并寄赵学舟⑤。\n记玉关⑥踏雪事清游，寒气脆貂裘。傍枯林古道，长河饮马，此意悠悠。短梦依然江表⑦，老泪洒西州⑧。一字无题处，落叶都愁。 载取白云归去⑨，问谁留楚佩，弄影中洲⑩？折芦花赠远，零落一身秋。向寻常野桥流水，待招来，不是旧沙鸥。空怀感，有斜阳处，却怕登楼⑪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2236, "title": "水龙吟 白莲", "author": "张炎", "body": "仙人掌上芙蓉，涓涓犹滴金盘露。轻装照水，纤裳玉立，飘飘似舞。几度销凝，满湖烟月，一汀鸥鹭。记小舟夜悄，波明香远，浑不见、花开处。 应是浣纱人妒。褪红衣、被谁轻误？闲情淡雅，冶姿清润，凭娇待语。隔浦相逢，偶然倾盖，似传心素。怕湘皋珮解，绿云十里，卷西风去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2237, "title": "摸鱼子 高爱山隐居", "author": "张炎", "body": "爱吾庐、傍湖千顷，苍茫一片清润。晴岚暖翠融融处，花影倒窥天镜。沙浦迥。看野水涵波，隔柳横孤艇。眠鸥未醒。甚占得莼乡，都无人见，斜照起春暝。 还重省。岂料山中秦晋，桃源今度难认。林间即是长生路，一笑原非捷径。深更静。待散发吹箫，跨鹤天风冷。凭高露饮。正碧落尘空，光摇半壁，月在万松顶。\n宋人词意\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2238, "title": "解连环 孤雁", "author": "张炎", "body": "楚江空晚。怅离群万里，恍然惊散。自顾影、欲下寒塘，正沙净草枯，水平天远。写不成书，只寄得、相思一点。料因循误了，残毡拥雪，故人心眼。 谁怜旅愁荏苒。谩长门夜悄，锦筝弹怨。想伴侣、犹宿芦花，也曾念春前，去程应转。暮雨相呼，怕蓦地、玉关重见。未羞他、双燕归来，画帘半卷。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2239, "title": "满庭芳 小春", "author": "张炎", "body": "晴皎霜花，晓融冰羽，开帘觉道寒轻。误闻啼鸟，生意又园林。闲了凄凉赋笔，便而今、懒听秋声。消凝处，一枝借暖，终是未多情。 阳和能几许？寻红探粉，也恁忺人。笑邻娃痴小，料理护花铃。却怕惊回睡蝶，恐和他、草梦都醒。还知否，能消几日，风雪灞桥深？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2240, "title": "忆旧游 登蓬莱阁", "author": "张炎", "body": "问蓬莱何处，风月依然，万里江清。休说神仙事，便神仙纵有，即是闲人。笑我几番醒醉，石磴扫松阴。任狂客难招，采芳难赠，且自微吟。 俯仰成陈迹，叹百年谁在，阑槛孤凭。海日生残夜，看卧龙和梦，飞入秋冥。还听水声东去，山冷不生云。正目极空寒，萧萧汉柏愁茂陵。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2241, "title": "台城路", "author": "张炎", "body": "寄姚江太白山人陈文卿\n薛涛笺上相思字，重开又还重摺。载酒船空，眠波柳老，一缕离痕难折。虚沙动月。叹千里悲歌，唾壶敲缺。却说巴山，此时怀抱那时节。 寒香深处话别。病来浑瘦损，懒赋情切。太白闲云，新丰旧雨，多少英游消歇。回潮似咽。送一点秋心，故人天末。江影沉沉，露凉鸥梦阔。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2242, "title": "月下笛", "author": "张炎", "body": "孤游万竹山中，闲门落叶，愁思黯然，因动《黍离》之感。时寓甬东积翠山舍。\n万里孤云，清游渐远，故人何处。寒窗梦里，犹记经行旧时路。连昌约略无多柳，第一是、难听夜雨。漫惊回凄悄，相看烛影，拥衾谁语。 张绪①，归何暮。半零落依依，断桥鸥鹭。天涯倦旅，此时心事良苦。只愁重洒西州泪②，问杜曲人家在否。恐翠袖、正天寒，犹倚梅花那树。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2243, "title": "绮罗香 红叶", "author": "张炎", "body": "万里飞霜，千林落木，寒艳不招春妒。枫冷吴江，独客又吟愁句。正船舣、流水孤村，似花绕、斜阳归路。甚荒沟、一片凄凉，载情不去载愁去。 长安谁问倦旅？羞见衰颜借酒，飘零如许。谩倚新妆，不入洛阳花谱。为回风、起舞尊前，尽化作、断霞千缕。记阴阴、绿遍江南，夜窗听暗雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2244, "title": "疏影 梅影", "author": "张炎", "body": "黄昏片月。似碎阴满地，还更清绝。枝北枝南，疑有疑无，几度背灯难折。依稀倩女离魂处，缓步出、前村时节。看夜深、竹外横斜，应妒过云明灭。 窥镜蛾眉淡抹。为容不在貌，独抱孤洁。莫是花光①，描取春痕，不怕丽谯吹彻。还惊海上燃犀去，照水底、珊瑚如活。做弄得、酒醒天寒，空对一庭香雪。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2245, "title": "湘月①", "author": "张炎", "body": "余载书往来山阴道中，每以事夺，不能尽兴。戊子冬晚，与徐平野、王中仙曳舟溪上。天空水寒，古意萧飒。中仙有词雅丽；平野作《晋雪图》，亦清逸可观。余述此调，盖白石《念奴娇》鬲指声②也。\n行行且止，把乾坤收入，篷窗深里。星散白鸥三四点，数笔横塘秋意。岸觜冲波，篱根受叶，野径通村市。疏风迎面，湿衣原是空翠。 堪叹敲雪门荒，争棋墅冷，苦竹鸣山鬼。纵使如今犹有晋，无复清游如此。落日沙黄，远天云淡，弄影芦花外。几时归去，剪取一半烟水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2246, "title": "声声慢", "author": "张炎", "body": "别四明诸友归杭\n山风古道，海国轻车，相逢只在东瀛。淡泊秋光，恰似此日游情。休嗟鬓丝断雪，喜闲身、重渡西泠。又溯远，趁回潮拍岸，断浦扬舲。 莫向长亭折柳，正纷纷落叶，同是飘零。旧隐新招，知住第几层云。疏篱尚存晋菊，想依然、认得渊明。待去也，最愁人、犹恋故人。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2247, "title": "长亭怨 旧居有感", "author": "张炎", "body": "望花外、小桥流水，门巷愔愔，玉箫声绝。鹤去台空，佩环何处弄明月？十年前事，愁千折、心情顿别。露粉风香谁为主？都成消歇。 凄咽。晓窗分袂处，同把带鸳亲结。江空岁晚，便忘了、尊前曾说。恨西风不庇寒蝉，便扫尽、一林残叶。谢杨柳多情，还有绿阴时节。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2248, "title": "甘州 寄李筠房", "author": "张炎", "body": "望涓涓一水隐芙蓉，几被暮云遮。正凭高送目，西风断雁，残月平沙。未觉丹枫尽老，摇落已堪嗟。无避秋声处，愁满天涯。 一自盟鸥别后，甚酒瓢诗锦，轻误年华。料荷衣初暖，不忍负烟霞。记前度、剪灯一笑，再相逢、知在那人家？空山远，白云休赠，只赠梅花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2249, "title": "清平乐", "author": "张炎", "body": "候蛩凄断，人语西风岸。月落沙平江似练，望尽芦花无雁。\n暗教愁损兰成，可怜夜夜关情。只有一枝梧叶，不知多少秋声！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2250, "title": "朝中措", "author": "张炎", "body": "清明时节雨声哗，潮拥渡头沙。翻被梨花冷看，人生苦恋天涯。 燕帘莺户，云窗雾阁，酒醒啼鸦。折得一枝杨柳，归来插向谁家？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2251, "title": "阮郎归 有怀北游", "author": "张炎", "body": "钿车骄马锦相连，香尘逐管弦。瞥然飞过水秋千。清明寒食天。 花贴贴，柳悬悬。莺房几醉眠。醉中不信有啼鹃。江南二十年。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2252, "title": "清平乐", "author": "张炎", "body": "采芳人杳，顿觉游情少。客里看春多草草，总被诗愁分了。\n去年燕子天涯，今年燕子谁家？三月休听夜雨，如今不是催花。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2253, "title": "思佳客", "author": "张炎", "body": "题周草窗《武林旧事》\n梦里瞢腾说梦华，莺莺燕燕已天涯。蕉中覆处应无鹿，汉上从来不见花。 今古事，古今嗟，西湖流水响琵琶。铜驼烟雨栖芳草，休向江南问故家。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2254, "title": "沁园春", "author": "王炎午", "body": "又是年时，杏红欲脸，柳绿初芽。奈寻春步远，马嘶湖曲；卖花声过，人唱窗纱。暖日晴烟，轻衣罗扇，看遍王孙七宝车。谁知道，十年魂梦，风雨天涯！ 休休何必伤嗟。谩赢得、青青两鬓华！且不知门外，桃花何代；不知江左，燕子谁家。世事无情，天公有意，岁岁东风岁岁花。拚一笑，且醒来杯酒，醉后杯茶。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2255, "title": "踏莎行 闲游", "author": "刘将孙", "body": "水际轻烟，沙边微雨。荷花芳草垂杨渡。多情移徙忽成愁，依稀恰是西湖路。 血染红笺，泪题锦句。西湖岂忆相思苦？只应幽梦解重来，梦中不识从何去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2256, "title": "沁园春", "author": "刘将孙", "body": "大桥名清江桥，在樟镇十里许，有无闻翁赋《沁园春》、《满庭芳》二阕，书避乱所见女子，末有“埋冤姐姐、衔恨婆婆”，语极俚。后有螺川杨氏和二首，又自序生杨嫁罗，丙子暮春，自涪翁亭下舟行，追骑迫，间逃入山，卒不免于驱掠。行三日，经此桥，睹无闻二词，以为特未见其苦，乃和于壁。复云“观者毋谓弄笔墨非好人家儿女”。此词虽俚，谅当近情，而首及权奸误国。又云“便归去，懒东涂西抹，学少年婆”，又云“错应谁铸”，皆追记往日之事，甚可哀也。因念南北之交，若此何限，心常痛之。适触于目，因其调为赋一词，悉叙其意，辞不足而情有余悲矣。\n流水断桥，坏壁春风，一曲韦娘。记宰相开元，弄权疮痏；全家骆谷，追骑仓皇。彩凤随鸦，琼奴失意，可似人间白面郎。知他是、燕南牧马，塞北驱羊？ 啼痕自诉衷肠，尚把笔低徊愧下堂。叹国手无棋，危途何策；书窗如梦，世路方长。青冢琵琶，穹庐笳拍，未比渠侬泪万行。二十载，竟何时委玉，何地埋香。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2257, "title": "摸鱼儿", "author": "徐一初", "body": "对茱萸、一年一度，龙山今在何处？参军莫道无勋业，消得从容尊俎。君看取，便破帽飘零，也博名千古。当年幕府。知多少时流，等闲收拾，有个客如许！ 追往事，满目山河晋土。征鸿又过边羽。登临莫上高层望，怕见故宫禾黍。觞绿醑，浇万斛牢愁，泪阁新亭雨。黄花无语。毕竟是西风，朝来披拂，犹忆旧时主。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2258, "title": "忆秦娥", "author": "郑文妻", "body": "花深深，一钩罗袜行花阴。行花阴。闲将柳带，细结同心。日边消息空沉沉。画眉楼上愁登临。愁登临。海棠开后，望到如今。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2259, "title": "鱼游春水", "author": "无名氏", "body": "秦楼东风里，燕子还来寻旧垒。馀寒犹峭，红日薄侵罗绮。嫩草方抽碧玉茵，媚柳轻窣黄金蕊。莺啭上林，鱼游春水。\n几曲阑干遍倚，又是一番新桃李。佳人应怪归迟，梅妆泪洗。\n凤箫声绝沉孤雁，望断清波无双鲤。云山万重，寸心千里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2260, "title": "阮郎归", "author": "无名氏", "body": "春风吹雨绕残枝，落花无可飞。小池寒绿欲生漪，雨晴还日西。 帘半卷，燕双归。讳愁无奈眉。翻身整顿着残棋，沉吟应劫①迟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2261, "title": "浣溪沙 瓜陂铺题壁", "author": "无名氏", "body": "剪碎香罗浥泪痕，鹧鸪声断不堪闻，马嘶人去近黄昏。\n整整斜斜杨柳陌，疏疏密密杏花村，一番风月更消魂。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2262, "title": "雨中花", "author": "无名氏", "body": "我有五重深深愿。第一愿、且图久远。二愿恰如雕梁双燕。岁岁后、长相见。 三愿薄情相顾恋。第四愿、永不分散。五愿奴哥收因结果，做个大宅院。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2263, "title": "眉峰碧", "author": "无名氏", "body": "蹙破眉峰碧。纤手还重执。镇日相看未足时，忍便使鸳鸯隻！ 薄暮投村驿。风雨愁通夕。窗外芭蕉窗里人，分明叶上心头滴。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2264, "title": "青玉案", "author": "无名氏", "body": "钉鞋踏破祥符路。似白鹭、纷纷去。试盝幞头谁与度。八厢儿事①，两员直殿，怀挟无藏处。 时辰报尽天将暮，把笔胡填备员句。试问闲愁知几许？两条脂烛，半盂馊饭，一阵黄昏雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2265, "title": "水调歌头", "author": "无名氏", "body": "建炎庚戌题吴江\n平生太湖上，短棹几经过。如今重到，何事愁与水云多？拟把匣中长剑，换取扁舟一叶，归去老渔蓑。银艾非吾事，丘壑已蹉跎。 鲙新鲈、斟美酒，起悲歌。太平生长，岂谓今日识兵戈！欲泻三江雪浪，净洗胡尘千里，不用挽天河。回首望霄汉，双泪堕清波。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2266, "title": "眼儿媚", "author": "无名氏", "body": "萧萧江上荻花秋，做弄许多愁。半竿落日，两行新雁，一叶扁舟。 惜分长怕君先去，直待醉时休。今宵眼底，明朝心上，后日眉头。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2267, "title": "青玉案", "author": "无名氏", "body": "年年社日停针线。怎忍见、双飞燕。今日江城春已半。一身犹在，乱山深处，寂寞溪桥畔。 春衫著破谁针线。点点行行泪痕满。落日解鞍芳草岸。花无人戴，酒无人劝，醉也无人管。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2268, "title": "踏莎行", "author": "无名氏", "body": "殢酒情怀，恨春时节。柳丝巷陌黄昏月。把君团扇卜君来，近墙扑得双蝴蝶。 笑不成言，喜还生怯。颠狂绝似前春雪。夜寒无处著相思，梨花一树人如削。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2269, "title": "一剪梅", "author": "无名氏", "body": "漠漠春阴酒半酣。风透春衫，雨透春衫。人家蚕事欲眠三。桑满筐篮，柘满筐篮。 先自离怀百不堪。樯燕呢喃，梁燕呢喃。篝灯强把锦书看。人在江南，心在江南。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2270, "title": "采桑子", "author": "无名氏", "body": "年年才到花时候，风雨成旬。不肯开晴，误却寻花陌上人。 今朝报道天晴也，花已成尘。寄语花神，何似当初莫做春。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2271, "title": "浣溪沙", "author": "无名氏", "body": "水涨鱼天拍柳桥。云鸠拖雨过江皋。一番春信入东郊。\n闲碾凤团消短梦，静看燕子垒新巢。又移日影上花梢。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2272, "title": "如梦令", "author": "无名氏", "body": "莺嘴啄花红溜，燕尾点波绿皱。指冷玉笙寒，吹彻《小梅》春透。依旧，依旧，人与绿杨俱瘦。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2273, "title": "金明池", "author": "无名氏", "body": "琼苑金池，青门紫陌，似雪杨花满路。云日淡、天低昼永，过三点两点细雨。好花枝、半出墙头，似怅望、芳草王孙何处。更水绕人家，桥当门巷，燕燕莺莺飞舞。 怎得东君长为主，把绿鬓朱颜，一时留住？佳人唱、《金衣》莫惜，才子倒、玉山休诉。况春来、倍觉伤心，念故国情多，新年愁苦。纵宝马嘶风，红尘拂面，也则寻芳归去。\n金明池（琼苑金池） 无名氏\n——明刊本《诗馀画谱》", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2274, "title": "眼儿媚", "author": "无名氏", "body": "杨柳丝丝弄轻柔，烟缕织成愁。海棠未雨，梨花先雪，一半春休。 而今往事难重省，归梦绕秦楼。相思只在：丁香枝上，豆蔻梢头。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2275, "title": "鹧鸪天", "author": "无名氏", "body": "枝上流莺和泪闻，新啼痕间旧啼痕。一春鱼鸟①无消息，千里关山劳梦魂。 无一语，对芳尊。安排肠断到黄昏。甫能炙得灯儿了，雨打梨花深闭门。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2276, "title": "满江红", "author": "无名氏", "body": "斗帐高眠，寒窗静、潇潇雨意。南楼近，更移三鼓，漏传一水。点点不离杨柳外，声声只在芭蕉里。也不管、滴破故乡心，愁人耳。 无似有，游丝细；聚复散，真珠碎。天应分付与，别离滋味。破我一床蝴蝶梦，输他双枕鸳鸯睡。向此际、别有好思量，人千里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2277, "title": "千秋岁令", "author": "无名氏", "body": "想风流态，种种般般媚。恨别离时太容易。香笺欲写相思意，相思泪滴香笺字。画堂深，银烛暗，重门闭。 似当日欢娱何日遂。愿早早相逢重设誓。美景良辰莫轻拌，鸳鸯帐里鸳鸯被，鸳鸯枕上鸳鸯睡。似恁地，长恁地，千秋岁。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2278, "title": "长相思", "author": "无名氏", "body": "去年秋，今年秋。湖上人家乐复忧，西湖依旧流。\n吴循州，贾循州。十五年间一转头，人生放下休。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2279, "title": "御街行", "author": "无名氏", "body": "霜风渐紧寒侵被。听孤雁、声嘹唳。一声声送一声悲，云淡碧天如水。披衣告语：“雁儿略住，听我些儿事。 塔儿南畔城儿里，第三个、桥儿外，濒河西岸小红楼，门外梧桐雕砌。请教且与，低声飞过，那里有、人人无寐。”", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2280, "title": "檐前铁", "author": "无名氏", "body": "悄无人，宿雨厌厌，空庭乍歇。听檐前铁马戛叮当，敲破梦魂残结。丁年事，天涯恨，又早在心头咽。 谁怜我、绮帘前，镇日鞋儿双跌。今番也、石人应下千行血。拟展青天，写作断肠文，难尽说。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2281, "title": "清平乐令", "author": "吴城小龙女", "body": "帘卷曲阑独倚，山展暮天无际。泪眼不曾晴，家在吴头楚尾。 数点雪花乱委，扑鹿沙鸥惊起。诗句欲成时，没入苍烟丛里。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2282, "title": "回心院", "author": "萧观音", "body": "扫深殿，闭久金铺暗。游丝络网尘作堆，积岁青苔厚阶面。扫深殿，待君宴。\n拂象床，凭梦借高唐。敲坏半边知妾卧，恰当天处少辉光。拂象床，待君王。\n换香枕，一半无云锦。为是秋来展转①多，更有双双泪痕渗。换香枕，待君寝。\n铺翠被，羞杀鸳鸯对。犹忆当时叫合欢，而今独覆相思块。铺翠被，待君睡。\n装绣帐，金钩未敢上。解却四角夜光珠，不教照见愁模样。装绣帐，待君贶。\n叠锦茵，重重空自陈。只愿身当白玉体，不愿伊当薄命人。叠锦茵，待君临。\n展瑶席，花笑三韩碧。笑妾新铺玉一床，从来妇欢不终夕。展瑶席，待君息。\n剔银灯，须知一样明。偏是君来生彩晕，对妾故作青荧荧。剔银灯，待君行。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2283, "title": "人月圆", "author": "吴激", "body": "南朝千古伤心事，犹唱后庭花。旧时王谢，堂前燕子，飞向谁家？ 恍然一梦，仙肌胜雪，宫髻堆鸦。江州司马，青衫泪湿，同是天涯。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2284, "title": "春从天上来", "author": "吴激", "body": "会宁府遇老姬，善鼓瑟。自言梨园旧籍，因感而赋此\n海角飘零。叹汉苑秦宫，坠露飞萤。梦里天上，金屋银屏。歌吹竞举青冥。问当时遗谱，有绝艺、鼓瑟湘灵。促哀弹，似林莺呖呖，山溜泠泠。 梨园太平乐府，醉几度春风，鬓变星星。舞破中原，尘飞沧海，飞雪万里龙庭。写胡笳幽怨，人憔悴、不似丹青。酒微醒。对一窗凉月，灯火青荧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2285, "title": "念奴娇", "author": "蔡松年", "body": "还都后，诸公见追和赤壁词，用韵者凡六人，亦复重赋\n离骚痛饮，笑人生佳处，能消何物。夷甫当年成底事，空想岩岩玉壁。五亩苍烟，一丘寒碧，岁晚忧风雪。西州扶病，至今悲感前杰。 我梦卜筑萧闲，觉来岩桂，十里幽香发。嵬隗胸中冰与炭，一酌春风都灭。胜日神交，悠然得意，遗恨无毫发。古今同致，永和徒记年月。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2286, "title": "相见欢", "author": "蔡松年", "body": "九日种菊西岩，云根石缝，金葩玉蕊遍之。夜置酒前轩，花间列蜜炬，风泉悲鸣，炉香蓊于岩穴。故人陈公辅坐石横琴，萧然有尘外趣，要余作数语，使清音者度之。\n云闲晚溜琅琅。泛炉香。一段斜川松菊瘦而芳。 人如鹄，琴如玉，月如霜。一曲清商人物两相忘。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2287, "title": "鹧鸪天 赏荷", "author": "蔡松年", "body": "秀樾横塘十里香，水花晚色静年芳。胭脂雪瘦熏沉水，翡翠盘高走夜光。 山黛远，月波长，暮云秋影蘸潇湘。醉魂应逐凌波梦，分付西风此夜凉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2288, "title": "鹊桥仙 待月", "author": "完颜亮", "body": "停杯不举，停歌不发，等候银蟾出海。不知何处片云来，做许大、通天障碍。 虬髯撚断，星眸睁裂，唯恨剑锋不快。一挥截断紫云腰，仔细看、嫦娥体态。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2289, "title": "江城子", "author": "蔡珪", "body": "王温季①自北都归，过余三河，坐中赋此\n鹊声迎客到庭除。问谁欤？故人车。千里归来，尘色半征裾。珍重主人留客意，奴白饭，马青刍。 东城入眼杏千株。雪模糊，俯平湖。与子花间，随分倒金壶。归报东垣诗社友，曾念我，醉狂无？", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2290, "title": "鹧鸪天", "author": "刘著", "body": "雪照山城玉指寒，一声羌管怨楼间。江南几度梅花发，人在天涯鬓已斑。 星点点，月团团。倒流河汉入杯盘。翰林风月三千首，寄与吴姬忍泪看。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2291, "title": "雨中花慢 代州南楼", "author": "赵可", "body": "云朔南陲，全赵幕府，河山襟带名藩。有朱楼缥缈，千雉①回旋。云度飞狐②绝险，天围紫塞③高寒。吊兴亡遗迹，咫尺西陵，烟树苍然。 时移事改，极目伤心，不堪独倚危栏。唯是年年飞雁，霜雪知还。楼上四时长好，人生一世谁闲。故人有酒，一尊高兴，不减东山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2292, "title": "浣溪沙", "author": "赵可", "body": "抬转炉熏自换香。锦衾收拾却遮藏。二年尘暗小鸳鸯。\n落木萧萧风似雨。疏櫺皎皎月如霜。此时此夜最凄凉。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2293, "title": "采桑子", "author": "王寂", "body": "十年尘土湖州梦，依旧相逢。眼约心同，空有灵犀一点通。 寻春自恨来何暮，春事成空。懊恼东风，绿尽疏阴落尽红。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2294, "title": "望海潮", "author": "邓千江", "body": "云雷天堑，金汤地险，名藩自古皋兰。营屯绣错，山形米聚，喉襟百二秦关。鏖战血犹殷。见阵云冷落，时有雕盘。静塞楼头晓月，依旧玉弓弯。 看看，定远西还。有元戎阃命，上将斋坛。区脱昼空，兜零夕举，甘泉又报平安。吹笛虎牙闲。且宴陪珠履，歌按云鬟。招取英灵毅魄，长绕贺兰山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2295, "title": "乌夜啼", "author": "刘迎", "body": "离恨远萦杨柳，梦魂长绕梨花。青衫记得章台①月，归路玉鞭斜。 翠镜啼痕印袖，红墙醉墨笼纱②。相逢不尽平生事，春思入琵琶。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2296, "title": "青玉案", "author": "党怀英", "body": "红莎绿蒻春风饼，趁梅驿，来云岭。紫桂岩空琼窦冷。佳人却恨，等闲分破，缥缈双鸾影。 一瓯月露心魂醒，更送清歌助清兴。痛饮休辞今夕永。与君洗尽，满襟烦暑，别作高寒境。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2297, "title": "鹧鸪天", "author": "党怀英", "body": "云步凌波小凤钩，年年星汉踏清秋。只缘巧极稀相见，底用人间乞巧楼。 天外事，两悠悠。不应也作可怜愁。开帘放入窥窗月，且尽新凉睡美休。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2298, "title": "月上海棠", "author": "党怀英", "body": "傲霜枝袅团珠蕾。冷香霏、烟雨晚秋意。萧散绕东篱，尚仿佛、见山清气。西风外，梦到斜川栗里①。 断霞鱼尾明秋水。带三两飞鸿点烟际。疏林飒秋声，似知人、倦游无味。家何处？落日西山紫翠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2299, "title": "谒金门", "author": "王庭筠", "body": "双喜鹊，几报归期浑错。尽做旧愁都忘却，新愁何处着？\n瘦雪一痕墙角，青子已妆残萼。不道枝头无可落，东风犹作恶。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2300, "title": "凤栖梧", "author": "王庭筠", "body": "衰柳疏疏苔满地。十二阑干，故国三千里。南去北来人老矣。短亭依旧残阳里。 紫蟹黄柑真解事。似倩西风、劝我归欤未。王粲登临寥落际。雁飞不断天连水。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2301, "title": "朝中措", "author": "完颜璹", "body": "襄阳①古道灞陵桥，诗兴与秋高。千古风流人物，一时多少雄豪。 霜清玉塞，云飞陇首，风落江皋。梦到凤凰台上，山围故国周遭。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2302, "title": "春草碧", "author": "完颜璹", "body": "几番风雨西城陌，不见海棠红、梨花白。底事胜赏匆匆，正自天付酒肠窄。更笑老东君，人间客。 赖有玉管新翻，罗襟醉墨。望中倚栏人，如曾识。旧梦回首何堪，故苑春光又陈迹。落尽后庭花，春草碧。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2303, "title": "浣溪沙 梦中作", "author": "王磵", "body": "林樾人家急暮砧。夕阳人影入江深。倚阑疏快北风襟。\n雨自北山明处黑，云随白鸟去边阴。几多秋思乱乡心。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2304, "title": "水调歌头", "author": "赵秉文", "body": "四明有狂客，呼我谪仙人。俗缘千劫不尽，回首落红尘。我欲骑鲸归去，只恐神仙官府，嫌我醉时真。笑拍群仙手，几度梦中身。 倚长松，聊拂石，坐看云。忽然黑霓落手，醉舞紫毫春。寄语沧浪流水，曾识闲闲居士，好为濯冠巾。却返天台去，华发散麒麟。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2305, "title": "青杏儿", "author": "赵秉文", "body": "风雨替花愁。风雨罢，花也应休。劝君莫惜花前醉，今年花谢，明年花谢，白了人头。 乘兴两三瓯。拣溪山好处追游。但教有酒身无事，有花也好，无花也好，选甚春秋。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2306, "title": "大江东去", "author": "赵秉文", "body": "用东坡先生韵\n秋光一片，问苍苍桂影，其中何物？一叶扁舟波万顷，四顾粘天无壁。叩枻长歌，嫦娥欲下，万里挥冰雪。京尘千丈①，可能容此人杰？ 回首赤壁矶边，骑鲸人去，几度山花发。澹澹长空今古梦②，只有归鸿明灭。我欲从公，乘风归去，散此麒麟发。三山安在，玉箫吹断明月！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2307, "title": "行香子", "author": "许古", "body": "秋入鸣皋，爽气飘萧。挂衣冠、初脱尘劳。窗间岩岫，看尽昏朝。夜山低，晴山近，晓山高。 细数闲来，几处村醪。醉模糊、信手挥毫。等闲陶写，问甚风骚。乐因循，能潦倒，也消摇。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2308, "title": "蝶恋花 聚骨扇", "author": "完颜璟", "body": "几股湘江龙骨瘦。巧样翻腾，叠作湘波皱。金缕小钿花草斗。翠条更结同心扣。 金殿珠帘闲永昼。一握清风，暂喜怀中透。忽听传宣须急奏。轻轻褪入香罗袖。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2309, "title": "临江仙", "author": "辛愿", "body": "河山亭留别钦叔、裕之\n谁识虎头峰下客，少年有意功名。清朝无路到公卿。萧萧茅屋下，白发老书生。 邂逅对床逢二妙，挥毫落纸堪惊。他年联袂上蓬瀛。春风莲烛影，莫问此时情。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2310, "title": "水龙吟", "author": "王渥", "body": "短衣匹马清秋，惯曾射虎南山下。西风白水，石鲸鳞甲，山川图画。千古神州，一时胜事，宾僚儒雅。快长堤万弩，平冈千骑，波涛卷，鱼龙夜。 落日孤城鼓角，笑归来、长围初罢。风云惨淡，貔貅得意，旌旗闲暇。万里天河，更须一洗，中原兵马。看鞬櫜呜咽，咸阳道左，拜西还驾。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2311, "title": "蓦山溪", "author": "张中孚", "body": "山河百二①，自古关中好。壮岁喜功名，拥征鞍、雕裘绣帽。时移事改，萍梗落江湖，听楚语，厌蛮歌，往事知多少？ 苍颜白发，故里欣重到。老马省曾行②，也频嘶、冷烟残照。终南山色，不改旧时青③；长安道，一回来，须信一回老。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2312, "title": "感皇恩 出京门有感", "author": "李俊民", "body": "忍泪出门来，杨花如雪。惆怅天涯又离别。碧云西畔，举目乱山重叠。据鞍归去也，情凄切！ 一日三秋，寸肠千结。敢向青天问明月。算应无恨，安用暂圆还缺？愿人长似，月圆时节。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2313, "title": "水调歌头", "author": "元好问", "body": "与李长源游龙门\n滩声荡高壁，秋气静云林。回头洛阳城阙，尘土一何深。前日神光牛背，今日春风马耳，因见古人心。一笑青山底，未受二毛侵。 问龙门，何所似，似山阴。平生梦想佳处，留眼更登临。我有一卮芳酒，唤取山花山鸟，伴我醉时吟。何必丝与竹，山水有清音。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2314, "title": "水调歌头 赋三门津", "author": "元好问", "body": "黄河九天上，人鬼瞰重关。长风怒卷高浪，飞洒日光寒。峻似吕梁千仞，壮似钱塘八月，直下洗尘寰。万象入横溃，依旧一峰闲。 仰危巢，双鹄过，杳难攀。人间此险何用，万古秘神奸。不用燃犀下照，未必佽飞强射，有力障狂澜。唤取骑鲸客，挝鼓过银山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2315, "title": "摸鱼儿", "author": "元好问", "body": "问世间、情是何物，直教生死相许？天南地北双飞客，老翅几回寒暑。欢乐趣，离别苦，就中更有痴儿女。君应有语，渺万里层云，千山暮雪，只影向谁去？ 横汾路，寂寞当年箫鼓，荒烟依旧平楚。招魂①楚些何嗟及，山鬼②暗啼风雨。天也妒，未信与，莺儿燕子俱黄土。千秋万古，为留待骚人，狂歌痛饮，来访雁邱处。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2316, "title": "摸鱼儿", "author": "元好问", "body": "泰和中，大名民家小儿女，有以私情不如意赴水者，官为踪迹之，无见也。其后踏藕者得二尸水中，衣服仍可验，其事乃白。是岁此陂荷花开，无不并蒂者。沁水梁国用，时为录事判官，为李用章内翰言如此。此曲以乐府《双蕖怨》命篇。“咀五色之灵芝，香生九窍；咽三危①之瑞露，春动七情”，韩偓《香奁集》中自序语。\n问莲根、有丝多少，莲心知为谁苦？双花脉脉娇相向，只是旧家儿女。天已许。甚不教、白头生死鸳鸯浦？夕阳无语。算谢客烟中，湘妃江上，未是断肠处。 香奁梦，好在灵芝瑞露。人间俯仰今古。海枯石烂情缘在，幽恨不埋黄土。相思树，流年度，无端又被西风误。兰舟少住。怕载酒重来，红衣半落，狼藉卧风雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2317, "title": "水龙吟", "author": "元好问", "body": "素丸何处飞来，照人只是承平旧。兵尘万里，家书三月，无言搔首。几许光阴，几回欢聚，长教分手。料婆娑桂树，多应笑我，憔悴似，金城柳。 不爱竹西歌吹，爱空山、玉壶清昼。寻常梦里，膏车盘谷，拏舟枋口。不负人生，古来惟有，中秋重九。愿年年此夕，团栾儿女，醉山中酒。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2318, "title": "沁园春 除夕", "author": "元好问", "body": "再见新正，去岁逐贫，今年逐穷。算公田二顷，谁如元亮；吴牛十角，未比龟蒙。面目堪憎，语言无味，五鬼行来此病同。齑盐里，似扬雄寂寞，韩愈龙钟。 何人炮凤烹龙，且莫笑先生饭甑空。便看来朝镜，都无勋业；拈将诗笔，犹有神通。花柳横陈，江山呈露，尽入经营惨淡中。闲身在，看薄批明月，细切清风。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2319, "title": "青玉案", "author": "元好问", "body": "落红吹满沙头路。似总为、春将去。花落花开春几度。多情惟有，画梁双燕，知道春归处。 镜中冉冉韶华暮。欲写幽怀恨无句。九十花期能几许。一卮芳酒，一襟清泪，寂寞西窗雨。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2320, "title": "临江仙", "author": "元好问", "body": "自洛阳往孟津道中作\n今古北邙山下路，黄尘老尽英雄。人生长恨水长东。幽怀谁共语，远目送归鸿。 盖世功名将底用，从前错怨天公。浩歌一曲酒千钟。男儿行处是，未要论穷通。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2321, "title": "临江仙", "author": "元好问", "body": "李辅之在齐州，予客济源，辅之有和\n荷叶荷花何处好？大明湖上新秋。红妆翠盖木兰舟。江山如画里，人物更风流。 千里故人千里月，三年孤负欢游。一尊白酒寄离愁。殷勤桥下水，几日到东州！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2322, "title": "小重山", "author": "元好问", "body": "酒冷灯青夜不眠。寸肠千万缕，两相牵。鸳鸯秋雨半池莲。分飞苦，红泪晓风前。 天远雁翩翩。雁来人北去，远如天。安排心事待明年。无情月，看待几时圆！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2323, "title": "鹧鸪天", "author": "元好问", "body": "候馆灯昏雨送凉，小楼人静月侵床。多情却被无情恼，今夜还如昨夜长。 金屋暖，玉炉香。春风都属富家郎。西园何限相思树，辛苦梅花候海棠。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2324, "title": "鹧鸪天", "author": "元好问", "body": "只近浮名不近情。且看不饮更何成。三杯渐觉纷华远①，一斗都浇块磊平。 醒复醉，醉还醒。灵均憔悴可怜生。《离骚》读杀浑无味，好个诗家阮步兵！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2325, "title": "鹧鸪天", "author": "元好问", "body": "薄命妾辞\n颜色如花画不成。命如叶薄可怜生。浮萍自合无根蒂，杨柳谁教管送迎。 云聚散，月亏盈。海枯石烂古今情。鸳鸯只影江南岸，肠断枯荷夜雨声。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2326, "title": "人月圆", "author": "元好问", "body": "玄都观里桃千树，花落水空流。凭君莫问，清泾浊渭，去马来牛。 谢公扶病，羊昙挥涕，一醉都休。古今几度，生存华屋，零落山丘。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2327, "title": "清平乐 太山上作", "author": "元好问", "body": "江山残照，落落舒清眺。涧壑风来号万窍，尽入长松悲啸。\n井蛙瀚海云涛，醯鸡日远天高。醉眼千峰顶上，世间多少秋毫！", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2328, "title": "清平乐", "author": "元好问", "body": "离肠宛转，瘦觉妆痕浅。飞去飞来双语燕，消息知郎近远。\n楼前小雨珊珊，海棠帘幕轻寒。杜宇一声春去，树头无数青山。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2329, "title": "点绛唇 长安中作", "author": "元好问", "body": "沙际春归，绿窗犹唱留春住。问春何处，花落莺无语。\n渺渺吟怀，漠漠烟中树。西楼暮，一帘疏雨，梦里寻春去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2330, "title": "摸鱼儿", "author": "元好问", "body": "楼桑村汉昭烈庙\n问楼桑、故居无处，青林留在祠宇。荒坛社散乌声□①，寂寞汉家箫鼓。春已暮。君不见、锦城花重惊风雨。刘郎良苦。尽玉垒青云，锦江秀色，办作一丘土！ 西山好，满意龙盘虎踞。登临感怆千古。当时诸葛成何事，伯仲果谁伊吕？还自语。缘底事、十年来往燕南路？征鞍且驻。就老瓦盆边，田翁共饮，携手醉乡去。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2331, "title": "玉楼春", "author": "元好问", "body": "惊沙猎猎风成阵，白雁一声霜有信。琵琶肠断塞门秋，却望紫台知远近。 深宫桃李无人问，旧爱玉颜今自恨。明妃留在两眉愁，万古春山颦不尽。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2332, "title": "木兰花慢 游三台", "author": "元好问", "body": "拥岧岧双阙，龙虎气，郁峥嵘。想暮雨珠帘，秋香桂树，指顾台城。台城，为谁西望，但哀弦凄断似平生。只道江山如画，争教天地无情。 风云奔走十年兵，惨淡入经营。问对酒当歌，曹侯墓上，何用虚名。青青，故都乔木，怅西陵遗恨几时平？安得参军健笔，为君重赋芜城。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2333, "title": "满江红", "author": "段克己", "body": "雨后荒园，群卉尽、律残无射。疏篱下，此花能保，英英鲜质。盈把足娱陶令意，夕餐谁似三闾洁？到而今、狼藉委苍苔，无人惜。 堂上客，须空白。都无语，怀畴昔。恨因循过了，重阳佳节。飒飒凉风吹汝急，汝身孤特应难立。谩临风、三嗅绕芳丛，歌还泣。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2334, "title": "江城子", "author": "段成己", "body": "阶前流水玉鸣渠。爱吾庐，惬幽居。屋上青山，山鸟喜相呼。少日功名空自许，今老矣，欲何如。 闲来活计未全疏。月边渔，雨边锄。花底风来，吹乱读残书。谁唤九原摩诘起，凭画作、倦游图。", "category": "宋词", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2335, "title": "〔黄钟〕人月圆", "author": "元好问", "body": "重冈已隔红尘断，村落更年丰。移居要就：窗中远岫，舍后长松。　　十年种木，一年种谷，都付儿童。老夫惟有：醒来明月，醉后清风。\n玄都观里桃千树，花落水空流。凭君莫问：清泾浊渭，去马来牛。　　谢公扶病，羊昙挥涕，一醉都休。古今几度：生存华屋，零落山丘。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2336, "title": "〔双调〕骤雨打新荷", "author": "元好问", "body": "绿叶阴浓，遍池亭水阁，偏趁凉多。海榴初绽，朵朵蹙红罗。乳燕雏莺弄语，有高柳鸣蝉相和。骤雨过，琼珠乱撒，打遍新荷。\n人生百年有几，念良辰美景，休放虚过。穷通前定，何用苦张罗。命友邀宾玩赏，对芳樽浅酌低歌。且酩酊，任他两轮日月，来往如梭。此曲调名本为“小圣乐”，或入双调、或入小石调。因为元好问之作“骤雨过，琼珠乱撒，打遍新荷”几句脍炙人口，故人们又称此曲为“骤雨打新荷”。元陶宗仪《辍耕录》卷九云：“〔小圣乐〕乃小石调曲，元遗山先生好问所制，而名姬多歌之，俗以为‘骤雨打新荷’是也。”赵松雪听歌姬唱此词，赋诗赞曰：“主人自有沧洲趣，游女乃歌白雪词。”此曲正是以“白雪词”（高雅的歌曲）抒写“沧洲趣”（放浪江湖的逸致闲情）。这里表现的，乃是宋元之际文人们一种典型的精神生活，有一定认识意义。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2337, "title": "〔越调〕小桃红", "author": "杨果", "body": "满城烟水月微茫，人倚兰舟唱。常记相逢若耶上，隔三湘，碧云望断空惆怅。美人笑道，莲花相似，情短藕丝长。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2338, "title": "〔越调〕小桃红", "author": "杨果", "body": "采莲人和采莲歌，柳外兰舟过。不管鸳鸯梦惊破，夜如何？有人独上江楼卧。伤心莫唱，南朝旧曲，司马泪痕多。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2339, "title": "〔越调〕小桃红", "author": "杨果", "body": "采莲湖上棹船回，风约湘裙翠。一曲琵琶数行泪，望君归，芙蓉开尽无消息。晚凉多少，红鸳白鹭，何处不双飞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2340, "title": "〔仙吕〕翠裙腰", "author": "杨果", "body": "莺穿细柳翻金翅，迁上最高枝。海棠零乱飘阶址，坠胭脂。共谁同唱送春词。\n〔金盏儿〕减容姿，瘦腰肢，绣床尘满慵针指。眉懒画，粉羞施，憔悴死。无尽闲愁将甚比，恰如梅子雨丝丝。\n〔绿窗愁〕有客持书至，还喜却嗟咨。未委归期约几时，先拆破鸳鸯字。原来则是卖弄他风流浪子：夸翰墨，显文词，枉用了身心空费了纸。\n〔赚尾〕总虚脾，无实事，乔问候的言辞怎使。复别了花笺重作念，偏自家少负你相思。唱道再展放重读，读罢也无言暗切齿。沉吟了数次，骂你个负心贼堪恨，把一封寄来的书都扯做纸条儿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2341, "title": "〔南吕〕干荷叶", "author": "刘秉忠", "body": "干荷叶，色苍苍，老柄风摇荡。减了清香，越添黄。都因昨夜一场霜，寂寞在秋江上。\n干荷叶，色无多，不奈风霜锉。贴秋波，倒枝柯。宫娃齐唱采莲歌，梦里繁华过。\n南高峰，北高峰，惨淡烟霞洞。宋高宗，一场空。吴山依旧酒旗风，两度江南梦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2342, "title": "〔般涉调〕耍孩儿", "author": "杜仁杰", "body": "风调雨顺民安乐，都不似俺庄家快活。桑蚕五谷十分收，官司无甚差科。当村许下还心愿，来到城中买些纸火。正打街头过，见吊个花碌碌纸榜，不似那答儿闹穰穰人多。\n〔六煞〕见一个人手撑着椽做的门，高声的叫“请请”，道“迟来的满了无处停坐”。说道“前截儿院本《调风月》，背后幺末敷演《刘耍和》”。高声叫“赶散易得，难得的妆哈[2]”。\n〔五煞〕要了二百钱放过咱，入得门上个木坡。见层层叠叠团坐。抬头觑是个钟楼模样，往下觑却是人旋窝。见几个妇女向台儿上坐。又不是迎神赛社，不住的擂鼓筛锣。\n〔四煞〕一个女孩儿转了几遭，不多时引出一伙。中间里一个央人货。裹着枚皂头巾顶门上插一管笔，满脸石灰更着些黑道儿抹。知他待是如何过？浑身上下，则穿领花布直裰。\n〔三煞〕念了会诗共词，说了会赋与歌。无差错。唇天口地无高下，巧语花言记许多。临绝末，道了低头撮脚，爨罢将幺拨。\n〔二煞〕一个妆做张太公，他改做小二哥。行行行说向城中过。见个年少的妇女向帘儿下立，那老子用意铺谋待取做老婆。教小二哥相说合，但要的豆谷米麦，问甚布绢纱罗。\n〔一煞〕教太公往前挪不敢往后挪，抬左脚不敢抬右脚。翻来覆去由他一个。太公心下实焦躁，把一个皮棒槌则一下打做两半个。我则道脑袋天灵破，则道兴词告状，刬地大笑呵呵。\n〔尾〕则被一胞尿，爆的我没奈何，刚捱刚忍更待看些儿个，枉被这驴颓笑杀我。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2343, "title": "〔仙吕〕醉中天", "author": "王和卿", "body": "弹破庄周梦，两翅驾东风。三百座名园、一采一个空。谁道风流种，唬杀寻芳的蜜蜂。轻轻飞动，把卖花人扇过桥东。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2344, "title": "〔仙吕〕一半儿", "author": "王和卿", "body": "书来和泪怕开缄，又不归来空再三。这样病儿谁惯耽！越恁瘦岩岩，一半儿增添一半儿减。\n将来书信手拈着，灯下恣恣观觑了。两三行字真带草。提起来越心焦，一半儿丝挦一半儿烧。\n别来宽褪缕金衣，粉悴烟憔减玉肌。泪点儿只除衫袖知。盼佳期，一半儿才干一半儿湿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2345, "title": "〔双调〕拨不断", "author": "王和卿", "body": "胜神鳌，夯风涛，脊梁上轻负着蓬莱岛。万里夕阳锦背高，翻身犹恨东洋小。太公怎钓？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2346, "title": "〔越调〕小桃红盍西村", "author": "盍西村", "body": "万家灯火闹春桥，十里光相照，舞凤翔鸾势绝妙。可怜宵，波间涌出蓬莱岛。香烟乱飘，笙歌喧闹，飞上玉楼腰。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2347, "title": "〔越调〕小桃红", "author": "盍西村", "body": "绿云冉冉锁清湾，香彻东西岸。官课今年九分办；厮追攀，渡头买得新鱼雁。杯盘不干，欢欣无限，忘了大家难。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2348, "title": "〔越调〕小桃红", "author": "盍西村", "body": "杏花开候不曾晴，败尽游人兴。红雪飞来满芳径。问春莺，春莺无语风方定。小蛮有情，夜凉人静，唱彻醉翁亭。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2349, "title": "〔越调〕小桃红", "author": "盍西村", "body": "海棠开过到蔷薇，春色无多味。争奈新来越憔悴。教他谁？小环也似知人意。疏帘卷起，重门不闭，要看燕双飞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2350, "title": "〔越调〕小桃红", "author": "盍西村", "body": "绿杨堤畔蓼花洲，可爱溪山秀。烟水茫茫晚凉后，捕鱼舟，冲开万顷玻璃皱。乱云不收，残霞妆就，一片洞庭秋。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2351, "title": "〔双调〕潘妃曲", "author": "商挺", "body": "带月披星担惊怕，久立纱窗下。等候他。蓦听得门外地皮儿踏，则道是冤家，原来风动荼架。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2352, "title": "〔双调〕潘妃曲", "author": "商挺", "body": "闷酒将来刚刚咽，欲饮先浇奠。频祝愿，普天下心厮爱早团圆。谢神天，教俺也频频的勤相见。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2353, "title": "〔双调〕潘妃曲", "author": "商挺", "body": "一点青灯人千里。锦字凭谁寄？雁来稀。花落东君也憔悴。投至望君回。滴尽多少关山泪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2354, "title": "〔中吕〕阳春曲", "author": "胡祗遹", "body": "几枝红雪墙头杏，数点青山屋上屏。一春能得几晴明？三月景，宜醉不宜醒。\n残花酝酿蜂儿蜜，细雨调和燕子泥。绿窗春睡觉来迟。谁唤起？窗外晓莺啼。\n一帘红雨桃花谢，十里清阴柳影斜。洛阳花酒一时别。春去也，闲煞旧蜂蝶。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2355, "title": "〔双调〕沉醉东风", "author": "胡祗遹", "body": "锦织江边翠竹，绒穿海上明珠。月淡时，风清处，都隔断落红尘土。一片闲云任卷舒，挂尽朝云暮雨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2356, "title": "〔中吕〕喜春来", "author": "伯　颜", "body": "金鱼玉带罗襕扣，皂盖朱幡列五侯。山河判断在俺笔尖头。\n得意秋，分破帝王忧。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2357, "title": "〔仙吕〕点绛唇", "author": "不忽木", "body": "宁可身卧糟丘，赛强如命悬君手。寻几个知心友，乐以忘忧，愿作林泉叟。\n〔混江龙〕布袍宽袖，乐然何处谒王侯。但樽中有酒，身外无愁。数着残棋江月晓，一声长啸海门秋[1]。山间深住，林下隐居，清泉濯足。强如闲事萦心，淡生涯一味谁参透。草衣木食[2]，胜如肥马轻裘。\n〔油葫芦〕虽住在洗耳溪边不饮牛，贫自守。乐闲身翻作抱官囚，布袍宽褪拿云手，玉箫占断谈天口。吹箫仿伍员，弃瓢学许由。野云不断深山岫，谁肯官路里半途休。\n〔天下乐〕明放着伏事君王不到头，休休，难措手。游鱼儿见食不见钩，都只为半纸功名[3]一笔勾，急回头两鬓秋。\n〔那吒令〕谁待似落花般莺朋燕友，谁待似转灯般龙争虎斗。你看这迅指间乌飞兔走，假若名利成，至如田园就，都是些去马来牛[4]。\n〔鹊踏枝〕臣则待醉江楼，卧山丘。一任教谈笑虚名，小子封侯。臣向这仕路上为官倦首，枉尘埋了锦带吴钩[5]。\n〔寄生草〕但得黄鸡嫩，白酒熟，一任教疏篱墙缺茅庵漏。则要窗明炕暖蒲团厚，问甚身寒腹饱麻衣旧。饮仙家水酒两三瓯，强如看翰林风月三千首。\n〔村里迓鼓〕臣离了九重宫阙，来到这八方宇宙。寻几个诗朋酒友，向尘世外消磨白昼。臣则待领着紫猿，携白鹿，跨苍虬。观着山色，听着水声，饮着玉瓯，倒大来省气力如诚惶顿首。\n〔元和令〕臣向山林得自由，比朝市内不生受。玉堂金马间琼楼，控珠帘十二钩。臣向草庵门外见瀛洲，看白云天尽头。\n〔上马娇〕但得个月满舟，酒满瓯，则待雄饮醉时休。紫箫吹断三更后，畅好是休，孤鹤唳一声秋。\n〔游四门〕世间闲事挂心头，唯酒可忘忧。非是微臣常恋酒，叹古今荣辱，看兴亡成败，则待一醉解千愁。\n〔后庭花〕拣溪山好处游，向仙家酒旋[6]。会三岛十洲客，强如宴公卿万户侯。不索你问缘由，把玄关[7]泄漏。这箫声世间无，天上有，非微臣说强口。酒葫芦挂树头，打鱼船缆渡口。\n〔柳叶儿〕则待看山明水秀，不恋您市曹中物穰人稠。想高官重职难消受，学耕耨，种田畴，倒大来无虑无忧。\n〔赚尾〕既把世情疏，感谢君恩厚，臣怕饮的是黄封御酒[8]。竹杖芒鞋任意留，拣溪山好处追游。就着这晓云收，冷落了深秋，饮遍金山月满舟。那其间潮来的正悠，船开在当溜[9]，卧吹箫管到扬州。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2358, "title": "〔正宫〕黑漆弩", "author": "王　恽", "body": "苍波万顷孤岑矗，是一片水面上天竺。金鳌头满咽三杯，吸尽江山浓绿。蛟龙虑恐下燃犀，风起浪翻如屋。任夕阳归棹纵横，待偿我平生不足。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2359, "title": "〔越调〕平湖乐", "author": "王恽", "body": "采菱人语隔秋烟，波静如横练。入手风光莫流转，共留连。画船一笑春风面。江山信美，终非吾土，问何日是归年。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2360, "title": "〔越调〕平湖乐", "author": "王　恽", "body": "社坛烟淡散林鸦，把酒观多稼。霹雳弦声斗高下，笑喧哗，壤歌亭外山如画。朝来致有，西山爽气，不羡日夕佳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2361, "title": "〔黄钟〕节节高", "author": "卢挚", "body": "雨晴云散，满江明月。风微浪息，扁舟一叶。半夜心，三生梦，万里别，闷倚篷窗睡些。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2362, "title": "〔南吕〕金字经", "author": "卢挚", "body": "梦中邯郸道，又来走这遭。须不是山人索价高，时自嘲，虚名无处逃。谁惊觉？晓霜侵鬓毛。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2363, "title": "〔双调〕沉醉东风", "author": "卢挚", "body": "挂绝壁松枯倒倚，落残霞孤鹜齐飞。四围不尽山，一望无穷水。散西风满天秋意。夜静云帆月影低，载我在潇湘画里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2364, "title": "〔双调〕沉醉东风", "author": "卢挚", "body": "对酒问人生几何，被无情日月消磨。炼成腹内丹，泼煞心头火。葫芦提醉中闲过。万里云山入浩歌，一任旁人笑我。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2365, "title": "〔双调〕沉醉东风", "author": "卢挚", "body": "题红叶清流御沟，赏黄花人醉歌楼。天长雁影稀，月落山容瘦。冷清清暮秋时候。衰柳寒蝉一片愁，谁肯教白衣送酒？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2366, "title": "〔双调〕沉醉东风", "author": "卢挚", "body": "恰离了绿水青山那答，早来到竹篱茅舍人家。野花路畔开，村酒槽头榨。直吃的欠欠答答。醉了山童不劝咱，白发上黄花乱插。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2367, "title": "〔双调〕沉醉东风", "author": "卢挚", "body": "残花酿蜂儿蜜脾，细雨和燕子香泥。白雪柳絮飞，红雨桃花坠。杜鹃声又是春归。纵有新诗赠别离，医不可相思病体。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2368, "title": "〔双调〕蟾宫曲", "author": "卢挚", "body": "沙三伴哥来嗏！两腿青泥，只为捞虾。太公庄上，杨柳阴中，磕破西瓜。小二哥昔涎剌塔，碌轴上淹着个琵琶。看荞麦开花，绿豆生芽。无是无非，快活煞庄家。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2369, "title": "〔双调〕蟾宫曲", "author": "卢挚", "body": "道南宅岂识楼桑[1]。何许英雄，惊倒孙郎。汉鼎[2]才分，流延晋宋，弹指萧梁[3]。昭代[4]车书四方，北溟鱼[5]浮海吞江。临眺苍茫。醉倚歌鬟[6]，吟断寒窗。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2370, "title": "〔双调〕蟾宫曲", "author": "卢挚", "body": "朝瀛洲暮舣湖滨，向衡麓寻诗，湘水寻春。泽国纫兰，汀洲搴若，谁与招魂？空目断苍梧暮云，黯黄陵宝瑟凝尘。世态纷纷，千古长沙，几度词臣！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2371, "title": "〔双调〕蟾宫曲", "author": "卢挚", "body": "江城歌吹风流，雨过平山，月满西楼。几许华年，三生醉梦，\n六月凉秋。按锦瑟佳人劝酒，卷朱帘齐按凉州。客去还留，云树萧萧，河汉悠悠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2372, "title": "〔双调〕蟾宫曲", "author": "卢挚", "body": "柳濛烟梨雪参差，犬吠柴荆，燕语茅茨。老瓦盆边，田家翁媪，鬓发如丝。桑柘外秋千女儿，髻双鸦[9]斜插花枝。转眄移时，应叹行人，马上哦诗。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2373, "title": "〔双调〕蟾宫曲", "author": "卢挚", "body": "系行舟谁遣卿卿[11]，爱林下风姿，云外歌声。宝髻堆云，冰弦散雨，总是才情。恰绿树南熏[12]晚晴，险些儿羞杀啼莺。客散邮亭，楚调将成，醉梦初醒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2374, "title": "〔双调〕寿阳曲", "author": "卢挚", "body": "才欢悦，早间别，痛煞煞好难割舍。画船儿载将春去也，空留下半江明月。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2375, "title": "〔双调〕殿前欢", "author": "卢挚", "body": "酒杯浓，一葫芦春色醉山翁，一葫芦酒压花梢重。随我奚童，葫芦干、兴不穷。谁人共，一带青山送。乘风列子[13]，列子乘风。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2376, "title": "〔中吕〕喜春来过普天乐", "author": "赵岩", "body": "琉璃殿暖香浮细，翡翠帘深卷燕迟，夕阳芳草小亭西。间纳履，见十二个粉蝶儿飞。一个恋花心，一个搀春意。一个翩翻粉翅，一个乱点罗衣。一个掠草飞，一个穿帘戏。一个赶过杨花西园里睡，一个与游人步步相随。一个拍散晚烟，一个贪欢嫩蕊，那一个与祝英台梦里为期。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2377, "title": "〔中吕〕山坡羊", "author": "陈草庵", "body": "伏低伏弱，装呆装落，是非犹自来着莫。任从他，待如何。天公尚有妨农过，蚕怕雨寒苗怕火。阴，也是错；晴，也是错。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2378, "title": "〔中吕〕山坡羊", "author": "陈草庵", "body": "晨鸡初叫，昏鸦争噪，那个不去红尘闹。路遥遥，水迢迢，功名尽在长安道。今日少年明日老。山，依旧好；人，憔悴了。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2379, "title": "〔仙吕〕一半儿", "author": "关汉卿", "body": "云鬟雾鬓胜堆鸦，浅露金莲簌绛纱，不比等闲墙外花。骂你个俏冤家，一半儿难当一半儿耍。\n碧纱窗外静无人，跪在床前忙要亲。骂了个负心回转身。虽是我话儿嗔，一半儿推辞一半儿肯。\n银台灯灭篆烟残，独入罗帏淹泪眼，乍孤眠好教人情兴懒。薄设设被儿单，一半儿温和一半儿寒。\n多情多绪小冤家，迤逗得人来憔悴煞，说来的话先瞒过咱。怎知他，一半儿真实一半儿假。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2380, "title": "〔南吕〕四块玉", "author": "关汉卿", "body": "自送别，心难舍，一点相思几时绝。凭阑袖拂杨花雪。溪又斜，山又遮，人去也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2381, "title": "〔南吕〕四块玉", "author": "关汉卿", "body": "适意行，安心坐。渴时饮饥时餐醉时歌，困来时就向莎茵卧。\n日月长，天地阔，闲快活。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2382, "title": "〔南吕〕四块玉", "author": "关汉卿", "body": "旧酒投[1]，新醅泼[2]，老瓦盆边笑呵呵。共山僧野叟闲吟和。他出一对鸡，我出一个鹅，闲快活。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2383, "title": "〔南吕〕四块玉", "author": "关汉卿", "body": "意马收，心猿锁。跳出红尘恶风波，槐阴午梦谁惊破。离了利名场，钻入安乐窝，闲快活。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2384, "title": "〔南吕〕四块玉", "author": "关汉卿", "body": "南亩耕，东山卧，世态人情经历多。闲将往事思量过。贤的是他，愚的是我，争什么！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2385, "title": "〔商调〕梧叶儿", "author": "关汉卿", "body": "别离易，相见难，何处锁雕鞍。春将去，人未还，这其间，殃及煞[3]愁眉泪眼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2386, "title": "〔双调〕沉醉东风", "author": "关汉卿", "body": "咫尺的天南地北，霎时间月缺花飞。手执着饯行杯，眼阁着别离泪。刚道得声“保重将息”，痛煞煞教人舍不得。“好去者望前程万里！”", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2387, "title": "〔双调〕沉醉东风", "author": "关汉卿", "body": "忧则忧鸾孤凤单，愁则愁月缺花残。为则为俏冤家，害则害谁曾惯？瘦则瘦不似今番，恨则恨孤帏绣衾寒，怕则怕黄昏到晚。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2388, "title": "〔双调〕碧玉箫", "author": "关汉卿", "body": "秋景堪题，红叶满山溪；松径偏宜，黄菊绕东篱。正清樽斟泼醅，有白衣劝酒杯。官品极，到底成何济！归，学取他渊明醉。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2389, "title": "〔双调〕大德歌", "author": "关汉卿", "body": "子规啼，不如归，道是春归人未归。几日添憔悴，虚飘飘柳絮飞。一春鱼雁无消息，则见双燕斗衔泥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2390, "title": "〔双调〕大德歌", "author": "关汉卿", "body": "俏冤家，在天涯，偏那里绿杨堪系马！困坐南窗下，数对清风想念他。蛾眉淡了教谁画？瘦岩岩羞带石榴花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2391, "title": "〔双调〕大德歌", "author": "关汉卿", "body": "风飘飘，雨潇潇，便做陈抟睡不着。懊恼伤怀抱，扑簌簌泪点抛。秋蝉儿噪罢寒蛩儿叫，淅零零细雨打芭蕉。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2392, "title": "〔双调〕大德歌", "author": "关汉卿", "body": "雪纷纷，掩重门，不由人不断魂！瘦损江梅韵，那里是清江江上村！香闺里冷落谁瞅问？好一个憔悴的凭阑人！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2393, "title": "〔黄钟〕侍香金童", "author": "关汉卿", "body": "春闺院宇，柳絮飘香雪。帘幕轻寒雨乍歇，东风落花迷粉蝶。芍药初开，海棠才谢。\n〔幺〕柔肠脉脉，新愁千万迭。偶记年前人乍别，秦台玉箫声断绝。雁底关河，马头明月。\n〔降黄龙衮〕鳞鸿无个，锦笺慵写。腕松金，肌削玉，罗衣宽彻。泪痕淹破，胭脂双颊。宝鉴愁临，翠钿羞贴。\n〔幺〕等闲辜负，好天良夜。玉炉中，银台上，香消烛灭。凤帏冷落，鸳衾虚设。玉笋频搓，绣鞋重。\n〔出队子〕听子规啼血，又西楼角韵咽。半帘花影自横斜，画檐间丁当风弄铁，纱窗外琅玕敲瘦节。\n〔幺〕铜壶玉漏催凄切，正更阑人静也。金闺潇洒转伤嗟。莲步轻移呼侍妾，把香桌儿安排打快些！\n〔神仗儿煞〕深沉院舍，蟾光皎洁。整顿了霓裳，把名香谨爇。伽伽拜罢，频频祷祝：不求富贵豪奢，只愿得夫妻每早早圆备者！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2394, "title": "〔南吕〕一枝花", "author": "关汉卿", "body": "轻裁虾万须，巧织珠千串。金钩光错落，绣带舞蹁跹。似雾非烟，妆点就深闺院，不许那等闲人取次展。摇四壁翡翠浓阴，射万瓦琉璃色浅。\n〔梁州〕富贵似侯家紫帐，风流如谢府红莲，锁春愁不放双飞燕。绮窗相近，翠户相连，雕栊相映，绣幕相牵。拂苔痕满砌榆钱，惹杨花飞点如绵。愁的是抹回廊暮雨萧萧，恨的是筛曲槛西风剪剪，爱的是透长门夜月娟娟。凌波殿前，碧玲珑掩映湘妃面，没福怎能够见。十里扬州风物妍，出落着神仙。\n〔尾〕恰便似一池秋水通宵展，一片朝云尽日悬。你个守户的先生肯相恋，煞是可怜，则要你手掌里奇擎着耐心儿卷。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2395, "title": "〔南吕〕一枝花", "author": "关汉卿", "body": "普天下锦绣乡，环海内风流地。大元朝新附国，亡宋家旧华夷。水秀山奇，一到处堪游戏，这答儿忒富贵[4]。满城中绣幕风帘，一哄地[5]人烟凑集。\n〔梁州第七〕百十里街衢整齐，万余家楼阁参差，并无半答儿[6]闲田地。松轩竹径，药圃花蹊，茶园稻陌，竹坞梅溪。一陀儿一句诗题，一步儿一扇屏帏。西盐场便似一带琼瑶，吴山色千叠翡翠。兀良[7]，望钱塘江万顷玻璃。更有清溪、绿水，画船儿来往闲游戏。浙江亭[8]紧相对，相对着险岭高峰长怪石，堪羡堪题。\n〔尾〕家家掩映渠流水，楼阁峥嵘出翠微，遥望西湖暮山势。看了这壁，觑了那壁，纵有丹青下不得笔。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2396, "title": "〔南吕〕一枝花", "author": "关汉卿", "body": "攀出墙朵朵花，折临路枝枝柳[9]。花攀红蕊嫩，柳折翠条柔。\n浪子风流。凭着我折柳攀花手，直煞得花残柳败休。半生来折柳攀花，一世里眠花卧柳。\n〔梁州〕我是个普天下郎君领袖，盖世界浪子班头。愿朱颜不改常依旧。花中消遣，酒内忘忧。分茶，竹；打马，藏阄[10]。通五音六律[11]滑熟。甚闲愁到我心头。伴的是银筝女银台前理银筝笑倚银屏，伴的是玉天仙携玉手并玉肩同登玉楼。伴的是金钗客歌金缕捧金樽满泛金瓯[12]。你道我老也，暂休。占排场风月功名首，更玲珑又剔透。我是个锦阵花营都帅头[13]，曾玩府游州。\n〔隔尾〕子弟每是个茅草冈、沙土窝初生的兔羔儿乍向围场上走[14]；我是个经笼罩、受索网、苍翎毛老野鸡蹅踏的阵马儿熟[15]。经了些窝弓冷箭蜡枪头[16]，不曾落人后。恰不道“人到中年万事休”，我怎肯虚度了春秋。\n〔尾〕我是个蒸不烂、煮不熟、捶不匾、炒不爆、响珰珰一粒铜豌豆，恁子弟每谁教你钻入他锄不断、斫不下、解不开、顿不脱、慢腾腾千层锦套头[17]？我玩的是梁园月，饮的是东京酒；赏的是洛阳花，攀的是章台柳。我也会围棋、会蹴踘、会打围、会插科、会歌舞、会吹弹、会咽作、会吟诗、会双陆。你便是落了我牙、歪了我嘴、瘸了我腿、折了我手，天赐与我这几般儿歹症候。尚兀自不肯休。则除是阎王亲自唤，神鬼自来勾。三魂归地府，七魄丧冥幽。天哪，那其间才不向烟花路儿上走。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2397, "title": "诈妮子调风月[18]", "author": "关汉卿", "body": "〔越调·斗鹌鹑〕短叹长吁，千声万声；捣枕捶床，到三更四更。便是止渴思梅，充饥画饼。因甚顷刻休，则伤我取次成。好个个舒心，干支剌没兴。\n〔紫花儿序〕好轻乞列薄命，热忽剌姻缘，短古取恩情。见一个耍蛾儿来往向烈焰上飞腾，正撞着银灯，拦头送了性命。咱两个堪为比并：我为那包髻白身，你为这灯火青荧。\n〔幺〕我把这银灯来指定，引了咱两个魂灵。都是这一点虚名，怕不百伶百俐，千战千赢，更做道能行怎离得影？这一场了身不正，怎当那厮大四至铺排，小夫人名称？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2398, "title": "关大王独赴单刀会", "author": "关汉卿", "body": "〔双调·新水令〕大江东去浪千叠，引着这数十人驾着这小舟一叶。又不比九重龙凤阙，可正是千丈虎狼穴。大丈夫心烈，我觑这单刀会似赛村社。\n（云）好一派江景也呵！（唱）\n〔驻马听〕水涌山叠，年少周郎何处也？不觉的灰飞烟灭，可怜黄盖转伤嗟。破曹的樯橹一时绝，鏖兵的江水犹然热，好教我情惨切！（云）这也不是江水，（唱）二十年流不尽的英雄血！\n〔胡十八〕想古今立勋业，那里也舜五人、汉三杰[19]？两朝相隔数年别，不付能见者，却又早老也。开怀的饮数杯，（云）将酒来。（唱）尽心儿待醉一夜。\n〔庆东原〕你把我真心儿待，将筵宴设，你这般攀今揽古，分甚枝叶？我根前使不着你“之乎者也”、“诗云子曰”，早该豁口截舌[20]！有意说孙刘，你休目下番成吴越！\n〔沉醉东风〕想着俺汉高皇图王霸业，汉光武秉正除邪，汉王允将董卓诛，汉皇叔把温侯灭，俺哥哥合承受汉家基业。则你这东吴国的孙权，和俺刘家却是甚枝叶？请你个不克己先生自说！\n〔雁儿落〕则为你三寸不烂舌，恼犯我三尺无情铁。这剑饥餐上将头，渴饮仇人血。\n〔得胜令〕则是条龙向鞘中蛰，唬得人向坐间呆，今日故友每才相见，休着俺弟兄每相间别。鲁子敬听者，你心内休乔怯，畅好是随邪[21]，休怪我十分酒醉也。\n〔搅筝琶〕却怎生闹炒炒军兵列，上来的休遮当，莫拦截！（云）当着我的，呵呵！（唱）我着他剑下身亡，目前流血。便有那张仪口、蒯通舌，休那里躲闪藏遮。好生的送我到船上者，我和你慢慢的相别。\n〔离亭宴带歇指煞〕我则见紫袍银带公人列，晚天凉风冷芦花谢，我心中喜悦。昏惨惨晚霞收，冷飕飕江风起，急飐飐云帆扯[22]。承管待、承管待，多承谢、多承谢。唤梢公慢者，缆解开岸边龙，船分开波中浪，棹搅碎江中月。正欢娱有甚进退，且谈笑不分明夜。说与你两件事先生记者：百忙里称不了老兄心，急切里倒不了俺汉家节。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2399, "title": "温太真玉镜台", "author": "关汉卿", "body": "〔寄生草·幺篇〕不枉了开着金屋、空着画堂！酒醒梦觉无情况，好天良夜成疏旷，临风对月空惆怅。怎能够可情人消受锦幄凤凰衾？把愁怀都打撇在玉枕鸳鸯帐。\n〔六幺序〕兀的不消人魂魄、绰人眼光？说神仙那的是天堂。则见脂粉馨香，环珮丁当，藕丝嫩新织仙裳，但风流都在他身上，添分毫便不停当。见他的不动情？你便都休强，则除是铁石儿郎，也索恼断柔肠！\n〔赚煞尾〕恰才立一朵海棠娇，捧一盏梨花酿，把我双送入愁乡醉乡。我这里下得阶基无个顿放，画堂中别是风光。恰才刚挂垂杨一抹斜阳，改变了黯黯阴云蔽上苍。眼见得人倚绿窗，又则怕灯昏罗帐，天那，休添上画檐间疏雨，滴愁肠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2400, "title": "温太真玉镜台", "author": "关汉卿", "body": "〔牧羊关〕纵然道肌如雪，腕似冰，虽是一段玉，却是几样磨成：指头是三节儿琼瑶，指甲似十颗水晶。稳坐的有那稳坐堪人敬，但举动有那举动可人憎。他兀自未揎起金衫袖，我又早先听的玉钏鸣。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2401, "title": "闺怨佳人拜月亭", "author": "关汉卿", "body": "〔油葫芦〕分明是风雨催人辞故国！行一步一叹息，两行愁泪脸边垂。一点雨间一行凄惶泪，一阵风对一声长吁气。〔做滑科〕，百忙里一步一撒！嗨，索与他一步一提！这一对绣鞋儿分不得帮和底，稠紧紧粘带着淤泥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2402, "title": "闺怨佳人拜月亭", "author": "关汉卿", "body": "〔伴读书〕你靠栏槛临台榭，我准备名香爇。心事悠悠凭谁说，只除向金鼎焚龙麝，与你殷勤参拜遥天月，此意也无别。\n〔笑和尚〕韵悠悠比及把角品绝，碧荧荧投至那灯儿灭，薄设设衾共枕空舒设。冷清清不恁迭，闲遥遥生枝节，闷恹恹怎捱他如年夜！\n〔倘秀才〕天那！这一炷香，则愿削减了俺尊君狠切；这一炷香，则愿俺那抛闪下的男儿较些。那一个爷娘不间叠，不似俺，忒嗻，劣缺。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2403, "title": "感天动地窦娥冤", "author": "关汉卿", "body": "〔斗虾蟆〕空悲戚，没理会，人生死，是轮回。感着这般病疾，值着这般时势，可是风寒暑湿，或是饥饱劳役，各人症候自知。人命关天关地，别人怎生替得？寿数非干今世，相守三朝五夕，说甚一家一计？又无羊酒段匹，又无花红财礼；把手为活过日，撒手如同休弃。不是窦娥忤逆，生怕傍人论议。不如听咱劝你，认个自家悔气，割舍的一具棺材停置，几件布帛收拾，出了咱家门里，送入他家坟地。这不是你那从小儿年纪指脚的夫妻。我其实不关亲，无半点恓惶泪。休得要心如醉，意似痴，便这等嗟嗟怨怨，哭哭啼啼。\n〔感皇恩〕呀！是谁人唱叫扬疾，不由我不魄散魂飞。恰消停，才苏醒，又昏迷。捱千般打拷，万种凌逼，一杖下，一道血，一层皮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2404, "title": "感天动地窦娥冤", "author": "关汉卿", "body": "〔正宫·端正好〕没来由犯王法，不提防遭刑宪，叫声屈动地惊天！顷刻间游魂先赴森罗殿，怎不将天地也生埋怨。\n〔滚绣球〕有日月朝暮悬，有鬼神掌著生死权。天地也只合把清浊分辨，可怎生糊突了盗跖颜渊。为善的受贫穷更命短，造恶的享富贵又寿延。天地也做得个怕硬欺软，却元来也这般顺水推船。地也，你不分好歹何为地？天也，你错勘贤愚枉做天！哎，只落得两泪涟涟。\n〔耍孩儿〕不是我窦娥罚下这等无头愿，委实的冤情不浅；若没些儿灵圣与世人传，也不见得湛湛青天。我不要半星热血红尘洒，都只在八尺旗枪素练悬。等他四下里皆瞧见，这就是咱苌弘化碧[23]，望帝啼鹃[24]。\n〔二煞〕你道是暑气暄，不是那下雪天；岂不闻飞霜六月因邹衍[25]？若果有一腔怨气喷如火，定要感的六出冰花滚似绵，免着我尸骸现；要什么素车白马[26]，断送出古陌荒阡！\n〔一煞〕你道是天公不可期，人心不可怜，不知皇天也肯从人愿。做甚么三年不见甘霖降？也只为东海曾经孝妇冤。如今轮到你山阳县。这都是官吏每无心正法，使百姓有口难言。\n〔煞尾〕浮云为我阴，悲风为我旋，三桩儿誓愿明题遍。（做哭科，云）婆婆也，直等待雪飞六月，亢旱三年呵，（唱）那其间才把你个屈死的冤魂这窦娥显。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2405, "title": "感天动地窦娥冤", "author": "关汉卿", "body": "〔梅花酒〕你道是咱不该“这招状供写的明白”，本一点孝顺的心怀，倒做了惹祸的胚胎。我只道官吏每还覆勘，怎将咱屈斩首在长街！第一要素旗枪鲜血洒，第二要三尺雪将死尸埋，第三要三年旱示天灾。咱誓愿委实大。\n〔收江南〕呀，这的是衙门从古向南开，就中无个不冤哉！痛杀我娇姿弱体闭泉台，早三年以外，则落的悠悠流恨似长淮。\n〔鸳鸯煞尾〕从今后把金牌势剑从头摆，将滥官污吏都杀坏，与天子分忧，万民除害。嘱付你爹爹，收养我奶奶。可怜他无妇无儿，谁管顾年衰迈！再将那文卷舒开，（带云）爹爹也，把我窦娥名下，（唱）屈死的于伏[27]罪名儿改。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2406, "title": "赵盼儿风月救风尘", "author": "关汉卿", "body": "〔仙吕·点绛唇〕妓女追陪，觅钱一世。临收计，怎做的百纵千随，知重咱风流婿。\n〔混江龙〕我想这姻缘匹配，少一时一刻强难为。如何可意？怎的相知？怕不便脚搭着脑杓成事早，怎知他手拍着胸脯悔后迟！寻前程，觅下稍，恰便是黑海也似难寻觅。料的来人心不问，天理难欺。\n〔油葫芦〕姻缘簿全凭我共你，谁不待拣个称意的？他每都拣来拣去百千回。待嫁一个老实的，又怕尽世儿难成对；待嫁一个聪俊的，又怕半路里轻抛弃。遮莫向狗溺处藏，遮莫向牛屎里堆，忽地便吃了一个合扑地，那时节睁着眼怨他谁！\n〔天下乐〕我想这先嫁的还不曾过几日，早折的容也波仪、瘦似鬼，只教你难分说、难告诉、空泪垂！我看了些觅前程俏女娘，见了些铁心肠男子辈，便一生里孤眠，我也直甚颓！\n〔元和令〕做丈夫的便做不的子弟，那做子弟的他影儿里会虚脾，那做丈夫的忒老实。那厮虽穿着几件虼螂皮，人伦事晓得甚的？\n〔胜葫芦〕你道这子弟情肠甜似蜜，但娶到他家里，多无半载周年相弃掷，早努牙突嘴，拳椎脚踢，打的你哭啼啼。\n〔幺篇〕恁时节船到江心补漏迟，烦恼怨他谁？事要前思免后悔。我也劝你不得，有朝一日，准备着搭救你块望夫石。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2407, "title": "赵盼儿风月救风尘", "author": "关汉卿", "body": "〔金菊香〕想当日他暗成公事，只怕不相投。我作念你的言词，今日都应口。则你那去时，恰便似去秋。他本是薄幸的班头，还说道有恩爱、结绸缪。\n〔醋葫芦〕你铺排着鸳衾和凤帱，指望效天长共地久；蓦入门知滋味便合休。几番家眼睁睁打干净待离了我这手。（带云）赵盼儿（唱）你做的个见死不救，可不羞杀这桃园中杀白马、宰乌牛。\n〔幺篇〕那一个不碜可可道横死亡？那一个不实丕丕拔了短筹？则你这亚仙子母老实头。普天下爱女娘的子弟口，那一个不指皇天各般说咒？恰似秋风过耳早休休！\n〔幺篇〕想当初有忧呵同共忧，有愁呵一处愁。他道是残生早晚丧荒丘，做了个游街野巷村务酒；你道是百年之后，立一个妇名儿，做鬼也风流。\n〔后庭花〕我将这情书亲自修，教他把天机休泄漏。传示与休莽戆收心的女，拜上你浑身疼的歹事头。你好没来由，遭他毒手，无情的棍棒抽，赤津津鲜血流，逐朝家如暴囚，怕不将性命丢！况家乡隔郑州，有谁人相睬瞅，空这般出尽丑。\n〔柳叶儿〕则教你怎生消受，我索合再做个机谋。把这云鬟蝉鬓妆梳就，珊瑚钩，芙蓉扣，扭捏的身子儿别样娇柔。\n〔双雁儿〕我着这粉脸儿搭救你女骷髅，割舍的一不做二不休，拼了个由他咒也波咒。不是我说大口，怎出得我这烟月手！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2408, "title": "钱大尹智宠谢天香", "author": "关汉卿", "body": "〔石榴花〕我则道坐着的是那个俊儒流，我这里猛窥视、细凝眸，原来是三年不肯往杭州；闪的我落后，有国难投。莫不是把咱故意相迤逗，特故的把他来惭羞。你觑那衣服每各自施忠厚，百般里省不的甚缘由。\n〔斗鹌鹑〕并无那私事公仇，到与俺张筵置酒。我则是佯不相瞅，怎敢、怎敢道问候。我这里施罢礼、官人行紧低首。谁敢道是离了左右，我则索侍立傍边，我则索趋前褪后。\n〔上小楼〕更做道题个话头，你可便心休僝僽。你觑那首领面前，一左一右，不离前后。你若带酒，是必休将咱迤逗。这里可便不比我那上厅祗候。\n〔幺〕他那里则是举手，我这里忍着泪眸。不敢道是厮问厮当，厮来厮去，厮掴厮揪；我如今在这里不自由！你觑我皮里抽肉；你休问我可怎生骨岩岩脸儿黄瘦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2409, "title": "望江亭中秋切鲙", "author": "关汉卿", "body": "〔越调·斗鹌鹑〕则这今晚开筵，正是中秋令节。只合低唱浅斟，莫待他花残月缺。见了的珍奇，不消的咱说。则这鱼鳞甲鲜，滋味别。这鱼不宜那水煮油煎，则是那薄批细切。\n〔紫花儿序〕俺则待稍关打节，怕有那惯施舍的经商，不请言赊。则俺这篮中鱼尾，又不比案上罗列，活计全别。俺则是一撒网一蓑衣一箬笠，先图些打捏[28]。只问那肯买的哥哥，照顾俺也些些。\n〔金蕉叶〕相公你若是报一声着人远接，怕不的船儿上有五十座笙歌摆设。你为公事来到这些，不知你怎生做兀的关节？\n〔调笑令〕若是贱妾，晚来些，相公船儿上黑齁齁[29]的熟睡歇，则你那金牌势剑身傍列。见官人远离一射，索用甚从人拦当者，俺只待拖狗皮的拷断他腰截。\n〔鬼三台〕不是我夸贞烈，世不曾和个人儿热。我丑则丑刁决古，不由我见官人便心邪，我也立不的志节。官人你救黎民为人须为彻，拿滥官杀人须见血。我呵只为你这眼去眉来，使不着我那冰清玉洁。\n〔圣药王〕珠冠儿怎戴者，霞帔儿怎挂者，这三檐伞怎向顶门遮。唤侍妾，簇捧者。我从来打鱼船上扭的那身子儿别，替你稳坐七香车。\n〔秃厮儿〕那厮也忒懵懂玉山低趄，着鬼祟醉眼乜斜，我将这金牌虎符都袖褪[30]者。唤相公，早醒些，快迭。\n〔络丝娘〕我且回身将杨衙内深深的拜谢，您娘向急飐飐[31]船儿上去也。到家对儿夫尽分说，那一番周折。\n〔收尾〕从今不受人磨灭，稳情取好夫妻百年喜悦。俺这里美孜孜在芙蓉帐笑春风，只他那冷清清杨柳岸伴残月。\n〔马鞍儿〕（李稍唱）想着想着跌脚儿叫。（张千唱）想着想着我难熬。（衙内唱）酩子里愁肠酩子里[32]焦。（众合唱）又不敢着傍人知道，则把他这好香烧，好香烧，咒的他热肉儿跳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2410, "title": "望江亭中秋切鲙", "author": "关汉卿", "body": "〔双调·新水令〕有这等倚权豪贪酒色滥官员，将俺个有儿夫的媳妇来欺骗。他只待强拆开我长搀搀的连理枝，生摆断我颤巍巍的并头莲；其实负屈衔冤，好将俺穷百姓可怜见！\n〔沉醉东风〕杨衙内官高势显，昨夜个说地谈天，只道他仗金牌将夫婿诛，恰元来击云板请夫人见。只听的叫吖吖嚷成一片，抵多少笙歌引至画堂前。看他可认的我有些面善？\n〔雁儿落〕只他那身常在柳陌眠，脚不离花街串，几年闻姓名，今日逢颜面。\n〔得胜令〕呀！请你个杨衙内少埋冤。（衙内云）这一位夫人好面熟也。（李稍云）兀的不是张二嫂？（衙内云）嗨！夫人，你使的好见识，直被你瞒过小官也！（正旦唱：）吓的他半晌只茫然，又无那八棒十枷罪，止不过三交两句言。这一只渔船，只费得半夜工夫缠，俺两口儿，今年做一个中秋八月圆。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2411, "title": "钱大尹智勘绯衣梦", "author": "关汉卿", "body": "〔南吕·一枝花〕去时节恰黄昏灯影中，看看的定夜钟声后。我可便本欲图两处喜，到翻做满怀愁，心绪浇油。脚趔趄、家前后，身倒偃、门左右。觉一阵地惨天愁，遍体上寒毛抖擞。\n〔梁州〕战速速肉如钩搭，森森的发似人揪。本待要铺谋定计风也不教透；送的我有家难奔，有事难收。脚下的鹅楣涩道，身倚定亮隔虬楼。我一片心搜寻遍四大神州，不中用野走娇羞。俺、俺、俺，本是那一对儿未成就交颈的鸳鸯；是、是、是，则为那软兀剌误事的那禽兽，天那、天那，闪的我嘴碌都恰便似跌了弹的斑鸠。我欲待问一个事头；昏天黑地，谁敢向花园里走，我从来又怯后。则为那无用的梅香无去就，送的我泼水难收。我来到这花园中也。兀的不是风筝儿。\n〔四块玉〕那风筝儿为记号，他可便依然有；咱两个相约在梧桐树边头。险不绊倒了我那，则我这绣鞋儿莫不跚着那青苔溜。这泥污了我这鞋底尖。红染了我这罗裤口。可怎生血浸湿我这白那个袜头！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2412, "title": "包待制三勘蝴蝶梦", "author": "关汉卿", "body": "〔脱布衫〕争奈一家一计，肠肚萦牵；一上一下，语话熬煎；一左一右，把孩儿顾恋；一捋一把，雨泪涟涟。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2413, "title": "包待制智斩鲁斋郎", "author": "关汉卿", "body": "〔南吕·一枝花〕全失了人伦天地心，倚仗着恶党凶徒势。活支剌娘儿双拆散，生各札夫妇两分离。从来有日月交蚀，几曾见夫主婚、妻招婿？今日个妻嫁人、夫做媒，自取些奁房断送陪随，那里也羊酒、花红、段匹？\n〔梁州第七〕他凭着恶哏哏威风纠纠，全不怕碧澄澄天网恢恢。一夜间摸不着陈抟睡[33]，不分喜怒，不辨高低。弄的我身亡家破，财散人离！对浑家又不敢说是谈非，行行里只泪眼愁眉。你、你、你，做了个别霸王自刎虞姬[34]，我、我、我，做了个进西施归湖范蠡[35]，来、来、来，浑一似嫁单于出塞明妃[36]。正青春似水，娇儿幼女成家计，无忧虑，少萦系，平地起风波二千尺，一家儿瓦解星飞。\n〔牧羊关〕怕不晓日楼台静，春风帘幙低，没福的怎生消得！这厮强赖人钱财，莽夺人妻室。高筑座营和寨，斜搠面杏黄旗。梁山泊贼相似，与蓼儿洼争甚的！\n〔四块玉〕将一杯醇糯酒十分的吃，更怕我酒后疏狂失了便宜。扭回身刚咽的口长吁气，我乞求得醉似泥，唤不归。我则图别离时，不记得。\n〔骂玉郎〕也不知你甚些儿看的能当意？要你做夫人，不许我过今日，因此上急忙忙送你到他家内。这都是我缘分薄，恩爱尽，受这等死临逼。\n〔感皇恩〕他、他、他，嫌官小不为，嫌马瘦不骑，动不动挑人眼、剔人骨、剥人皮。他少甚么温香软玉，舞女歌姬！虽然道我灾星现，也是他的花星照，你的福星催。\n〔采茶歌〕撇下了亲夫主不须提，单是这小业种好孤凄，从今后谁照觑他饥时饭，冷时衣？虽然个留得亲爷没了母，只落得一番思想一番悲。\n〔黄钟尾〕夺了我旧妻儿，却与个新佳配，我正是弃了甜桃绕山寻醋梨。知他是甚亲戚！教喝下庭阶，转过照壁。出的宅门，扭回身体，遥望着后堂内，养家的人，贤惠的妻！非今生是宿世。我则索寡宿孤眠过年岁，几时能勾再得相逢，则除是南柯梦儿里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2414, "title": "刘夫人庆赏五侯宴", "author": "关汉卿", "body": "〔正宫·端正好〕风飕飕，遍身麻。则我这笃簌簌[37]连身战，冻钦钦手脚难拳。走的紧来到荒坡佃，觉我这可扑扑的心头战。\n〔滚绣球〕我这里立不定虚气喘，无筋力手腕软。瘦身躯急难动转，恰来到井口旁边。雪打的我眼怎开，风吹的我身倒偃[38]。冻碌碌自嗟自怨，也是咱前世前缘。冻的我拿不的绳索，拳挛着手，立不定身躯耸定肩，苦痛难言。\n〔倘秀才〕我这里立不定，吁吁的气喘。我将这绳头儿呵的来觉软。一桶水提离井口边，寒惨惨手难拳。我可便应难动转。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2415, "title": "须贾大夫谇范叔", "author": "高文秀", "body": "〔油葫芦〕自古书生多命薄，端的可便成事的少，你看几人平步蹑云霄。便读得十年书也只受的十年暴，便晓得十分事也抵不得十分饱。至如俺学到老，越着俺穷到老。想诗书不是防身宝，刬地着俺白屋教儿曹。\n〔天下乐〕他每只是些趓避当差影身草。自古来文章，可便将人都误了。劝今人休将前辈学。学卞庄斩虎的入虎穴，学吕望钓鱼的近池沼，学太康放鹰鹘拿燕雀。\n〔那吒令〕我论着那斩虎的，则不如去斩蛟；钓鱼的，则不如去钓鳌；放鹰的，则不如去放。调大谎往上趱，抱粗腿向前跳，倒能勾禄重官高。\n〔鹊踏枝〕但有些个好穿着、好靴脚，出来的苫眼铺眉，一个个纳胯那腰，说谎的今时可便使着。天那则俺这诚实的管老死蓬蒿。\n〔寄生草〕本待要寻知契、谒故交，见十家九家门关了。起三阵五阵檐风哨，有千片万片梨花落。但得个一顷半顷洛阳田，谁待想七月八月长安道。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2416, "title": "须贾大夫谇范叔", "author": "高文秀", "body": "〔牧羊关〕敢怕吃那细索面醒酒汤，便是油汁水瀽污也何妨。今日个为公子设佳筵，怎倒与小生作贱降[1]。只见一条沉铁索当前面，两束粗荆棍在边厢。那里有这般样稀奇物？大夫也，强将来做荐[2]寿觞。\n〔牧羊关〕泪雹子腮边落，血冬凌满脊梁。冻剥剥雪上加霜。则被你饿掉了三魂，敲翻了五脏。带肉连皮颤，彻髓透心凉。似这等勘范叔森罗殿，抵多少冻苏秦冰雪堂[3]。\n〔牧羊关〕待走来如何走，待藏来怎地藏。没揣[4]的偏和他打个头撞。我几曾吃美酒羊羔，刚则是吃了会胡枷乱棒。则被这粪沾湿我两鬓角，尿浸透我一胸膛。你闻不的我这秽气混身臭，院公也，我几吃那开埕[5]十里香。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2417, "title": "黑旋风双献功", "author": "高文秀", "body": "〔哨遍〕可便道恭敬不如从命，今日里奉着哥哥令。若有人将哥哥厮欺负，我和他两白日便见那簸箕星[6]。则我这两条臂拦关扶碑[7]；则我这两只手可敢便直钓缺丁[8]。理会的山儿性，我从来个路见不平，爱与人当道撅坑[9]。我喝一喝骨都都海波腾，撼一撼赤力力山岳崩。但恼着我黑脸的爹爹，和他做场的歹斗，翻过来落可便吊盘的煎饼[10]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2418, "title": "黑旋风双献功", "author": "高文秀", "body": "〔赚煞尾〕我也不用一条枪，也不用三尺铁，则俺这壮士怒目前见血。东岳庙磕塔的相逢无话说，把那厮滴溜扑马上活挟。他若是与时节，万事无些；不与呵，山儿待放些劣撇。恼起我这草坡前倒拖牛的性格，强逞我这敌官军勇烈，我把那厮脊梁骨，各支支生做两三截。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2419, "title": "黑旋风双献功", "author": "高文秀", "body": "〔得胜令〕呀！便问我要东西，叔待[11]则你那没梁桶儿便休提。不比你财主们多周济，量俺这穷庄家有甚的？俺真个堪嗤。俺孩儿每卧土坑披麻被，你可也争知？（带云）还有精着腿，无个袴儿穿的。（唱）谁有那闲钱补笊篱[12]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2420, "title": "好酒赵元遇上皇", "author": "高文秀", "body": "〔南吕·一枝花〕汤着风把柳絮迎，冒着雪把梨花拂。雪遮得千树老，风剪得万枝枯。这般风雪程途，雪迷了天涯路。风又紧，雪又扑，恰便似杴瀽[13]筛扬，恰便似挦[14]绵扯絮。\n〔梁州〕假若韩退之蓝关外不前骏马[15]，孟浩然灞陵桥不肯骑驴[16]，冻的我战兢兢手脚难停住。更那堪天寒日短，旷野消疏，关山寂寞，风雪交杂。浑身上单夹衣服，舞东风乱糁[17]珍珠。抬起头似出窟顽蛇，缩着肩似水淹老鼠，躬着腰人样虾蛆。几时到帝都？刮天刮地狂风鼓，谁曾受这番苦？见三匹金鞍拴在老桑树，多敢是国戚皇族。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2421, "title": "保成公径赴渑池会", "author": "高文秀", "body": "〔雁儿落〕旗开云影飘[19]，炮响雷霆噪。弓开秋月圆，箭发流星落。\n〔得胜令〕霎时间尸首积山高，鲜血滚波涛。觅子寻爷叫，呼兄唤弟号。俺将帅雄骁，恰便似撞雾天边鹞。他军马奔逃，恰便似飘风云外鹤。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2422, "title": "看钱奴买冤家债主", "author": "郑廷玉", "body": "〔滚绣球〕我这里急急的研了墨浓，便待要轻轻的下了笔划。呀！儿也，这是我不得已无如之奈。可着我斑管难抬。这孩儿性情乖，是他娘肠肚摘下来。今日将俺这子父情可都撇在九霄云外，则俺这三口儿生扢扎两处分开。做娘的伤心惨惨刀剜腹，做爹的滴血簌簌泪满腮，恰便是郭巨般活把儿埋。\n〔倘秀才〕俺儿也差着一个字千般的见责。那员外伸着五个指十分的便掴，打的他连耳通红半壁腮。说又不敢高声语，哭又不敢放声来，他则是偷将那泪揩。\n〔滚绣球〕也曾有三年乳十月胎，似珍珠掌上抬。甚工夫养得他偌大，须不是半路里拾的婴孩。我虽是穷秀才，他觑人忒小哉。那些个公平买卖，量这一贯钞值甚钱财。他道我贪他香饵终吞钓，我则道留下青山怕没柴。拼的个搠笔巡街。\n〔倘秀才〕如今这有钱的度量呵，做不的三江也那四海，便受用呵多不到十年五载。我骂你个勒掯穷民狠员外，或是有人家典段匹，或是有人家当环钗，你则待加一倍放解。\n〔塞鸿秋〕快离了他这公孙弘东阁门桯外。再休想汉孔融北海开尊待。多谢你范尧夫肯付舟中麦。〔带云〕那员外呵，〔唱〕怎不学庞居士预放来生债。他他他则待掐破我三思台，他他他可便破我天灵盖，走走走早跳出了齐孙膑这一座连环寨。\n〔随煞〕别人家便当的一周年，下架容赎解。〔带云〕这员外呵！〔唱〕他巴到那五个月，还钱本利该，纳了利从头儿再取索，还了钱文书上厮混赖。似这等无仁义愚浊的却有财，偏着俺有德行聪明的嚼齑菜。这八个字穷通怎的排，则除非天打算日头儿轮到来。发背疔疮是你这富汉的灾，禁口伤寒着你这有钱的害。有一日贼打劫火烧了你院宅，有一日人连累抄没了旧钱债，恁时节合着锅无钱买米柴，忍饥饿街头做乞丐。这才是你家破人亡见天败。你还这等苦克瞒心骂我来，直待要犯了法遭了刑，你可便恁时节改！（同旦儿下）", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2423, "title": "楚昭公疏者下船", "author": "郑廷玉", "body": "〔寄生草〕从来道要得千军易，偏求一将难。闲时故把忠臣慢，差时不听忠臣谏，危时却要忠臣干。谁当这借吴雪恨伍将军，我则索求那扶周摄政姬公旦。\n〔幺篇〕你须想着归期急，休言他去路艰。止不过船临古渡垂杨岸，路经险道邛崃坂，小可如君骑羸马连云栈。你休辞山遥水远路三千，我专等你坚甲利刃那兵十万。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2424, "title": "〔仙吕〕寄生草", "author": "白朴", "body": "长醉后方何碍，不醒时有甚思。糟腌两个功名字，醅千古兴亡事，曲埋万丈虹霓志。不达时皆笑屈原非，但知音尽说陶潜是。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2425, "title": "〔仙吕〕醉中天", "author": "白朴", "body": "疑是杨妃在，怎脱马嵬灾？曾与明皇捧砚来。美脸风流杀。叵奈挥毫李白，觑着矫态，洒松烟点破桃腮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2426, "title": "〔中吕〕阳春曲", "author": "白朴", "body": "知荣知辱牢缄口，谁是谁非暗点头。诗书丛里且淹留。闲袖手，贫煞也风流。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2427, "title": "〔中吕〕阳春曲", "author": "白朴", "body": "张良辞汉全身计，范蠡归湖远害机。乐山乐水总相宜，君细推，今古几人知。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2428, "title": "〔中吕〕阳春曲", "author": "白朴", "body": "轻拈斑管书心事，细折银笺写恨词。可怜不惯害相思。则被你个肯字儿，迤逗我许多时。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2429, "title": "〔中吕〕阳春曲", "author": "白朴", "body": "从来好事天生俭，自古瓜儿苦后甜。奶娘催逼紧拘钳，甚是严，越间阻越情忺[2]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2430, "title": "〔越调〕天净沙", "author": "白朴", "body": "春山暖日和风，阑干楼阁帘栊，杨柳秋千院中。啼莺舞燕，小桥流水飞红。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2431, "title": "〔越调〕天净沙", "author": "白朴", "body": "云收雨过波添，楼高水冷瓜甜，绿树阴垂画檐。纱厨藤簟，玉人罗扇轻缣。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2432, "title": "〔越调〕天净沙", "author": "白朴", "body": "孤村落日残霞，轻烟老树寒鸦，一点飞鸿影下。青山绿水，白草红叶黄花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2433, "title": "〔越调〕天净沙", "author": "白朴", "body": "一声画角谯门，半庭新月黄昏。雪里山前水滨。竹篱茅舍，淡烟衰草孤村。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2434, "title": "〔双调〕驻马听", "author": "白朴", "body": "裂石穿云，玉管宜横清更洁。霜天沙漠，鹧鸪风里欲偏斜。凤凰台上暮云遮，梅花惊作黄昏雪。人静也，一声吹落江楼月。\n雪调冰弦，十指纤纤温更柔。林莺山溜[3]，夜深风雨落弦头。芦花岸上对兰舟，哀弦恰似愁人消瘦。泪盈眸，江州司马别离后。\n白雪阳春，一曲西风几断肠。花朝月夜，个中唯有杜韦娘。前声起彻绕危梁，后声并至银河上。韵悠扬，小楼一夜云来往。\n凤髻蟠空，袅娜腰肢温更柔。轻衫莲步，汉宫飞燕旧风流。谩催鼍鼓品梁州，鹧鸪飞起春罗袖。锦缠头，刘郎[4]错认风前柳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2435, "title": "〔双调〕沉醉东风", "author": "白朴", "body": "黄芦岸白渡口，绿杨堤红蓼滩头。虽无刎颈交，却有忘机友。点秋江白鹭沙鸥。傲杀人间万户侯，不识字烟波钓叟。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2436, "title": "〔双调〕庆东原", "author": "白朴", "body": "忘忧草[5]，含笑花[6]，劝君闻早冠宜挂。那里也能言陆贾？那里也良谋子牙？那里也豪气张华？千古是非心，一夕渔樵话。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2437, "title": "〔双调〕得胜乐", "author": "白朴", "body": "独自走，踏成道，空走了千遭万遭。肯不肯疾些儿通报，休直到教担搁得天明了。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2438, "title": "〔双调〕得胜乐", "author": "白朴", "body": "红日晚，残霞在，秋水共长天一色。寒雁儿呀呀的天外，怎生不捎带个字儿来？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2439, "title": "〔大石调〕青杏子", "author": "白朴", "body": "空外六花翻，被大风洒落千山。穷冬节物偏宜晚。冻凝沼沚，寒侵帐幕，冷湿阑干。\n〔归塞北〕貂裘客，嘉庆卷帘看。好景画图收不尽，好题诗句咏尤难。疑在玉壶间。\n〔好观音〕富贵人家应须惯，红炉暖不畏初寒。开宴邀宾列翠鬟，拼酡颜，畅饮休辞惮。\n〔幺〕劝酒佳人擎金盏，当歌者款撒香檀。歌罢喧喧笑语繁，夜将阑，画烛银光灿。\n〔结音[7]〕似觉筵间香风散，香风散非麝非兰；醉眼朦腾问小蛮[8]，多管是南轩蜡梅绽。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2440, "title": "〔双调〕乔木查", "author": "白朴", "body": "海棠初雨歇，杨柳轻烟惹，碧草茸茸铺四野。俄然回首处，乱红堆雪。\n〔幺〕恰春光也，梅子黄时节，映日榴花红似血。胡葵开满院，碎剪宫缬。\n〔挂搭沽序〕倏忽早庭梧坠，荷盖缺。院宇砧韵切，蝉声咽，露白霜结。水冷风高，长天雁字斜，秋香次第开彻。\n〔幺〕不觉的冰澌结，彤云布朔风凛冽。乱扑吟窗，谢女堪题，柳絮飞，玉砌长郊万里，粉污遥山千叠。\n去路赊，渔叟散，披蓑去，江上清绝。幽悄闲庭，舞榭歌楼酒力怯，人在水晶宫阙。\n〔幺〕岁华如流水，消磨尽自古豪杰。盖世功名总是空，方信花开易谢，始知人生多别。忆故园，谩叹嗟，旧游池馆，翻做了狐踪兔穴。休痴休呆，蜗角蝇头，名亲共利切。富贵似花上蝶，春宵梦说。\n〔尾〕少年枕上欢，杯中酒好天良夜，休辜负了锦堂风月。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2441, "title": "裴少俊墙头马上", "author": "白朴", "body": "〔鹊踏枝〕怎肯道负花期，惜芳菲，粉悴胭憔，他绿暗红稀。九十日春光如过隙，怕春归又早春归。\n〔寄生草〕柳暗青烟密，花残红雨飞。这人人和柳浑相类，花心吹得人心碎，柳眉不转蛾眉系。为甚西园陡恁景狼藉，正是东君不管人憔悴。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2442, "title": "裴少俊墙头马上", "author": "白朴", "body": "〔梅花酒〕他毒肠狠切，丈夫又软揣些些；相公又恶噷噷乖劣，夫人又叫丫丫似蝎蜇。你不去望夫石上变化身，筑坟台上立个碑碣。待教我谩，愁万缕，闷千叠，心似醉，意如呆，眼似瞎，手如瘸，轻拈掇，慢拿捻。\n〔收江南〕呀！叮珰掂做了两三截，有鸾胶[9]难续玉簪折，则他这夫妻儿女两离别。总是我业彻，也强如参辰[10]日月不交接。\n〔雁儿落〕似陷人坑千丈穴，胜滚浪千堆雪。恰才石头上损玉簪，又教我水底捞明月。\n〔得胜令〕冰弦断，便情绝；银瓶坠，永离别。把几口儿分两处，谁更待双轮碾四辙[11]。恋酒色淫邪，那犯七出[12]的应拼舍；享富贵豪奢，这守三从的谁似妾。\n〔沉醉东风〕梦惊破情缘万结，路迢遥烟水千叠。常言道有亲娘有后爷，无亲娘无疼热。他要送我到官司，逞尽豪杰。多谢你把一双幼女痴儿好觑者，我待信拖拖[13]去也。\n〔甜水令〕端端共重阳，他须是你裴家枝叶。孩儿也啼哭的似痴呆，这须是我子母情肠厮牵厮惹，兀的不痛杀人也！\n〔折桂令〕果然人生最苦是离别。方信道花发风筛，月满云遮；谁更敢倒凤颠鸾，撩蜂剔蝎，打草惊蛇。坏了咱墙头上传情简帖，拆开咱柳阴中莺燕蜂蝶。儿也咨嗟，女又拦截。既瓶坠簪折，咱义断恩绝。\n〔鸳鸯煞〕休把似残花败柳冤仇结，我与你生男长女填还彻，指望生则同衾，死则共穴。唱道题柱[14]胸襟，当垆[15]的志节，也是前世前缘，今生今业。少俊呵，与你干驾了会香车[16]，把这个没气性的文君送了也！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2443, "title": "唐明皇秋夜梧桐雨", "author": "白朴", "body": "〔忆王孙〕瑶阶月色晃疏棂，银烛秋光冷画屏，消遣此时此夜景；和月步闲庭，苔浸的凌波罗袜冷。\n〔胜葫芦〕露下天高夜气清，风掠得羽衣轻，香惹丁东环珮声，碧天澄净，银河光莹，只疑是身在玉蓬瀛。\n〔金盏儿〕他此夕把云路凤车乘，银汉鹊桥平。不甫能今夜成欢庆，枕边忽听晓鸡鸣，则早离愁情脉脉，别泪雨泠泠。五更长叹息，则是一夜短恩情。\n〔醉扶归〕暗想那织女分，牛郎命，虽不老，是长生；他阻隔银河信杳冥，经年度岁成孤另；你试向天宫打听，他决害了些相思病。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2444, "title": "唐明皇秋夜梧桐雨", "author": "白朴", "body": "〔快活三〕嘱咐你仙音院莫怠慢，道与你教坊司要迭办。把个太真妃扶在翠盘问，快结束，宜妆扮。\n〔鲍老儿〕双撮得泥金衫袖挽，把月殿里霓裳按。郑观音琵琶准备弹，早搭上鲛绡襻；贤王玉笛，花奴羯鼓，韵美声繁；寿宁锦瑟，梅妃玉箫，嘹亮循环。\n〔古鲍老〕屹剌剌撒开紫檀，黄翻绰向前手拈板。低低的叫声玉环；太真妃笑时花近眼。红牙箸趁五音击着梧桐按，嫩枝柯犹未干，更带着瑶琴音泛。卿呵，你则索出几点琼珠汗。\n〔红芍药〕腰鼓声干，罗袜弓弯，玉佩丁东响珊珊，即渐里舞云鬟。施呈你蜂腰细，燕体翻，作两袖香风拂散。寡人亲捧杯玉露甘寒，你可也莫得留残，拼着个醉醺醺直吃到夜静更阑。\n〔剔银灯〕止不过奏说边庭上造反，也合看空便，觑迟疾紧慢；等不的俺筵上笙歌散，可不气丕丕冒突天颜！那些个齐管仲郑子产，敢待做假忠孝龙逢比干？\n〔蔓菁菜〕险些儿慌杀你个周公旦。你道我因歌舞坏江山，你常好是占奸。早难道羽扇纶巾笑谈间，破强虏三十万。\n〔满庭芳〕你文武两班，空列些乌靴象简，金紫罗襕；内中没个英雄汉，扫荡尘寰。惯纵的个无徒禄山，没揣的撞过潼关，先败了哥舒翰。疑怪昨宵向晚，不见烽火报平安。\n〔普天乐〕恨无穷，愁无限，争奈仓卒之际，避不得蓦岭登山。銮驾迁，成都盼，更那堪浐水西飞雁，一声声送上雕鞍。伤心故园，西风渭水，落日长安。\n〔啄木儿尾〕端详了你上马娇，怎支吾蜀道难！替你愁那嵯峨峻岭连云栈，自来驱驰可惯，几程儿捱得过剑门关！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2445, "title": "唐明皇秋夜梧桐雨", "author": "白朴", "body": "〔双调·新水令〕五方旗招飐日边霞，冷清清半张鸾驾；鞭倦袅，镫慵踏，回首京华，一步步放不下。\n〔驻马听〕隐隐天涯，剩水残山五六搭；萧萧林下，坏垣破屋两三家。秦川远树雾昏花，灞桥衰柳风潇洒；煞不如碧窗纱，晨光闪烁鸳鸯瓦。\n〔殿前欢〕他是朵娇滴滴海棠花，怎做得闹荒荒亡国祸根芽？再不将曲弯弯远山眉儿画，乱松松云鬓堆鸦，怎下的碜磕磕马蹄儿脸上踏？则将细袅袅咽喉掐，早把条长搀搀素白练安排下。他那里一身受死，我痛煞煞独力难加。\n〔鸳鸯煞〕黄埃散漫悲风飒，碧云黯淡斜阳下；一程程水绿山青，一步步剑岭巴峡。唱道感叹情多，恓惶泪洒，早得升遐，休休却是今生罢。这个不得已的官家，哭上逍遥玉骢马。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2446, "title": "唐明皇秋夜梧桐雨", "author": "白朴", "body": "〔正宫·端正好〕自从幸西川还京兆，甚的是月夜花朝。这半年来白发添多少？怎打叠[17]愁容貌！\n〔幺篇〕瘦岩岩不避群臣笑。玉叉儿将画轴高挑，荔枝花果香檀桌，目觑了伤怀抱。\n〔滚绣球〕险些把我气冲倒，身谩靠，把太真妃放声高叫。叫不应，雨泪嚎咷。这待诏[18]手段高，画的来没半星儿差错。虽然是快染能描，画不出沉香亭畔回鸾舞，花萼楼前上马娇，一段儿妖娆。\n〔倘秀才〕妃子呵，常记得千秋节[19]华清宫宴乐，七夕会长生殿乞巧[20]，誓愿学连理枝比翼鸟，谁想你乘彩凤返丹霄，命夭！\n〔呆骨朵〕寡人待有心盖一座杨妃庙，争奈无权柄谢位辞朝。则俺这孤辰限难熬，更打着离恨天[21]最高。在生时同衾枕，不能勾死后也同棺椁。谁承望马嵬坡尘土中，可惜把一朵海棠花零落了。\n〔白鹤子〕那身离殿宇，信步下亭皋。见杨柳袅翠蓝丝，芙蓉拆胭脂萼。\n〔幺〕见芙蓉怀媚脸，遇杨柳忆纤腰。依旧的两般儿点缀上阳宫，他管一灵儿潇洒长安道。\n〔幺〕常记得碧梧桐阴下立，红牙箸手中敲；他笑整缕金衣，舞按霓裳乐。\n〔幺〕到如今翠盘中荒草满，芳树下暗香消；空对井梧阴，不见倾城貌。\n〔倘秀才〕本待闲散心追欢取乐，倒惹的感旧恨天荒地老。怏怏归来凤帏悄，甚法儿捱今宵，懊恼！\n〔芙蓉花〕淡氤氲串烟袅，昏惨剌银灯照；玉漏[22]迢迢，才是初更报。暗觑清霄，盼梦里他来到。却不道口是心苗，不住的频频叫。\n〔伴读书〕一会家心焦躁，四壁厢秋虫闹；忽见掀帘西风恶，遥观满地阴云罩。俺这里披衣闷把帏屏靠，业[23]眼难交。\n〔笑和尚〕原来是滴溜溜绕闲阶败叶飘，疏剌剌刷落叶被西风扫，忽鲁鲁风闪得银灯爆，厮琅琅鸣殿铎，扑簌簌动朱箔，吉丁当玉马儿向檐间闹。\n〔倘秀才〕闷打颏[24]和衣卧倒，软兀剌[25]方才睡着。\n忽见青衣走来报，道太真妃将寡人邀、宴乐。\n〔双鸳鸯〕斜[26]翠鸾翘，浑一似出浴的旧风标，映着云屏一半儿娇。好梦将成还惊觉，半襟情泪湿鲛绡。\n〔蛮姑儿〕懊恼，窨约[27]。惊我来的又不是楼头过雁，砌下寒蛩，檐前玉马，架上金鸡；是兀那窗儿外梧桐上雨潇潇。一声声洒残叶，一点点滴寒梢，会把愁人定虐[28]。\n〔滚绣球〕这雨呵，又不是救旱苗，润枯草，洒开花萼；谁望道秋雨如膏。向青翠条，碧玉梢，碎声儿剥，增百十倍歇和芭蕉。子管里珠连玉散飘千颗，平白地瀽[29]瓮翻盆下一宵，惹的人心焦。\n〔叨叨令〕一会价紧呵，似玉盘中万颗珍珠落；一会价响呵，似玳筵前几簇笙歌闹；一会价清呵，似翠岩头一派寒泉瀑；一会价猛呵，似绣旗下数面征鼙操。兀的不恼杀人也么哥！兀的不恼杀人也么哥！则被他诸般儿雨声相聒噪。\n〔倘秀才〕这雨一阵阵打梧桐叶凋，一点点滴人心碎了。枉着金井银床紧围绕，只好把泼枝叶做柴烧，锯倒。\n〔滚绣球〕长生殿那一宵，转回廊说誓约，不合对梧桐并肩斜靠，尽言词絮絮叨叨。沉香亭那一朝，按霓裳，舞六幺，红牙箸击成腔调，乱宫商闹闹炒炒。是兀那当时欢会栽排下，今日凄凉厮辏着，暗地量度。\n〔三煞〕润蒙蒙杨柳雨，凄凄院宇侵帘幕；细丝丝梅子雨，妆点江干[30]满楼阁；杏花雨红湿阑干，梨花雨玉容寂寞；荷花雨翠盖翩翻，豆花雨绿叶萧条：都不似你惊魂破梦，助恨添愁，彻夜连宵。莫不是水仙弄娇，蘸杨柳洒风飘。\n〔二煞〕似喷泉瑞兽临双沼，刷刷似食叶春蚕散满箔。乱洒琼阶，水传宫漏；飞上雕檐，酒滴新槽。直下的更残漏断，枕冷衾寒，烛灭香消。可知道夏天不觉，把高凤麦[31]来漂。\n〔黄钟煞〕顺西风低把纱窗哨，送寒气频将绣户敲。莫不是天故将人愁闷搅！度铃声响栈道，似花奴羯鼓调，如伯牙水仙操[32]。洗黄花，润篱落；渍苍苔，倒墙角；渲湖山，漱石窍；浸枯荷，溢池沼。沾残蝶粉渐消，洒流萤焰不着。绿窗前促织叫，声相近雁影高。催邻砧处处捣，助新凉分外早。斟量来这一宵，雨和人紧厮熬，伴铜壶点点敲，雨更多泪不少。雨湿寒梢，泪染龙袍，不肯相饶，共隔着一树梧桐直滴到晓。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2447, "title": "董秀英花月东墙记", "author": "白朴", "body": "〔仙吕·点绛唇〕万物乘春，落花成阵。莺声嫩，垂柳黄匀，越引起心间闷。\n〔混江龙〕三春时分，南园草木一时新；清和天气，淑景良辰。紫陌游人嫌日短，青闺素女[33]怕黄昏。寻芳俊士，拾翠[34]佳人；千红万紫，花柳分春。对韶光半响不开言，一天愁都结做心间恨，憔悴了玉肌金粉[35]，瘦损了窈窕精神。\n〔油葫芦〕杏朵桃枝似绛唇，柳絮纷，春光偏闪断肠人。微风细雨催花信，闲愁万种心间印。罗帏绣被寒孤，欲断魂，掩重门尽日无人问，情不遂越伤神。\n〔天下乐〕我只见杨柳横墙易得春，欢欣，可意人，一见了心下如何忍。送秋波眼角情，近东墙住左邻，觑了可憎才有就因。\n〔那吒令〕一见了那人，不由我断魂；思量起这人，有韩文柳文；他是个俏人，读齐论鲁论。想的咱不下怀，几时得成秦晋，甚何年一处温存？\n〔鹊踏枝〕好教我闷昏昏，泪纷纷，都只为美貌潘安，仁者能仁[36]。一会家心中自忖，谁与俺通个殷勤。\n〔寄生草〕怕的是黄昏后，入罗帏愁越狠。孤眠独枕教人闷，愁潘病沈[37]教人恨，行迟力顿教人困。似这等含情掩卧象牙床，几时得阳台上遇着多才俊。\n〔幺〕汉相如坐寒窗下，卓氏女配做婚。都只为我情你意相投顺，姻缘自把佳期问，郎才女貌皆相趁。你道是阻东墙难会碧纱厨，似俺这干荷叶那讨灵犀润。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2448, "title": "韩翠颦御水流红叶", "author": "白朴", "body": "〔柳青娘〕谁曾道是趁逐，天赐这场厮迤逗。看了这诗中意投，必定是个俊儒流。裁冰剪雪忒惯熟。若得来双双配偶，尽今生共结绸缪。则这去年前红叶上，红叶上把诗修。\n〔道合〕恰向今秋，恰向今秋，今秋园苑却闲游，恰相投。着俺着俺自僝僽，恁的恁的空遥受。同观的池上景清幽。细凝眸，自索受；使咱家，空迤逗。道那些那些合成就，那些那些合承受，天生落在咱家彀；若还见的迟些后，若不咱收，风力飕飕，趁着龙沟，荡荡悠悠，险些淹淹逐水，逐水向向向向向东流。\n〔耍孩儿〕往常我守椒房耽寂寞捱昏昼，今日个更添上关心症候。趁西风飘离了树梢头，送与我这一场闲闷闲愁。见了些翠裙凤翅伤秋扇，听了些绛帻鸡人报晓筹，年年池馆皆依旧。则俺这宫嫔年老，几时得叶落归秋。\n〔三煞〕题诗人长共短，有情人知他是好共丑！不明不暗因他瘦。心儿中作念何曾见，梦儿里相逢不厮偢，这姻缘空遥受。则俺那青鸾无信，红叶难酬。\n〔二煞〕弄诗章相戏逐，不良才歹事头，去年间写两句诗迤逗。暗欢喜空把他心中爱，虚烦恼胡遮我脸上羞。办着个至诚心将他候，看承做神珠玉颗，出入在凤阁龙楼。\n〔一煞〕做一个符牌儿[38]挑在鬓边，做一个面花儿贴在额头，绣一个香囊儿盛了揣着肉。他道是无情则许无情受，我正是好处将来好处收。自今夜黄昏后，安排着洞房花烛，绣幕香球。\n〔尾声〕稳坐着白象床，满斟着碧玉瓯；用鲛绡将红叶儿怀中搂，你与我递一盏儿新婚庆喜的酒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2449, "title": "〔中吕〕满庭芳", "author": "姚燧", "body": "天风海涛，昔人曾此，酒圣诗豪。我到此闲登眺，日远天高。山接水茫茫渺渺，水连天隐隐迢迢。供吟啸，功名事了，不待老僧招。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2450, "title": "〔中吕〕普天乐", "author": "姚燧", "body": "浙江秋，吴山夜。愁随潮去，恨与山叠。塞雁来，芙蓉谢。冷雨青灯读书舍，怕离别又早离别。今宵醉也，明朝去也，宁奈些些。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2451, "title": "〔中吕〕醉高歌", "author": "姚燧", "body": "十年燕月歌声，几点吴霜鬓影。西风吹起鲈鱼兴，已在桑榆暮景。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2452, "title": "〔中吕〕醉高歌", "author": "姚燧", "body": "岸边烟柳苍苍，江上寒波漾漾。《阳关》旧曲[1]低低唱，只恐行人断肠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2453, "title": "〔中吕〕醉高歌", "author": "姚燧", "body": "十年书剑长吁，一曲琵琶暗许。月明江上别湓浦，愁听兰舟夜雨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2454, "title": "〔中吕〕阳春曲", "author": "姚燧", "body": "笔头风月时时过，眼底儿曹渐渐多。有人问我事如何，人海阔，无日不风波。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2455, "title": "〔越调〕凭阑人", "author": "姚燧", "body": "马上墙头瞥见他，眼角眉尖拖逗咱。论文章他爱咱，睹妖娆咱爱他。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2456, "title": "〔越调〕凭阑人", "author": "姚燧", "body": "两处相思无计留，君上孤舟妾倚楼，这些兰叶舟，怎载如许愁？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2457, "title": "〔越调〕凭阑人", "author": "姚燧", "body": "欲寄君衣君不还，不寄君衣君又寒。寄与不寄间，妾身千万难。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2458, "title": "〔正宫〕黑漆弩", "author": "刘敏中", "body": "长巾阔领深村住，不识我唤作伧父。掩白沙翠竹柴门，听彻秋来夜雨。闲将得失思量，往事水流东去。便宜教画却凌烟，甚是功名了处？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2459, "title": "〔双调〕雁儿落过得胜令", "author": "庾天锡", "body": "从他绿鬓斑，欹枕白石烂。回头红日晚，满目青山矸[1]。翠立数峰寒，碧锁暮云间。媚景春前赏，晴岚雨后看。开颜，玉盏金波满。狼山，人生相会难。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2460, "title": "〔南吕〕四块玉", "author": "马致远", "body": "采药童，乘鸾客，怨感刘郎下天台。春风再到人何在？桃花又不见开，命薄的穷秀才，谁叫你回去来。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2461, "title": "〔南吕〕四块玉", "author": "马致远", "body": "送客时，秋江冷。商女琵琶断肠声。可知道司马和愁听。月又明，酒又酲，客乍醒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2462, "title": "〔南吕〕四块玉", "author": "马致远", "body": "睡海棠，春将晚，恨不得明皇掌中看。霓裳便是中原乱。不因这玉环，引起那禄山，怎知蜀道难！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2463, "title": "〔南吕〕四块玉", "author": "马致远", "body": "画不成，西施女，她本倾城却倾吴。高哉范蠡乘舟去。那里是泛五湖？若纶竿不钓鱼，便索他学楚大夫。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2464, "title": "〔南吕〕四块玉", "author": "马致远", "body": "暮雨迎，朝云送，暮雨朝云去无踪。襄王谩说阳台梦。云来也是空，雨来也是空，怎捱十二峰。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2465, "title": "〔南吕〕四块玉", "author": "马致远", "body": "两鬓皤，中年过，因甚区区苦张罗？人间宠辱都参破。种春风二顷田，远红尘千丈波，倒大来闲快活。\n带野花，携村酒，烦恼如何到心头。谁能跃马常食肉[1]？二顷田，一具[2]牛，饱后休。\n佐国心，拿云手[3]，命里无时莫刚求。随时过遣休生受。几叶绵，一片绸，暖后休。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2466, "title": "〔南吕〕金字经", "author": "马致远", "body": "夜来西风里，九天鹏鹗[4]飞。困煞中原一布衣[5]。悲，故人知未知？登楼意，恨无上天梯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2467, "title": "〔越调〕天净沙", "author": "马致远", "body": "枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2468, "title": "〔双调〕蟾宫曲", "author": "马致远", "body": "东篱半世蹉跎，竹里游亭，小宇婆娑。有个池塘，醒时渔笛，醉后渔歌。严子陵他应笑我，孟光台我待学他。笑我如何？倒大江湖，也避风波。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2469, "title": "〔双调〕蟾宫曲", "author": "马致远", "body": "咸阳百二山河，两字功名，几阵干戈。项废东吴，刘兴西蜀，梦说南柯。韩信功兀的般证果，蒯通言那里是风魔？成也萧何，败也萧何，醉了由他。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2470, "title": "〔双调〕清江引", "author": "马致远", "body": "樵夫觉来山月底，钓叟来寻觅。你把柴斧抛，我把渔船弃。寻取个稳便处闲坐地。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2471, "title": "〔双调〕清江引", "author": "马致远", "body": "绿蓑衣紫罗袍谁是主，两件儿都无济。便作钓鱼人，也在风波里。则不如寻个稳便处闲坐地。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2472, "title": "〔双调〕清江引", "author": "马致远", "body": "林泉隐居谁到此，有客清风至。会作山中相，不管人间事。争什么半张名利纸？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2473, "title": "〔双调〕清江引", "author": "马致远", "body": "东篱本是风月主。晚节园林趣。一枕葫芦架，几行垂杨树。\n是搭儿快活闲住处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2474, "title": "〔双调〕寿阳曲", "author": "马致远", "body": "花村外，草店西，晚霞明雨收天霁。四围山一竿残照里，锦屏风又添铺翠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2475, "title": "〔双调〕寿阳曲", "author": "马致远", "body": "夕阳下，酒旆闲，两三航未曾着岸。落花水香茅舍晚，断桥头卖鱼人散。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2476, "title": "〔双调〕寿阳曲", "author": "马致远", "body": "渔灯暗，客梦回，一声声滴人心碎。孤舟五更家万里，是离人几行情泪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2477, "title": "〔双调〕寿阳曲", "author": "马致远", "body": "云笼月，风弄铁，两般儿助人凄切。剔银灯欲将心事写，长吁气一声欲灭。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2478, "title": "〔双调〕寿阳曲", "author": "马致远", "body": "从别后，音信绝，薄情种害煞人也。逢一个见一个因话说，不信你耳轮儿不热。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2479, "title": "〔双调〕寿阳曲", "author": "马致远", "body": "心间事，说与他，动不动早言两罢。罢字儿碜可可你道是耍，我心里怕那不怕。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2480, "title": "〔双调〕湘妃怨", "author": "马致远", "body": "春风骄马五陵儿[6]，暖日西湖三月时，管弦触水莺花市，不知音不到此，宜歌宜酒宜诗。山过雨颦眉黛，柳拖烟堆鬓丝。可喜杀睡足的西施。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2481, "title": "〔双调〕湘妃怨", "author": "马致远", "body": "采莲湖上画船儿，垂钓滩头白鹭鸶。雨中楼阁烟中寺，笑王维作画师。蓬莱倒影参差。熏风来至，荷香净时。清洁煞避暑的西施。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2482, "title": "〔双调〕拨不断", "author": "马致远", "body": "菊花开，正归来。伴虎溪僧[7]鹤林友[8]龙山客[9]，似杜工部陶渊明李太白，有洞庭柑[10]东阳酒[11]西湖蟹[12]。哎！楚三闾[13]休怪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2483, "title": "〔双调〕拨不断", "author": "马致远", "body": "布衣中，问英雄，王图霸业成何用！禾黍高低六代宫，楸梧远近千官冢，一场恶梦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2484, "title": "〔双调〕夜行船", "author": "马致远", "body": "百岁光阴一梦蝶，重回首往事堪嗟。今日春来，明朝花谢。急罚盏夜阑[14]灯灭。\n〔乔木查〕想秦宫汉阙，都做了衰草牛羊野。不恁么[15]渔樵没话说。纵荒坟横断碑，不辨龙蛇[16]。\n〔庆宣和〕投至[17]狐踪与兔穴，多少豪杰。鼎足虽坚半腰里折。魏耶？晋耶？\n〔落梅风〕天教你富，莫太奢。没多时好天良夜。富家儿更做道你心似铁，争辜负了锦堂风月。\n〔风入松〕眼前红日又西斜，疾似下坡车。不争镜里添白雪，上床与鞋履相别。莫笑巢鸠计拙，葫芦提一向装呆。\n〔拨不断〕利名竭，是非绝。红尘不向门前惹，绿树偏宜屋角遮，青山正补墙头缺；更那堪竹篱茅舍。\n〔离亭宴煞〕蛩[18]吟罢一觉才宁贴[19]，鸡鸣时万事无休歇。何年是彻？看密匝匝蚁排兵，乱纷纷蜂酿蜜，急攘攘蝇争血。裴公绿野堂[20]，陶令白莲社[21]，爱秋来时那些：和露摘黄花，带霜分紫蟹，煮酒烧红叶。想人生有限杯，浑几个重阳节？人问我顽童记者：便北海[22]探吾来，道东篱醉了也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2485, "title": "〔般涉调〕哨遍", "author": "马致远", "body": "自唐晋倾亡之后，草书扫地无踪迹。天再生玉嵓翁，卓然独立根基。甚纲纪？胸怀洒落，意气聪明，才德相兼济。当日先生沉醉，脱巾露顶，裸袖揎衣；霜毫历历蘸寒泉，麝墨浓浓浸端溪；卷展霜缣，管握铜龙，赋歌赤壁。\n〔幺〕仔细看六书八法皆完备，舞凤戏翔鸾韵美。写长空两脚墨淋漓，洒东窗燕子衔泥。甚雄势！斩钉截铁，缠葛垂丝，似有风云气。据此清新绝妙，堪为家宝，可上金石。二王古法梦中存，怀素遗风尽真习。料想方今，寰宇四海，应无赛敌。\n〔五煞〕尽一轴，十数尺，从头一扫无凝滞。声清恰似蚕食叶，气勇浑如猊抉石。超先辈，消翰林一赞，高士留题。\n〔四〕写的来狂又古，颠又实，出乎其类拔乎萃。软如杨柳和风舞，硬似长空霹雳摧。真堪惜！沉沉着着，曲曲直直。\n〔三〕画一画如阵云，点一点似怪石，撇一撇如展鹍鹏翼。弯环怒偃乖龙骨，峻峭横拖巨蟒皮。特殊异，似神符堪咒，蚯蚓蟠泥。\n〔二〕写的来娇又嗔，怒又喜，千般丑恶十分媚。恶如山鬼拔枯树，媚似杨妃按羽衣。谁堪比？写黄庭换取，道士鹅归。\n〔一〕颜真卿苏子瞻，米元章黄鲁直，先贤墨迹君都得。满箱拍塞数千卷，文锦编挑满四围。通三昧，磨崖的本，画赞初碑。\n〔尾〕据划画难，字样奇，就中浑穿诸家体，四海纵横第一管笔。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2486, "title": "〔般涉调〕耍孩儿", "author": "马致远", "body": "近来时买得匹蒲梢骑，气命儿般看承爱惜。逐宵上草料数十番，喂饲得膘息胖肥。但有些秽污却早忙刷洗，微有些辛勤便下骑。有那等无知辈，出言要借，对面难推。\n〔七煞〕懒设设牵下槽，意迟迟背后随，气忿忿懒把鞍来鞴。我沉吟了半晌语不语，不晓事颓人知不知？他又不是不精细，道不得“他人弓莫挽，他人马休骑”。\n〔六煞〕不骑呵西棚下凉处拴，骑时节拣地皮平处骑。将青青嫩草频频的喂。歇时节肚带松松放，怕坐的困尻包儿款款移。勤觑着鞍和辔，牢踏着宝镫，前口儿休提。\n〔五煞〕饥时节喂些草，渴时节饮些水。着皮肤休使粗毡屈，三山骨休使鞭来打，砖瓦上休教稳着蹄。有口话你明明的记：饱时休走，饮了休驰。\n〔四煞〕抛粪时教干处抛，尿绰时教净处尿。拴时节拣个牢固桩橛上系。路途上休要踏砖块，过水处不教践起泥。这马知人义，似云长赤兔，如益德乌骓。\n〔三煞〕有汗时休去檐下拴，渲时休教侵着颓。软煮料草铡底细。上坡时款把身来耸，下坡时休教走得疾。休道人忒寒碎。休教鞭着马眼，休教鞭擦损毛衣。\n〔二煞〕不借时恶了弟兄，不借时反了面皮。马儿行嘱咐叮咛记：鞍心马户将伊打，刷子去刀莫作疑。则叹的一声长吁气，哀哀怨怨，切切悲悲。\n〔一煞〕早晨间借与他，日平西盼望你，倚门专等来家内。柔肠寸寸因他断，侧耳频频听你嘶。道一声“好去”，早两泪双垂。\n〔尾〕没道理没道理，忒下的忒下的。恰才说来的话君专记，一口气不违借与了你。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2487, "title": "江州司马青衫泪", "author": "马致远", "body": "〔叨叨令〕我这两日上西楼盼望三十遍，空存得故人书，不见离人面。听的行雁来也我立尽吹箫院，闻得声马嘶也目断垂杨线。相公呵，你元来死了也么哥，你元来死了也么哥。从今后越思量越想的冤魂儿现。\n〔醉太平·二煞〕少不的听那惊回客梦黄昏犬，聒碎人心落日蝉。止不过临万顷苍波，落几双白鹭；对千里青山，闻两岸啼猿。愁的是三秋雁字，一夏蚊雷，二月芦烟。不见他青灯黄卷，却索共渔火对愁眠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2488, "title": "半夜雷轰荐福碑", "author": "马致远", "body": "〔寄生草〕想前贤语，总是虚。可不道书中车马多如簇，可不道书中自有千钟粟，可不道书中有女颜如玉，则见他白衣便得一个状元郎，那里是绿袍儿赚了书生处。\n〔幺篇〕这壁拦住贤路，那壁又挡住仕途。如今这越聪明越受聪明苦，越痴呆越享了痴呆福，越糊突越有了糊突富。则这有银的陶令不休官，无钱的子张学干禄。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2489, "title": "半夜雷轰荐福碑", "author": "马致远", "body": "〔红绣鞋〕本待看金色清凉境界，霎时间都做了黄公水墨楼台。多管是角木蛟当直圣亲差，把黄河移得至，和东海取将来，抵多少长江风送客。\n〔上小楼〕这雨水平常有来，不似今番特煞！这场大雨，非为秋霖，不是甘泽；遮莫是箭杆雨、过云雨，可更淋漓辰霭。看你怎生飘麦。\n〔幺篇〕振乾坤雷鼓鸣，走金蛇电影开。他那里撼岭巴山，搅海翻江，倒树摧崖。这孽畜，更做你这般神通广大，也不合佛顶上大惊小怪。\n〔满庭芳〕粉碎了阎浮世界，今年是九龙治水，少不的珠露成灾，将一统家丈三碑霹雳做了石头块，这的则好与妇女捶帛。把似你便逞头角欺负俺这秀才，把似你便有爪牙近取那澹台，周处也曾除三害！我若得那魏徵剑来，我可也敢驱上斩龙台！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2490, "title": "太华山陈抟高卧", "author": "马致远", "body": "〔叨叨令〕向那华山中已觅下终焉计，怎生都堂内才看旁州例。议公事枉损了元阳气，理朝纲怕搅了安眠睡。贫道做不的官也么哥，做不的官也么哥。不要紫罗袍只乞黄绸被。\n〔倘秀才〕我但睡呵十万根更筹转刻，七八瓮铜壶漏水，恨不的生扭死窗前报晓鸡。休想我惜花春起早，爱月夜眠迟，这般的道理。\n〔滚绣球〕贫道呵爱穿的蔀落衣，爱吃的藜藿食。睡时节幕天席地，黑喽喽鼻息如雷、二三年唤不起。若在那，省部里，敢每日画不着卯历。有句话对圣主先题，贫道呵贪闲身外全无事，除睡人间总不知。空教人贴眼舒眉。\n〔倘秀才〕陛下道君子周而不比。贫道呵小人穷斯滥矣。俺须索志于道、依于仁、据于德。本待用贤退不肖；怎倒做举枉错诸直。更是不宜。\n〔滚绣球〕三千贯、二千石。一品官、二品职。只落的故纸上两行史记。无过是重裀卧、列鼎而食。虽然道臣事君以忠、君使臣以礼。哎！这便是死无葬身之地。敢向那云阳市血染朝衣。本居林下绝名利。自不合刬下山来惹是非。不如归去来兮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2491, "title": "破幽梦孤雁汉宫秋", "author": "马致远", "body": "〔混江龙〕料必他珠帘不挂，望昭阳一步一天涯。疑了些无风竹影，恨了些有月窗纱。他每见弦管声中巡玉辇，恰便似斗牛星畔盼浮槎。（旦做弹科）（驾云）是哪里弹的琵琶响？（内官云）是。（正末唱）是谁人偷弹一曲，写出嗟呀？（内官云）快报去接驾。（驾云）不要。（唱）莫便要忙传圣旨，报与他家。我则怕乍蒙恩把不定心儿怕，惊起宫槐宿鸟，庭树栖鸦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2492, "title": "破幽梦孤雁汉宫秋", "author": "马致远", "body": "〔牧羊关〕兴废从来有，干戈不肯休。可不食君禄，命悬君手。太平时卖你宰相功劳，有事处把俺佳人递流。你们干请了皇家俸，着甚的分破帝王忧？那壁厢锁树[23]的怕弯着手，这壁厢攀栏[24]的怕破了头。\n〔贺新郎〕俺又不曾彻青霄高盖起摘星楼。不说他伊尹扶汤，则说那武王伐纣。有一朝身到黄泉后，若和他留侯留侯厮遘，你可也羞那不羞？你卧重裀，食列鼎，乘肥马，衣轻裘。你须见舞春风嫩柳宫腰瘦，怎下的教他环珮影摇青冢月，琵琶声断黑江秋！\n〔斗虾蟆〕当日个谁展英雄手，能枭项羽头，把江山属俺炎刘？全亏韩元帅九里山前战斗，十大功劳成就。恁也丹墀里头，枉被金章紫绶；恁也朱门里头，都宠着歌衫舞袖。恐怕边关透漏，殃及家人奔骤。似箭穿着雁口，没个人敢咳嗽。吾当僝僽[25]，他也他也红妆年幼，无人搭救。昭君共你每有甚么杀父母冤仇？休休，少不的满朝中都做了毛延寿！我呵，空掌着文武三千队，中原四百州；只待要割鸿沟。陡恁[26]的千军易得，一将难求。\n〔哭皇天〕你有甚事疾忙奏，俺无那鼎镬边滚热油。我道你文臣安社稷，武将定戈矛；你只会文武班头，山呼万岁，舞蹈扬尘，道那声诚惶顿首。如今阳关路上，昭君出塞；当日未央宫里，女主[27]垂旒。文武每，我不信你敢差排吕太后。枉以后，龙争虎斗，都是俺鸾交凤友。\n〔乌夜啼〕今日嫁单于，宰相休生受。早则俺汉明妃有国难投。它那里黄云不出青山岫。投至两处凝眸，盼得一雁横秋。单注着寡人今岁揽闲愁。王嫱这运添憔瘦，翠羽冠，香罗绶，都做了锦蒙头暖帽，珠络缝貂裘。\n〔三煞〕我则恨那忘恩咬主贼禽兽，怎生不画在凌烟阁上头？紫台行都是俺手里的众公侯，有那桩儿不共卿谋？那件儿不依卿奏？争忍教第一夜梦迤逗！从今后不见长安望北斗，生扭做织女牵牛。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2493, "title": "破幽梦孤雁汉宫秋", "author": "马致远", "body": "〔步步娇〕您将那一曲阳关休轻放，俺咫尺如天样，慢慢的捧玉觞，朕本意待尊前捱些时光，且休问劣了宫商[28]，您则与我半句儿俄延着唱。\n〔殿前欢〕则甚么留下舞衣裳，被西风吹散旧时香。我委实怕宫车再过青苔巷，猛到椒房[29]，那一会想菱花镜里妆，风流相，兜的[30]又横心上。看今日昭君出塞，几时似苏武还乡？\n〔七弟兄〕说甚么大王、不当、恋王嫱，兀良，怎禁他临去也回头望！那堪这散风雪旌节影悠扬，动关山鼓角声悲壮。\n〔梅花酒〕呀！俺向着这迥野悲凉，草已添黄，兔早迎霜。犬褪得毛苍，人搠起缨枪，马负着行装，车运着糇粮[31]，打猎起围场。他他他，伤心辞汉主；我我我，携手上河梁[32]。他部从入穷荒，我銮舆返咸阳。返咸阳，过宫墙；过宫墙，绕回廊；绕回廊，近椒房；近椒房，月昏黄；月昏黄，夜生凉；夜生凉，泣寒螀；泣寒螀，绿纱窗；绿纱窗，不思量！\n〔收江南〕呀！不思量除是铁心肠！铁心肠也愁泪滴千行。美人图今夜挂昭阳，我那里供养，便是我高烧银烛照红妆。\n〔鸳鸯煞〕我煞大臣行说一个推辞谎，又则怕笔尖儿那火编修讲。不见他花朵儿精神，怎趁那草地里风光？唱道伫立多时，徘徊半晌，猛听的塞雁南翔，呀呀的声嘹亮，却原来满目牛羊，是兀那载离恨的毡车半坡里响。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2494, "title": "破幽梦孤雁汉宫秋", "author": "马致远", "body": "〔白鹤子〕多管是春秋高，筋力短；莫不是食水少，骨毛轻？待去后，愁江南网罗宽；待向前，怕塞北雕弓硬。\n〔幺篇〕伤感似替昭君思汉主，哀怨似作薤露[33]哭田横[34]，凄怆似和半夜楚歌声，悲切似唱三叠阳关令。\n〔十二月〕休道是咱家动情，你宰相每也生憎。不比那雕梁燕语，不比那锦树莺鸣。汉昭君离乡背井，知他在何处愁听？\n〔尧民歌〕呀呀的飞过蓼花汀，孤雁儿不离了凤凰城。画檐间铁马响丁丁，宝殿中御榻冷清清，寒也波更，萧萧落叶声，烛暗长门静。\n〔随煞〕一声儿绕汉宫，一声儿寄渭城，暗添人白发成衰病，直恁的吾当[35]可也劝不省。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2495, "title": "吕洞宾三醉岳阳楼", "author": "马致远", "body": "〔混江龙〕梭头琴样，助吟毫清彻看书窗，恰行过一区道院，几处斋堂。竹几暗添龙尾润，布袍常带麝脐香，早来到洞庭湖畔，百尺楼傍，端的是凭凌云汉，映带潇湘。俺这里蹑飞梯，凝望眼，离人间似有三千丈，则好高欢避暑，王粲思乡。\n〔油葫芦〕俺只见十二阑干接上苍，我则怕惊着玉皇，谁着你直侵北斗建槽坊？！写道是岳阳楼形胜偏雄壮，更压着你洞庭春好酒新炊荡。翠巍巍当着楚山，浪淘淘临着汉江。正菊花秋不醉倒陶元亮，怎发付团脐蟹一包黄。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2496, "title": "马丹阳三度任风子", "author": "马致远", "body": "〔斗鹌鹑〕大古里万水千山[36]，卖弄你三从四德。我漾起拳头，他揣与我个面皮。休，休，休！今世里饶人不是痴。咱两个善厮离。我来到林下山间，再谁想星前月底。\n〔普天乐〕出虎狼丛，拜辞了鸳鸯会。这的中做布碾，好做铺持。急切里无片纸。将这的铺在田地。就着这水渠中，插手在青泥内，与你个泥手模便当休离。我和你恩断义绝，花残月缺，再谁恋锦被罗帏。\n〔上小楼〕你道是夫唱妇随，夫荣妻贵。我从那早起晚息，择菜挑荠，打水浇畦。你向这里撒。休寻自缢。菜园中葱[37]人脆。\n〔满庭芳〕这担轻如你底。你道我担荆筐受苦，强如你火院便宜。两头来往搬兴废。休想我担是担非。虽不如张子房休官罢职，我待学陶渊明归去来兮。咱休罪，今朝厮离。由你做张郎妇李郎妻。\n〔耍孩儿〕想人生六合乾坤内，活到七十都能有几。人生幻化比芳菲。人愁老花怕春归。人贫人富无多限，花开花落能有几。咱想着人子（只）有三寸元阳气。贯串着凡胎浊骨，使作那肉眼愚眉。\n〔六煞〕第一来女色再不侵，第二来把香醪再不吃，堆金积玉成何济。人生一世心都爱，谁为三般事不迷。跳出红尘内，寻泛锦槎天浪，烂斧柯仙棋。\n〔三煞〕一投匆匆月出东，却早厌厌日落西。秋鸿塞雁相催逼。玉天仙妻子权休罪。魔合罗孩儿谁是谁。我见他揾不迭腮边泪。问甚么水胡花性命，爱惜你花朵儿身起。\n〔收尾〕由你死共死、活后活，我二则二、一则一。你道是娇妻、幼子和兄弟。我跳出七代，先灵稽首也劝不的！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2497, "title": "邯郸道省悟黄粱梦", "author": "马致远等", "body": "〔金盏儿〕上昆仑，摘星辰，觑东洋海则是一掬寒泉滚，泰山一捻细微尘。天高三二寸，地厚一鱼鳞。抬头天外觑，无我一般人。\n〔后庭花〕我驱的是六丁六甲神，七星七曜君。食紫芝草千年寿，看碧桃花几度春。常则是醉醺醺，高谈阔论，来往的尽是天上人。\n〔醉中天〕俺那里自酦村醪嫩，自折野花新，独对青山酒一尊。闲将那朱顶仙鹤引，醉归去松阴满身。泠然风韵，铁笛声吹断云根。\n〔金盏儿〕俺那里地无尘，草长春，四时花发常娇嫩，更那翠屏般山色对柴门。雨滋棕叶润，露养药苗新。听野猿啼古树，看流水绕孤村。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2498, "title": "邯郸道省悟黄粱梦", "author": "马致远等", "body": "〔大石调·六国朝〕风吹羊角，雪剪鹅毛，飞六出，海山白，冻一壶，天地老。便有丹青巧，画笔难描。俺这里遥望千山表，是谁将粉黛扫？幽窗下寒敲竹叶，前村里冷压梅梢。撩乱野云飞，微茫江树杳。\n〔归塞北〕为甚春归早？既不沙可怎生蝶翅舞飘飘。梅蕊粉填合长安道，柳花绵迷却灞陵桥，山馆酒旗遥。\n〔初问口〕想那捕鱼叟蓑笠纶竿，他向那寒潭独钓。和俺这采樵人迷却归来道。则见冻雀又飞，寒鸦又噪，古木林中蓦听的山猿叫。\n〔怨别离〕园林无处不萧条，春归也犹未觉。满地梨花无人扫。寒料峭，遥望见一点青山兀良却又早不见了。\n〔归塞北〕白云岛，则听得孤鬼吼荒郊。九天女鼓风驱造化，六丁神挥剑斩长蛟。既不沙可怎生就地卷风涛。\n〔幺篇〕孤村晓，稚子道犹自月明高。青女剪冰寒不散，黑云喷雨冻难消，无处觅渔樵。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2499, "title": "邯郸道省悟黄粱梦", "author": "马致远等", "body": "〔倘秀才〕你早则省得浮世风灯石火，再休恋儿女神珠玉颗。咱人百岁光阴有几何？端的日月去，似撺梭，想你那受过的坎坷。\n〔滚绣球〕你梦儿里见了么，心儿里省得么？这一觉睡早经了二十年兵火。觉来也依旧存活，瓢古[38]自放在灶窝，驴古[39]自映着树科。睡朦胧无多一和，半霎儿改变了山河。兀的是黄粱未熟荣华尽，世态才知鬓发皤，早则人事蹉跎。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2500, "title": "〔仙吕〕后庭花", "author": "赵孟頫", "body": "清溪一叶舟，芙蓉两岸秋。采菱谁家女，歌声起暮鸥。乱云愁，满头风雨，戴荷叶归去休。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2501, "title": "〔中吕〕十二月过尧民歌", "author": "王实甫", "body": "自别后遥山隐隐，更那堪远水粼粼。见杨柳飞绵[1]滚滚，对桃花醉脸醺醺。透内阁香风阵阵，掩重门暮雨纷纷。　　怕黄昏忽地又黄昏，不销魂怎地不销魂？新啼痕压旧啼痕，断肠人忆断肠人！今春，香肌瘦几分，搂带宽三寸。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2502, "title": "〔商调〕集贤宾", "author": "王实甫", "body": "拈苍髯笑擎冬夜酒，人事远老怀幽。志难酬知机的王粲，梦无凭见景的庄周。免饥寒桑麻愿足，毕婚嫁儿女心休。百年期六分甘到手，数支干周遍又从头。笑频因酒醉，烛换为诗留。\n〔逍遥乐〕江梅并瘦，槛竹同清，岩松共久。身外何求？笑时人鹤背扬州！明月清风老致优，对绿水青山依旧：曲肱北牖，舒啸东皋，放眼西楼。\n〔金菊香〕想着那红尘黄阁昔年羞，到如今白发青衫此地游。乐桑榆酬诗共酒，酒侣诗俦，诗潦倒酒风流。\n〔醋葫芦〕到春来日迟迟兰蕙芳，暖溶溶桃杏稠。闹春光莺燕语啾啾，自焚香下帘清坐久。闲把那丝桐一奏，涤尘襟消尽了古今愁。\n〔幺篇〕到夏来锁松阴竹坞亭，载荷香柳岸舟。有鲜鱼鲜藕客堪留，放白鹤远邀云外叟。展楸枰消磨长昼，较亏成一笑两奁收。\n〔幺篇〕到秋来醉丹霞树饱霜，绽金钱菊弄秋。半山残照挂城头，老菱香蟹肥堪佐酒。正值着登高时候，染霜毫乘醉赋归休。\n〔幺篇〕到冬来搅清酣鸡语繁，漾茅檐日影稠。压梅梢晴雪带花留，倚蒲团唤童重荡酒。看万里冰绡染就，有王维妙手总难酬。\n〔梧叶儿〕退一步乾坤大，饶一着万虑休。怕狼虎恶图谋。遇事休开口，逢人只点头。见香饵莫吞钩，高抄起经纶大手。\n〔后庭花〕住一间蔽风霜茅草丘，穿一领卧苔莎粗布裘。捏几首写怀抱歪诗句，吃几杯放心胸村醪酒。这潇洒傲王侯，且喜的身登中寿。有微资堪赡赒，有亭园堪纵游。保天和自养修，放形骸任自由。把尘缘一笔勾，再休题名利友。\n〔青哥儿〕呀！闲处叹蜂喧蜂喧蚁斗，静中笑蝶讪蝶讪莺羞。你便有快马，难熬我这钝炕头。见如今蔬果初熟，浊酒新[2]，豆粥[3]香浮。大叫高讴，睁着眼张着口尽胡诌，这快活谁能够！\n〔尾声〕醉时节盘陀石上眠，饱时节婆娑松下走，困时节布衲里睡齁齁。偶乘闲细将玄奥剖，把至理一星星参透，却原来括乾坤物我总浮沤。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2503, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔油葫芦〕九曲风涛何处显，只除是此地偏。这河带齐梁，分秦晋，隘幽燕。雪浪拍长空，天际秋云卷；竹索缆浮桥，水上苍龙偃。东西溃九州，南北串百川。归舟紧不紧如何见？恰便似弩箭乍离弦。\n〔天下乐〕只疑是银河落九天；渊泉，云外悬，入东洋不离此径穿。滋洛阳千种花，润梁园万顷田，也曾泛浮槎到日月边。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2504, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔元和令〕颠不剌的见了万千，似这般可喜娘的庞儿罕曾见。则着人眼花撩乱口难言，魂灵儿飞在半天。他那里尽人调戏，着香肩，只将花笑拈。\n〔上马娇〕这的是兜率宫，休猜做了离恨天。呀，谁想着寺里遇神仙！我见他宜嗔宜喜春风面，偏、宜贴翠花钿。\n〔胜葫芦〕则见他宫样眉儿新月偃，斜侵入鬓云边。未语人前先腼腆，樱桃红绽，玉粳白露，半晌恰方言。\n〔幺篇〕恰便似呖呖莺声花外啭，行一步可人怜。解舞腰肢娇又软，千般袅娜，万般旖旎，似垂柳晚风前。\n〔后庭花〕若不是衬残红，芳径软，怎显得步香尘底样儿浅。且休题眼角儿留情处，则这脚踪儿将心事传。慢俄延，投至到栊门儿前面，刚那了一步远。刚刚的打个照面，风魔了张解元。似神仙归洞天，空余下杨柳烟，只闻得鸟雀喧。\n〔柳叶儿〕呀，门掩着梨花深院，粉墙儿高似青天。恨天，天不与人行方便，好着我难消遣，端的是怎留连。小姐呵，则被兀你的不引了人意马心猿？\n〔寄生草〕兰麝香仍在，佩环声渐远。东风摇曳垂杨线，游丝牵惹桃花片，珠帘掩映芙蓉面，你道河中开府相公家，我道是南海水月观音现。\n〔赚煞〕饿眼望将穿，馋口涎空咽，空着我透骨髓相思病染，怎当他临去秋波那一转！休道是小生，便是铁石人也意惹情牵。近庭轩，花柳争妍，日午当庭塔影圆。春光在眼前，争奈玉人不见，将一座梵王宫疑是武陵源。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2505, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔耍孩儿〕当初那巫山远隔如天样，听说罢又在巫山那厢。业身躯[4]虽是立在回廊，魂灵儿已在他行。本待要安排心事传幽客，我只怕漏泄春光与乃堂。夫人怕女孩儿春心荡，怪黄莺儿作对，怨粉蝶儿成双。\n〔二煞〕院宇深，枕簟凉，一灯孤影摇书幌。纵然酬得今生志，着甚支吾[5]此夜长。睡不着如翻掌，少可有一万声长吁短叹，五千遍捣枕捶床。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2506, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔越调·斗鹌鹑〕玉宇无尘，银河泻影；月色横空，花阴满庭；罗袂生寒，芳心自警。侧着耳朵儿听，蹑着脚步儿行；悄悄冥冥，潜潜等等。\n〔拙鲁速〕对着盏碧荧荧短檠灯，倚着扇冷清清旧帏屏。灯儿又不明，梦儿又不成；窗儿外淅零零的风儿透疏棂，忒楞楞的纸条儿鸣；枕头儿上孤零，被窝儿里寂静。你便是铁石人，铁石人也动情。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2507, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔混江龙〕落红成阵，风飘万点正愁人。池塘梦晓，阑槛辞春；蝶粉轻沾飞絮雪，燕泥香惹落花尘；系春心情短柳丝长，隔花阴人远天涯近。香消了六朝金粉，清减了三楚精神。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2508, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔正宫·端正好〕不念法华经，不礼梁皇忏[6]，[7]了僧伽帽，袒下我这偏衫。杀人心逗起英雄胆，两只手将乌龙尾钢椽揝[8]。\n〔叨叨令〕浮沙羹、宽片粉[9]添些杂糁，酸黄齑、烂豆腐休调啖，万余斤黑面从教暗，我将这五千人做一顿馒头馅。是必休误了也么哥！休误了也么哥！包残余肉把青盐蘸。\n〔滚绣球〕我经文也不会谈，逃禅[10]也懒去参；戒刀头近新来钢蘸，铁棒上无半星儿土渍尘缄。别的都僧不僧、俗不俗，女不女、男不男，只会斋得饱也只向那僧房中胡渰[11]，那里怕焚烧了兜率伽蓝。则为那善文能武人千里，凭着这济困扶危书一缄，有勇无惭。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2509, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔上小楼〕“请”字儿不曾出声，“去”字儿连忙答应；可早莺莺根前，“姐姐”呼之，喏喏连声。秀才每闻道“请”，恰便似听将军严令，和他那五脏神[12]愿随鞭镫。\n〔满庭芳〕来回顾影，文魔秀士，风欠酸丁。下工夫将额颅十分挣[13]，迟和疾擦倒苍蝇[14]，光油油耀花人眼睛，酸溜溜螫得人牙疼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2510, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔得胜令〕谁承望这即即世世老婆婆，着莺莺做妹妹拜哥哥。白茫茫溢起蓝桥水，赤邓邓点着祆庙火。碧澄澄清波，扑剌剌将比目鱼分破；急攘攘因何，扢搭地把双眉锁纳合。\n〔折桂令〕他其实咽不下玉液金波。谁承望月底西厢，变做了梦里南柯。泪眼偷淹，酩子里揾湿香罗。他那里眼倦开软瘫做一垛；我这里手难抬称不起肩窝。病染沉疴，断然难活。则被你送了人呵，当甚么喽啰。\n〔离亭宴带歇指煞〕从今后玉容寂寞梨花朵，胭脂浅淡樱桃颗，这相思何时是可？昏邓邓黑海来深，白茫茫陆地来厚，碧悠悠青天来阔；太行山般高仰望，东洋海般深思渴。毒害的恁么。俺娘呵，将颤巍巍双头花蕊搓，香馥馥同心缕带割，长搀搀连理琼枝挫。白头娘不负荷，青春女成担搁，将俺那锦片也似前程蹬脱。俺娘把甜句儿落空了他，虚名儿误赚了我。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2511, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔小桃红〕人间看波。玉容深锁绣帏中，怕有人搬弄。想嫦娥，西没东生有谁共？怨天公，裴航不作游仙梦。这云似我罗帏数重，只恐怕嫦娥心动，因此上围住广寒宫。\n〔天净沙〕莫不是步摇得宝髻玲珑？莫不是裙拖得环珮玎？莫不是铁马儿檐前骤风？莫不是金钩双控，吉丁当敲响帘栊？\n〔调笑令〕莫不是梵王宫，夜撞钟？莫不是疏竹潇潇曲槛中？莫不是牙尺剪刀声相送？莫不是漏声长滴响壶铜？潜身再听在墙角东，原来是近西厢理结丝桐。\n〔秃厮儿〕其声壮，似铁骑刀枪冗冗；其声幽，似落花流水溶溶；其声高，似风清月朗鹤唳空；其声低，似听儿女语，小窗中，喁喁。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2512, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔圣药王〕果若你有心，他有心，昨日秋千院宇夜深沉；花有阴，月有阴，“春宵一刻抵千金”，何须“诗对会家吟”？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2513, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔越调·斗鹌鹑〕则着你夜去明来，倒有个天长地久；不争你握雨携云，常使我提心在口。则合带月披星，谁着你停眠整宿？老夫人心数多，情性；使不着我巧语花言，将没做有。\n〔紫花儿序〕老夫人猜那穷酸做了新婿，小姐做了娇妻，这小贱人做了牵头。俺小姐这些时春山低翠，秋水凝眸。别样的都休，试把你裙带儿拴，纽门儿扣，比着你旧时肥瘦，出落得精神，别样的风流。\n〔金蕉叶〕我着你但去处行监坐守，谁着你迤逗[15]的胡行乱走？若问着此一节呵如何诉休？你便索与他个“知情”的犯由[16]。\n〔调笑令〕你绣帏里效绸缪，倒凤颠鸾百事有。我在窗儿外几曾轻咳嗽，立苍苔将绣鞋儿冰透。今日个嫩皮肤倒将粗棍抽，姐姐呵，俺这通殷勤的着甚来由？\n〔鬼三台〕夜坐时停了针绣，共姐姐闲穷究，说张生哥哥病久。咱两个背着夫人，向书房问候。（夫人云）问候呵，他说甚么？（红云）他说来，道“老夫人事已休，将恩变为仇，着小生半途喜变做忧”。他道：“红娘你且先行，教小姐权时落后。”\n〔秃厮儿〕我则道神针法灸，谁承望燕侣莺俦。他两个经今月余则是一处宿，何须你一一问缘由？\n〔圣药王〕他每不识忧，不识愁，一双心意两相投。夫人得好休，便好休，这其间何必苦追求！常言道“女大不中留[17]”。\n〔麻郎儿〕秀才是文章魁首，姐姐是仕女班头；一个通彻三教九流，一个晓尽描鸾刺绣。\n〔幺篇〕世有、便休、罢手[18]，大恩人怎做敌头？起白马将军故友，斩飞虎叛贼草寇。\n〔络丝娘〕不争和张解元参辰卯酉，便是与崔相国出乖弄丑。到底干连着自己骨肉，夫人索穷究。\n〔小桃红〕当日个月明才上柳梢头，却早人约黄昏后。羞得我脑背后将牙儿衬着衫儿袖。猛凝眸，看时节则见鞋底尖儿瘦。一个恣情的不休，一个哑声儿厮耨。呸！那其间可怎生不害半星儿羞？\n〔幺篇〕既然泄漏怎干休？是我相投首[19]。俺家里陪酒陪茶倒就。你休愁，何须约定通媒媾？我弃了部署不收，你原来“苗而不秀”。呸！你是个银样镴[20]枪头。\n〔东原乐〕相思事，一笔勾，早则展放从前眉儿皱，美爱幽欢恰动头。既能够，张生，你觑兀的般可喜娘庞儿也要人消受。\n〔收尾〕来时节画堂箫鼓鸣春昼，列着一对儿鸾交凤友。那其间才受你说媒红，方吃你谢亲酒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2514, "title": "崔莺莺待月西厢记", "author": "王实甫", "body": "〔正宫·端正好〕碧云天，黄花地，西风紧，北雁南飞。晓来谁染霜林醉？总是离人泪。\n〔滚绣球〕恨相见得迟，怨归去得疾。柳丝长玉骢难系，恨不倩疏林挂住斜晖。马儿迍迍[21]的行，车儿快快的随，却告了相思回避，破题儿[22]又早别离。听得道一声“去也”，松了金钏；遥望见十里长亭，减了玉肌。此恨谁知！\n〔叨叨令〕见安排着车儿、马儿，不由人熬熬煎煎的气；有甚么心情花儿、靥儿，打扮得娇娇滴滴的媚；准备着被儿、枕儿，则索昏昏沉沉的睡；从今后衫儿、袖儿，都揾做重重叠叠的泪。兀的不闷杀人也么哥！兀的不闷杀人也么哥！久已后书儿、信儿，索与我凄凄惶惶的寄。\n〔脱布衫〕下西风黄叶纷飞，染寒烟衰草萋迷。酒席上斜签着坐的，蹙愁眉死临侵[23]地。\n〔小梁州〕我见他阁泪汪汪不敢垂，恐怕人知。猛然见了把头低，长吁气，推整素罗衣。\n〔幺篇〕虽然久后成佳配，奈时间怎不悲啼。意似痴，心如醉，昨宵今日，清减了小腰围。\n〔上小楼〕合欢未已，离愁相继。想着俺前暮私情，昨夜成亲，今日别离。我谂知[24]这几日相思滋味，却原来比别离情更增十倍。\n〔幺篇〕年少呵轻远别，情薄呵易弃掷。全不想腿儿相挨，脸儿相偎，手儿相携。你与俺崔相国做女婿，妻荣夫贵。但得一个并头莲，煞强如状元及第。\n〔满庭芳〕供食太急，须臾对面，顷刻别离。若不是酒席间子母每当回避，有心待与他举案齐眉。虽然是厮守得一时半刻，也合着俺夫妻每共桌而食。眼底空留意，寻思起就里，险化做望夫石。\n〔快活三〕将来的酒共食，尝着似土和泥。假若便是土和泥，也有些土气息，泥滋味。\n〔朝天子〕暖溶溶玉醅，白泠泠似水，多半是相思泪。眼面前茶饭怕不待要吃，恨塞满愁肠胃。蜗角虚名，蝇头微利，拆鸳鸯在两下里。一个这壁，一个那壁，一递一声长吁气。\n〔四边静〕霎时间杯盘狼籍，车儿投东，马儿向西，两意徘徊，落日山横翠。知他今宵宿在那里？有梦也难寻觅。\n〔耍孩儿〕淋漓襟袖啼红泪，比司马青衫更湿。伯劳[25]东去燕西飞，未登程先问归期。虽然眼底人千里，且尽生前酒一杯。未饮心先醉，眼中流血，心里成灰。\n〔五煞〕到京师服水土，趁程途节饮食，顺时自保揣身体。荒村雨露宜眠早，野店风霜要起迟！鞍马秋风里，最难调护，最要扶持。\n〔四煞〕这忧愁诉与谁？相思只自知，老天不管人憔悴。泪添九曲黄河溢，恨压三峰华岳低。到晚来闷把西楼倚，见了些夕阳古道，衰柳长堤。\n〔三煞〕笑吟吟一处来，哭啼啼独自归。归家若到罗帏里，昨宵个绣衾香暖留春住，今夜个翠被生寒有梦知。留恋你别无意，见据鞍上马，阁不住泪眼愁眉。\n〔二煞〕你休忧文齐福不齐，我则怕你停妻再娶妻。休要一春鱼雁无消息！我这里青鸾有信频须寄，你却休“金榜无名誓不归”。此一节君须记，若见了那异乡花草，再休似此处栖迟。\n〔一煞〕青山隔送行，疏林不做美，淡烟暮霭相遮蔽。夕阳古道无人语，禾黍秋风听马嘶。我为甚么懒上车儿内，来时甚急，去后何迟？\n〔收尾〕四围山色中，一鞭残照里。遍人间烦恼填胸臆，量这些大小车儿如何载得起！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2515, "title": "四丞相高会丽春堂", "author": "王实甫", "body": "〔越调·斗鹌鹑〕闲对着绿树青山，消遣我烦心倦目。潜入那水国渔乡，早跳出龙潭虎窟。披着领箬笠蓑衣，堤防他斜风细雨。长则是琴一张、酒一壶。自饮自斟，自歌自舞。\n〔紫花儿序〕也不学刘伶荷锸，也不学屈子投江，且做个范蠡归湖。绕一滩红蓼，过两岸青蒲。渔夫，将我这小小船儿棹将过去。惊起那几行鸥鹭。似这等乐以忘忧，胡必归欤。\n〔小桃红〕水声山色两模糊，闲看云来去。则我怨结愁肠对谁诉？自踌躇。想这场烦恼都也由咱取。感今怀古，旧荣新辱。都装入酒葫芦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2516, "title": "吕蒙正风雪破窑记", "author": "王实甫", "body": "〔金盏儿〕绣球儿你寻一个心慈善、性温良、有志气、好文章。这一生事都在你这绣球儿上。夫妻相待，贫和富有何妨。贫和富，是我命福；好共歹，在你斟量。休打着那无恩情轻薄子，你寻一个知敬重画眉郎[26]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2517, "title": "吕蒙正风雪破窑记", "author": "王实甫", "body": "〔中吕·粉蝶儿〕瓮牖桑枢，世间穷尽都在此处，有一千个不识消疏。范丹也索移，原宪也索，便有那颜回也难住。虽然是人不堪居，我觑的胜兰堂绿窗朱户。\n〔醉春风〕恨不恨买臣妻，学不学卓氏女，破窑中熬了我数年，多受了些个苦。苦，一饮一啄，事皆前定，也是我一生衣禄。\n〔上小楼〕你如今知咱受苦，将咱小觑，怎肯道是连累街坊，带累亲邻，败坏风俗。冻杀我，甘心死去，则这个泼家私，觑也那是不觑。\n〔普天乐〕我这里猛然观，抬头觑，我道是谁家个奸汉，却原来是应举的儿夫。咱须是旧有姻，关连着亲肠肚，但得个身安乐还家重完聚，问甚么官不官便待怎的？有一个张良也曾弃印，有一个陶潜罢职，有一个范蠡归湖。\n〔十二月〕走将来朝云暮雨，似水也那如鱼。又无那暖烘烘的被卧，都是些薄湿湿的衣服。明晃晃腰间甚物，怎想你那身上埋伏。\n〔尧民歌〕呀，两三层麻布里藏珍珠，万万丈波心里钓鳌鱼。怕你得官酬志汉相如，倒做了好色荒淫鲁秋胡。儿也波夫，冤家问一句，说罢也重完聚。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2518, "title": "韩彩云丝竹芙蓉亭", "author": "王实甫", "body": "〔仙吕·点绛唇〕天霁云开，月华精彩，南楼外。行过庭阶，我潜立在湖山侧。\n〔混江龙〕今夜个百无妨碍，洗乾坤风露净尘埃。冷清清风摇翠竹，白泠泠露滴苍苔。风力紧寒侵金缕衣，露华凉冰透绣罗鞋。轻移莲步，慢转雕栏，帘筛月影，灯晃书斋。又不敢呼名道姓，我则索蹑足潜踪，悄声儿独立在窗儿外。想着俺怀儿中受用，怕甚么脸儿上抢白。\n〔油葫芦〕我着这瘦耸耸香肩将门扇儿挨，你试猜，止不过月明千里故人来。则我这后园中晚谒文章伯，你不肯秦楼夜访金钗客。外面儿模样好，就里最为事歹。我不比你穷酸般胡谝[27]教君怪，不放参紧闭定看书斋。\n〔天下乐〕却做了十谒朱门九不开。书斋，好幽哉，不曾有俗客来，将旧帏屏几扇儿窗下摆。恋蝴蝶床榻儿窄，梦梅花纸帐儿矮。秀才呵，你正是成人好不自在。\n〔村里迓古〕你休教一时风火，烧了咱百年恩爱。则为你衾寒枕冷，咱厮敬重一家无外。你这般假古，乔身份，妆些台孩。可知道死了杜甫，亡了韩愈，淹了李白，我道来你可甚贤贤易色？\n〔元和令〕便有那曹子建七步才，还不了庞居士一分债。他那般气昂昂胸次卷江淮，你可是酒肠宽似海？则想我夜深私出绣房来，实丕丕耽着利害。\n〔上马娇〕一来是天地差，二来是缘分该，则你个啉[28]宋玉自裁划，待将这无路巫娥推出门外。我为甚么来？干教我空下楚阳台！\n〔游四门〕却正是蒺藜沙上野花开，可不道疑是玉人来。则为你冷清清难把长更捱，砌下乱蛩哀，咍，我特地探多才。\n〔胜葫芦〕休着我倚定门儿手托腮，休将那不睹事的话儿揣，小的每天生酒量窄。道的我速速的眼跳，氲氲的耳热，忽忽的燎双腮。\n〔幺篇〕你见我两朵桃花上脸来，则怕你悔后也栋梁材，哎，你个秉烛颜渊自鉴戒。兀的般月斜风细，更阑人静，天上巧安排。\n〔后庭花〕保亲的论孟白[29]，主婚的唐宋策；送女的霜毫笔，守亲的是石砚台。你既怕女裙钗，无心耽待，枉将伊厮定害。王子高不好色，周琼姬忒分外，卓文君事不谐。\n〔柳叶儿〕哎，你个汉相如休怪，则要你温我的浸冷罗鞋，干教我羞答答的懒把门桯蓦[30]。哎，你个梁山伯，不采我这祝英台，羞的我怏怏儿回来。\n〔寄生草〕你则怕担烦恼，惹罪责，为侄儿恐怕尊姑怪，书生不好阴人爱；莫不你一家儿受了康禅戒！量这个彩云吃打有何羞，尚犹自文王下马将荆条拜。\n〔尾声〕得了首有情分的断肠词，自惹下场无倒断相思债。这一个小书舍里天宽地窄，也不索对天地说盟山言誓海，咱则是常川似今夜鱼水和谐。紧栽排，怎肯教信断音乖，则要你常准备迎风户半开。来日个一更左侧，你倚门儿等待，我则等的夫人烧罢夜香来。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2519, "title": "同乐院燕青博鱼", "author": "李文蔚", "body": "〔大石调·六国朝〕我揣巴些残汤剩水，打叠起浪酒闲茶。我着些气呵暖我这冻拳头，再着些唾揩光我这冷鼻凹。瘦的来我这身子儿没个麻稭大，兀的不消磨了我刺绣的青黛和这硃砂。眼见得穷活路，觅不出衣和饭，怕不道酷寒亭把我来冻饿杀。全不见那昏惨惨云遮了银汉，则听的淅零零雪糁琼沙，我我我，待踮着个鞋底儿去拣那浅中行，先绰的这棒头来向深处插。\n〔喜秋风〕我与你便吖吖叫，我与你便磨磨擦。我为甚将这脚尖儿细细踏。我怕只怕这路儿有些步步滑，将那前街后巷我便如盘卦。刚才个渐渐里呵的我这手温和，可又早切切里冻的我这脚麻辣。\n〔归塞北〕天那，您不肯道是相赍发，专与俺这穷汉做冤家。这雪呵他如柳絮不添我身上絮，似梨花却变做了眼前花。则我这拄杖冻难拿。\n〔雁过南楼〕我是一个混海龙摧鳞去甲，我是一只爬山虎也啰奈削爪敲牙。往常时我习武艺学兵法，到如今半筹也不纳，则我这拿云手怕不待寻觅那等瞎生涯。我能舞剑偏不能疙蹅蹅敲象板，会轮枪偏不会支楞楞拨琵琶，着甚度年华。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2520, "title": "便宜行事虎头牌", "author": "李直夫", "body": "〔搅筝琶〕咱须是关亲意，也索要顾兵机。官里着你户列簪缨，着你门排画戟，可怎生不交战，不迎敌，吃的个醉如泥。情知你便是快行兵姜太公、齐管仲、越范蠡、汉张良，可也管着些甚的。枉了你哭哭啼啼。\n〔胡十八〕他则待[1]酒食，可便恋声妓，他那里肯道把隘口退强贼，每日则是吹笛擂鼓做筵席。（老旦云）你叔叔老了也。（正末云）你道叔叔老了，他多大年纪也？（老旦云）他六十岁了。（正末唱）他恰才便六十。（云）姜太公八十遇文王，戊午日兵临孟水，甲子日血浸朝歌，扶立周朝八百年天下。（唱）他比那伐纣的姜太公，尚兀自还少他二十岁。\n〔庆宣和〕则这断事处，谁教你可便来这里？这讼厅上可便使不着你那家有贤妻。（云）着他那属官每，便道叔叔犯下罪过来，可着媳妇儿来说。（唱）你这个关节儿常好道[2]来的疾。（云）茶茶，你若不回去呵，（唱）可都枉擘破咱这面皮，面皮。\n〔步步娇〕则你这大小属官，都在这厅阶下跪，畅好是一个个无廉耻。他是叔父我是侄，道底来火须不热如灰[3]，你是必再休提。（云）他是我的亲人，犯下这般正条款的罪过来，我尚然杀坏了，你每若有些儿差错呵，（唱）你可便先看取他这个傍州例。\n〔沽美酒〕则见他的做样势，笑吟吟的强支对。他那里口口声声道是饶过，只我这里寻思了一会，这公事岂容易。\n〔太平令〕我将他几番家叱退，他苦央及两次三回。则管里指官画吏，不住的叫天吖[4]地。（带云）狗儿，（唱）你可向这里，问你，莫不待替吃。（狗儿云）我替吃，我替吃。（正末云）你替吃，令人，你安排下大棒子者。（唱）我先拷的你，拷的你腰截粉碎。\n〔雁儿落〕你畅好是腕头有气力，我身上无些意。可不道厨中有热人，我共他心下无仇气。\n〔得胜令〕打的来一棍子一刀锥，一下起一层皮。他去那血泊里难禁忍，则着俺校椅上怎坐实。他失误了军期，难道他没罪谁担罪。（云）打了多少也？（经历云）打了三十也。（正末唱）才打到三十？赤瓦不剌海[5]，你也忒官不威牙爪威。\n〔鸳鸯煞〕你则合眠霜卧雪驱兵队，披星带月排戈戟。你也曾对咱盟咒再不贪杯，唱道[6]索记前言，休贻后悔。谁着你旦暮朝夕，尝吃的来醺醺醉，到今日待怨他谁。这都是你那恋酒迷歌上落得的。（众随下）", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2521, "title": "散家财天赐老生儿", "author": "武汉臣", "body": "〔混江龙〕请来凭脉，（云）一投的凭罢那脉也。婆婆道：“老的你索与我换上盖咱！”老夫便道：“你与我说了，我与你。”他便道：“老儿你贺喜者。”（唱）他道小梅行必定是个厮儿胎，不由我不频频的加额，落可便暗暗的伤怀。但得一个生忿子拽布披麻扶灵柩，索强似那孝顺女罗裙包土筑坟台。往常我瞒心昧己信口胡开，把神佛毁谤，将僧道抢白，因此上折乏的儿孙缺少。现如今我筋力全衰，人说着便去人唤着忙来。看经要灭罪，舍钞要消灾，我急煎煎去把那稳婆和老娘寻。恨不得曲躬躬将他土块的这砖头来拜。（带云）我想儿孙的福分非同小可也。（唱）使不着人强马壮，端的是鬼使神差。\n〔油葫芦〕有那等守护贤良老秀才，他说的来狠利害。（云）他每都道是刘从善那老子空有钱，则恁般割舍不的使。若是个女儿呵罢论；若是个小厮儿呵，耻辱他老子一场。（唱）他待将这老头儿监押去游街。（带云）小梅，你若真得个儿呵！（唱）我情愿谢神天，便把那香花赛，请亲邻便把猪羊宰。遮莫他将蹇卫[1]迎，草棍捱，但得他不骂我做绝户的刘员外，只我也情愿湿肉伴干柴。\n〔天下乐〕我可便得一个残疾的小厮儿来，问什么兴也波衰？总是那天数该。（云）天哪！倘是我小梅这妮子分娩了，你觑这早晚多早晚也，莫不是小厮儿生得毒么？（唱）则他那时辰儿问什么好共歹，我但得把他摇车儿上缚，便把我去墓子里面埋，我便做一个鬼魂儿可便也快哉！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2522, "title": "救孝子贤母不认尸", "author": "王仲文", "body": "〔满庭芳〕似这等含冤负屈，拼着个割舍了三文钱的泼[1]命，更和这半百岁的微躯。你要我数说您大小诸官府，一刬的[2]木笏司[3]糊突，并无聪明正直的心腹。尽都是那绷扒吊拷的招伏，把囚人百般拴住，打的来登时命卒。哎哟！这便是您做下的个死工夫。\n〔五煞〕人死者不复生，那断弦者怎再续。从来个罪疑便索从轻恕。磨勘成的文状才难动，罗织[4]就的词因到底虚。官人每枉请着皇家禄，都只是捉生替死，屈陷无辜。\n〔四煞〕则你那捆麻绳用竹，签批头棍下脑箍。可不道父娘一样皮和骨，便做那石镌成骨节也槌敲的碎，铁铸就的皮肤也锻炼的枯。打得来没半点儿容针处。方信道人心似铁，您也忒官法如炉。\n〔二煞〕我明明的眼觑着，暗暗的心自苦。那一面沉枷脖项难回顾。透枷拴深使钉来钉，侵井口窄将印缝铺。恰便似刀搅着你这娘肠肚。望后来怎禁推抢，待向前去又被揪捽。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2523, "title": "月明和尚度柳翠", "author": "李寿卿", "body": "〔黄钟尾〕你道是“这回和月常相守”，才赚的春风可便树点头。聚莺朋，合燕友；蜂衙喧，蝶梦幽；啭黄鹂，鸣锦鸠；噪昏鸦，覆野鸥；袅金丝，春水沟；拂红裙，夜月楼；酒旗前，望竿后；风又狂，雨又骤；霜正严，雪正厚；霜来欺，月来救。我救的这月里桫椤[1]永长寿；我着你访灵山会首；也不索别章台的这故友，我则怕你又折入情郎画眉手。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2524, "title": "月明和尚度柳翠", "author": "李寿卿", "body": "〔耍孩儿·三煞〕来了，你呵：黄莺也，懒更啼；金蝉也，无处栖。来了，你呵，再不见那绿荫深处把青骢系。来了，你呵，再不见那舞春风楚宫别院纤腰细。来了，你呵，再不见那缀晓露汉殿长门翠黛低。来了，你呵，再不见那影蹁跹比张绪多娇媚。来了，你呵，再不见那助清凉陶令宅两行斜映，增杀气亚夫营万缕低垂。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2525, "title": "说诸伍员吹箫", "author": "李寿卿", "body": "〔甜水令〕想当日为避追兵，忙离濑上，奔来江表，烟水隔迢遥。幸遇渔翁，将咱济渡。别无推调，元来他也是个遁世的由巢[2]。\n〔折桂令〕他待要把酒论交，觑的我千金剑赠，只当作一片尘飘。俺本为衔着冤仇，思图报复，受尽煎熬。只要他休泄漏俺这萍根浪脚，那知道翻断送他雪鬓霜毛。空余下波浪滔滔，芦荻萧萧，至今的回首东风，尚忍不住泪点双抛。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2526, "title": "〔中吕〕普天乐", "author": "滕宾", "body": "柳丝柔，莎茵细。数枝红杏，闹出墙围。院宇深，秋千系。好雨初晴东郊媚。看儿孙月下扶犁。黄尘意外，青山眼里，归去来兮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2527, "title": "〔中吕〕普天乐", "author": "滕宾", "body": "翠荷残，苍梧坠。千山应瘦，万木皆稀。蜗角名，蝇头利，输与渊明陶陶醉。尽黄菊围绕东篱，良田数顷，黄牛一只，归去来兮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2528, "title": "〔正宫〕叨叨令", "author": "邓玉宾", "body": "一个空皮囊包裹着千重气，一个干骷髅顶戴着十分罪。为儿女使尽些拖刀计，为家私费尽些担山力。您省的也么哥？您省的也么哥？这一个长生道理何人会？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2529, "title": "〔正宫〕叨叨令", "author": "邓玉宾", "body": "白云深处青山下，茅庵草舍无冬夏。闲来几句渔樵话，困来一枕葫芦架。您省的也么哥，您省的也么哥？煞强如风波千丈担惊怕。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2530, "title": "汉高皇濯足气英布", "author": "尚仲贤", "body": "〔黄钟·醉花阴〕俺则见楚汉争锋竞寰土，那楚霸王甘心伏输？此一阵不寻俗，这汉英布武勇谁如？据慷慨堪称许，善韬略晓兵书，没半霎儿早熬翻了楚项羽！\n〔喜迁莺〕骨剌剌旗门开处，那楚重瞳在阵面上高呼：“无徒杀人可恕，情理难容！”这匹夫两下里厮耻辱，那一个道待你非轻，这一个道负你何辜？\n〔出队子〕俺这里先锋前部，会分支，能对付，[1]，响飕飕。阵上发个金镞，火火火；齐臻臻军前列着军卒，呀呀呀。俺则见垓心里骤战驹——\n〔刮地风〕鼕鼕鼕，不待的三声凯战鼓，忽剌剌两面旗舒。扑腾腾二马相交处，则听的闹垓垓喊震天隅。俺则见一来一去不见赢输，两匹马、两员将有如星注。那一个使火尖枪，正是他楚项羽，忽的呵早刺着胸脯。\n〔四门子〕俺英布正是他的英雄处，见枪来早轻轻的放过去，两员将各自寻门路。整彪躯轮巨毒，虚里着实，实里着虚，厮过瞒各自依法度。虚里着实，实里着虚，则听的连天喊举！\n〔古水仙子〕纷纷纷，溅土雨，霭霭霭，黑气黄云遮了太虚。刷刷刷，马荡动征尘；隐隐隐，人蟠在杀雾；吁吁吁，马和人都气促；吉当当，枪和斧笼罩着身躯；扢挣挣，斧迎枪几番烟焰举；可擦擦，枪迎斧万道霞光出；厮琅琅，断铠甲落兜鍪[2]——\n〔尾声〕嗔忿忿，将一匹跨下征紧缠住。杀的那楚项羽促律律向北忙逋。兀的不生掿损明晃晃这柄簸箕般金蘸斧！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2531, "title": "洞庭湖柳毅传书", "author": "尚仲贤", "body": "〔越调·斗鹌鹑〕他两个天北天南，海西海东，云闭云开，水淹水冲，烟罩烟飞，火烧火烘！卒律律电影重，古突突雾气浓。起几个骨碌碌的轰雷，更一阵扑簌簌的怪风。\n〔紫花儿序〕险惊杀了负薪的樵子，慌杀了采药的仙童，唬杀了撒网的渔翁。全不见红莲映日，翠盖迎风，遮笼都是那鬼卒神兵四下攻。则俺这两只脚争些儿踏空，可擦擦坠落红尘，兀的不跌破了我青铜。〔小桃红〕那小龙大开水殿饮金钟，厮琅琅几部笙歌送，不觉的天边黑云重。昏邓邓敢包笼，忽剌剌半空霹雳声惊动，古都都揭了瓦陇，吸哩哩提了斗栱，滴溜溜早翻过水晶宫。\n〔紫花儿序〕忽的呵阴云伏地，淹的呵洪水滔天，腾的呵烈火飞空。泾河龙逃归碧落，钱塘龙赶上苍穹。两条龙的威风，怕不喊杀了鳖大夫、龟将军、鼍相公。这其间各赌神通，早翻过那海岛十洲，只待要拔倒了华岳三峰！\n〔鬼三台〕两条龙身躯纵，震的那乾坤动。恶哏哏健勇，赤焰焰满天红，一撞一冲，则教你心如铁石地怕恐，便有那铜山铁壁都没用。钱塘龙逆水忙截，泾河龙淤泥便……", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2532, "title": "洞庭湖柳毅传书", "author": "尚仲贤", "body": "〔商调·集贤宾〕则俺那寄书来的秀才错立了身，怎能勾平步上青云。则为他长安市不登虎榜，救的我泾河岸脱离羊群。他本望至公楼独占鳌头，今日向洞庭湖跳过了龙门。则我这重叠叠的眷姻可也堪自哂，若不成就燕尔新婚，我则待收拾些珍宝物，报答您大恩人。\n〔金菊香〕则我这凌波袜小上阶痕，手提着沥水湘裙与你入殿门，在这浑金椅前（做见二亲科，唱）参了二亲。那一场电走雷奔，（做见钱塘君科，唱）驾风云的叔父你可也索是劳神。\n〔后庭花〕俺满口儿要结姻，他舒心儿不勘婚。信口儿无回话，刬的偷睛儿横觑人。我这里两眉颦，他则待暗传芳信；对面的辞了亲，就儿里相逗引。俺叔父敢则嗔，那其间怎的忍，吼一声风力紧，吐半天烟雾昏，轻喝处摄了你魂，但抹着可更分了你身。你见他狠不狠，他从来恩不恩。\n〔柳叶儿〕秀才也敢教你有家难奔，是是是熬不出寡宿孤辰。谁着你自揽下四海三江闷，你端的心儿顺，意儿真，秀才也便休愁暮雨朝云。\n〔浪里来煞〕这薄礼呵请先生休见阻，送行者宁无赆。则为你假乖张不就我这门亲，害的来两下里憔悴损。我则索向龙宫纳闷，怎禁他水村山馆自黄昏。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2533, "title": "陶渊明归去来兮", "author": "尚仲贤", "body": "〔正宫·倘秀才〕面对着青山故友，眼不见白衣送酒，我则怕明日黄花蝶也愁。好教我情绪懒，意难酬，无言低首。\n〔灵寿杖〕西风落叶山容瘦，呀呀的雁过南楼，霜满汀洲，水痕渐收。山泼黛层层崄[3]，水泛碧粼粼皱。记的是清明三月三，不觉又重阳九月九。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2534, "title": "海神庙王魁负桂英", "author": "尚仲贤", "body": "〔双调·新水令〕岂不闻举头三尺有神祇，咱人便行一步也有个当方土地。想着那应举去了的折桂郎，那厮做了个拐恩情的打家贼。咱别话儿休题，王魁才可招取俺那海神庙说来的誓。\n〔夜行船〕我望着正面儿尊神忙拜起，哎，吁！长吁了两次三回。办着我一点虔心，阁着两行情泪，哎，耶耶也，则这埚儿是是俺那送行的田地。\n〔沉醉东风〕则他那人间语天闻若雷，但行处祸福相随。国家明明的放着王法，耶耶！你须暗暗的施着神鬼。各要个寸心不昧，兀的般弃旧怜新将盟誓违，惯得他碜可可的辜恩负德。\n〔庆东原〕清耿耿将明香来爇，骨碌碌将杯筊[4]掷，则见尽今生到老无抛弃；却不道夫唱妇随，夫荣妇贵，俺可是末夫妻来也那[5]福齐。耶耶，怎教别人更戴了我金冠，也披我这霞帔。\n〔乔牌儿〕我图个甚的，怎承望有今日！成时节自不合道成的容易，今日个待悔来怎的悔。\n〔折桂令〕元来这乞儿每饱病难医，我知道这厮负德辜恩，枉了我举案齐眉。那其间忍冷耽饥，穷滴滴少衣无食，大古里怎生般家豪富贵，刬地那厌娼人门户低微。他如今在宰相家里，别娶了娇妻，锦帐罗帏，步步儿相随，永不相离。我一捻儿年纪，耽阁了我身奇。我叫一声王魁，王魁嗏，你营勾了我当甚末便宜。\n〔胡十八〕则为你便忒正直，着你做神祇。这的是他负了俺，须不是俺虚脾。这殿阶前空立一统[6]正直碑！我付了这壁，我告诉与那壁，你为甚将我不应对？元来是这一堂儿都是个塑来的泥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2535, "title": "鲁大夫秋胡戏妻", "author": "石君宝", "body": "〔叨叨令〕你道是鸾凰则许鸾凰配，鸳鸯则许鸳鸯对，庄家做尽庄家势。留着你那村里鼓儿则向村里擂。其实我便觑不上也波哥，其实我便觑不上也波哥。我道你有铜钱则不如抱着铜钱睡！\n〔煞尾〕爹爹也，怎使这洞房花烛拖刀计[1]？（李云）我这模样，可也不丑。（正旦唱）我则骂你闹市云阳[2]吃剑贼！牛表牛筋[3]是你亲戚，大户乡头是你相识。哎！不晓事庄家甚官位？这时分俺男儿在那里：他或是皂盖雕轮绣幕围，玉辔金鞍骏马骑，两行公人排列齐，水罐银盆摆的直，斗来大黄金肘后随，箔来大元戎帅字旗。回想他亲娘今年七十岁，早来到土长根生旧乡地。恁时节母子夫妻得完备，我说你个驴马村夫为仇气。那一个日头儿知他是近的谁，狼虎般公人每拿下伊。我可也不道轻轻的便素放[4]了你。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2536, "title": "鲁大夫秋胡戏妻", "author": "石君宝", "body": "〔满庭芳〕我慌还一个庄家万福。他不是闲游的浪子，多敢是一个取应的名儒。我见他便躬着身、插着手、陪言语。你既读那孔圣之书，我是个采桑养蚕妇女，休猜做锄田送饭村姑。他酩子里丢抹娘一句，怎人模人样，做出这等不君子，待何如？\n〔上小楼〕你待要谐比翼，你也曾听杜宇，他那里口口声声，撺掇先生不如归去。你道是不比俺那养蚕处，好将伊留住；则俺那蚕老了，到那里怎生发付？\n〔十二月〕兀的是谁家一个匹夫？畅好是胆大心粗！眼脑儿涎涎邓邓，手脚儿扯扯也那捽捽。是他便拦住我还家去路，我则索大叫波高呼！\n〔尧民歌〕桑园里只待强逼做欢娱，唬的我手儿脚儿滴羞蹀躞战笃速。他便相偎相抱扯衣服，一来一往当拦住。当也波初，则道是峨冠士大夫，原来是个不晓事的乔男女。\n〔耍孩儿〕可不道书中有女颜如玉，你将着金要买人云雨[5]，却不道黄金散尽为收书。哎！你个富家郎惯使珍珠，倚仗着囊中有钞多声势，岂不闻财上分明大丈夫？不由咱生嗔怒，我骂你个沐猴冠冕，牛马襟裾！\n〔二煞〕俺那牛屋里怎成得美眷姻，鸦窠里怎生着鸾凤雏，蚕茧纸难写姻缘簿，短桑科长不出连枝树，沤麻坑养不活比目鱼，辘轴[6]上也打不出那连环玉。似你这伤风败俗，怕不的地灭天诛。\n〔三煞〕你瞅我一瞅，黥了你那额颅；扯我一扯，削了你那手足；你汤我一汤，拷了你那腰截骨；掐我一掐，我着你三千里外该流递；搂我一搂，我着你十字阶头便上木驴。哎！吃万剐的遭刑律！我又不曾掀了你家坟墓，我又不曾杀了你家眷属。\n〔尾煞〕这厮睁着眼，觑我骂那死尸；腆着脸，着我咒他上祖。谁着你桑园里戏弄人家良人妇！便跳出你那七代先灵也做不的主。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2537, "title": "李亚仙花酒曲江池", "author": "石君宝", "body": "〔寄生草〕他将那花阴串，我将这柳径穿。少年人乍识春风面，春风面半掩桃花扇。桃花扇轻拂垂杨线，垂杨线怎系锦鸳鸯，锦鸳鸯不锁黄金殿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2538, "title": "李亚仙花酒曲江池", "author": "石君宝", "body": "〔南吕·一枝花〕俺娘眼上带一对乖，心内隐着十分狠，脸上生那歹斗毛，手内有那握刀纹。狠的来世上绝伦，下死手，无分寸。眼又尖，手又紧。他拳起处又早着昏，那郎君呵，不带伤必然内损。\n〔梁州第七〕俺娘呵，则是个吃人脑的风流太岁，剥人皮的娘子丧门。油头粉面敲人棍，笑里刀剐皮割肉，绵里针剔髓挑筋。娘使尽虚心冷气，女着些带耍连真，总饶你便通天彻地的郎君，也不够三朝五日遭瘟。则俺那爱钱娘扮出个凶神，卖笑女伴了些死人，有情郎便是那冤魂。俺娘钱亲钞紧，女心里憎恶娘亲近，娘爱的女不顺。娘爱的郎君个个村，女爱的却无银。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2539, "title": "诸宫调风月紫云庭", "author": "石君宝", "body": "〔鲍老儿〕从来撒欠风[9]爱恁末，敲才兀自不改动些儿个。你这般忍冷耽饥觅着我，越引起我那色胆天来大。我每日千思万想，行眠立盹，不是存活[10]。这般山长水远，天遥地阔，不想你直来阿。\n〔哨遍〕送的人赤手空拳难过，都是俺舌尖上一点砂糖唾。越精细[11]的越着他怎出俺这打多情地网天罗。且说俺这小哥哥，为俺耽惊受怕，波迸流移[12]冷落了读书院一就把功名懒堕。自尽教萱堂有梦，并不想兰省登科。几时得两扶红日上青天，空望着一片白云隔黄河。则共我这般携手儿相将，举步儿同行，他想所事[13]满心儿快活。\n〔耍孩儿〕早是你不合将堂上双亲躲，你却待改换你家门小可[14]。这李亚仙苦劝你个郑元和。再休提那撒板鸣锣。若还俺娘知咱这暗私奔到毒似那倒寨计，若还恁耶见你这诸宫调更狠如那唱挽歌。你脖项上新开锁。俺娘难道那风云气少，恁耶却甚末儿女情多。\n〔收尾〕此行折末山村野店上藏，竹篱茅舍里躲。能够得个桑榆景内安闲的过，也强如锣板声中断送了我。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2540, "title": "〔双调〕殿前欢", "author": "阿里西瑛", "body": "懒云窝，醒时诗酒醉时歌。瑶琴不理抛书卧，无梦南柯。得清闲尽快活。日月似撺梭过，富贵比花开落。青春去也，不乐如何。\n懒云窝，醒时诗酒醉时歌。瑶琴不理抛书卧，尽自磨陀。想人生待则么？富贵比花开落，日月似撺梭过。呵呵笑我，我笑呵呵。\n懒云窝，客至待如何？懒云窝里和衣卧，尽自婆娑。想人生待则么？贵比我高些个，富比我松些个？呵呵笑我，我笑呵呵。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2541, "title": "〔正宫〕鹦鹉曲", "author": "冯子振", "body": "嵯峨峰顶移家住，是个不唧樵父[1]。烂柯时树老无花，叶叶枝枝风雨。〔幺〕故人曾唤我归来，却道不如休去。指门前万叠云山，是不费青蚨[2]买处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2542, "title": "〔正宫〕鹦鹉曲", "author": "冯子振", "body": "年年牛背扶犁住，近日最懊恼杀农夫。稻苗肥恰待抽花，渴煞青天雷雨。〔幺〕恨残霞不近人情，截断玉虹南去。望人间三尺甘霖，看一片闲云起处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2543, "title": "〔正宫〕鹦鹉曲", "author": "冯子振", "body": "孤村三两人家住，终日对野叟田父。说今朝绿水平桥，昨日溪南新雨。〔幺〕碧天边岩穴归云[3]，白鹭一行飞去。便芒鞋竹杖行春，问底是青帘舞处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2544, "title": "〔正宫〕鹦鹉曲", "author": "冯子振", "body": "新凉时节城南住，灯火诵鲁国尼父。到秋来宋玉生悲，不赋高唐云雨。〔幺〕一声声只在芭蕉，断送别离人去。甚河桥柳树全疏，恨正在长亭短处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2545, "title": "〔正宫〕鹦鹉曲", "author": "冯子振", "body": "茅庐诸葛亲曾住，早赚出抱膝梁父。笑谈间汉鼎[4]三分，不记得南阳耕雨。〔幺〕叹西风卷尽豪华，往事大江东去。彻如今话说渔樵，算也是英雄了处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2546, "title": "〔正宫〕鹦鹉曲", "author": "冯子振", "body": "花骢嘶断留侬住，满酌酒劝据鞍父。柳青青万里初程，点染阳关朝雨。〔幺〕怨春风雁不回头，一个个背人飞去。望河桥敛衽频啼，早蓦到长亭短处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2547, "title": "〔双调〕寿阳曲", "author": "朱帘秀", "body": "山无数，烟万缕，憔悴煞玉堂人物。倚篷窗一身儿活受苦，恨不得随大江东去。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2548, "title": "〔正宫〕塞鸿秋", "author": "贯云石", "body": "战西风几点宾鸿至，感起我南朝千古伤心事。展花笺欲写几句知心事，空教我停霜毫半晌无才思。往常得兴时，一扫无瑕疵。今日个病厌厌刚写下两个相思字。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2549, "title": "〔正宫〕小梁州", "author": "贯云石", "body": "春风花草满园香，马系在垂杨。桃红柳绿映池塘。堪游赏，沙暖睡鸳鸯。〔幺〕宜晴宜雨宜阴旸，比西施淡抹浓妆。玉女弹，佳人唱，湖山堂上，直吃醉何妨。\n画船撑入柳阴凉，一派笙簧。采莲人和采莲腔。声嘹亮，惊起宿鸳鸯。〔幺〕佳人才子游船上，醉醺醺笑饮琼浆。归棹晚，湖光荡，一钩新月，十里芰荷香。\n芙蓉映水菊花黄，满目秋光。枯荷叶底鹭鸶藏。金风荡，飘动桂枝香。〔幺〕雷峰塔畔登高望，见钱塘一派长江。湖水清，江潮漾，天边斜月，新雁两三行。\n彤云密布锁高峰，凛冽寒风。银河片片洒长空。梅梢冻，雪压路难通。〔幺〕六桥倾刻如银洞，粉妆成九里寒松。酒满斟，笙歌送，玉船银棹，人在水晶宫。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2550, "title": "〔南吕〕金字经", "author": "贯云石", "body": "蛾眉能自惜，别离泪似倾。休唱《阳关》第四声。情，夜深愁寐醒。人孤零，萧萧月二更。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2551, "title": "〔南吕〕金字经", "author": "贯云石", "body": "泪溅描金袖，不知心为谁？芳草萋萋人未归。期，一春鱼雁稀。人憔悴，愁堆八字眉。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2552, "title": "〔中吕〕红绣鞋", "author": "贯云石", "body": "挨着靠着云窗同坐，偎着抱着月枕双歌，听着数着愁着怕着早四更过。四更过情未足，情未足夜如梭。天哪，更闰一更儿妨甚么！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2553, "title": "〔双调〕蟾宫曲", "author": "贯云石", "body": "问东君何处天涯？落日啼鹃，流水桃花，淡淡遥山，萋萋芳草，隐隐残霞。随柳絮吹归那答，趁游丝惹在谁家。倦理琵琶，人倚秋千，月照窗纱。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2554, "title": "〔双调〕清江引", "author": "贯云石", "body": "弃微名去来心快哉！一笑白云外。知音三五人，痛饮何妨碍？醉袍袖舞嫌天地窄。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2555, "title": "〔双调〕清江引", "author": "贯云石", "body": "竞功名有如车下坡，惊险谁参破？昨日玉堂臣，今日遭残祸。争如我避风波走在安乐窝！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2556, "title": "〔双调〕清江引", "author": "贯云石", "body": "南枝夜来先破蕊，泄露春消息。偏宜雪月交，不惹蜂蝶戏。有时节暗香来梦里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2557, "title": "〔双调〕清江引", "author": "贯云石", "body": "芳心对人娇欲说，不忍轻轻折。溪桥淡淡烟，茅舍澄澄月。包藏几多春意也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2558, "title": "〔双调〕清江引", "author": "贯云石", "body": "玉人泣别声渐杳，无语伤怀抱。寂寞武陵源，细雨连芳草，都被他带将春去了。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2559, "title": "〔双调〕清江引", "author": "贯云石", "body": "若还与他相见时，道个真传示：不是不修书，不是无才思，绕清江买不得天样纸！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2560, "title": "〔双调〕清江引", "author": "贯云石", "body": "金钗影摇春燕斜，木杪[1]生春叶。水塘春始波，火候春初热。土牛儿载将春到也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2561, "title": "〔双调〕寿阳曲", "author": "贯云石", "body": "鱼吹浪，雁落沙，倚吴山翠屏高挂。看江潮鼓声千万家，卷朱帘玉人如画。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2562, "title": "〔双调〕寿阳曲", "author": "贯云石", "body": "新秋至，人乍别，顺长江水流残月。悠悠画船东去也，这思量起头儿一夜。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2563, "title": "〔双调〕殿前欢", "author": "贯云石", "body": "畅幽哉，春风无处不楼台。一时怀抱俱无奈，总对天开。就渊明归去来，怕鹤怨山禽怪，问甚功名在。酸斋是我，我是酸斋。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2564, "title": "〔双调〕殿前欢", "author": "贯云石", "body": "楚怀王，忠臣跳入汨罗江。《离骚》读罢空惆怅，日月同光。伤心来笑一场，笑你个三闾强，为甚不身心放。沧浪污你，你污沧浪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2565, "title": "〔双调〕殿前欢", "author": "贯云石", "body": "怕相逢，怕相逢歌罢酒樽空。醉归来纵有阳台梦，云雨无踪。楼心月扇底风，情缘重。恨不似《钗头凤》。东阳瘦损[2]，羞对青铜。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2566, "title": "〔双调〕殿前欢", "author": "贯云石", "body": "怕秋来，怕秋来秋绪感秋怀。扫空阶落叶西风外。独立苍苔，看黄花谩自开。人安在？还不彻相思债。朝云暮雨，都变了梦里阳台。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2567, "title": "〔双调〕殿前欢", "author": "贯云石", "body": "隔帘听，几番风送卖花声。夜来微雨天阶净。小院闲庭，轻寒翠袖生。穿芳径，十二阑干[3]凭。杏花疏影，杨柳新晴。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2568, "title": "〔中吕〕粉蝶儿", "author": "贯云石", "body": "描不上小扇轻罗，你便是真蓬莱赛他不过。虽然是比不的百二山河，一壁厢嵌平堤，连绿野，端的有亭台百座。暗想东坡，逋仙诗有谁酬和？\n〔好事近南〕漫说凤凰坡[4]，怎比繁华江左[5]！无穷千古，真个是胜迹极多。烟笼雾锁，绕六桥[6]翠障如螺座。青霭霭山抹柔蓝，碧澄澄水泛金波。\n〔石榴花北〕我则见采莲人和采莲歌，端的是胜景胜其他。则他那远峰倒影蘸清波，晴岚翠锁，怪石嵯峨。我则见沙鸥数点湖光破，吚吚哑哑橹声摇过。我则见这女娇羞倚定着雕栏坐，恰便似宝鉴对嫦娥。\n〔料峭东风南〕缘何？乐事赏心多，诗朋酒侣吟哦。花浓酒艳，破除万事无过[7]。嬉游玩赏，对清风明月安然坐。任春夏秋月冬天，适兴四时皆可。\n〔斗鹌鹑北〕闹穰穰的急管繁弦，齐臻臻的兰舟画舸，娇滴滴粉黛相连，颤巍巍翠云翠云万朵。端的是洗古磨今锦绣窝，你不信试觑波：绿依依杨柳千株，红馥馥芙蕖万朵。\n〔扑灯蛾南〕清风送蕙香，月穿岫云破。清湛湛水光浮岚碧，响珰珰晓钟敲破，呜咽咽猿啼在古岭，见对对鸳鸯戏清波。迢迢似渔舟钓艇，碧澄澄满船雨笠共烟蓑。\n〔上小楼北〕密匝匝那一坨[8]，疏剌剌这几窝。我这里对着晴岚，倚着青山，湛着清波。微雨初收，微烟初散，微风初过。却正是再休题淡妆浓抹。\n〔扑灯蛾南〕叠叠层楼画阁，簇簇奇花异果。远远的绿莎茵，茸茸的芳草坡，圪蹬[9]的马蹄踏破。隐隐似长桥卧波，细袅袅绿柳金拖。迢迢似渔舟钓艇，碧澄澄满船雨笠共烟蓑。\n〔尾声〕阴晴昼夜皆行乐，古往今来吟咏多，雪月风花事事可。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2569, "title": "〔双调〕折桂令", "author": "鲜于必仁", "body": "烂樵柯[1]石室忘归。足智神谋，妙理仙机。险似隋唐，胜如楚汉，败若梁齐。消日月闲中是非[2]，傲乾坤忙里轻肥。不曳旌旗，寸纸关河，万里安危。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2570, "title": "〔双调〕雁儿落过得胜令", "author": "邓玉宾子", "body": "乾坤一转丸，日月双飞箭。浮生梦一场，世事云千变。万里玉门关，七里钓鱼滩。晓日长安近，秋风蜀道难。休干，误杀英雄汉。看看，星星两鬓斑。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2571, "title": "〔双调〕雁儿落过得胜令", "author": "邓玉宾子", "body": "晴风雨气收，满眼山光秀。寻苗枸杞[1]香，曳杖桄榔[2]瘦。识破抱官囚，谁更事王侯？甲子[3]无拘系，乾坤只自由。无忧，醉了还依旧；归休[4]，湖天风月秋。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2572, "title": "临江驿潇湘秋夜雨", "author": "杨显之", "body": "〔梁州〕我则见舞旋旋飘空的这败叶，恰便似红溜溜血染胭脂，冷嗖嗖西风了却黄花事。看了些林梢掩映，山势参差。走的我口干舌苦，眼晕头疪[1]。我可也把不住抹泪揉眵[2]，行不上软弱腰肢。我我我，款款的兜定这鞋儿，是是是，慢慢的按下这笠儿，呀呀呀，我可便轻轻的拽起这裙儿。我想起亏心的那厮，你为官消不得人伏侍？你忙杀呵写不得那半张纸？我也须有个日头儿见你时，好着我仔细寻思。\n〔牧羊关〕兀的是闲言语，甚意思，他怎肯道节外生枝。我和他离别了三年，我怎肯半星儿失志。我则道他不肯弃糟糠妇，他原来别寻了个女娇姿。只待要打灭了这穷妻子。呀、呀、呀！你畅好是负心的崔甸士。\n〔哭皇天〕则我这脊梁上如刀刺，打得来青间紫。飕飕的雨点下，烘烘的疼半时。怎当他无情无情的棍子，打得来连皮彻骨，夹脑通心，肉飞筋断，血溅魂消。直着我一疼来一疼来一个死。我只问你个亏心甸士，怎揣与我这无名的罪儿？\n〔黄钟煞〕休休休，劝君莫把机谋使，现现现，东岳新添一个速报司。你你你，负心人信有之，咱咱咱，薄命妾自不是。快快快，就今日逐离此，行行行，可怜见只独自。细细细，心儿里暗忖思，苦苦苦，业身躯怎动止？管管管，少不的在路上停尸。（做悲科，唱）哎哟天那！但不知那塌儿里把我来磨勒死！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2573, "title": "临江驿潇湘秋夜雨", "author": "杨显之", "body": "〔黄钟·醉花阴〕忽听的摧林怪风鼓，更那堪瓮瀽盆倾骤雨！耽疼痛，捱程途，风雨相催，雨点儿何时住？眼见的折挫杀女娇姝，我在这空野荒郊，可着谁做主。\n〔喜迁莺〕淋的我走投无路，知他这沙门岛是何处酆都！长吁气结成云雾，行行里着车辙把腿陷住，可又早闪了胯骨。怎当这头直上急簌簌雨打，脚底下滑擦擦泥淤。\n〔刮地风〕则见他努眼撑睛大叫呼，不邓邓气夯胸脯。我湿淋淋只待要巴前路，哎，行不动我这打损的身躯。（解子喝科，云）还不走哩！（正旦唱）我捱一步又一步何曾停住，这壁厢那壁厢有似江湖。则见那恶风波，他将我紧当处。问行人踪迹消疏，似这等白茫茫野水连天暮，（带云）哥哥也，（唱）你着我女孩儿怎过去？\n〔古水仙子〕他他他，忒狠毒，敢敢敢，昧己瞒心将我图。你你你，恶狠狠公隶监束，我我我，软揣揣罪人的苦楚。痛痛痛，嫩皮肤上棍棒数，冷冷冷，铁锁在项上拴住。可可可，干支剌送的人活地狱，屈屈屈，这烦恼待向谁行诉！（带云）哥哥。（唱）来来来，你是我的护身符。\n〔随尾〕天与人心紧相助。只我这啼痕向脸儿边厢聚。（带云）天那，天那！（唱）眼见的泪点儿更多如他那秋夜雨！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2574, "title": "临江驿潇湘秋夜雨", "author": "杨显之", "body": "〔正宫·端正好〕雨如倾，敢则是风如扇。半空里风雨相缠，两般儿不顾行人怨，偏打着我头和面。\n〔滚绣球〕当日个近水边，到岸前，怎当那风高浪卷，则俺这两般儿景物凄然。风刮的似箭穿，雨下的似瓮瀽。看了这风雨呵委实的不善，也是我命儿里惹罪招愆。我只见雨淋淋写出潇湘景，更和这云淡淡妆成水墨天。只落的两泪涟涟。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2575, "title": "赵氏孤儿大报仇", "author": "纪君祥", "body": "〔醉中天〕我若是献出去图荣进，却不道利自己损别人。可怜他三百口亲丁尽不存，着谁来雪这终天恨？（带云）那屠岸贾若见这孤儿呵！（唱）怕不就连皮带筋、拈成齑粉。我可也没来由，立这样没眼的功勋！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2576, "title": "赵氏孤儿大报仇", "author": "纪君祥", "body": "〔南吕·一枝花〕兀的不屈沉杀大丈夫，损坏了真梁栋。被那些腌臜屠狗辈，欺负俺慷慨钓鳌翁。正遇着不道的灵公，偏贼子加恩宠，著贤人受困穷。若不是急流中将脚步抽回，险些儿闹市里把头皮断送。\n〔梁州第七〕他他他，在元帅府扬威也那耀勇；我我我，在太平庄罢职归农。再休想鹓班豹尾[1]相随从。他如今官高一品，位极三公；户封八县，禄享千钟。见不平处有眼如矇，听咒骂处有耳如聋。他他他，只将那会谄谀的着列鼎重裀[2]，害忠良的便加官请俸，耗国家的都叙爵论功。他他他，只贪着目前受用，全不省爬的高来可也跌的来肿，怎如俺守田园学耕种，早跳出伤人饿虎丛，倒大来从容。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2577, "title": "赵氏孤儿大报仇", "author": "纪君祥", "body": "〔双调·新水令〕我则见荡征尘飞过小溪桥，多管是损忠良贼徒来到。齐臻臻摆着士卒，明晃晃列着枪刀。眼见的我死在今朝，更避甚痛笞掠。\n〔驻马听〕想着我罢职辞朝，曾与赵盾名为刎颈交。是那个埋情出告，原来这程婴舌是斩身刀。你正是狂风偏纵扑天雕，严霜故打枯根草。不争把孤儿又杀坏了，可着他三百口冤仇甚人来报？\n〔雁儿落〕是那一个实丕丕将着粗棍敲？打的来痛杀杀精皮掉。我和你狠程婴有甚的仇？却教我老公孙受这般虐。\n〔得胜令〕打的我无缝可能逃，有口屈成招。莫不是那孤儿他知道，故意的把咱家指定了？我委实的难熬，尚兀自强着牙根儿闹；暗地里偷瞧，只见他早唬的腿脡儿摇。\n〔水仙子〕俺二人商议要救这小儿曹。哎！一句话来到我舌尖上却咽了。我怎生把你程婴道，似这般有上梢无下梢。只被你打的来不知一个颠倒。遮莫便打的我皮都绽，肉尽销，休想我有半字儿攀着。\n〔川拨棹〕你当日演神獒[3]，把忠臣来扑咬。逼的他走死荒郊，刎死钢刀，缢死裙腰，将三百口全家老小尽行诛剿。并没那半个儿剩落，还不厌你心苗。\n〔梅花酒〕呀！见孩儿卧血泊，那一个哭哭号号，这一个怨怨焦焦，连我也战战摇摇。直恁般歹做作，只除是没天道。呀！想孩儿离褥草，到今日恰十朝，刀下处怎耽饶，空生长枉劬劳，还说甚要防老。\n〔收江南〕呀！兀的不是家富小儿骄。见程婴心似热油浇，泪珠儿不敢对人抛，背地里揾了。没来由割舍的亲生骨肉吃三刀。\n〔鸳鸯煞〕我七旬死后偏何老，这孩儿一岁死后偏知小。俺两个一处身亡，落的个万代名标。我嘱咐你个后死的程婴，休别了[4]横亡的赵朔。畅道是光阴过去的疾，冤仇报复的早。将那厮万剐千刀，切莫要轻轻的素放了。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2578, "title": "陶学士醉写风光好", "author": "戴善夫", "body": "〔金盏儿〕我这里觑容颜，待追攀。嗨、畅好是冷丁丁沉默无情汉。则见那冬凌霜雪都堆在两眉间，恰便似额颅上挂着紫塞[1]，鼻凹里倘着蓝关[2]。可知道秀才双脸冷，宰相五更寒[3]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2579, "title": "陶学士醉写风光好", "author": "戴善夫", "body": "〔滚绣球〕这酒则是斟八分，学士索是饮一巡，则不要滴留喷噀。学士这玳筵间息怒停嗔，你则待点上灯关上门，那时节举杯丰韵。这里酒盏儿不肯沾唇，却不道相逢不饮空归去[4]，则这明月清风也笑人，常索教酒满金樽。\n〔叨叨令〕学士写时节有些腔儿韵，妾身讴时节有些词儿顺。做时节难诉千般恨，写时节则是三更尽。学士你记得也么哥，记得也么哥？兀的是亲笔写下牢收顿。\n〔滚绣球〕那素衣服是妾身，诈作驿吏妻把香火焚。我诵情诗暗传芳信，向明月中独立黄昏。见学士下砌跟，瞻北辰，转身躯猛然惊问，便和咱燕尔新婚。咱正是武陵溪畔曾相识，今日佯推不认人[5]，道的他满面似烧云。\n〔倘秀才〕妾身本不肯舒心就亲，学士便做不的先奸后婚，学士早回过，灯光掩上门。妾身谋成不谋败，学士宜假不宜真，不信不自隐。\n〔滚绣球〕好也啰学士你营勾了人，却便装忘魂。知他是甚娘情分，你则是憎嫌俺烟月风尘。昨夜个我虽改换的衣袂新，须是模样真。咱只得眼前厮趁，实丕丕与你情亲。你把万般做作千般怒，兀的甚一夜夫妻百夜恩，则是眼里无珍。\n〔三煞〕贱妾煞是展污了个经天纬地真英俊，为国于民大宰臣。贱妾煞不识高低，不知远近，不辨贤愚，不别清浑。这的是天注定的是非，天指引的前程，天匹配的婚姻！咱兀的教太守主婚，则这〔风光好〕是媒人。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2580, "title": "薛仁贵荣归故里[1]", "author": "张国宾", "body": "〔十二月〕敢则是一簇簇踏青拾翠，一攒攒傍陇寻畦。俺只见一道儿红尘荡起。元来的一骑马闪电奔驰。一从使都是浑身绣织，一将军怎倒着缟素裳衣？\n〔尧民歌〕呀！莫不是半空中降下雪神祇，他叫一声雄吼若春雷，諕的我心儿胆儿急獐拘猪的自昏迷；手儿脚儿滴羞笃速的似呆痴，禁也波持，身躯怎动移？我可便不待酒，佯妆醉。\n〔上小楼〕蓦听的人言马嘶，威风也那猛势。諕的我战战兢兢、慌慌张张，只待要哭哭啼啼。这一壁、那一壁，怎生逃避？好着我磕扑的在马前跪膝。\n〔满庭芳〕怎敢道是推东主西，我则怕言无关典，话不投机。孩儿每在龙门镇民户当夫役，今日正百五寒食，上坟的都是同乡共里，吃酒用瓦钵和这磁杯，怕官人待要来敛科税，我去村头行报知。官人也，你但道的我便依随。\n〔耍孩儿〕则你那老爹娘受苦，你身荣贵，全改换了个雄躯壮体，比那时将息的可便越丰肥，长出些苫唇的髭。我才咒骂了你几句，你权休怪，也是我间别来的多年把你不认的。哎！你看他马儿上簪簪的势，早忘和俺掏斑鸠争攀古树，摸虾蟆混入淤泥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2581, "title": "相国寺公孙合汗衫", "author": "张国宾", "body": "〔朝天子〕哎哟！可则俺两口儿都老迈，肯分的便正该。天那！天那！也是俺注定的合受这饥寒债。我如今无铺无盖，教我冷难挨。肯分的雪又紧，风偏大，到晚来，可便不敢番身，拳成做一块。天那！天那！则俺两口儿受冰雪堂地狱灾。我这里跪在大街，望着那发心的爷娘每拜。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2582, "title": "苏子瞻风雪贬黄州", "author": "费唐臣", "body": "〔混江龙〕想着那丝纶阁上，常则是紫薇花对紫薇郎。步九重春色，拂两袖天香。万里云烟挥翰墨，一天星斗焕文章。翰林风月，京洛山川，洞庭烟雨，金谷莺花，怎能够一轮皂盖飞头上。诗吟的神嚎鬼哭，文惊的地老天荒。\n〔鹊踏枝〕万言策上君王，一骑马度衡阳，索离了三岛蓬莱，直走遍九曲沧浪。学不的李太白逍遥在醉乡，参破了韩昌黎夕贬潮阳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2583, "title": "〔中吕〕粉蝶儿", "author": "姚守中", "body": "性鲁心愚，住烟村饱谙农务。丑则丑堪画堪图，杏花村，桃林野，春风几度。疏林外红日西晡，载吹笛牧童归去。\n〔醉春风〕绿野喜春耕，一犁江上雨。力田扶耙受驱驰，因为主甘分受苦。苦，苦，经了些横雨斜风，酷寒盛夏，暮烟晓雾。\n〔红绣鞋〕牧放在芳草岸白古渡，嬉游于绿杨堤红蓼平湖，画工描我在远山图。助田单英勇阵[1]，驾老子蓦山居，古今人吟未足。\n〔石榴花〕朝耕暮垦费工夫，辛苦为谁乎？一朝染患倒在官衢。见一个宰辅，借问农夫，气喘因何故，听说罢感叹长吁。那官人劝课还朝去，题着咱名字奏鸾舆。\n〔斗鹌鹑〕他道我润国于民，受千辛万苦。每日向堰口拖船，渡头拽车。一勇性天生胆气粗，从来不怕虎。为伍的是伴哥王留，受用的是村歌社鼓。\n〔上小楼〕感谢中书部，符行移诸处。所在官司，禁治严明，遍下乡都。里正行，社长行，叮咛省谕：宰耕牛的捕获申路。\n〔幺〕食我者肌肤未肥，卖我者家私不富。若是老病残疾，卒中身亡，不堪耕锄，告本官，送本都，从公发付。闪得我丑尸骸不着坟墓。\n〔满庭芳〕衙冤负屈，春工办足，却待闲居。圈门前见两个人来觑，多应是将我窥图。一个曾受戒南庄上的忻都，一个是累经断北王屠。好教我心惊虑，若是将咱卖与，一命在须臾。\n〔十二月〕心中畏惧，意下踌躇。莫不待将我衅钟[2]，不忍其觳觫[3]。那思想耕牛为主，他则是嗜利而图。被这厮添钱买我离桑枢，不睹是牵咱过前途。一声频叹气长吁，两眼凄惶泪如珠。凶徒，凶徒，贪财性狠毒，绑我在将军柱[4]。\n〔耍孩儿〕只见他手持刀器将咱觑，吓得我战扑速魂归地府。登时间满地血模糊，碎分张骨肉皮肤。尖刀儿割下薄刀儿切，官秤称来私秤上估。应捕人在旁边觑，张弹压先抬了膊项，李弓兵强要了胸脯。\n〔二〕却不道闻其声不忍食其肉[5]，刬地加料物宽锅中烂煮。煮得美甘甘香喷喷软如酥，把从前的主雇招呼。他则道三分为本十分利，那里问一失人身万劫无。有一等贪啜的乔人物，就本店随机儿索唤，买归家取意儿庖厨。\n〔三〕或是包馒头待上宾，或是裹馄饨请伴侣。向磁罐中软火儿葱椒，胜如黄犬能医冷，赛过胡羊善补虚。添几盏椒花露。你装的肚皮饱旺，我的性命何辜！\n〔四〕我本是时苗留下犊，田单用过牯。勤耕苦战功无补。他比那图财害命情尤重，我比那展草垂缰义有余。我是一个直钱底物：有我时田园开辟，无我时仓廪空虚。\n〔五〕泥牛能报春[6]，石牛能致雨[7]，耕牛运土遭诛戮。从今后草坡边野鹿无朋友，麦垄上山羊失了伴侣。那的是我伤情处，再不见柳梢残月，再不见古木昏乌。\n〔六〕觔儿铺了弓，皮儿挽做鼓，骨头儿卖与钗环铺。黑角儿做就乌犀带，花蹄儿开成玳瑁梳。无一件抛残物，好材儿卖与了靴匠，碎皮儿回与田夫。\n〔尾〕我元阳寿未终，死得真个屈苦。告你个阎罗王正直无私曲，诉不尽平生受过苦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2584, "title": "沙门岛张生煮海", "author": "李好古", "body": "〔那吒令〕听疏剌剌晚风，风声落万松；明朗朗月容，容光照半空；响潺潺水冲，冲流绝涧中。又不是采莲女拨棹声，又不是捕鱼叟鸣榔动，惊的那夜眠人睡眼朦胧。\n〔鹊踏枝〕又不是拖环珮，韵玎，又不是战铁马，响铮；又不是佛院僧房，击磬敲钟。一声声諕的我心中怕恐，原来是厮琅琅，谁抚丝桐。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2585, "title": "沙门岛张生煮海", "author": "李好古", "body": "〔南吕·一枝花〕黑弥漫水容沧海宽，高崪峍山势昆仑大；明滴溜冰轮出海角，光灿烂红日转山崖。这日月往来，只山海依然在，弥八方遍九垓。问甚么河汉江淮，是水呵都归大海。\n〔梁州第七〕你看那缥渺间十洲三岛，微茫处阆苑蓬莱，望黄河一股儿浑流派。高冲九曜，远映三台，上连银汉，下接黄埃，势汪洋无岸无涯，出许多异宝奇哉。看看看波涛涌光隐隐无价珠玑，是是是草木长香喷喷长生药材，有有有蛟龙偃郁沉沉精怪灵胎。常则是云昏、气霭，碧油油隔断红尘界，恍疑在九天外。平吞了八九区云梦泽，问甚么翠岛苍崖。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2586, "title": "沙门岛张生煮海", "author": "李好古", "body": "〔正宫·端正好〕一地里受煎熬，满海内空劳攘，兀的不慌杀了海上龙王。我则见水晶宫血气从空撞，闻不得鼻口内干烟炝。\n〔滚绣球〕那秀才谁承望，急煎煎做这场。不知他挟着的甚般伎俩，只待要卖弄杀手段高强。莫不是放火光，逼太阳，烧的来焰腾腾滚波翻浪。纵有那雷和雨，也救不得惊惶。则见锦鳞鱼活泼剌波心跳，银脚蟹乱扒沙在岸上藏。但着一点儿，就是一个燎浆。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2587, "title": "沙门岛张生煮海", "author": "李好古", "body": "〔得胜令〕你待将铅汞燎干枯，早难道水火不同炉。将大海扬尘度，把东洋烈焰煮。神术锻化的为夫妇。几乎熬煎杀俺眷属。\n〔沽美酒〕待着俺辞龙宫，离水府，上碧落，赴云衢。我和你同会西池见圣母，秀才也，抵多少跳龙门应举，攀仙桂步蟾蜍。\n〔太平令〕广成子长生诗句，东华仙看定婚书。引仙女仙童齐赴，献仙酒仙桃相助。愿普天下旷夫怨女，便休教间阻。至诚的，一个个皆如所欲。\n〔收尾〕则今日双双携手登仙去，也不枉鲛绡帕留为信物。闲看他蟠桃灼灼树头红，撇罢了尘世茫茫海中苦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2588, "title": "忠义士豫让吞炭", "author": "杨梓", "body": "〔耍孩儿〕今日个会兵机的襄子夸英勇，显的没下梢的将军落空。你将他碜可可斩在乱军中，把一个死尸骸暴露霜风。刬地漆头为器斟琼液，可甚翠袖殷勤捧玉钟，未出语心先痛。杀人可恕，情理难容。\n〔三煞〕豁不了我这满腹冤，干休了半世功，急煎煎独力难敌众。（拔剑将襄子衣服碎剁科，云）罢罢，我今日剑锉了你这衣服，就和杀了你一般。死亦无恨。（唱）虽不能够碎分肢体诛了襄子，烂锉了这件衣服便是报了俺主公。至如把残生送，下埋黄土，仰问苍空。\n〔二煞〕士为知己死，女为悦己容。（云）豫让蒙俺主君知爱，超出流辈，今日安忍背主事仇！（唱）我怎肯做诸侯烈士每相讥讽，我怎肯躬身叉手降麾下，我宁可睁眼舒头伏剑锋。枉了你闲唧哝。折末官高一品，禄享千钟。\n〔尾声〕我不想声闻在人世间，名标在史记中。你把我主人公葬在麒麟冢。谁受你徼买人情赵王宠。（自刎下）", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2589, "title": "功臣宴敬德不伏老", "author": "杨梓", "body": "〔那吒令〕知尉迟，辕门外的众军；讲尉迟，普天下的万民；谮尉迟，是你这样小人。我将这鏖战册件件与你观，功劳簿桩桩与你论，那其间便见得元勋。\n〔鹊踏枝〕我也曾在沙场上领着敌军，舍着残生；我也曾楂鼓夺旗，抓将挟人；我也曾杀得败残兵骨碌碌人头乱滚，碜可可热血相喷。\n〔寄生草〕太平时文胜似武，事急也武胜似文。我也曾苦相持恶战讨遭危困，扶持的国家安天下定狼烟静，生熬的剑锋缺鞭节曲枪尖钝。我只待要一心儿分破帝王忧，只我这两条眉锁江山恨。\n〔六幺序〕想为官的如骑着虎，他用人似积薪，教后来人在上居尊，李道宗这厮呵他非武非文，他曾立甚么功勋？怎敢欺侮俺开国的功臣？他走将来上首头无些谦逊，论功处谁敢欺人。若不是军师救了咱危困，他须是一枝一叶，俺须是四海他人。\n〔幺篇〕他不索胡云，休论，我性不容人，拳打了谗臣，恁般生嗔，若不是军师可便劝准。我没来由献甚么勤？知他是君负其臣，臣负其君？若留得恶楚强秦，怎生便敢诛了韩信？古人言信不虚云。想淮阴与鄂国咱两个同时运，一任那渔樵闲话，少不得青史标名。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2590, "title": "功臣宴敬德不伏老", "author": "杨梓", "body": "〔耍三台〕你须知咱名讳，尽忠心天知地知。这一场小可如美良川交兵的手段，御科园单鞭夺槊的雄威。小可如牛口谷鞭伏了窦建德，小可如下河东与刘黑闼相持。你看我再施逞生擒王世充的英雄，你看我重施展活捉雷世猛当时的气力。\n〔幺篇〕我老只老呵，老了咱些年纪。老只老呵，老不了我胸中武艺。老只老呵，老不了我龙韬虎略。老只老呵，老不了我妙策神机。老只老呵，老不了我一片忠心贯日。老只老呵，尚兀自万夫难敌。（徐云）老将军，你便索要去，只怕你老了去不得。（末唱）俺老只老，止不过添了些雪鬓霜髭。老只老，又不曾驼腰曲背。\n〔尾声〕老只老呵，只我这水磨鞭不曾长出些白髭须，量这厮何须咱费力。（带云）你看这厮，明日在垓心里，绰见我那铁扑头，红抹额，乌油甲，皂罗袍。（唱）他便跳下马受绳缚，着这厮卷了旗，卸了甲，收了军，拱手儿降俺这大唐国。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2591, "title": "李太白贬夜郎", "author": "王伯成", "body": "〔六幺序〕何时静，尽日狂，但行处酒债寻常。粜尽黄粱，典尽衣裳，知他在谁家里也琴剑书箱！这酒似长江后浪催前浪，洒歌楼醉墨琳琅。笔尖儿鼓角声悲壮，驱雷霆号令，焕星斗文章。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2592, "title": "李太白贬夜郎", "author": "王伯成", "body": "〔殿前欢〕酒如川，鹭鸥长聚武陵源，鸳鸯不锁黄金殿，绿蓑衣带雨和烟。酒里坐，酒里眠。红蓼岸，黄芦堰，更压着金马门，琼林宴。岸边学渊明种柳，水面学太乙浮莲。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2593, "title": "吕洞宾度铁拐李岳", "author": "岳伯川", "body": "〔混江龙〕想前日解来强盗，都只为昧心钱买转了这管紫霜毫，减一笔教当刑的责断，添一笔教为从的该敲。这一管扭曲作直取状笔，更狠似图财致命杀人刀。出来的都关来节去，私多公少。可曾有一件儿合天道！他每都指山卖磨，将百姓画地为牢。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2594, "title": "吕洞宾度铁拐李岳", "author": "岳伯川", "body": "〔庆东原〕为甚我今日身不正，则为我往常心不直。和那鬼魂灵不能勾两脚踏实地。至如省里部里，台里院里，咱只说府里州里，他官人每一个个要为国不为家，怎知道也似我说的行不的。\n〔太清歌〕他退猪汤不热如俺浓研的墨，他杀狗刀不快如俺完成笔。他虽是杀生害命为家计，这恶业休提。俺请受了人几文钱改是成非，似这般所为，碜可可的活取民心髓，抵多少猪肝猪蹄。也则是秤大小为生过日，不强似俺着人脓血换人衣。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2595, "title": "梁山泊李逵负荆", "author": "康进之", "body": "〔混江龙〕可正是清明时候，却言“风雨替花愁”。和风渐起，暮雨初收。俺则见杨柳半藏沽酒市，桃花深映钓鱼舟。更和这碧粼粼春水波纹绉，有往来社燕，远近沙鸥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2596, "title": "梁山泊李逵负荆", "author": "康进之", "body": "〔正宫·端正好〕抖搜着黑精神，扎煞开黄髭，则今番不许收拾。俺可也磨拳擦掌，行行里，按不住莽撞心头气。\n〔滚绣球〕宋江，这是甚所为，甚道理？不知他主着何意，激的我怒气如雷。可不道[3]他是谁，我是谁，俺两个半生来岂有些嫌隙；到今日却做了日月交食。不争几句闲言语，我则怕恶识多年旧面皮，展转猜疑。\n〔倘秀才〕哎！你个刎颈的知交庆喜。（宋江云）庆什么喜？（正末唱）则你那压寨的夫人在那里？（指鲁智深科，云）秃驴，你做的好事来！（唱）打干净球儿不道的[4]走了你。（宋江云）怎么？智深兄弟，也有你那？（正末唱）强赌当，硬支持，要见个到底。\n〔滚绣球〕俺哥哥要娶妻，这秃厮会做媒。（宋江云）智深兄弟，说你曾做什么媒来。（鲁智深云）你看这厮，到下山去噇[5]了多少酒，醉的来似踹不杀的老鼠一般，知他支支的说甚么哩。（正末唱）元来个梁山泊有天无日。（做拔斧斫旗科）（唱）就恨不斫倒这一面黄旗！（众做夺斧科）（宋江云）你这铁牛，有甚么事，也不查个明白，就提起板斧来，要斫倒我杏黄旗，是何道理？（学究云）山儿，你也忒口快心直哩！（正末唱）你道我忒口快，忒心直，还待要献勤出力。（做喊科，云）众兄弟们，都来！（宋江云）都来做甚么？（正末唱）则不如做个会六亲庆喜的筵席。（宋江云）做什么筵席？（正末唱）走不了你个撮合山师父唐三藏，更和这新女婿郎君，哎，你个柳盗跖，看那个便宜。\n〔一煞〕则为你两头白面搬兴废，转背言词说是非。这厮敢狗行狼心，虎头蛇尾。不是我节外生枝，囊里盛锥。谁要你夺人爱女，逞己风流，被咱都知。（宋江云）你看黑牛这村沙样势那。（正末唱）休怪我村沙样势，平地上起孤堆。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2597, "title": "梁山泊李逵负荆", "author": "康进之", "body": "〔双调·新水令〕这一场烦恼可也奔人来，没来由共哥哥赌赛。袒下我这红纳袄，跌绽我这旧皮鞋。心下量猜：（带云）到山寨上，哥哥不打，则要头，（唱）怎发付脖项上这一块[9]？\n〔驻马听〕有心待不顾形骸，（带云）这碧湛湛石崖，不得底的深涧，我待跳下去，休说一个，便是十个黑旋风，也不见了。（唱）两三番自投碧湛崖。敬临山寨，行一步如上吓魂台。我死后，墓顶头谁定远乡牌[10]，灵位边谁咒生天界[11]？怎擘划[12]，但得个完全尸首，便是十分采。\n〔搅筝琶〕我来到辕门外，见小校雁行排。（带云）往常时我来呵，（唱）他这般退后趋前；（带云）怎么今日的，（唱）他将我佯呆不采。（做偷瞧科，云）哦！原来是俺宋公明哥哥和众兄弟，都升堂了也。（唱）他对着那有期会的众英才，一个个稳坐抬颏[13]。我说的明白，道莽撞的廉颇请罪来，死也应该。\n〔沉醉东风〕呼保义哥哥见责，我李山儿情愿餐柴。第一来看着咱兄弟情，第二来少欠他脓血债[14]。休道您兄弟不伏烧埋[15]，由你便直打到梨花月上来，若不打，这顽皮不改。\n〔步步娇〕则听得宝剑声鸣，使我心惊骇，端的个风团快[16]。似这般好器械，一柞[17]来铜钱，恰便似砍麻秸。（带云）想您兄弟十载相依，那般恩义，都也不消说了。（唱）还说甚旧情怀，早砍取我半壁天灵盖。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2598, "title": "秦修然竹坞听琴", "author": "石子章", "body": "〔中吕·粉蝶儿〕这些时懒诵《南华》，将一串数珠来壁间闲挂；念一首断肠词颠倒熟滑。不免的唤道姑、添净水，我刚刚的把圣贤来参罢；若不是会首人家，几番将这道袍脱下。\n〔醉春风〕我如今将草索儿系住心猿，又将藕丝儿缚定意马。人说道出家的都待要断尘情，我道来都是些假、假！几时能勾月枕双欹，玉箫齐品，翠鸾同跨？\n〔红绣鞋〕我恰才搭伏定芙蓉懒架，恰合眼梦见他家，觉来也依旧隔天涯。早是我心绪又乱，更那堪客人侵杂，道甚么相公在门首前方下马。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2599, "title": "黄桂娘秋夜竹窗雨", "author": "石子章", "body": "〔仙吕·点绛唇〕红雨纷纷，落花成阵，东风紧。空忙煞蝶使蜂神，却又早零落芳菲尽。\n〔混江龙〕枝头春褪，一春鱼雁赏花频。想花开一季，春色三分；多半狂风多半雨，一分流水二分尘。我这里出兰堂，离绣阁，鸣玉佩，撒金莲[1]，转回廊，临曲槛，早来到十二曲雕阑近。本待要寻芳选胜，却交人对景伤神。\n〔油葫芦〕枝上流莺和泪闻，为甚这粉汗湮？我常是新啼痕间旧啼痕。我这里懒妆只为心间恨。举杯试向花前问：人能得几日好？花能得几日新？却又早海棠过了酴醾尽，憔悴煞惜花人。\n〔天下乐〕可早花落花开断送春。恨东均[2]，无定准，九十日却如一梦魂。畅好是花谢的疾，春去的紧，撺断了人生有限身！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2600, "title": "老庄周一枕蝴蝶梦", "author": "史九敬先", "body": "〔仙吕·点绛唇〕飞下天宫，将帝宣钦奉。因他宿缘重，但得相逢，是一枕蝴蝶梦。\n〔混江龙〕世俗迎送，都是些是非人我虎狼丛。流的紧黄河九曲，坐的稳华岳三峰。依旧春风人世所，黄河一去永无踪。生太素[1]阴阳未判，辨清浊混沌[2]初分；推物理[3]三皇治世，定人伦五帝兴隆。宠女色夏桀无道，自荒淫太甲居桐；废殷祀纣辛[4]失位，建周朝文武成功。为宰臣职居相府，作公侯禄厚千钟；名利似汤浇瑞雪，荣华如秉烛当风。度寒暑雁鸿南北，搬兴废乌兔西东；天地久消磨造化，黄尘老埋没英雄。人有限，事无穷；观二气，渐消熔。一会家叹干戈千载战争场，可怜人一枕南柯梦。恰开眼蜂衙蚁阵，转回头兔迹狐踪。\n〔油葫芦〕不如我跨风乘鸾朝玉京，仙家日月永。你只待浩歌一曲酒千钟。见如今春秋七国刀兵动，不如我柳阴中一枕南柯梦。俺昆仑顶上人，比凌烟阁上臣。试看咸阳原上麒麟冢，都一般潇洒月明中！\n〔天下乐〕转首繁华扫地空，你看乾坤，造化功。笑凡夫与吾心不同。我欲待说是西，他却来道做东。想尘埃谁识神仙种，空教我嘻笑不言中！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2601, "title": "〔中吕〕最高歌兼喜春来", "author": "张养浩", "body": "诗磨的剔透玲珑，酒灌的痴呆懵懂。高车大纛[1]成何用，一部笙歌断送。金波潋滟浮银瓮，翠袖殷勤捧玉钟[2]。对一缕绿杨烟[3]，看一弯梨花月[4]，卧一枕海棠风[5]。似这般闲受用，再谁想、丞相府帝王宫。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2602, "title": "〔中吕〕喜春来", "author": "张养浩", "body": "路逢饿殍须亲问，道遇流民必细询。满城都道好官人。还自哂，只落的白发满头新。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2603, "title": "〔中吕〕朱履曲", "author": "张养浩", "body": "那的是为官荣贵。止不过多吃些筵席，更不呵安插些旧相知。家庭中添些盖作，囊箧里攒些东西。教好人每看做甚的。\n才上马齐声儿喝道，只这的便是送了人的根苗。直引到深坑里恰心焦。祸来也何处躲，天怒也怎生饶。把旧来时威风不见了。\n正胶漆当思勇退，到参商才说归期。只恐范蠡、张良笑人痴。捵着胸登要路，睁着眼履危机，直到那其间谁救你。\n弄世界机关识破。叩天门意气消磨。人潦倒青山慢嵯峨。前面有千古远，后头有万年多。量半炊时成得甚么。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2604, "title": "〔中吕〕普天乐", "author": "张养浩", "body": "折腰惭，迎尘拜。槐根梦觉，苦尽甘来。花也喜欢，山也相爱，万古东篱天留在，做高人轮到吾侪。山妻稚子，团栾笑语，其乐无涯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2605, "title": "〔中吕〕普天乐", "author": "张养浩", "body": "楚《离骚》，谁能解？就中之意，日月明白。恨尚存，人何在？空快活了湘江鱼虾蟹。这先生畅好是胡来。怎如向青山影里，狂歌痛饮，其乐无涯！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2606, "title": "〔中吕〕普天乐", "author": "张养浩", "body": "好田园，佳山水。闲中真乐，几个人知？自在身，从吟醉。一片闲云无拘系，说神仙恰是真的。任鸡虫失得，夔蚿[6]多寡，鹏[7]高低。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2607, "title": "〔中吕〕朝天曲", "author": "张养浩", "body": "挂冠，弃官，偷走下连云栈。湖山佳处屋两间，掩映垂杨岸。满地白云，东风吹散，却遮了一半山。严子陵钓滩，韩元帅将坛，那一个无忧患？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2608, "title": "〔中吕〕朝天曲", "author": "张养浩", "body": "柳堤，竹溪，日影筛金翠。杖藜徐步近钓矶。看鸥鹭闲游戏。农父渔翁，贪营活计，不知他在图画里。对这般景致，坐的，便无酒也令人醉。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2609, "title": "〔中吕〕山坡羊", "author": "张养浩", "body": "骊山四顾，阿房一炬，当时奢侈今何处？只见草萧疏，水萦纡，至今遗恨迷烟树。列国周齐秦汉楚。赢，都变做了土；输，都变做了土！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2610, "title": "〔中吕〕山坡羊", "author": "张养浩", "body": "悲风成阵，荒烟埋恨，碑铭残缺应难认。知他是汉朝君，晋朝臣？把风云庆会消磨尽，都做北邙山下尘。便是君，也唤不应；便是臣，也唤不应。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2611, "title": "〔中吕〕山坡羊", "author": "张养浩", "body": "峰峦如聚，波涛如怒。山河表里潼关路。望西都，意踌蹰。伤心秦汉经行处，宫阙万间都做了土。兴，百姓苦！亡，百姓苦！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2612, "title": "〔中吕〕山坡羊", "author": "张养浩", "body": "三杰当日，俱曾此地，殷勤纳谏论兴废。见遗基，怎不伤悲！山河犹带英雄气。试上最高处闲坐地：东，也在图画里；西，也在图画里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2613, "title": "〔双调〕沽美酒兼太平令", "author": "张养浩", "body": "在官时只说闲，得闲也又思官，直到教人做样看。从前的试观，那一个不遇灾难：楚大夫行吟泽畔，伍将军血污衣冠，乌江岸消磨了好汉，咸阳市干休了丞相。这几个百般、要安，不安，怎如俺五柳庄逍遥散诞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2614, "title": "〔双调〕胡十八", "author": "张养浩", "body": "正妙年，不觉的老来到。思往常，似昨朝。好光阴流水不相饶。都不如醉了，睡着。任金乌搬废兴，我只推不知道。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2615, "title": "〔双调〕殿前欢", "author": "张养浩", "body": "可怜秋，一帘疏雨暗西楼。黄花零落重阳后，减尽风流。对黄花人自羞。花依旧，人比黄花瘦。问花不语，花替人愁。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2616, "title": "〔双调〕雁儿落兼得胜令", "author": "张养浩", "body": "[8]秉笏：秉，持；笏，朝笏，又叫手版，古代君臣在朝廷上相见时手中所持的狭长板片，用以比画或在上面记事。丹墀：帝王宫殿的台阶。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2617, "title": "〔双调〕雁儿落兼得胜令", "author": "张养浩", "body": "云来山更佳，云去山如画，山因云晦明，云共山高下。倚仗立云沙，回首见山家。野鹿眠山草，山猿戏野花。云霞，我爱山无价。看时行踏，云山也爱咱。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2618, "title": "〔双调〕雁儿落兼得胜令", "author": "张养浩", "body": "也不学严子陵七里滩，也不学姜太公磻溪岸，也不学贺知章乞鉴湖，也不学柳子厚游南涧。俺住云水屋三间，风月竹千竿，一任傀儡棚中闹，且向昆仑顶上看。身安，倒大来无忧患；游观，壶中天地宽。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2619, "title": "〔双调〕得胜令", "author": "张养浩", "body": "万象欲焦枯，一雨足沾濡。天地回生意，风云起壮图。农夫，舞破蓑衣绿；和余，欢喜的无是处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2620, "title": "〔双调〕水仙子", "author": "张养浩", "body": "一江烟水照晴岚，两岸人家接画檐，芰荷丛一段秋光淡，看沙鸥舞再三，卷香风十里珠帘。画船儿天边至，酒旗儿风外飐，爱杀江南。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2621, "title": "〔双调〕沉醉东风", "author": "张养浩", "body": "班定远飘零玉关。楚灵均憔悴江干。李斯有黄犬悲，陆机有华亭叹。张柬之老来遭难，把个苏子瞻长流了四五番。因此上功名意懒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2622, "title": "〔双调〕折桂令", "author": "张养浩", "body": "一轮飞镜谁磨？照彻乾坤，印透山河。玉露泠泠，洗秋空银汉无波，比常夜清光更多，尽无碍桂影婆娑。老子高歌，为问嫦娥，良夜恹恹，不醉如何？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2623, "title": "〔越调〕寨儿令", "author": "张养浩", "body": "天欲明，觉寒生，打书窗只闻风有声。步出柴荆，遥望郊坰，滚滚势如倾。四围山岩壑都平，道途间无个人行。爱园林春浩荡，喜天地气澄清。巧丹青，怎画绰然亭。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2624, "title": "〔双调〕新水令", "author": "张养浩", "body": "急流中勇退不争多，厌喧烦静中闲坐。利名场说著逆耳，烟霞疾做了沉疴。若不是天意相合，这清福怎能个。\n〔川拨棹〕每日家笑呵呵，陶渊明不似我。跳出天罗，占断烟波；竹坞松坡，到处婆娑。到大来清闲快活，看时节醉了呵。\n〔七弟兄〕唱个，弹个[9]，似风魔，把功名富贵都参破。有花有酒有行窝[10]，无烦无恼无灾祸。\n〔梅花酒〕年纪又半百过，壮志消磨，暮景蹉跎，鬓发浑皤。想人生能几何，叹日月似撺梭。自相度，图个甚，谩张罗，得磨跎且磨跎。共邻叟两三个，无拘束即脾和[11]。\n〔收江南〕向花前莫惜醉颜酡，古和今都是一南柯。紫罗襕未必胜渔蓑，休只管恋他。急回头好景亦无多。\n〔离亭宴煞〕高竿上本事从逻逻[12]，委实的赛他不过。非是俺全身远害，免教人信口开喝。我把这势利绝，农桑不能理会庄家过活。青史内不标名，红尘外便是我。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2625, "title": "〔南吕〕一枝花", "author": "张养浩", "body": "用尽我为民为国心，祈下些值玉值金雨。数年空盼望，一旦遂沾濡[13]。唤省焦枯[14]。喜万象春如故，恨流民尚在途。留不住都弃业抛家。当不的也离乡背土。\n〔梁州〕恨不的把野草翻腾做菽粟，澄河沙都变化做金珠。直使千门万户家豪富，我也不枉了受天禄[15]，眼觑着灾伤教我没是处，只落的雪满头颅。\n〔尾声〕青天多谢相扶助，赤子从今罢叹吁。只愿的三日霖霪[16]不停住，便下当街上似五湖，都淹了九衢，犹自洗不尽从前受过的苦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2626, "title": "〔正宫〕鹦鹉曲", "author": "白贲", "body": "侬家鹦鹉洲边住，是个不识字渔父。浪花中一叶扁舟，睡煞江南烟雨。〔幺〕觉来时满眼青山，抖擞绿蓑归去。算从前错怨天公，甚也有安排我处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2627, "title": "张孔目智勘魔合罗", "author": "孟汉卿", "body": "〔混江龙〕连阴不住，荒郊一望水模糊。我则见雨迷了山岫，云锁了青虚。云气深如倒悬着东大海，雨势大似翻合了洞庭湖，好教我满眼儿没处寻归路。黑暗暗云迷四野，白茫茫水淹长途。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2628, "title": "张孔目智勘魔合罗", "author": "孟汉卿", "body": "〔叫声〕你曾把愚痴的小孩提教诲，教诲的心聪慧，若把这冤屈事，说与勘官知。\n〔醉春风〕不强似你教幼女演裁缝，劝佳人学绣刺。要分别那不明白的重刑名，魔合罗，全在你，你。若出脱了这妇衔冤，我教人将你享祭，煞强如小儿博戏。\n〔滚绣球〕我与你曲湾湾画翠眉，宽绰绰穿绛衣，明晃晃凤冠霞帔，妆严的你这样何为？你若是到七月七，那其间乞巧的，将你做一家儿燕喜；你可便显神通，百事依随。比及你露十指玉笋穿针线，你怎不启一点朱唇说是非，教万代人知。\n〔倘秀才〕枉塑你似观音像仪，怎无那半点儿慈悲面皮？空着我盘问你，你将我不应对，我彻上下，细观窥，到底。\n〔蛮姑儿〕我则道在那壁，原来在这里。谁想这底座儿下包藏着杀人贼。呼左右，上阶基，谁把高山认的？\n〔柳青娘〕只着这些儿见识，瞒过这老无知，却不你千悔万悔，泼水在地怎收拾。吓的个黄甘甘脸儿如地皮。可不道一言既出，便有驷马难追。已招伏，怎改易，要承抵。\n〔道和〕方知端的，知端的，虚事不能实。忒跷蹊，教俺教俺难根缉，教俺教俺耽干系，使心机，啜赚出是和非。难支吾，难支对，难分说，难分细。那些那些咱欢喜，咱伶俐，一行人个个服情罪。若非若非有天理，这当堂假限刚三日，可不的势剑倒是咱先吃！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2629, "title": "包待制智赚灰阑记", "author": "李行道", "body": "〔混江龙〕毕罢了浅斟低唱，撇下了数行莺燕占排场。不是我攀高接贵，由他每说短论长。再不去卖笑追欢风月馆，再不去迎新送旧翠红乡。我可也再不怕官司勾唤，再不要门户承当，再不放宾朋出入，再不见邻里推抢，再不愁家私营运，再不管世事商量。每日价喜孜孜一双情意两相投，直睡到暖溶溶三竿日影在纱窗上。伴着个有疼热的夫主，更送着个会板障的亲娘。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2630, "title": "包待制智赚灰阑记", "author": "李行道", "body": "〔挂玉钩〕则这个有疼热亲娘怎下得，（带云）爷爷，你试觑波！（唱）孩儿也这臂膊似麻稭细。他是个无情分尧婆管甚的！你可怎生来参不透其中意！他使着侥幸心，咱受着腌气。不争俺两硬相夺，使孩儿损骨伤肌。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2631, "title": "晋文公火烧介子推", "author": "狄君厚", "body": "〔越调·斗鹌鹑〕焰腾腾火起红霞，黑洞洞烟飞墨云，闹垓垓火块纵横，急穰穰烟煤乱滚。悄蹙蹙火巷外潜藏，古爽爽烟峡内侧隐。我子见烦烦的烟气熏，纷纷的火焰喷，急煎煎地火燎心焦，密匝匝烟屯合峪门。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2632, "title": "地藏王证东窗事犯", "author": "孔文卿", "body": "〔混江龙〕想挟人捉将，相持厮杀数千场；则落得披枷带锁，枉了俺展土开疆。信着个挟天子令诸侯紫绶臣，待损俺守边塞破敌军铁衣郎！俺与你扫除妖气，洗荡妖氛，不能够名标簿上。刬地屈问厅前，想儿曹歹谋帝王前，不由英雄泪滴枷梢上。想着俺掌帅府将军一令，到不出的坐都堂约法三章！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2633, "title": "地藏王证东窗事犯", "author": "孔文卿", "body": "〔越调·斗鹌鹑〕但行处怨雾凄迷，悲风乱吼。恰离枉死城中，早转到阴山背后。不能青史内标名，只落的钢刀下斩首。每日秦不管，魏不收，送的俺酩子里遭诛。更怕我葫芦提罢乎。\n〔紫花儿序〕三魂儿潇潇洒洒，七魄儿怨怨哀哀，一灵儿荡荡悠悠。俺不是降灾邪祟，俺是出力公侯。你问缘由，我对圣主明言剐骨仇。俺说的并无虚谬。谢上圣将这屈死冤魂，放入这凤阁龙楼。\n〔小桃红〕躬身叉手紧低头，又不敢把龙床扣，拜舞山呼痛僝僽。见官里[1]猛抬头，惊回御寝把天颜奏，灯影下诚惶顿首。臣说着伤心感旧，尚古自[2]眉锁庙堂愁。\n〔鬼三台〕臣在生时多生受，驰甲胄，做先锋帅首，向沙塞拥貔貅。臣说着呵自羞，想微臣挟人捉将一旦休，只落的披枷带锁遭重囚。臣想统三军永远长春，不想半路里拔着短筹。\n〔紫花儿序〕臣性命不若如花梢滴露、风里杨花、水上浮沤。臣统三军、舍命与四国王做敌头，将四京九府平收。不想臣扶侍君王不到头，提起来雨泪交流。想微臣盖世功名，到今日一笔都勾。\n〔金蕉叶〕臣舍性命沙场上战斗，臣出气力军前阵后。刬地撇俺在三闲里不愀。臣意社稷江山宇宙。\n〔调笑令〕陛下，索趁逐，替微臣报冤仇。臣须是一日无常万事休，不能勾悬牌挂印将君恩受。只落的扒吊拷百事有，早难道臣宰千秋。\n〔秃厮儿〕臣望写皇阁千年不朽，标青史万代名留。臣做了个充饥画饼风内烛。这冤仇、这冤仇、怎肯干休。\n〔圣药王〕臣这方头、又不曾写犯由，也合三思然后再追求。臣海外、收复了四百州。将凌烟阁番作抱官囚，久以后再谁想分破帝王忧。\n〔络丝娘〕臣舍性命出气力请粗粮将边庭镇守。秦桧没功劳请俸干吃了堂食御酒。他待将咱宋室江山一笔勾，好金帛和大金家结构。\n〔绵搭絮〕臣趁着悲风淅淅、怨气哀哀。天公不管，地府难收，相伴着野草闲花满地愁。不能够敕赐官封万户侯。想世事悠悠，叹英雄逐水流。\n〔拙鲁速〕臣将抽头、不抽头，向杀人处，便攒头。秦桧安排钓钩，正着他机彀，怎生收救！臣当初只见食不见钩。\n〔幺〕想微臣志未酬。除秦桧一命休，陛下逼逐记在心头。将缘由苦苦遗留、明明说透。把那禽兽剐割肌肉，号令签头，豁不尽心上忧。\n〔收尾〕忠臣难出贼臣彀，陛下宣的文武公卿讲究：用刀斧将秦桧市曹中诛，唤俺这屈死冤魂奠盏酒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2634, "title": "谢金莲诗酒红梨花", "author": "张寿卿", "body": "〔后庭花〕俺将俏书生去问他，又怕这劣[1]梅香瞧见咱。俺这里有意传心事，他那里无言指落花。争奈我是女孩儿家，做这一场话靶，可不的被傍人活笑杀。\n〔金盏儿〕这秀才忒撑达[2]。将我问根芽。妾身住处兀那东直下，深村旷野不堪夸。俺那里遮藏红杏树，掩映碧桃花。兀良，山前五六里，林外两三家。\n〔醉中天〕笑哈哈捧流霞[3]，我羞怯怯怎酬答。也不知前世今生甚的缘法，相会在花枝下。可知道刘郎喜杀，又值着我玉真未嫁，抵多少香饭胡麻。\n〔赚煞〕这早晚二更过，初更罢，扑粉面香风飒飒。夜静归来路儿滑，露溶溶湿润衣纱。哎！你个解元嗏！觑着这几朵梨花，更一片银河隔彩霞。贪和你书生打话，畅好是兜兜搭搭，因此上不知明月落谁家。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2635, "title": "死生交范张鸡黍", "author": "宫天挺", "body": "〔天下乐〕你道是文章好立身；我道今人，都为名利引，怪不着赤紧的翰林院那伙老子每钱上紧。他歪吟的几句诗，胡诌下一道文，都是些要人钱的谄佞臣。\n〔那吒令〕国子监里助教的，尚书是他故人；秘书监里著作的，参政是他丈人；翰林院应举的，是左丞相的舍人。则《春秋》不知怎的发，《周礼》不知如何论，知制诰是怎的行文？\n〔鹊踏枝〕我堪恨那伙老乔民，用这等小猢狲。但学得些妆点皮肤、“子曰”“《诗》云”，本待要借路儿苟图一个出身，他每现如今都齐了行不用别人。\n〔寄生草〕将凤凰池拦了前路，麒麟阁顶杀后门。便有那汉相如献赋难求进，贾长沙痛哭谁偢问，董仲舒对策无公论。便有那公孙弘撞不开昭文馆内虎牢关，司马迁打不破编修院里长蛇阵。\n〔幺篇〕口边厢奶腥也犹未落，顶门上胎发也尚自存。生下来便落在那爷羹娘饭长生运，正行着兄先弟后财帛运，又交着夫荣妻贵催官运。你大拼着十年家富小儿娇，也少不的一朝马死黄金尽。\n〔六幺序〕您子父每轮替着当朝贵，倒班儿居要津，则欺瞒着帝子王孙。猛力如轮，诡计如神，谁识您那一伙害军民聚敛之臣。现如今那栋梁材平地上刚三寸，您说波怎支撑那万里乾坤？都是些装肥羊法酒人皮囤，一个个智无四两、肉重千匠。\n〔幺篇〕这一伙魔军，又无甚功勋，却着他画戟朱门，列鼎重裀，赤金白银，翠袖红裙，花酒盈樽，羊马成群。有一日天打算衣绝禄尽，下场头少不的吊脊抽筋。小子白身，乐道安贫，觑此辈何足云云。满胸襟拍塞怀孤愤，将云间太华平吞！想为人怎敢言而无信？枉了咱顶天立地，束发冠巾。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2636, "title": "严子陵垂钓七里滩", "author": "宫天挺", "body": "〔青哥儿〕那里面暗隐着风波、风波千丈。你说波使磁瓯的有甚灾伤？我醉了呵东倒西歪尽不妨。我若烂醉在村乡，着李二公扶将，到草舍茅堂，靠瓮牖蓬窗，新苇席清凉，旧木枕边厢，袒脱下衣裳，放散诞心肠，任百事无妨，倒大来免虑忘忧，纳被蒙头，任意翻身，强如您宰相侯王，遭断没属官象牙床，泥金亢。\n〔赚煞〕平地上窝弓，水面上张罗网，再谁想相寻相访。鸿鹄志飞腾天一方，拣深山旷野潜藏。莫行唐，蓦岭登冈，拽着个钝木斧，系着条粗麻绳，拹着条旧担杖。我则待驾孤舟荡漾，趁五湖烟浪，望七里滩头，轻舟短棹，蓑笠纶竿，一钩香饵钓斜阳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2637, "title": "严子陵垂钓七里滩", "author": "宫天挺", "body": "〔滚绣球〕斥銮驾却是应也不应？布衣人却是惊也不惊？更做道一人有庆，汉君王真恁地将銮驾别无处施呈。他出郭迎，俺旧伴等，待刚来我跟前显耀他帝王的权柄，和俺钓鱼人莫不两国相争。齐臻臻戈殳镫棒当头摆，明晃晃武士金瓜夹路行。我怎敢冲撞朝廷。\n〔倘秀才〕他往常穿一领粗布袍被我常扯的偏襟袒领，他如今穿着领柘黄袍我若是轻抹着该多大来罪名。我则是那草店上相逢时那个身命，便和您，叙交情，做咱那伴等。\n〔滚绣球〕投至得帝业兴，家业成，四边宁静，经了几千场虎斗龙争。则为我交契情，我广打听，到处里曾问遍庶民百姓，最显的是暮秋霜气严凝。都说你“须知后汉功臣力，不及滹沱一片冰”。端的是鬼怕神惊。\n〔脱布衫〕则为你搬调人两字功名，驱用人半世浮生。一个楚霸王拔山举鼎，乌江岸剑抹了咽颈。\n〔小梁州〕都则为耻向东吴再起兵，那其间也是高祖功成。道贼王莽篡了龙廷，有真命，文叔再中兴。\n〔幺篇〕贫道暗暗心内自思省，建武十三年八月期程。王新室有百万兵困你在昆阳阵。那其间醉魂也半轮明月，觉来时依旧照茅亭。\n〔耍孩儿〕自古兴亡成败皆前定，若是你不患难如何得太平。自从祖公公昔日陷彭城，真乃是死里逃生。不龙吟怎得真龙显？不发黑如何得晓日明？虽然您明圣，若不是云台上英雄并力，你独自个孤掌难鸣。\n〔四煞〕为民乐业在家内居，为农的欣然在垄上耕，从你为君社稷安，盗贼息，狼烟静。九层春露都恩到，两鬓秋霜何足星。百姓每家家庆，庆道是民安国泰，法正官清。\n〔三煞〕休将闲事争提，莫将席面冷，磁瓯瓦钵似南阳兴。若相逢不饮空归去，我怕听阳关第四声。你把这瓮内酒休交剩。我若不令十分酩酊，怎解咱数载离情。\n〔二煞〕你也不是我的君，我也不是你的卿，咱两个一尊酒罢先言定。若你万圣主今夜还归去，我便七里滩途程来日登。又不曾更了名姓，你则是十年前沽酒刘秀，我则是七里滩垂钓的严陵。\n〔煞尾〕您每朝聚九卿，你须当起五更，去得迟呵着这两班文武在丹墀候等。俺出家来纳被蒙头，黑甜一枕，直睡到红日三竿犹兀自唤不的我醒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2638, "title": "〔双调〕蟾宫曲", "author": "郑光祖", "body": "飘飘泊泊船缆定沙汀，悄悄冥冥。江树碧荧荧，半明不灭一点渔灯。冷冷清清潇湘景晚风生，淅留淅零暮雨初晴，皎皎洁洁照橹篷剔留团栾月明。正潇潇飒飒和银筝失留疏剌秋声，见希胡都茶客微醒。细寻寻思思：“双生，双生，你可闪下苏卿！”", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2639, "title": "〔双调〕蟾宫曲", "author": "郑光祖", "body": "弊裘尘土压征鞍鞭倦袅芦花。弓剑萧萧，一竟入烟霞。动羁怀西风禾黍秋水蒹葭。千点万点老树寒鸦，三行两行写高寒呀呀雁落平沙。曲岸西边近水涡鱼网纶竿钓艖，断桥东下傍溪沙疏篱茅舍人家。见满山满谷，红叶黄花。正是凄凉时候，离人又在天涯！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2640, "title": "醉思乡王粲登楼", "author": "郑光祖", "body": "〔迎仙客〕雕檐外红日低，画栋畔彩云飞；十二阑干，阑干在天外倚。我这里望中原，思故里，不由我感叹酸嘶，越搅的我这一片乡心碎。\n〔红绣鞋〕泪眼盼秋水长天远际，归心似落霞孤鹜齐飞；则我这襄阳倦客苦思归。我这里凭阑望，母亲那里倚门悲，争奈我身贫归未得。\n〔普天乐〕楚天秋，山叠翠，对无穷景色，总是伤悲。好教我动旅怀难成醉，枉了也壮志如虹英雄辈，都做助江天景物凄其：气呵做了江风淅淅，愁呵做了江声沥沥，泪呵弹做了江雨霏霏。\n〔石榴花〕现如今寒蛩唧唧向人啼，哎！知何日是归期？想当初只守着旧柴扉，不图甚的，倒得便宜。则今山林钟鼎俱无味，命矣时兮。哎！可知道枉了我顶天立地居人世，老兄也恰便是睡梦里过了三十。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2641, "title": "迷青琐倩女离魂", "author": "郑光祖", "body": "〔元和令〕杯中酒，和泪酌；心间事，对伊道：似长亭折柳赠柔条，哥哥你休有上梢没下梢。从今虚度可怜宵，奈离愁不了。\n〔后庭花〕我这里翠帘车先控着，他那里黄金镫懒去挑；我泪湿香罗袖，他鞭垂碧玉梢。望迢迢，恨堆满西风古道。想急煎煎人多情人去了，和青湛湛天有情天亦老。俺气氲氲喟然声不定交，助疏剌剌动羁怀风乱扫；滴扑籁簌界残妆粉泪抛，洒细蒙蒙浥香尘暮雨飘。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2642, "title": "迷青琐倩女离魂", "author": "郑光祖", "body": "〔越调·斗鹌鹑〕人去阳台，云归楚峡。不争他江渚停舟，几时得门庭过马？悄悄冥冥，潇潇洒洒。我这里踏岸沙，步月华；我觑这万水千山，都只在一时半霎。\n〔紫花儿序〕想倩女心间离恨，赶王生柳外兰舟，似盼张骞天上浮槎。汗溶溶琼珠莹脸，乱松松云髻堆鸦，走的我筋力疲乏。你莫不夜泊秦淮卖酒家？向断桥西下，疏剌剌秋水菰蒲，冷清清明月芦花。\n〔小桃红〕我蓦听得马嘶人语闹喧哗，掩映在垂杨下，唬的我心头丕丕那惊怕，原来是响珰珰鸣榔板捕鱼虾。我这里顺西风悄悄听沉罢，趁着这厌厌露华，对着这澄澄月下，惊的那呀呀呀寒雁起平沙。\n〔调笑令〕向沙堤款踏，莎草带霜滑；掠湿湘裙翡翠纱，抵多少苍苔露冷凌波袜。看江上晚来堪画，玩冰壶潋滟天上下，似一片碧玉无瑕。\n〔秃厮儿〕你觑远浦孤鹜落霞，枯藤老树昏鸦，听长笛一声何处发，歌欸乃[1]，橹咿哑。\n〔圣药王〕近蓼洼，缆钓槎，有折蒲衰柳老蒹葭；近水凹，傍短槎[2]，见烟笼寒水月笼沙，茅舍两三家。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2643, "title": "迷青琐倩女离魂", "author": "郑光祖", "body": "〔迎仙客〕日长也愁更长，红稀也信尤稀。春归也奄然人未归。我则道相别也数十年，我则道相隔着几万里。为数归期，则那竹院里刻遍琅玕翠。\n〔普天乐〕想鬼病最关心，似宿酒迷春睡；绕晴雪杨花陌上，趁东风燕子楼西。抛闪杀我年少人，辜负了这韶华日。早是离愁添萦系，更那堪景物狼藉。愁心惊一声鸟啼，薄命趁一春事已，香魂逐一片花飞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2644, "title": "迷青琐倩女离魂", "author": "郑光祖", "body": "〔挂金索〕蓦入门庭，则教我立不稳行不正；望见首饰妆奁，志不宁心不定；见几个年少丫环，口不住手不停，拥着个半死佳人，唤不醒呼不应。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2645, "title": "虎牢关三战吕布", "author": "郑光祖", "body": "〔尾声〕十载武夫闲，九得兵书看，八卦阵如同等闲，七禁令将军我小看，六丁神不许将我遮拦。者么是五云间，四壁银山，三姓家姓恁意儿反。（关末云）兄弟，想吕布十分英勇，又有八健将，则怕你难敌么。（正末唱）二哥哥你休将我小看，凭着我这一生得村汉。（关末云）兄弟也，两阵之间，你可怎生交马也。（正末唱）我可敢半空中滴溜扑番过那一座虎牢关。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2646, "title": "梅香骗翰林风月", "author": "郑光祖", "body": "〔寄生草〕此景翰林才吟难尽，丹青笔画不成。觑海棠风锦机摇动鲛绡泠，芳草烟翠纱笼罩玻璃净，垂杨露绿丝穿透珍珠迸。池中星有如那玉盘乱撒水晶丸，松梢月恰便似苍龙捧出轩辕镜[3]。\n〔幺篇〕他曲未终肠先断，俺耳才闻愁越增，一程程捱入相思境，一声声总是相思令，一星星尽诉相思病。不争向琴操中单诉着你飘零，可不道窗儿外更有个人孤另。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2647, "title": "梅香骗翰林风月", "author": "郑光祖", "body": "〔圣药王〕他道是这一场，这一桩，都是这辱门败户小婆娘。杀人呵要见伤，拿贼呵要见赃。请起来波，多愁多病俏才郎。这是谁与他的紫香囊。\n〔麻郎儿〕这声音九分是你令堂。呀，头一句先抓揽着梅香。您吵闹起花烛洞房，自支吾待月西厢。\n〔幺篇〕哎，不妨，莫慌，我当。亲生女非比他行，家丑事不可外扬。你索取一个治家不严的招状。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2648, "title": "萧何月下追韩信", "author": "金仁杰", "body": "〔双调·新水令〕恨天涯流落客孤寒，叹英雄半世虚幻。坐下马空踏遍山水雄，背上剑枉射得斗牛寒！恨塞于天地之间。云遮断玉砌雕栏，按不住浩然气透霄汉！\n〔驻马听〕回首青山，拍拍离愁满战鞍；举头新雁，呀呀哀怨伴天寒。止望学龙投大海驾天关，刬地似军骑羸马连云栈。且相逢，觑英雄如匹似闲，堪恨无端四海苍生眼！\n〔沉醉东风〕干功名千难万难，求身仕两次三番。前番离了楚国，今次又别炎汉，不觉的皓首苍颜。就月朗回头把剑看，忽然伤感默上心来，百忙里揾不干我英雄泪眼！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2649, "title": "陈季卿悟道竹叶舟", "author": "范康", "body": "〔三煞〕趁着这响咿哑数声柔橹前溪口，早看见明滴溜几点鱼灯古渡头。则见秋江雪浪拍天浮，更月黑云愁。疏剌剌风狂雨骤，这天气甚时候。白茫茫银涛不断流，那里也骑鹤扬州。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2650, "title": "〔正宫〕醉太平", "author": "曾瑞", "body": "相邀士夫，笑引奚奴。涌金门外过西湖，写新诗吊古。苏堤堤上寻芳树，断桥桥畔沽醽醁[1]，孤山山下醉林逋。洒梨花暮雨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2651, "title": "〔南吕〕四块玉", "author": "曾瑞", "body": "罗网施，权豪使，石火光阴不多时。劼活若比吴蚕似。皮作锦，茧做丝，蛹烫死。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2652, "title": "〔南吕〕骂玉郎过感皇恩采茶歌", "author": "曾瑞", "body": "无情杜宇[2]闲淘气，头直上耳根底。声声聒得人心碎。你怎知，我就里[3]，愁无际？帘幕低垂，重门深闭。曲阑边，雕檐外，画楼西。将春酲[4]唤起，将晓梦惊回。无明夜，闲聒噪，厮禁持[5]。我几曾离，这绣罗帏，没来由劝我道不如归。狂客江南正着迷，这声儿好去对俺那人啼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2653, "title": "〔般涉调〕哨遍", "author": "曾瑞", "body": "十二宫分了巳未[6]，禀乾坤二气成形质。颜色异种多般，本性善群兽难及。向塞北，李陵台畔，苏武坡前，嚼卧夕阳外。趁满目无穷草地，散一川平野，走四塞荒陂。驭车善致晋侯欢，拂石能逃左慈危。舍命于家，就死成仁，杀身报国。\n〔幺〕告朔何疑，代衅钟偏称宣王意。享天地济民饥，据云山水陆无敌。尽之矣！蹄熊掌，鹿脯獐[7]，比我都无滋味。折莫[8]烹炮煮煎熛蒸炙，便盐淹将巵[9]，醋拌糟焙。肉麋肌鲊可为珍，莼菜鲈鱼有何奇。于四时中无不相宜。\n〔耍孩儿〕从黑河边赶我到东吴内，我也则望前程万里。想道是物离乡贵有些峥嵘，撞着个主人翁少东没西。无料喂把肠胃都抛做粪，无水饮将脂膏尽化做尿，便似养虎豹牢监系。从朝至暮，坐守行随。\n〔幺〕见一日八十番觑我膘脂，除我柯杖外别有甚的。许下浙江等处恶神祇，又请过在城新旧相知。待赁与老火者残岁里呈高戏，要雇与小子弟新年中扮社直[10]。穷养的无巴避[11]，待准折舞裙歌扇，要打摸暖帽春衣。\n〔一煞〕把我蹄指甲要舒做晃窗，头上角要锯做解锥，瞅着颔下须紧要挝笔；待生挦我毛裔铺毡袜，待活剥我监儿[12]踏磹皮[13]。眼见的难回避。多应早晚，不保朝夕。\n〔二〕火里赤[14]磨了快刀，忙古歹[15]烧下热水。若客都来抵九千鸿门会。先许下神鬼[16]了前膊，再请下相知揣了后腿，围我在垓心内。便休想一刀两段，必然是万剐凌迟。\n〔尾〕我如今剌搭着两个蔫耳朵，滴溜着一条粗硬腿。我便是蝙蝠臀内精精地，要祭赛的穷神下的呵吃。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2654, "title": "〔商调〕集贤宾", "author": "曾瑞", "body": "闷登楼倚阑干看暮景，天阔水云平。浸池面楼台倒影，书云笺雁字斜横。衰柳拂月户云窗，残荷临水阁凉亭。景凄凉助人愁越逞，下妆楼步月空庭。鸟惊环佩响，鹤吹铎铃鸣。\n〔逍遥乐〕对景如青鸾舞镜。天隔羊车，人囚凤城。好姻缘辜负了今生，痛伤悲雨泪如倾。心如醉满怀何日醒？西风传玉漏丁宁。恰过半夜，胜似三秋，才交四更。\n〔金菊香〕秋虫夜语不堪听，啼树宫鸦不住声。入孤帏强眠寻梦境，被相思鬼绰[17]了魂灵。纵有梦也难成。\n〔醋葫芦〕睡不着，坐不宁；又不疼不痛病萦萦。待不思量霎儿心未肯，没乱[18]到更阑人静。\n〔高平煞〕照愁人残蜡碧荧荧，沉水烟消金兽鼎。败叶走庭除，修竹扫苍楹。唱道是[19]人和闷可难争，则我瘦身躯怎敢共愁肠竞？伤心情脉脉，病体困腾腾。画屋风轻，翠被寒增，也温不过早来袜儿冷。\n〔尾〕睡魔盼不来，丫鬟叫不应，香消烛灭冷清清。唯嫦娥与人无世情，可怜咱孤另：透疏帘斜照月偏明。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2655, "title": "〔正宫〕金殿喜重重南", "author": "范居中", "body": "风雨秋堂。孤枕无眠，愁听雁南翔。风也凄凉，雨也凄凉，节序已过重阳。盼归期何期何事归未得？料天教暂尔参商。昼思乡，夜思乡，此情常是悒怏。〔赛鸿秋北〕想那人妒青山、愁蹙在眉峰上，泣丹枫、泪滴在香腮上，拔金钗、划损在雕阑上，托瑶琴、哀诉在冰弦上。无事不思量，总为咱身上。争知我懒贪书，羞对酒，也只为他身上。\n〔金殿喜重重南〕凄怆，望美人兮天一方。谩想象赋《高唐》。梦到他行[1]，身到他行，甫能得一霎成双。是谁将好梦都惊破，被西风吹起啼螀。恼刘郎，害潘郎，折倒[2]尽旧日豪放。\n〔货郎儿北〕想着和他相偎厮傍，知他是千场万场。我怎比司空见惯当寻常？才离了一时半刻，恰便似三暑十霜。\n〔醉太平北〕恨程途渺茫，更风波零瀼[3]。我这里千回百转自徬徨，撇不下多情数桩：半真半假乔模样，宜嗔宜喜娇情况，知疼知热俏心肠。但提来暗伤[4]。\n〔赚南〕终日悬望，恰原来捣虚撇抗。误我一向，到此才知言是谎。把[5]当初花前宴乐，星前誓约，真个崔张不让。命该凋丧，险些病染膏肓，此言非妄。\n〔怕春归北〕白发陡然千丈，非关明镜无情，缘愁似个长。相别时多，相见时难，天公自主张。若能够相见，我和他对着灯儿深讲。\n〔春归犯南〕自想，但只愁年华老，容颜改，添惆怅。蓦然平地，反生波浪。最莫把青春弃掷，他时难算风流帐。怎辜负银屏绣褥朱幌，才色相当，两情契合非强？怎割舍眉南面北成撇漾[6]！\n〔尾声南〕动止幸然俱无恙，画堂内别是风光；散却离忧重欢畅。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2656, "title": "〔南吕〕一枝花", "author": "施惠", "body": "离匣牛斗[1]寒，到手风云助。插腰奸胆破，出袖鬼神伏。正直规模[2]，香檀杷虎口双吞玉，沙鱼鞘龙鳞密砌珠。挂三尺壁上飞泉，响半夜床头骤雨。\n〔梁州〕金错落盘花扣挂，碧玲珑镂玉妆束，美名儿今古人争慕。弹鱼空馆，断蟒长途；逢贤把赠，遇寇即除。比莫邪[3]端的全殊，纵干将未必能如。曾遭遇诤朝谗烈士朱云，能回避叹苍穹雄夫项羽，怕追陪报私仇侠客专诸。价孤[4]，世无。数十年是俺家藏物，吓人魂，射人目。相伴着万卷图书酒一壶，遍历江湖。\n〔尾声〕笑提常向尊前舞，醉解多从醒后赎，则为俺未遂封侯把它久担误。有一日修文用武，驱蛮静虏，好与清时定边土。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2657, "title": "〔南吕〕一枝花", "author": "孛罗御史", "body": "懒簪獬豸冠，不入麒麟画。旋栽陶令菊，学种邵平瓜，觑不的闹穰穰蚁阵蜂衙。卖了青骢马，换耕牛度岁华。利名场再不行踏，风波海其实怕他。\n〔梁州〕尽燕雀喧檐聒耳，任豺狼当道磨牙，无官守无言责相牵挂。春风桃李，夏月桑麻，秋天禾黍，冬月梅茶。四时景物清佳，一门和气欢洽。叹子牙渭水垂钓，胜潘岳河阳种花，笑张骞河汉乘槎。这家，那家，黄鸡白酒安排下。撒会顽[1]，放会耍。拚[2]着老瓦盆边醉后扶，一任他风落了乌纱。\n〔牧羊关〕王大户相邀请，赵乡司[3]扶下马。则听得扑冬冬社鼓频挝。有几个不求仕的官员，东庄措大[4]，他每都拍手歌丰稔，俺再不想巡案去奸猾。御史台开除我，尧民图添上咱。\n〔贺新郎〕奴耕婢织足生涯。随分村疃[5]人情，赛强如宪台风化。趁一溪流水浮鸥鸭，小桥掩映蒹葭。芦花千顷雪，红树一川霞。长江落日牛羊下。山中闲宰相，林外野人家。\n〔隔尾〕诵诗书稚子无闲暇，奉甘旨萱堂到白发。伴辘轳村翁说一会挺膊子话[6]。闲时节笑咱，醉时节睡咱。今日里无是无非快活煞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2658, "title": "王妙妙死哭秦少游", "author": "鲍天祐", "body": "〔双调·新水令〕似一江春水向东流，对秋天动情感旧。心愁一万缕，半载胜三秋。一望雷州，一凝伫，一僝僽。\n〔驻马听〕一向淹留，寄一纸书来一字愁。自从别后，一番花落一番羞，一声杜宇倦凝眸。趁一鞭行色慵回首。我精神一旦休，折倒的一枝粉淡梨花瘦。\n〔甜水令〕则见那闹闹烘烘，聒聒噪噪，道姓题名，围前围后。湿浸浸冷汗遍身流。哭哭啼啼，凄凄凉凉，不堪回首，愁和闷常在心头。\n〔折桂令〕困腾腾高枕无忧；却和你梦里相逢，元来是神绕魂游。一灵儿杳杳冥冥，哀哀怨怨，荡荡悠悠。凄惶泪流了再流，思量心愁上添愁，空教我淹损双眸。拆散了燕侣莺俦，至老风流，佳句难酬；觑了这一曲新词，便是他两句遗留。\n〔落梅风〕染胭脂、双眉皱，形容出、两鬓秋。觑绝时泪淹衫袖，病来时倒大来不自由，怎画的来骨崖崖影儿消瘦。\n〔庆东原〕你为我容颜瘦，我为你心绪愁。临歧执手相别后，我为你再不惹狂朋怪友，再不吃闲茶浪酒，再不上谢馆秦楼，再不共厮追陪，再不说闲声嗽。\n〔沉醉东风〕你虚飘飘拔着短筹，冷清清算在雷州。感承你实丕丕厮爱怜，乐陶陶常相守，谁承望苦恹恹拆散鸾俦。眼睁睁一日无常万事休，则落的痛杀杀浇茶奠酒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2659, "title": "〔般涉调〕哨遍", "author": "睢景臣", "body": "社长排门告示：但有的差使无推故。这差使不寻俗。一壁厢纳草也根，一边又要差夫，索应付。又言是车驾，都说是銮舆，今日还乡故。王乡老执定瓦台盘，赵忙郎抱着酒葫芦。新刷来的头巾，恰糨来的绸衫，畅好是妆幺大户。\n〔耍孩儿〕瞎王留引定伙乔男女，胡踢蹬吹笛擂鼓。见一彪人马到庄门。匹头里几面旗舒：一面旗白胡阑套住个迎霜兔；一面旗红曲连打着个毕月乌；一面旗鸡学舞；一面旗狗生双翅；一面旗蛇缠葫芦。\n〔五煞〕红漆了叉，银铮了斧。甜瓜苦瓜黄金镀。明晃晃马枪尖上挑，白雪雪鹅毛扇上铺。这几个乔人物，拿着些不曾见的器仗，穿着些大作怪衣服。\n〔四煞〕辕条上都是马，套顶上不见驴。黄罗伞柄天生曲。车前八个天曹判，车后若干递送夫。更几个多娇女，一般穿着，一样妆梳。\n〔三煞〕那大汉下的车，众人施礼数。那大汉觑得人如无物。众乡老展脚舒腰拜，那大汉挪身着手扶。猛可里抬头觑，觑多时认得，险气破我胸脯。\n〔二煞〕你须身姓刘，你妻须姓吕。把你两家儿根脚从头数。你本身做亭长，耽几盏酒。你丈人教村学，读几卷书。曾在俺庄东住，也曾与我喂牛切草，拽坝扶锄。\n〔一煞〕春采了桑，冬借了俺粟，零支了米麦无重数。换田契强称了麻三秤，还酒债偷量了豆几斛。有甚胡突处？明标着册历，现放着文书。\n〔尾〕少我的钱，差发内旋拨还；欠我的粟，税粮中私准除。只道刘三，谁肯把你揪捽住？白甚么改了姓、更了名，唤做汉高祖？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2660, "title": "〔正宫〕叨叨令", "author": "周文质", "body": "筑墙的曾入高宗梦，钓鱼的也应飞熊梦；受贫的是个凄凉梦，做官的是个荣华梦。笑煞人也末哥，笑煞人也末哥，梦中又说人间梦。\n去年今日题诗处，佳人才子相逢处。世间多少伤心处，人面不知归何处。望不见也末哥，望不见也末哥，绿窗空对花深处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2661, "title": "〔正宫〕叨叨令", "author": "周文质", "body": "叮叮铁马儿乞留玎琅闹，啾啾唧唧促织儿依柔依然叫。\n滴滴点点细雨儿淅零淅留哨，潇潇洒洒梧叶儿失流疏剌落。\n睡不著也末哥，睡不着也末哥，孤孤另另单枕上迷模登靠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2662, "title": "〔越调〕寨儿令", "author": "周文质", "body": "挑短檠，倚云屏，伤心伴人清瘦影。薄酒初醒，好梦难成，斜月为谁明。闷恹恹听彻残更，意迟迟盼杀多情。西风穿户冷，檐马隔帘鸣。叮，疑是珮环声。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2663, "title": "持汉节苏武还乡", "author": "周文质", "body": "〔中吕·粉蝶儿〕羊角风踅地踅天，鹅毛雪扑头扑面，恰便似落琼花粉甸山川；接天涯，侵海角，都冻做寒冰一片。休笑俺牧羊人耸定双肩，你便是铁石人也冻的撼颏打战。\n〔醉春风〕雪打的我眼难开，风吹的身倒偃。似这般风吹雪打荡散了群羊，漫山中微微的显，显。单于王地占了三山，汉武帝早分了千顷，苏武呵，几时能勾户封八县。\n〔迎仙客〕我这里望塞边，则听的雁声喧，元来是这舞寒风渐离了云汉远。呀呀的一声低，忽忽的两翅软，有分的正落在我根前。莫不是天与俺行方便？\n〔石榴花〕这一封寄帛书全央你个塞鸿传。则要你乘风势驾云轩。者莫你宿芦花穿柳岸过平川，哎，雁也，休恋着水食地面，将日月俄延。则你那六稍翎疾提防着雕翎箭。蓦然间祷告青天，愿孤飞影里青云现，便休题风紧雁行偏。\n〔斗鹌鹑〕你若到富贵中华，寻取那皇宫内院。你过的天堑黄河，那的是长安建都地面。我这里专等招贤武帝宣。单于王若可怜，我则去那凌烟阁[1]上标名，哎，雁儿也，你索在那禽书中把你姓显。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2664, "title": "〔双调〕折桂令", "author": "赵禹圭", "body": "长江浩浩西来，水面云山，山上楼台。山水相连，楼台相对，天与安排。诗句成风烟动色，酒杯倾天地忘怀。醉眼睁开，遥望蓬莱。一半儿云遮，一半儿烟霾。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2665, "title": "〔正宫〕绿幺遍", "author": "乔吉", "body": "不占龙头选，不入名贤传。时时酒圣，处处诗禅。烟霞状元，江湖醉仙。笑谈便是编修院。留连，批风抹月四十年。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2666, "title": "〔中吕〕满庭芳", "author": "乔吉", "body": "吴头楚尾，江山入梦，海鸟忘机。闲来得觉胡伦睡，枕著蓑衣。钓台下风云庆会，纶竿上日月交蚀。知滋味，桃花浪里，春水鳜鱼肥。\n湖平棹稳，桃花泛暖，柳絮吹春。蒌蒿香脆芦芽嫩，烂煮河豚。闲日月熬了些酒樽，恶风波飞不上丝纶。芳村近，田原隐隐，疑是避秦人。\n携鱼换酒，鱼鲜可口，酒热扶头。盘中不是鲸鲵肉，鲟鲊初熟。太湖水光摇酒瓯，洞庭山影落鱼舟。归来后，一竿钓钩，不挂古今愁。\n江声撼枕，一川残月，满目遥岑。白云流水无人禁，胜似山林。钓晚霞寒波濯锦，看秋潮夜海镕金。村醪窨[1]，何人共饮，鸥鹭是知心。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2667, "title": "〔中吕〕满庭芳", "author": "乔吉", "body": "活鱼旋打，沽些村酒，问那人家。江山万里天然画，落日烟霞。垂袖舞风生鬓发，扣舷歌声撼渔槎。初更罢，波明浅沙，明月浸芦花。\n秋江暮景，胭脂林障，翡翠山屏。几年罢却青云兴，直泛沧溟。卧御榻弯的腿疼，坐羊皮惯得身轻。风初定，丝纶慢整，牵动一潭星。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2668, "title": "〔中吕〕山坡羊", "author": "乔吉", "body": "鹏搏九万，腰缠十万，扬州鹤背骑来惯。事间关，景阑珊，黄金不富英雄汉。一片世情天地间。白，也是眼；青，也是眼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2669, "title": "〔中吕〕山坡羊", "author": "乔吉", "body": "朝三暮四，昨非今是，痴儿不解荣枯事。家私，宠花枝，黄金壮起荒淫志，千百锭买张招状纸。身，已至此；心，犹未死。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2670, "title": "〔中吕〕山坡羊", "author": "乔吉", "body": "冬寒前后，雪晴时候，谁人相伴梅花瘦？钓鳌舟，缆汀洲，绿蓑不耐风霜透。投至有鱼来上钩，风，吹破头；霜，皴破手。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2671, "title": "〔越调〕小桃红", "author": "乔吉", "body": "落花飞絮隔朱帘，帘静重门掩。掩镜羞看脸儿嬱[2]，嬱眉尖。眉尖指屈将归期念。念他抛闪，闪咱少欠。欠[3]你病厌厌。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2672, "title": "〔越调〕天净沙", "author": "乔吉", "body": "笔尖扫尽痴云，歌声唤醒芳春。花担安排酒樽，海棠风信，明朝陌上吹尘。\n一从鞍马西东，几番衾枕朦胧。薄幸虽来梦中，争如无梦，那时真个相逢。\n隔窗谁爱听琴？倚帘人是知音。一句话当时至今，今番推甚，酬劳凤枕鸳衾。\n莺莺燕燕春春，花花柳柳真真，事事风风韵韵，娇娇嫩嫩，停停当当人人。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2673, "title": "〔越调〕凭阑人", "author": "乔吉", "body": "瘦马驮诗天一涯，倦鸟呼愁村数家。扑头飞柳花，与人添鬓华。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2674, "title": "〔双调〕折桂令", "author": "乔吉", "body": "风风雨雨梨花，窄索帘栊，巧小窗纱。甚情绪灯前，客怀枕畔，心事天涯。三千丈清愁鬓发，五十年春梦繁华。蓦见人家，杨柳分烟，扶上檐牙。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2675, "title": "〔双调〕折桂令", "author": "乔吉", "body": "华阳巾鹤氅蹁跹，铁笛吹云，竹杖撑天。伴柳怪花妖，麟祥凤瑞，酒圣诗禅。不应举江湖状元，不思凡风月神仙。断简残编，翰墨云烟，香满山川。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2676, "title": "〔双调〕折桂令", "author": "乔吉", "body": "百花洲上新台，檐吻云平，图画天开。鹏俯沧溟，蜃横城市，鳌驾蓬莱。学捧心山颦翠色，怅悬头土湿腥苔。悼古兴怀，休近阑干，万丈尘埃。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2677, "title": "〔双调〕折桂令", "author": "乔吉", "body": "蓬莱老树苍云，禾黍高低，狐兔纷纭。半折残碑，空余故址，总是黄尘。东晋亡也再难寻个右军，西施去也绝不见甚佳人。海气长昏，啼声干，天地无春。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2678, "title": "〔双调〕折桂令", "author": "乔吉", "body": "红梨叶染胭脂，吹起霞绡，绊住霜枝。正万里西风，一天暮雨，两地相思。恨薄命佳人在此，问雕鞍游子何之？雁未来时，流水无情，莫写新诗。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2679, "title": "〔双调〕折桂令", "author": "乔吉", "body": "问荆溪溪上人家：为甚人家，不种梅花？老树支门，荒蒲绕岸，苦竹圈笆。寺无僧狐狸样瓦，官无事乌鼠当衙。白水黄沙，倚遍阑干，数尽啼鸦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2680, "title": "〔双调〕折桂令", "author": "乔吉", "body": "斗牛[5]边缆住仙槎，酒瓮诗瓢，小隐烟霞。厌行李程途，虚花世态，潦草生涯。酒肠渴柳阴中拣云头[6]剖瓜，诗句香梅梢上扫雪片烹茶。万事从他，虽是无田，胜似无家。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2681, "title": "〔双调〕折桂令", "author": "乔吉", "body": "江南倦客登临。多少豪雄，几许消沉。今日何堪，买田阳羡，挂剑长林。霞缕烂谁家昼锦，月钩横故国丹心。窗影灯深，燐火青青，山鬼喑喑。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2682, "title": "〔双调〕清江引", "author": "乔吉", "body": "相思瘦因人间阻，只隔墙儿住。笔尖和露珠，花瓣题诗句，倩衔泥燕儿将过去。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2683, "title": "〔双调〕清江引", "author": "乔吉", "body": "垂杨翠丝千万缕，惹住闲情绪。和泪送春归，倩水将愁去，是溪边落红昨夜雨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2684, "title": "〔双调〕水仙子", "author": "乔吉", "body": "笙歌梦断蒺藜沙，罗绮香余野菜花。乱云老树夕阳下，燕休寻王谢家。恨兴亡怒煞些鸣蛙。铺锦池埋荒甃[8]，流杯亭堆破瓦，何处也繁华？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2685, "title": "〔双调〕水仙子", "author": "乔吉", "body": "谁家练杵动秋庭，那岸窗纱闪夜灯。异乡丝鬓明朝镜，又多添几处星！露华零梧叶无声。金谷园中梦，玉门关外情，凉月三更。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2686, "title": "〔双调〕水仙子", "author": "乔吉", "body": "冬前冬后几村庄，溪北溪南两履霜，树头树底孤山上。冷风来何处香？忽相逢缟袂绡裳。酒醒寒惊梦，笛凄春断肠，淡月昏黄。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2687, "title": "〔双调〕水仙子", "author": "乔吉", "body": "搅柔肠离恨病相兼，重聚首佳期卦怎占？豫章城开了座相思店。闷勾肆儿逐日添，愁行货顿塌在眉尖。税钱比茶船上欠，斤两去等秤上掂，吃紧的历册般拘钤。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2688, "title": "〔双调〕水仙子", "author": "乔吉", "body": "眼中花怎得接连枝，眉上锁新教配钥匙，描笔儿勾销了伤春事。闷葫芦断线儿，锦鸳鸯别对了个雄雌。野蜂儿难寻觅，蝎虎儿干害死，蚕蛹儿毕罢了相思。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2689, "title": "〔双调〕水仙子", "author": "乔吉", "body": "天机织罢月梭闲，石壁高垂雪练寒。冰丝带雨悬霄汉，几千年晒未干。露华凉人怯衣单。似白虹饮涧，玉龙下山，晴雪飞滩。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2690, "title": "〔双调〕水仙子", "author": "乔吉", "body": "冷无香柳絮扑将来，冻成片梨花拂不开。大灰泥漫了三千界，银棱了东大海[9]。探梅的心噤难捱，面瓮儿里袁安舍，盐堆儿里党尉宅，粉缸儿里舞榭歌台。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2691, "title": "〔双调〕殿前欢", "author": "乔吉", "body": "懒云窝，静看松影挂长萝。半间僧舍平分破，尘虑消磨。听不厌隐士歌，梦不喜高轩过，聘不起东山卧。疏慵在我，奔竞从他。\n懒神仙，懒窝中打坐几多年。梦魂不到青云殿，酒兴诗颠。轻便如宰相权，冷淡如名贤传，自在如彭泽县[11]。苍天负我，我负苍天。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2692, "title": "〔双调〕殿前欢", "author": "乔吉", "body": "拍阑干。雾花吹鬓海风寒。浩歌惊得浮云散。细数青山，指蓬莱一望间。纱巾岸，鹤背骑来惯。举头长啸，直上天坛。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2693, "title": "〔双调〕卖花声", "author": "乔吉", "body": "肝肠百炼炉间铁，富贵三更枕上蝶，功名两字酒中蛇。尖风薄雪，残杯冷炙，掩清灯竹篱茅舍。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2694, "title": "〔双调〕雁儿落过得胜令", "author": "乔吉", "body": "黄花开数朵，翠竹栽些个。农桑事上熟，名利场中捋[12]。禾黍小庄科[13]，篱落棱鸡鹅。五亩清闲地，一枚安乐窝。行呵，官大忧愁大；藏呵，田多差役多。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2695, "title": "〔双调〕雁儿落过得胜令", "author": "乔吉", "body": "殷勤红叶诗，冷淡黄花市。清江天水笺，白雁云烟字。游子去何之？无处寄新词。酒醒灯昏夜，窗寒梦觉时。寻思，谈笑十年事；嗟咨，风流两鬓丝。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2696, "title": "〔南吕〕梁州第七", "author": "乔吉", "body": "鱼尾红残霞隐隐，鸭头绿[14]秋水涓涓。芙蓉灿烂摇波面。见沉浮鸥伴，来往鱼船。平沙衰草，古木苍烟。江乡景堪爱堪怜！有丹青巧笔难传。揉蓝靛绿水溪头，铺腻粉白岸边，抹胭脂红叶林前。将笠檐儿慢卷，迎头，仰面，偷睛儿觑见碧天外雁行现，写破祥云一片笺，头直上慢慢盘旋。\n〔一枝花〕忙拈鹊画弓，急取雕翎箭，端直了燕尾[15]，搭上虎筋弦，秋月弓圆，箭发如飞电。觑高低无侧偏，正中宾鸿，落在蒹葭不见。\n〔尾〕转过紫荆坡白草冢黄芦堰，惊起些红脚鸭金头鹅锦背鸳，唬得这儿连忙向败荷里串。血模糊翅搧，扑剌剌可怜，十二枝梢翎向地皮上剪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2697, "title": "〔商调〕集贤宾", "author": "乔吉", "body": "恨青青画桥东畔柳，曾祖送少年游。散晴雪杨花清昼，又一场心事悠悠。翠丝长不系雕鞍，碧云寒空掩朱楼。揎罗袖试将纤玉手，绾东风摇损轻柔。同心方胜结，缨络绣文球[16]。\n〔逍遥乐〕绾不成鸳鸯双叩，空惊散梢头，一双锦鸠。何处忘忧，听枝上数声黄栗留[17]。怕不弄春娇巧转歌喉。惊回好梦，题起离情，唤醒闲愁。\n〔醋葫芦〕雨晴珠泪收，烟颦翠黛羞。风流还自怨风流，病多不奈秋。未秋来早先消瘦，晓风残月在帘钩。\n〔浪里来煞〕不要你护雕阑花甃香，荫苍苔石径幽；只要你盼行人终日替我凝眸，只要你重温灞陵[18]别后酒。如今时候，只要向绿阴深处缆归舟。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2698, "title": "〔双调〕新水令", "author": "乔吉", "body": "绣闺深培养出牡丹芽，控银钩绣帘不挂。莺燕游上苑，蝶梦绕东华。富贵人家，花阴内柳阴下。\n〔乔木查〕忽地迎头见咱，娇小心儿里怕，厌地回身拢鬓鸦，傍阑干行又羞，双脸烘霞。\n〔搅筝琶〕我凝眸罢，心内顽麻。可知曲江头三次遗鞭，我粉墙外几乎坠马。人说观自在活菩萨，堪夸。普陀山几时曾到他，更隔着海角天涯。\n〔甜水令〕他秋水回波，春山摇翠，芳心迎迓，彼此各承答。诗句传情，琴声写恨，衷肠牵挂，许多时不得欢洽。\n〔雁儿落〕斗的满街里闲嗑牙，待罢呵如何罢。空揣着题诗玉版笺，织锦香罗帕。\n〔得胜令〕我是个为客秀才家，你是个未嫁女娇娃。不是将海鹤儿相埋怨，休把这纸鹞儿厮调发。若是真么，回与我句实成的话。天那，送了人呵不是耍。\n〔离亭宴煞〕只因你赡不下解合的心肠儿叉[19]，不是我口不严俵扬[20]的风声儿大。伫头凭阑，一日三衙。唱道成时节准备着小意儿妆，不成时怎肯呆心儿跳塔。哎，你个吃戏冤家，来来来将人休量抹。我不是琉璃井底鸣蛙，我是个花柳营中惯战马。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2699, "title": "玉箫女两世姻缘", "author": "乔吉", "body": "〔商调·集贤宾〕隔纱窗日高花弄影，听何处啭流莺。虚飘飘半衾幽梦，困腾腾一枕春酲。趁着那游丝儿恰飞过竹坞桃溪，随着这蝴蝶儿又来到月榭风亭。觉来时倚着这翠云十二屏，恍惚似坠露飞萤。多咱是寸肠千万结，只落的长叹两三声。\n〔逍遥乐〕犹古自身心不定，倚遍危楼，望不见长安帝京。何处也薄情，多应恋金屋银屏[21]。想则想于咱不志诚，空说下碜磕磕[22]海誓山盟。赤紧的[23]关河又远，岁月如流，鱼雁[24]无凭。\n〔金菊香〕怕不待几番落笔强施呈，争奈一段伤心画不能，腮斗上泪痕粉渍定。没颜色鬓乱钗横，和我这眼皮眉黛欠分明。\n〔柳叶儿〕兀的不寂寞了菱花妆镜，自觑了自害心疼。将一片志诚心写入了冰绡[25]，这一篇相思令，寄与多情，道是人憔悴不似丹青。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2700, "title": "杜牧之诗酒扬州梦", "author": "乔吉", "body": "〔那吒令〕倒金瓶凤头，捧琼浆玉瓯，蹴金莲凤头，并凌波玉钩，整金钗凤头，露春纤玉手，天有情天亦老，春有意春须瘦，云无心云也生愁。\n〔鹊踏枝〕花比他不风流，玉比他不温柔，端的是莺也消魂，燕也含羞，蜂与蝶花间四友，呆打颏都歇在豆蔻梢头。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2701, "title": "李太白匹配金钱记", "author": "乔吉", "body": "〔那吒令〕俺则见香车载楚娃，各剌剌雕轮碾落花；王孙乘骏马，扑腾腾金鞭袅落花；游人指酒家，虚飘飘青旗扬落花。宽绰绰翠亭边蹴踘场，笑呷呷粉墙外秋千架，香馥馥麝兰熏罗绮交加。\n〔鹊踏枝〕闹炒炒嫩绿草聒鸣蛙，轻丝丝淡黄柳带栖鸦。碧茸茸杜若芳洲，暖溶溶流水人家。子规声好教人恨，他只待送春归几树铅华。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2702, "title": "〔越调〕斗鹌鹑", "author": "苏彦文", "body": "地冷天寒，阴风乱刮；岁久冬深，严霜遍撒；夜永更长，寒浸卧榻。梦不成，愁转加。杳杳冥冥，潇潇洒洒。\n〔紫花儿序〕早是我衣服破碎，铺盖单薄，冻的我手脚酸麻。冷弯做一块，听鼓打三挝。天哪，几时捱的鸡儿叫更儿尽点儿煞。晓钟打罢，巴到天明，刬地波查[1]。\n〔秃厮儿〕这天晴不得一时半霎，寒凛冽走石飞沙。阴云黯淡闭日华，布四野，满长空、天涯。\n〔圣药王〕脚又滑，手又麻，乱纷纷瑞雪舞梨花。情绪杂，囊箧乏。若老天全不可怜咱，冻钦钦怎行踏？\n〔紫花儿序〕这雪袁安难卧，蒙正回窑，买臣还家，退之不爱，浩然休夸，真佳。江上渔翁罢了钓槎，便休题晚来堪画。休强呵映雪读书，且免了这扫雪烹茶。\n〔尾声〕最怕的是檐前头倒把冰锥挂，喜端午愁逢腊八。巧手匠雪狮儿一千般成，我盼的是泥牛儿四九里打。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2703, "title": "〔仙吕〕醉中天", "author": "刘时中", "body": "花木相思树，禽鸟折枝图。水底双双比目鱼，岸上鸳鸯户。一步步金厢翠铺。世间好处，休没寻思，典卖了西湖。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2704, "title": "〔南吕〕四块玉", "author": "刘时中", "body": "官况甜，公途险。虎豹重关整威严，仇多恩少皆堪叹。业贯盈，横祸满，无处闪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2705, "title": "〔中吕〕朝天子", "author": "刘时中", "body": "柳营，月明，听传过将军令。高楼鼓角戒严更，卧护得边声静。横槊吟情，投壶歌兴，有前人旧典型。战争，惯经，草木也知名姓。\n《虎韬》，《豹韬》，一览胸中了。时时拂拭旧弓刀，却恨封侯早。夜月铙歌，春风牙纛，看团花锦战袍。鬓毛，木雕，谁便道冯唐老？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2706, "title": "〔中吕〕朝天子", "author": "刘时中", "body": "有钱，有权，把断风流选。朝来街子几人传，书记还平善。兔走如梭，乌飞如箭，早秋霜两鬓边。暮年，可怜，乞食在歌姬院。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2707, "title": "〔中吕〕山坡羊", "author": "刘时中", "body": "云山有意，轩裳无计，被西风吹断功名泪。去来兮，便休提。青山尽解招人醉，得失到头皆物理。得，他命里；失，咱命里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2708, "title": "〔中吕〕山坡羊", "author": "刘时中", "body": "朝朝琼树，家家朱户，骄嘶过沽酒楼前路。贵何如？贱何如？六桥都是经行处，花落水流深院宇。闲，天定许；忙，人自取。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2709, "title": "〔双调〕折桂令", "author": "刘时中", "body": "正黄尘赤日长途，便雷奋天池，教雨随车。把世外炎氛，人间热恼，一洗无余。展洙泗千年画图，纳潇湘一道冰壶[1]。报政何如？风动三湘[2]，霜满重湖[3]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2710, "title": "〔双调〕清江引", "author": "刘时中", "body": "春光荏苒如梦蝶，春去繁华歇。风雨两无情，庭院三更夜，明日落红多去也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2711, "title": "〔双调〕殿前欢", "author": "刘时中", "body": "醉颜酡，太翁庄上走如梭。门前几个官人坐，有虎皮驮驮。呼王留唤伴哥，无一个，空叫得喉咙破。人踏了瓜果，马践了田禾。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2712, "title": "〔双调〕雁儿落过得胜令", "author": "刘时中", "body": "和风闹燕莺，丽日明桃杏。长江一线平，暮雨千山静。载酒送君行，折柳系离情。梦里思梁苑，花时别渭城。长亭，咫尺人孤另；愁听，阳关第四声。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2713, "title": "〔正宫〕端正好", "author": "刘时中", "body": "众生灵遭磨障，正值着时岁饥荒。谢恩光拯济皆无恙，编做本词儿唱。\n〔滚绣球〕去年时正插秧，天反常，那里取若时雨降？旱魃生四野灾伤。谷不登，麦不长，因此万民失望，一日日物价高涨。十分料钞加三倒，一斗粗粮折四量，煞是凄凉。\n〔倘秀才〕殷实户欺心不良，停塌户瞒天不当。吞象心肠歹伎俩，谷中添秕屑，米内插粗糠，怎指望他儿孙久长。\n〔滚绣球〕甑生尘老弱饥，米如珠少壮荒。有金银那里每典当？尽枵腹[4]高卧斜阳。剥榆树餐，挑野菜尝。吃黄不老胜如熊掌，蕨根粉以代糇粮。鹅肠苦菜连根煮，荻笋芦蒿带叶[5]，则留下杞柳株樟。\n〔倘秀才〕或是捶麻柘稠调豆浆，或是煮麦麸稀和细糠，他每早合掌擎拳谢上苍。一个个黄如经纸，一个个瘦似豺狼，填街卧巷。\n〔滚绣球〕偷宰了些阔角牛，盗斫了些大叶桑。遭时疫无棺活葬，贱卖了些家业田庄。嫡亲儿共女，等闲参与商。痛分离是何情况！乳哺儿没人要撇入长江。那里取厨中剩饭杯中酒，看了些河里孩儿岸上娘，不由我不哽咽悲伤。\n〔倘秀才〕私牙子船湾外港，行过河中宵月明。则发迹了些无徒米麦行。牙钱加倍解，卖面处两般装，昏钞早先除了四两。\n〔滚绣球〕江乡相，有义仓，积年系税户掌。借贷数补搭得十分停当，都侵用过将官府行唐。那近日劝粜到江乡，按户口给月粮。富户都用钱买放，无实惠尽是虚桩。充饥画饼诚堪笑，印信凭由却是谎，快活了些社长知房[6]。\n〔伴读书〕磨灭尽诸豪壮，断送了些闲浮浪。抱子携男扶筇杖[7]，羸伛偻[8]如虾样，一丝游气沿途创，阁泪汪汪。\n〔货郎〕见饿莩成行街上，乞出拦门斗抢。便财主每也怀金鹄立待其亡。感谢这监司主张，似汲黯[9]开仓。披星带月热中肠，济与粜亲临发放。见孤孀疾病无皈向，差医煮粥分厢巷。更把赃输钱分例米，多般儿区处的最优长。众饥民共仰，似枯木逢春，萌芽再长。\n〔叨叨令〕有钱的贩米谷置田庄添生放，无钱的少过活分骨肉无承望；有钱的纳宠妾买人口偏兴旺，无钱的受饥馁填沟壑遭灾障。小民好苦也么哥，小民好苦也么哥，便秋收鬻妻卖子家私丧。\n〔三煞〕这相公爱民忧国无偏党，发政施仁有激昂。恤老怜贫，视民如子，起死回生，扶弱摧强。万万人感恩知德，刻骨铭心，恨不得展草垂缰。覆盆[10]之下，同受太阳光。\n〔二煞〕天生社稷真卿相，才称朝廷作栋梁。这相公主见宏深，秉心仁恕，治政公平，莅事慈祥，可与萧曹[11]比并，伊傅[12]齐肩，周召[13]班行。紫泥宣诏，花衬马蹄忙。\n〔一煞〕愿得早居玉笋朝班上，伫看金瓯姓字香。入阙朝京，攀龙附凤，和鼎调羹，论道兴邦。受用取貂蝉济楚[14]，衮绣峥嵘，珂佩丁当。普天下万民乐业，都知是前任绣衣郎。\n〔尾声〕相门出相前人奖，官上加官后代昌。活被生灵恩不忘，粒我烝民德怎偿。父老儿童细较量，樵叟渔夫曾论讲，共说东湖柳岸旁，那里清幽更舒畅。靠着云卿苏圃场[15]，与徐孺子[16]流芳挹清况。盖一座祠堂人供养，立一统碑碣字数行，将德政因由都载上，使万万代官民见时节想。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2714, "title": "〔正宫〕端正好", "author": "刘时中", "body": "既官府甚清明，采舆论听分诉。据江西剧郡洪都，正该省宪亲临处，愿英俊开言路。\n〔滚绣球〕库藏中钞本多，贴库每弊怎除，纵关防任谁不顾。坏钞法恣意强图。都是无廉耻卖买人，有过犯驵侩徒。倚仗着几文钱，百般胡做。将官府觑得如无。只这素无行止乔男女，都整扮衣冠学士夫，一个个胆大心粗。\n〔倘秀才〕堪笑这没见识街市匹夫，好打那好顽劣江湖伴侣，旋将表德官名相体呼，声音多厮称，字样不寻俗。听我一个个细数。\n〔滚绣球〕粜米的唤子良，卖肉的呼仲甫，做皮的是仲才、邦辅，唤清之必定开沽，卖油的唤仲明，卖盐的称士鲁，号从简是采帛行铺，字敬先是鱼鲊之徒，开张卖饭的呼君宝，磨面登罗底叫德夫。何足云乎？\n〔倘秀才〕都结义过如手足，但聚会分张耳目，探听司县何人可共处。那问他无根脚，只要肯出头颅，扛扶着便补。\n〔滚绣球〕三二百锭费本钱，七八下里去干取。诈捏作曾编卷，假如名目。偷俸钱表里相符。这一个图小倒，那一个苟俸禄，把官钱视同己物，更狠如盗跖之徒。官攒库子均摊着要，弓手门军那一个无，试说这厮每贪污。\n〔倘秀才〕提调官非无法度，争奈蠹国贼操心太毒。从出本处先将科钞除。高低还分例，上下没言语，贴库每他每做了钞主。\n〔滚绣球〕且说一季中事例钱，开作时各自与。库子每随高低预先除去。军百户十锭无虚，攒司五五拿，官人六六除，四牌头每一名是两封足数，更有合干人把门军弓手殊途。那里取官民两便通行法，赤紧他贿赂单宜左道术。于汝安乎？\n〔倘秀才〕为甚但开库诸人不伏，倒筹单先须计咒。苗子钱高低随着钞数，放小民三二百，报花户一千余，将官钱陪出。\n〔滚绣球〕一任你叫得昏，等到午，佯呆着不瞅不觑。他却整块价卷在包袱，着纤如晃库门。兴贩的论百价数，都是真扬州武昌客旅，窝藏着家里安居。排的文语呼为绣，假钞公然唤做殊，这等儿三七价明估。\n〔倘秀才〕有揭字驼字衬数，有赫心剜心异呼。有钞脚频成印上字模，半边子尤自可，捶作钞甚胡突，这等儿四六分价唤取。\n〔滚绣球〕赴解时弊更多，作下人就做夫。捡块数几曾详数，止不过得南新吏贴相符，那问他料不齐、数不足？连柜子一时扛去，怎教人心悦诚服？自古道：人存政举，思他前辈，到今日法出奸生，笑煞老夫。公道也私乎？\n〔倘秀才〕比及烧昏钞先行摆布，散夫钱僻静处俵与，暗号儿在烧饼中间觑有无。一名夫半锭，社长总收贮，烧得过便吹笛擂鼓。\n〔塞鸿秋〕一家家倾银注玉多豪富，一个个烹羊挟妓夸风度，撇摽手到处称人物，妆旦色取去为媳妇。朝朝寒食春，夜夜无宵暮，吃筵席唤做赛堂食，受用尽人间福。\n〔呆骨朵〕这贼每也有难堪处，怎禁他强盗每追逐。要饭钱排日支持，索赍发无时横取。奈表里通同做，有上下交征去。真乃是源清流亦清，从今后人除弊不除。\n〔脱布衫〕有聪明正直嘉谟，安得不剪其繁芜，成就了闾阎小夫，坏尽了国家法度。\n〔小梁州〕这厮每玩法欺公胆气粗，恰便似饿虎当途。二十五等则例尽皆无，难着目，他道陪钞待何如。\n〔幺〕一等无辜被害这羞辱，厮攀指一地里胡突，自有他通神物。见如今虚其府库，好教他鞭背出虫蛆。\n〔十二月〕不是我论黄数黑，怎禁他恶紫夺朱。争奈何人心不古，出落着马牛襟裾。口将言而嗫嚅，足欲进而趑趄。\n〔尧民歌〕想商鞅徙木意何如，汉国萧何断其初。法则有准使民服，期于无刑佐皇图。说与当途：无毒不丈夫，为如如把平生误。\n〔耍孩儿十三煞〕天开地辟由盘古，人物才分下土。传之三代币方行，有刀圭帛布促初。九府圜法俱周制，三品堆金乃汉图。止不过作贸易通财物。这是黎民命脉，朝世权术。\n〔十二〕蜀冠瑊交子行，宋真宗会子举，都不如当今钞法通商贾。配成五对为官本，工墨三分任倒除。设制久无更故。民如按堵，法比通衢。\n〔十一〕已自六十秋楮币行，则这两三年法度沮。被无知贼子为奸蠹，私更彻镘心无愧。那想官有严刑罪必诛，忒无忌惮无忧惧。你道是成家大宝，怎想是取命官符。\n〔十〕穷汉每将绰号称，把头每表德呼。巴不得登时事了干回付，向库中钻刺真强盗，却不财上分明大丈夫，坏尽今时务。怕不你人心奸巧，争念有造物乘除。\n〔九〕乘孛模样哏，扭蛮腰礼仪疏，不疼钱一地里胡分付。宰头羊日日羔儿会，没手盏朝朝仕女图。怯薛回家去，一个个欺凌亲戚，眇视乡闾。\n〔八〕没高低妾与妻，无分限儿共女。及时打扮衠珠玉，鸡头般珠子缘鞋口，火炭似真金裹脑梳，服色例休题取，打扮得怕不赛夫人样子。脱不了市辈规模。\n〔七〕他那想赴京师关本时，受官差在旅途。耽惊受怕过朝暮，受了五十四站风波苦，亏杀数百千程递运夫。哏生受哏搭负，广费了些首思分例，倒换了些沿路文书。\n〔六〕到省库中将官本收得无疏虞，朱钞足，那时才得安心绪。常想着半江春水翻风浪，愁得一夜秋霜染鬓须。历重难博得个根基固，少甚命不快遭贼寇，霎时间送了身躯。\n〔五〕论宣差清如酌贪泉吴隐之，廉似还桑椹赵判府，则为忒慈仁，反被相欺侮。每持大体诸人服，若说私心半点无。本栋梁材若早使君朝辅，肯苏民瘼，不事苞苴。\n〔四〕急宜将法变更，但因循弊若初，严刑峻法休轻恕。则这二攒司过似蛇吞象；再差十大户犹如插翅虎。一半儿弓手先芟去，合干人同知数目，把门军切禁科需。\n〔三〕提调官免罪名，钞法房选吏胥，攒典俸多的路吏差着做。廉能州吏以新点，贪滥军官合减除。住仓库，无升补。从今倒钞，各分行铺，写明坊隅。\n〔二〕逐户儿编褙成料例来，各分旬将勘合书，逐张儿背印拘钤住，即时支料还原主。本日交昏入库房，直到起解时才方取，免得他撑船小倒，提调官封锁无虞。\n〔一〕紧拘收在库官，切关防起解夫。钞面上与官攒，俱各亲标署。库官但该一贯须鲸配，库子折莫三钱便断除，满百锭皆抄估。捶钞的、揭剥的不怕他人心似铁，小倒的、兴贩的明放着官法如炉。\n〔尾〕忽青天开眼觑，这红巾合命殂。且举其纲，若不怕伤时务，他日陈言终细数。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2715, "title": "〔双调〕新水令", "author": "刘时中", "body": "世无伯乐怨他谁？干送了挽盐车骐骥。空怀伏枥心，徒负化龙威。索甚伤悲，用之行舍之弃。\n〔驻马听〕玉鬣银蹄，再谁想三月襄阳绿草齐。雕鞍金辔，再谁收一鞭行色夕阳低。花间不听紫骝嘶，帐前空叹乌骓逝。命乖我自知，眼见的千金骏骨无人贵。\n〔雁儿落〕谁知我汗血功，谁想我垂缰义，谁怜我千里才，谁识我千钧力？\n〔得胜令〕谁念我当日跳檀溪，救先主出重围？谁念我单刀会随着关羽？谁念我美良川扶持敬德？若论着今日，索输与这驴群队！果必有征敌，这驴每怎用的？\n〔甜水令〕只为这乍富儿曹，无知小辈，一概地把人欺。一迷里快蹿轻踮，乱走胡奔，紧先行不识尊卑。\n〔折桂令〕致令得官府闻知，验数目存留，分官品高低。准备着竹杖芒鞋，免不得奔走驱驰。再不敢鞭骏骑向街头闹起，则索扭蛮腰将足下殃及。为此辈无知，将我连累，把我埋没在蓬蒿，坑陷在污泥。\n〔尾〕有一等逞雄心屠户贪微利，咽馋涎豪客思佳味。一地把性命亏图，百般地将刑法陵迟。唱道任意欺公，全无道理。从今去谁买谁骑？眼见得无客贩无人喂。便休说站驿难为，则怕你东讨西征那时节悔！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2716, "title": "〔双调〕蟾宫曲", "author": "阿鲁威", "body": "问人间谁是英雄？有酾酒临江，横槊曹公。紫盖黄旗，多应借得，赤壁东风。更惊起南阳卧龙，便成名八阵图中。鼎足三分，一分西蜀，一分江东。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2717, "title": "〔双调〕蟾宫曲", "author": "阿鲁威", "body": "动高吟楚客秋风，故国山河，水落江空。断送离愁，江南烟雨，杳杳孤鸿。依旧向邯郸道中，问居胥今有谁封？何日论文，渭北春天，日暮江东。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2718, "title": "〔双调〕蟾宫曲", "author": "阿鲁威", "body": "理征衣鞍马匆匆。又在关山，鹧鸪声中。三叠《阳关》，一杯鲁酒[1]，逆旅新丰。看五陵[2]无树起风，笑长安却误英雄。云树蒙蒙，春水东流，有似愁浓。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2719, "title": "〔双调〕蟾宫曲", "author": "阿鲁威", "body": "烂羊头谁羡封侯！斗酒篇诗，也自风流。过隙光阴，尘埃野马，不障闲鸥。离汗漫飘蓬九有，向壶山小隐三秋。归赋《登楼》，白发萧萧，老我南州。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2720, "title": "〔正宫〕醉太平", "author": "王元鼎", "body": "声声啼乳鸦，生叫破韶华。夜深微雨润堤沙，香风万家。画楼洗净鸳鸯瓦，彩绳半湿秋千架。觉来红日上窗纱，听街头卖杏花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2721, "title": "〔双调〕折桂令", "author": "虞集", "body": "鸾舆三顾茅庐，汉祚难扶，日暮桑榆[1]。深渡南泸[2]，长驱西蜀，力拒东吴。美乎周瑜妙术，悲夫关羽云殂。天数盈虚，造物乘除[3]。问汝何如，早赋归欤。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2722, "title": "〔双调〕夜行船", "author": "李泂", "body": "驿路西风冷绣鞍，离情秋色相关。鸿雁啼寒，枫林染泪，撺断[1]旅情无限。\n〔风入松〕丈夫双泪不轻弹，都付酒杯间。苏台景物非虚诞，年前倚棹曾看。野水鸥边萧寺，乱云马首吴山。\n〔新水令〕君行那与利名干？纵疏狂柳羁花绊。何曾畏，道途难？往日今番，江海上浪游惯。\n〔乔牌儿〕剑横腰秋水寒，袍夺目晓霞灿。虹霓胆气冲霄汉，笑谈间人见罕。\n〔离亭宴煞〕束装预喜苍头办，分襟无奈骊驹趱[2]。容易去何时重返？见月客窗思，问程村店宿，阻雨山家饭。传情字莫违，买醉金宜散。千古事毋劳吊挽。阖闾墓野花埋，馆娃宫淡烟晚。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2723, "title": "〔正宫〕塞鸿秋", "author": "薛昂夫", "body": "功名万里忙如燕，斯文一脉微如线。光阴寸隙流如电，风霜两鬓白如练。尽道便休官，林下何曾见，至今寂寞彭泽县。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2724, "title": "〔正宫〕塞鸿秋", "author": "薛昂夫", "body": "凌歊台畔黄山铺，是三千歌舞亡家处。望夫山下乌江渡，是八千子弟思乡去。江东日暮云。渭北春天树，青山太白坟如故。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2725, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "沛公，大风，也得文章用。却教猛士叹良弓，多了游云梦。驾驭英雄，能擒能纵，无人出彀中。后宫，外宗，险把炎刘并。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2726, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "伍员，报亲，多了鞭君忿。可怜悬首在东门，不见包胥恨。半夜潮声，千年孤愤，钱塘万马奔。骇人，怒魂，何似吹箫韵？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2727, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "卞和，抱璞，只合荆山坐。三朝不遇待如何？两足先遭祸。传国争符，伤身行货，谁教献与他！切蹉，琢磨，何似偷敲破。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2728, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "丙吉，宰执，燮理阴阳气。有司不问尔相推，人命关天地。牛喘非时，何须留意？原来养得肥。早知，好吃，杀了供堂食。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2729, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "老莱，戏采，七十年将迈。堂前取水作婴孩，犹欲双亲爱。东倒西歪，佯啼颠拜，虽然称孝哉！上阶，下阶，跌杀休相赖！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2730, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "董卓，巨饕[1]，为恶天须报。一脐然出万民膏，谁把逃亡照？谋位藏金，贪心无道，谁知没下梢。好教，火烧，难买棺材料。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2731, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "伯牙，韵雅，自与松风话。高山流水淡生涯，心与琴俱化。欲铸钟期，黄金无价。知音人既寡，尽他，爨下，煮了仙鹤罢。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2732, "title": "〔中吕〕朝天子", "author": "薛昂夫", "body": "孟母，丧夫，教子迁离墓。再迁市井厌屠沽，迁傍芹宫住。如此三迁，房钱无数，方成一大儒。问猪，引取，好辩长于喻。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2733, "title": "〔中吕〕山坡羊", "author": "薛昂夫", "body": "大江东去，长安西去，为功名走遍天涯路。厌舟车，喜琴书，早星星鬓影瓜田暮。心待足时名便足。高，高处苦；低，低处苦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2734, "title": "〔双调〕殿前欢", "author": "薛昂夫", "body": "柳扶疏，玻璃万顷浸冰壶。流莺声里笙歌度，士女相呼。有丹青画不如。迷归路，又撑入荷深处。知他是西湖恋我、我恋西湖？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2735, "title": "〔双调〕楚天遥过清江引", "author": "薛昂夫", "body": "花开人正欢，花落春如醉。春醉有时醒，人老欢难会。一江春水流，万点杨花坠。谁道是杨花，点点离人泪。回首有情风万里，渺渺天无际。愁共海潮来，潮去愁难退。更那堪晚来风又急。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2736, "title": "〔双调〕楚天遥过清江引", "author": "薛昂夫", "body": "屈指数春来，弹指惊春去。蛛丝网落花，也要留春住。几日喜春晴，几夜愁春雨。六曲小屏山，题遍伤春句。春若有情应解语，问着无凭据。江东日暮云，渭北春天树。不知那答儿是春住处！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2737, "title": "〔双调〕楚天遥过清江引", "author": "薛昂夫", "body": "有意送春归，无计留春住。明年又着来，何似休归去。桃花也解愁，点点飘红玉。目断楚天遥，不见春归路。春若有情春更苦，暗里韶光度。夕阳山外山，春水渡傍渡。不知那答儿是春住处！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2738, "title": "〔南吕〕金字经", "author": "吴弘道", "body": "落花风飞去，故枝依旧鲜。月缺终须有再圆。圆。月圆人未圆。朱颜变，几时得重少年。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2739, "title": "〔南吕〕金字经", "author": "吴弘道", "body": "这家村醪尽，那家醅瓮开。卖了肩头一担柴，咍！酒钱怀内揣。葫芦在，大家提去来。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2740, "title": "〔双调〕拨不断", "author": "吴弘道", "body": "泛浮槎，寄生涯，长江万里秋风驾。稚子和烟煮嫩茶，老妻带月炰新鲊。醉时闲话。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2741, "title": "〔双调〕拨不断", "author": "吴弘道", "body": "暮云遮，雁行斜，渔人独钓寒江雪。万木天寒冻欲折，一枝冷艳开清绝。竹篱茅舍。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2742, "title": "〔中吕〕普天乐", "author": "赵善庆", "body": "稻粱肥，蒹葭秀。黄添篱落，绿淡汀洲。木叶空，山容瘦。沙鸟翻风知潮候，望烟江万顷沉秋。半竿落日，一声过雁，几处危楼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2743, "title": "〔中吕〕普天乐", "author": "赵善庆", "body": "晚天长，秋水苍。山腰落日，雁背斜阳。璧月词，朱唇唱，犹记当年兰舟上。洒西风，泪湿罗裳。钗分凤凰，杯斟鹦鹉，人拆鸳鸯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2744, "title": "〔中吕〕山坡羊", "author": "赵善庆", "body": "来时春社，去时秋社，年年来去搬寒热。语喃喃，忙劫劫，春风堂上寻王谢。巷陌乌衣夕照斜。兴，多见些；亡，都尽说。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2745, "title": "〔中吕〕山坡羊", "author": "赵善庆", "body": "骊山横岫，渭河环秀，山河百二还如旧。狐兔悲，草木秋；秦宫隋苑徒遗臭，唐阙汉陵何处有？山，空自愁；河，空自流。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2746, "title": "〔越调〕凭阑人", "author": "赵善庆", "body": "铜雀台空锁暮云，金谷园荒成路尘。转头千载春，断肠几辈人。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2747, "title": "〔双调〕沉醉东风", "author": "赵善庆", "body": "山对面兰堆翠岫，草齐腰绿染沙洲。傲霜橘柚青，濯雨蒹葭秀。隔沧波隐隐江楼。点破潇湘万顷秋，是几叶儿传黄败柳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2748, "title": "〔双调〕折桂令", "author": "赵善庆", "body": "问六桥何处堪夸？十里晴湖，二月韶华。浓淡峰峦，高低杨柳，远近桃花。临水临山寺塔，半村半郭人家。杯泛流霞，板撒红牙。紫陌游人，画舫娇娃。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2749, "title": "〔双调〕折桂令", "author": "赵善庆", "body": "八窗开水月交光。诗酒坛台，莺燕排场。歌扇摇风，梨云飘雪，粉黛生香。红袖台已更旧邦，白头民犹说新堂。花妒幽芳，人换宫妆。惟有湖山，不管兴亡。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2750, "title": "〔双调〕庆东原", "author": "赵善庆", "body": "砧声住，蛩韵切，静寥寥门掩清秋夜。秋心凤阙，秋愁雁堞，秋梦蝴蝶。十载故乡心，一夜邮亭月。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2751, "title": "〔越调〕柳营曲", "author": "马谦斋", "body": "亲凤塔，住龙沙，天下太平无事也。辞却公衙，别了京华，甘分老农家。傲河阳潘岳栽花，效东门邵平种瓜。庄前栽果木，山下种桑麻。度岁华，活计老生涯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2752, "title": "〔越调〕柳营曲", "author": "马谦斋", "body": "曾窨约，细评薄，将业兵功非小可。生死存活，成败消磨，战策属谁多？破西川平定干戈，下南交威镇山河。守玉关班定远，标铜柱马伏波。那两个，今日待如何？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2753, "title": "〔越调〕柳营曲", "author": "马谦斋", "body": "手自搓，剑频磨，古来丈夫天下多。青镜摩挲，白首蹉跎，失志困衡窝。有声名谁识廉颇，广才学不用萧何。忙忙的逃海滨，急急的隐山阿。今日个，平地起风波。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2754, "title": "〔双调〕沉醉东风", "author": "马谦斋", "body": "瓷瓯内潋滟莫掩，瓦盆中渐浅重添。线鸡肥，新篘酽，不须典琴留剑。二顷桑麻足养廉，归去来长安路险。\n取富贵青蝇竞血，进功名白蚁争穴。虎狼丛甚日休？是非海何时彻？人我场慢争优劣。免使旁人做话说，咫尺韶华去也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2755, "title": "宜秋山赵礼让肥", "author": "秦简夫", "body": "〔寄生草〕饿的这民饥色，看看的如蜡渣。他每都家家上树把这槐芽掐。他每都村村沿道将榆皮剐。他每都人人绕户将粮食化。现如今弟兄衣袂不遮身，可着俺贫寒子母无安下。\n〔醉扶归〕我吃的这茶饭有难消化，母亲那肌肤瘦力衰乏。量这半勺儿粥都添了有甚哪？我转着这空碗儿，我着这匙尖儿刮，我陪着笑脸儿百般的喜洽，不由我泪不住行儿下。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2756, "title": "宜秋山赵礼让肥", "author": "秦简夫", "body": "〔凭阑人〕由你将我身躯七事子开，由你将我心肝一件件摘。我道来，我道来，除死呵，无大灾。\n〔络丝娘〕我只道你杀人刀十分的利害，元来这活人心依然尚在。便做道俺两个该死的游魂甚耽待，也则是可怜见白头奶奶。\n〔东原乐〕敢道是凶年岁，瘦骨骸。便剐将来也填不满一餐债。因此在饿虎喉中乞得这免死牌。蒙恩贷，从今后遥望着你的营门，常常礼拜。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2757, "title": "东堂老劝破家子弟", "author": "秦简夫", "body": "〔鹊踏枝〕你则待要爱纤腰，可便似柔条。不离了舞榭歌台，不俫更那月夕花朝。想当日个按六幺舞霓裳未了，猛回头烛灭香消。\n〔寄生草〕我为甚叮咛劝叮咛道，你有祸根有祸苗。你抛撇了这丑妇家中宝，挑踢着美女家生哨。哎，儿也，这的是你自作下穷汉家私暴。只思量倚檀槽听唱一曲桂枝香，你少不的撇摇槌，学打几句莲花落。\n〔六幺序〕那里面藏圈套，都是些绵中刺笑里刀。那一个出得他掴打挝揉，止不过帐底鲛绡，酒畔羊羔。人的玉软香娇，半席地恰便似八百里梁山泊，抵多少月黑风高。那泼烟花专等你个腌材料，快准备着五千船盐引，十五担茶挑。\n〔幺篇〕你把他门限儿蹅着，消息儿汤着。那里面又没官僚，又没王条，又没公曹，又没囚牢。到的来金谷也，那富饶早半合儿断送了，直教你无计能逃，有路难超。搜剔尽皮格也那翎毛，浑身遍体，星星开剥，尽着他炙煿烹炮。那虔婆一对刚牙爪，遮莫你手轻脚疾，敢可也立做了骨化形销。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2758, "title": "晋陶母剪发待宾", "author": "秦简夫", "body": "〔那吒令〕则他这今年，非同似往年，恰还了纸钱，又少欠下笔钱。常着我左肩，那在这右肩。与人家做生活打些坌活，闲停止妆宅眷。端的使碎我意马心猿。\n〔鹊踏枝〕你则待要赴佳筵，倒金舡；喒如今少米无柴，赤手空拳。你不学汉贾谊献长策万言，你则待学刘伶般烂醉十年。\n〔寄生草〕你则待扶头酒寻半碗，谒人诗赠几篇；请着你不离，随着他转；逢着你的唱偌，迎着他善。后来便说着你的体面难消遣，则你这拖狗皮缠定这谢家楼，几时得布衣人走上黄金殿。\n〔金盏儿〕钱字是大金傍戋，信字是立人边言。信近于义，钱招怨。这一个有钱可更有信，两件事古来传：这一个有钱的石崇般富，这一个有信的范丹贤。你常存着立身夫子信，休恋这转世邓通钱。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2759, "title": "河南府张鼎勘头巾", "author": "陆登善", "body": "〔梁州第七〕我从来甘剥剥与民无私，谁敢道另巍巍节外生枝。我向吓魂台把文案偷窥视。见一人高声叫屈，我这里低首寻思，多应被拷打无地，全没那半点儿心慈！想危亡顷刻参差，端的是垂命悬丝。正厅上坐着个问事官人，阶直下排两行恶哏哏行刑汉子，书案边立着个响珰珰责状曹司。为什事咬牙切齿，諕的犯罪人面色如金纸。见相公判个“斩”字，慌向前来取台旨，便待要血泊内横尸。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2760, "title": "〔黄钟〕人月圆", "author": "张可久", "body": "兴亡千古繁华梦，诗眼倦天涯。孔林乔木，吴宫蔓草，楚庙寒鸦。数间茅舍，藏书万卷，投老村家。山中何事，松花酿酒，春水煎茶。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2761, "title": "〔黄钟〕人月圆", "author": "张可久", "body": "梅花浑似真真面，留我倚阑杆。雪晴天气，松腰玉瘦，泉眼冰寒。兴亡遗恨，一丘黄土，千古青山。老僧同醉，残碑休打，宝剑羞看。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2762, "title": "〔黄钟〕人月圆", "author": "张可久", "body": "三高祠下天如镜，山色浸空蒙。莼羹张翰，渔舟范蠡，茶灶龟蒙。故人何在，前程那里，心事谁同？黄花庭院，青灯夜雨，白发秋风。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2763, "title": "〔黄钟〕人月圆", "author": "张可久", "body": "山藏白虎云藏寺，池上老梅枝。洞庭归兴，香柑红树，鲈脍银丝。白家池馆，吴王花草，长似坡诗。可人怜处，啼乌夜月，犹怨西施。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2764, "title": "〔正宫〕塞鸿秋", "author": "张可久", "body": "直钩曾下严滩钓，清风自学苏门啸；蜜蜂飞绕簪花帽，野猿坐守烧丹灶。扁舟范蠡高，五柳陶潜傲。南华梦里先惊觉。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2765, "title": "〔正宫〕醉太平", "author": "张可久", "body": "翩翩野舟，泛泛沙鸥。登临不尽古今愁，白云去留。凤凰台上青山旧，秋千墙里垂杨瘦，琵琶亭畔野花秋。长江自流。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2766, "title": "〔正宫〕醉太平", "author": "张可久", "body": "人皆嫌命窘，谁不见钱亲？水晶环入面糊盆，才沾粘便滚。文章糊了盛钱囤，门庭改作迷魂阵，清廉贬入睡馄饨。葫芦提倒稳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2767, "title": "〔仙吕〕锦橙梅", "author": "张可久", "body": "红馥馥的脸衬霞，黑髭髭的鬓堆鸦。料应他，必是个中人，打扮的堪描画。颤巍巍的插着翠花，宽绰绰的穿着轻纱。兀的不风韵煞人也嗏。是谁家，我不住了偷睛儿抹？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2768, "title": "〔中吕〕迎仙客", "author": "张可久", "body": "雨乍晴，月笼明。秋香院落砧杵鸣。二三更，千万声，捣碎离情。不管愁人听。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2769, "title": "〔中吕〕红绣鞋", "author": "张可久", "body": "绝顶峰攒雪剑，悬崖水挂冰帘，倚树哀猿弄云尖。血华啼杜宇，阴洞吼飞廉。比人心山末险！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2770, "title": "〔中吕〕红绣鞋", "author": "张可久", "body": "鸣玉珮凌烟图画，乐云村投老生涯。少年谁识故侯家？青蛇昏宝剑，团锦碎袍花。飞龙闲厩马。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2771, "title": "〔中吕〕红绣鞋", "author": "张可久", "body": "船系谁家古岸，人归何处青山。且将诗做画图看：雁声芦叶老，鹭影蓼花寒，鹤巢松树晚。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2772, "title": "〔中吕〕普天乐", "author": "张可久", "body": "蕊珠宫，蓬莱洞。青松影里，红藕香中。千机云锦重，一片银河冻。缥缈佳人双飞凤，紫箫寒月满长空。阑干晚风，菱歌上下，渔火西东。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2773, "title": "〔中吕〕普天乐", "author": "张可久", "body": "会真诗，相思债。花笺象管，钿盒金钗。雁啼明月中，人在青山外。独上危楼愁无奈，起西风一片离怀。白衣未来，东篱好在，黄菊先开。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2774, "title": "〔中吕〕普天乐", "author": "张可久", "body": "为谁忙？莫非命。西风驿马，落月书灯。青天蜀道难，红叶吴江冷。两字功名频看镜，不饶人白发星星。钓鱼子陵，思莼季鹰，笑我飘零。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2775, "title": "〔中吕〕普天乐", "author": "张可久", "body": "北邙烟，西州泪，先朝故家，破冢残碑。樽前有限杯，门外无常鬼。未冷鸳帏合欢被，画楼前玉碎花飞。悔之晚矣，蒲团纸被，归去来兮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2776, "title": "〔中吕〕喜春来", "author": "张可久", "body": "落红小雨苍苔径，飞絮东风细柳营。可怜客里过清明。不待听，昨夜杜鹃声。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2777, "title": "〔中吕〕喜春来", "author": "张可久", "body": "荷盘敲雨珠千颗，山背披云玉一蓑。半篇诗景费吟哦，芳草坡，松外采茶歌。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2778, "title": "〔中吕〕满庭芳", "author": "张可久", "body": "风波几场，急疏利锁，顿解名缰。故园老树应无恙？梦绕沧浪，伴赤松归欤子房，赋寒梅瘦却何郎。溪桥上，东风暗香，浮动月昏黄。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2779, "title": "〔中吕〕朝天子", "author": "张可久", "body": "与谁、画眉[1]，猜破风流谜。铜驼巷[2]里玉骢[3]嘶，夜半归来醉。小意收拾，怪胆矜持，不识羞谁似你！自知、理亏，灯下和衣睡。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2780, "title": "〔中吕〕齐天乐过红衫儿", "author": "张可久", "body": "人生底事辛苦，枉被儒冠误。读书，图，驷马高车。但沾着者也之乎，区区，牢落江湖，奔走在仕途。半纸虚名，十载功夫。人传《梁甫吟》，自献《长门赋》，谁三顾茅庐？白鹭洲边住，黄鹤矶头去。唤奚奴，鲙鲈鱼，何必谋诸妇。酒葫芦，醉模糊，也有安排我处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2781, "title": "〔中吕〕齐天乐过红衫儿", "author": "张可久", "body": "浮生扰扰红尘，名利君休问。闲人，贫，富贵浮云。乐林泉远害全身，将军，举鼎拔山，只落得自刎。学范蠡归湖，张翰思莼。田园富子孙，玉帛萦方寸，争如醉里乾坤。曾与高人论，不羡元戎印。浣花村，掩柴门，倒大无忧闷。共开樽，细论文，快乐清闲道本。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2782, "title": "〔中吕〕山坡羊", "author": "张可久", "body": "云松螺髻，香温鸳被，掩春闺一觉伤春睡。柳花飞，小琼姬，一声“雪下呈祥瑞”，团圆梦儿生唤起。“谁，不做美？呸，却是你！”", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2783, "title": "〔中吕〕山坡羊", "author": "张可久", "body": "危台凝伫，苍苍烟树，夕阳曾送龙舟去。映菰芦，捕鱼图，一竿风旆桥西路。人物风流闻上古。儒，秦太虚；湖，明月珠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2784, "title": "〔中吕〕卖花声", "author": "张可久", "body": "阿房舞殿翻罗袖，金谷名园起玉楼，隋堤古柳缆龙舟。不堪回首，东风还又，野花开暮春时候。\n美人自刎乌江岸，战火曾烧赤壁山，将军空老玉门关。伤心秦汉，生民涂炭，读书人一声长叹。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2785, "title": "〔中吕〕卖花声", "author": "张可久", "body": "十年落魄江滨客，几度雷轰荐福碑，男儿未遇暗伤怀。忆淮阴年少，灭楚为帅，气昂昂汉坛三拜。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2786, "title": "〔南吕〕四块玉", "author": "张可久", "body": "落帽风，登高酒。人远天涯碧云秋，雨荒篱下黄花瘦。愁又愁，楼上楼，九月九。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2787, "title": "〔双调〕庆东原", "author": "张可久", "body": "诗情放，剑气豪。英雄不把穷通较。江中斩蛟，云间射雕，席上挥毫。他得志笑闲人，他失脚闲人笑。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2788, "title": "〔双调〕庆东原", "author": "张可久", "body": "山容瘦，木叶凋。对西窗尽是诗材料。苍烟树杪，残雪柳条，红日花梢。他得志笑闲人，他失脚闲人笑。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2789, "title": "〔双调〕落梅风", "author": "张可久", "body": "江村路，水墨图，不知名野花无数。离愁满怀难寄书，付残潮落红流去。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2790, "title": "〔双调〕落梅风", "author": "张可久", "body": "秋千院，拜扫天，柳荫中躲莺藏燕。掩霜纨递将诗半篇，怕帘外卖花人见。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2791, "title": "〔双调〕水仙子", "author": "张可久", "body": "蝇头老子五千言，鹤背扬州十万钱，白云两袖吟魂健。赋庄生秋水篇，布袍宽风月无边。名不上琼林殿，梦不到金谷园，海上神仙。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2792, "title": "〔双调〕水仙子", "author": "张可久", "body": "天边白雁写寒云，镜里青鸾瘦玉人，秋风昨夜愁成阵。思君不见君，缓歌独自开樽。灯挑尽，酒半醺，如此黄昏。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2793, "title": "〔双调〕水仙子", "author": "张可久", "body": "夕阳芳草废歌台，老树寒鸦静御街，神仙环珮今何在？荒基生暮霭，叹英雄白骨苍苔。花已飘零去，山曾富贵来，俯仰伤怀。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2794, "title": "〔双调〕水仙子", "author": "张可久", "body": "朝朝琼树后庭花，步步金莲潘丽华，龙蟠虎踞山如画。伤心诗句多，危城落日寒鸦。凤不至空台上，燕飞来百姓家。恨满天涯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2795, "title": "〔双调〕殿前欢", "author": "张可久", "body": "钓鱼台[4]，十年不上野鸥猜。白云来往青山在，对酒开怀。欠伊周[5]济世才，犯刘阮贪杯戒，还李杜吟诗债。酸斋笑我，我笑酸斋。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2796, "title": "〔双调〕殿前欢", "author": "张可久", "body": "月笼沙，十年心事付琵琶。相思懒看帏屏画，人在天涯。春残豆蔻花，情寄鸳鸯帕，香冷荼架。旧游台榭，晓梦窗纱。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2797, "title": "〔双调〕殿前欢", "author": "张可久", "body": "望长安，前程渺渺鬓斑斑。南来北往随征雁，行路艰难。青泥小剑关，红叶湓江岸，白草连云栈。功名半纸，风雪千山。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2798, "title": "〔双调〕殿前欢", "author": "张可久", "body": "小阑干，又添新竹两三竿。倒持手版[6]搘颐看，容我偷闲。松风古砚寒，藓土白石烂，蕉雨疏花绽。青山爱我，我爱青山。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2799, "title": "〔双调〕折桂令", "author": "张可久", "body": "掩柴门啸傲烟霞，隐隐林峦，小小仙家。楼外白云，窗前翠竹，井底朱砂。五亩宅无人种瓜，一村庵有客分茶。春色无多，开到蔷薇，落尽梨花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2800, "title": "〔双调〕折桂令", "author": "张可久", "body": "对青山强整乌纱，归雁横秋，倦客思家。翠袖殷勤，金杯错落，玉手琵琶。人老去西风白发，蝶愁来明日黄花。回首天涯，一抹斜阳，数点寒鸦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2801, "title": "〔双调〕折桂令", "author": "张可久", "body": "唤西施伴我西游，客路依依，烟水悠悠。翠树啼鹃，青天旅雁，白雪盟鸥[7]。人倚梨花病酒，月明杨柳维舟。试上层楼，绿满江南，红褪春愁。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2802, "title": "〔双调〕折桂令", "author": "张可久", "body": "画船儿载不起离愁。人在西陵，恨满东州。懒上归鞍，慵开泪眼，怕倚层楼。春去春来，管送别依依岸柳。潮生潮落，会忘机泛泛沙鸥。烟水悠悠，有句相酬，无计相留。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2803, "title": "〔双调〕清江引", "author": "张可久", "body": "西风信来家万里，问我归期未？雁啼红叶天，人醉黄花地，芭蕉雨声秋梦里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2804, "title": "〔双调〕清江引", "author": "张可久", "body": "黄莺乱啼门外柳，细雨清明后。能消几日春，又是相思瘦。梨花小窗人病酒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2805, "title": "〔双调〕清江引", "author": "张可久", "body": "纶巾紫髯风满把[8]，老向辕门[9]下。霜明宝剑花，尘暗银鞍帕[10]。江边草青闲战马。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2806, "title": "〔越调〕小桃红", "author": "张可久", "body": "一城秋雨豆花凉。闲倚平山望。不似年时鉴湖上，锦云香，采莲人语荷花荡。西风雁行，清溪渔唱，吹恨入沧浪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2807, "title": "〔越调〕天净沙", "author": "张可久", "body": "嗈嗈落雁平沙，依依孤鹜残霞，隔水疏林几家。小舟如画，渔歌唱入芦花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2808, "title": "〔越调〕天净沙", "author": "张可久", "body": "青苔古木萧萧，苍云秋水迢迢。红叶山斋小小。有谁曾到？探梅人过溪桥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2809, "title": "〔越调〕天净沙", "author": "张可久", "body": "红蕉隐隐窗纱，朱帘小小人家。绿柳匆匆去马。断桥西下，满湖烟雨愁花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2810, "title": "〔越调〕寨儿令", "author": "张可久", "body": "写旧游，换新愁。玉箫寒酒醒江上楼，黄鹤矶头，白鹭汀洲，烟水共悠悠。人何在七国春秋，浪淘尽千古风流。隋堤[11]犹翠柳，汉土自鸿沟[12]。休，来往愧沙鸥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2811, "title": "〔越调〕寨儿令", "author": "张可久", "body": "你见么？我愁他，青门几年不种瓜。世味嚼蜡，尘事抟沙，聚散树头鸦。自休官清煞陶家，为调羹俗了梅花。饮一杯金谷酒，分七碗玉川茶。嗏，不强如坐三日县官衙。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2812, "title": "〔越调〕寨儿令", "author": "张可久", "body": "石斗滩，剑门关[13]，上青天不如行路难。世事循环，春色阑珊，人老且投闲。文君古调休弹，疏翁樵唱新刊。梅亭十二阑，茅屋两三间。看，一带好江山。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2813, "title": "〔越调〕凭阑人", "author": "张可久", "body": "远水晴天明落霞。古岸渔村横钓槎。翠帘沽酒家。画桥吹柳花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2814, "title": "〔越调〕凭阑人", "author": "张可久", "body": "二客同游过虎溪，一径无尘穿翠微。寸心流水知，小窗明月归。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2815, "title": "〔越调〕凭阑人", "author": "张可久", "body": "江水澄澄江月明，江上何人玉筝？隔江和泪听，满江长叹声。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2816, "title": "〔南吕〕一枝花", "author": "张可久", "body": "长天落彩霞，远水涵秋镜。花如人面红，山似佛头青。生色围屏，翠冷松云径，嫣然眉黛横。但携将旖旎浓香，何必赋横斜瘦影。\n〔梁州〕挽玉手留连锦英，据胡床指点银瓶。素娥不嫁伤孤零。想当年小小，问何处卿卿。东坡才调，西子娉婷，总相宜千古留名。吾二人此地私行，六一泉亭上诗成，三五夜花前月明，十四弦指下风生。可憎，有情，捧红牙合和伊州令。万籁寂，四山静。幽咽泉流水下声，鹤怨猿惊。\n〔尾声〕岩阿禅窟鸣金磬，波底龙宫漾水精。夜色清，酒力醒。宝篆销，玉漏鸣。笑归来仿佛已二更，煞强似踏雪寻梅灞桥冷。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2817, "title": "〔中吕〕上小楼", "author": "任昱", "body": "荆棘满途，蓬莱闲住。诸葛茅庐，陶令松菊，张翰莼鲈。不顺俗，不妄图，清高风度。任年年落花飞絮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2818, "title": "〔中吕〕红绣鞋", "author": "任昱", "body": "新亭馆相迎相送，古云山宜淡宜浓。画船归去有渔篷。随人松岭月，醒酒柳桥风。索新诗红袖拥。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2819, "title": "〔双调〕沉醉东风", "author": "任昱", "body": "有待江山信美，无情岁月相催。东里来，西邻醉，听渔樵讲些兴废。依旧中原一布衣，更休想麒麟画里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2820, "title": "〔双调〕折桂令", "author": "任昱", "body": "毳袍[1]宽两袖风烟，来自西州，游遍中原。锦句诗余，彩云花下，璧月樽前。今乐府知音状元，古词林饱记神仙。名不虚传，三峡飞泉，万籁号天。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2821, "title": "〔双调〕清江引", "author": "任昱", "body": "南山豆苗荒数亩，拂袖先归去。高官鼎内鱼，小吏罝[2]中兔。争似闭门闲看书！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2822, "title": "〔双调〕清江引", "author": "任昱", "body": "吴山越山山下水，总是凄凉意。江流今古愁，山雨兴亡泪。沙鸥笑人闲未得。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2823, "title": "〔双调〕清江引", "author": "钱霖", "body": "梦回昼长帘半卷，门掩荼院。蛛丝挂柳棉，燕嘴粘花片，啼莺一声春去远。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2824, "title": "〔般涉调〕哨遍", "author": "钱霖", "body": "试把贤愚穷究，看钱奴自古呼铜臭。徇己苦贪求，待不教泉货[1]周流。忍包羞，油铛插手，血海舒拳，肯落他人后？晓夜寻思机彀，缘情钩距[2]，巧取旁搜。蝇头场上苦驱驰，马足尘中厮追逐，积攒下无厌就。舍死忘生，出乖弄丑。\n〔耍孩儿〕安贫知足神明佑，好聚敛多招悔尤。王戎[3]遗下旧牙筹，夜连明计算无休。不思日月搬乌兔，只与儿孙作马牛。添消瘦，不调裀鼎[4]，恣逞戈矛。\n〔十煞〕渐消磨双脸春，已雕飕两鬓秋。终朝不乐眉长皱，恨不得柜头钱五分息招人借，架上[5]一周年不放赎。狠毒性如狼狗，把平人骨肉，做自己膏油。\n〔九煞〕有心待拜五侯，教人唤甚半州。忍饥寒攒得家私厚。待垒做钱山儿倩军士喝号提铃守，怕化做钱龙[6]儿请法官行罡布气[7]留。半炊儿八遍把牙关叩，只愿得无支有管，少出多收。\n〔八煞〕亏心事尽意为，不义财尽力掊，那里问亲兄弟亲姊妹亲姑舅。只待要春风金谷骄王恺[8]，一任教夜雨新丰困马周[9]。无亲旧，只知敬明眸皓齿，不想共肥马轻裘。\n〔七煞〕资生利转多，贪婪意不休，为锱铢[10]舍命寻争斗。田连阡陌心犹窄，架插诗书眼不瞅。也学采东篱菊，子是个装呵元亮，豹子浮丘[11]。\n〔六煞〕恨不得扬子江变做酒，枣穰金[12]积到斗。为几文垫[13]背钱受了些旁人咒，一斗粟与亲眷分了颜面，二斤麻把相知结下寇仇。真纰缪，一味的骄而且吝，甚的是乐以忘忧。\n〔五煞〕这财曾燃了董卓脐，曾枭了元载头，聚而不散遭殃咎。怕不是堆金积玉连城富，贬眼早野草闲花满地愁。干生受，生财有道，受用无由。\n〔四煞〕有一日大小运并在命宫，死囚限缠在卯酉，甚的散得疾子为你聚来得骤。恰待调和新曲歌金帐，逼临得红粉[14]佳人坠玉楼。难收救，一壁厢投河奔井，一壁厢烂额焦头。\n〔三煞〕窗隔每都飐飐的飞，椅桌每都出出的走，金银钱米都消为尘垢。山魈木客相呼唤，寡宿孤辰厮趁逐。喧白昼，花月妖将家人狐媚，虚耗鬼把仓库潜偷。\n〔二煞〕恼天公降下灾，犯官刑系在囚。他用钱时难参透，待买他上木驴钉子轻轻钉，吊脊筋钩儿浅浅钩。便用杀难宽宥，魂飞荡荡，魄散悠悠。\n〔尾〕出落他平生聚敛的情，都写做临刑犯罪由。将他死骨头告示向通衢里甃[15]，任他日炙风吹慢慢朽。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2825, "title": "〔黄钟〕人月圆", "author": "徐再思", "body": "江皋楼观前朝寺，秋色入秦淮。败垣芳草，空廊落叶，深砌苍苔。远人南去，夕阳西下，江水东来。木兰花在，山僧试问，知为谁开？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2826, "title": "〔中吕〕朝天子", "author": "徐再思", "body": "里湖，外湖，无处是无春处。真山真水真画图，一片玲珑玉。宜酒宜诗，宜晴宜雨。销金锅、锦绣窟。老苏，老逋，杨柳堤梅花墓。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2827, "title": "〔中吕〕朝天子", "author": "徐再思", "body": "远山，近山，一片青无间。逆流泝上乱石滩，险似连云栈。落日昏鸦，西风归雁。叹崎岖途路难。得闲，且闲，何处无鱼羹饭。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2828, "title": "〔中吕〕普天乐", "author": "徐再思", "body": "玉华寒，冰壶冻。云间玉兔，水面苍龙。酒一樽，琴三弄。唤起凌波仙人梦，倚阑干满面天风。楼台远近，乾坤表里，江汉西东。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2829, "title": "〔中吕〕普天乐", "author": "徐再思", "body": "晚云收，夕阳挂，一川枫叶，两岸芦花。鸥鹭栖，牛羊下。万顷波光天图画，水晶宫冷浸红霞。凝烟暮景，转晖老树，背影昏鸦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2830, "title": "〔中吕〕阳春曲", "author": "徐再思", "body": "水深水浅东西涧，云去云来远近山。秋风征棹钓鱼滩，烟树晚，茅舍两三间。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2831, "title": "〔商调〕梧叶儿", "author": "徐再思", "body": "芳草思南浦，行云梦楚阳，流水恨潇湘。花底春莺燕，钗头金凤凰，被面绣鸳鸯。是几等儿眠思梦想。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2832, "title": "〔越调〕天净沙", "author": "徐再思", "body": "昨朝深雪前村。今宵淡月黄昏。春到南枝几分？水香冰晕。唤回逋老诗魂。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2833, "title": "〔越调〕凭阑人", "author": "徐再思", "body": "髻拥春云松玉钗，眉淡秋山羞镜台。海棠开未开，粉郎来未来？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2834, "title": "〔越调〕凭阑人", "author": "徐再思", "body": "前日春从愁里得，今日春从愁里归。避愁愁不离，问春春不知。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2835, "title": "〔双调〕沉醉东风", "author": "徐再思", "body": "一自多才间阔，几时盼得成合？今日个猛见他门前过。待唤着怕人瞧科。我这里高唱当时水调歌，要识得声音是我。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2836, "title": "〔双调〕蟾宫曲", "author": "徐再思", "body": "紫霜毫是是非非，万古虚名，一梦初回。失又何愁，得之何喜，闷也何为？落日外萧山翠微，小桥边古寺残碑。文藻珠玑，醉墨淋漓，何似班超，投却毛锥[3]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2837, "title": "〔双调〕蟾宫曲", "author": "徐再思", "body": "平生不会相思，才会相思，便害相思。身似浮云，心如飞絮，气若游丝。空一缕余香在此，盼千金游子何之。证候来时，正是何时？灯半昏时，月半明时。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2838, "title": "〔双调〕清江引", "author": "徐再思", "body": "相思有如少债的，每日相催逼。常挑着一担愁，准不了三分利。这本钱见他时才算得。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2839, "title": "〔双调〕水仙子", "author": "徐再思", "body": "一声梧叶一声秋。一点芭蕉一点愁。三更归梦三更后。落灯花棋未收，叹新丰逆旅淹留。枕上十年事，江南二老忧，都到心头。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2840, "title": "〔双调〕水仙子", "author": "徐再思", "body": "九分恩爱九分忧，两处相思两处愁，十年迤逗十年受。几遍成几遍休，半点事半点惭羞。三秋恨三秋感旧，三春怨三春病酒，一世害一世风流。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2841, "title": "〔双调〕殿前欢", "author": "徐再思", "body": "老苍龙，避乖高卧此山中。岁寒心不肯为梁栋，翠蜿蜒俯仰相从。秦皇旧日封，靖节何年种，丁固当时梦？半溪明月，一枕清风。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2842, "title": "〔双调〕蟾宫曲", "author": "孙周卿", "body": "草团标正对山凹。山竹炊粳，山水煎茶。山芋山薯，山葱山韭，山果山花。山溜响冰敲月牙，扫山云惊散林鸦。山色元佳，山景堪夸，山外晴霞，山下人家。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2843, "title": "〔南吕〕骂玉郎过感皇恩采茶歌", "author": "顾德润", "body": "蛛丝满甑尘生釜，浩然气尚吞吴。并州每恨无亲故。三匝乌，千里驹，中原鹿。走遍长途，反下乔木。若立朝班，乘骢马，驾高车。常怀卞玉，敢引辛裾。羞归去，休进取，任揶揄。暗投珠，叹无鱼。十年窗下万言书。欲赋生来惊人语，必须苦下死工夫。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2844, "title": "〔越调〕黄蔷薇带庆元贞", "author": "顾德润", "body": "步秋香径晚，怨翠阁衾寒。笑把霜枫叶拣，写罢衷情兴懒。几年月冷倚阑干，半生花落盼天颜[1]，九重云锁隔巫山[2]。休看！作等闲，好去到人间。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2845, "title": "〔双调〕清江引", "author": "曹德", "body": "长门柳丝千万结，风起花如雪。离别复离别，攀折更攀折，苦无多旧时枝叶也。\n长门柳丝千万缕，总是伤心树。行人折嫩条，燕子衔轻絮，都不由凤城春做主。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2846, "title": "〔双调〕庆东原", "author": "曹德", "body": "低茅舍，卖酒家，客来旋把朱帘挂。长天落霞，方池睡鸭，老树昏鸦。几句杜陵诗，一幅王维画。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2847, "title": "〔失宫调〕三棒鼓声频", "author": "曹德", "body": "先生醉也，童子扶著。有诗便写，无酒重赊，山声野调欲唱些，俗事休说。问青天借得松间月，陪伴今夜。长安此时春梦热，多少豪杰，明朝镜中头似雪，乌帽难遮。星般大县儿难弃舍，晚入庐山社。比及眉未攒，腰曾折，迟了也，去官陶靖节。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2848, "title": "〔越调〕黄蔷薇过庆元贞", "author": "高克礼", "body": "燕燕别无甚孝顺，哥哥行在意殷勤。玉纳子藤箱儿问肯，便待要锦帐罗帏就亲。吓得我惊急列蓦出卧房门，他措支剌扯住我皂腰裙，我软兀剌好话儿倒温存：“一来怕夫人情性哏，二来怕误妾百年身。”", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2849, "title": "〔中吕〕普天乐", "author": "王仲元", "body": "树杈枒，藤缠挂；冲烟塞雁，接翅昏鸦；展江乡水墨图，列湖口潇湘画。过浦穿溪沿江汊，问孤航夜泊谁家？无聊倦客，伤心逆旅，恨满天涯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2850, "title": "〔般涉调〕哨遍", "author": "高安道", "body": "十载寒窗诚意，书生皆想登科记[1]。奈时运未亨通，混尘嚣日日衔杯，厮伴着青云益友。谈笑忘机，出语无俗气。偶题起老成靴脚[2]，人人道好，个个称奇。若要做四缝磕瓜头[3]，除是南街小王皮。快做能裁，着脚中穿，在城第一。\n〔耍孩儿〕铺中选就对新材式，嘱付咱穿的样制。“裁缝时用意下工夫，一桩桩听命休违。细锥粗线禁登陟，厚底团根教壮实。线脚儿深深勒，靿子[4]齐上下相趁，口[5]宽脱着容易。”\n〔七煞〕“探头休蹴尖，衬薄怕汗湿。减刮的休显刀痕迹，剜裁的脸戏儿微分间短，拢揎[6]得腮帮儿省可里肥。要着脚随人意，休教脑窄，莫得趺低。”\n〔六煞〕丁宁说了一回，分明听了半日，交付与价钞先伶俐。“从前名誉休多说，今后生活便得知，限三日穿新的！”“您休说谎，俺不催逼。”\n〔五煞〕人言他有信行，谁知道不老实。许多时刬地[7]无消息。量底样九遍家掀皮尺，寻裁刀数遭家取磨石。做尽荒獐势，走的筋舒力尽，憔的眼运头低。\n〔四煞〕几番煨胶锅借楦头[8]，数遍粘主根买桦皮，喷了水埋在糠槽[9]内。今朝取了明朝取，早又催来晚又催。怕越了靴行例，见天阴道胶水解散，恰天晴说皮糙燋黧。\n〔三煞〕走的来不发心，燋的荒[10]见次第。计数儿算有三千个誓。迷奚着谎眼先陪笑，执闭着顽心更道易。巴的今日，罗街拽巷，唱叫扬疾。\n〔二煞〕好一场恶一场，哭不得笑不得。软厮禁硬厮拼[11]都不济。调脱空对众攀今古，念条款依然说是非。难回避，骷髅卦[12]几番自说，猫狗砌数遍亲题。\n〔一煞〕又不是凤麒麟钩绊着缝，又不是鹿衔花窟嵌着刺，又不是倒钩针背衬上加些功绩，又不是三垂云银线分花样，又不是一抹圈金沿宝里。每日闲淘气，子索行监坐守，谁敢东走西移。\n〔尾〕初言定正月终，调发[13]到十月一。新靴子投至能够完备，旧兀剌先磨了半截底。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2851, "title": "〔双调〕燕引雏", "author": "大食惟寅", "body": "气横秋，心驰八表快神游。词林谁出先生右？独占鳌头。诗成神鬼愁，笔落龙蛇走，才展山川秀。声传南国，名播中州。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2852, "title": "〔南吕〕一枝花", "author": "亢文苑", "body": "琴声动鬼神，剑气冲牛斗；西风张翰志，落日仲宣楼。潘鬓成秋，渐觉休文瘦，卧元龙百尺楼。自扶囊拄杖挑包，醉濯足新丰换酒。\n〔梁州〕尽是些喧晓日茅檐燕雀，故意困盐车千里骅骝，英雄肯落儿曹彀？乾坤倦客，江海扁舟；床头金尽，壮志难酬。任飘零身寄南州，恨黄尘敝尽貂裘。看别人苫眼铺眉，笑自己缄舌闭口，但则索向寒窗袖手藏头。如今，更有，那屠龙计策干生受。慢劳攘慢奔走，顾我真成丧家狗，计拙如鸠。\n〔尾〕蛟龙须待春雷吼，鹗腾风万里游；大丈夫峥嵘恁时候，扶汤佐周，光前耀后，直教万古清名长不朽。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2853, "title": "〔仙吕〕后庭花", "author": "吕止庵", "body": "西风黄叶疏，一年音信无。要见除非梦，梦回总是虚。梦虽虚，犹兀自暂时节相聚。近新来和梦无。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2854, "title": "〔仙吕〕后庭花", "author": "吕止庵", "body": "功名览镜看，悲歌把剑弹。心事鱼缘木，前程羝触藩。世途艰，艰声长叹，满天星斗寒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2855, "title": "〔中吕〕粉蝶儿", "author": "孙叔顺", "body": "海马闲骑，则为瘦人参请他医治。背药包的刘寄奴跟随，一脚的陌门东，来到这干阁内，飞帘簌地。能医其乡妇沉疾。因此上，共宾郎结成欢会。\n〔醉春风〕说远志、诉莲心、靠肌酥、偎玉体、食膏粱，五味卧重裀，阳起是你，你。受用他笑吐丁香、软柔钟乳，到有些五灵之气。\n〔迎仙客〕行过芍药圃、菊花篱，沉香亭色情何太急！停立在曲槛边，从容在芳径里，待黄昏不想当归，尚有百部徘徊意。\n〔红绣鞋〕半夏遐蛇床上同睡，芫花边似燕子双飞。则道洞房风月少人知，不想被红娘先蹴破，使君子受凌迟，便有他白头公难救你。\n〔耍孩儿〕木贼般合解到当官跪，刀笔吏焉能放你。便将白纸取招伏，选剥了裩布无衣。荜澄茄拷打得青皮肿，玄胡索拴缚得狗脊低。你便穿山甲应何济，议论得罪名管仲，毕拨得文案无疑。\n〔三煞〕他做官司的剖决明，告私情的能指实，监囚在里人心碎。一个旱莲腮空滴白凡泪，一个漏芦腿难禁苦杖笞。吊疼痛，添憔悴。问甚么干连你父子？可惜教带累了乌梅。\n〔二煞〕意浓甜有苦参，事多凶大戟，今日个身遭缧绁，犹道是心甘遂。清廉家却有这糊突事，时罗姐难为官宜妻，浪荡子合当废。破故纸揩不了腥臭，寒水石洗不尽身肌。\n〔一煞〕向雨余凉夜中，对天南星月底，说合成织女牵牛会。指望常山远水恩情久，不想这剪草除根巾帻低，那一个画不成青黛蛾眉。\n〔尾〕骂你个辱先灵的蒋太医，我看你怎回乡归故里！蔓荆子，续断了通奸罪，则被那散杏子的康瘤儿笑杀你！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2856, "title": "〔仙吕〕解三酲", "author": "真氏", "body": "奴本是明珠擎掌，怎生的流落平康。对人前乔做作娇模样，背地里泪千行。三春南国怜飘荡，一事东风没主张。添悲怆，那里有珍珠十斛，来赎云娘！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2857, "title": "〔双调〕殿前欢", "author": "景元启", "body": "月如牙，早庭前疏影印窗纱。逃禅老笔应难画，别样清佳。据胡床再看咱，山妻骂：“为甚情牵挂？”大都来梅花是我，我是梅花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2858, "title": "〔仙吕〕寄生草", "author": "查德卿", "body": "姜太公贱卖了磻溪岸，韩元帅命博得拜将坛。羡傅说[1]守定岩前版，叹灵辄吃了桑间饭，劝豫让吐出喉中炭。如今凌烟阁一层一个鬼门关，长安道一步一个连云栈。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2859, "title": "〔仙吕〕一半儿", "author": "查德卿", "body": "自将杨柳品题人[2]，笑拈[3]花枝比较春，输与海棠三四分。再偷匀[4]，一半儿胭脂一半儿粉。\n绿窗时有唾茸粘，银甲频将彩线挦[5]，绣到凤凰心自嫌。按春纤，一半儿端相一半儿掩。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2860, "title": "〔中吕〕普天乐", "author": "查德卿", "body": "鹧鸪词，鸳鸯帕，青楼梦断，锦字书乏。后会绝，前盟罢。淡月香风秋千下，倚阑干人比梨花。如今那里？依栖何处？流落谁家？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2861, "title": "〔越调〕柳营曲", "author": "查德卿", "body": "临故国，认残碑，伤心六朝如逝水。物换星移，城是人非，今古一枰棋。南柯梦一觉初回，北邙坟三尺荒堆。四围山护绕，几处树高低。谁，曾赋黍离离？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2862, "title": "〔越调〕柳营曲", "author": "查德卿", "body": "烟艇闲，雨蓑干，渔翁醉醒江上晚。啼鸟关关，流水潺潺，乐似富春山。数声柔橹江湾，一钩香饵波寒。回头观兔魄，失意放渔竿。看，流下蓼花滩。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2863, "title": "〔双调〕蟾宫曲", "author": "查德卿", "body": "问从来谁是英雄？一个农夫，一个渔翁。晦迹南阳，栖身东海，一举成功。八阵图名成卧龙，《六韬》书功在非熊。霸业成空，遗恨无穷。蜀道寒云，渭水秋风。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2864, "title": "〔双调〕蟾宫曲", "author": "查德卿", "body": "倚西风百尺层楼，一道秦淮，九点齐州。塞雁南来，夕阳西下，江水东流。愁极处消除是酒，酒醒时依旧多愁。山岳糟丘，湖海杯瓯。醉了方休，醒后从头。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2865, "title": "〔越调〕天净沙", "author": "吴西逸", "body": "长江万里归帆，西风几度阳关，依旧红尘满眼。夕阳新雁，此情时拍阑干。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2866, "title": "〔越调〕天净沙", "author": "吴西逸", "body": "楚云飞满长空，湘江不断流东。何事离多恨冗？夕阳低送，小楼数点残鸿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2867, "title": "〔越调〕天净沙", "author": "吴西逸", "body": "江亭远树残霞，淡烟芳草平沙。绿柳阴中系马。夕阳西下，水村山郭人家。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2868, "title": "〔双调〕清江引", "author": "吴西逸", "body": "白雁乱飞秋似雪，清露生凉夜。扫却石边云，醉踏松根月，星斗满天人睡也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2869, "title": "〔双调〕寿阳曲", "author": "吴西逸", "body": "萦心事，惹恨词，更那堪动人秋思。画楼边几声新雁儿，不传书摆成个“愁”字。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2870, "title": "〔双调〕雁儿落带过得胜令", "author": "吴西逸", "body": "春花闻杜鹃，秋月看归燕。人情薄似云，风景疾如箭。留下买花钱，趱入种桑园。茅苫三间厦，秧肥数顷田。床边，放一册冷淡渊明传；窗前，抄几联清新杜甫篇。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2871, "title": "〔黄钟〕昼夜乐", "author": "赵显宏", "body": "风送梅花过小桥，飘飘。飘飘地乱舞琼瑶，水面上流将去了。觑绝时落英无消耗，似才郎水远山遥。怎不焦。今日明朝，今日明朝，又不见他来到。〔幺〕佳人，佳人多命薄。今遭，难逃。难逃他粉悴烟憔，直恁般鱼沉雁杳。谁承望拆散了鸾凰交，空教人梦断魂劳。心痒难揉，心痒难揉。盼不得鸡儿叫。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2872, "title": "〔南吕〕一枝花", "author": "唐毅夫", "body": "不呈六出祥，岂应三白瑞？易添身上冷，能使腹中饥。有甚稀奇。无主向沿街坠，不着人到处飞。暗敲窗有影无形，偷入户潜踪蹑迹。\n〔梁州〕才苫上茅庵草舍，又钻入破壁疏篱，似扬花滚滚轻狂势。你几曾见贵公子锦裀绣褥？你多曾伴老渔翁箬笠蓑衣？为飘风胡作胡为，怕腾云相趁相随。只着你冻的个孟浩然挣挣痴痴，只着你逼的个林和靖钦钦历历，只着你阻的个韩退之哭哭啼啼。更长，漏迟，被窝中无半点阳和气。恼人眠，搅人睡。你那冷燥皮肤似铁石，着我怎敢相偎？\n〔尾〕一冬酒债因他累，千里关山被你迷。似这等浪蕊闲花也不是久长计，尽飘零数日，扫除做一堆，我将你温不热薄情儿化做了水。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2873, "title": "〔双调〕寿阳春", "author": "李爱山", "body": "离京邑，出凤城。山林中隐名埋姓。乱纷纷世事不欲听，倒大来耳根清净。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2874, "title": "〔越调〕天净沙", "author": "朱庭玉", "body": "庭前落尽梧桐，水边开彻芙蓉。解与诗人意同，辞柯霜叶，飞来就我题红。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2875, "title": "〔大石调〕青杏子", "author": "朱庭玉", "body": "游宦又驱驰，意徘徊执手临岐。欲留难恋应无计。昨宵好梦，今朝幽怨，何日归期？\n〔归塞北〕肠断处，取次[1]作别离。五里短亭人上马，一声长叹泪沾衣。回首各东西。\n〔初问口〕万叠云山，千重烟水，音书纵有凭谁寄？恨萦牵，愁堆积。天，天不管人憔悴！\n〔怨别离〕感情风物正凄凄，晋山青，汾水碧。谁返扁舟芦花外，归棹急，惊散鸳鸯相背飞。\n〔擂鼓体〕一鞭行色苦相催。皆因些子、浮名薄利，萍梗飘流无定迹。好在[2]阳关图画里。\n〔催拍子带赚煞〕未饮离杯心如醉，须信道“送君千里”。怨怨哀哀，凄凄苦苦啼啼。唱道[3]分破鸾钗，丁宁嘱咐好将息。不枉了男儿堕志气，消得英雄眼中泪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2876, "title": "〔双调〕行香子", "author": "朱庭玉", "body": "烟草萋萋，霜叶飞飞。落闲阶不管狼籍。雁儿才过，燕子先归。盼佳音，无佳信，误佳期。\n〔幺〕帘幕空垂。院宇幽凄。步回廊自恨别离。鬅松鬓发，束减腰围。见人羞，惊人问，怕人知。\n〔乔木查〕但凭高望远，谩把阑干倚。不信功名犹未已。知他何处也，歌酒狂迷。\n〔天仙令〕相思忆。长是泪沾衣。恨满西风，情随逝水。闲恨与闲情，何日终极。伤心眼前无限景，都撮上愁眉。\n〔离亭宴带歇指煞〕橹声齐和归帆急。渔歌渐远鸣榔息。尖青寸碧，遥岑叠连天际。暮霭生，孤烟起。掩映残霞落日。江上两三家，山前六七里。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2877, "title": "〔越调〕小桃红", "author": "李伯瑜", "body": "水胎毡衬[1]要柔和，用最软的皮儿裹。手内无他煞难过。得来呵，普天下好净也应难躲。兀的般砌末，守着个粉脸儿色末，诨广笑声多。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2878, "title": "〔中吕〕阳春曲", "author": "李德载", "body": "茶烟一缕轻轻扬，搅动兰膏四座香。烹煎妙手赛维扬。非是谎，下马试来尝！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2879, "title": "〔中吕〕阳春曲", "author": "李德载", "body": "蒙山顶上春光早，扬子江心水味高。陶家学士更风骚。应笑倒，销金帐饮羊羔。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2880, "title": "〔中吕〕阳春曲", "author": "李德载", "body": "金芽嫩采枝头露，雪乳香浮塞上酥。我家奇品世间无。君听取，声价彻皇都。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2881, "title": "〔正宫〕醉太平", "author": "程景初", "body": "恨绵绵深宫怨女，情默默梦断羊车，冷清清长门寂寞长青芜。日迟迟春风院宇，泪漫漫介破琅玕玉。闷淹淹散心出户闲凝伫，昏惨惨晚烟妆点雪模糊，淅零零洒梨花暮雨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2882, "title": "〔正宫〕端正好", "author": "孙季昌", "body": "《鸳鸯被》半床闲，《蝴蝶梦》孤帏静；常则是《哭香囊》两泪盈盈。若是这《姻缘簿》上合该定，有一日《双驾车》把香肩并。\n〔滚绣球〕常记的《曲江池》丽日晴，正对着春风《细柳营》；初相逢在《丽春园》遣兴，便和他《谒浆的崔护》留情。曾和他在《万花堂》讲志诚，《锦香亭》设誓盟；谁承望下场头半星儿不应，央及杀《调风月》燕燕莺莺。则被这《西厢待月张君瑞》，送了这《花月东墙董秀英》，盼杀君卿。\n〔倘秀才〕《玩江楼》围着画屏，见一只《采莲舟》斜弯在蓼汀，待和他《竹叶传情》诉咱闷萦；《并头莲》分做两下，《鸳鸯会》不完成，知他是怎生？\n〔滚绣球〕付能的《潇湘夜雨》晴，早闪出《乌林皓月》明，正《孤雁汉宫秋》静，知他是甚情怀《月夜闻筝》？那时节理残妆对《玉镜台》，推烧香到《拜月亭》；则被这《梅香》紧将咱随定，不能够写相思《红叶题情》。指望似多情《双渐怜苏小》，到做了薄幸《王魁负桂英》，撇得我冷冷清清。\n〔倘秀才〕《金凤钗》斜簪在鬓影，《抱妆盒》寒侵倦整，想《踏雪寻梅》路怎行？弄黄昏《梅梢月》，香正满《酷寒亭》，伤情对景。\n〔叨叨令〕当日被《破连环》说啜得再成交颈，谁承望《错立身》的子弟无音信；闪得我似《离魂倩女》相思病，将一个《魔合罗》脸儿消磨尽。径不着也么哥，如今这《谎郎君》一个个传槽病。\n〔脱布衫〕我便是《蓝桥驿》实志真诚，他便似《竹林寺》有影无形，受寂寞似《越娘背灯》，恨别离如《乐昌分镜》。\n〔小梁州〕他便是《柳毅传书》住洞庭，《千里独行》。《吹箫》伴侣冷清清，我待学《孟姜女》般真诚性，我则怕《啼哭倒了长城》。\n〔幺〕《京娘怨》杀成孤另，怨你个《画眉的张敞》杂情；揣着窃玉心，《偷香》性。我则学《举案齐眉》，《贤孝牌》上立个清名。\n〔尾〕《金钗剪烛》人初静，《彩扇题诗》句未成。《后庭花》歌残《玉树》声，《琵琶怨》凄凉不忍听。比《题桥的相如》忒寡情，《戏妻秋胡》不老成。想则想《关山远》路程，恨则恨《衣锦还乡》不见影。则不如一纸《刘公书》谨缄定，寄与你个《三负心》的敲才自思省。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2883, "title": "〔中吕〕朝天子", "author": "李致远", "body": "梵宫、晚钟。落日蝉声送。半规凉月半帘风，骚客情尤重。何处楼台，笛声悲动？二毛斑秋夜永。楚峰、几重？遮不断相思梦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2884, "title": "〔中吕〕红绣鞋", "author": "李致远", "body": "梦断陈王罗袜，情伤学士琵琶。又见西风换年华。数杯添泪酒，几点送秋花，行人天一涯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2885, "title": "〔双调〕落梅风", "author": "李致远", "body": "斜阳外，春雨足，风吹皱一池寒玉。画楼中有人情正苦，杜鹃声莫啼归去。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2886, "title": "〔般涉调〕哨遍", "author": "杨立斋", "body": "张五牛、商正叔编《双渐小卿》，赵真卿善歌。立斋见杨玉娥唱其曲，因作〔鹧鸪天〕及〔哨遍〕以咏之。\n〔鹧鸪天〕烟柳风花锦作园，霜芽露叶玉装船。谁知皓齿纤腰会，只在轻衫短帽边。啼玉靥，咽冰弦，五牛身后更无传。词人老笔佳人口，再唤春风到眼前。\n〔哨遍〕世事抟沙嚼蜡，等闲荣辱休惊讶，日月不饶咱。晓窗前拂净菱花，试觑咱，虽是闲愁无种，闲闷无芽，子敢衠种出星星发。知进退宜休罢，便今日苏秦六国，明日早贾谊长沙，不如买牛学种洛阳田，抱瓮自浇邵平瓜。向甚云栈挥鞭，沧海撑舟，斗牛泛槎。\n〔幺〕好向名利场中一纳头，剩告取些松宽暇。且莫住山凹，清闲中不见个生涯。向甚末，南邻富贵，北里奢华，只有此身无价。幸遇明时德化，除徭役拯济贫乏。救得这困鱼腮惊急列地脱了香钩，盖因那饿虎血模糊地污了烟，方表圣德无加。\n〔耍孩儿〕对江山满目真堪画，休把这媚景良辰作塌。清风明月不拈钱，闻未老只合欢洽。问甚往来燕子春秋社，说怎末辛苦蜂儿早晚衙。休呆发，便得征西车马，争如杜曲桑麻。\n〔幺〕莫将愁字儿眉尖上挂，得一笑处笑一时半霎。百钱长向杖头挑，没拘束到处行踏。饥时节选着那六局[1]全食店里添些个气，渴时节拣那百尺高楼上咽数盏儿巴。更那碗清茶罢，听俺几回儿把戏也不村呵。\n〔七煞〕据小的每，大厮八，着几条坐木做陈蕃榻。谢尊官肯把荒场降，劳贵脚还将贱地来踏。棚上下，对文星乐宿，唱唱唦唦。\n〔六〕前汉又陈，后汉又乏，古尚书团掿损殷周夏，五代史止是谈些更变，三国志无过说些战伐，也不希咤，终少些团香弄玉，惹草粘花。\n〔五〕这个才子文艺高，那个佳人聪俊雅，可知道共把青鸾跨。一个是纱巾蕉扇睁睁道[2]，一个是翠靥金毛俏鼻凹。无人坐。一个是玉堂学士，一个是金斗名娃。\n〔四〕又有个员外村，有个商贾沙，一弄儿黑漆筋红油靶。一个向丽春园大碗里空了酒，一个扬子江江船中就与茶。精神儿大，著敲棍也门背后合伏地巴背，中毒拳也教铛里仰卧地寻叉。\n〔三〕而今汝阳斋掩绿苔，豫章城噪晚鸦，金山寺草长满题诗塔。唯有长天倒影随流水，孤鹜高飞送落霞。成潇洒，但见云间汀树，不闻江上琵琶。\n〔二〕静悄悄的谁念他？冷清清的谁问他？尚有人见鞍思马。张五牛创制似选石中玉，商正叔重编如添锦上花。碎把那珠玑撒，四头儿热闹，枝节儿熟滑。\n〔一〕俺学唱咱，学说咱，谁敢和前辈争高下。赵真真先占了头名榜，杨玉娥权充了第二家。替佛传法，锣敲月面，板撒红牙。\n〔尾〕须不教一句儿讹，半字儿差。唱一本多愁多绪多情话，教你听一遍风流浪子煞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2887, "title": "〔中吕〕普天乐", "author": "张鸣善", "body": "洛阳花，梁园月。好花须买，皓月须赊。花倚栏干看烂熳开，月曾把酒问团圆夜。月有盈亏花有开谢，想人生最苦离别。花谢了三春[1]近也，月缺了中秋到也，人去了何日来也？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2888, "title": "〔中吕〕普天乐", "author": "张鸣善", "body": "海棠娇，梨花嫩，春妆成美脸，玉捻就精神。柳眉颦翡翠弯，香脸腻胭脂晕，款步香尘双鸳印，立东风一朵巫云。奄的转身，吸的便哂，森的销魂。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2889, "title": "〔中吕〕普天乐", "author": "张鸣善", "body": "雨儿飘，风儿扬。风吹回好梦，雨滴损柔肠。风萧萧梧叶中，雨点点芭蕉上。风雨相留添悲怆，雨和风卷起凄凉。风雨儿怎当？雨风儿定当，风雨儿难当！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2890, "title": "〔中吕〕普天乐", "author": "张鸣善", "body": "讲诗书，习功课。爷娘行[2]孝顺，兄弟行谦和。为臣要尽忠，与朋友休言过[3]。养性终朝端然坐，免教人笑俺风魔。先生道“学生琢磨”，学生道“先生絮聒”，馆东道“不识字由他”。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2891, "title": "〔双调〕水仙子", "author": "张鸣善", "body": "铺眉苫眼早三公，裸袖揎拳享万钟，胡言乱语成时用。大纲来都是烘。说英雄谁是英雄？五眼鸡岐山鸣凤，两头蛇南阳卧龙，三脚猫渭水飞熊。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2892, "title": "〔双调〕落梅风", "author": "张鸣善", "body": "漫天坠，扑地飞，白占许多田地。冻杀吴民都是你！难道是国家祥瑞？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2893, "title": "〔双调〕水仙子", "author": "杨朝英", "body": "雪晴天地一冰壶，竟往西湖探老逋，骑驴踏雪溪桥路。笑王维作画图，拣梅花多处提壶。对酒看花笑，无钱当剑沽，醉倒在西湖！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2894, "title": "〔双调〕水仙子", "author": "杨朝英", "body": "杏花村里旧生涯，瘦竹疏梅处士家，深耕浅种收成罢。酒新，鱼旋打，有鸡豚竹笋藤花。客到家常饭，僧来谷雨茶，闲时节自炼丹砂。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2895, "title": "〔中吕〕红绣鞋", "author": "宋方壶", "body": "短命的偏逢薄倖，老成的偏遇真成，无情的休想遇多情。懵懂的怜瞌睡，鹘伶的惜惺惺，若要轻别人还自轻。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2896, "title": "〔中吕〕红绣鞋", "author": "宋方壶", "body": "雨潇潇一帘风劲，昏惨惨半点灯明，地炉[1]无火拨残星。薄设设衾剩铁，孤另另枕如冰，我却是怎支吾[2]今夜冷。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2897, "title": "〔中吕〕山坡羊", "author": "宋方壶", "body": "青山相待，白云相爱，梦不到紫罗袍共黄金带。一茅斋，野花开，管甚谁家兴废谁成败，陋巷箪瓢亦乐哉！贫，气不改；达，志不改。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2898, "title": "〔双调〕清江引", "author": "宋方壶", "body": "剔秃一轮天外月，拜了低低说：是必常团圆，休着些儿缺，愿天下有情底都似你者。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2899, "title": "〔双调〕水仙子", "author": "宋方壶", "body": "一天蟾影映婆娑，万古谁将此镜磨？年年到今宵不缺些儿个。广寒宫好快活，碧天遥难问姮娥。我独对清光坐，闲将白雪歌，月儿你团圆我却如何！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2900, "title": "〔双调〕水仙子", "author": "宋方壶", "body": "时人个个望高官，位至三公[3]不若闲。老妻顽子无忧患，一家儿得自安。破柴门对绿水青山。沽村酒三杯醉，理瑶琴[4]数曲弹，都回避了胆战心寒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2901, "title": "〔南吕〕一枝花", "author": "宋方壶", "body": "妖娆体态轻，薄劣腰肢细。窝巢居柳陌，活计傍花溪。相趁相随，聚朋党成群队。逞轻狂撒蒂，爱黄昏月下星前，怕青宵风吹日炙。\n〔梁州〕每日穿楼台兰堂画阁，透帘栊绣幕罗帏。帐嗡嗡乔声气，不禁拍抚，怎受禁持？厮鸣厮咂，相抱相偎；损伤人玉体冰肌，人娇并枕同席。瘦伶仃腿似蛛丝，薄支辣翅如苇煤，快棱憎嘴似钢锥。透人，骨髓，满口儿认下胭脂记。想着痒那些滋味，有你后甚是何曾到眼底？到强如蝶使蜂媒。\n〔尾〕闲时节离不了花香柳影清阴里睡，闷时节则就日暖风和叶底下依。不想瘦躯老人根前逞精细，且休说香罗袖里，桃花扇底——则怕露冷天寒恁时节悔。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2902, "title": "〔越调〕斗鹌鹑", "author": "宋方壶", "body": "落日遥岑[5]，淡烟远浦[6]。萧寺[7]疏钟，戍楼暮鼓。一叶扁舟，数声去橹，那惨戚，那凄楚，恰待欢娱，顿成间阻。\n〔紫花儿〕瘦岩岩香消玉减，冷清清夜永更长，孤另另枕剩衾余。羞花闭月，落雁沉鱼。踌躇，从今后谁寄萧娘一纸书？无情无绪，水淹蓝桥，梦断华胥。\n〔调笑令〕肺腑，恨怎舒，三叠阳关愁万缕。幽期密约欢爱处，动离愁暮云无数。今夜月明何处宿？依依古岸黄芦。\n〔秃厮儿〕欢笑地不堪举目，回首处景物萧疏，星前月下谁共语。漫嗟吁，自踌躇，何如？\n〔圣药王〕[8]别太速，情最苦。松金减玉瘦了身躯。鬼病添，神思虚，心如刀剜泪如珠。意儿里懒上香车。\n〔尾〕眼睁睁怎忍分飞去，痛杀我也吹箫伴侣。不付能[9]恰住了送行客一帆风，又添起助离愁半江雨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2903, "title": "〔双调〕折桂令", "author": "王举之", "body": "问蛤蜊风致何如？秀出乾坤，功在诗书。云叶轻盈，灵华纤腻，人物清癯。采燕赵天然丽语，拾姚卢肘后明珠，绝妙功夫。家住西湖，名播东都。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2904, "title": "〔双调〕河西六娘子", "author": "柴野愚", "body": "骏马双翻碧玉蹄，青丝鞚[1]、黄金羁[2]，入秦楼将在垂杨下系。花压帽檐低，风透绣罗衣，袅吟鞭、月下归。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2905, "title": "〔中吕〕醉高歌过红绣鞋", "author": "贾固", "body": "乐心儿比目连枝，肯意儿新婚燕尔。画船开抛闪的人独自，遥望关西店儿。黄河水流不尽心事，中条山隔不断相思。当记得夜深沉、人静悄、自来时。来时节三两句话，去时节一篇诗，记在人心窝儿里直到死。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2906, "title": "〔正宫〕塞鸿秋", "author": "周德清", "body": "长江万里白如练，淮山数点青如淀；江帆几片疾如箭，山泉千尺飞如电。晚云都变露，新月初学扇，塞鸿一字来如线。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2907, "title": "〔中吕〕朝天子", "author": "周德清", "body": "月光，桂香，趁着风飘荡。砧声摧动一天霜，过雁声嘹亮。叫起离情，敲残客况，梦家山身异乡。夜凉，枕凉，不许离人强。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2908, "title": "〔中吕〕满庭芳", "author": "周德清", "body": "披文握武，建中兴庙宇，载青史图书。功成却被权臣妒，正落奸谋。闪杀人望旌节中原士夫，误杀人弃丘陵南渡銮舆。钱塘路，愁风怨雨，长是洒西湖。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2909, "title": "〔中吕〕阳春曲", "author": "周德清", "body": "半池暖绿鸳鸯睡，满径残红燕子飞，一林老翠杜鹃啼。春事已，何日是归期？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2910, "title": "〔双调〕蟾宫曲", "author": "周德清", "body": "宰金头黑脚天鹅，客有钟期，座有韩娥。吟既能吟，听还能听，歌也能歌。和白雪新来较可，放行云飞去如何？醉睹银河，灿灿蟾孤，点点星多。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2911, "title": "〔双调〕折桂令", "author": "周德清", "body": "倚蓬窗无语嗟呀，七件儿全无，做甚么人家？柴似灵芝，油如甘露，米若丹砂。酱瓮儿才罄撒，盐瓶儿又告消乏。茶也无多，醋也无多，七件事尚且艰难，怎生教我折柳攀花！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2912, "title": "〔南吕〕一枝花", "author": "班惟志", "body": "透疏帘风摇杨柳阴，泻长空月转梧桐影，冷雕盘香销金兽[1]火，咽铜龙漏滴玉壶[2]冰。何处银筝？声嘹呖云霄应，逐轻风过短棂。耳才闻天上仙韶，身疑在人间胜境。\n〔梁州〕恰便似溅石窟寒泉乱涌，集瑶台鸾凤和鸣，走金盘乱撒骊珠迸。嘶风骏偃，潜沼鱼惊，天边雁落，树梢云停。早则是字样分明，更那堪音律关情？凄凉比汉昭君[3]塞上琵琶，清韵如王子乔[4]风前玉笙，悠扬似张君瑞[5]月下琴声。再听，愈惊，叮咛一曲《阳关令》[6]。感离愁，动别兴。万事萦怀百样增，一洗尘清。\n〔尾〕他那里轻笼纤指冰弦应，俺这里谩写花笺锦字迎，越感起文园[7]少年病。是谁家玉卿？只恁般可憎！唤的人一枕蝴蝶梦儿醒。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2913, "title": "昊天塔孟良盗骨", "author": "朱凯", "body": "〔双调·新水令〕归来馀醉未曾醒，但触着我这秃爷爷没些干净。那哭的莫不是山中老树怪，潭底毒龙精，敢便待显圣通灵？只俺个道高的鬼神敬。\n〔驻马听〕那里每噎噎哽哽，搅乱俺这无是无非窗下僧。越哭的孤孤另另，莫不是着枪着箭的败残兵？我靠三门倚定壁儿听，耸双肩手抵着牙儿定。似这等沸腾腾，可甚么绿阴满地禅房静。\n〔步步娇〕只你个负屈含冤的也合通名姓，莫不是远探你那爹娘的病？莫不是你犯下些违条罪不轻？莫不是打担推车撞着贼兵？我连问道你两三声，怎没半句儿将咱来答应。\n〔雁儿落〕俺这里便骂了人也谁敢应；俺这里便打了人也无争竞；俺这里便劫了人也没罪名；俺这里便杀了人也不偿命。\n〔水仙子〕现如今火烧人肉喷鼻腥，俺几曾道为惜飞蛾纱罩灯。若不杀生啊有什么轮回证，这便是咱念阿弥超度的经。对客官细说分明：我也曾杀的番军怕，几曾有个信士[1]请？直到中年才落发为僧。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2914, "title": "〔正宫〕醉太平", "author": "钟嗣成", "body": "绕前街后街，进大院深宅。怕有那慈悲好善小裙钗，请乞儿一顿饱斋，与乞儿绣副合欢带，与乞儿换副新铺盖，将乞儿携手上阳台[1]。救贫咱波奶奶！\n俺是悲田院[2]下司，俺是刘九儿[3]宗枝。郑元和当日拜为师，传留下莲花落[4]稿子。搠竹杖绕遍莺花市[5]，提灰笔写遍鸳鸯字，打爻槌[6]唱会鹧鸪词。穷不了俺风流敬思。\n风流贫最好，村沙富难交。拾灰泥补砌了旧砖窑，开一个教乞儿市学。裹一顶半新不旧乌纱帽，穿一领半长不短黄麻罩，系一条半联不断皂环绦，做一个穷风月训导[7]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2915, "title": "〔双调〕凌波仙", "author": "钟嗣成", "body": "五言常写和陶诗，一曲能传冠柳词，半生书法欺颜字。占风流独我师，是梨园南北分司。当时事，仔细思，细思量不是当时。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2916, "title": "〔双调〕凌波仙", "author": "钟嗣成", "body": "平生湖海少知音，几曲宫商大用心，百年光景还争甚？空赢得雪鬓侵，跨仙禽路绕云深。欲挂坟前剑[8]，重听膝上琴[9]，漫携琴载酒相寻。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2917, "title": "〔南吕〕一枝花", "author": "钟嗣成", "body": "生居天地间，禀受阴阳气。既为男子身，须入世俗机。所事堪宜，件件可咱家意。子[10]为评跋上惹是非，折莫[11]旧友新知，才见了着人笑起。\n〔梁州〕子为外貌儿不中抬举，因此内才儿不得便宜。半生未得文章力，空自胸藏锦绣，口唾珠玑。争奈灰容土貌，缺齿重颏，更兼着细眼单眉，人中短髭鬓稀稀。那里取陈平般冠玉精神，何晏般风流面皮？那里取潘安般俊俏容仪？自知，就里，清晨倦把青鸾[12]对，恨杀爷娘不争气。有一日黄榜[13]招收丑陋的，准拟夺魁。\n〔隔尾〕有时节软乌纱抓札起钻天髻，乾皂靴出落着簌地衣，向晚乘闲后门立。猛可地笑起，似一个甚的？恰便似现世钟馗唬不杀鬼。\n〔牧羊关〕冠不正相知罪，貌不扬怨恨谁，那里也尊瞻视貌重招威！枕上寻思，心头怒起，空长三十岁，暗想九千回，恰便似木上节难镑刨[14]，胎中疾没药医。\n〔贺新郎〕世间能走的不能飞，饶你千件千宜，百伶百俐。闲中解尽其中意，暗地里自恁解释。倦闲游出塞临池，临池鱼恐坠，出塞雁惊飞，入园林宿鸟应回避。生前难入画，死后不留题！\n〔隔尾〕写神的[15]要得丹青意，子怕你巧笔难传造化机。不打草[16]两般儿可同类：法刀鞘依着格式，妆鬼的添上嘴鼻，眼巧何须样子比。\n〔哭皇天〕饶你有拿雾艺冲天计，诛龙局段打凤机，近来论世态，世态有高低。有钱的高贵，无钱的低微。那里问风流子弟？折末[17]颜如灌口[18]，貌赛神仙，洞宾出世，宋玉重生，设答了镘的[19]，梦撒了寮丁。他睬你也不见得，枉自论黄数黑，谈是说非。\n〔乌夜啼〕一个斩蛟龙秀士[20]为高第，升堂室今古谁及；一个射金钱武士为夫婿，韬略无敌，武艺深知，丑和好自有是和非，文和武便是傍州例[21]。有鉴识，无嗔讳，自花白[22]寸心不昧，若说谎上帝应知。\n〔收尾〕常记得半窗夜雨灯初昧，一枕秋风梦未回。见一人，请相会，道咱家，必高贵。既通儒，又通吏，既通疏，更精细。一时间，失商议，既成形，悔不及。子教你，请俸给，子孙多，夫妇宜，货财充，仓廪实，福禄增，寿算齐，我特来，告你知。暂相别，恕请罪。叹息了几声，懊悔了一会。觉来时记得，记得他是谁？原来是不做美当年的捏胎鬼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2918, "title": "〔双调〕折桂令", "author": "周浩", "body": "想贞元朝士无多，满目江山，日月如梭。上苑繁华，西湖富贵，总付高歌。麒麟冢衣冠坎坷，凤凰台人物蹉跎。生待如何，死待如何？纸上清名，万古难磨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2919, "title": "〔正宫〕醉太平", "author": "汪元亨", "body": "憎苍蝇竞血，恶黑蚁争穴，急流中勇退是豪杰，不因循苟且。叹乌衣一旦非王谢，怕青山两岸分吴越，厌红尘万丈混龙蛇，老先生去也。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2920, "title": "〔正宫〕醉太平", "author": "汪元亨", "body": "莫争高竞低，休说是谈非，此身不肯羡轻肥，且埋名隐迹。叹世人用尽千般计，笑时人倚尽十分势，看高人着尽一枰棋。老先生见机。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2921, "title": "〔中吕〕朝天子", "author": "汪元亨", "body": "长歌咏楚词，细赓和杜诗，闲临写羲之字。乱云堆里结茅茨，无意居朝市。珠履三千，金钗十二，朝承恩暮赐死。采商山紫芝，理桐江钓丝，毕罢了功名事。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2922, "title": "〔中吕〕朝天子", "author": "汪元亨", "body": "荣华梦一场，功名纸半张，是非海波千丈。马蹄踏碎禁街霜，听几度头鸡唱。尘土衣冠，江湖心量，出皇家麟凤网。慕夷齐首阳，叹韩彭未央，早纳纸风魔状。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2923, "title": "〔中吕〕朝天子", "author": "汪元亨", "body": "身不出敝庐，脚不登仕途，名不上功劳簿。窗前流水枕边书，深参透其中趣。大泽诛蛇，中原逐鹿，任江山谁作主。孟浩然跨驴，严子陵钓鱼，快活煞闲人物。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2924, "title": "〔中吕〕朝天子", "author": "汪元亨", "body": "风俗变甚讹，人情较太薄，世事处真微末。收拾琴剑入山阿，眼不见高轩过。性本疏懒，才非王佐，守一丘并一壑。算人生几何，惊头颅半皤，怕干惹萧墙祸。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2925, "title": "〔双调〕沉醉东风", "author": "汪元亨", "body": "远城市人稠物穰，近村居水色山光。熏陶成野叟情，铲削去时官样，演习会牧歌樵唱。老瓦盆边醉几场，不撞入天罗地网。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2926, "title": "〔双调〕沉醉东风", "author": "汪元亨", "body": "二十载江湖落魄，三千程途路奔波。虎狼丛辨是非，风波海分人我。到如今做哑装矬，着意来寻安乐窝，摆脱了名韁利锁。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2927, "title": "〔双调〕折桂令", "author": "汪元亨", "body": "叹天之未丧斯文，剑气丹光，酒魄诗魂。名利秋霜，荣华朝露，富贵浮云。看青山、玩绿水，醉田家瓦盆；采黄花、摘红叶，戏庄上儿孙。随分耕耘，过遣晨昏；竹几藤床，草舍柴门。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2928, "title": "〔双调〕夜行船", "author": "杨维桢", "body": "霸业艰危。叹吴王端为、苎罗仙子，倾城处，妆出捧心娇媚。奢侈，玉液金茎，宝凤雕龙，银鱼丝鲙。游戏，沉溺在翠红乡，忘却卧薪滋味。\n〔前腔〕乘机，勾践雄徒，聚干戈要雪、会稽羞耻。怀奸计、越赂私通伯嚭。谁知，忠谏不听，剑赐属镂，灵胥空死。狼狈，不想道请行成，北面称臣不许。\n〔斗蛤〕堪悲，身国俱亡，把烟花山水，等闲无主。叹高台百尺，顿遭烈炬。休觑，珠翠总劫灰，繁华只废基。恼人意，尀耐范蠡扁舟，一片太湖烟水。\n〔前腔〕听启，檇李亭荒，更夫椒树老，浣花池废。问铜沟[1]明月，美人何处？春去，杨柳水殿攲，芙蓉池馆摧。动情的，只见绿树黄鹂，寂寂怨谁无语。\n〔锦衣香〕馆娃宫，荆榛蔽；响屧廊，莓苔翳。可惜剩水残山，断崖高寺，百花深处一僧归。空遗旧迹，走狗斗鸡。想当年僭祭，望郊台凄凉云树，香水鸳鸯去。酒城倾坠，茫茫练渎，无边秋水。\n〔浆水令〕采莲泾红芳尽死，越来溪吴歌惨凄，宫中鹿走草萋萋。黍离故墟，过客伤悲。离宫废，谁避暑？琼姬墓冷苍烟蔽。空原滴，空原滴、梧桐秋雨。台城上，台城上、夜乌啼。\n〔尾声〕越王百计吞吴地，归去层台高起，只今亦是鹧鸪飞处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2929, "title": "〔黄钟〕人月圆", "author": "倪瓒", "body": "伤心莫问前朝事，重上越王台。鹧鸪啼处，东风草绿，残照花开。怅然孤啸，青山故国，乔木苍苔。当时明月，依依素影，何处飞来？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2930, "title": "〔黄钟〕人月圆", "author": "倪瓒", "body": "惊回一枕当年梦，渔唱起南津。画屏云嶂，池塘春草，无限销魂。旧家应在，梧桐覆井，杨柳藏门。闲身空老，孤篷听雨，灯火江村。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2931, "title": "〔越调〕小桃红", "author": "倪瓒", "body": "一江秋水澹寒烟，水影明如练。眼底离愁数行雁，雪晴天，绿苹红蓼参差见。吴歌荡桨，一声哀怨，惊起白鸥眠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2932, "title": "〔越调〕凭阑人", "author": "倪瓒", "body": "客有吴郎吹洞箫，明月沉江春雾晓。湘灵不可招，水云中环珮摇。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2933, "title": "〔双调〕折桂令", "author": "倪瓒", "body": "草茫茫秦汉陵阙，世代兴亡，却便似月影圆缺。山人室堆案图书，当窗松桂，满地薇蕨。侯门深何须刺谒，白云间自可怡悦。到如今世事难说，天地间不见一个英雄，不见一个豪杰。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2934, "title": "〔双调〕水仙子", "author": "倪瓒", "body": "东风花外小红楼，南浦山横眉黛愁。春寒不管花枝瘦，无情水自流。檐间燕语娇柔，惊回幽梦，难寻旧游，落日帘钩。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2935, "title": "〔双调〕水仙子", "author": "倪瓒", "body": "吹箫声断更登楼，独自凭阑独自愁。斜阳绿惨红消瘦，长江天际流。百般娇千种温柔，金缕曲新声低按。碧油车名园共游，绛绡裙罗袜如钩。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2936, "title": "〔双调〕殿前欢", "author": "倪瓒", "body": "揾啼红，杏花消息雨声中。十年一觉扬州梦，春水如空，雁波寒写去踪。离愁重，南浦行云送，冰弦玉柱，弹怨东风。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2937, "title": "〔双调〕水仙子", "author": "夏庭芝", "body": "丽春园先使棘针屯，烟月牌荒将烈焰焚。实心儿辞却莺花阵，谁想香车不甚稳，柳花亭进退无门。夫人是夫人分，奴婢是奴婢身，怎做夫人！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2938, "title": "〔中吕〕朝天子", "author": "刘庭信", "body": "夜深深静悄，明朗朗月高，小书院无人到。书生今夜且休睡着，有句话低低道：半扇儿窗棂，不须轻敲，我来时将花树儿摇。你可便记着，便休要忘了，影儿动咱来到。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2939, "title": "〔双调〕折桂令", "author": "刘庭信", "body": "想人生最苦离别，三个字细细分开，凄凄凉凉无了无歇。别字儿半响痴呆，离字儿一时拆散，苦字儿两下里堆叠。他那里鞍儿马儿身子儿劣怯，我这里眉儿眼儿脸脑儿乜斜。侧着头叫一声“行者”，阁着泪说一句“听者”，得官时先报期程，丢丢抹抹远远的迎接。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2940, "title": "〔双调〕折桂令", "author": "刘庭信", "body": "想人生最苦离别，唱到阳关，休唱三叠。急煎煎抹泪柔眵，意迟迟揉腮耳，呆答孩闭口藏舌。“情儿分儿你心里记者，病儿痛儿我身上添些，家儿活儿既是抛撇，书儿信儿是必休绝，花儿草儿打听的风声，车儿马儿我亲自来也！”", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2941, "title": "〔双调〕水仙子", "author": "刘庭信", "body": "恨重叠，重叠恨，恨绵绵，恨满晚妆楼。愁积聚，积聚愁，愁切切，愁斟碧玉瓯。懒梳妆，梳妆懒，懒设设，懒爇黄金兽。泪珠弹，弹珠泪，泪汪汪，汪汪不住流。病身躯，身躯病，病恹恹，病在我心头。花见我，我见花，花应憔瘦。月对咱，咱对月，月更害羞。与天说，说与天，天也还愁。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2942, "title": "〔双调〕雁儿落过得胜令", "author": "刘庭信", "body": "懒栽潘岳花，学种樊迟稼。心闲梦寝安，志满忧愁大。无福享荣华，有分受贫乏。燕度春秋社，蜂喧早晚衙。茶瓜，林下渔樵话。桑麻，山中宰相家。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2943, "title": "〔南吕〕一枝花", "author": "刘庭信", "body": "丝丝杨柳风，点点梨花雨。雨随花瓣落，风趁柳条疏。春事成虚，无奈春归去。春归何太速？试问东君：谁肯与莺花做主？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2944, "title": "〔仙吕〕太常引", "author": "刘燕歌", "body": "故人别我出阳关，无计锁雕鞍。今古别离难，兀谁画蛾眉远山。一尊别酒，一声杜宇，寂寞又春残。明月小楼间，第一夜相思泪弹。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2945, "title": "〔仙吕〕后庭花", "author": "邵亨贞", "body": "铜壶更漏残，红妆春梦阑，江上花无语，天涯人未还。倚楼闲，月明千里，隔江何处山。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2946, "title": "〔正宫〕小梁州", "author": "汤式", "body": "秋风江上棹孤舟，烟水悠悠。伤心无句赋登楼，山容瘦，老树替人愁。〔幺〕樽前醉把茱萸嗅，问相知几个白头？乐可酬，人非旧，黄花时候，难比旧风流。\n秋风江上棹孤航，烟水茫茫。白云西去雁南翔，推篷望，清思满沧浪。〔幺〕东篱载酒陶元亮，等闲间过了重阳。自感伤，何情况，黄花惆怅，空作去年香。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2947, "title": "〔中吕〕满庭芳", "author": "汤式", "body": "残花剩柳，摧垣废屋，新冢荒丘。海门天堑还依旧，滚滚东流。铁瓮城横刺着虎口，金山寺高镇着鳌头。斜阳候，吟登舵楼，灯火望扬州。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2948, "title": "〔中吕〕满庭芳", "author": "汤式", "body": "钱唐故址，东吴霸业，南渡京师。其间四百八十寺，不似当时。山空蒙湖潋滟随处写坡仙旧诗？水清浅月黄昏何人吊逋老荒祠？伤情思，西湖若此，何似比西施？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2949, "title": "〔中吕〕醉高歌带红绣鞋", "author": "汤式", "body": "落花天红雨纷纷，芳草地苍烟衮衮。杜鹃啼血清明近，单注着离人断魂。深巷静，凄凉成阵；小楼空，寂寞为邻。吟对青灯几黄昏？无家常在客，有酒不论文，更想甚“江东日暮云”！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2950, "title": "〔中吕〕山坡羊", "author": "汤式", "body": "羁怀萦挂，人情浇诈，相逢休说伤时话。路波蹅[1]，事交杂，秋光何处堪消暇！昨夜梦魂归到家。田，不种瓜；园，不灌花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2951, "title": "〔双调〕湘妃引", "author": "汤式", "body": "木犀风淅淅喷雕棂，兰麝香氤氲绕画屏，梧桐月淡淡悬青镜。漏初残人乍醒，恨多才何处飘零。填不满凄凉幽窖，捱不出凄惶梦境，打不开磊块愁城。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2952, "title": "〔双调〕天香引", "author": "汤式", "body": "问西湖昔日如何？朝也笙歌，暮也笙歌，问西湖今日如何？朝也干戈，暮也干戈。昔日也，二十里沽酒楼，春风绮罗；今日个，两三个打鱼船，落日沧波。光景蹉跎，人物消磨。昔日西湖，今日南柯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2953, "title": "〔双调〕天香引", "author": "汤式", "body": "羡江都自古神州，天上人间，楚尾吴头。十万家画栋朱帘，百数曲红桥绿沼，三千里锦缆龙舟。柳招摇，花掩映，春风紫骝；玉玎珰，珠络索，夜月香兜。歌舞都休，光景难留。富贵随落日西沉，繁华逐逝水东流。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2954, "title": "〔双调〕蟾宫曲", "author": "汤式", "body": "冷清清人在西厢，叫一声张郎，骂一声张郎。乱纷纷花落东墙，问一会红娘，絮一会红娘。枕儿余，衾儿剩，温一半绣床，间一半绣床。月儿斜，风儿细，开一扇纱窗，掩一扇纱窗。荡悠悠梦绕高唐，萦一寸柔肠，断一寸柔肠。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2955, "title": "〔双调〕庆东原", "author": "汤式", "body": "故园一千里，孤帆数日程，倚篷窗自叹漂泊命。城头鼓声，江心浪声，山顶钟声。一夜梦难成，三处愁相并。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2956, "title": "〔南吕〕一枝花", "author": "汤式", "body": "锦囊宽闲凤琴，宝匣冷藏龙剑，篆香消闲翠鼎，书卷广乱牙签。郁闷恹恹。《青琐论》无心念，紫霜毫不待拈。尪羸[2]似老文园病渴的相如，寂寞如居海岛伤怀的子瞻。\n〔梁州〕看白云闲出岫[3]频移净几，爱青山正当窗不卷疏帘。客房儿冷落似邯郸店，心滴碎铜壶青漏[4]，耳愁闻铁马虚檐[5]。肠欲断阶前夜雨，梦初回屋角秋蟾。一片心远功名无甚沾粘，两只脚信行藏有甚拘钤。经了些摧舟楫走蛟鼍鲸窟波翻[6]，行了些坏车轮被虎豹[7]羊肠路险，过了些连云梯绝猿猴鸟道峰尖[8]。静中，自检：事无成志不遂人情欠，休施逞且妆俭。但得个小小生涯足养廉，甘分鳞潜。\n〔尾声〕能文章会谈论才高反被时人厌，守清贫乐清闲运拙频遭俗子嫌。有一日际会风云得凭验。那时节威仪可瞻，经纶得兼，正笏垂绅远佞谄。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2957, "title": "西游记", "author": "杨讷", "body": "〔乔牌儿〕一个个手执白木植，身穿着紫搭背，白石头黄铜片去腰间系，一对脚似踏在黑瓮里。\n〔新水令〕官人每腰屈共头低，吃得醉醺醺脑门着地。咿咿呜呜吹竹管，扑扑通通打牛皮。见几个无知，叫一会闹一会。\n〔雁儿落〕见一个粉搽白面皮，红着油髻。笑一声打一棒椎，跳一跳高似田地。（张云）这是做院本的。（姑云）更好笑哩。（唱）\n〔川拨棹〕好着我笑微微，一个汉木雕成两个腿。见几个回回，舞着面旌旗，阿剌剌口里不知道甚的妆着鬼。人多我看不仔细。\n〔七弟兄〕我钻在这壁、那壁，没安我这死身已。滚将一个碡在根底，脚踏着才得见真实。百般打扮千般戏。\n〔梅花酒〕那的他唤做甚傀儡，黑墨线儿提着红白粉儿，妆着人样的东西。飕飕胡哨起，冬冬地鼓声催，一个摩着大旗。他坐着吃堂食，我立着看筵席。两只腿板僵直，肚皮里似春雷。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2958, "title": "西游记", "author": "杨讷", "body": "〔南吕·玉交枝〕贪杯无厌，每日价泛流霞[1]潋滟；子云嘲谑防微渐，托鸱夷[2]彩笔拈。季鹰好饮豪兴添，忆莼鲈只为葡萄酽，倒玉山恁般瑕玷。又不是周晏相沾，糟腌着葛仙翁，曲埋那张孝廉。恣狂情，谁与砭。英雄尽你夸，富贵饶他占。则这黄垆畔有祸殃，玉缸边多危险。酒呵播名声天下嫌。\n〔幺〕待谁来挂念，早则是桃腮杏脸。巫山洛浦皆虚艳，把西子比无盐。那里有佳人将四德兼，为龙漦衾枕[3]是干戈渐，锦片似江山着敌敛。可曾悔恋了秾纤，碎鸾钗，间宝奁。这风情，怎强谵。眼见坠楼人，犹把临春占。笑男儿自着鞭，叹青娥藏刀剑。色呵播声名天下嫌。\n〔幺〕富豪的偏俭，奢华的无过是聚敛。王戎郭况心无厌，拥金穴握牙签[4]。可知道分金鲍叔廉，煞强如牢把铜山占，晋和峤也多褒贬。恰便是朱方聚歼，有齿的焚身，多财的要谦。斗量珠，树系缣，刑伤为美姝，杀伐因求剑。空有那万贯钱，到底来亡沟堑。财呵播名声天下嫌。\n〔幺〕英雄气焰，貔虎般不能收敛；夷门燕市皆为僭，空僝愁枉威严。探丸厉刃掀紫髯，笑谈落得填坑堑，尽淋漓一腔丹慊。惹傍人血泪横沾，冷觑王侯，暖守兵钤[5]。发冲冠，雄猛添，惊皇博浪椎，寂寞乌江剑。恁忘了泡影与河山，算相争都无餍。气呵播声名天下嫌。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2959, "title": "西游记", "author": "杨讷", "body": "〔正宫·端正好〕我在巽宫里居，离宫里过，我直滚沙石撼动娑婆。天长地久谁煞得我，把世界都参破。\n〔滚绣球〕孟婆是我教成，风神是我正果。我和骊山老母是姊妹两个，我通风他通火。角木蛟井木犴是叔伯亲，斗木獬奎木狼是舅姑哥。当日宴蟠桃惹起这场灾祸，西王母道他金能欺风木催槎[6]。当日个酒逢知己千钟少，话不投机一句多。死也待如何。\n〔倘秀才〕明月照疏林花果，寒露滴空山薜萝，四面青山紧围裹。松梢闻鹤唳，洞口看猿过，与凡尘间阔。\n〔滚绣球〕这扇子六丁神巧铸成，五道神细打磨。阎浮间并无二个。上秤称一千斤犹有余多。管二十四气风，吹灭八十一洞火。火焰山神见咱也胆破。恼着我呵登时间便起干戈。我且着扇搧翻地狱门前树，卷起天河水上波。我是第一洞妖魔。\n〔叨叨令〕我这片杀人心胆天来大，救人命志少些儿个。你道是火焰山师父实难过，则这个铁峰的魔女能行祸。休得要闲中寻闹也波哥，休得要闲中寻闹也波哥。则你那秃髑髅敢禁不得钢刀剁。\n〔白鹤子〕你道是花果山是祖居，铁峰是我的行窝。在彼处难比强，来此处索伏些懦。\n〔中吕·快活三〕恼的我无明火怎收撮，泼毛团你敢张罗。卖弄他铜筋铁骨自开合，我一扇子敢着你翻筋斗三千个。\n〔鲍老儿〕他大叫高呼勒着我，更怕我杨柳腰肢袅娜。耀武扬威越逞过，更怕我桃脸风吹得破。弯弓蹬弩，拈枪使棒，擂鼓筛锣。\n〔古鲍老〕手提着太阿，碧澄澄恰如三尺波。额攒着翠蛾，恶狠狠怒如千丈火。狂旗磨，战鼓敲，妖兵和。你便吃了灵丹数颗，争似我风声偏大，半合儿敢着你难捞摸。\n〔道和〕这扇子柄长面阔，锁铁贯嵌金磨，骨把揠薄。妖气罩冷风多，云端顶上观见我。铁棒来抽身便躲，戒刀着怎地存活。我着戒刀折，铁棒损，力消磨。\n〔柳青娘〕休么，从来不识这妖魔，忒轻薄也待如何。那厮有神通难摸，艺高强名扬播。偷灵丹老子怎近他，盗蟠桃玉皇难奈何。那厮上天宫将神威挫，下人间兴祸多。看着身躯大，顷刻成微末。看着东方过，顷刻向西方落。一任他铁骨铜筋火眼睛，不索交兵，敢着他随风一扇，扇了渡江河。\n〔尾〕或是堕在远冈，落在浅波，滴溜溜有似梧飘落。便是天着他有命，今生必定害风魔。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2960, "title": "马丹阳度脱刘行首", "author": "杨讷", "body": "〔锦上花〕淡饭粗衣，山中活计。落托清闲，到大幽微。采蕨寻芝，绕山转水，炼药烧丹，驱神捉鬼。\n〔幺篇〕困来那一眠，闲来那一醉。一任渔樵，说是谈非。笑杀儿曹，走南料北。空叹英雄，争高竞低。\n〔江儿水〕人生快活能有几，过一岁无一岁。将军使机谋，宰相施忠义，都在俺这老先生谈笑里。\n〔碧玉箫〕想韩侯当日，钝剑一身亏。彭越何为，烂锉肉如泥。九江王受困危，竿尖上挑首级。恁莫痴，争是张良会。归，急流中身先退。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2961, "title": "〔南吕〕四块玉", "author": "兰楚芳", "body": "我事事村，他般般丑，丑则丑村则村意相投。则为他丑心儿真，博得我村情儿厚。似这般丑眷属，村配偶，只除天上有。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2962, "title": "〔南吕〕四块玉", "author": "兰楚芳", "body": "意思儿真，心肠儿顺，只争个口角头不囫囵。怕人知，羞人说，嗔人问。不见后又嗔，得见后又忖，多敢死后肯。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2963, "title": "〔仙吕〕点绛唇", "author": "王大学士", "body": "丰稔年华，酒旗斜插，茅檐下。小桥流水人一家，一带山如画。\n〔混江龙〕桔槔闲挂，呼童汲水旋烹茶。柔桑荏苒，古柏槎牙。雾锁草桥三四横，烟笼茅舍数十家。岗盘曲，畎兜答，莺迁乔木丘冢。一个鸥鹭水面，雁落平沙。喧檐宿雀，啼树栖鸦。柴扉吠犬，鼓吹鸣蛙。侬家鹦鹉洲，不入麒麟画。百姓每讴歌鼓腹，一弄儿笑语喧哗。\n〔油葫芦〕刚见一百个儿童刁刁厥厥的耍，更那堪景物佳。一个将［尧民歌］乱唱的令儿差，一个是扑冬冬擂鼓无高下，一个支周知挣羌管吹难收煞。一个水盆里击着料瓜，一个拖床上拍着布瓦。一个一张舞得了千斤乍，一个学舞斗虾。\n〔天下乐〕一个道一阵黄风一阵沙，一个天生丑势煞，一个无店三碌轴上闲坐衙。一个将斤斗翻，一个将背抛打，一个响扑儿学咯牙。\n〔那吒令〕一个向瓜田里坐树乱扯，一个向枣树上胡乱打，一个向古墓上翻砖弄瓦。一个扯着衣衫，一个揪住棍把，一个播土扬沙。\n〔鹊踏枝〕一个眼麻花，一个手支沙，一个浅水涡里摸鳖捞虾，一个见麒麟打煞，一个舞着唱着匾担禾叉。\n〔寄生草〕一个擎着山鹧，一个架着老鸦。一个向柳阴中笑把人头画，一个向桑园里学揭龟儿卦，一个向墙匡里引的芒郎骂。一个跳灰驴大闹麦场头，一个踏竹马偃卧在葫芦架。\n〔金盏儿〕一个叫丫丫，一个笑呷呷。一个棘斜混倒上树千般耍，一个山声野调学唱搅筝琶。一个斗巨子抢了嘴问，一个竖直立的磕了门牙。一个无人处寻豆角，一个背地里咽生瓜。\n〔村里迓古〕一个放顽撒泼，一个唱歌厮骂。一个村村棒棒牛撒橛乔画，一个狗打肝腌相欠欠答答。一个弹的捹，一个舞的虾。一个唱的哑，一个水底浑如纳瓜。\n〔元和令〕一个舞乔捉蛇呆木答，一个舞尿里蛆的法刀把，一个跳百索背儿仰剌叉。一个一个儿窝的眼又瞎，一个将纸鸦儿放起盼的人眼睛花，一个递撇牛的没乱杀。\n〔上马娇〕一个村，一个又沙，一个丑嘴脸特胡沙。一个将花桑树纽捏搬调话，一个打和的差，一个不剌着簸箕拨琵琶。\n〔胜葫芦〕一个恐惊林外野人家，一个道休厮闹，一个道嗟牙。一个赛牛王香纸方烧罢。一个将磁瓯瓦钵，一个不门清光滑辣，一个没鼻子喃浑。\n〔后庭花〕一个掬蝙蝠踏破瓦，一个竖牵牛扯了尾拔。一个摸鹁鸽掀翻盖，一个打斑鸠的击碎。一个岸边打滑擦，一个头尖眼大。一个莎岗上扑马扎，一个游泥蚌蛤。一个柳堤边钓水扎，一个沙湍上烧黄鳝，一个膊项上瘿疙疸。一个唇缺丑势煞，一个磨的特剌查。一个做生活的不颗恰，一个觅虱子头上掐。一个编蒲笠特抹答，一个鞭牛叱咤。\n〔青歌儿〕一个牛斤，一个谎诈。一个光答答又无头发，一个蒙松雨里种芝麻。一个兜答，一个奸滑。一个交加，一个皱查。这一坐乔民闹交加，定害的爷娘骂。\n〔尾〕一个潜立在晚风前，一个暗约在斜阳下。一个见厮抵拽着棒打，一个恋汀洲蓼岸芦花。一个映着蒹葭，一个收拾罢钓鱼艖，一个笑指疏篱噪晚鸦，一个绿蓑斜挂，一个倒骑牛背入烟霞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2964, "title": "宋太祖龙虎风云会", "author": "罗贯中", "body": "〔南吕·一枝花〕漫漫杀气飞，滚滚征尘罩，恹恹红日惨，隐隐阵云高。军布满荒郊，我命将凭三略，行兵按六韬。右白虎左按青龙，后玄武前依朱雀。\n〔梁州第七〕护中军七层剑戟，守先锋万队枪刀，五方旗四面相围绕。朱旛皂盖，黄钺白旄；箭攒雕羽，弓挂龙弰。滴溜溜号带齐飘，威凛凛挂甲披袍，扑咚咚鼓擂春雷，雄纠纠人披绣袄。不剌剌马顿绒绦，咆哮，战讨。马和人飞上红尘道，金镫稳，玉鞭袅，催动龙驹把辔摇，转过山腰。\n〔牧羊关〕见几点寒星现，一钩新月皎，看看的兵至陈桥。教前队休行，催后军赶着，屯车仗离官道，就馆驿度今宵。疾忙教各部下关粮米，对名儿支料草。\n〔贺新郎〕诸军众将一周遭，小心的下寨安营，在意的提铃喝号。七禁令五十四斩从公道，丁宁休犯法违条。卷旌旗，停斧钺，卧鞭炼，竖枪刀。悄悄的各依队伍休喧闹，解鞍松战马，卸甲脱征袍。\n〔隔尾〕五更筹更听金鸡报，一部从休辞永夜劳。画角齐吹玉梅调。人休贪睡着，马须要喂饱。我且半倚帏屏盼天晓。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2965, "title": "宋太祖龙虎风云会", "author": "罗贯中", "body": "〔正宫·端正好〕光射水晶宫，冷透鲛绡帐，夜深沉、睡不稳龙床，离金门、私出天街上，正瑞雪空中降。\n〔滚绣球〕似纷纷蝶翅飞，如漫漫柳絮狂。剪冰花旋风儿飘荡，践琼瑶脚步儿匆忙。用白襕两袖遮，将乌纱小帽荡。猛回头把凤楼凝望，全不见碧琉璃瓦鹙鸳央。一霎儿九重宫阙如银砌，半合儿万里乾坤似玉妆，粉填满封疆。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2966, "title": "李素兰风月玉壶春", "author": "贾仲明", "body": "〔六幺序〕呀！猛见了心飘荡，魂灵儿飞在天，怎生来这搭儿遇着神仙？他那里眼送眉传，我这里腹热心煎，两下里都思惹情牵。他则管送春情不住相留恋，引的人意悬悬似热地蚰蜒。他生的身躯袅娜真堪羡，更那堪眉弯新月，步蹙金莲！\n〔后庭花〕感谢你个曲江池李亚仙，肯顾恋这贬江州白乐天。愿你个李素兰常风韵，则这个玉壶生永结缘。双通叔敢开言，着你个苏卿心愿！我虽无那走江湖大本钱，也敢陪家私住几年。\n〔柳叶儿〕也养的恁满门宅眷，也是我出言在骏马之前。哎，你个谢天香肯把耆卿恋。我借住临川县，敢买断丽春园，一任着金山寺摆满了贩茶船！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2967, "title": "吕洞宾桃柳升仙梦", "author": "贾仲明", "body": "〔越调·斗鹌鹑北〕经了些水远山遥，畅好是天宽地狭。野店生莓，山城噪鸦。崎岖长途，奔驰瘦马。昏邓邓尘似筛，扑唐唐泥又滑。绿水堤边，青山那答。\n〔紫花儿序北〕夕阳古道，客旅人稀，老树槎枒。一林红叶，三径黄花。看了那、高低禾黍，纷纷桑共麻。俺则为功名牵挂。今日个背井离乡，几时得任满还家？\n〔诉衷肠南〕你道是功名牵挂，早过了夕阳下，一带云山似图画。眼巴巴几时得到京华！过山遥路远怎去？他教我心惊胆颤怕。如今容颜瘦，倒不如受辛勤还家罢！我如今力困筋乏。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2968, "title": "刘晨阮肇误入桃源", "author": "王子一", "body": "〔中吕·粉蝶儿〕兔走乌飞，搬不尽古今兴废，急回来物换星移。成就了凤鸾交、莺燕侣，五百年夙缘仙契。不多时执手临岐，倒搅下干相思一场憔悴。\n〔醉春风〕则被这红灼灼洞中花，碧澄澄溪上水，赚将刘、阮入桃源，畅好是美，美。受用他一段繁华，端详了一班人物，别是个一重天地！\n〔迎仙客〕下坡如投地阱，蓦岭似上天梯。这的是蝴蝶梦中家万里。不甫能雨才收，没揣的风又起。似这般风雨凄凄，早难道迟日江山丽？\n〔红绣鞋〕见了这三五搭人家稀密，过了这百千重山路逶迤。那里也新郎归去马如飞，愁的是林深禽语碎，怕的是路远客行迟！呀，却原来鹧鸪啼烟树里。\n〔醉高歌〕望见那萧萧古寺投西，行过这泛泛危桥转北，早来到三家疃上熟游地，这搭儿分明记得。\n〔普天乐〕曾得个几星霜、多年岁，为甚么松杉作洞，花木成蹊！往时节将嫩苗跑土栽，今日呵见老树冲天立。见了这景物翻腾非前日，不由人几般儿心下猜疑：修补了颓垣败壁，整顿了明窗净几，改换了茅舍疏篱。\n〔石榴花〕则见这野风吹起纸钱灰，鼕鼕的挝鼓响如雷，原来是当村父老众相知，赛牛王社日，摆列着尊罍。到的这柴门前便唤咱儿名讳。他那里默无声弄盏传杯，一个个紧低头不睬佯妆醉。方信道人面逐高低。\n〔斗鹌鹑〕我今日衣锦还乡，儿呵你也合开门倒屣。我这里道姓呼名，他那里嗑牙料嘴，则道是啜之人来撞席，饕餮他酒共食。似恁般妄作胡为，敢欺侮咱浮踪浪迹。\n〔上小楼〕则见他一时半刻，使尽了千方百计。吃紧的理不服人，言不谙典，话不投机。看不的乔所为、歹见识、刁天决地。早难道气昂昂后生可畏。\n〔幺篇〕真乃是重色不重贤，度人不度己！使的这牛表、沙三、伴哥、王留，唱叫扬疾，走将来手便棰、脚便踢，将咱忤逆。这的是孩儿每孝当竭力。\n〔满庭芳〕你道我面生可疑，便待要扬威耀武，也合问姓甚名谁。那些个吐虹霓三千丈英雄气，全不管长幼尊卑。你道我上天台狼餐豹食，谁想我入桃源雨约云期。休得要夸强会，瞒神諕鬼。大古里人善得人欺！\n〔十二月〕叹急急年光似水，看纷纷世事如棋；回首时今来古往，伤心处物是人非。若不游嫦娥月窟，必定到王母瑶池。\n〔尧民歌〕呀！生折散碧桃花下凤鸾栖，端的个人生最苦是别离，倒做了伯劳飞燕各东西，早难道有情何怕隔年期！伤也波悲，登高怨落晖，添几点青衫泪。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2969, "title": "〔正宫〕叨叨令", "author": "无名氏", "body": "黄尘万古长安路，折碑三尺邙山墓。西风一叶乌江渡，夕阳十里邯郸树。老了人也么哥，老了人也么哥，英雄尽是伤心处。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2970, "title": "〔正宫〕叨叨令", "author": "无名氏", "body": "溪边小径舟横渡，门前流水清如玉。青山隔断红尘路，白云满地无寻处。说与你寻不得也么哥[1]，寻不得也么哥，却原来侬家鹦鹉洲边住。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2971, "title": "〔正宫〕叨叨令", "author": "无名氏", "body": "不思量尤在心头记，越思量越恁地[2]添憔悴。香罗帕揾不住腮边泪，几时节笑吟吟成了鸳鸯配。兀的不盼杀人也么哥，兀的不盼杀人也么哥，咱两个武陵溪畔曾相识。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2972, "title": "〔正宫〕塞鸿秋", "author": "无名氏", "body": "爱他时似爱初生月，喜他时似喜看梅梢月，想他时道几首西江月，盼他时似盼辰钩月。当初意儿别，今日相抛撇，要相逢似水底捞明月。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2973, "title": "〔正宫〕塞鸿秋", "author": "无名氏", "body": "东边路西边路南边路，五里铺七里铺十里铺；行一步盼一步懒一步，霎时间天也暮日也暮云也暮。斜阳满地铺，回首生烟雾。兀的不山无数水无数情无数！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2974, "title": "〔正宫〕塞鸿秋", "author": "无名氏", "body": "朝烧炼暮烧炼朝暮学烧炼，这里串那里串到处都串遍。东家骗西家骗南北都诓遍，惹的妻埋怨子埋怨父母都埋怨。我问你金丹何日成？铅汞何日见？只落的披一片挂一片拖一片！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2975, "title": "〔正宫〕醉太平", "author": "无名氏", "body": "堂堂大元，奸佞专权。开河变钞祸根源，惹红巾万千。官法滥，刑法重，黎民怨。人吃人，钞买钞，何曾见？贼做官，官做贼，混愚贤。哀哉可怜！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2976, "title": "〔正宫〕醉太平", "author": "无名氏", "body": "夺泥燕口，削铁针头，刮金佛面细搜求：无中觅有。鹌鹑嗉里寻豌豆，鹭鸶腿上劈精肉，蚊子腹内刳脂油。亏老先生下手！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2977, "title": "〔正宫〕醉太平", "author": "无名氏", "body": "寻葫芦锯瓢，拾砖瓦攒窑，暖堂院翻做乞儿学，做一个莲花落训道。戴一顶十花九裂遮尘帽，穿一领千补百衲藏形袄，系一条七断八续勒身绦。这的是子弟每下梢。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2978, "title": "〔小石调〕归来乐", "author": "无名氏", "body": "动不动说甚么玉堂金马，虚费了文园笔札。只恐怕渴死了汉相如，空落下文君再寡。哈哈，到头来都是假。总饶你事业伊周，文章董贾，少不得北邙山下。哈哈，俺归去也呀。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2979, "title": "〔仙吕〕游四门", "author": "无名氏", "body": "落红满地湿胭脂，游赏正宜时。呆才料不顾蔷薇刺，贪折海棠枝。支，抓破绣裙儿。\n海棠花下月明时，有约暗通私。不付能等得红娘至，欲审旧题诗。支，关上角门儿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2980, "title": "〔仙吕〕寄生草", "author": "无名氏", "body": "问甚么虚名利，管甚么闲是非。想着他击珊瑚、列锦帐石崇势，则不如卸罗襕、纳象简张良退，学取他枕清风、铺明月陈抟睡。看了那吴山青似越山青，不如今朝醉了明朝醉。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2981, "title": "〔仙吕〕三番玉楼人", "author": "无名氏", "body": "风摆檐间马，雨打响碧窗纱，枕剩衾寒没乱煞。不着我题名儿骂，暗想他，忒情杂，等来家，好生的歹斗咱。我将那厮脸儿上不抓，耳轮儿揪罢，我问你“昨夜宿谁家？”", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2982, "title": "〔中吕〕朝天子", "author": "无名氏", "body": "早霞，晚霞，妆点庐山画。仙翁何处炼丹砂？一缕白云下。客去斋余，人来茶罢，叹浮生指落花。楚家，汉家，做了渔樵话。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2983, "title": "〔中吕〕朝天子", "author": "无名氏", "body": "白生生面皮，软溶溶肚皮，抄手儿得人意。当初只说假虚皮，就里多葱脍。水面上鸳鸯，行行来对对，空团圆不到底。生时节手儿上捏你，熟时节口儿里嚼你，美甘甘肚儿内知滋味。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2984, "title": "〔中吕〕朝天子", "author": "无名氏", "body": "不读书有权，不识字有钱，不晓事倒有人夸荐。老天只恁忒心偏，贤和愚无分辨。折挫英雄，消磨良善，越聪明越运蹇。志高如鲁连，德过如闵骞，依本分只落的人轻贱。\n不读书最高，不识字最好，不晓事倒有人夸俏。老天不肯辨清浊，好和歹没条道。善的人欺，贫的人笑，读书人都累倒。立身则《小学》，修身则《大学》，智和能都不及鸭青钞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2985, "title": "〔中吕〕满庭芳", "author": "无名氏", "body": "枉乖柳青，贪食饿鬼，劼镘妖精。为几文口含钱做死的和人竞，动不动舍命亡生。向鸣珂巷里幽囚杀小卿，丽春园里迭配了双生，莺花寨埋伏的硬。但开旗决赢，谁敢共俺娘争。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2986, "title": "〔中吕〕红绣鞋", "author": "无名氏", "body": "窗外雨声声不住，枕边泪点点长吁，雨声泪点急相逐。雨声儿添凄惨，泪点儿助长吁，枕边泪倒多如窗外雨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2987, "title": "〔中吕〕红绣鞋", "author": "无名氏", "body": "一两句别人闲话，三四日不把门踏，五六日不来呵在谁家？七八遍买龟儿卦，久已后见他么？十分的憔悴煞。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2988, "title": "〔中吕〕喜春来", "author": "无名氏", "body": "海棠过雨红初淡，杨柳无风睡正酣。杏烧红桃剪锦草揉蓝。三月三，和气盛东南。\n垂门艾挂狰狰虎，竞水舟飞两两凫。浴兰汤斟绿醑泛香蒲。五月五，谁吊楚三闾。\n天孙一夜停机暇，人世千家乞巧忙。想双星心事密话头长。七月七，回首笑三郎。\n香橙肥蟹家家酒，红叶黄花处处秋。极追寻高眺望绝风流。九月九，莫负少年游。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2989, "title": "〔中吕〕喜春来", "author": "无名氏", "body": "窄裁衫褃安排瘦，淡扫蛾眉准备愁。思君一度一登楼。凝望久，雁过楚天秋。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2990, "title": "〔中吕〕四换头", "author": "无名氏", "body": "两叶眉头，怎锁相思万种愁。从他别后，无心挑绣。这般证候，天知道和天瘦。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2991, "title": "〔中吕〕四换头", "author": "无名氏", "body": "东墙花月，好景良宵恁记者。低低的说，来时节，明日早些。不志诚随灯灭。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2992, "title": "〔中吕〕十二月过尧民歌", "author": "无名氏", "body": "看看的相思病成，怕见的是八扇帏屏：一扇儿双渐小卿，一扇儿君瑞莺莺，一扇儿越娘背灯，一扇儿煮海张生。一扇儿桃源仙子遇刘晨，一扇儿崔怀宝逢着薛琼琼，一扇儿谢天香改嫁柳耆卿，一扇儿刘盼盼昧杀八官人。哎！天公，天公！教他对对成，偏俺合孤另！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2993, "title": "〔中吕〕快活三过朝天子四换头", "author": "无名氏", "body": "人去后敛翠颦，春归也掩朱门。日长庭静怕黄昏，又是愁时分。新痕，旧痕，泪滴尽愁难尽，今宵鸳帐睡怎稳。口儿念心儿印，独上妆楼，无人存问。见花梢月半轮，望频，断魂，正人远天涯近。长空成阵，雁字行行点暮云。早是多离多恨，多愁多闷。叮咛的嘱君，若见俺那人，早寄取个平安信。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2994, "title": "〔南吕〕骂玉郎过感皇恩采茶歌", "author": "无名氏", "body": "牛羊犹恐他惊散，我子索手不住紧遮拦，恰才见枪刀军马无边岸。諕的我无人处走，走到浅草里听，听罢也向高阜处偷睛看。吸力力振动地户天关，諕的我扑扑的胆战心寒。那枪忽地早刺中彪躯，那刀亨[3]地掘倒战马，那汉扑地抢下征鞍。俺牛羊散失，您可甚人马平安。把一座介丘县，生纽做枉死城，却翻做鬼门关。败残军受魔障，德胜将马顽，子见他歪剌剌赶过饮牛湾。荡的那卒律律红尘遮望眼，振的这滴溜溜红叶落空山。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2995, "title": "〔南吕〕骂玉郎过感皇恩采茶歌", "author": "无名氏", "body": "四时唯有春无价，尊日月富年华，垂杨影里人如画。锦一攒[5]，绣一堆，在秋千下。语笑欣恰，炒闹喧哗。软红乡，簇定个，小宫娃。彩绳款拈，画板轻蹅，微着力，身慢举，拽裙纱。众矜夸，是交加。彩云飞上日边霞，体态轻盈那闲雅，精神羞落树头花。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2996, "title": "〔双调〕清江引", "author": "无名氏", "body": "皂罗辫儿紧扎捎，头戴方檐帽。穿领阔袖衫，坐个四人轿。又是张吴王米虫儿来到了。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2997, "title": "〔双调〕水仙子", "author": "无名氏", "body": "丽春园苏氏弃了双生，海神庙王魁负了桂英。薄幸的自古逢着薄幸，志诚的逢着志诚，把志诚簿幸来评。志诚的合天意，薄幸的逢着鬼兵，志诚的到底有个前程。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2998, "title": "〔双调〕水仙子", "author": "无名氏", "body": "退毛鸾凤不如鸡，虎离岩前被兔欺，龙居浅水虾蟆戏，一时间遭困厄。有一日起一阵风雷，虎一扑十硕力[6]，凤凰展翅飞，那其间别辨高低。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 2999, "title": "〔双调〕水仙子", "author": "无名氏", "body": "打着面皂雕旗招飐忽地转过山坡，见一火番官唱凯歌，呀来呀来呀来呀来齐声和。虎皮包马上，当先里亚子哥哥。番鼓儿劈扑桶擂，火不思必留不剌扑，簇捧着个带酒沙陀。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3000, "title": "〔双调〕水仙子", "author": "无名氏", "body": "青山隐隐水茫茫，时节登高却异乡。孤城孤客孤舟上，铁石人也断肠，泪涟涟断送了秋光。黄花梦，一夜香，过了重阳。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3001, "title": "〔双调〕水仙子", "author": "无名氏", "body": "夕阳西下水东流，一事无成两鬓秋。伤心人比黄花瘦，怯重阳九月九，强登临情思悠悠。望故国三千里，倚秋风十二楼，没来由惹起闲愁。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3002, "title": "〔双调〕水仙子", "author": "无名氏", "body": "常记的离筵饮泣饯行时，折尽青青杨柳枝。欲拈斑管书心事，无那可乾坤天样般纸，意悬悬诉不尽相思。谩写下鸳鸯字，空吟就花月词，凭何人付与娇姿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3003, "title": "〔双调〕水仙子", "author": "无名氏", "body": "转寻思转恨负心贼，虚意虚名歹见识。只被他沙糖口啜赚了鸳鸯会，到人前讲是非，咒的你不满三十。再休想我过从的意，我今日懊悔迟，先输了花朵般身己。\n娘心里烦恼恁儿知，伏不定床前忙跪膝。是昨宵饮得十分醉，一时错悔是迟，由奶奶法外凌迟：打时节留些游气，骂时节存些面皮；可怜见俺是儿女夫妻。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3004, "title": "〔双调〕水仙子", "author": "无名氏", "body": "风流局面实堪夸，有色教人心爱煞。间深里谁肯轻抛下，等闲时须下马，试将门儿开咱。分付孩儿话，迟疾早到家，休想我半步那差。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3005, "title": "〔双调〕水仙子", "author": "无名氏", "body": "丝纶长线寄天涯，纵放由咱手内把。纸糊披就里没牵挂，被狂风一任刮，线断在海角天涯。收又收不下，见又不见他，知他流落在谁家？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3006, "title": "〔双调〕水仙子过折桂令", "author": "无名氏", "body": "一春长费买花钱，每日花边一醉眠。喜春来百花都开遍，任簪花压帽偏，花间士女秋千。红相映桃花面，人更比花少年，来寻陌上花钿。来寻陌上花钿，正是那玉楼人醉杏花天。常言道惜花早起，爱月夜眠。花底相逢少年，赴佳期梨花深院，约定在花架傍边。柳影花阴，兀的是月下星前。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3007, "title": "〔越调〕小桃红", "author": "无名氏", "body": "断肠人寄断肠词，词写心间事。事到头来不由自，自寻思，思量往日真诚志。志诚是有，有情谁似，似俺那人儿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3008, "title": "〔越调〕天净沙", "author": "无名氏", "body": "平沙细草斑斑，曲溪流水潺潺，塞上清秋早寒。一声新雁，黄云红叶青山。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3009, "title": "〔越调〕天净沙", "author": "无名氏", "body": "西风渭水长安，淡烟疏雨骊山，不见昭阳玉环。夕阳楼上，无言独倚阑干。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3010, "title": "〔越调〕寨儿令", "author": "无名氏", "body": "有钱时唤小哥，无钱也失人情。好家私伴着些歹后生，卖弄他聪明，一哄的胡行：踢气球养鹌鹑；解库中不想营生；包服内响钞精钞，但行处十数个花街里做郎君。则由他胡子传柳隆卿[7]。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3011, "title": "〔越调〕柳营曲", "author": "无名氏", "body": "白海青，皂笼鹰，鸦鹘兔鹘相间行。细犬金铃，白马红缨，前后御林兵。喊嘶嘶飞战马蹄轻，雄纠纠御驾亲征。厮琅琅环辔响，吉丁铛镫敲鸣，呀剌剌齐和凯歌行。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3012, "title": "〔越调〕柳营曲", "author": "无名氏", "body": "一叶舟，五湖游，闹垓垓不如归去休。红蓼滩头，白鹭沙鸥，正值着明月洞庭秋。进西施一捻[8]风流，起吴越两处冤仇。趁西风闲袖手，重整理钓鱼钩，看一江春水向东流！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3013, "title": "〔商调〕梧叶儿", "author": "无名氏", "body": "东村里鸡生凤，南庄上马变牛，六月里裹皮裘。瓦垄上宜栽树，阳沟里好驾舟。瓮来的大肉馒头，俺家的茄子大如斗。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3014, "title": "〔商调〕梧叶儿", "author": "无名氏", "body": "一粒米针穿着吃，一文钱剪截充，但开口昧神灵。看儿女如衔泥燕，爱钱财似竞血蝇。无明夜攒金银，都做充饥画饼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3015, "title": "失宫调牌名", "author": "无名氏", "body": "城中黑潦，村中黄潦，人都道天瓢翻了。出门溅我一身泥，这污秽如何可扫？东家壁倒，西家壁倒，窥见室家之好。问天公还有几时晴？天也道阴晴难保。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3016, "title": "〔仙吕〕村里迓鼓", "author": "无名氏", "body": "正值着丽人天气，可正是赏花赏花的这时候。你看那花红和这柳绿，绕着这舍南舍北、庄前庄后。则见那柳飞绵，花似锦，江山清秀。他每都携着美酝，穿红杏，摇翠柳。我直吃的笑吟吟醺醺带酒。\n〔元和令〕锦模糊江景幽，翠崚嶒远山秀。正值着稻分畦、蚕入簇、麦初熟。太平人闲袖手，趁着这古堤沙岸绿荫稠，缆船儿执着钓钩，缆船儿执着钓钩。\n〔上马娇〕我将这锦鲤兜，网索来收。村务内酒初熟。恰归来半醉黄昏后，暮雨收，牧童儿归去倒骑牛。\n〔游四门〕正是枫林梧叶报新秋，呀呀的寒雁过南楼。正遇着鸡肥蟹壮秋收候。霜降水痕收。朋友每留，乘兴饮两三瓯。\n〔胜葫芦〕正值着浅碧的这粼粼露远洲，赏红叶一枝秋，我则见三径黄花景物幽。正值着丰年稔岁，太平箫鼓，酒醒时节再扶头。\n〔后庭花〕我则待寻梅访故友，踏雪沽酽酒。宝篆焚金鼎，浊醪饮巨瓯，只吃的醉了时休。酒杯中不够，村务内将琴剑留，仓廒中将米麦收。浑酦醅瓮底篘。再邀住林下叟。\n〔柳叶儿〕我直吃到二更的时候，正喧哗交错觥筹，一任教月移梅影横窗瘦。心相爱，意相投，醉时节纳被蒙头。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3017, "title": "〔南吕〕一枝花", "author": "无名氏", "body": "不沽朝野名，自守烟波分。斜风新箬笠，细雨旧丝纶。志访玄真，家与秦淮近，清时容钓隐。相看着绿水悠悠，回避了红尘滚滚。\n〔梁州〕结交些鱼虾伴侣，搭识上鸥鹭亲邻，忘机怕与儿曹混。寻了些六朝往事，吊了些千古英魂，悲了些陈宫禾黍，叹了些梁殿荆榛。本是个虚飘飘天地闲人，乐陶陶江汉逸民。有时摇棹近白鹭洲笑采青，有时推蓬向朱雀桥闲看晚云，有时湾船在乌衣巷独步斜曛，有时满身衣襟爽透荷香润，旋折来柳条嫩，穿得鲜鲜出网鳞，归去黄昏。\n〔骂玉郎〕一篝灯火篘[9]佳酝，身趔趄，醉醺醺，高歌细和沧浪韵[10]，全不受利名拘，那里将兴亡记，把甚么荣枯问。\n〔感皇恩〕守着这萧索江滨，冷淡柴门。凉露湿蓑衣，清风生酒斝[11]，明月照盘飧[12]。樵夫野叟，相近相亲。昨日离石头城[13]，今朝在桃叶渡[14]，明日又杏花村。\n〔采茶歌〕山妻也最甘贫，稚子也颇通文，无忧无虑度朝昏。但得年年生意好，武陵何用访秦人。\n〔尾〕茫茫烟水无穷尽，泛泛萍踪少定根。为甚生平怕求进？想王侯大勋，博渔樵一哂，争似我一叶江湖钓船稳！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3018, "title": "〔双调〕殿前喜过播海令大喜人心", "author": "无名氏", "body": "谪仙醉眼何曾开，春眠花市侧。伯伦笑口寻常开，荷锸[15]埋，妨何碍？糟丘高垒葬残骸。先生也快哉！乌帽歪，醉眼开，心快哉！想贤愚今何在？云遮了庾亮楼，尘生满故国台。幸有金樽解愁怀，高歌归去来。诗书诗书润几斋，任落魄任落魄无妨碍。脱利名浮云外，俺窝中好避乖。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3019, "title": "〔双调〕珍珠马南", "author": "无名氏", "body": "箫声唤起瑶台月，独倚阑干情惨切，此恨与谁说？又值那黄昏时节。花飞也，一点点似离人泪血。\n〔步步娇南〕暗想当年，罗帕上把新诗写，偷绾同心结。心猿乖，意马劣。都将软玉温香，嫩枝柔叶，琴瑟正和协。不觉花影转过梧桐月。\n〔雁儿落北〕不觉的梧桐月转过西银台上，昏惨惨灯将灭。怎禁他纱窗外铁马儿敲，这些时一团娇香肌瘦怯。\n〔沉醉东风南〕一团娇香肌瘦怯。半含羞翠钿轻贴，微笑对人悄说：休负了今宵月，等闲间将海棠偷折。山盟共设，不许暂时少撇。若有箇负心的教他随灯儿便灭。\n〔得胜令北〕呀！若有一箇负心的教他随灯灭。惨可可山盟海誓对谁说，海神庙现放着勾魂帖。那神灵仔细写，你休要心斜，非是俺难割舍，你休要痴呆，殷勤将春心漏泄。\n〔忒忒令南〕他殷勤将春心漏泄，我风流寸肠中热。因此上楚云深锁黄舍阙，休把佳期暂撇。燕山绝，湘江竭，断鱼封雁帖。\n〔沽美酒北〕湘江断鱼雁帖，他一去了信音绝。想着他负德辜恩将谎话说。眼见的花残月缺，自别来甚时节甚时节。\n〔好姐姐南〕自别，逢时遇节，冷淡了风花雪月。奈愁肠万结，怎禁窗外铁无休歇，一似珮环摇明月，又被西风将锦帐揭。\n〔川拨棹北〕又被西风将锦帐揭。倚帏屏情惨切，这些时信断音绝。眼中流血，心内刀切，泪痕千叠，因此上渭城人肌肤瘦怯。\n〔桃红菊南〕渭城人肌肤瘦怯，楚天秋应难并叠。停勒了画眉郎京尹，补填了河阳令满缺。\n〔七弟兄北〕补填了河阳令满缺。一片似火也，心间事与谁说？好教我行眠立盹无明夜，今日箇吹箫无伴彩云赊。闻筝的月下疏狂劣，画眉郎手脚拙，窃玉的性情别，把好梦成吴越。\n〔川拨棹南〕成吴越。怎禁他巧言搬斗喋，平白地送暖偷寒，平白地送暖偷寒，猛可的搬唇递舌，水晶丸不住撇，点钢锹一味撅。\n〔梅花酒北〕他将那点钢锹一迷里撅，劈贤刀手中撇，打捞起块丹枫叶。鸳鸯被半床歇，胡蝶梦冷些些，破香囊后成血，楚馆着火焚者。\n〔锦衣香南〕他将那楚馆焚，秦楼来拽，洛浦填，泾河截，梅家庄水罐汤瓶打为磁屑，贾充宅守定粉墙缺，武陵溪涧花儿钉了桩橛，楚襄王梦惊回者，汉相如赶翻车辙，深锁芙蓉阙，紫箫吹裂，碧桃花下凤凰将翎毛生扯。\n〔收江南北〕呀！你敢在碧桃花下将凤毛扯。人生最苦是离别，山长水远路途赊，何年是彻，响菱花镜碎玉簪折。\n〔浆水令南〕响菱花镜碎，支楞楞瑶琴弦断绝，革支支同心绾带扯，击玎珰宝簪儿坠折，采莲人偏把并头折，比目鱼就池中冷水烧热，连理树生砍折，打捞起御水流红叶，蓝桥[16]下翻滚滚波浪卷雪，祆神庙[17]祆神庙焰腾腾火走金蛇。\n〔尾声〕饶君巧把机谋设，止不住负心薄劣。梦儿里若见他俺与他分说。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3020, "title": "包待制陈州粜米", "author": "无名氏", "body": "〔混江龙〕做的个上梁不正，只待要损人利己惹人憎。他若是将咱刁蹬[18]，休道我不敢掀腾[19]。柔软莫过溪涧水，到了不平地上也高声。他也故违了皇宣命，都是些吃仓廒的鼠耗，咂脓血的苍蝇。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3021, "title": "包待制陈州粜米", "author": "无名氏", "body": "〔哭皇天〕那刘衙内把孩儿荐，范学士怎也就将敕命宣？只今个贼仓官享富贵，全不管穷百姓受熬煎，一刬的在青楼缠恋。那厮每不依钦定，私自加添，盗粜了仓米，干没了官钱，都送与泼烟花、泼烟花王粉莲。早被俺亲身儿撞见，可便肯将他来轻轻的放免？\n〔乌夜啼〕为头儿先吃俺开荒剑，则他那性命不在皇天。刘衙内也，可怎生着我行方便？这公事体察完全，不是流传。那怕你天章学士有夤缘，就待乞天恩走上金銮殿；只我个包龙图，元铁面；也少不得着您名登紫禁，身丧黄泉！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3022, "title": "玉清庵错送鸳鸯被", "author": "无名氏", "body": "〔油葫芦〕甚风儿吹你个姑姑来到此，慌忙将礼数施。自从我绣鸳鸯几曾离了绣床时。我着这金线儿妆出鸳鸯字，我着这绿绒儿分作鸳鸯翅。你看那枝缠着花，花缠着枝。直等的俺成就了百岁姻缘事，恁时节才添上两个眼睛儿。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3023, "title": "随何赚风魔蒯通", "author": "无名氏", "body": "〔耍孩儿〕今日个萧何反间施谋智，黑洞洞不知一个的实。若将军一脚到京畿，但踏着消息儿[20]你可也便身亏。他安排着香饵把鳌鱼钓，准备着窝弓将虎豹射。咱人泰极多生否[21]，再休想吉祥如意，多管是你恶限临逼。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3024, "title": "随何赚风魔蒯通", "author": "无名氏", "body": "〔沽美酒〕兀的不是狡兔死，走狗僵；高鸟尽，劲弓藏。也枉了你荐举他来这一场。把当日个筑台拜将，到今日又待要筑坟堂。\n〔太平令〕便做有春秋祭飨，也济不得他九泉下魂魄凄凉。倒不如早将我油烹火葬，好和他死生厮傍。我可也不慌不忙，还含笑的就亡。呀！这便算做你加官赐赏。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3025, "title": "杨氏女杀狗劝夫", "author": "无名氏", "body": "〔太平令〕吃的是亲嫂嫂的酒食，更过如吕太后的筵席。嫂嫂，俺哥哥觉来你支持，“我也不是个善的”。諕的我一个脸描不的画不的，一双箸拿不的放不的，一口面吐不的咽不的。我便有万口舌头教我说个甚的。\n〔叨叨令〕则被这吸里忽剌的朔风儿那里好笃簌簌避，又被这失留屑历的雪片儿偏向我密蒙蒙坠。将这领希留合剌的布衫儿扯得来乱纷纷碎，将这双乞量曲律的膝儿罚他去直僵僵跪。兀的不冻杀人也么哥，兀的不冻杀人也么哥，越惹他必丢匹搭的响骂儿这一场扑腾腾气。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3026, "title": "庞居士误放来生债", "author": "无名氏", "body": "〔寄生草〕富极是招灾本，财多是惹祸因。如今人恨不的那银窟笼里守定银堆儿盹，恨不的那钱眼孔里铸造下行钱印。（做合掌科云）南无阿弥陀佛。（唱）争如我向禅榻上便参破禅机闷。近新来打拆了郭况铸钱罏，这些时厮挦碎了鲁褒的这《钱神论》。\n〔六幺序〕这钱呵无过是乾坤象，熔铸的字体匀。这钱呵何足云云。这钱呵，使作的仁者无仁，恩者无恩。费千百才买的居邻。这钱呵，动佳人有意郎君俊，糊突尽九烈三真[22]。这钱呵，将嫡亲的昆仲绝了情分。这钱呵，也买不的山丘零落，养不的画屋生春。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3027, "title": "冻苏秦衣锦还乡", "author": "无名氏", "body": "〔鸳鸯煞〕想当初风尘落落谁怜悯，到今日衣冠楚楚争亲近。畅道威震诸侯，腰悬六印，也索把世态炎凉，心中暗忖：假使一朝马死黄金尽，可不的依旧苏秦，做陌路看承被人哂。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3028, "title": "神奴儿大闹开封府", "author": "无名氏", "body": "〔隔尾〕我将你怀儿中撮哺似心肝儿般敬，眼前觑当似在手掌儿上擎。（带云）神奴儿哥哥，（唱）我叫道有二千声神奴儿将你来叫不应。为你呵走折我这腿脡，俺嫂嫂哭破那双眼睛，我这里静坐到天明将一个业冤来等。\n〔牧羊关〕我则怕走的你身子困，又嫌这铺卧冷，我与你种着火停着残灯。怕你害渴时有柿子和梨儿，害饥时有软肉也那薄饼。我将你寻到有三千遍，叫道有两千声，怎这般死没堆在灯前立?（带云）小爹爹，家里来波！（唱）你可怎生悄声儿在门外听？", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3029, "title": "庞涓夜走马陵道", "author": "无名氏", "body": "〔滚绣球〕你休那里信口诌，则管里无了收。这言语你也合三思然后，俺兄弟怎肯道东涧东流！他亏我似猪狗，我亏他似马牛，俺两个曾对天说咒，俺兄弟他怎肯火上浇油！俺两个胜如管鲍分金义，休猜做孙庞刖足仇，枉惹得万代名留！\n〔二煞〕我饮过这香喷喷三盏儿安魂酒，则被你闪杀我也血渌渌一双脚指头。刀落处鼻痛心酸，皮开肉绽，筋骨相离，鲜血浇流。哎，可怎生神嚎鬼哭，雾惨云昏，白日为幽。耳边厢只听得半空中风吼，莫不是和天地替人愁！\n〔煞尾〕兄弟，则这功名成就合成就，我得好休时便好休。养可疮海上游，洗了耳觅许由，学太公把钓钩，逐范蠡一叶舟。想荣华风内烛，富贵如水上沤，将利名一笔勾，再不向杀人场揽祸尤，白白的将性命丢。攒住眉头懒转眸，咬定牙儿且忍羞，打熬着足上浸浸血水流——哎，你个行刃的哥哥你畅好是下的手！", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3030, "title": "朱太守风雪渔樵记", "author": "无名氏", "body": "〔三煞〕你似那碔砆石比玉何惊骇，鱼目如珠不拣择。我是个插翅的金雕，你是个没眼的燕雀，本合两处分飞，焉能勾百岁和谐。你则待折灵芝喂牛草，打麒麟当羊卖，摔瑶琴做烧柴，你把那沉香木来毁坏，偏把那臭榆栽。\n〔二煞〕那知道岁寒然后知松柏，你看我似粪土之墙朽木材。断然是捱不彻饥寒，禁不过气恼，怎知我守定心肠，留下形骸。但有日官居八座[23]，位列三台[24]，日转千阶[25]，头直上打一轮皂盖，那其间谁敢道我负薪来。\n〔随煞尾〕我直到九龙殿里题长策，五凤楼前骋壮怀。我若是不得官和姓改，将我这领白褴衫脱在玉阶，金榜亲将姓氏开。敕赐宫花满头戴，宴罢琼林微醉色，狼虎也似弓兵两下排，水罐银盆一字儿摆。恁时节方知这个朱秀才，不要你插插花花认我来，哭哭啼啼泪满腮，你这般怨怨哀哀磕着头拜。那其间我在马儿上，醉眼矇眬将你来并不睬。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3031, "title": "孟德耀举案齐眉", "author": "无名氏", "body": "〔后庭花〕他是个守青毡一腐儒，捱黄齑忍饿夫；那里取带秋色羊脂玉，赛明月照夜珠。父亲阿，你坏风俗，枉了你清廉名目。你断别人家不是处，下钱财要等足，少分文不放出，敢如何违法度。\n〔赚煞〕他富则富，富不中我志诚心；这秀才穷则穷，穷不辱我姻缘簿。我若是合快乐不遭受苦，若是我合受苦强寻一个荣贵处，也只怕无福消除。教人道这乔男女，则是些牛马襟裾。父亲你原来不敬书生敬财主。我又不曾临邛县驾车，他又不曾升仙桥题柱，早学那卓文君拟定嫁相如。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3032, "title": "王月英元夜留鞋记", "author": "无名氏", "body": "〔混江龙〕你道我粉容憔悴，恰便似枝头杨柳恨春迟。每日家羞看燕舞，怕听莺啼。又不是侍女无情与我相懆，又不是老亲多事把我紧收拾。为甚么妆台不整，锦被难偎，雕阑闷倚，绣幙低垂？长则是苦恹恹不遂我相思意，到如今钏松了玉腕，衣褪了香肌。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3033, "title": "王月英元夜留鞋记", "author": "无名氏", "body": "〔滚绣球〕且饶过王月英，待唤声郭秀才，又则怕有人在画檐之外。我靠香肩将玉体轻挨。觑着时眼不开，问着时头不抬，扶起来试看他容颜面色，哎，却原来醉醺醺东倒西歪。我这里一双柳叶眉儿皱，他那里两朵桃花上脸来。说甚乖乖。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3034, "title": "玎玎珰珰盆儿鬼", "author": "无名氏", "body": "〔庆元贞〕俺出门红日乍平西，归时犹未夕阳低，怎教俺担惊受怕着昏迷？这都是、咱老背悔，门儿外不曾撒的把儿灰。\n〔黄蔷薇〕俺这里高声叫有贼。慌走到街里，又无一个巡军捷讥[26]，着谁来共咱应对。\n〔庆元贞〕扭回身疾便入房内，被门桯绊我一个合扑地。一只手揪住这厮泼毛衣，使拳捶、和脚踢。呸，原来是一领旧羊皮。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3035, "title": "玎玎珰珰盆儿鬼", "author": "无名氏", "body": "〔正宫·端正好〕抱着他冤楚楚瓦盆儿，直到这另巍巍公堂下。只待要如律令把贼汉擒拿，谁似这龙图包老声名大？俺索向屏墙侧偷窥罢。\n〔滚绣球〕俺则见狠公吏把荆杖挝，恶曹司将文卷押。两边厢摆列着势剑铜，中间里端坐个象简乌纱。盆儿也道假来你又不是假，道耍来你又不是耍，直被你唬得人心慌胆乍，没来由俺可也做这等冤家。盆儿也若是你今朝不把情由诉，平日空将正直夸，早准备带锁披枷。\n〔叨叨令〕俺为甚的无柴少米不纳民间价？为甚的穿衙入府不受官司骂？也则为公心直道、从没分毫诈。也不是强唇劣嘴要做乡村霸。则被你都坏了我也么哥、则被你都坏了我也么哥，倒不如吞声忍气依旧回家罢。\n〔醉高歌〕你背地里玎玎珰珰说话，着紧处你便妆聋作哑。俺只待提起来望这街直下，摔碎你做几片零星瓦查。\n〔红绣鞋〕恰才那粗棍子浑如臂大，他将俺打一下直似钩搭，你是个鬼魂儿倒捉弄俺老人家。不是俺怕将他这门桯蓦，也不是俺懒将他这地皮蹅。盆儿也俺可便待今番吃了三顿打。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3036, "title": "风雨像生货郎旦", "author": "无名氏", "body": "〔梁州第七〕正遇着美遨游融和的天气，更兼着没烦恼丰稔的年时。有谁人不想快平生志，都只待高张绣幕，都只待烂醉金卮。我本是穷乡寡妇，没甚的艳色娇姿。又不会卖风流弄粉调脂，又不会按宫商品竹弹丝。无过是赶几处沸腾腾热闹场儿，摇几下桑琅琅蛇皮鼓儿，唱几句韵悠悠信口腔儿。一诗一词，都是些人间新近希奇事，扭捏来无诠次[29]。倒也会动的人心谐的耳，都一般喜笑孜孜。\n〔转调货郎儿〕也不唱韩元帅[30]偷营劫寨，也不唱汉司马[31]陈言献策，也不唱巫娥云雨楚阳台[32]，也不唱梁山伯，也不唱祝英台，只唱那娶小妇的长安李秀才。\n〔三转〕那李秀才不离了花街柳陌，占场儿贪杯好色。看上那柳眉星眼杏花腮，对面儿相挑泛，背地里暗差排。抛着他浑家不睬，只教那媒人往来。闲家擘划，诸般绰开，花红布摆。早将一个泼贱的烟花娶过来。\n〔四转〕那婆娘舌剌剌挑茶斡剌，百枝枝花儿叶子，望空里揣与他个罪名儿。寻这等闲公事，他正是节外生枝，调三斡四。只教你大浑家吐不的咽不的这一个心头刺，减了神思，瘦了容姿。病恹恹睡损了裙儿[33]，难扶策，怎动止。忽的呵冷了四肢，将一个贤惠[34]的浑家生气死。\n〔五转〕火逼的好人家人离物散，更那堪更深夜阑。是谁将火焰山移向到长安。烧地户，燎天关。单则把凌烟阁留他世上看。恰便似九转飞芒[35]老君炼丹，恰便似介子推在绵山，恰便似子房[36]烧了连云栈，恰便似赤壁下曹兵涂炭，恰便似布牛阵举火田单，恰便似火龙鏖战锦斑斓。将那房檐扯，脊梁扳。急救呵，可又早连累了官房五六间。\n〔六转〕我只见黑黯黯天涯云布，更那堪湿淋淋倾盆骤雨。早是那窄窄狭狭、沟沟堑堑路崎岖，知奔向何方所？犹喜的消消洒洒、断断续续、出出律律、忽忽噜噜阴云开处，我只见霍霍闪闪电光星炷。怎禁那萧萧瑟瑟风，点点滴滴雨，送的来高高下下、凹凹凸凸、一搭模糊？早做了扑扑簌簌、湿湿渌渌、疏林人物。倒与他妆就了一幅昏昏惨惨潇湘水墨图。\n〔七转〕河岸上和谁讲话？向前去亲身问他。只说道奸夫是船家，猛将咱家长喉咙掐，磕搭地揪住头发。我是个婆娘，怎生救拔！也是他合亡化，扑鼕的命掩黄泉下，将李春郎的父亲，只向那翻滚滚波心水淹杀。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3037, "title": "冯玉兰夜月泣江舟", "author": "无名氏", "body": "〔商调·集贤宾〕正沧江夜寒明月皎，觑地远叩天遥。这船呵在风中簸荡任东西，水上浮漂；又无人把舵推篷，那里也举棹撑篙。我则听的古都都泼天也似怒涛，斗合着忽剌剌风声儿厮闹。这水也流不尽俺千端愁思积，这风也抵不过俺一片哭声高。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3038, "title": "小尉迟将斗将认父归朝", "author": "无名氏", "body": "〔柳青娘〕到来日扑冬冬的征鼙慢凯，韵悠悠的角声哀，响铛铛的铜锣款筛。忽剌剌的绣旗开，黑漫漫杀气遮了日色，恶哏哏[37]的人离了寨栅，扑腾腾马践尘埃。碜磕磕的镫相磨，乱纷纷的枪相截，密匝匝的甲相挨。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3039, "title": "桃花女破法嫁周公", "author": "无名氏", "body": "〔滚绣球〕我头直上发似揪，耳轮边热似火，我行行里袖传一课，急慌忙把脚步儿频挪：我这里穿大道桑柘林，穿小径荆棘科。则见乱交加不知是那个，则听的沸滚滚热闹镬铎。俺父亲揎拳袖因何事？他这般唱叫扬疾不俫便可也为什么？有甚的好话评跋。\n〔滚绣球〕则你这媒人一个个，啜人口似蜜钵，都只是随风倒舵，索媒钱嫌少争多。女亲家会放水，男亲家点着火。你将那好言语往来收撮，则办得两下里挑唆。你将那半句话搬调做十分事，一尺水翻腾做百丈波，则你那口似悬河。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3040, "title": "苏子瞻醉写赤壁赋", "author": "无名氏", "body": "〔圣药王〕一枝的曲未终，韵更清，便似子规枝上月三更。低一声，高一声，似东风花外锦鸠鸣，恰便似斜月睡闻莺。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3041, "title": "锦云堂暗定连环计", "author": "无名氏", "body": "〔滚绣球〕炉焚着宝篆香，酒斟着玉液浆，奏笙歌乐声嘹亮，今日个画堂中别是风光。虽然是锦绣乡，暗藏着战斗场。则争无虎贲郎将，玳筵前拥出红妆。我只待窝弓药箭擒狼虎，布网张罗打凤凰，不比寻常。\n〔鲍老儿〕你这里鼓舌摇唇说短长，则俺那新媳妇在车儿上。盼不见画戟雕鞍旧日郎，咒骂杀王丞相。枉了你扬威耀武，尽忠竭节，定国安邦。偏容他鸱鸮弄舌，乌鸦展翅，强配鸾凰。\n〔煞尾〕虽然是女娘家不气长，从来个做男儿当自强。若要你勃腾腾怒发三千丈，则除今夜里亲见貂蝉细细的访。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3042, "title": "逞风流王焕百花亭", "author": "无名氏", "body": "〔快活三〕这书词是亲手修，重新把密情兜。也不枉我虚名赢的上青楼，早展放双眉皱。\n〔鲍老催〕我这里展脚舒腰忙顿首，引的我口角顽涎溜。我只道姻缘簿消除一笔勾，又谁知今日还能彀？这书词则是纸摄人魂的下帖，摘人心的公案，追人命的勾头。（王小二云）官人，你愁除病减，都在这封书上，早则喜也。（正末唱）再休题愁除病减，花成蜜就，叶落归秋。\n〔耍孩儿〕我便似被困围的败将专求救。哎，高君也，咱两个棋逢对手。也不索推轮捧毂，筑坛台专仗你那妙策神谋。则你是添兵减灶齐孙膑，唤风呼雨蜀武侯，将巧计亲传授。这一番若得贺氏逢王焕，便似织女见牵牛。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3043, "title": "金水桥陈琳抱妆盒", "author": "无名氏", "body": "〔牧羊关〕我抱定这妆盒子，便是揣着个愁布袋。我未到宫门，早忧的我这头白。盒子里藏的是储君，我肚皮里怀的是鬼胎。虽不见公庭上遭横祸，赤紧的盒子里隐飞灾。承御也，你办着个喜溶溶笑脸儿回还去，却教我将着个碜磕磕恶头儿掇过来。\n〔贺新郎〕则见他恶哏哏独自撞将来。太子也，你在这七宝盒中，我陈琳早魂飞九霄云外。我嘱咐你个小储君盒子里权宁耐，你若是分毫儿挣，登时间粉碎了我尸骸。则被你威逼的我身先战，死摧的我脚难抬，恰便似狗探汤不敢望前迈。才动脚如临追命府，行一步似上摄魂台。\n〔菩萨梁州〕石榴长在金阶。（刘皇后云）莫不是核桃?（正末唱）合逃出您宫外。（刘皇后云）莫不是梨儿?（正末唱）今宵离了后宰。（刘皇后云）莫不是李子?（正末唱）这玉皇李子苦尽甘来，也是他天然异种出群材。开时节不许游蜂采，摘时节则愿的君王戴。（刘皇后云）李子有甚好处，万岁爷倒喜着他？待我把这树都砍坏了者。（正末唱）娘娘也偏生你意儿歹，怎忍见片片残红点碧苔？陪伴他这古木崩崖。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}, {"id": 3044, "title": "汉钟离度脱蓝采和", "author": "无名氏", "body": "〔仙吕·点绛唇〕俺将这古本相传，路歧体面，习行院，打诨通禅，穷薄艺知深浅。\n〔混江龙〕试看我行针步线，俺在这梁园城一交却又早二十年，常则是与人方便，会客周全。做一段有憎爱劝贤孝新院本，觅几文济饥寒得温暖养家钱，俺这里不比别州县，学这几分薄艺，胜似千顷良田。\n〔油胡芦〕甚杂剧请恩官望着心爱的选，俺路歧每怎敢自专，这的是才人书会刬新编。我做一段于佑之金水题红怨，张忠泽玉女琵琶怨，做一段老令公刀对刀，小尉迟鞭对鞭，或是三王定政临虎殿，都不如诗酒丽春园。\n〔天下乐〕或是做雪拥蓝关马不前。小人，其实本事浅，感谢看官相可怜。一壁将牌额题，一壁将靠背悬，我则待天下将我的名姓显。", "category": "元曲", "analysis": "此版本内置古诗词正文；未收录现代出版物赏析。"}];
const WALLPAPERS=["mountain-1.png", "mountain-2.png", "mountain-3.png"];